package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.regex.Pattern;

/**
 * The live activity message, {@code "k":"activity"} (docs/plans/activities.md §5.1). Its own kind, not one of
 * {@link GroupCodec}'s: an older client's {@code GroupCodec.decode} returns null for a kind it does not know, and
 * {@code GroupService.notData} then drops it with a debug line, so the new message costs an older build nothing.
 *
 * <p>Everything read is bounded: the payload's size, every string (control characters and angle brackets removed,
 * so nothing a member sends can become Swing HTML), and every number.
 */
final class ActivityCodec
{
	static final String KIND = "activity";
	/** Longer payloads are dropped unread. */
	static final int MAX_CHARS = 2048;
	static final int MAX_NAME = 40;
	static final int MAX_MODE = 24;
	static final int MAX_PHASE = 40;
	static final int MAX_BOARD = 64;
	static final int MAX_STATS = 64;
	static final int MAX_MODS = 120;
	static final int MAX_TEAM = 64;
	static final int MAX_WAVE = 1000;
	static final long MAX_ELAPSED_MS = 86_400_000L;
	private static final Pattern ID = Pattern.compile("[a-z0-9_]{0,24}");
	private static final Pattern UNSAFE = Pattern.compile("[\\p{Cntrl}<>]");

	private ActivityCodec()
	{
	}

	/** This player's state, or a clear frame ({@code "id":""}) for {@link ActivityState#NONE}. */
	static String encode(Gson gson, ActivityState s)
	{
		JsonObject o = new JsonObject();
		o.addProperty("v", 1);
		o.addProperty("k", KIND);
		o.addProperty("at", s.at);
		o.addProperty("id", s.id);
		if (s.active())
		{
			o.addProperty("cat", s.cat);
			o.addProperty("name", s.name);
			o.addProperty("mode", s.mode);
			o.addProperty("phase", s.phase);
			o.addProperty("board", s.board);
			o.addProperty("wave", s.wave);
			o.addProperty("max", s.max);
			o.addProperty("startedAt", s.startedAt);
			o.addProperty("elapsedMs", s.elapsedMs);
			o.addProperty("stats", s.stats);
			o.addProperty("mods", s.mods);
			o.addProperty("team", s.team);
		}
		return gson.toJson(o);
	}

	/** A cheap first look, so other kinds are not parsed twice. */
	static boolean isActivity(String json)
	{
		return json != null && json.contains("\"" + KIND + "\"");
	}

	/** The state sent, {@link ActivityState#NONE} for a clear frame, or null for anything malformed. */
	static ActivityState decode(Gson gson, String json)
	{
		JsonObject o = GroupCodec.object(gson, json, MAX_CHARS);
		if (o == null || !KIND.equals(string(o, "k", 16)) || number(o, "v", 0, Integer.MAX_VALUE) < 1)
		{
			return null;
		}
		JsonElement idElement = o.get("id");
		if (idElement == null || !idElement.isJsonPrimitive() || !ID.matcher(idElement.getAsString()).matches())
		{
			return null;
		}
		long at = number(o, "at", 0, Long.MAX_VALUE);
		String id = idElement.getAsString();
		if (id.isEmpty())
		{
			return new ActivityState.Builder("", at).build();
		}
		String name = string(o, "name", MAX_NAME);
		if (name.isEmpty())
		{
			return null;
		}
		return new ActivityState.Builder(id, at).cat(string(o, "cat", 16)).name(name)
			.mode(string(o, "mode", MAX_MODE)).phase(string(o, "phase", MAX_PHASE)).board(string(o, "board", MAX_BOARD))
			.wave((int) number(o, "wave", 0, MAX_WAVE)).max((int) number(o, "max", 0, MAX_WAVE))
			.startedAt(number(o, "startedAt", 0, Long.MAX_VALUE)).elapsedMs(number(o, "elapsedMs", 0, MAX_ELAPSED_MS))
			.stats(string(o, "stats", MAX_STATS)).mods(string(o, "mods", MAX_MODS)).team(string(o, "team", MAX_TEAM))
			.build();
	}

	/** The field as safe display text, at most {@code max} characters; empty when missing or not a string. */
	static String string(JsonObject o, String key, int max)
	{
		JsonElement e = o.get(key);
		if (e == null || !e.isJsonPrimitive())
		{
			return "";
		}
		String clean = UNSAFE.matcher(e.getAsString()).replaceAll("").trim();
		return clean.length() > max ? clean.substring(0, max) : clean;
	}

	/** The field clamped to {@code [min, max]}; {@code min} when missing or not a number. */
	static long number(JsonObject o, String key, long min, long max)
	{
		JsonElement e = o.get(key);
		if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber())
		{
			return min;
		}
		double d = e.getAsDouble();
		if (Double.isNaN(d) || d <= min)
		{
			return min;
		}
		return d >= max ? max : e.getAsLong();
	}
}

package com.vinnyvangogh.groupironman;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.concurrent.TimeUnit;

/**
 * What the sidebar Log tab shows (Board 2026-11-10): every group event the
 * overlay or Discord can show, yours and members', from the same
 * {@link GroupEvent} objects. Pure: the feed is a {@link DropLog} with this
 * class's bounds, kept in {@link GroupRoster#feed()} and the group cache; this
 * class searches, filters and lays it out.
 */
final class ActivityLog
{
	/** Kept: the newest this many, and none older than {@link #MAX_AGE_MS}, whichever keeps fewer. */
	static final int MAX_ENTRIES = 2000;
	static final long MAX_AGE_MS = TimeUnit.DAYS.toMillis(30);

	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEE d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter WHEN = DateTimeFormatter.ofPattern("d MMM yyyy, HH:mm", Locale.ENGLISH);

	private ActivityLog()
	{
	}

	/** A new, empty feed with the Log's bounds. */
	static DropLog newFeed()
	{
		return new DropLog(MAX_ENTRIES, MAX_AGE_MS, System::currentTimeMillis);
	}

	/** The time range picker. */
	enum Range
	{
		ALL("All time"), TODAY("Today"), WEEK("Last 7 days");

		final String label;

		Range(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}

		/** The oldest time this range keeps. */
		long from(long now, ZoneId zone)
		{
			switch (this)
			{
				case TODAY:
					return Instant.ofEpochMilli(now).atZone(zone).toLocalDate().atStartOfDay(zone).toInstant()
						.toEpochMilli();
				case WEEK:
					return now - TimeUnit.DAYS.toMillis(7);
				default:
					return Long.MIN_VALUE;
			}
		}
	}

	/** The search box, the category chips (none ticked keeps all), the member picker (empty for all) and the range. */
	static final class Filter
	{
		static final Filter ALL = new Filter("", EnumSet.noneOf(GroupEvent.Category.class), "", Range.ALL);

		final String query;
		final Set<GroupEvent.Category> categories;
		final String member;
		final Range range;

		Filter(String query, Set<GroupEvent.Category> categories, String member, Range range)
		{
			this.query = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
			this.categories = categories.isEmpty() ? EnumSet.noneOf(GroupEvent.Category.class)
				: EnumSet.copyOf(categories);
			this.member = member == null ? "" : member.trim();
			this.range = range == null ? Range.ALL : range;
		}

		boolean keeps(GroupEvent e, ItemLookup items, long from)
		{
			return e.at >= from
				&& (categories.isEmpty() || categories.contains(e.type.category))
				&& (member.isEmpty() || member.equalsIgnoreCase(e.member))
				&& (query.isEmpty() || haystack(e, items).contains(query));
		}
	}

	/** {@code events} (newest first) that {@code filter} keeps, in the same order. */
	static List<GroupEvent> filter(List<GroupEvent> events, Filter filter, ItemLookup items, long now, ZoneId zone)
	{
		long from = filter.range.from(now, zone);
		List<GroupEvent> out = new ArrayList<>();
		for (GroupEvent e : events)
		{
			if (filter.keeps(e, items, from))
			{
				out.add(e);
			}
		}
		return out;
	}

	/** Everything the search box matches: member, item names, place, the line itself. Lower case. */
	static String haystack(GroupEvent e, ItemLookup items)
	{
		StringBuilder out = new StringBuilder();
		out.append(e.member).append('\n').append(e.text).append('\n').append(e.detail).append('\n')
			.append(e.location).append('\n').append(EventText.title(e)).append('\n')
			.append(EventText.describe(e, items));
		for (Integer id : e.items.keySet())
		{
			out.append('\n').append(items.name(id));
		}
		for (Integer id : e.taken.keySet())
		{
			out.append('\n').append(items.name(id));
		}
		return out.toString().toLowerCase(Locale.ROOT);
	}

	/** A category chip's label: "Drops", "Activities". */
	static String label(GroupEvent.Category category)
	{
		String name = category.name();
		return name.charAt(0) + name.substring(1).toLowerCase(Locale.ROOT);
	}

	/** Members seen in the feed, for the member picker. */
	static List<String> members(List<GroupEvent> events)
	{
		Set<String> out = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
		for (GroupEvent e : events)
		{
			out.add(e.member);
		}
		return new ArrayList<>(out);
	}

	/** One heading and its events. */
	static final class Section
	{
		final String title;
		final List<GroupEvent> events = new ArrayList<>();

		Section(String title)
		{
			this.title = title;
		}
	}

	/**
	 * {@code shown} (newest first) in sections: "Since you last played" on
	 * top when {@code since} is known (members' events after it), then the
	 * rest by day. An event is in one section only.
	 */
	static List<Section> sections(List<GroupEvent> shown, long since, String self, long now, ZoneId zone)
	{
		List<Section> out = new ArrayList<>();
		Section top = since > 0 ? new Section("Since you last played (" + BoostText.ago(now, since) + ")") : null;
		if (top != null)
		{
			out.add(top);
		}
		Section day = null;
		LocalDate today = date(now, zone);
		for (GroupEvent e : shown)
		{
			if (top != null && e.at > since && !e.member.equalsIgnoreCase(self))
			{
				top.events.add(e);
				continue;
			}
			String title = dayTitle(date(e.at, zone), today);
			if (day == null || !day.title.equals(title))
			{
				day = new Section(title);
				out.add(day);
			}
			day.events.add(e);
		}
		return out;
	}

	private static LocalDate date(long at, ZoneId zone)
	{
		return Instant.ofEpochMilli(at).atZone(zone).toLocalDate();
	}

	static String dayTitle(LocalDate day, LocalDate today)
	{
		if (day.equals(today))
		{
			return "Today";
		}
		return day.equals(today.minusDays(1)) ? "Yesterday" : DAY.format(day);
	}

	/** One row: an icon, the member, a short line and how long ago; the full text on hover; the text Copy puts on the clipboard. */
	static final class Row
	{
		final GroupEvent event;
		/** "Vorkath dropped 1 x Draconic visage (2.3M gp)", game amounts. */
		final String text;
		final String ago;
		/** The hover: title, the full line, the value and the time. Amounts in the game's style with every digit. */
		final String full;
		final String copy;
		/** The item to draw, -1 for none. */
		final int itemId;
		final long quantity;
		/** The skill to draw for a level or XP event, null for none. */
		final String skill;

		private Row(GroupEvent e, ItemLookup items, long now, ZoneId zone, boolean notShared)
		{
			String unshared = notShared ? " (" + StorageChange.NOT_SHARED + ")" : "";
			this.event = e;
			this.text = EventText.describe(e, items) + unshared;
			this.ago = BoostText.ago(now, e.at);
			long value = value(e, items);
			String when = WHEN.format(Instant.ofEpochMilli(e.at).atZone(zone));
			String sentence = EventText.sentence(e, Amounts.BOTH.words(items));
			String worth = value > 0 ? "Value: " + Amounts.BOTH.of(value) + " gp" : "";
			this.full = EventText.title(e) + "\n" + sentence + (worth.isEmpty() ? "" : "\n" + worth) + "\n" + when
				+ (notShared ? "\n" + StorageChange.NOT_SHARED : "");
			this.copy = "[" + when + "] " + sentence + (worth.isEmpty() ? "" : " (" + worth + ")") + unshared;
			Map.Entry<Integer, Integer> icon = iconItem(e, items);
			this.itemId = icon == null ? -1 : icon.getKey();
			this.quantity = icon == null ? 0 : icon.getValue();
			this.skill = skillOf(e);
		}
	}

	static Row row(GroupEvent e, ItemLookup items, long now, ZoneId zone)
	{
		return new Row(e, items, now, zone, false);
	}

	/** A row that says why it went nowhere when {@code storage} holds it as an own visit kept to this client. */
	static Row row(GroupEvent e, ItemLookup items, long now, ZoneId zone, StorageLog storage)
	{
		boolean notShared = e.type.category == GroupEvent.Category.STORAGE && storage.notShared(e.at, e.member);
		return new Row(e, items, now, zone, notShared);
	}

	/** The gp the event is worth: its items, or the number for a death's loss; 0 when none. */
	static long value(GroupEvent e, ItemLookup items)
	{
		if (e.type == GroupEvent.Type.DEATH_VALUE)
		{
			return e.number;
		}
		return EventText.value(e.items, items) + EventText.value(e.taken, items);
	}

	/** The event's most valuable item, or its first when no price is known; null with none. */
	static Map.Entry<Integer, Integer> iconItem(GroupEvent e, ItemLookup items)
	{
		Map<Integer, Integer> from = e.items.isEmpty() ? e.taken : e.items;
		Map.Entry<Integer, Integer> best = null;
		long bestValue = -1;
		for (Map.Entry<Integer, Integer> i : from.entrySet())
		{
			long v = items.price(i.getKey()) * i.getValue();
			if (v > bestValue)
			{
				best = i;
				bestValue = v;
			}
		}
		return best;
	}

	/** The skill a level, 99 or XP event is about; null for the rest and for a max total. */
	static String skillOf(GroupEvent e)
	{
		switch (e.type)
		{
			case LEVEL_UP:
			case XP_MILESTONE:
				return e.text;
			case MAXED:
				return "total".equalsIgnoreCase(e.text) ? null : e.text;
			default:
				return null;
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * What the Activities tab shows (docs/plans/activities.md §4.1), as plain rows so the Swing code only lays them out:
 * a card per member in an activity now ("LIVE NOW"), then recent completions and deaths from the Log ("RECENT
 * RUNS"), both behind the All / Bossing / Minigames filter.
 */
final class ActivityRows
{
	enum Filter
	{
		ALL("All"), BOSSING("Bossing"), MINIGAMES("Minigames");

		final String label;

		Filter(String label)
		{
			this.label = label;
		}

		boolean keeps(boolean bossing)
		{
			return this == ALL || (this == BOSSING) == bossing;
		}
	}

	/** How many recent runs are listed. */
	static final int MAX_RECENT = 25;
	private static final Set<GroupEvent.Type> RUNS = EnumSet.of(GroupEvent.Type.ACTIVITY_COMPLETE,
		GroupEvent.Type.ACTIVITY_DEATH);

	/** One member's live card. */
	static final class Card
	{
		final String member;
		final boolean you;
		/** "Alex" or "Alex (you)". */
		final String title;
		/** "The Inferno - wave 42/69", "solo - 38m", then glory and modifiers when there are any. */
		final List<String> lines;

		Card(String member, boolean you, List<String> lines)
		{
			this.member = member;
			this.you = you;
			this.title = you ? member + " (you)" : member;
			this.lines = Collections.unmodifiableList(lines);
		}
	}

	private ActivityRows()
	{
	}

	/** Live cards, you first, then by name. */
	static List<Card> live(Map<String, ActivityState> activities, Filter filter, String self, long now)
	{
		List<Card> out = new ArrayList<>();
		for (Map.Entry<String, ActivityState> e : activities.entrySet())
		{
			ActivityState s = e.getValue();
			if (s.active() && filter.keeps(s.bossing()))
			{
				out.add(card(e.getKey(), e.getKey().equalsIgnoreCase(self), s, now));
			}
		}
		out.sort((a, b) -> a.you != b.you ? (a.you ? -1 : 1) : a.member.compareToIgnoreCase(b.member));
		return out;
	}

	private static Card card(String member, boolean you, ActivityState s, long now)
	{
		List<String> lines = new ArrayList<>();
		lines.add(s.phase.isEmpty() ? s.name : s.name + " - " + s.phase);
		String time = ActivityState.duration(s.elapsed(now));
		lines.add(s.mode.isEmpty() ? time : s.mode + " - " + time);
		if (!s.stats.isEmpty())
		{
			lines.add(s.stats);
		}
		if (!s.mods.isEmpty())
		{
			lines.add("Modifiers: " + s.mods);
		}
		return new Card(member, you, lines);
	}

	/** "Done: Alex completed The Inferno, kill count 3 (1:58:12) - 9m ago", newest first. */
	static List<String> recent(List<GroupEvent> feed, Filter filter, ItemLookup lookup, long now)
	{
		List<GroupEvent> runs = new ArrayList<>();
		for (GroupEvent e : feed)
		{
			if (RUNS.contains(e.type) && filter.keeps(bossing(e.text)))
			{
				runs.add(e);
			}
		}
		runs.sort((a, b) -> Long.compare(b.at, a.at));
		List<String> out = new ArrayList<>();
		for (GroupEvent e : runs.subList(0, Math.min(MAX_RECENT, runs.size())))
		{
			String mark = e.type == GroupEvent.Type.ACTIVITY_DEATH ? "Died: " : "Done: ";
			out.add(mark + EventText.sentence(e, lookup) + " - " + BoostText.ago(now, e.at));
		}
		return out;
	}

	/** Every activity this build tracks is bossing; a name it does not know counts as a minigame. */
	static boolean bossing(String activity)
	{
		for (WaveTracker.Arena a : WaveTracker.Arena.values())
		{
			if (a.title.equalsIgnoreCase(activity))
			{
				return true;
			}
		}
		return false;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.concurrent.TimeUnit;

/**
 * What one member is doing right now in a tracked activity (docs/plans/activities.md §5.1): "Fight Caves, wave
 * 37/63, solo". Display-ready: every string is formatted by the sender, so a receiver on an older build still shows
 * activities it has no detector for. Immutable; {@link #NONE} is "not in an activity".
 *
 * <p>Only coarse where-and-how-far status: the activity, the wave, how long, player-chosen modifiers. Never a boss
 * mechanic, attack, prayer or hazard (§1.3).
 */
final class ActivityState
{
	/** Bossing, for the Activities tab's filter. Fight Caves, Inferno and Colosseum are all this. */
	static final String BOSS = "boss";
	static final String MINIGAME = "minigame";
	/** Not in an activity: what a clear frame decodes to. */
	static final ActivityState NONE = new Builder("", 0).build();

	/** Slug, e.g. {@code fight_caves}; empty when not in an activity. */
	final String id;
	/** {@link #BOSS} or {@link #MINIGAME}. */
	final String cat;
	/** "Fight Caves". */
	final String name;
	/** "solo", or "duo with Sam" from {@link TeamSummary}. */
	final String mode;
	/** "wave 37/63". */
	final String phase;
	/** The live board's words, coarse so the board is not edited every wave: "in Fight Caves, wave 35". */
	final String board;
	final int wave;
	final int max;
	/** When the run started, the sender's clock. */
	final long startedAt;
	/** Time spent in the run as of {@link #at} (pauses while logged out). */
	final long elapsedMs;
	/** "14,200 glory"; empty when none. */
	final String stats;
	/** "Mantimayhem II, Myopia I"; empty when none. */
	final String mods;
	/** Named group members and a count of anyone else; empty when solo. */
	final String team;
	/** When this state was true, the sender's clock. */
	final long at;
	private final String overlay;

	private ActivityState(Builder b)
	{
		id = b.id;
		cat = b.cat;
		name = b.name;
		mode = b.mode;
		phase = b.phase;
		board = b.board;
		wave = b.wave;
		max = b.max;
		startedAt = b.startedAt;
		elapsedMs = Math.max(0, b.elapsedMs);
		stats = b.stats;
		mods = b.mods;
		team = b.team;
		at = b.at;
		overlay = "  " + (phase.isEmpty() ? name : name + ": " + phase);
	}

	boolean active()
	{
		return !id.isEmpty();
	}

	/** Bossing (true) or a minigame, for the Activities tab's filter. */
	boolean bossing()
	{
		return !MINIGAME.equals(cat);
	}

	/** Time in the run at {@code now}: the elapsed time sent, plus the time since it was sent. */
	long elapsed(long now)
	{
		return elapsedMs + Math.max(0, now - at);
	}

	/** The Group tab card's line: "Fight Caves - wave 37/63 - solo". */
	String cardLine()
	{
		StringBuilder out = new StringBuilder(name);
		if (!phase.isEmpty())
		{
			out.append(" - ").append(phase);
		}
		if (!mode.isEmpty())
		{
			out.append(" - ").append(mode);
		}
		return out.toString();
	}

	/** The in-game group box's sub-line: "Fight Caves: wave 37/63". Made once here, never per frame. */
	String overlayLine()
	{
		return overlay;
	}

	/** "38m" or "1h 4m" or "42s": how long a run has gone on. */
	static String duration(long ms)
	{
		long s = TimeUnit.MILLISECONDS.toSeconds(Math.max(0, ms));
		if (s < 60)
		{
			return s + "s";
		}
		long m = s / 60;
		return m < 60 ? m + "m" : m / 60 + "h " + m % 60 + "m";
	}

	Builder toBuilder()
	{
		return new Builder(id, at).cat(cat).name(name).mode(mode).phase(phase).board(board).wave(wave).max(max)
			.startedAt(startedAt).elapsedMs(elapsedMs).stats(stats).mods(mods).team(team);
	}

	static final class Builder
	{
		private final String id;
		private final long at;
		private String cat = BOSS;
		private String name = "";
		private String mode = "";
		private String phase = "";
		private String board = "";
		private int wave;
		private int max;
		private long startedAt;
		private long elapsedMs;
		private String stats = "";
		private String mods = "";
		private String team = "";

