package com.vinnyvangogh.groupironman;

import net.runelite.client.util.QuantityFormatter;

/**
 * How an item quantity or a gp value reads (Board 2026-11-10: "450001 in
 * group storage" should read the way the game's inventory does).
 *
 * <p>The short form is RuneLite's {@code QuantityFormatter.quantityToStackSize}
 * (runelite-client {@code net/runelite/client/util/QuantityFormatter.java}):
 * under 10,000 it is the comma-grouped number; from 10,000 it divides by the
 * largest of 1K/1M/1B the amount reaches, formats with English grouping and at
 * most three decimals, keeps the first four characters and drops a trailing
 * point, then adds the suffix. So 13,280 is "13.2K", 450,001 "450K" and
 * 9,999,999 "10M" (the three-decimal rounding carries it over).
 */
enum Amounts
{
	/** The game's stack text: "13.2K", "450K", "10M". The panel, chat and overlays. */
	GAME,
	/** Every digit, comma grouped: "450,001". Panel tooltips. */
	EXACT,
	/** The game's text, then every digit when the short form dropped any: "450K (450,001)". Discord. */
	BOTH;

	/** Amounts below this read in full in the game's own format, so there is nothing to add. */
	private static final long SHORTENED_FROM = 10_000;

	String of(long amount)
	{
		switch (this)
		{
			case EXACT:
				return QuantityFormatter.formatNumber(amount);
			case BOTH:
				String game = QuantityFormatter.quantityToStackSize(amount);
				return Math.abs(amount) < SHORTENED_FROM ? game
					: game + " (" + QuantityFormatter.formatNumber(amount) + ")";
			default:
				return QuantityFormatter.quantityToStackSize(amount);
		}
	}

	/** {@code base}'s names and prices, with amounts in this style. */
	ItemLookup words(ItemLookup base)
	{
		Amounts style = this;
		return new ItemLookup()
		{
			@Override
			public String name(int id)
			{
				return base.name(id);
			}

			@Override
			public long price(int id)
			{
				return base.price(id);
			}

			@Override
			public int slot(int id)
			{
				return base.slot(id);
			}

			@Override
			public String amount(long amount)
			{
				return style.of(amount);
			}
		};
	}
}

package com.vinnyvangogh.groupironman;

import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

/**
 * Puts a member's bank back together from its parts.
 *
 * <p>Parts can arrive out of order, twice (a resend on a party sync), or not
 * at all (the member logged out mid-send). A snapshot is only handed on once
 * every part of the same snapshot is in; a newer snapshot discards an
 * unfinished older one, and a part of an older snapshot is ignored.
 *
 * <p>Synchronized: party messages arrive on OkHttp's websocket thread, and
 * leaving a party clears it from the client thread.
 */
final class BankAssembler
{
	private static final class Pending
	{
		final long takenAt;
		final Map<Integer, Integer>[] parts;

		@SuppressWarnings("unchecked")
		Pending(long takenAt, int of)
		{
			this.takenAt = takenAt;
			this.parts = new Map[of];
		}

		boolean complete()
		{
			for (Map<Integer, Integer> p : parts)
			{
				if (p == null)
				{
					return false;
				}
			}
			return true;
		}
	}

	private final Map<Long, Pending> pending = new HashMap<>();

	/** The whole snapshot when this part completes it, else null. */
	synchronized BankSnapshot accept(long memberId, GroupCodec.BankPart part)
	{
		Pending p = pending.get(memberId);
		if (p != null && part.takenAt < p.takenAt)
		{
			return null;
		}
		if (p == null || part.takenAt > p.takenAt || p.parts.length != part.of)
		{
			p = new Pending(part.takenAt, part.of);
			pending.put(memberId, p);
		}
		p.parts[part.part] = part.items;
		if (!p.complete())
		{
			return null;
		}
		pending.remove(memberId);
		Map<Integer, Integer> all = new TreeMap<>();
		for (Map<Integer, Integer> items : p.parts)
		{
			for (Map.Entry<Integer, Integer> e : items.entrySet())
			{
				all.merge(e.getKey(), e.getValue(), ItemCounts::saturatingAdd);
			}
		}
		return new BankSnapshot(p.takenAt, all);
	}

	synchronized void forget(long memberId)
	{
		pending.remove(memberId);
	}

	synchronized void clear()
	{
		pending.clear();
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collection;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.function.Predicate;

/**
 * Which bank cards in the Banks tab are open (Board 2026-11-13). Every bank
 * starts open and the player folds them from the header, like the Group tab's
 * member cards. While the bank filter searches, banks with a match show open
 * and the rest fold to their header; the player can still flip one for that
 * filter, and clearing the filter brings back what they had chosen. Held in
 * memory only, like the Group tab: nothing is saved.
 */
final class BankFolds
{
	/** Banks the player folded with no filter, by member. */
	private final Set<String> folded = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
	/** Banks flipped while the current filter searches: member to open. Cleared when the filter changes. */
	private final Map<String, Boolean> flipped = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
	private String query = "";

	/** Call before reading a draw's state, with the bank filter's text. */
	void filter(String text)
	{
		ItemQuery q = ItemQuery.parse(text);
		String now = q == null ? "" : ItemQuery.normalize(text);
		if (!now.equals(query))
		{
			flipped.clear();
			query = now;
		}
	}

	/** Whether {@code member}'s bank is drawn open; {@code matches} is whether it has an item the filter finds. */
	boolean open(String member, boolean matches)
	{
		if (query.isEmpty())
		{
			return !folded.contains(member);
		}
		Boolean flip = flipped.get(member);
		return flip != null ? flip : matches;
	}

	/** The header was clicked: fold an open bank, open a folded one. */
	void toggle(String member, boolean matches)
	{
		set(member, !open(member, matches));
	}

	/** Collapse all ({@code open} false) or Expand all. */
	void setAll(Collection<String> members, boolean open)
	{
		for (String m : members)
		{
			set(m, open);
		}
	}

	/** Whether any bank is drawn open, so the link offers Collapse all rather than Expand all. */
	boolean anyOpen(Collection<String> members, Predicate<String> matches)
	{
		for (String m : members)
		{
			if (open(m, matches.test(m)))
			{
				return true;
			}
		}
		return false;
	}

	private void set(String member, boolean open)
	{
		if (!query.isEmpty())
		{
			flipped.put(member, open);
		}
		else if (open)
		{
			folded.remove(member);
		}
		else
		{
			folded.add(member);
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Map;

/**
 * A member's bank as it was when they last closed it: item counts and when.
 * Tab-free and slot-free; see {@link ItemCounts}.
 */
final class BankSnapshot
{
	private final long takenAt;
	private final Map<Integer, Integer> items;

	BankSnapshot(long takenAt, Map<Integer, Integer> items)
	{
		this.takenAt = takenAt;
		this.items = ItemCounts.sorted(items);
	}

	/** Epoch millis on the sender's clock when the bank was closed. */
	long takenAt()
	{
		return takenAt;
	}

	Map<Integer, Integer> items()
	{
		return items;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof BankSnapshot))
		{
			return false;
		}
		BankSnapshot b = (BankSnapshot) o;
		return takenAt == b.takenAt && items.equals(b.items);
	}

	@Override
	public int hashCode()
	{
		return Long.hashCode(takenAt) * 31 + items.hashCode();
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

/**
 * Barrows set progress: which pieces of each brother's set this player has
 * had from the chest since the plugin started counting, kept by piece name
 * (a chest piece is always undegraded, so the name is the piece).
 *
 * <p>Saved as plain text in the player's RuneLite profile; it is a count of
 * what this client saw, not the collection log, and the event says "from the
 * chest" so nobody reads it as more.
 */
final class BarrowsProgress
{
	static final String[] BROTHERS = {"Ahrim's", "Dharok's", "Guthan's", "Karil's", "Torag's", "Verac's"};
	static final int PIECES = 4;

	private final Set<String> seen = new TreeSet<>();

	static BarrowsProgress parse(String saved)
	{
		BarrowsProgress out = new BarrowsProgress();
		for (String s : (saved == null ? "" : saved).split("\\|"))
		{
			if (!s.trim().isEmpty())
			{
				out.seen.add(s.trim().toLowerCase(Locale.ROOT));
			}
		}
		return out;
	}

	String save()
	{
		return String.join("|", seen);
	}

	/** Records the chest's pieces; "Dharok's 3/4" for each brother with a piece in it, empty when none. */
	String add(Map<Integer, Integer> chest, ItemLookup lookup)
	{
		Set<String> brothers = new LinkedHashSet<>();
		for (int id : chest.keySet())
		{
			String name = lookup.name(id);
			String brother = brother(name);
			if (brother != null)
			{
				seen.add(name.toLowerCase(Locale.ROOT));
				brothers.add(brother);
			}
		}
		List<String> parts = new ArrayList<>();
		for (String b : brothers)
		{
			parts.add(b + " " + count(b) + "/" + PIECES);
		}
		return String.join(", ", parts);
	}

	private int count(String brother)
	{
		String prefix = brother.toLowerCase(Locale.ROOT);
		int n = 0;
		for (String s : seen)
		{
			if (s.startsWith(prefix))
			{
				n++;
			}
		}
		return Math.min(n, PIECES);
	}

	private static String brother(String name)
	{
		for (String b : BROTHERS)
		{
			if (name.startsWith(b))
			{
				return b;
			}
		}
		return null;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.concurrent.TimeUnit;

/** Small text formats the group panel uses, kept pure so they are tested. */
final class BoostText
{
	private BoostText()
	{
	}

	/** "90" when unboosted, "90 (+8)" when boosted, "90 (-3)" when drained. */
	static String level(int real, int boosted)
	{
		int diff = boosted - real;
		if (diff == 0)
		{
			return Integer.toString(real);
		}
		return real + " (" + (diff > 0 ? "+" : "") + diff + ")";
	}

	/** "just now", "5m ago", "3h ago", "2d ago". A time ahead of now (clock skew) reads as just now. */
	static String ago(long now, long then)
	{
		long ms = now - then;
		if (ms < TimeUnit.MINUTES.toMillis(1))
		{
			return "just now";
		}
		if (ms < TimeUnit.HOURS.toMillis(1))
		{
			return TimeUnit.MILLISECONDS.toMinutes(ms) + "m ago";
		}
		if (ms < TimeUnit.DAYS.toMillis(1))
		{
			return TimeUnit.MILLISECONDS.toHours(ms) + "h ago";
		}
		return TimeUnit.MILLISECONDS.toDays(ms) + "d ago";
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

/**
 * Client thread only. Feeds {@link ContainerContents} from the game the way
 * Combat Vitals' plugin does ({@code CombatVitalsPlugin#readContainerDialog},
 * {@code #keepContainerCounts}, {@code #scanContainers}): chat lines, the Check
 * dialog's Objectbox text, Fill / Empty clicks and the inventory change after
 * them. Only reads: no click or message is changed or sent.
 *
 * <p>Known counts are kept per account (RuneScape profile config,
 * {@code containerCount.<KIND>}), so a login starts from the last known count
 * instead of no number.
 */
final class CarriedContainers
{
	static final String KEY_PREFIX = "containerCount.";
	/** "You catch some shrimps.", "You catch a shark!": one fish, which an open barrel takes. */
	private static final Pattern CATCH = Pattern.compile("^You catch (?:a|an|some) (.+?)[.!]?$");
	/** Caught fish that stack in the inventory; the barrel takes neither. */
	private static final Pattern STACKING_CATCH = Pattern.compile("^(?:minnows|karambwanji)$");
	private static final String COAL_BAG_CAPE = "smithing cape";

	private final Client client;
	private final ItemManager itemManager;
	private final ConfigManager configManager;
	private final ContainerContents contents = new ContainerContents();

	/** Containers carried in the inventory, from the last scan. */
	private final Set<SkillingContainer> carried = EnumSet.noneOf(SkillingContainer.class);
	/** The inventory's filling slots at the last scan, -1 until read. */
	private int filling = -1;
	/** The Check dialog text already read, so one dialog is read once. */
	private String dialog;
	/** Counts as last written to the profile; null until restored after a login. */
	private Map<SkillingContainer, Integer> saved;
	/** Whether an item takes its own slot that a gathered item could have used; definitions never change. */
	private final Map<Integer, Boolean> fillers = new HashMap<>();
	/** Item name to id, for a container's contents in Find; -1 for a name with no tradeable item. */
	private final Map<String, Integer> ids = new HashMap<>();

	@Inject
	CarriedContainers(Client client, ItemManager itemManager, ConfigManager configManager)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.configManager = configManager;
	}

	/** A game or spam chat line; @return whether a count changed. */
	boolean chat(String message)
	{
		String line = Text.removeTags(message);
		int tick = client.getTickCount();
		boolean changed = contents.message(line, tick);
		Matcher fish = CATCH.matcher(line);
		if (!changed && fish.matches() && !STACKING_CATCH.matcher(fish.group(1).toLowerCase(Locale.ROOT)).matches())
		{
			changed = contents.fishCaught(tick);
		}
		return changed;
	}

	/** Fill, Empty or Empty to bank on a container, in the inventory or the bank. */
	void clicked(String option, String target)
	{
		SkillingContainer kind = target == null ? null : SkillingContainer.fromItemName(Text.removeTags(target));
		if (kind != null)
		{
			contents.clicked(kind, option, client.getTickCount());
		}
	}

	/** The inventory or equipment changed; @return whether a count changed. */
	boolean itemsChanged()
	{
		int before = filling;
		scan();
		return contents.inventoryChanged(before, filling, client.getTickCount());
	}

	/** Once a tick: the Check dialog, then keeping counts per account; @return whether a count changed. */
	boolean tick()
	{
		boolean changed = readDialog();
		keepCounts();
		if (filling < 0)
		{
			scan();
		}
		return changed;
	}

	void loggedOut()
	{
		contents.clear();
		carried.clear();
		filling = -1;
		dialog = null;
		saved = null;
	}

	/** What each carried container is known to hold; one not carried, or unknown, is left out. */
	Map<SkillingContainer, GroupCodec.Held> held()
	{
		Map<SkillingContainer, GroupCodec.Held> out = new EnumMap<>(SkillingContainer.class);
		for (SkillingContainer kind : carried)
		{
			int n = contents.contents(kind);
			if (n >= 0)
			{
				out.put(kind, new GroupCodec.Held(n, itemIds(contents.named(kind))));
			}
		}
		return out;
	}

	/** Names to ids, all or nothing: one name without an item leaves the contents unfindable, not half right. */
	private Map<Integer, Integer> itemIds(Map<String, Integer> named)
	{
		if (named == null)
		{
			return Collections.emptyMap();
		}
		Map<Integer, Integer> out = new TreeMap<>();
		for (Map.Entry<String, Integer> e : named.entrySet())
		{
			int id = ids.computeIfAbsent(e.getKey().toLowerCase(Locale.ROOT), this::lookUp);
			if (id < 0)
			{
				return Collections.emptyMap();
			}
			out.merge(id, e.getValue(), Integer::sum);
		}
		return out;
	}

	/** The tradeable item named exactly {@code lowerName}, or -1. */
	private int lookUp(String lowerName)
	{
		// var: ItemManager#search's element type has moved packages between RuneLite releases.
		for (var price : itemManager.search(lowerName))
		{
			if (price.getName() != null && price.getName().equalsIgnoreCase(lowerName))
			{
				return price.getId();
			}
		}
		return -1;
	}

	/**
	 * A container's Check answers in the item dialog, not in chat: "The basket contains:<br>14 x Yew logs".
	 * Read once per dialog, with line breaks as spaces.
	 */
	private boolean readDialog()
	{
		Widget text = client.getWidget(InterfaceID.Objectbox.TEXT);
		if (text == null || text.isHidden() || text.getText() == null)
		{
			dialog = null;
			return false;
		}
		String message = Text.removeTags(text.getText().replace("<br>", " ")).trim();
		if (message.equals(dialog))
		{
			return false;
		}
		dialog = message;
		return contents.message(message, client.getTickCount());
	}

	/** Restores this account's counts once its profile is known, then writes any count that changed. */
	private void keepCounts()
	{
		if (client.getGameState() != GameState.LOGGED_IN || configManager.getRSProfileKey() == null)
		{
			return;
		}
		if (saved == null)
		{
			saved = new EnumMap<>(SkillingContainer.class);
			for (SkillingContainer kind : SkillingContainer.values())
			{
				Integer count = configManager.getRSProfileConfiguration(GroupIronmanConfig.GROUP, KEY_PREFIX + kind.name(),
					Integer.class);
				if (count != null)
				{
					contents.restore(kind, count);
					saved.put(kind, count);
				}
			}
		}
		for (Map.Entry<SkillingContainer, Integer> e : contents.known().entrySet())
		{
			if (!e.getValue().equals(saved.get(e.getKey())))
			{
				configManager.setRSProfileConfiguration(GroupIronmanConfig.GROUP, KEY_PREFIX + e.getKey().name(),
					e.getValue());
				saved.put(e.getKey(), e.getValue());
			}
		}
	}

	/** Which containers are carried and open, their capacities, and the inventory's filling slots. */
	private void scan()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return;
		}
		carried.clear();
		Set<SkillingContainer> open = EnumSet.noneOf(SkillingContainer.class);
		int slots = 0;
		for (Item item : inventory.getItems())
		{
			if (item.getId() <= 0)
			{
				continue;
			}
			String name = itemManager.getItemComposition(item.getId()).getName();
			SkillingContainer kind = SkillingContainer.fromItemName(name);
			if (kind != null)
			{
				carried.add(kind);
				if (SkillingContainer.isOpen(name))
				{
					open.add(kind);
				}
			}
			else if (fillers.computeIfAbsent(item.getId(), this::fills))
			{
				slots++;
			}
		}
		filling = slots;
		contents.carried(open, capacities());
	}

	/** A slot item: not stackable and not noted, so a gathered item could not share its slot. */
	private boolean fills(int id)
	{
		ItemComposition item = itemManager.getItemComposition(id);
		return !item.isStackable() && item.getNote() == -1;
	}

	/** The coal bag takes 36 with a Smithing cape worn. */
	private Map<SkillingContainer, Integer> capacities()
	{
		Map<SkillingContainer, Integer> out = new EnumMap<>(SkillingContainer.class);
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn == null)
		{
			return out;
		}
		for (Item item : worn.getItems())
		{
			if (item.getId() > 0 && itemManager.getItemComposition(item.getId()).getName().toLowerCase(Locale.ROOT)
				.startsWith(COAL_BAG_CAPE))
			{
				out.put(SkillingContainer.COAL_BAG, SkillingContainer.COAL_BAG_CAPE_CAPACITY);
			}
		}
		return out;
	}
}

package com.vinnyvangogh.groupironman;

import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;

/**
 * Online and offline posts for members without the plugin, as the game's Group channel sees them (Board
 * 2026-11-11, 'Online status' Posts).
 *
 * <ul>
 * <li>Each such member gets the same rules as a member's own login: the offline grace, a relog inside it posting
 * nothing, at most one pair per {@link PresenceDebounce#PAIR_MS}, a hop never a logout. It is a
 * {@link PresenceDebounce} per member.</li>
 * <li>The first channel after a {@link #reset} (this player's login) is the baseline: who is already on is not a
 * login. Losing the channel (this player's hop or logout) is not everyone logging out.</li>
 * <li>Members whose clients run the plugin post their own and are skipped.</li>
 * <li>Every plugin user sees the same channel; only the one that {@link #leads} sends the posts to Discord.</li>
 * </ul>
 *
 * Not thread-safe: the engine holds its presence lock.
 */
final class ChannelPosts
{
	private final ZoneId zone;
	private final Map<String, PresenceDebounce> members = new HashMap<>();
	private boolean seeded;

	ChannelPosts(ZoneId zone)
	{
		this.zone = zone;
	}

	/** The game's presence now: the posts for members without the plugin ({@code plugin} false), in order. */
	List<GroupEvent> update(GamePresence game, Predicate<String> plugin, long now, int graceMinutes)
	{
		if (!game.known())
		{
			return Collections.emptyList();
		}
		List<GroupEvent> out = new ArrayList<>();
		for (String name : game.names())
		{
			if (plugin.test(name))
			{
				continue;
			}
			PresenceDebounce member = members.computeIfAbsent(GroupMembers.key(name), k -> new PresenceDebounce(zone));
			if (game.state(name) == GamePresence.State.ONLINE)
			{
				List<GroupEvent> posts = member.login(now, game.world(name), name, graceMinutes);
				if (seeded)
				{
					out.addAll(posts);
				}
			}
			else
			{
				member.logout(now);
			}
		}
		seeded = true;
		return out;
	}

	/** Timer: the offlines whose grace has passed. */
	List<GroupEvent> poll(long now, int graceMinutes)
	{
		List<GroupEvent> out = new ArrayList<>();
		for (PresenceDebounce member : members.values())
		{
			GroupEvent offline = member.poll(now, graceMinutes);
			if (offline != null)
			{
				out.add(offline);
			}
		}
		return out;
	}

	/** This player logged out: forget everyone, and take the next channel as a new baseline. */
	void reset()
	{
		members.clear();
		seeded = false;
	}

	/**
	 * The group's leader posts while their client is online and in the party (Board 2026-11-14); otherwise
	 * {@link #leads(String, boolean, Collection)} picks the first by name. Every client knows the same signed leader,
	 * so they still agree; one that does not ({@code leader} empty) falls back to the name rule.
	 */
	static boolean leads(String self, boolean syncing, Collection<String> othersOnline, String leader)
	{
		String boss = GroupMembers.key(leader == null ? "" : leader);
		if (syncing && !boss.isEmpty())
		{
			if (boss.equals(GroupMembers.key(self)))
			{
				return true;
			}
			for (String other : othersOnline)
			{
				if (boss.equals(GroupMembers.key(other)))
				{
					return false;
				}
			}
		}
		return leads(self, syncing, othersOnline);
	}

	/**
	 * {@link #leads(String, Collection)} for a client that may not be in the party: one that is not syncing is
	 * not heard by the others, who may post without it, so it posts only when it hears no one either.
	 */
	static boolean leads(String self, boolean syncing, Collection<String> othersOnline)
	{
		return syncing ? leads(self, othersOnline) : othersOnline.isEmpty() && !GroupMembers.key(self).isEmpty();
	}

	/**
	 * True when {@code self} is the plugin user that posts for the rest: the first by name of itself and
	 * {@code othersOnline}, the plugin users online. Every client works it out from the same names, so one posts.
	 */
	static boolean leads(String self, Collection<String> othersOnline)
	{
		String me = GroupMembers.key(self);
		if (me.isEmpty())
		{
			return false;
		}
		for (String other : othersOnline)
		{
			String key = GroupMembers.key(other);
			if (!key.isEmpty() && key.compareTo(me) < 0)
			{
				return false;
			}
		}
		return true;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the game message "New item added to your collection log: X".
 *
 * <p>The game only sends it with the in-game setting <i>Collection log - New
 * addition notification</i> turned on; SETUP.md says so. The plugin checks the
 * message type is a game message before calling this, so a player typing the
 * same words in chat is not read.
 */
final class ClogMessage
{
	private static final Pattern NEW_SLOT = Pattern.compile("^New item added to your collection log: (.+)$");
	private static final Pattern TAG = Pattern.compile("<[^>]*>");

	private ClogMessage()
	{
	}

	/** The item name, or null when this is not that message. */
	static String parse(String message)
	{
		if (message == null)
		{
			return null;
		}
		Matcher m = NEW_SLOT.matcher(TAG.matcher(message).replaceAll("").trim());
		if (!m.matches())
		{
			return null;
		}
		String item = m.group(1).trim();
		return item.isEmpty() ? null : item;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.List;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.VarbitID;

/**
 * The Fortis Colosseum modifiers the player has already chosen, with their tier, read from the game's own level
 * varbits: "Mantimayhem II, Myopia I". Only what the player picked at the pillar; never a spawn, timer or hazard
 * (docs/plans/activities.md §1.2 row 3).
 *
 * <p>Verified against runelite-api 1.13.6 with {@code javap -constants net.runelite.api.gameval.VarbitID}: each
 * {@code COLOSSEUM_MODIFIER_*_STACKS_CLIENT} constant below exists. The mapping (and that Bees! is the game's
 * "toxicity" varbit) follows the Hub plugin LlemonDuck/fortis-colosseum, {@code util/Modifier.java}, which reads the
 * same ids (9791, 9790, 10681, 9796, 4588, 9795, 9792, 9798, 9797, 9799). A level of 0 is not chosen.
 *
 * <p>Not here: Dynamic Duo, Quartet, Red Flag and Totemic have no level varbit (one tier only); the Hub plugin reads
 * them from a script argument, a raw script id with no gameval constant, so this slice leaves them out.
 */
final class ColosseumModifiers
{
	private static final String[] NAMES = {"Bees!", "Blasphemy", "Doom", "Frailty", "Mantimayhem", "Myopia",
		"Reentry", "Relentless", "Solarflare", "Volatility"};
	private static final int[] LEVEL_VARBITS = {
		VarbitID.COLOSSEUM_MODIFIER_TOXICITY_STACKS_CLIENT,
		VarbitID.COLOSSEUM_MODIFIER_BLASPHEMY_STACKS_CLIENT,
		VarbitID.COLOSSEUM_MODIFIER_DOOM_STACKS_CLIENT,
		VarbitID.COLOSSEUM_MODIFIER_FRAILTY_STACKS_CLIENT,
		VarbitID.COLOSSEUM_MODIFIER_MANTIMAYHEM_STACKS_CLIENT,
		VarbitID.COLOSSEUM_MODIFIER_MYOPIA_STACKS_CLIENT,
		VarbitID.COLOSSEUM_MODIFIER_REENTRY_STACKS_CLIENT,
		VarbitID.COLOSSEUM_MODIFIER_RELENTLESS_STACKS_CLIENT,
		VarbitID.COLOSSEUM_MODIFIER_SOLARFLARE_STACKS_CLIENT,
		VarbitID.COLOSSEUM_MODIFIER_VOLATILITY_STACKS_CLIENT,
	};
	private static final String[] TIERS = {"", "I", "II", "III"};

	private ColosseumModifiers()
	{
	}

	/** Every varbit read, for the engine's change check. */
	static int[] varbits()
	{
		return LEVEL_VARBITS.clone();
	}

	/** "Mantimayhem II, Myopia I", in name order; empty when none chosen. */
	static String describe(IntUnaryOperator varbit)
	{
		List<String> out = new ArrayList<>();
		for (int i = 0; i < NAMES.length; i++)
		{
			int level = varbit.applyAsInt(LEVEL_VARBITS[i]);
			if (level > 0)
			{
				out.add(NAMES[i] + " " + TIERS[Math.min(level, TIERS.length - 1)]);
			}
		}
		return String.join(", ", out);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * How much is in each chat-tracked container (log basket, fish barrel, coal
 * bag), from the game's own lines, never a guess: unknown until a Check or an
 * empty says. A Check's answer is the item dialog's text (Objectbox), not a
 * chat line: "The basket contains: 14 x Yew logs".
 *
 * <p>Copied from Combat Vitals' {@code ContainerContents} (same author; a copy,
 * not a dependency, Board 2026-11-14), whose wording comes from the Plugin
 * Hub's GP Per Hour plugin (MosheBenZacharia/GP-Per-Hour @ cce6706,
 * {@code itemcharges/items/U_LogBasket.java}, {@code U_FishBarrel.java},
 * {@code U_CoalBag.java}). Fill and Empty move what the inventory change that
 * follows them shows. A gathered item that lands in the inventory while its
 * container is open means the container is full.
 *
 * <p>Added here: what is inside by item name, for Find, kept only while every
 * item is accounted for. A Check or an empty sets it, a gathered log or coal
 * that names itself adds to it, and any change it cannot name (a Fill, an
 * extra log, a fish) drops it: the count stays, the names go unknown.
 *
 * <p>Pure: messages, clicks and slot counts in, counts out.
 */
final class ContainerContents
{
	/** A Fill or Empty is matched to an inventory change at most this many ticks later. */
	static final int CLICK_TICKS = 2;

	private static final Pattern COUNT = Pattern.compile("(\\d+) x ");

	private static final Pattern BASKET_CHECK = Pattern.compile("^The basket contains:(.*)$");
	private static final Pattern BASKET_EMPTY = Pattern.compile(
		"^(?:(?:Your|The) basket is empty|You empty your basket(?: into the bank)?)\\.?$");
	private static final Pattern BASKET_ADD = Pattern.compile("^You get some ([\\w' -]+ )?logs[.!]?$");
	private static final Pattern BASKET_EXTRA = Pattern.compile("^The nature offerings enabled you to chop an extra log\\.?$");

	private static final Pattern BARREL_CHECK = Pattern.compile("^The barrel contains:(.*)$");
	private static final Pattern BARREL_EMPTY = Pattern.compile("^(?:Your|The) barrel is empty\\.?$");
	private static final Pattern BARREL_FULL = Pattern.compile("^The barrel is full\\..*$");
	private static final Pattern BARREL_EXTRA = Pattern.compile("^.* enabled you to catch an extra fish\\.?$");

	private static final Pattern COAL_CHECK = Pattern.compile("^The coal bag (?:still )?contains (one|\\d+) ");
	private static final Pattern COAL_EMPTY = Pattern.compile("^(?:Your|The) coal bag is (?:now )?empty\\.?$");
	private static final Pattern COAL_ADD = Pattern.compile("^You manage to mine some coal\\.?$");
	private static final String COAL = "Coal";

	private final Map<SkillingContainer, Integer> contents = new EnumMap<>(SkillingContainer.class);
	/** Per container, item name to count, only while it adds up to the count. */
	private final Map<SkillingContainer, Map<String, Integer>> named = new EnumMap<>(SkillingContainer.class);
	private Set<SkillingContainer> open = Collections.emptySet();
	private Map<SkillingContainer, Integer> capacities = Collections.emptyMap();

	private SkillingContainer clicked;
	private boolean clickedFill;
	private int clickedTick;

	/** The open container the last gathered item should have gone into, and the tick it was gathered. */
	private SkillingContainer gathered;
	private int gatheredTick = Integer.MIN_VALUE;
	/** The last tick the inventory's filling slots grew without a Fill or Empty to explain it. */
	private int grewTick = Integer.MIN_VALUE;
	/** The tick of the message being handled, MIN_VALUE when the caller has none. */
	private int tick = Integer.MIN_VALUE;

	/** Items inside, or -1 while unknown. */
	int contents(SkillingContainer container)
	{
		final Integer n = contents.get(container);
		return n == null ? -1 : n;
	}

	/** Item name to count when every item inside is known, else null. */
	Map<String, Integer> named(SkillingContainer container)
	{
		final Map<String, Integer> n = named.get(container);
		return n == null ? null : Collections.unmodifiableMap(new TreeMap<>(n));
	}

	/** Every known count, for the plugin to keep across logins. */
	Map<SkillingContainer, Integer> known()
	{
		return new EnumMap<>(contents);
	}

	/** A count kept from an earlier login; a count already known this session wins. */
	void restore(SkillingContainer container, int count)
	{
		if (count >= 0 && !contents.containsKey(container))
		{
			contents.put(container, count);
		}
	}

	/** Which containers are carried open, and every carried one's capacity, from the last scan. */
	void carried(Set<SkillingContainer> open, Map<SkillingContainer, Integer> capacities)
	{
		this.open = open.isEmpty() ? Collections.emptySet() : EnumSet.copyOf(open);
		this.capacities = capacities;
	}

	/** @return whether a count changed */
	boolean message(String message)
	{
		return message(message, Integer.MIN_VALUE);
	}

	/**
	 * A chat line, or a Check dialog's text, seen on {@code tick}.
	 *
	 * @return whether a count changed
	 */
	boolean message(String message, int tick)
	{
		if (message == null)
		{
			return false;
		}
		this.tick = tick;
		return basket(message) || barrel(message) || coal(message);
	}

	/** A fish worth a barrel slot was caught; it lands in the barrel while open and not full. */
	boolean fishCaught(int tick)
	{
		this.tick = tick;
		return addOne(SkillingContainer.FISH_BARREL, null);
	}

	/** Fill, Empty or Empty to bank clicked on a container; anything else is ignored. */
	void clicked(SkillingContainer container, String option, int tick)
	{
		if ("Empty to bank".equalsIgnoreCase(option))
		{
			named.put(container, new TreeMap<>());
			set(container, 0);
			clicked = null;
		}
		else if ("Fill".equalsIgnoreCase(option) || "Empty".equalsIgnoreCase(option))
		{
			clicked = container;
			clickedFill = "Fill".equalsIgnoreCase(option);
			clickedTick = tick;
		}
	}

	/**
	 * The inventory's filling slots changed: after a Fill, what left went in;
	 * after an Empty, what arrived came out.
	 *
	 * @return whether a count changed
	 */
	boolean inventoryChanged(int fillingBefore, int fillingAfter, int tick)
	{
		if (!clickPending(tick) || fillingBefore < 0 || fillingAfter < 0)
		{
			return fillingBefore >= 0 && fillingAfter > fillingBefore && grew(tick);
		}
		return moved(clickedFill ? fillingBefore - fillingAfter : fillingAfter - fillingBefore);
	}

	/** A Fill or Empty clicked recently enough to explain an inventory change on {@code tick}. */
	private boolean clickPending(int tick)
	{
		return clicked != null && tick - clickedTick <= CLICK_TICKS;
	}

	/** {@code moved} items went in (Fill) or came out (Empty) of the clicked container. */
	private boolean moved(int moved)
	{
		final SkillingContainer container = clicked;
		final int now = contents(container);
		if (moved <= 0 || now < 0)
		{
			return false;
		}
		clicked = null;
		set(container, clickedFill ? Math.min(capacity(container), now + moved) : Math.max(0, now - moved));
		return true;
	}

	void clear()
	{
		contents.clear();
		named.clear();
		open = Collections.emptySet();
		capacities = Collections.emptyMap();
		clicked = null;
		gathered = null;
		gatheredTick = Integer.MIN_VALUE;
		grewTick = Integer.MIN_VALUE;
	}

	/** The inventory grew on {@code tick} with no Fill or Empty behind it: full, if an item was just gathered. */
	private boolean grew(int tick)
	{
		grewTick = tick;
		return fullIfLanded();
	}

	/** A gathered item and an inventory that grew on the same tick: it missed the open container, so it is full. */
	private boolean fullIfLanded()
	{
		if (gathered == null || gatheredTick == Integer.MIN_VALUE || gatheredTick != grewTick
			|| !open.contains(gathered))
		{
			return false;
		}
		set(gathered, capacity(gathered));
		gathered = null;
		return true;
	}

	private boolean basket(String message)
	{
		if (check(SkillingContainer.LOG_BASKET, BASKET_CHECK, message)
			|| empty(SkillingContainer.LOG_BASKET, BASKET_EMPTY, message))
		{
			return true;
		}
		final Matcher add = BASKET_ADD.matcher(message);
		if (add.matches())
		{
			return addOne(SkillingContainer.LOG_BASKET, logName(add.group(1)));
		}
		return BASKET_EXTRA.matcher(message).matches() && addOne(SkillingContainer.LOG_BASKET, null);
	}

	/** "You get some yew logs.": "Yew logs"; "You get some logs.": "Logs". */
	static String logName(String kind)
	{
		if (kind == null || kind.trim().isEmpty())
		{
			return "Logs";
		}
		final String k = kind.trim();
		return Character.toUpperCase(k.charAt(0)) + k.substring(1) + " logs";
	}

	private boolean barrel(String message)
	{
		if (BARREL_FULL.matcher(message).matches())
		{
			set(SkillingContainer.FISH_BARREL, capacity(SkillingContainer.FISH_BARREL));
			return true;
		}
		return check(SkillingContainer.FISH_BARREL, BARREL_CHECK, message)
			|| empty(SkillingContainer.FISH_BARREL, BARREL_EMPTY, message)
			|| (BARREL_EXTRA.matcher(message).matches() && addOne(SkillingContainer.FISH_BARREL, null));
	}

	private boolean coal(String message)
	{
		final Matcher check = COAL_CHECK.matcher(message);
		if (check.find())
		{
			final int n = "one".equals(check.group(1)) ? 1 : Integer.parseInt(check.group(1));
			final Map<String, Integer> items = new TreeMap<>();
			if (n > 0)
			{
				items.put(COAL, n);
			}
			named.put(SkillingContainer.COAL_BAG, items);
			set(SkillingContainer.COAL_BAG, n);
			return true;
		}
		return empty(SkillingContainer.COAL_BAG, COAL_EMPTY, message)
			|| (COAL_ADD.matcher(message).matches() && addOne(SkillingContainer.COAL_BAG, COAL));
	}

	/** "The basket contains: 5 x Logs, 3 x Oak logs": the sum of the counts, and each name's. */
	private boolean check(SkillingContainer container, Pattern pattern, String message)
	{
		final Matcher matcher = pattern.matcher(message);
		if (!matcher.matches())
		{
			return false;
		}
		final String list = matcher.group(1);
		final Map<String, Integer> items = new TreeMap<>();
		int total = 0;
		final Matcher count = COUNT.matcher(list);
		boolean more = count.find();
		while (more)
		{
			final int n = Integer.parseInt(count.group(1));
			final int nameStart = count.end();
			more = count.find();
			final String name = itemName(list.substring(nameStart, more ? count.start() : list.length()));
			total += n;
			if (!name.isEmpty())
			{
				items.merge(name, n, Integer::sum);
			}
		}
		named.put(container, items);
		set(container, total);
		return true;
	}

	/** " Yew logs, " or " Yew logs" (dialog lines joined by spaces): "Yew logs". */
	private static String itemName(String raw)
	{
		String name = raw.trim();
		while (name.endsWith(",") || name.endsWith("."))
		{
			name = name.substring(0, name.length() - 1).trim();
		}
		return name;
	}

	private boolean empty(SkillingContainer container, Pattern pattern, String message)
	{
		if (!pattern.matcher(message).matches())
		{
			return false;
		}
		named.put(container, new TreeMap<>());
		set(container, 0);
		return true;
	}

	/**
	 * One more into an open container that is known and not full; otherwise it went to the inventory.
	 * Remembered for the tick, so an inventory that grew on it as well marks the container full.
	 * {@code name} is the item when the line names it, else null.
	 */
	private boolean addOne(SkillingContainer container, String name)
	{
		if (open.contains(container) && tick != Integer.MIN_VALUE)
		{
			gathered = container;
			gatheredTick = tick;
			if (fullIfLanded())
			{
				return true;
			}
		}
		final int now = contents(container);
		if (!open.contains(container) || now < 0 || now >= capacity(container))
		{
			return false;
		}
		final Map<String, Integer> items = named.get(container);
		if (items != null && name != null)
		{
			items.merge(name, 1, Integer::sum);
		}
		set(container, now + 1);
		return true;
	}

	/** Sets a count; the names stay only while they add up to it. */
	private void set(SkillingContainer container, int count)
	{
		contents.put(container, count);
		final Map<String, Integer> items = named.get(container);
		if (items == null)
		{
			return;
		}
		int sum = 0;
		for (int n : items.values())
		{
			sum += n;
		}
		if (sum != count)
		{
			named.remove(container);
		}
	}

	private int capacity(SkillingContainer container)
	{
		final Integer capacity = capacities.get(container);
		return capacity != null ? capacity : container.capacity;
	}
}

package com.vinnyvangogh.groupironman;

import java.time.DayOfWeek;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.temporal.TemporalAdjusters;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;

/**
 * The daily digest: each category's lines since the last digest, collected
 * alongside the instant posts (never instead of them), and when the digest
 * and the weekly recap are due. Pure and clock-free, so the schedule is
 * tested with fixed times.
 *
 * <p>Only this player's own lines are ever held, the same rule as every post
 * (BRIEF.md #18), so a group's digests are one per member.
 */
final class Digest
{
	/** Most lines kept per category per day; the oldest make way. */
	static final int MAX_LINES = 50;

	private final Map<GroupEvent.Category, LinkedList<String>> lines = new EnumMap<>(GroupEvent.Category.class);

	synchronized void add(GroupEvent.Category category, String line)
	{
		LinkedList<String> held = lines.computeIfAbsent(category, c -> new LinkedList<>());
		held.addLast(line);
		while (held.size() > MAX_LINES)
		{
			held.removeFirst();
		}
	}

	/** The held lines, oldest first, and forgets them. */
	synchronized List<String> drain(GroupEvent.Category category)
	{
		LinkedList<String> held = lines.remove(category);
		return held == null ? new ArrayList<>() : new ArrayList<>(held);
	}

	/** One {@code CATEGORY<tab>line} per line. Event text holds no tabs or newlines once flattened. */
	synchronized String save()
	{
		StringBuilder out = new StringBuilder();
		for (Map.Entry<GroupEvent.Category, LinkedList<String>> e : lines.entrySet())
		{
			for (String line : e.getValue())
			{
				out.append(e.getKey().name()).append('\t').append(flat(line)).append('\n');
			}
		}
		return out.toString();
	}

	private static String flat(String line)
	{
		return line.replace('\t', ' ').replace('\n', ' ');
	}

	static Digest parse(String saved)
	{
		Digest out = new Digest();
		for (String row : (saved == null ? "" : saved).split("\n"))
		{
			String[] parts = row.split("\t", 2);
			GroupEvent.Category category = parts.length == 2 ? category(parts[0]) : null;
			if (category != null)
			{
				out.add(category, parts[1]);
			}
		}
		return out;
	}

	private static GroupEvent.Category category(String name)
	{
		for (GroupEvent.Category c : GroupEvent.Category.values())
		{
			if (c.name().equals(name))
			{
				return c;
			}
		}
		return null;
	}

	/** Today's digest time has passed and the last one was before it. A first run ({@code last} 0) only baselines. */
	static boolean dailyDue(long last, long now, int hour, ZoneId zone)
	{
		if (last <= 0)
		{
			return false;
		}
		ZonedDateTime today = Instant.ofEpochMilli(now).atZone(zone).withHour(hour).withMinute(0).withSecond(0)
			.withNano(0);
		return now >= today.toInstant().toEpochMilli() && last < today.toInstant().toEpochMilli();
	}

	/** This Monday's recap time has passed and the last recap was before it. */
	static boolean weeklyDue(long last, long now, int hour, ZoneId zone)
	{
		if (last <= 0)
		{
			return false;
		}
		ZonedDateTime monday = Instant.ofEpochMilli(now).atZone(zone)
			.with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY)).withHour(hour).withMinute(0).withSecond(0)
			.withNano(0);
		long at = monday.toInstant().toEpochMilli();
		return now >= at && last < at;
	}

	/** One player's week: XP since the first reading, and counts. Saved per account. */
	static final class Week
	{
		private long xpStart = -1;
		private long xpNow;
		private int drops;
		private int kills;
		private int deposits;
		private int withdrawals;

		private Week()
		{
		}

		void xp(long total)
		{
			if (xpStart < 0)
			{
				xpStart = total;
			}
			xpNow = total;
		}

		void drop()
		{
			drops++;
		}

		void kill()
		{
			kills++;
		}

		void storage(boolean deposit)
		{
			if (deposit)
			{
				deposits++;
			}
			else
			{
				withdrawals++;
			}
		}

		GroupEvent recap(long at, String member)
		{
			return GroupEvent.of(GroupEvent.Type.WEEKLY_RECAP, at, member)
				.text(drops + " drops, " + kills + " kills, " + deposits + " deposits, " + withdrawals + " withdrawals")
				.number(xpStart < 0 ? 0 : Math.max(0, xpNow - xpStart))
				.build();
		}

		void startOver()
		{
			xpStart = xpNow;
			drops = 0;
			kills = 0;
			deposits = 0;
			withdrawals = 0;
		}

		String save()
		{
			return xpStart + "," + xpNow + "," + drops + "," + kills + "," + deposits + "," + withdrawals;
		}

		static Week parse(String saved)
		{
			Week w = new Week();
			String[] p = (saved == null ? "" : saved).split(",");
			if (p.length != 6)
			{
				return w;
			}
			try
			{
				w.xpStart = Long.parseLong(p[0]);
				w.xpNow = Long.parseLong(p[1]);
				w.drops = Integer.parseInt(p[2]);
				w.kills = Integer.parseInt(p[3]);
				w.deposits = Integer.parseInt(p[4]);
				w.withdrawals = Integer.parseInt(p[5]);
				return w;
			}
			catch (NumberFormatException e)
			{
				return new Week();
			}
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

/**
 * Holds the Discord-bound events of one moment until the rest of it has
 * arrived, one open moment per {@link DiscordMerge.Family}. A kill's pet line,
 * a tick's combat level and a death's value all come a little after the first
 * event; {@link DiscordMerge} then makes the moment one post.
 *
 * <p>A second event of a kind already held (the next kill's drop) starts a
 * new moment rather than joining the old one; levels, collection log slots
 * and minimums come several at once, so for them only the same skill, slot
 * or item twice does. Client thread
 * only, apart from {@link Pending#screenshot}, which the frame encoder sets.
 */
final class DiscordBatch
{
	static final class Pending
	{
		final DiscordMerge.Family family;
		final List<GroupEvent> events = new ArrayList<>();
		final long due;
		/** The frame drawn when the moment began; null until it is encoded, or when none was asked for. */
		volatile byte[] screenshot;

		private Pending(DiscordMerge.Family family, long due)
		{
			this.family = family;
			this.due = due;
		}

		private boolean repeats(GroupEvent e)
		{
			for (GroupEvent held : events)
			{
				if (held.type == e.type && (held.text.equalsIgnoreCase(e.text) || !sharesMoment(e.type)))
				{
					return true;
				}
			}
			return false;
		}

		/** Kinds that come several to a moment, one per skill, slot or item: only the same one twice is a repeat. */
		private static boolean sharesMoment(GroupEvent.Type type)
		{
			return DiscordMerge.family(type) == DiscordMerge.Family.LEVEL || type == GroupEvent.Type.CLOG
				|| type == GroupEvent.Type.STORAGE_MINIMUM;
		}
	}

	private final Map<DiscordMerge.Family, Pending> open = new EnumMap<>(DiscordMerge.Family.class);

	/**
	 * Adds an event of a family to its open moment, or opens one that stays open {@code window} ms. Moments this
	 * finishes go into {@code done}. Returns the moment the event joined; it was just opened when it holds only
	 * this event.
	 */
	Pending add(GroupEvent e, long now, long window, List<Pending> done)
	{
		DiscordMerge.Family family = DiscordMerge.family(e.type);
		Pending p = open.get(family);
		if (p != null && p.repeats(e))
		{
			done.add(open.remove(family));
			p = null;
		}
		if (p == null)
		{
			p = new Pending(family, now + window);
			open.put(family, p);
		}
		p.events.add(e);
		if (DiscordMerge.closes(e.type))
		{
			done.add(open.remove(family));
		}
		return p;
	}

	/** Lends an open moment an event that is not posted on its own (a storage visit's summary). */
	void attach(GroupEvent e)
	{
		Pending p = open.get(DiscordMerge.family(e.type));
		if (p != null && p.events.stream().noneMatch(e::sameAs))
		{
			p.events.add(e);
		}
	}

	/** The moments whose wait is over, removed. */
	List<Pending> due(long now)
	{
		List<Pending> out = new ArrayList<>();
		for (Iterator<Pending> it = open.values().iterator(); it.hasNext(); )
		{
			Pending p = it.next();
			if (now >= p.due)
			{
				out.add(p);
				it.remove();
			}
		}
		return out;
	}

	/** Every open moment, removed: at logout, nothing more of any of them is coming. */
	List<Pending> drain()
	{
		List<Pending> out = new ArrayList<>(open.values());
		open.clear();
		return out;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * One moment, one Discord post. Kinds that describe the same moment (a kill's
 * drop, unique, collection log slot and pet; a tick's level up, 99, total and
 * combat level; a death and what it cost; one storage visit) are one
 * {@link Family}: {@link DiscordBatch} holds them for a moment and this turns
 * them into one {@link Post}, titled after the highest-ranked kind, with the
 * rest as extra lines. Pure, so every merge is tested without a client.
 *
 * <p>Discord only: the overlay and chat still get every event on its own.
 */
final class DiscordMerge
{
	/** Kinds that can share a moment. Each family lists its kinds best first: the first one present titles the post. */
	enum Family
	{
		DROP(1_800, GroupEvent.Type.PET, GroupEvent.Type.CLOG, GroupEvent.Type.UNIQUE, GroupEvent.Type.DROP),
		LEVEL(1_200, GroupEvent.Type.MAXED, GroupEvent.Type.TOTAL_LEVEL, GroupEvent.Type.COMBAT_LEVEL,
			GroupEvent.Type.LEVEL_UP, GroupEvent.Type.XP_MILESTONE),
		DEATH(1_200, GroupEvent.Type.DEATH, GroupEvent.Type.HC_LIFE_LOST, GroupEvent.Type.DEATH_VALUE),
		// The minimum and the visit reach the engine in one client-thread call: the next tick has them all.
		STORAGE(0, GroupEvent.Type.STORAGE_MINIMUM, GroupEvent.Type.STORAGE_LAST, GroupEvent.Type.STORAGE_DEPOSIT,
			GroupEvent.Type.STORAGE_WITHDRAWAL, GroupEvent.Type.STORAGE_SUMMARY);

		/** How long, in ms, the first event of a moment waits for the rest. */
		final long wait;
		final List<GroupEvent.Type> ranked;

		Family(long wait, GroupEvent.Type... ranked)
		{
			this.wait = wait;
			this.ranked = Collections.unmodifiableList(java.util.Arrays.asList(ranked));
		}
	}

	/** A death's value is counted {@link EventWatchers#DEATH_SETTLE_TICKS} ticks after it; wait past that. */
	static final long DEATH_VALUE_WAIT = 12_000;
	static final String BIG_VISIT = "Big storage visit";
	/** Discord refuses a field value over 1,024 characters. */
	static final int MAX_FIELD = 1_024;
	/** Discord allows 25 fields; Value, World and Where come first. */
	static final int MAX_EXTRAS = 20;

	private static final Map<GroupEvent.Type, Family> FAMILY = new EnumMap<>(GroupEvent.Type.class);
	private static final Map<GroupEvent.Type, Integer> RANK = new EnumMap<>(GroupEvent.Type.class);

	static
	{
		for (Family f : Family.values())
		{
			for (int i = 0; i < f.ranked.size(); i++)
			{
				FAMILY.put(f.ranked.get(i), f);
				RANK.put(f.ranked.get(i), i);
			}
		}
	}

	private DiscordMerge()
	{
	}

	/** The family a kind belongs to; null for a kind that is always its own post. */
	static Family family(GroupEvent.Type type)
	{
		return FAMILY.get(type);
	}

	/** How long a moment of this family stays open. A death waits for its value only when that is posted. */
	static long window(Family family, EventSettings settings)
	{
		if (family == Family.DEATH && settings.discord.contains(GroupEvent.Type.DEATH_VALUE))
		{
			return DEATH_VALUE_WAIT;
		}
		return family == null ? 0 : family.wait;
	}

	/** The last kind a moment can have: once it is in, nothing else is coming. */
	static boolean closes(GroupEvent.Type type)
	{
		return type == GroupEvent.Type.DEATH_VALUE;
	}

	/** What one Discord post says. A single event's post reads exactly as it did before merging existed. */
	static final class Post
	{
		/** Whose and when, the colour and the webhook: the highest-ranked event. */
		final GroupEvent lead;
		final String title;
		final String description;
		/** For the Value field and the thumbnail. */
		final Map<Integer, Integer> items;
		/** The other facts of the moment, each a field: {title, line}. */
		final List<String[]> extras;
		/** Worth the configured mention. */
		final boolean big;
		/**
		 * Group storage only: what went in and what came out, so the Value is the net (Board 2026-11-15: took 180,
		 * deposited 9,300 is 9,120, not 9,480). Null for every other post, whose Value sums {@link #items}.
		 */
		final Map<Integer, Integer> deposited;
		final Map<Integer, Integer> taken;

		Post(GroupEvent lead, String title, String description, Map<Integer, Integer> items, List<String[]> extras,
			boolean big)
		{
			this(lead, title, description, items, extras, big, null, null);
		}

		Post(GroupEvent lead, String title, String description, Map<Integer, Integer> items, List<String[]> extras,
			boolean big, Map<Integer, Integer> deposited, Map<Integer, Integer> taken)
		{
			this.lead = lead;
			this.title = title;
			this.description = description;
			this.items = items;
			this.extras = extras;
			this.big = big;
			this.deposited = deposited;
			this.taken = taken;
		}
	}

	/**
	 * The Value field's text: the summed worth for most posts; for group storage the net, deposited minus taken,
	 * with both sides when both moved ("9,120 gp (deposited 9,300, took 180)"). Empty when there is nothing to show.
	 */
	static String valueText(Post post, ItemLookup lookup)
	{
		if (post.deposited == null || post.taken == null)
		{
			long value = EventText.value(post.items, lookup);
			return value > 0 ? lookup.amount(value) + " gp" : "";
		}
		long in = EventText.value(post.deposited, lookup);
		long out = EventText.value(post.taken, lookup);
		if (in <= 0 && out <= 0)
		{
			return "";
		}
		if (out <= 0)
		{
			return lookup.amount(in) + " gp";
		}
		if (in <= 0)
		{
			return lookup.amount(out) + " gp taken";
		}
		long net = in - out;
		return (net < 0 ? "-" : "") + lookup.amount(Math.abs(net)) + " gp (deposited " + lookup.amount(in)
			+ ", took " + lookup.amount(out) + ")";
	}

	/** {@code lookup} words amounts the Discord way ({@link Amounts#BOTH}); the title says "Offline" for a logout. */
	static Post single(GroupEvent e, ItemLookup lookup)
	{
		return new Post(e, EventText.title(e), EventText.describe(e, lookup), e.items,
			Collections.emptyList(), e.isBig());
	}

	/** One post for a moment's events; null when none of them is worth posting on its own. */
	static Post merge(List<GroupEvent> events, EventSettings settings, ItemLookup lookup)
	{
		Post visit = visit(events, settings, lookup);
		if (visit != null)
		{
			return visit;
		}
		List<GroupEvent> kept = new ArrayList<>();
		for (GroupEvent e : events)
		{
			// A visit's summary rides along for the big post's item list; on its own it needs its switch.
			if (e.type != GroupEvent.Type.STORAGE_SUMMARY || settings.discord.contains(e.type))
			{
				kept.add(e);
			}
		}
		if (kept.size() > 1)
		{
			// A death that cost 0 gp adds no line to its death's post; alone, DiscordWebhook decides.
			kept.removeIf(EasterEggs::nothingLost);
		}
		if (kept.isEmpty())
		{
			return null;
		}
		kept.sort(Comparator.comparingInt(e -> RANK.getOrDefault(e.type, 0)));
		GroupEvent lead = kept.get(0);
		List<GroupEvent> rest = kept.subList(1, kept.size());
		return new Post(lead, EventText.title(lead), EventText.describe(lead, lookup), richest(kept, lookup),
			extras(rest, lookup), anyBig(kept));
	}

	/**
	 * A storage visit as one post: every item moved, the big stacks marked, the visit's total value, and the
	 * minimum and last-one lines. Null when the visit had no big move and the summary is off.
	 */
	private static Post visit(List<GroupEvent> events, EventSettings settings, ItemLookup lookup)
	{
		GroupEvent summary = find(events, GroupEvent.Type.STORAGE_SUMMARY);
		boolean deposit = find(events, GroupEvent.Type.STORAGE_DEPOSIT) != null;
		boolean withdrawal = find(events, GroupEvent.Type.STORAGE_WITHDRAWAL) != null;
		if (summary == null || !deposit && !withdrawal && !settings.discord.contains(GroupEvent.Type.STORAGE_SUMMARY))
		{
			return null;
		}
		StringBuilder text = new StringBuilder("group storage:");
		moved(text, "took", summary.taken, settings.storageMin, lookup);
		moved(text, "deposited", summary.items, settings.storageMin, lookup);
		Map<Integer, Integer> all = new TreeMap<>(summary.taken);
		summary.items.forEach((id, n) -> all.merge(id, n, Integer::sum));
		return new Post(summary, visitTitle(deposit, withdrawal), text.toString(), all,
			extras(folded(events), lookup), anyBig(events), summary.items, summary.taken);
	}

	static String visitTitle(boolean deposit, boolean withdrawal)
	{
		if (deposit && withdrawal)
		{
			return BIG_VISIT;
		}
		if (withdrawal)
		{
			return EventText.title(GroupEvent.Type.STORAGE_WITHDRAWAL);
		}
		return EventText.title(deposit ? GroupEvent.Type.STORAGE_DEPOSIT : GroupEvent.Type.STORAGE_SUMMARY);
	}

	/** A visit's minimum and last-one events, best first: lines in its post. */
	private static List<GroupEvent> folded(List<GroupEvent> events)
	{
		List<GroupEvent> rest = new ArrayList<>();
		for (GroupEvent e : events)
		{
			if (e.type == GroupEvent.Type.STORAGE_MINIMUM || e.type == GroupEvent.Type.STORAGE_LAST)
			{
				rest.add(e);
			}
		}
		rest.sort(Comparator.comparingInt(e -> RANK.get(e.type)));
		return rest;
	}

	/**
	 * " took 40K (40,000) x Coins (big, 40K gp), 5 x Lobster", after a "; " when something came before. The
	 * stack's amount is in {@code lookup}'s words; the big value is the game's short form, as
	 * {@link EventText#items} keeps it, so parentheses never nest.
	 */
	static void moved(StringBuilder text, String verb, Map<Integer, Integer> items, long min,
		ItemLookup lookup)
	{
		if (items.isEmpty())
		{
			return;
		}
		text.append(text.charAt(text.length() - 1) == ':' ? " " : "; ").append(verb).append(' ');
		List<String> parts = new ArrayList<>();
		for (Map.Entry<Integer, Integer> e : items.entrySet())
		{
			long worth = lookup.price(e.getKey()) * e.getValue();
			String part = lookup.amount(e.getValue()) + " x " + lookup.name(e.getKey());
			parts.add(worth >= min && worth > 0 ? part + " (big, " + Amounts.GAME.of(worth) + " gp)" : part);
		}
		text.append(String.join(", ", parts));
	}

	private static GroupEvent find(List<GroupEvent> events, GroupEvent.Type type)
	{
		for (GroupEvent e : events)
		{
			if (e.type == type)
			{
				return e;
			}
		}
		return null;
	}

	private static List<String[]> extras(List<GroupEvent> events, ItemLookup lookup)
	{
		List<String[]> out = new ArrayList<>();
		for (GroupEvent e : events)
		{
			if (out.size() >= MAX_EXTRAS)
			{
				break;
			}
			String line = EventText.describe(e, lookup);
			out.add(new String[]{EventText.title(e), line.length() > MAX_FIELD ? line.substring(0, MAX_FIELD) : line});
		}
		return out;
	}

	/** The items of the event worth the most: the drop over its untradeable subset, the death's losses. */
	private static Map<Integer, Integer> richest(List<GroupEvent> events, ItemLookup lookup)
	{
		Map<Integer, Integer> best = Collections.emptyMap();
		long bestValue = -1;
		for (GroupEvent e : events)
		{
			long v = EventText.value(e.items, lookup);
			if (!e.items.isEmpty() && v > bestValue)
			{
				best = e.items;
				bestValue = v;
			}
		}
		return best;
	}

	private static boolean anyBig(List<GroupEvent> events)
	{
		for (GroupEvent e : events)
		{
			if (e.isBig())
			{
				return true;
			}
		}
		return false;
	}
}

package com.vinnyvangogh.groupironman;

/**
 * Whose name a Discord post goes out under. Public, like every setting type: RuneLite reads settings through a
 * proxy that cannot see a package-private type, and the client black-screens (ConfigKeysTest).
 */
public enum DiscordPosterName
{
	/**
	 * No {@code username} is sent, so Discord shows the name and avatar set on the webhook. The label is short
	 * because the dropdown is as wide as its longest label, and a long one squeezed "Poster name" to "P...".
	 * Only the label: the setting is saved under the constant's name, so changing it never resets anyone.
	 */
	WEBHOOK("Webhook's own"),
	/**
	 * The webhook's RuneScape-flavoured default name ({@link Webhook#defaultName}). The constant keeps its first
	 * name, GIM_UTILITIES, because that is what a saved choice is stored under.
	 */
	GIM_UTILITIES("Default name"),
	/** The webhook's Custom box; a blank or refused box uses the default name. */
	CUSTOM("Custom");

	private final String label;

	DiscordPosterName(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.concurrent.TimeUnit;

/**
 * The posts waiting for one Discord webhook URL, and when the next may go ({@link DiscordSender} keeps one per
 * URL, so every limit below is per webhook). Pure and
 * clock-driven, so rate limits, back-off and quiet hours are tested without
 * a network.
 *
 * <ul>
 * <li>At most {@link #MAX_QUEUED} wait; a new post past that drops the oldest, whose {@link Result} hears
 * {@link #DROPPED}.</li>
 * <li>At most {@link #PER_MINUTE} go in any minute, well under Discord's own
 * per-webhook limit, so a busy evening never trips it.</li>
 * <li>A 429 waits its Retry-After and tries the same post again; a 5xx or a
 * network failure waits {@link #RETRY_MS}, at most {@link #MAX_ATTEMPTS} times.
 * Any other 4xx (a deleted webhook) drops the post: retrying cannot fix it.</li>
 * <li>One post is in flight at a time, so they arrive in order.</li>
 * </ul>
 */
final class DiscordQueue
{
	static final int MAX_QUEUED = 50;
	static final int PER_MINUTE = 20;
	static final long RETRY_MS = TimeUnit.SECONDS.toMillis(5);
	static final int MAX_ATTEMPTS = 3;
	/** The status a {@link Result} hears when its post was dropped from a full queue, never sent. */
	static final int DROPPED = -1;
	private static final long MINUTE = TimeUnit.MINUTES.toMillis(1);

	/** The final outcome of a post the caller wants to hear about: its status, and the created message's id. */
	interface Result
	{
		void done(int status, String messageId);
	}

	static final class Post
	{
		final String url;
		final String json;
		/** A PNG to attach, or null. */
		final byte[] png;
		/** The message this post edits in place (or deletes), or null for a new message. */
		final String edit;
		/** Told once how it went (never for a retry); null when nobody asks. A new post with one waits for its id. */
		final Result result;
		/** Deletes {@link #edit} instead of editing it; {@link #json} is null. */
		final boolean delete;
		int attempts;

		Post(String url, String json, byte[] png)
		{
			this(url, json, png, null, null);
		}

		Post(String url, String json, byte[] png, String edit, Result result)
		{
			this(url, json, png, edit, result, false);
		}

		private Post(String url, String json, byte[] png, String edit, Result result, boolean delete)
		{
			this.url = url;
			this.json = json;
			this.png = png;
			this.edit = edit;
			this.result = result;
			this.delete = delete;
		}

		/** Deletes {@code messageId}, sent by {@code url}'s webhook. */
		static Post delete(String url, String messageId, Result result)
		{
			return new Post(url, null, null, messageId, result, true);
		}
	}

	private final Deque<Post> waiting = new ArrayDeque<>();
	private final Deque<Long> sent = new ArrayDeque<>();
	private long notBefore;
	private Post inFlight;

	/**
	 * Queues {@code post}; the oldest waiting go when the queue is full. Returns those dropped that wanted their
	 * outcome, for the caller to tell {@link #DROPPED} outside this lock.
	 */
	synchronized List<Post> offer(Post post)
	{
		List<Post> dropped = new ArrayList<>();
		while (waiting.size() >= MAX_QUEUED)
		{
			Post old = waiting.pollFirst();
			if (old.result != null)
			{
				dropped.add(old);
			}
		}
		waiting.addLast(post);
		return dropped;
	}

	synchronized int size()
	{
		return waiting.size() + (inFlight == null ? 0 : 1);
	}

	/** The post to send now, or null: one in flight, quiet hours, a back-off, or the minute's cap reached. */
	synchronized Post next(long now, boolean quiet)
	{
		while (!sent.isEmpty() && now - sent.peekFirst() >= MINUTE)
		{
			sent.pollFirst();
		}
		if (inFlight != null || quiet || now < notBefore || sent.size() >= PER_MINUTE || waiting.isEmpty())
		{
			return null;
		}
		inFlight = waiting.pollFirst();
		inFlight.attempts++;
		sent.addLast(now);
		return inFlight;
	}

	/**
	 * How the in-flight post went: an HTTP status, or 0 for a network failure.
	 * {@code retryAfterMs} is the 429's Retry-After, negative when absent. True when the post will be tried again.
	 */
	synchronized boolean done(int status, long retryAfterMs, long now)
	{
		Post post = inFlight;
		inFlight = null;
		if (post == null || status >= 200 && status < 300)
		{
			return false;
		}
		if (status == 429)
		{
			notBefore = now + (retryAfterMs >= 0 ? retryAfterMs : RETRY_MS);
			waiting.addFirst(post);
			return true;
		}
		if ((status == 0 || status >= 500) && post.attempts < MAX_ATTEMPTS)
		{
			notBefore = now + RETRY_MS;
			waiting.addFirst(post);
			return true;
		}
		return false;
	}

	synchronized void clear()
	{
		waiting.clear();
		inFlight = null;
	}

	/** Quiet from {@code start} up to {@code end} (hours, 0-23), across midnight when start is later; equal means never. */
	static boolean quiet(int hour, int start, int end)
	{
		if (start == end)
		{
			return false;
		}
		return start < end ? hour >= start && hour < end : hour >= start || hour < end;
	}

	/** Discord's Retry-After header is in seconds, possibly fractional; negative when missing or unreadable. */
	static long retryAfterMs(String header)
	{
		if (header == null)
		{
			return -1;
		}
		try
		{
			return (long) Math.ceil(Double.parseDouble(header.trim()) * 1000);
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.IntSupplier;
import java.util.function.LongSupplier;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Posts queued events to Discord, one at a time, off the client thread.
 *
 * <p>{@link #pump} is called on a timer; for each webhook URL it takes the next
 * post that URL's {@link DiscordQueue} allows and hands it to the {@link Transport}, which in
 * the client is RuneLite's injected {@link OkHttpClient} with
 * {@code enqueue}, so nothing blocks any thread of ours (AGENTS.md, HTTP).
 *
 * <p><b>The webhook URL is a secret</b>: anyone with it can post to the
 * channel. It is never logged, here or in the transport; a failure logs only
 * the status or the exception's class.
 */
@Slf4j
final class DiscordSender
{
	interface Transport
	{
		/** Sends the post and calls {@code done} once with the status (0 for a network failure) and Retry-After. */
		void send(DiscordQueue.Post post, Done done);
	}

	interface Done
	{
		/** {@code messageId}: the created message's id, read only when the post asked for it; else null. */
		void done(int status, String retryAfter, String messageId);

		default void done(int status, String retryAfter)
		{
			done(status, retryAfter, null);
		}
	}

	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final MediaType PNG = MediaType.parse("image/png");

	/**
	 * One queue per webhook URL: Discord rate-limits each webhook on its own, so a busy or 429'd Drops webhook
	 * never holds back the Deaths one, and each keeps its own order and per-minute cap.
	 */
	private final Map<String, DiscordQueue> queues = new ConcurrentHashMap<>();
	/** Replies whose outcome is being handed to the post's owner right now ({@link #queued}). */
	private final AtomicInteger settling = new AtomicInteger();
	private final Transport transport;
	private final LongSupplier clock;
	private final IntSupplier hour;
	private volatile int quietStart;
	private volatile int quietEnd;

	DiscordSender(Transport transport, LongSupplier clock, IntSupplier hour)
	{
		this.transport = transport;
		this.clock = clock;
		this.hour = hour;
	}

	void quietHours(int start, int end)
	{
		quietStart = start;
		quietEnd = end;
	}

	/** Queues a post. A null URL (none set, or not a Discord webhook) means no post and no network at all. */
	void post(String url, String json, byte[] png)
	{
		if (url == null || json == null)
		{
			return;
		}
		offer(new DiscordQueue.Post(url, json, png));
	}

	/** Queues a new post whose final outcome, and the created message's id, go to {@code result}. */
	void post(String url, String json, byte[] png, DiscordQueue.Result result)
	{
		if (url != null && json != null)
		{
			offer(new DiscordQueue.Post(url, json, png, null, result));
		}
	}

	/** Queues an in-place edit of {@code messageId}, sent by {@code url}'s webhook; the outcome goes to {@code result}. */
	void edit(String url, String messageId, String json, byte[] png, DiscordQueue.Result result)
	{
		if (url != null && json != null && messageId != null)
		{
			offer(new DiscordQueue.Post(url, json, png, messageId, result));
		}
	}

	/**
	 * Queues deleting {@code messageId}, sent by {@code url}'s webhook (Discord "Delete Webhook Message",
	 * {@code DELETE /webhooks/{id}/{token}/messages/{message.id}}: "Deletes a message that was created by the
	 * webhook. Returns a 204 No Content response on success"; discord/discord-api-docs main,
	 * developers/resources/webhook.mdx). The outcome goes to {@code result}.
	 */
	void delete(String url, String messageId, DiscordQueue.Result result)
	{
		if (url != null && messageId != null)
		{
			offer(DiscordQueue.Post.delete(url, messageId, result));
		}
	}

	/** A post a full queue pushed out is told so, outside the queue's lock: its owner may queue another. */
	private void offer(DiscordQueue.Post post)
	{
		DiscordQueue queue = queues.computeIfAbsent(post.url, u -> new DiscordQueue());
		for (DiscordQueue.Post dropped : queue.offer(post))
		{
			dropped.result.done(DiscordQueue.DROPPED, null);
		}
	}

	/** Sends each webhook's next post, where its queue allows one now. Any thread; called by the timer. */
	void pump()
	{
		long now = clock.getAsLong();
		boolean quiet = DiscordQueue.quiet(hour.getAsInt(), quietStart, quietEnd);
		for (DiscordQueue queue : queues.values())
		{
			DiscordQueue.Post post = queue.next(now, quiet);
			if (post != null)
			{
				send(queue, post);
			}
		}
	}

	private void send(DiscordQueue queue, DiscordQueue.Post post)
	{
		transport.send(post, (status, retryAfter, messageId) ->
		{
			if (status < 200 || status >= 300)
			{
				log.debug("discord webhook {} failed: {}", post.delete ? "delete" : post.edit == null ? "post" : "edit",
					status == 0 ? "network error" : "HTTP " + status);
			}
			// Counted in queued() from leaving the queue until its owner has heard the outcome, so nobody sees an
			// empty sender while a reply's message id is still on its way to its owner.
			settling.incrementAndGet();
			try
			{
				boolean again = queue.done(status, DiscordQueue.retryAfterMs(retryAfter), clock.getAsLong());
				if (!again && post.result != null)
				{
					post.result.done(status, messageId);
				}
			}
			finally
			{
				settling.decrementAndGet();
			}
		});
	}

	/**
	 * Where a post goes. A new post that wants its message id waits for it ({@code ?wait=true}); an edit goes to
	 * {@code /messages/<id>} under the webhook (Discord "Edit Webhook Message",
	 * {@code PATCH /webhooks/{id}/{token}/messages/{message.id}}). A query the webhook already has (a
	 * {@code thread_id}) is kept, after the path, and {@code wait} joins it rather than starting a second one.
	 */
	static String target(DiscordQueue.Post post)
	{
		if (post.edit == null && post.result == null)
		{
			return post.url;
		}
		int q = post.url.indexOf('?');
		String path = q < 0 ? post.url : post.url.substring(0, q);
		String query = q < 0 ? "" : post.url.substring(q + 1);
		if (path.endsWith("/"))
		{
			path = path.substring(0, path.length() - 1);
		}
		if (post.edit != null)
		{
			path += "/messages/" + post.edit;
		}
		else
		{
			query = query.isEmpty() ? "wait=true" : query + "&wait=true";
		}
		return query.isEmpty() ? path : path + "?" + query;
	}

	/** The message id in a {@code ?wait=true} reply's message object; null when there is none. */
	static String messageId(Gson gson, String body)
	{
		try
		{
			JsonElement reply = gson.fromJson(body, JsonElement.class);
			if (reply == null || !reply.isJsonObject())
			{
				return null;
			}
			JsonObject o = reply.getAsJsonObject();
			return o.has("id") && o.get("id").isJsonPrimitive() ? o.get("id").getAsString() : null;
		}
		catch (JsonParseException | IllegalStateException e)
		{
			return null;
		}
	}

	int queued()
	{
		return queues.values().stream().mapToInt(DiscordQueue::size).sum() + settling.get();
	}

	void clear()
	{
		queues.values().forEach(DiscordQueue::clear);
	}

	/** The HTTP request for {@code post}: a POST, a PATCH for an edit, a DELETE (no body) for a delete. */
	static Request request(DiscordQueue.Post post)
	{
		Request.Builder builder = new Request.Builder().url(target(post));
		if (post.delete)
		{
			return builder.delete().build();
		}
		RequestBody body;
		if (post.png == null)
		{
			body = RequestBody.create(JSON, post.json);
		}
		else
		{
			body = new MultipartBody.Builder().setType(MultipartBody.FORM)
				.addFormDataPart("payload_json", post.json)
				.addFormDataPart("files[0]", DiscordWebhook.SCREENSHOT, RequestBody.create(PNG, post.png))
				.build();
		}
		return (post.edit == null ? builder.post(body) : builder.patch(body)).build();
	}

	/** The client's transport: RuneLite's own OkHttpClient, asynchronous. */
	static Transport okHttp(OkHttpClient http, Gson gson)
	{
		return (post, done) ->
		{
			Request request = request(post);
			boolean wantsId = post.edit == null && post.result != null;
			http.newCall(request).enqueue(new Callback()
			{
				@Override
				public void onFailure(Call call, IOException e)
				{
					// The class only: some exceptions carry the URL in their message.
					log.debug("discord webhook unreachable: {}", e.getClass().getSimpleName());
					done.done(0, null);
				}

				@Override
				public void onResponse(Call call, Response response)
				{
					try (Response r = response)
					{
						done.done(r.code(), r.header("Retry-After"), wantsId ? id(r) : null);
					}
				}

				/** The posted message's id; null when unreadable (the post still went, so it is not retried). */
				private String id(Response r)
				{
					try
					{
						if (!r.isSuccessful())
						{
							return null;
						}
						String id = r.body() == null ? null : messageId(gson, r.body().string());
						if (id == null)
						{
							// No URL: the status and content type say enough. Without the id the streak cannot be
							// edited, so the skill's next level posts anew.
							log.debug("discord webhook reply has no message id: HTTP {} {}", r.code(),
								r.header("Content-Type"));
						}
						return id;
					}
					catch (IOException e)
					{
						log.debug("discord webhook reply unreadable: {}", e.getClass().getSimpleName());
						return null;
					}
				}
			});
		};
	}
}

package com.vinnyvangogh.groupironman;

/**
 * How a Discord post looks. Public, like every setting type: RuneLite reads
 * settings through a proxy that cannot see a package-private type, and the
 * client black-screens (ConfigKeysTest).
 */
public enum DiscordStyle
{
	EMBED("Rich embed"),
	PLAIN("Plain text");

	private final String label;

	DiscordStyle(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.time.Instant;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * What a Discord webhook post says, and where it goes. Pure: building the
 * JSON needs no network, so its shape is tested.
 *
 * <p>Payload fields follow Discord's "Execute Webhook" endpoint
 * ({@code content}, {@code username}, {@code embeds}, {@code allowed_mentions};
 * a file goes in a multipart form beside {@code payload_json}). Item icons are
 * RuneLite's static item cache, the URL Dink uses
 * ({@code https://static.runelite.net/cache/item/icon/<id>.png},
 * pajlads/DinkPlugin {@code ItemUtils.ITEM_CACHE_BASE_URL}), at the stack's own
 * pile ({@link StackIcons}). Amounts read "450K (450,001)" ({@link Amounts#BOTH}).
 */
final class DiscordWebhook
{
	/** The third-party-server warning AGENTS.md asks for on a setting that sends anything off the client. */
	static final String WARNING = "This feature submits your IP address to a 3rd-party server not controlled or"
		+ " verified by RuneLite developers";
	static final String USERNAME = "GIM Utilities";
	static final String SCREENSHOT = "screenshot.png";
	/** Discord refuses {@code content} over 2,000 characters; lines past this wait out the day and are dropped. */
	static final int MAX_DIGEST = 1_900;
	private static final String ICON = "https://static.runelite.net/cache/item/icon/%d.png";
	/** discord.com (and the old discordapp.com, and the ptb/canary clients' hosts), /api/webhooks/id/token. */
	private static final Pattern URL = Pattern.compile(
		"^https://(?:(?:ptb|canary)\\.)?discord(?:app)?\\.com/api/webhooks/\\d+/[A-Za-z0-9_-]+/?$");

	/** Quotes a pasted link may come wrapped in: straight, backtick and curly. */
	private static final String QUOTES = "\"'`“”‘’";

	private DiscordWebhook()
	{
	}

	static boolean valid(String url)
	{
		return URL.matcher(clean(url)).matches();
	}

	/**
	 * The field as typed, without surrounding whitespace or quotes: a link
	 * pasted with its quotes, straight or curly, is the common mistake. Empty
	 * for null.
	 */
	static String clean(String url)
	{
		String s = url == null ? "" : url.trim();
		while (s.length() >= 2 && QUOTES.indexOf(s.charAt(0)) >= 0 && QUOTES.indexOf(s.charAt(s.length() - 1)) >= 0)
		{
			s = s.substring(1, s.length() - 1).trim();
		}
		return s;
	}

	/** Sets {@code allowed_mentions}: role and user pings only when {@code ping}, otherwise nobody. */
	static void allowMentions(JsonObject o, boolean ping)
	{
		JsonObject allowed = new JsonObject();
		JsonArray parse = new JsonArray();
		if (ping)
		{
			parse.add("roles");
			parse.add("users");
		}
		allowed.add("parse", parse);
		o.add("allowed_mentions", allowed);
	}

	/** {@link #digest(Gson, GroupEvent.Category, List, String)} under today's name, "GIM Utilities". */
	static String digest(Gson gson, GroupEvent.Category category, List<String> lines)
	{
		return digest(gson, category, lines, USERNAME);
	}

	/**
	 * One day's held lines for a category as a plain post; null when there are none. Mentions nobody.
	 * {@code username} null sends none, so the webhook's own name shows ({@link PosterNames}).
	 */
	static String digest(Gson gson, GroupEvent.Category category, List<String> lines, String username)
	{
		if (lines.isEmpty())
		{
			return null;
		}
		StringBuilder text = new StringBuilder("Daily digest, ").append(category.name().toLowerCase(Locale.ROOT));
		for (String line : lines)
		{
			if (text.length() + line.length() + 1 > MAX_DIGEST)
			{
				break;
			}
			text.append('\n').append(line);
		}
		JsonObject o = poster(username);
		o.addProperty("content", text.toString());
		allowMentions(o, false);
		return gson.toJson(o);
	}

	/** One event's post text; see {@link #words(DiscordMerge.Post, String)}. */
	static String words(GroupEvent e, ItemLookup lookup, String egg)
	{
		return words(DiscordMerge.single(e, lookup), egg);
	}

	/**
	 * What the post's description says: the lead's line, then the Easter egg under it. A death that cost 0 gp has
	 * no value line, so it says only the egg, or is null (nothing to post) when there is no egg.
	 */
	static String words(DiscordMerge.Post post, String egg)
	{
		String extra = egg == null || egg.trim().isEmpty() ? null : egg.trim();
		if (EasterEggs.nothingLost(post.lead))
		{
			return extra;
		}
		return extra == null ? post.description : post.description + "\n" + extra;
	}

	/** The JSON body ({@code payload_json} when a screenshot is attached), without an Easter egg. */
	static String payload(Gson gson, GroupEvent e, ItemLookup items, DiscordStyle style, String mention,
		boolean screenshot)
	{
		return payload(gson, e, items, style, mention, screenshot, null);
	}

	/** One event's post; null when there is nothing to post. */
	static String payload(Gson gson, GroupEvent e, ItemLookup items, DiscordStyle style, String mention,
		boolean screenshot, String egg)
	{
		// "450K (450,001)": the game's words, and nothing lost (Board 2026-11-10).
		ItemLookup lookup = Amounts.BOTH.words(items);
		return payload(gson, DiscordMerge.single(e, lookup), lookup, style, mention, screenshot, egg);
	}

	static String payload(Gson gson, DiscordMerge.Post post, ItemLookup lookup, DiscordStyle style, String mention,
		boolean screenshot)
	{
		return payload(gson, post, lookup, style, mention, screenshot, null);
	}

	/**
	 * One moment's post: its lead event's title and line, the other events' lines as fields, and the Easter egg
	 * under the line. {@code lookup} already words amounts the Discord way ({@link Amounts#BOTH}), as the post's
	 * text was built with it. Null when there is nothing to post.
	 */
	static String payload(Gson gson, DiscordMerge.Post post, ItemLookup lookup, DiscordStyle style, String mention,
		boolean screenshot, String egg)
	{
		return payload(gson, post, lookup, style, mention, screenshot, egg, USERNAME);
	}

	/**
	 * {@link #payload(Gson, DiscordMerge.Post, ItemLookup, DiscordStyle, String, boolean, String)} under
	 * {@code username}; null sends none, so Discord shows the webhook's own name and avatar ({@link PosterNames}).
	 * The footer says "GIM Utilities" whatever the name.
	 */
	static String payload(Gson gson, DiscordMerge.Post post, ItemLookup lookup, DiscordStyle style, String mention,
		boolean screenshot, String egg, String username)
	{
		String words = words(post, egg);
		if (words == null)
		{
			return null;
		}
		JsonObject o = poster(username);
		String tag = post.big && mention != null && !mention.trim().isEmpty() ? mention.trim() : "";
		// Only the configured mention may ping; a member or item name can never.
		allowMentions(o, !tag.isEmpty());
		if (style == DiscordStyle.PLAIN)
		{
			o.addProperty("content", (tag.isEmpty() ? "" : tag + " ") + plain(post, words));
			return gson.toJson(o);
		}
		if (!tag.isEmpty())
		{
			o.addProperty("content", tag);
		}
		JsonArray embeds = new JsonArray();
		embeds.add(embed(post, words, lookup, screenshot));
		o.add("embeds", embeds);
		return gson.toJson(o);
	}

	/**
	 * A member's level message as a new post under {@code username} (null for the webhook's own,
	 * {@link PosterNames}): one embed card per skill, the most recently levelled first, the picture on the top card
	 * (Board 2026-11-14). Plain style says one line per card. It never mentions anyone.
	 */
	static String levels(Gson gson, String member, List<LevelThreads.Card> cards, DiscordStyle style,
		boolean screenshot, String username)
	{
		JsonObject o = poster(username);
		allowMentions(o, false);
		if (style == DiscordStyle.PLAIN)
		{
			StringBuilder text = new StringBuilder();
			for (LevelThreads.Card c : cards)
			{
				text.append(text.length() == 0 ? "" : "\n").append(member).append(": ").append(c.text());
				if (c.broadcast)
				{
					text.append(" (").append(GroupBroadcasts.SOURCE).append(')');
				}
			}
			o.addProperty("content", text.toString());
			return gson.toJson(o);
		}
		JsonArray embeds = new JsonArray();
		for (LevelThreads.Card c : cards)
		{
			embeds.add(card(member, c, screenshot && embeds.size() == 0));
		}
		o.add("embeds", embeds);
		return gson.toJson(o);
	}

	/** One skill's card in a level message: "Alex: Level up", "Thieving 44 → 46 (+2) in 10 min". */
	private static JsonObject card(String member, LevelThreads.Card c, boolean screenshot)
	{
		GroupEvent.Type type = c.combat() ? GroupEvent.Type.COMBAT_LEVEL : GroupEvent.Type.LEVEL_UP;
		JsonObject embed = new JsonObject();
		embed.addProperty("title", member + ": " + EventText.title(type));
		embed.addProperty("description", c.text());
		embed.addProperty("color", type.category.colour);
		embed.addProperty("timestamp", Instant.ofEpochMilli(c.lastAt).toString());
		if (screenshot)
		{
			JsonObject image = new JsonObject();
			image.addProperty("url", "attachment://" + SCREENSHOT);
			embed.add("image", image);
		}
		JsonObject footer = new JsonObject();
		footer.addProperty("text", c.broadcast ? USERNAME + " · " + GroupBroadcasts.SOURCE : USERNAME);
		embed.add("footer", footer);
		return embed;
	}

	/**
	 * The same, as an edit of the member's message (Discord "Edit Webhook Message"): no {@code username}, which
	 * that endpoint does not take. A new screenshot replaces the old one: files sent with an edit are appended
	 * unless {@code attachments} lists every file the message keeps, here only the new upload.
	 */
	static String levelsEdit(Gson gson, String member, List<LevelThreads.Card> cards, DiscordStyle style,
		boolean screenshot)
	{
		return asEdit(gson, gson.fromJson(levels(gson, member, cards, style, screenshot, null), JsonObject.class),
			screenshot);
	}

	/**
	 * A post's body made an edit's (Discord "Edit Webhook Message"): no {@code username}, which that endpoint does not
	 * take, and with a screenshot the {@code attachments} list naming only the new upload, so it replaces the old one
	 * instead of being appended.
	 */
	static String asEdit(Gson gson, JsonObject o, boolean screenshot)
	{
		o.remove("username");
		if (screenshot)
		{
			JsonObject upload = new JsonObject();
			upload.addProperty("id", 0);
			upload.addProperty("filename", SCREENSHOT);
			JsonArray attachments = new JsonArray();
			attachments.add(upload);
			o.add("attachments", attachments);
		}
		return gson.toJson(o);
	}

	/**
	 * A member's grouped message ({@link EventThreads}) as a new post under {@code username}: one card per moment,
	 * newest first, at most {@link EditedThreads#MAX_CARDS}, the picture on the top card only (Board 2026-11-15: the
	 * newest event's). Plain style says one line per card, newest first, within Discord's 2,000 characters. It never
	 * mentions anyone: a moment that pings starts its own message.
	 */
	static JsonObject stack(Gson gson, List<EventThreads.Card> cards, DiscordStyle style, boolean screenshot,
		String username)
	{
		JsonObject o = poster(username);
		allowMentions(o, false);
		if (style == DiscordStyle.PLAIN)
		{
			StringBuilder text = new StringBuilder();
			for (EventThreads.Card c : cards)
			{
				if (c.line == null || text.length() + c.line.length() + 1 > MAX_DIGEST)
				{
					break;
				}
				text.append(text.length() == 0 ? "" : "\n").append(c.line);
			}
			o.addProperty("content", text.toString());
			return o;
		}
		JsonArray embeds = new JsonArray();
		for (EventThreads.Card c : cards)
		{
			if (c.embed == null || embeds.size() >= EditedThreads.MAX_CARDS)
			{
				continue;
			}
			JsonObject embed = gson.fromJson(c.embed, JsonObject.class);
			embed.remove("image");
			if (screenshot && embeds.size() == 0)
			{
				JsonObject image = new JsonObject();
				image.addProperty("url", "attachment://" + SCREENSHOT);
				embed.add("image", image);
			}
			embeds.add(embed);
		}
		o.add("embeds", embeds);
		return o;
	}

	/** The first embed of a post's body, as JSON; null for a plain post. */
	static String firstEmbed(Gson gson, String json)
	{
		JsonObject o = json == null ? null : gson.fromJson(json, JsonObject.class);
		JsonArray embeds = o == null || !o.has("embeds") ? null : o.getAsJsonArray("embeds");
		return embeds == null || embeds.size() == 0 ? null : gson.toJson(embeds.get(0));
	}

	/** A post's {@code content}; null when it has none. */
	static String content(Gson gson, String json)
	{
		JsonObject o = json == null ? null : gson.fromJson(json, JsonObject.class);
		return o == null || !o.has("content") ? null : o.get("content").getAsString();
	}

	/** A post's body, with the {@code username} key only when there is a name to send. */
	private static JsonObject poster(String username)
	{
		JsonObject o = new JsonObject();
		if (username != null)
		{
			o.addProperty("username", username);
		}
		return o;
	}

	/** "Alex: died; lost about 1.5M gp on death": the lead's sentence, each merged fact, then the egg's line. */
	private static String plain(DiscordMerge.Post post, String words)
	{
		int egg = words.indexOf('\n');
		StringBuilder text = new StringBuilder(post.lead.member).append(": ")
			.append(egg < 0 ? words : words.substring(0, egg));
		for (String[] extra : post.extras)
		{
			text.append("; ").append(extra[1]);
		}
		if (post.lead.broadcast)
		{
			text.append(" (").append(GroupBroadcasts.SOURCE).append(')');
		}
		return egg < 0 ? text.toString() : text.append(words.substring(egg)).toString();
	}

	private static JsonObject embed(DiscordMerge.Post post, String words, ItemLookup lookup, boolean screenshot)
	{
		GroupEvent e = post.lead;
		JsonObject embed = new JsonObject();
		embed.addProperty("title", e.member + ": " + post.title);
		embed.addProperty("description", words);
		embed.addProperty("color", e.type.category.colour);
		embed.addProperty("timestamp", Instant.ofEpochMilli(e.at).toString());
		JsonArray fields = fields(post, lookup);
		if (fields.size() > 0)
		{
			embed.add("fields", fields);
		}
		Integer icon = post.items.isEmpty() ? null : mostValuable(post.items, lookup);
		if (icon != null)
		{
			JsonObject thumb = new JsonObject();
			thumb.addProperty("url", String.format(ICON, StackIcons.variant(icon, post.items.get(icon))));
			embed.add("thumbnail", thumb);
		}
		if (screenshot)
		{
			JsonObject image = new JsonObject();
			image.addProperty("url", "attachment://" + SCREENSHOT);
			embed.add("image", image);
		}
		JsonObject footer = new JsonObject();
		footer.addProperty("text", e.broadcast ? USERNAME + " · " + GroupBroadcasts.SOURCE : USERNAME);
		embed.add("footer", footer);
		return embed;
	}

	/** Value, World and Where (inline), then one full-width field per merged fact. */
	private static JsonArray fields(DiscordMerge.Post post, ItemLookup lookup)
	{
		GroupEvent e = post.lead;
		JsonArray fields = new JsonArray();
		String value = DiscordMerge.valueText(post, lookup);
		if (!value.isEmpty())
		{
			fields.add(field("Value", value, true));
		}
		if (e.world > 0)
		{
			fields.add(field("World", Integer.toString(e.world), true));
		}
		if (!e.location.isEmpty())
		{
			fields.add(field("Where", e.location, true));
		}
		for (String[] extra : post.extras)
		{
			fields.add(field(extra[0], extra[1], false));
		}
		return fields;
	}

	private static JsonObject field(String name, String value, boolean inline)
	{
		JsonObject f = new JsonObject();
		f.addProperty("name", name);
		f.addProperty("value", value);
		f.addProperty("inline", inline);
		return f;
	}

	private static Integer mostValuable(Map<Integer, Integer> items, ItemLookup lookup)
	{
		Integer best = null;
		long bestValue = -1;
		for (Map.Entry<Integer, Integer> i : items.entrySet())
		{
			long v = lookup.price(i.getKey()) * i.getValue();
			if (v > bestValue)
			{
				best = i.getKey();
				bestValue = v;
			}
		}
		return best;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.function.LongSupplier;

/**
 * A log of group events, newest first, without duplicates. As the drops log
 * it holds every member's drops and new collection log slots, the newest
 * {@link #MAX_ENTRIES}, and is what each client resends. The Log tab's feed
 * of every event is one too, with {@link ActivityLog}'s bounds.
 *
 * <p>There is no server to hold events for a member who is offline. Instead
 * each client keeps its own events for {@link #RESEND_WINDOW_MS} and resends
 * them whenever someone joins the party, so a member who logs in later still
 * gets them as long as the other member is online at some point after. Resends
 * are recognised with {@link GroupEvent#sameAs} and logged once.
 */
final class DropLog
{
	static final int MAX_ENTRIES = 300;
	static final int MAX_RESEND = 50;
	static final long RESEND_WINDOW_MS = TimeUnit.DAYS.toMillis(7);

	private final LinkedList<GroupEvent> entries = new LinkedList<>();
	private final int maxEntries;
	/** Oldest an entry may be, against {@link #clock}; {@link Long#MAX_VALUE} for no age limit. */
	private final long maxAgeMs;
	private final LongSupplier clock;

	/** The drops log: the newest {@link #MAX_ENTRIES}, any age. */
	DropLog()
	{
		this(MAX_ENTRIES, Long.MAX_VALUE, System::currentTimeMillis);
	}

	/** A log of the newest {@code maxEntries} no older than {@code maxAgeMs}, whichever keeps fewer. */
	DropLog(int maxEntries, long maxAgeMs, LongSupplier clock)
	{
		this.maxEntries = maxEntries;
		this.maxAgeMs = maxAgeMs;
		this.clock = clock;
	}

	/** Adds an event in time order. Invalid, too old and duplicate events are dropped. */
	synchronized boolean add(GroupEvent event)
	{
		long now = clock.getAsLong();
		if (!event.isValid() || event.member.isEmpty() || tooOld(event, now))
		{
			return false;
		}
		int index = insertionIndex(event);
		if (index < 0)
		{
			return false;
		}
		entries.add(index, event);
		while (entries.size() > maxEntries || tooOld(entries.getLast(), now))
		{
			entries.removeLast();
		}
		return true;
	}

	/** Where {@code event} goes, newest first; -1 when it is already here. */
	private int insertionIndex(GroupEvent event)
	{
		// Newest first, so every entry at the same time or later is passed, and checked, before the insertion point.
		int index = 0;
		for (GroupEvent e : entries)
		{
			if (e.at < event.at)
			{
				break;
			}
			if (e.sameAs(event))
			{
				return -1;
			}
			index++;
		}
		return index;
	}

	private boolean tooOld(GroupEvent event, long now)
	{
		return maxAgeMs != Long.MAX_VALUE && now - event.at > maxAgeMs;
	}

	synchronized List<GroupEvent> entries()
	{
		return new ArrayList<>(entries);
	}

	synchronized void clear()
	{
		entries.clear();
	}

	/** Events after {@code since}, newest first, leaving out {@code self}'s own. */
	List<GroupEvent> since(long since, String self)
	{
		List<GroupEvent> out = new ArrayList<>();
		for (GroupEvent e : entries())
		{
			if (e.at <= since)
			{
				break;
			}
			if (self == null || !e.member.equalsIgnoreCase(self))
			{
				out.add(e);
			}
		}
		return out;
	}

	/** {@code member}'s own events from the resend window, newest first, at most {@link #MAX_RESEND}. */
	List<GroupEvent> recentBy(String member, long now)
	{
		List<GroupEvent> out = new ArrayList<>();
		for (GroupEvent e : entries())
		{
			if (out.size() >= MAX_RESEND || now - e.at > RESEND_WINDOW_MS)
			{
				break;
			}
			if (e.member.equalsIgnoreCase(member))
			{
				out.add(e);
			}
		}
		return out;
	}

	/** "Alex: Vorkath dropped 1 x Draconic visage (2h ago)". */
	static List<String> lines(List<GroupEvent> events, ItemLookup items, long now)
	{
		List<String> out = new ArrayList<>();
		for (GroupEvent e : events)
		{
			out.add(e.member + ": " + e.describe(items) + " (" + BoostText.ago(now, e.at) + ")");
		}
		return out;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

/**
 * Kills of a boss since its last unique, and the call-out each time the
 * streak reaches another multiple of the drop rate. Pure; saved per account.
 *
 * <p>Rates are the combined chance of any listed unique, read from the OSRS
 * wiki on 2026-11-09:
 * <a href="https://oldschool.runescape.wiki/w/Vorkath">Vorkath</a> (visages
 * 1/5,000 each, necklace 1/1,000, so 7/5,000, about 1/714) and
 * <a href="https://oldschool.runescape.wiki/w/Zulrah">Zulrah</a> (two rolls
 * at 1/1,024 for each of four items, so 8/1,024, 1/128). A boss not listed is
 * not tracked.
 */
final class DryStreak
{
	static final class Rate
	{
		final int oneIn;
		final Set<String> uniques;

		Rate(int oneIn, String... uniques)
		{
			this.oneIn = oneIn;
			Set<String> names = new HashSet<>();
			for (String u : Arrays.asList(uniques))
			{
				names.add(u.toLowerCase(Locale.ROOT));
			}
			this.uniques = Collections.unmodifiableSet(names);
		}
	}

	static final Map<String, Rate> RATES = new TreeMap<>();

	static
	{
		RATES.put("vorkath", new Rate(714, "Draconic visage", "Skeletal visage", "Dragonbone necklace"));
		RATES.put("zulrah", new Rate(128, "Tanzanite fang", "Magic fang", "Serpentine visage", "Uncut onyx"));
	}

	/**
	 * How far apart a kill's count line and its loot may land, in either order.
	 * The real order is not confirmed in game, so neither is assumed. Same
	 * allowance as {@link GroupEventEngine#KC_WINDOW_MS}.
	 */
	static final long HOLD_MS = 10_000L;

	private final Map<String, Integer> kills = new TreeMap<>();
	private final Map<String, GroupEvent> held = new TreeMap<>();
	private final Map<String, Long> lastKillAt = new TreeMap<>();
	private final Map<String, Long> uniqueAt = new TreeMap<>();

	private DryStreak()
	{
	}

	private static String key(String boss)
	{
		return boss == null ? "" : boss.trim().toLowerCase(Locale.ROOT);
	}

	/** One kill. A call-out it earns waits in {@link #due} until the kill's loot has had time to arrive. */
	void kill(String boss, long now, String member)
	{
		String key = key(boss);
		Rate rate = RATES.get(key);
		if (rate == null)
		{
			return;
		}
		Long unique = uniqueAt.remove(key);
		if (unique != null && now - unique <= HOLD_MS)
		{
			// This kill's unique arrived first and already ended the streak.
			return;
		}
		lastKillAt.put(key, now);
		int count = kills.merge(key, 1, Integer::sum);
		if (count % rate.oneIn == 0)
		{
			held.put(key, GroupEvent.of(GroupEvent.Type.DRY_STREAK, now, member).text(boss.trim()).number(count)
				.detail("unique rate about 1/" + rate.oneIn).build());
		}
	}

	/** A drop from {@code boss}: any listed unique among {@code itemNames} ends the streak. */
	void drop(String boss, Set<String> itemNames, long now)
	{
		String key = key(boss);
		Rate rate = RATES.get(key);
		if (rate == null)
		{
			return;
		}
		for (String name : itemNames)
		{
			if (rate.uniques.contains(name.toLowerCase(Locale.ROOT)))
			{
				kills.remove(key);
				held.remove(key);
				Long last = lastKillAt.get(key);
				if (last == null || now - last > HOLD_MS)
				{
					uniqueAt.put(key, now);
				}
				return;
			}
		}
	}

	/** Call-outs whose kill is older than {@link #HOLD_MS}: no unique can still cancel them. */
	List<GroupEvent> due(long now)
	{
		if (held.isEmpty())
		{
			return Collections.emptyList();
		}
		List<GroupEvent> out = new ArrayList<>();
		for (Iterator<Map.Entry<String, GroupEvent>> it = held.entrySet().iterator(); it.hasNext(); )
		{
			Map.Entry<String, GroupEvent> e = it.next();
			if (now - lastKillAt.get(e.getKey()) > HOLD_MS)
			{
				out.add(e.getValue());
				it.remove();
			}
		}
		return out;
	}

	int kills(String boss)
	{
		return kills.getOrDefault(key(boss), 0);
	}

	String save()
	{
		StringBuilder out = new StringBuilder();
		for (Map.Entry<String, Integer> e : kills.entrySet())
		{
			out.append(e.getKey()).append('=').append(e.getValue()).append(';');
		}
		return out.toString();
	}

	static DryStreak parse(String saved)
	{
		DryStreak out = new DryStreak();
		for (String part : (saved == null ? "" : saved).split(";"))
		{
			String[] kv = part.split("=");
			if (kv.length != 2 || !RATES.containsKey(kv[0]))
			{
				continue;
			}
			try
			{
				out.kills.put(kv[0], Math.max(0, Integer.parseInt(kv[1])));
			}
			catch (NumberFormatException e)
			{
				// Saved text from a newer or damaged profile: that boss starts over.
				out.kills.remove(kv[0]);
			}
		}
		return out;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Every Easter egg line, read once from {@code easter-eggs.txt} beside this class so they are easy to edit.
 * {@link EasterEggs} decides when one applies and picks a phrasing; a new phrasing is one more line in the file,
 * a new item one more line under its id. A missing file leaves every egg empty, so none is posted.
 *
 * <p>These post into shared Discord servers and go through Plugin Hub review: keep them light. No self-harm or
 * suicide wording, nothing aimed at a person. {@code EasterEggsTest} checks the length and a list of banned words.
 */
final class EasterEggLines
{
	/** Every line of the file by its name, both in file order: {@code NAME=line}, one phrasing per line. */
	private static final Map<String, List<String>> FILE = new LinkedHashMap<>();

	static
	{
		for (String line : RegionNames.resource("easter-eggs.txt").split("\n"))
		{
			int eq = line.indexOf('=');
			if (eq > 0 && !line.startsWith("#"))
			{
				FILE.computeIfAbsent(line.substring(0, eq).trim(), k -> new ArrayList<>()).add(line.substring(eq + 1).trim());
			}
		}
	}

	/** A death that cost 0 gp. */
	static final String[] FREE_TRIP = lines("FREE_TRIP");
	/** A death where all that was lost is a spade, maybe with clue items. */
	static final String[] CLUE_HUNTERS = lines("CLUE_HUNTERS");
	static final String[] PET = lines("PET");
	/** A level up to 73 in any skill: the B0aty 73 meme. */
	static final String[] LEVEL_73 = lines("LEVEL_73");
	/** A level up to 92: 92 is halfway to 99 in XP. */
	static final String[] LEVEL_92 = lines("LEVEL_92");
	/** A level up to 67 in any skill, or combat level 67: the "six seven" meme. Any emoji goes last. */
	static final String[] LEVEL_67 = lines("LEVEL_67");
	/** A level up to 69 in any skill, or combat level 69. Any emoji goes last. */
	static final String[] LEVEL_69 = lines("LEVEL_69");
	/** A 99 in one skill. */
	static final String[] SKILL_99 = lines("SKILL_99");
	/** Maxed: every skill at 99. */
	static final String[] MAXED_TOTAL = lines("MAXED_TOTAL");
	/** Combat level 126, the highest there is. */
	static final String[] COMBAT_126 = lines("COMBAT_126");
	/** Total level 2000. */
	static final String[] TOTAL_2000 = lines("TOTAL_2000");
	/** 200M XP in a skill, the most it can hold. */
	static final String[] XP_200M = lines("XP_200M");
	/** Quest completions, keyed by the quest name as posted. */
	static final String[] COOKS_ASSISTANT = lines("COOKS_ASSISTANT");
	static final String[] DRAGON_SLAYER = lines("DRAGON_SLAYER");
	static final String[] RECIPE_FOR_DISASTER = lines("RECIPE_FOR_DISASTER");
	/** A death to TzTok-Jad. */
	static final String[] JAD = lines("JAD");
	/** A dry streak post: the "sit" meme, kindly. */
	static final String[] SIT = lines("SIT");
	/** A gold ring put in group storage: "buying gf". */
	static final String[] BUYING_GF = lines("BUYING_GF");
	/** A "valuable" drop that is only Bones: the drop threshold is set very low. */
	static final String[] BONES_ONLY = lines("BONES_ONLY");
	/** A group storage deposit worth at least the 'Legend at' value. */
	static final String[] LEGEND = lines("LEGEND");
	/** A group storage withdrawal worth at least the 'Freeloader at' value. */
	static final String[] FREELOADER = lines("FREELOADER");

	// Item ids, as on the OSRS Wiki item infobox and static.runelite.net/cache/item/icon/<id>.png.
	static final int SPADE = 952;
	static final int BONES = 526;
	static final int TWISTED_BOW = 20997;
	static final int GOLD_RING = 1635;

	/** Drops by item id, the file's numbered lines, first row wins when a drop has several. */
	static final Map<Integer, String[]> ITEMS;

	static
	{
		Map<Integer, String[]> items = new LinkedHashMap<>();
		FILE.forEach((name, lines) ->
		{
			if (name.matches("\\d{1,9}"))
			{
				items.put(Integer.parseInt(name), lines.toArray(new String[0]));
			}
		});
		ITEMS = Collections.unmodifiableMap(items);
	}

	private EasterEggLines()
	{
	}

	/** The phrasings named {@code name}; none when the file lacks it. */
	private static String[] lines(String name)
	{
		return FILE.getOrDefault(name, Collections.emptyList()).toArray(new String[0]);
	}

	/** Every line, for the test that keeps them short and kind. */
	static List<String> all()
	{
		List<String> out = new ArrayList<>();
		FILE.values().forEach(out::addAll);
		return out;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * The optional funny line under a Discord post. Pure and table-driven: {@link #RULES} is checked in order and the
 * first rule with lines wins; the words live in {@link EasterEggLines}. The line is extra, never a replacement:
 * the post keeps every fact it had.
 *
 * <p>The phrasing is picked by {@link #pick}, a fixed hash of a seed taken from the event, so the same event always
 * gets the same line on every client and a test with a fixed seed is stable.
 */
final class EasterEggs
{
	/** One rule: the lines it offers for this event, or null when it does not apply. */
	interface Rule
	{
		String[] lines(GroupEvent e, ItemLookup lookup, Settings settings);
	}

	/** The Discord section's Easter egg settings. A threshold of 0 turns that egg off. */
	static final class Settings
	{
		final boolean on;
		final long legendAt;
		final long freeloaderAt;

		Settings(boolean on, long legendAt, long freeloaderAt)
		{
			this.on = on;
			this.legendAt = legendAt;
			this.freeloaderAt = freeloaderAt;
		}

		/** The group's Easter egg settings when it has them, else this member's own. */
		static Settings of(GroupSettingsSchema.Resolved values)
		{
			return new Settings(values.on("discordEasterEggs"), values.value("discordLegendAt"),
				values.value("discordFreeloaderAt"));
		}
	}

	/** Lost alongside a spade, these still make it a clue hunter's death. Matched on the item name's start. */
	private static final List<String> CLUE_ITEMS = Arrays.asList("clue ", "scroll box", "challenge scroll",
		"casket");
	/** Event types whose items are a drop the item table reads by id. */
	private static final Set<GroupEvent.Type> DROPS = Collections.unmodifiableSet(EnumSet.of(GroupEvent.Type.DROP,
		GroupEvent.Type.UNIQUE, GroupEvent.Type.CLUE, GroupEvent.Type.BARROWS));
	/** Event types that carry the item only as its name. */
	private static final Set<GroupEvent.Type> NAMED = Collections.unmodifiableSet(EnumSet.of(
		GroupEvent.Type.RAID_UNIQUE, GroupEvent.Type.CLOG));
	/** Event types whose number is a level a {@link #LEVEL_NUMBERS} egg reads: one skill's, or the combat level. */
	private static final Set<GroupEvent.Type> LEVELS = Collections.unmodifiableSet(EnumSet.of(
		GroupEvent.Type.LEVEL_UP, GroupEvent.Type.COMBAT_LEVEL));
	/**
	 * Levels with an egg in any skill and on the combat level, also tagged in game ({@link #overlayTag}). Total
	 * level has none: it posts only at multiples of {@link ProgressTracker#TOTAL_STEP}, so it never ends in 67.
	 */
	private static final Map<Long, String[]> LEVEL_NUMBERS;

	static
	{
		Map<Long, String[]> levels = new HashMap<>();
		levels.put(67L, EasterEggLines.LEVEL_67);
		levels.put(69L, EasterEggLines.LEVEL_69);
		LEVEL_NUMBERS = Collections.unmodifiableMap(levels);
	}

	/**
	 * Checked in order; the first that applies wins. Deaths are first so a spade outranks a free trip. The memes
	 * each key on one event type, so their order only matters where noted: the total-level "maxed" post comes
	 * before the one-skill 99, and the gold ring comes after Legend so a big deposit stays legendary.
	 */
	private static final List<Rule> RULES = Collections.unmodifiableList(Arrays.<Rule>asList(
		(e, l, s) -> clueDeath(e, l) ? EasterEggLines.CLUE_HUNTERS : null,
		(e, l, s) -> nothingLost(e) ? EasterEggLines.FREE_TRIP : null,
		(e, l, s) -> e.type == GroupEvent.Type.PET ? EasterEggLines.PET : null,
		at(GroupEvent.Type.LEVEL_UP, 73, EasterEggLines.LEVEL_73),
		at(GroupEvent.Type.LEVEL_UP, 92, EasterEggLines.LEVEL_92),
		(e, l, s) -> levelNumber(e),
		named(GroupEvent.Type.MAXED, "total", EasterEggLines.MAXED_TOTAL),
		(e, l, s) -> e.type == GroupEvent.Type.MAXED ? EasterEggLines.SKILL_99 : null,
		at(GroupEvent.Type.COMBAT_LEVEL, 126, EasterEggLines.COMBAT_126),
		at(GroupEvent.Type.TOTAL_LEVEL, 2000, EasterEggLines.TOTAL_2000),
		at(GroupEvent.Type.XP_MILESTONE, 200_000_000L, EasterEggLines.XP_200M),
		named(GroupEvent.Type.QUEST, "Cook's Assistant", EasterEggLines.COOKS_ASSISTANT),
		named(GroupEvent.Type.QUEST, "Dragon Slayer I", EasterEggLines.DRAGON_SLAYER),
		named(GroupEvent.Type.QUEST, "Recipe for Disaster", EasterEggLines.RECIPE_FOR_DISASTER),
		named(GroupEvent.Type.DEATH, "TzTok-Jad", EasterEggLines.JAD),
		(e, l, s) -> e.type == GroupEvent.Type.DRY_STREAK ? EasterEggLines.SIT : null,
		(e, l, s) -> bonesOnly(e) ? EasterEggLines.BONES_ONLY : null,
		EasterEggs::itemRow,
		(e, l, s) -> freeloader(e, l, s) ? EasterEggLines.FREELOADER : null,
		(e, l, s) -> legend(e, l, s) ? EasterEggLines.LEGEND : null,
		(e, l, s) -> deposited(e).containsKey(EasterEggLines.GOLD_RING) ? EasterEggLines.BUYING_GF : null));

	private EasterEggs()
	{
	}

	/** This type of event at exactly this number: a level, a total, an XP milestone. */
	private static Rule at(GroupEvent.Type type, long number, String[] lines)
	{
		return (e, l, s) -> e.type == type && e.number == number ? lines : null;
	}

	/** This type of event with this text, any case: a quest name, a killer, "total". */
	private static Rule named(GroupEvent.Type type, String text, String[] lines)
	{
		return (e, l, s) -> e.type == type && text.equalsIgnoreCase(e.text) ? lines : null;
	}

	/** The egg for one Discord post's events (a merged moment): the first event with one wins. */
	static String line(List<GroupEvent> events, ItemLookup lookup, Settings settings)
	{
		for (GroupEvent e : events)
		{
			String line = line(e, lookup, settings);
			if (line != null)
			{
				return line;
			}
		}
		return null;
	}

	/** The egg for this event, or null: the toggle is off or no rule applies. */
	static String line(GroupEvent e, ItemLookup lookup, Settings settings)
	{
		return line(e, lookup, settings, seed(e));
	}

	static String line(GroupEvent e, ItemLookup lookup, Settings settings, long seed)
	{
		if (!settings.on)
		{
			return null;
		}
		for (Rule rule : RULES)
		{
			String[] lines = rule.lines(e, lookup, settings);
			if (lines != null && lines.length > 0)
			{
				return lines[pick(seed, lines.length)];
			}
		}
		return null;
	}

	/**
	 * The tag for this event's line in the group box and banners, or null: only the level-number eggs (67, 69) show
	 * in game. The same phrasing as the Discord post, picked from the same seed, with any emoji cut off: the game
	 * font has none.
	 */
	static String overlayTag(GroupEvent e, Settings settings)
	{
		String[] lines = settings.on ? levelNumber(e) : null;
		if (lines == null || lines.length == 0)
		{
			return null;
		}
		String line = lines[pick(seed(e), lines.length)];
		int[] plain = line.codePoints().filter(c -> !Character.isSupplementaryCodePoint(c)).toArray();
		return new String(plain, 0, plain.length).trim();
	}

	/** An in-game line with this event's {@link #overlayTag} after it, or the line as it was. */
	static String tagged(String text, GroupEvent e, Settings settings)
	{
		String tag = overlayTag(e, settings);
		return tag == null ? text : text + " " + tag;
	}

	private static String[] levelNumber(GroupEvent e)
	{
		return LEVELS.contains(e.type) ? LEVEL_NUMBERS.get(e.number) : null;
	}

	/**
	 * Which of {@code n} phrasings a seed picks. MurmurHash3's 64-bit finalizer, so nearby seeds spread out;
	 * {@code new Random(seed).nextInt(n)} does not: its first value barely moves between close seeds.
	 */
	static int pick(long seed, int n)
	{
		long z = seed;
		z = (z ^ (z >>> 33)) * 0xff51afd7ed558ccdL;
		z = (z ^ (z >>> 33)) * 0xc4ceb9fe1a85ec53L;
		z ^= z >>> 33;
		return (int) Math.floorMod(z, (long) n);
	}

	/** The same on every client that sees the event: the sender's time, the member and the kind. */
	static long seed(GroupEvent e)
	{
		return 31L * (31L * e.at + e.member.toLowerCase(Locale.ROOT).hashCode()) + e.type.code.hashCode();
	}

	/** A death that cost 0 gp: its "lost about 0 gp" line is never posted. */
	static boolean nothingLost(GroupEvent e)
	{
		return e.type == GroupEvent.Type.DEATH_VALUE && e.number <= 0;
	}

	private static boolean clueDeath(GroupEvent e, ItemLookup lookup)
	{
		if (e.type != GroupEvent.Type.DEATH_VALUE || !e.items.containsKey(EasterEggLines.SPADE))
		{
			return false;
		}
		for (int id : e.items.keySet())
		{
			if (id != EasterEggLines.SPADE && !clueItem(lookup.name(id)))
			{
				return false;
			}
		}
		return true;
	}

	private static boolean clueItem(String name)
	{
		String n = name.toLowerCase(Locale.ROOT);
		return CLUE_ITEMS.stream().anyMatch(n::startsWith);
	}

	private static boolean bonesOnly(GroupEvent e)
	{
		return e.type == GroupEvent.Type.DROP && e.items.size() == 1 && e.items.containsKey(EasterEggLines.BONES);
	}

	private static String[] itemRow(GroupEvent e, ItemLookup lookup, Settings settings)
	{
		for (Map.Entry<Integer, String[]> row : EasterEggLines.ITEMS.entrySet())
		{
			int id = row.getKey();
			if ((DROPS.contains(e.type) && e.items.containsKey(id))
				|| (NAMED.contains(e.type) && lookup.name(id).equalsIgnoreCase(e.text)))
			{
				return row.getValue();
			}
		}
		return null;
	}

	/**
	 * Took at least the 'Freeloader at' value, and at least as much as was given back on the same visit. At, not
	 * just over, like {@link #legend}: both settings read "at".
	 */
	private static boolean freeloader(GroupEvent e, ItemLookup lookup, Settings settings)
	{
		long took = EventText.value(taken(e), lookup);
		return settings.freeloaderAt > 0 && took >= settings.freeloaderAt
			&& took >= EventText.value(deposited(e), lookup);
	}

	private static boolean legend(GroupEvent e, ItemLookup lookup, Settings settings)
	{
		return settings.legendAt > 0 && EventText.value(deposited(e), lookup) >= settings.legendAt;
	}

	private static Map<Integer, Integer> deposited(GroupEvent e)
	{
		boolean gave = e.type == GroupEvent.Type.STORAGE_DEPOSIT || e.type == GroupEvent.Type.STORAGE_SUMMARY;
		return gave ? e.items : Collections.emptyMap();
	}

	private static Map<Integer, Integer> taken(GroupEvent e)
	{
		switch (e.type)
		{
			case STORAGE_WITHDRAWAL:
				return e.items;
			case STORAGE_SUMMARY:
				return e.taken;
			default:
				return Collections.emptyMap();
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.util.function.LongSupplier;

/**
 * What {@link LevelPosts} and {@link EventPosts} share around their {@link EditedThreads}: the restart file, a
 * logout and shutdown. Any thread.
 */
abstract class EditedPosts
{
	private final EditedThreads<?, ?> threads;
	final LongSupplier clock;

	EditedPosts(EditedThreads<?, ?> threads, LongSupplier clock)
	{
		this.threads = threads;
		this.clock = clock;
	}

	/** The open messages to keep for a restart when they changed since the last call, else null ({@link EditedThreads#saved}). */
	String saved()
	{
		return threads.saved();
	}

	/** Messages an earlier run {@link #saved}, back as open while inside {@code window} of their first post. */
	void restore(String text, long window)
	{
		threads.restore(text, clock.getAsLong(), window);
	}

	/** A logout: no more joining, owed edits still go. */
	void close()
	{
		threads.close();
	}

	void clear()
	{
		threads.clear();
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;

/**
 * Discord messages that one member's later events edit in place: the first event posts and keeps the message's id,
 * more within the window (counted from the first post) mark it for an edit, and {@link #due} hands out at most one
 * edit per message every {@link #EDIT_GAP}, so quicker events fold into the next edit. An edit Discord refuses (the
 * message deleted, the webhook changed) is posted anew and that post is the one kept from then on.
 *
 * <p>The open messages survive a client restart: {@link #saved} hands out one line per message when they change,
 * keyed by the webhook's id from its URL ({@link StatusBoard#hookOf}, never the URL or its token), and
 * {@link #restore} takes them back, dropping any past the window. A restored message is joined only through the same
 * webhook. Shared by {@link LevelThreads} (a card per skill) and {@link EventThreads} (every other kind); each says
 * what a message holds, how it is keyed, and how it is saved. Pure and clock-driven; every method holds the lock.
 *
 * @param <T> the message and what it holds
 * @param <E> one post or edit of it, frozen when handed out
 */
abstract class EditedThreads<T extends EditedThreads.Message, E>
{
	/** At most one edit per message this often. */
	static final long EDIT_GAP = TimeUnit.SECONDS.toMillis(10);
	/** Edits in a row a server or network failure may cost before the message gives up and posts fresh. */
	static final int MAX_EDIT_FAILURES = 3;
	/** Cards in one message: Discord takes at most 10 embeds in a message. */
	static final int MAX_CARDS = 10;

	/** One message and its post state. Read and written only under the owner's lock. */
	static class Message
	{
		final String member;
		/** The webhook it posts to ({@link #tag}): what an event must match to join. Never null. */
		final String hook;
		/** The latest URL it was joined through; null for a restored message until an event joins it. */
		String url;
		final long first;
		long last;
		/** The message's one picture: the latest event's that had one. Never saved. */
		byte[] png;
		String messageId;
		/** A post or edit of it is with the sender. */
		boolean busy;
		/** Holds an event the message does not show yet. */
		boolean dirty;
		long sentAt;
		/** Edits in a row lost to a server or network failure. */
		int failures;

		/** A new message, its first post about to go to the sender. */
		Message(String member, String url, long now, byte[] png)
		{
			this.member = member;
			this.hook = tag(url);
			this.url = url;
			this.first = now;
			this.last = now;
			this.png = png;
			this.busy = true;
		}

		/** A saved message back after a restart: posted, not busy, its next event an edit. */
		Message(String hook, String member, long first, long last, String messageId)
		{
			this.hook = hook;
			this.member = member;
			this.first = first;
			this.last = last;
			this.messageId = messageId;
		}

		/** Whether an event through {@code url} at {@code now} may still join: same webhook, inside the window. */
		final boolean open(String url, long now, long window)
		{
			return hook.equals(tag(url)) && now - first < window;
		}

		/** An event joined: the message is owed an edit, with the newest picture if this one has one. */
		final void grew(String url, long now, byte[] picture)
		{
			this.url = url;
			last = now;
			png = picture == null ? png : picture;
			dirty = true;
		}
	}

	/** The messages an event can still join, by {@link #key}. */
	final Map<String, T> open = new HashMap<>();
	/** Every message with work left: the open ones, and closed ones still owed an edit. */
	private final List<T> live = new ArrayList<>();
	/** The open messages changed since {@link #saved} last handed them out. */
	boolean changed;

	/** What a message is found by: the member, and for {@link EventThreads} the kind of event too. */
	abstract String key(T m);

	/** One post or edit of {@code m}, copied so it is safe to read off the lock. */
	abstract E snapshot(T m);

	/** The message as one saved line; never holds a newline. */
	abstract String line(T m);

	/** A {@link #line} back; null when unreadable or from another format. */
	abstract T parse(String line);

	/** Holding the lock: {@code fresh} replaces any open message under its key; its first post goes back. */
	final E start(T fresh)
	{
		if (open.put(key(fresh), fresh) != null)
		{
			changed = true;
		}
		live.add(fresh);
		return snapshot(fresh);
	}

	/**
	 * The open messages to keep for a restart, one {@link #line} each, when they changed since the last call; null
	 * when they did not. Only messages with an id (and a Discord webhook to match them by) are kept.
	 */
	synchronized String saved()
	{
		if (!changed)
		{
			return null;
		}
		changed = false;
		List<String> lines = new ArrayList<>();
		for (T m : open.values())
		{
			if (m.messageId != null && m.hook.startsWith("w"))
			{
				lines.add(line(m));
			}
		}
		return String.join("\n", lines);
	}

	/**
	 * Messages {@link #saved} by an earlier run, back as open: the next event within {@code window} of the first post
	 * edits that message. Lines past the window or unreadable are dropped, and the next {@link #saved} no longer has
	 * them; a message this run already started wins.
	 */
	synchronized void restore(String text, long now, long window)
	{
		for (String line : text == null ? new String[0] : text.split("\n"))
		{
			T m = line.isEmpty() ? null : parse(line);
			if (m == null || now - m.first >= window || open.containsKey(key(m)))
			{
				changed |= !line.isEmpty();
				continue;
			}
			open.put(key(m), m);
			live.add(m);
		}
	}

	/** How a message's new post went: on success it is the one edited from now on. */
	synchronized void posted(T m, int status, String messageId, long now)
	{
		m.busy = false;
		if (ok(status) && messageId != null)
		{
			m.messageId = messageId;
			m.sentAt = now;
			changed = true;
			return;
		}
		// Nothing to edit (refused, failed, or dropped by a full queue): the member's next event posts anew.
		end(m);
	}

	/** The edits to send now: posted messages with a newer event, each at most once per {@link #EDIT_GAP}. */
	synchronized List<E> due(long now)
	{
		List<E> out = new ArrayList<>();
		for (Iterator<T> i = live.iterator(); i.hasNext(); )
		{
			T m = i.next();
			if (m.busy)
			{
				continue;
			}
			if (m.dirty && m.messageId != null && now - m.sentAt >= EDIT_GAP)
			{
				m.dirty = false;
				m.busy = true;
				m.sentAt = now;
				out.add(snapshot(m));
			}
			else if (!m.dirty && !open.containsValue(m))
			{
				i.remove();
			}
		}
		return out;
	}

	/**
	 * How an edit went. Discord refusing it (404 for a deleted message, or any 4xx) gives back the post to send in
	 * its place, its outcome to {@link #posted}. A server or network failure tries the edit again later, up to
	 * {@link #MAX_EDIT_FAILURES} in a row; then, or when the queue dropped the edit unsent
	 * ({@link DiscordQueue#DROPPED}), the message ends and the member's next event posts anew. Null when there is
	 * nothing more to send.
	 */
	synchronized E edited(T m, int status)
	{
		m.busy = false;
		if (ok(status))
		{
			m.failures = 0;
			return null;
		}
		if (status >= 400 && status < 500)
		{
			m.messageId = null;
			m.dirty = false;
			m.busy = true;
			return snapshot(m);
		}
		if (status == DiscordQueue.DROPPED || ++m.failures >= MAX_EDIT_FAILURES)
		{
			end(m);
			return null;
		}
		m.dirty = true;
		return null;
	}

	/** Holding the lock: no more edits or joining; {@link #due} forgets it. */
	private void end(T m)
	{
		m.dirty = false;
		changed |= open.values().remove(m);
	}

	/** A logout: no more joining, but an edit already owed still goes. Saved messages end too. */
	synchronized void close()
	{
		changed |= !open.isEmpty();
		open.clear();
	}

	/** Shutdown: everything forgotten. */
	synchronized void clear()
	{
		open.clear();
		live.clear();
	}

	/** The webhook a URL posts to: its id ({@link StatusBoard#hookOf}), so a thread or URL form is the same one. */
	static String tag(String url)
	{
		String hook = StatusBoard.hookOf(url);
		if (hook != null)
		{
			return hook;
		}
		return url == null ? "" : url;
	}

	static boolean ok(int status)
	{
		return status >= 200 && status < 300;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The game's chat lines for the medium event kinds. Pure, tags stripped first.
 *
 * <p><b>Unverified wording.</b> These lines were written from memory of the
 * base client's screenshot, chat commands and slayer plugins and of Dink: the
 * sources were not readable when this was built (BRIEF.md, part C). A line the
 * game words differently fails silent, so each needs one in-game check. The
 * Slayer lines are the exception: they are cited from RuneLite's source below.
 */
final class EventChat
{
	private static final Pattern CLUE = Pattern.compile("^You have completed ([0-9,]+) (\\w+) Treasure Trails?\\.?$");
	private static final Pattern COMBAT_TASK = Pattern.compile(
		"^Congratulations, you've completed an? (\\w+) combat task: (.+?)(?: \\(\\d+ points?\\))?\\.?$");
	private static final Pattern NEW_BEST = Pattern.compile(
		"(?i)(?:duration:|subdued in|completion time:) ([0-9:.]*[0-9])\\.? \\(new personal best\\)");
	/*
	 * Slayer lines. RuneLite's SlayerPlugin read these from chat and dialogue until it moved to varps
	 * (runelite/runelite 1f6ae893, 2023-02-24, "slayer: use vars for task tracking"); the patterns are its
	 * constants from the parent revision, SlayerPlugin.java:107-121, with the test lines in SlayerPluginTest.java
	 * :85-126. The completion line it only trusted when it named a Slayer master (:472), which the gem's
	 * "You've completed 0 tasks in a row and currently have a total of 0 points." does not.
	 * "You have completed your task! ..." is Dink's SlayerNotifier.SLAYER_TASK_REGEX (pajlads/DinkPlugin 485054b).
	 */
	/** CHAT_COMPLETE_MESSAGE, with Dink's "Mortimer" streak. Group 1 the streak, 2 the points this task gave. */
	private static final Pattern SLAYER_DONE = Pattern.compile("You've completed (?:at least )?([\\d,]+)"
		+ " (?:Wilderness |Mortimer )?tasks?(?: and received ([\\d,]+) points?, giving you a total of [\\d,]+"
		+ "| and reached the maximum amount of Slayer points \\([\\d,]+\\))?");
	private static final Pattern SLAYER_KILLED = Pattern.compile(
		"^You have completed your task! You killed ([\\d,]+) ([^.]+)\\..*");
	/** CHAT_GEM_PROGRESS_MESSAGE; the partner's name is a group here. */
	private static final Pattern SLAYER_GEM = Pattern.compile("^(?:You're assigned to kill|You have received a new"
		+ " Slayer assignment from (?<from>.*):) (?:[Tt]he )?(?<name>.+?)(?: (?:in|on|south of) (?:the )?[^;]+?)?"
		+ "(?:; only | \\()(?<amount>\\d+)(?: more to go\\.|\\))$");
	/** CHAT_GEM_COMPLETE_MESSAGE, CHAT_CANCEL_MESSAGE and CHAT_CANCEL_MESSAGE_JAD_ZUK: no task any more. */
	private static final Pattern SLAYER_CLEARED = Pattern.compile("^(?:You need something new to hunt\\."
		+ "|Your task has been cancelled\\.|You no longer have a slayer task(?: as you left the (?:fight cave|Inferno))?\\.)$");
	/** NPC_ASSIGN_MESSAGE: the master's (or NPC Contact's) dialogue. */
	private static final Pattern NPC_ASSIGN = Pattern.compile(".*(?:Your new task is to kill|You are to bring balance"
		+ " to)\\s*(?<amount>\\d+) (?<name>.+?)(?: (?:in|on|south of) (?:the )?.+)?\\.");
	/** NPC_ASSIGN_BOSS_MESSAGE. */
	private static final Pattern NPC_ASSIGN_BOSS = Pattern.compile("^(?:Excellent\\. )?You're now assigned to"
		+ " (?:kill|bring balance to) (?:the )?(?<name>.*) (?<amount>\\d+) times.*Your reward point tally is (.*)\\.$");
	/** NPC_ASSIGN_FIRST_MESSAGE: Turael's (or Spria's, Aya's) first task. */
	private static final Pattern NPC_ASSIGN_FIRST = Pattern.compile("^We'll start you off (?:hunting|bringing balance"
		+ " to) (?<name>.*), you'll need to kill (?<amount>\\d*) of them\\.$");
	/** NPC_CURRENT_MESSAGE: the master, or the gem's "Check", repeating the task already held. */
	private static final Pattern NPC_CURRENT = Pattern.compile("^You're (?:still(?: meant to be)?|currently assigned"
		+ " to) (?:hunting|bringing balance to|kill|bring balance to|slaying) (?<name>.+?)(?: (?:in|on|south of)"
		+ " (?:the )?.+)?(?:, with|; (?:you have|only)) (?<amount>\\d+)(?: more)? to go\\..*");
	private static final Pattern BREAK = Pattern.compile("(?i)<br\\s*/?>");
	private static final Pattern SPECIAL = Pattern.compile("^(.+?) found something special: (.+)$");
	private static final Pattern DASH_LOOT = Pattern.compile("^(.+?) - (.+)$");
	static final String SPECIAL_LOOT_HEADER = "Special loot:";

	private EventChat()
	{
	}

	/** {@code group(1)} and {@code group(2)} of the pattern on the tag-free line; null when it does not match. */
	private static String[] two(Pattern p, String message)
	{
		Matcher m = p.matcher(EventText.plain(message));
		return m.matches() ? new String[]{m.group(1).trim(), m.group(2).trim()} : null;
	}

	/** Clue tier and count: "You have completed 42 medium Treasure Trails." */
	static EventText.Count clue(String message)
	{
		String[] p = two(CLUE, message);
		return p == null ? null : new EventText.Count(p[1], number(p[0]));
	}

	/** {tier, task name}, or null. */
	static String[] combatTask(String message)
	{
		return two(COMBAT_TASK, message);
	}

	/** The time of a new personal best, or null. */
	static String personalBest(String message)
	{
		Matcher m = NEW_BEST.matcher(EventText.plain(message));
		return m.find() ? m.group(1) : null;
	}

	/**
	 * The streak line after a finished task: {streak, points this task gave, or -1 when the line gives none}.
	 * Null for any other line, the gem's "currently have a total of" line among them: only a line that sends
	 * you back to a Slayer master is one.
	 */
	static long[] slayerDone(String message)
	{
		String text = EventText.plain(message);
		if (!text.startsWith("You've completed") || !text.toLowerCase(Locale.ROOT).contains("slayer master"))
		{
			return null;
		}
		Matcher m = SLAYER_DONE.matcher(text);
		if (!m.find())
		{
			return null;
		}
		return new long[]{number(m.group(1)), m.group(2) == null ? -1 : number(m.group(2))};
	}

	/** "You have completed your task! You killed 19 Icefiends. ...": the monster, or null. */
	static String slayerKilled(String message)
	{
		String[] p = two(SLAYER_KILLED, message);
		return p == null ? null : capital(p[1]);
	}

	/** The gem's empty-task line, or a cancelled task. */
	static boolean slayerCleared(String message)
	{
		return SLAYER_CLEARED.matcher(EventText.plain(message)).matches();
	}

	/** The gem's progress line (not new), or a partner's assignment (new, from them); null for anything else. */
	static SlayerTask slayerChat(String message)
	{
		Matcher m = SLAYER_GEM.matcher(EventText.plain(message));
		if (!m.matches())
		{
			return null;
		}
		String from = m.group("from");
		return task(m.group("name"), m.group("amount"), from == null ? "" : from.trim(), from != null);
	}

	/**
	 * The NPC dialogue: a new assignment ({@code npc} gave it) or the task repeated (not new); null for any other
	 * line. {@code <br>} breaks are spaces, as RuneLite's {@code Text.sanitizeMultilineText} made them.
	 */
	static SlayerTask slayerDialog(String text, String npc)
	{
		String line = EventText.plain(BREAK.matcher(text == null ? "" : text).replaceAll(" ")).replaceAll("\\s+", " ");
		String from = EventText.plain(npc);
		for (Pattern p : new Pattern[]{NPC_ASSIGN, NPC_ASSIGN_BOSS, NPC_ASSIGN_FIRST})
		{
			Matcher m = p.matcher(line);
			if (m.find())
			{
				return task(m.group("name"), m.group("amount"), from, true);
			}
		}
		Matcher current = NPC_CURRENT.matcher(line);
		return current.find() ? task(current.group("name"), current.group("amount"), from, false) : null;
	}

	private static SlayerTask task(String name, String amount, String from, boolean fresh)
	{
		return new SlayerTask(capital(name.trim()), number(amount), from, fresh);
	}

	/** "icefiends" as the gem says it reads "Icefiends". */
	private static String capital(String name)
	{
		return name.isEmpty() ? name : Character.toUpperCase(name.charAt(0)) + name.substring(1);
	}

	/** A Slayer task as a line names it. */
	static final class SlayerTask
	{
		final String name;
		final long amount;
		/** The master or partner who gave it; empty when the line does not say. */
		final String from;
		/** The line hands out a task, rather than repeating the one held. */
		final boolean fresh;

		SlayerTask(String name, long amount, String from, boolean fresh)
		{
			this.name = name;
			this.amount = amount;
			this.from = from;
			this.fresh = fresh;
		}
	}

	/** {player, item} from "Alex found something special: X". */
	static String[] raidSpecial(String message)
	{
		return two(SPECIAL, message);
	}

	/** {player, item} from Chambers' "Alex - X", which only means loot straight after its header line. */
	static String[] raidDash(String message)
	{
		return two(DASH_LOOT, message);
	}

	static boolean isSpecialLootHeader(String message)
	{
		return SPECIAL_LOOT_HEADER.equals(EventText.plain(message));
	}

	private static long number(String digits)
	{
		try
		{
			return Long.parseLong(digits.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.IntPredicate;

/**
 * Turns what the game already told this client into events: a group storage
 * visit into its storage events, a drop's untradeables into a unique, a
 * storage minimum into its event. Pure; the client reads live in
 * {@link GroupEventEngine}.
 */
final class EventDetect
{
	/** Untradeables that drop all the time and are not what anyone means by a unique. */
	static final String DEFAULT_UNTRADEABLE_IGNORE = "Clue scroll, Scroll box, Brimstone key, Larran's key,"
		+ " Ancient shard, Dark totem, Mossy key, Giant key, Ecumenical key, Looting bag";

	/** The account type varbit's value for a Hardcore Group Ironman (Varbits.ACCOUNT_TYPE javadoc, runelite-api). */
	static final int HARDCORE_GROUP_IRONMAN = 5;

	private EventDetect()
	{
	}

	/** A member's storage visit as events: deposit, withdrawal, summary and "took the last". Thresholds come later. */
	static List<GroupEvent> storage(StorageChange change, ItemLookup lookup)
	{
		List<GroupEvent> out = new ArrayList<>();
		if (change == null || change.isEmpty())
		{
			return out;
		}
		String by = change.member();
		long at = change.at();
		if (!change.deposited().isEmpty())
		{
			out.add(GroupEvent.of(GroupEvent.Type.STORAGE_DEPOSIT, at, by).items(change.deposited())
				.number(EventText.value(change.deposited(), lookup)).build());
		}
		if (!change.took().isEmpty())
		{
			out.add(GroupEvent.of(GroupEvent.Type.STORAGE_WITHDRAWAL, at, by).items(change.took())
				.number(EventText.value(change.took(), lookup)).build());
		}
		out.add(GroupEvent.of(GroupEvent.Type.STORAGE_SUMMARY, at, by).items(change.deposited())
			.taken(change.took()).build());
		Map<Integer, Integer> last = new TreeMap<>();
		for (Map.Entry<Integer, Integer> e : change.took().entrySet())
		{
			if (change.after().getOrDefault(e.getKey(), 0) <= 0)
			{
				last.put(e.getKey(), e.getValue());
			}
		}
		if (!last.isEmpty())
		{
			out.add(GroupEvent.of(GroupEvent.Type.STORAGE_LAST, at, by).items(last).build());
		}
		return out;
	}

	static GroupEvent minimum(long at, String member, LowStock.Alert alert)
	{
		return GroupEvent.of(GroupEvent.Type.STORAGE_MINIMUM, at, member).text(alert.item).number(alert.have)
			.detail("minimum " + Amounts.GAME.of(alert.minimum)).build();
	}

	/** The untradeable items in a drop, less the ignored names; empty when there are none. */
	static Map<Integer, Integer> uniques(Map<Integer, Integer> drop, IntPredicate tradeable, ItemLookup lookup,
		String ignore)
	{
		List<String> skip = new ArrayList<>();
		for (String s : (ignore == null ? "" : ignore).split(","))
		{
			if (!s.trim().isEmpty())
			{
				skip.add(s.trim().toLowerCase(Locale.ROOT));
			}
		}
		Map<Integer, Integer> out = new TreeMap<>();
		for (Map.Entry<Integer, Integer> e : drop.entrySet())
		{
			if (tradeable.test(e.getKey()))
			{
				continue;
			}
			String name = lookup.name(e.getKey()).toLowerCase(Locale.ROOT);
			if (skip.stream().noneMatch(name::startsWith))
			{
				out.put(e.getKey(), e.getValue());
			}
		}
		return out;
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.LongSupplier;
import java.util.function.Supplier;

/**
 * {@link EventThreads}' decisions sent through the {@link DiscordSender}: a member's message's first post (the
 * moment's usual post, kept by its message id), its owed edits, and the new post that replaces a message Discord no
 * longer has. Any thread.
 */
final class EventPosts extends EditedPosts
{
	private static final String VISIT = "group storage:";

	private final EventThreads threads;
	private final DiscordSender sender;
	private final Gson gson;
	private final Supplier<DiscordStyle> style;
	/** Names and prices, amounts read the Discord way: a storage card's net lines and value. */
	private final Supplier<ItemLookup> words;

	EventPosts(DiscordSender sender, Gson gson, LongSupplier clock, Supplier<DiscordStyle> style,
		Supplier<ItemLookup> words)
	{
		this(new EventThreads(gson), sender, gson, clock, style, words);
	}

	private EventPosts(EventThreads threads, DiscordSender sender, Gson gson, LongSupplier clock,
		Supplier<DiscordStyle> style, Supplier<ItemLookup> words)
	{
		super(threads, clock);
		this.threads = threads;
		this.sender = sender;
		this.gson = gson;
		this.style = style;
		this.words = words;
	}

	/**
	 * A moment as a card: its post in both styles (so a style change mid-message still has its words), with the
	 * Easter egg, never a mention or a picture. Null when its kind never groups, or it has nothing to say. Client
	 * thread, as every post's words are built there.
	 */
	static EventThreads.Moment moment(Gson gson, String url, DiscordMerge.Post post, ItemLookup lookup, String egg,
		String username, boolean pings)
	{
		String family = EventThreads.family(post.lead.type);
		String embed = DiscordWebhook.payload(gson, post, lookup, DiscordStyle.EMBED, null, false, egg, null);
		if (family == null || embed == null)
		{
			return null;
		}
		String plain = DiscordWebhook.payload(gson, post, lookup, DiscordStyle.PLAIN, null, false, egg, null);
		EventThreads.Card card = new EventThreads.Card(DiscordWebhook.firstEmbed(gson, embed),
			DiscordWebhook.content(gson, plain));
		String move = post.description.startsWith(VISIT) ? post.description.substring(VISIT.length()).trim()
			: post.description;
		return new EventThreads.Moment(family, url, username, pings, card, post.lead, post.extras, move);
	}

	/**
	 * A moment into its member's message, {@code png} its picture or null. A new message posts {@code firstJson},
	 * the moment's usual post; a joined one is edited by {@link #tick} in time.
	 */
	void add(EventThreads.Moment moment, String firstJson, byte[] png, long window)
	{
		EventThreads.Edit fresh = threads.add(moment, png, clock.getAsLong(), window);
		if (fresh != null)
		{
			post(fresh, firstJson);
		}
	}

	/** Once a second: the edits owed now. */
	void tick()
	{
		for (EventThreads.Edit edit : threads.due(clock.getAsLong()))
		{
			JsonObject o = message(edit);
			if (o == null)
			{
				// Nothing to say: the message ends as a dropped edit would, and the next moment posts anew.
				threads.edited(edit.feed, DiscordQueue.DROPPED);
				continue;
			}
			String json = DiscordWebhook.asEdit(gson, o, edit.png != null);
			sender.edit(edit.url, edit.messageId, json, edit.png, (status, id) -> refused(edit, status));
		}
	}

	private void refused(EventThreads.Edit edit, int status)
	{
		EventThreads.Edit again = threads.edited(edit.feed, status);
		if (again != null)
		{
			JsonObject o = message(again);
			post(again, o == null ? null : gson.toJson(o));
		}
	}

	private void post(EventThreads.Edit m, String json)
	{
		if (json == null)
		{
			threads.posted(m.feed, 0, null, clock.getAsLong());
			return;
		}
		sender.post(m.url, json, m.png, (status, id) -> threads.posted(m.feed, status, id, clock.getAsLong()));
	}

	/** The whole message as a new post's body: the cards, or storage's net card. Null when there is nothing. */
	private JsonObject message(EventThreads.Edit m)
	{
		if (!m.storage)
		{
			return DiscordWebhook.stack(gson, m.cards, style.get(), m.png != null, m.username);
		}
		ItemLookup lookup = words.get();
		String json = DiscordWebhook.payload(gson, net(m, lookup), lookup, style.get(), null, m.png != null, null,
			m.username);
		return json == null ? null : gson.fromJson(json, JsonObject.class);
	}

	/**
	 * Group storage over every visit in the message as one post: each item's amount summed ("took 2 x Rope" then
	 * "deposited 10 x Rope" reads "deposited 8 x Rope"), the Value of what moved overall, then the visits, newest
	 * first, and the newest visit's minimum and last-one lines.
	 */
	static DiscordMerge.Post net(EventThreads.Edit m, ItemLookup lookup)
	{
		Map<Integer, Integer> took = new TreeMap<>();
		Map<Integer, Integer> put = new TreeMap<>();
		m.net.forEach((id, n) -> (n < 0 ? took : put).put(id, (int) Math.min(Integer.MAX_VALUE, Math.abs(n))));
		StringBuilder text = new StringBuilder(VISIT);
		// No "(big ...)" marks: those are about one move, and these are sums.
		DiscordMerge.moved(text, "took", took, Long.MAX_VALUE, lookup);
		DiscordMerge.moved(text, "deposited", put, Long.MAX_VALUE, lookup);
		if (took.isEmpty() && put.isEmpty())
		{
			text.append(" nothing moved overall");
		}
		Map<Integer, Integer> all = new TreeMap<>(took);
		all.putAll(put);
		List<String[]> extras = new ArrayList<>();
		if (m.moves.size() > 1)
		{
			String visits = String.join("\n", m.moves);
			extras.add(new String[]{"Visits, newest first", visits.length() > DiscordMerge.MAX_FIELD
				? visits.substring(0, DiscordMerge.MAX_FIELD) : visits});
		}
		extras.addAll(m.extras);
		GroupEvent lead = m.lead.event();
		return new DiscordMerge.Post(lead, DiscordMerge.visitTitle(!put.isEmpty(), !took.isEmpty()), text.toString(),
			all, extras, false, put, took);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Map;
import java.util.TreeMap;
import java.util.function.Consumer;

/**
 * Sends each event to the outputs whose switch for its kind is on, after the
 * thresholds. Pure: the outputs are plain consumers, so every rule here is
 * tested without a client or a network.
 *
 * <p><b>One poster per event.</b> Only this player's own events go to
 * Discord. A member's event reaches this client over the party, and that
 * member's own client is the one that posts it (if they turned Discord on),
 * so a group with everyone posting still posts each event once.
 */
final class EventRouter
{
	private final Consumer<GroupEvent> discord;
	private final Consumer<GroupEvent> overlay;
	private final Consumer<GroupEvent> digest;
	private final Consumer<GroupEvent> log;

	EventRouter(Consumer<GroupEvent> discord, Consumer<GroupEvent> overlay)
	{
		this(discord, overlay, e ->
		{
		});
	}

	/**
	 * {@code digest} takes this player's own events for the daily digest. It
	 * is a separate output: an event can post now and be in tonight's digest,
	 * and a ticked digest never holds an instant post back.
	 */
	EventRouter(Consumer<GroupEvent> discord, Consumer<GroupEvent> overlay, Consumer<GroupEvent> digest)
	{
		this(discord, overlay, digest, e ->
		{
		});
	}

	/**
	 * {@code log} is the sidebar Log tab. It takes every event that passes the
	 * thresholds, yours and members', whichever Discord and overlay switches
	 * are on (Board 2026-11-10): the Log has no switch of its own.
	 */
	EventRouter(Consumer<GroupEvent> discord, Consumer<GroupEvent> overlay, Consumer<GroupEvent> digest,
		Consumer<GroupEvent> log)
	{
		this.discord = discord;
		this.overlay = overlay;
		this.digest = digest;
		this.log = log;
	}

	/** {@code own}: this player's event, from this client; false for a member's from the party. */
	void route(GroupEvent event, boolean own, EventSettings settings, ItemLookup lookup)
	{
		GroupEvent kept = threshold(event, settings, lookup);
		if (kept == null || !kept.isValid() || kept.member.isEmpty())
		{
			return;
		}
		log.accept(kept);
		if (settings.overlay.contains(kept.type))
		{
			overlay.accept(kept);
		}
		if (own)
		{
			send(kept, settings);
		}
	}

	/**
	 * Discord and the digest only, under {@code settings}, for an event {@link #route} already showed under this
	 * member's own: a game broadcast for a member without the plugin, posted without the poster's own opt-outs.
	 */
	void post(GroupEvent event, EventSettings settings, ItemLookup lookup)
	{
		GroupEvent kept = threshold(event, settings, lookup);
		if (kept != null && kept.isValid() && !kept.member.isEmpty())
		{
			send(kept, settings);
		}
	}

	private void send(GroupEvent kept, EventSettings settings)
	{
		if (settings.discord.contains(kept.type))
		{
			discord.accept(kept);
		}
		if (settings.digests(kept.type))
		{
			digest.accept(kept);
		}
	}

	/** The event as the thresholds leave it: a drop keeps only its valuable stacks; null when nothing is left. */
	static GroupEvent threshold(GroupEvent event, EventSettings settings, ItemLookup lookup)
	{
		switch (event.type)
		{
			case DROP:
				return valuableStacks(event, settings.dropMin, lookup);
			case CLUE:
				return atLeast(event, settings.clueMin);
			case LEVEL_UP:
				return everyN(atLeast(event, settings.levelMin), settings.levelEvery);
			case STORAGE_DEPOSIT:
			case STORAGE_WITHDRAWAL:
				return atLeast(event, settings.storageMin);
			default:
				return event;
		}
	}

	private static GroupEvent atLeast(GroupEvent event, long min)
	{
		return event.number >= min ? event : null;
	}

	/**
	 * "Post every N levels": only levels that are a multiple of {@code every}.
	 * 99 always counts; 99s, max total, total level milestones and combat
	 * levels are kinds of their own and never come through here. One action
	 * that gains several levels (low Prayer, 3 → 7 with N = 5) counts when it
	 * passes a multiple, so a jump never skips the level it crossed.
	 *
	 * <p>This filter runs before "Combine level-ups": a skill's streak post is
	 * made of the levels that pass it, so with N = 5 one post reads 59 → 65
	 * and is edited when 70 comes, not at every level in between.
	 */
	private static GroupEvent everyN(GroupEvent levelUp, int every)
	{
		if (levelUp == null || every <= 1 || levelUp.number >= ProgressTracker.MAX_LEVEL)
		{
			return levelUp;
		}
		long before = levelUp.previous > 0 && levelUp.previous < levelUp.number ? levelUp.previous
			: levelUp.number - 1;
		// The highest multiple of N at or below the new level is above the old one.
		return levelUp.number / every * every > before ? levelUp : null;
	}

	private static GroupEvent valuableStacks(GroupEvent event, long min, ItemLookup lookup)
	{
		Map<Integer, Integer> valuable = new TreeMap<>();
		for (Map.Entry<Integer, Integer> e : event.items.entrySet())
		{
			if (lookup.price(e.getKey()) * e.getValue() >= min)
			{
				valuable.put(e.getKey(), e.getValue());
			}
		}
		return valuable.isEmpty() ? null : event.toBuilder().items(valuable).build();
	}
}

