			GroupIronmanConfig::overlayActivityComplete);
		both(GroupEvent.Type.ACTIVITY_DEATH, GroupIronmanConfig::discordActivityDeath,
			GroupIronmanConfig::overlayActivityDeath);

		DIGEST.put(GroupEvent.Category.DROPS, GroupIronmanConfig::digestDrops);
		DIGEST.put(GroupEvent.Category.DEATHS, GroupIronmanConfig::digestDeaths);
		DIGEST.put(GroupEvent.Category.STORAGE, GroupIronmanConfig::digestStorage);
		DIGEST.put(GroupEvent.Category.PROGRESS, GroupIronmanConfig::digestProgress);
		DIGEST.put(GroupEvent.Category.GROUP, GroupIronmanConfig::digestGroup);
		DIGEST.put(GroupEvent.Category.ACTIVITIES, GroupIronmanConfig::digestActivities);
	}

	/** Everything off: what a fresh install, and the plugin before startUp, sees. */
	static final EventSettings OFF = new EventSettings(EnumSet.noneOf(GroupEvent.Type.class),
		EnumSet.noneOf(GroupEvent.Type.class), Long.MAX_VALUE, Long.MAX_VALUE, 99, 365, false, 0, 100, 5,
		EnumSet.noneOf(GroupEvent.Category.class), 20, 1, EnumSet.noneOf(GroupEvent.Type.class), false);

	final Set<GroupEvent.Type> discord;
	final Set<GroupEvent.Type> overlay;
	final long dropMin;
	final long storageMin;
	final int levelMin;
	final int backAfterDays;
	/** "Share group events": members' non-drop events are taken in, and ours sent. */
	final boolean share;
	final long clueMin;
	/** A kill count milestone every this many kills; 0 for none. */
	final int kcEvery;
	final int graveWarnMinutes;
	/**
	 * Categories with a once-a-day summary post. In addition to the instant
	 * posts, never instead of them: a category's digest lists every event of
	 * it, ticked for instant posting or not.
	 */
	final Set<GroupEvent.Category> digest;
	final int digestHour;
	/**
	 * The sidebar Log takes every kind (Board 2026-11-10), so every kind is
	 * detected while the plugin runs. False only in {@link #OFF}.
	 */
	final boolean log;
	/** "Post every N levels": a level up counts only when its level is a multiple of this (99 always counts). */
	final int levelEvery;
	/** This member's own "don't post" kinds: kept out of the digest as well as the instant posts. */
	final Set<GroupEvent.Type> noPost;

	EventSettings(Set<GroupEvent.Type> discord, Set<GroupEvent.Type> overlay, long dropMin, long storageMin,
		int levelMin, int backAfterDays, boolean share)
	{
		this(discord, overlay, dropMin, storageMin, levelMin, backAfterDays, share, 0, 100, 5,
			EnumSet.noneOf(GroupEvent.Category.class), 20);
	}

	EventSettings(Set<GroupEvent.Type> discord, Set<GroupEvent.Type> overlay, long dropMin, long storageMin,
		int levelMin, int backAfterDays, boolean share, long clueMin, int kcEvery, int graveWarnMinutes,
		Set<GroupEvent.Category> digest, int digestHour)
	{
		this(discord, overlay, dropMin, storageMin, levelMin, backAfterDays, share, clueMin, kcEvery,
			graveWarnMinutes, digest, digestHour, 1, EnumSet.noneOf(GroupEvent.Type.class), true);
	}

	private EventSettings(Set<GroupEvent.Type> discord, Set<GroupEvent.Type> overlay, long dropMin, long storageMin,
		int levelMin, int backAfterDays, boolean share, long clueMin, int kcEvery, int graveWarnMinutes,
		Set<GroupEvent.Category> digest, int digestHour, int levelEvery, Set<GroupEvent.Type> noPost, boolean log)
	{
		this.log = log;
		this.levelEvery = Math.max(1, levelEvery);
		this.noPost = Collections.unmodifiableSet(copy(noPost));
		this.clueMin = Math.max(0, clueMin);
		this.kcEvery = Math.max(0, kcEvery);
		this.graveWarnMinutes = Math.max(1, Math.min(14, graveWarnMinutes));
		this.digest = Collections.unmodifiableSet(digest.isEmpty()
			? EnumSet.noneOf(GroupEvent.Category.class) : EnumSet.copyOf(digest));
		this.digestHour = Math.max(0, Math.min(23, digestHour));
		this.discord = Collections.unmodifiableSet(copy(discord));
		this.overlay = Collections.unmodifiableSet(copy(overlay));
		this.dropMin = Math.max(0, dropMin);
		this.storageMin = Math.max(0, storageMin);
		this.levelMin = levelMin;
		this.backAfterDays = Math.max(1, backAfterDays);
		this.share = share;
	}

	private static void both(GroupEvent.Type type, Predicate<GroupIronmanConfig> discord,
		Predicate<GroupIronmanConfig> overlay)
	{
		DISCORD.put(type, discord);
		OVERLAY.put(type, overlay);
	}

	/** Logins and logouts are posts only in that mode; the live board edits one message instead. */
	private static boolean postsOnline(GroupIronmanConfig config)
	{
		return config.discordOnlineStatus() == OnlineStatus.POSTS;
	}

	private static Set<GroupEvent.Type> copy(Set<GroupEvent.Type> types)
	{
		return types.isEmpty() ? EnumSet.noneOf(GroupEvent.Type.class) : EnumSet.copyOf(types);
	}

	/** This member's own config only: no group settings, no opt-outs. */
	static EventSettings from(GroupIronmanConfig config)
	{
		return from(config, new GroupSettingsSchema.Resolved(config, null), MemberPrefs.NONE);
	}

	/**
	 * The group's settings where it has them ({@code values}), this member's
	 * own config where it has none, then this member's own opt-outs on top:
	 * a kind they opted out of is not posted, a muted kind not shown. "Share
	 * group events" stays the member's own.
	 */
	static EventSettings from(GroupIronmanConfig config, GroupSettingsSchema.Resolved values, MemberPrefs prefs)
	{
		Set<GroupEvent.Type> discord = EnumSet.noneOf(GroupEvent.Type.class);
		Set<GroupEvent.Type> overlay = EnumSet.noneOf(GroupEvent.Type.class);
		for (GroupEvent.Type t : GroupEvent.Type.values())
		{
			boolean post = t == GroupSettingsSchema.OWN_DISCORD ? postsOnline(config)
				: values.on(GroupSettingsSchema.discordKey(t));
			if (post && prefs.posts(t))
			{
				discord.add(t);
			}
			if (values.on(GroupSettingsSchema.overlayKey(t)) && !prefs.mute.contains(t))
			{
				overlay.add(t);
			}
		}
		return new EventSettings(discord, overlay, values.value("eventDropMinValue"),
			values.value("eventStorageMinValue"), values.intValue("eventLevelMin"),
			values.intValue("eventBackAfterDays"), config.groupShareEvents(), values.value("eventClueMinValue"),
			values.intValue("eventKcEvery"), values.intValue("eventGravestoneWarnMinutes"), digests(values, prefs),
			values.intValue("discordDigestHour"), values.intValue("eventLevelEvery"), prefs.noPost, true);
	}

	/** The digest is this member's own events too: "Don't post my events" leaves it empty. */
	private static Set<GroupEvent.Category> digests(GroupSettingsSchema.Resolved values, MemberPrefs prefs)
	{
		Set<GroupEvent.Category> out = EnumSet.noneOf(GroupEvent.Category.class);
		for (GroupEvent.Category c : GroupEvent.Category.values())
		{
			if (!prefs.all && values.on(GroupSettingsSchema.digestKey(c)))
			{
				out.add(c);
			}
		}
		return out;
	}

	/** A copy with other level-up thresholds. */
	EventSettings levels(int min, int every)
	{
		return new EventSettings(discord, overlay, dropMin, storageMin, min, backAfterDays, share, clueMin, kcEvery,
			graveWarnMinutes, digest, digestHour, every, noPost, log);
	}

	/** Discord, the overlay or the digest wants this kind. */
	boolean wants(GroupEvent.Type type)
	{
		return discord.contains(type) || overlay.contains(type) || digests(type);
	}

	/** Worth detecting: the Log takes every kind, so any settings but {@link #OFF} detect all of them. */
	boolean detects(GroupEvent.Type type)
	{
		return log || wants(type);
	}

	/** This kind goes in its category's daily digest. The weekly recap is a post of its own. */
	boolean digests(GroupEvent.Type type)
	{
		return type != GroupEvent.Type.WEEKLY_RECAP && digest.contains(type.category) && !noPost.contains(type);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.function.BiFunction;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The words for each {@link GroupEvent.Type}, and the game's chat and widget
 * lines that start one. Pure, so every line can be tested without a client.
 *
 * <p>Message texts follow the base client's screenshot plugin
 * ({@code ScreenshotPlugin.java} at runelite master: {@code PET_MESSAGES}
 * ~:111-113, {@code BOSSKILL_MESSAGE_PATTERN} ~:102, the Barrows chest count
 * line ~:398, the quest scroll title ~:286-291).
 */
final class EventText
{
	private static final String[] PET_MESSAGES = {
		"You have a funny feeling like you're being followed",
		"You feel something weird sneaking into your backpack",
		"You have a funny feeling like you would have been followed",
	};
	private static final Pattern TAG = Pattern.compile("<[^>]*>");
	/** "Your Vorkath kill count is: 120." and "Your Barrows chest count is: 41." */
	private static final Pattern KILL_COUNT = Pattern.compile(
		"^Your (.+?) (?:kill|chest|success|completion|completed) count is: ?([0-9,]+)\\.?$");
	/** "Your completed Chambers of Xeric count is: 12." The word order is unverified: see {@link EventChat}. */
	private static final Pattern RAID_COUNT = Pattern.compile("^Your completed (.+?) count is: ?([0-9,]+)\\.?$");
	/** "You have completed Cook's Assistant!" and "You have completed the Restless Ghost Quest!" */
	private static final Pattern QUEST = Pattern.compile(
		"^You (?:have|'ve) (?:completed|been|rebuilt|achieved|helped|defeated|restored|freed|found|learned|solved)"
			+ "(?: the)? '?(.+?)'?(?: [Qq]uest)?[!.]?$");

	private static final Map<GroupEvent.Type, BiFunction<GroupEvent, ItemLookup, String>> LINES =
		new EnumMap<>(GroupEvent.Type.class);
	private static final Map<GroupEvent.Type, String> TITLES = new EnumMap<>(GroupEvent.Type.class);

	static
	{
		// Kept word for word from 1.0.0's log line; the value goes in the embed's own field.
		line(GroupEvent.Type.DROP, "Valuable drop", (e, l) -> (e.text.isEmpty() ? "received a drop: "
			: e.text + " dropped ") + StorageLog.describe(e.items, l) + kc(e));
		line(GroupEvent.Type.CLOG, "New collection log slot", (e, l) -> "new collection log slot, " + e.text);
		line(GroupEvent.Type.PET, "Pet", (e, l) -> "a pet!" + (e.text.isEmpty() ? "" : " (" + e.text + ")"));
		line(GroupEvent.Type.UNIQUE, "Untradeable unique", (e, l) -> "untradeable from " + e.text + ": "
			+ StorageLog.describe(e.items, l));
		line(GroupEvent.Type.DEATH, "Died", EventText::death);
		line(GroupEvent.Type.STORAGE_DEPOSIT, "Big storage deposit", (e, l) -> "deposited "
			+ items(e, l) + " to group storage");
		line(GroupEvent.Type.STORAGE_WITHDRAWAL, "Big storage withdrawal", (e, l) -> "took "
			+ items(e, l) + " from group storage");
		line(GroupEvent.Type.STORAGE_SUMMARY, "Group storage visit", EventText::summary);
		line(GroupEvent.Type.STORAGE_MINIMUM, "Storage minimum hit", (e, l) -> "group storage is low on " + e.text
			+ ": " + l.amount(e.number) + " left" + (e.detail.isEmpty() ? "" : ", " + e.detail));
		line(GroupEvent.Type.STORAGE_LAST, "Took the last one", (e, l) -> "took the last of "
			+ StorageLog.describe(e.items, l) + " from group storage");
		line(GroupEvent.Type.LEVEL_UP, "Level up", (e, l) -> e.text + " level " + e.number);
		line(GroupEvent.Type.MAXED, "99!", (e, l) -> "total".equalsIgnoreCase(e.text)
			? "maxed, total level " + e.number : "99 " + e.text + "!");
		line(GroupEvent.Type.XP_MILESTONE, "XP milestone", (e, l) -> l.amount(e.number) + " " + e.text + " XP");
		line(GroupEvent.Type.COMBAT_LEVEL, "Combat level", (e, l) -> "combat level " + e.number);
		line(GroupEvent.Type.TOTAL_LEVEL, "Total level", (e, l) -> "total level " + e.number);
		line(GroupEvent.Type.QUEST, "Quest complete", (e, l) -> "completed " + e.text
			+ (e.number > 0 ? " (" + e.number + " QP)" : ""));
		line(GroupEvent.Type.QUEST_POINTS, "Quest points", (e, l) -> e.text.isEmpty()
			? e.number + " quest points" : e.text + ", " + e.number + " quest points");
		line(GroupEvent.Type.ONLINE, "Online", (e, l) -> isOffline(e) ? offline(e) : "is " + e.text
			+ onWorld(e));
		line(GroupEvent.Type.BACK, "Back", (e, l) -> "is back after " + e.number + (e.number == 1 ? " day" : " days"));
		line(GroupEvent.Type.BARROWS, "Barrows chest", (e, l) -> "Barrows chest" + (e.number > 0 ? " " + e.number : "")
			+ ": " + items(e, l) + (e.detail.isEmpty() ? "" : " (" + e.detail + ")"));
		line(GroupEvent.Type.RAID_UNIQUE, "Raid unique", (e, l) -> "purple! " + e.text
			+ (e.number > 0 ? ", raid count " + e.number : "") + (e.detail.isEmpty() ? "" : " (" + e.detail + ")"));
		line(GroupEvent.Type.CLUE, "Clue reward", (e, l) -> e.text + " clue reward: " + items(e, l)
			+ (e.detail.isEmpty() ? "" : " (" + e.detail + ")"));
		line(GroupEvent.Type.DRY_STREAK, "Dry streak", (e, l) -> e.number + " " + e.text + " kills without a unique"
			+ (e.detail.isEmpty() ? "" : " (" + e.detail + ")"));
		line(GroupEvent.Type.DEATH_VALUE, "Lost on death", EventText::deathValue);
		line(GroupEvent.Type.GRAVESTONE_EXPIRING, "Gravestone expiring", (e, l) -> "gravestone"
			+ (e.location.isEmpty() ? "" : " at " + e.location) + (e.world > 0 ? " on world " + e.world : "")
			+ " has about " + e.number + " min left" + graveItems(e, l));
		line(GroupEvent.Type.HC_LIFE_LOST, "Group life lost", (e, l) -> "lost a Hardcore group life, " + e.number
			+ (e.number == 1 ? " life" : " lives") + " left");
		line(GroupEvent.Type.WILDERNESS, "Wilderness", (e, l) -> e.text);
		line(GroupEvent.Type.DIARY, "Achievement diary", (e, l) -> "completed the " + e.text + " diary");
		line(GroupEvent.Type.COMBAT_TASK, "Combat achievement", (e, l) -> "combat task: " + e.text
			+ (e.detail.isEmpty() ? "" : " (" + e.detail + ")"));
		line(GroupEvent.Type.KC_MILESTONE, "Kill count milestone", (e, l) -> e.number + " " + e.text + " kills");
		line(GroupEvent.Type.PERSONAL_BEST, "New personal best", (e, l) -> "new personal best: " + e.text);
		line(GroupEvent.Type.WEEKLY_RECAP, "Weekly recap", (e, l) -> "this week: +" + l.amount(e.number) + " XP, "
			+ e.text);
		line(GroupEvent.Type.SLAYER, "Slayer", (e, l) -> slayer(e));
		line(GroupEvent.Type.FARMING, "Farming run", (e, l) -> ready(e));
		line(GroupEvent.Type.BIRDHOUSE, "Bird houses and Hespori", (e, l) -> ready(e));
		line(GroupEvent.Type.REQUEST, "Request", (e, l) -> RequestBoard.describe(e));
		line(GroupEvent.Type.ACTIVITY_START, "Activity started", (e, l) -> "started " + e.text + extra(e));
		line(GroupEvent.Type.ACTIVITY_WAVE, "Activity wave", (e, l) -> "reached " + e.detail + " in " + e.text);
		line(GroupEvent.Type.ACTIVITY_COMPLETE, "Activity completed", EventText::activityDone);
		line(GroupEvent.Type.ACTIVITY_DEATH, "Activity death", (e, l) -> "died in " + e.text + extra(e)
			+ (e.world > 0 ? " (world " + e.world + ")" : ""));
	}

	/** " (wave 58/69, 1h 12m)": the event's detail in brackets, or nothing. */
	private static String extra(GroupEvent e)
	{
		return e.detail.isEmpty() ? "" : " (" + e.detail + ")";
	}

	/** "completed The Inferno, kill count 3 (69/69, 1:58:12)" or "left Fortis Colosseum (claimed loot after wave 7)". */
	private static String activityDone(GroupEvent e, ItemLookup lookup)
	{
		return (e.number > 0 ? "completed " + e.text + ", kill count " + e.number : "left " + e.text) + extra(e);
	}

	private static boolean isOffline(GroupEvent e)
	{
		return e.type == GroupEvent.Type.ONLINE && "offline".equals(e.text);
	}

	private static String onWorld(GroupEvent e)
	{
		return e.world > 0 ? " on world " + e.world : "";
	}

	/** "offline, played 1h 12m on world 303, logged off at 1:35 PM": the clock is the logout, not the post. */
	private static String offline(GroupEvent e)
	{
		// 0 is also an older client's offline, from the party: no session known, so none said.
		return "offline" + (e.number > 0 ? ", played " + PresenceDebounce.played(e.number) : "") + onWorld(e)
			+ (e.detail.isEmpty() ? "" : ", logged off at " + e.detail);
	}

	/**
	 * "New Slayer task: 19 x Icefiends (Turael)" or "Slayer task done: Icefiends (streak 1, 2 points)"
	 * ({@link SlayerWatch}). An older member's client sends "task done" and "new task: X", worded as it was.
	 */
	private static String slayer(GroupEvent e)
	{
		if ("task done".equals(e.text) || e.text.startsWith("new task: "))
		{
			return "slayer " + e.text + (e.number > 0 ? " (" + e.number + ")" : "");
		}
		String extra = e.detail.isEmpty() ? "" : " (" + e.detail + ")";
		return e.number > 0 ? "New Slayer task: " + e.number + " x " + e.text + extra : "Slayer task done: " + e.text + extra;
	}

	private static String ready(GroupEvent e)
	{
		return e.text + " ready" + (e.detail.isEmpty() ? "" : ": " + e.detail);
	}

	private static String deathValue(GroupEvent e, ItemLookup lookup)
	{
		return "lost about " + lookup.amount(e.number) + " gp on death" + (e.location.isEmpty() ? "" : " at " + e.location)
			+ (e.detail.isEmpty() ? "" : " (" + e.detail + ")");
	}

	/** Items shown on a gravestone warning: the most valuable few, as "Lost on death" counted them. */
	static final int GRAVE_TOP = 3;

	/** "; in it: 1 x Abyssal whip, 13.2K x Coins and 2 more (1.6M gp)": empty when the death was not counted. */
	private static String graveItems(GroupEvent e, ItemLookup lookup)
	{
		if (e.items.isEmpty())
		{
			return "";
		}
		List<Map.Entry<Integer, Integer>> ranked = new ArrayList<>(e.items.entrySet());
		ranked.sort(Comparator.comparingLong((Map.Entry<Integer, Integer> i) -> lookup.price(i.getKey()) * i.getValue())
			.reversed().thenComparing(Map.Entry::getKey));
		List<String> parts = new ArrayList<>();
		for (Map.Entry<Integer, Integer> i : ranked.subList(0, Math.min(GRAVE_TOP, ranked.size())))
		{
			parts.add(Amounts.GAME.of(i.getValue()) + " x " + lookup.name(i.getKey()));
		}
		int more = ranked.size() - parts.size();
		long value = value(e.items, lookup);
		return "; in it: " + String.join(", ", parts) + (more > 0 ? " and " + more + " more" : "")
			+ (value > 0 ? " (" + Amounts.GAME.of(value) + " gp)" : "");
	}

	private EventText()
	{
	}

	private static void line(GroupEvent.Type type, String title, BiFunction<GroupEvent, ItemLookup, String> line)
	{
		TITLES.put(type, title);
		LINES.put(type, line);
	}

	/** What happened, without the member: "Vorkath dropped 1 x Draconic visage (1.2M)". */
	static String describe(GroupEvent e, ItemLookup lookup)
	{
		return LINES.get(e.type).apply(e, lookup);
	}

	/** "Alex: Vorkath dropped ..." */
	static String sentence(GroupEvent e, ItemLookup lookup)
	{
		return e.member + ": " + describe(e, lookup);
	}

	/** A short heading for an embed or a toast. */
	static String title(GroupEvent.Type type)
	{
		return TITLES.get(type);
	}

	/** The heading for this event: "Offline" for a logout, where the type alone would say "Online". */
	static String title(GroupEvent e)
	{
		return isOffline(e) ? "Offline" : title(e.type);
	}

	/** Every type has words; a new type without them fails EventTextTest, not a player's client. */
	static boolean covers(GroupEvent.Type type)
	{
		return LINES.containsKey(type) && TITLES.containsKey(type);
	}

	/**
	 * "1 x Draconic visage (1.2M gp)": the items and their total value when any is known. The total is
	 * always the game's short form: Discord's exact total is its own Value field, and a short total keeps
	 * "40K (40,000) x Coins (40K gp)" from nesting parentheses.
	 */
	static String items(GroupEvent e, ItemLookup lookup)
	{
		long value = value(e.items, lookup);
		return StorageLog.describe(e.items, lookup) + (value > 0 ? " (" + Amounts.GAME.of(value) + " gp)" : "");
	}

	/** Total value at the lookup's prices. */
	static long value(Map<Integer, Integer> items, ItemLookup lookup)
	{
		long total = 0;
		for (Map.Entry<Integer, Integer> e : items.entrySet())
		{
			total += lookup.price(e.getKey()) * e.getValue();
		}
		return total;
	}

	private static String kc(GroupEvent e)
	{
		return e.number > 0 ? ", kill count " + e.number : "";
	}

	private static String death(GroupEvent e, ItemLookup lookup)
	{
		StringBuilder out = new StringBuilder("died");
		if (!e.location.isEmpty())
		{
			out.append(" at ").append(e.location);
		}
		if (!e.text.isEmpty())
		{
			out.append(", killed by ").append(e.text);
		}
		if (e.world > 0)
		{
			out.append(" (world ").append(e.world).append(')');
		}
		if (e.number == GroupEvent.LIFE_LOST)
		{
			out.append(". The group lost a life.");
		}
		return out.toString();
	}

	private static String summary(GroupEvent e, ItemLookup lookup)
	{
		StringBuilder out = new StringBuilder("group storage:");
		if (!e.taken.isEmpty())
		{
			out.append(" took ").append(StorageLog.describe(e.taken, lookup));
		}
		if (!e.items.isEmpty())
		{
			out.append(e.taken.isEmpty() ? " deposited " : "; deposited ").append(StorageLog.describe(e.items, lookup));
		}
		return out.toString();
	}

	static String plain(String message)
	{
		return message == null ? "" : TAG.matcher(message).replaceAll("").trim();
	}

	/** A pet message, from a game message only. */
	static boolean isPet(String message)
	{
		String text = plain(message);
		for (String pet : PET_MESSAGES)
		{
			if (text.startsWith(pet))
			{
				return true;
			}
		}
		return false;
	}

	/** A kill or chest count line: the name ("Vorkath", "Barrows") and the count; null when not one. */
	static Count killCount(String message)
	{
		String text = plain(message);
		Matcher m = KILL_COUNT.matcher(text);
		if (!m.matches())
		{
			m = RAID_COUNT.matcher(text);
			if (!m.matches())
			{
				return null;
			}
		}
		try
		{
			return new Count(m.group(1).trim(), Long.parseLong(m.group(2).replace(",", "")));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** The quest name from the quest scroll's title, or the whole title when it reads some other way. */
	static String questName(String title)
	{
		String text = plain(title);
		Matcher m = QUEST.matcher(text);
		return m.matches() ? m.group(1).trim() : text;
	}

	static final class Count
	{
		final String name;
		final long count;

		Count(String name, long count)
		{
			this.name = name;
			this.count = count;
		}
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * A member's other Discord posts grouped like their level-ups (Board 2026-11-15: "everything needs to do that"): per
 * member and per kind of event ({@link #family}), the first moment posts and later ones within the window edit that
 * same message. Most kinds add an embed card each, the newest on top, up to {@link #MAX_CARDS} (Discord's limit on
 * embeds); the next moment past that starts a new message. Group storage visits net out instead: one card, the items
 * moved summed per item over every visit ("took 2 x Rope", then "deposited 10 x Rope", reads "deposited 8 x Rope"),
 * with the list of visits under it.
 *
 * <p>A moment that pings the configured mention never joins: it starts a message of its own, so the ping goes
 * (an edit never pings). Posting, editing, refusals and the restart file are {@link EditedThreads}'; a saved line is
 * one JSON object.
 */
final class EventThreads extends EditedThreads<EventThreads.Feed, EventThreads.Edit>
{
	/** Group storage's family: its moments net out into one card. */
	static final String STORAGE = "STORAGE";
	/** Visits listed under a storage card, newest first; Discord caps the field anyway ({@link DiscordMerge#MAX_FIELD}). */
	static final int MAX_MOVES = 25;
	/** Marks a saved line of this format. */
	private static final int VERSION = 1;

	private final Gson gson;

	EventThreads(Gson gson)
	{
		this.gson = gson;
	}

	/**
	 * Which message a kind of event groups into, or null for a kind that always posts on its own: online and offline
	 * (they have their own once-per-10-minutes rule), the gravestone warning (a timer that must notify) and the
	 * weekly recap (a summary already). Everything else groups by its category, with slayer tasks on their own.
	 */
	static String family(GroupEvent.Type type)
	{
		switch (type)
		{
			case ONLINE:
			case BACK:
			case GRAVESTONE_EXPIRING:
			case WEEKLY_RECAP:
				return null;
			case SLAYER:
				return "SLAYER";
			default:
				return type.category.name();
		}
	}

	/** The facts of a moment's lead event a storage card is drawn from: whose, when, the world and place. */
	static final class Lead
	{
		final GroupEvent.Type type;
		final long at;
		final String member;
		final int world;
		final String location;
		final boolean broadcast;

		Lead(GroupEvent e)
		{
			this.type = e.type;
			this.at = e.at;
			this.member = e.member;
			this.world = e.world;
			this.location = e.location;
			this.broadcast = e.broadcast;
		}

		GroupEvent event()
		{
			return GroupEvent.of(type, at, member).world(world).location(location).broadcast(broadcast).build();
		}
	}

	/** One card of a message: the moment's embed, and its line for plain style. */
	static final class Card
	{
		final String embed;
		final String line;

		Card(String embed, String line)
		{
			this.embed = embed;
			this.line = line;
		}
	}

	/** One moment going to Discord, already worded: what it adds to its member's message. */
	static final class Moment
	{
		final String member;
		final String family;
		final String url;
		/** The poster name its first post goes under; a replacement post uses it too. Null for the webhook's own. */
		final String username;
		/** It pings the configured mention: it never joins a message, so the ping goes. */
		final boolean pings;
		final Card card;
		/** Storage: what the visit took and deposited; empty otherwise. */
		final Map<Integer, Integer> taken;
		final Map<Integer, Integer> deposited;
		/** Storage: the visit's line in the list of visits ("took 2 x Rope"). */
		final String move;
		final Lead lead;
		/** Storage: the visit's other facts (its minimum and last-one lines), {title, line} each. */
		final List<String[]> extras;

		Moment(String family, String url, String username, boolean pings, Card card, GroupEvent lead,
			List<String[]> extras, String move)
		{
			this.member = lead.member;
			this.family = family;
			this.url = url;
			this.username = username;
			this.pings = pings;
			this.card = card;
			boolean visit = lead.type == GroupEvent.Type.STORAGE_SUMMARY;
			this.taken = visit ? lead.taken : Collections.emptyMap();
			this.deposited = visit ? lead.items : Collections.emptyMap();
			this.move = move;
			this.lead = new Lead(lead);
			this.extras = extras;
		}
	}

	/** One member's message for one family. Read and written only under the owner's lock. */
	static final class Feed extends EditedThreads.Message
	{
		final String family;
		String username;
		/** Its cards, the newest first. Storage keeps none: its one card is drawn from {@link #net}. */
		final List<Card> cards = new ArrayList<>();
		/** Storage: each item's amount over every visit, deposits positive; zeros are dropped. */
		final Map<Integer, Long> net = new TreeMap<>();
		/** Storage: each visit's line, the newest first. */
		final List<String> moves = new ArrayList<>();
		Lead lead;
		List<String[]> extras = Collections.emptyList();

		private Feed(Moment m, long now, byte[] png)
		{
			super(m.member, m.url, now, png);
			this.family = m.family;
		}

		private Feed(Saved s)
		{
			super(s.hook, s.member, s.first, s.last, s.id);
			this.family = s.family;
			this.username = s.username;
			cards.addAll(s.cards);
			net.putAll(s.net);
			moves.addAll(s.moves);
			this.lead = s.lead;
			this.extras = s.extras;
		}

		boolean storage()
		{
			return STORAGE.equals(family);
		}

		/** Room for one more moment: storage always has it, others while under {@link #MAX_CARDS}. */
		private boolean fits()
		{
			return storage() || cards.size() < MAX_CARDS;
		}

		private void add(Moment m)
		{
			username = m.username;
			lead = m.lead;
			extras = m.extras;
			if (!storage())
			{
				cards.add(0, m.card);
				return;
			}
			m.taken.forEach((id, n) -> net.merge(id, -(long) n, Long::sum));
			m.deposited.forEach((id, n) -> net.merge(id, (long) n, Long::sum));
			net.values().removeIf(n -> n == 0);
			if (m.move != null && !m.move.isEmpty())
			{
				moves.add(0, m.move);
				if (moves.size() > MAX_MOVES)
				{
					moves.subList(MAX_MOVES, moves.size()).clear();
				}
			}
		}
	}

	/** What one post or edit of a message says, frozen when it is handed out: safe to read off the lock. */
	static final class Edit
	{
		final Feed feed;
		final String url;
		final String messageId;
		final String username;
		final boolean storage;
		/** Copies of the cards, newest first. */
		final List<Card> cards;
		final Map<Integer, Long> net;
		final List<String> moves;
		final Lead lead;
		final List<String[]> extras;
		final byte[] png;

		private Edit(Feed f)
		{
			this.feed = f;
			this.url = f.url;
			this.messageId = f.messageId;
			this.username = f.username;
			this.storage = f.storage();
			this.cards = Collections.unmodifiableList(new ArrayList<>(f.cards.subList(0,
				Math.min(MAX_CARDS, f.cards.size()))));
			this.net = Collections.unmodifiableMap(new TreeMap<>(f.net));
			this.moves = Collections.unmodifiableList(new ArrayList<>(f.moves));
			this.lead = f.lead;
			this.extras = f.extras;
			this.png = f.png;
		}
	}

	/** A {@link Feed} as its saved line holds it. */
	private static final class Saved
	{
		int v;
		String hook;
		String member;
		String family;
		long first;
		long last;
		String id;
		String username;
		List<Card> cards = new ArrayList<>();
		Map<Integer, Long> net = new TreeMap<>();
		List<String> moves = new ArrayList<>();
		Lead lead;
		List<String[]> extras = new ArrayList<>();

		/** Written by this format, with a message to edit and what its card is drawn from. */
		boolean complete()
		{
			return v == VERSION && hook != null && member != null && family != null && id != null && !id.isEmpty()
				&& lead != null && lead.type != null && lists();
		}

		/** Gson leaves a list null only for a line that names it null: never one of ours. */
		private boolean lists()
		{
			return cards != null && net != null && moves != null && extras != null;
		}
	}

	/**
	 * One moment into its member's message for its family: joined when that message is open on the same webhook,
	 * within {@code window} ms of its first post, has room, and the moment does not ping (null back; {@link #due}
	 * edits it in time). Otherwise a new message, its first post returned: send it and report back to
	 * {@link #posted} with {@link Edit#feed}.
	 */
	synchronized Edit add(Moment m, byte[] png, long now, long window)
	{
		Feed f = open.get(key(m.member, m.family));
		if (f != null && !m.pings && f.open(m.url, now, window) && f.fits())
		{
			f.add(m);
			f.grew(m.url, now, png);
			changed = true;
			return null;
		}
		Feed fresh = new Feed(m, now, png);
		fresh.add(m);
		return start(fresh);
	}

	private static String key(String member, String family)
	{
		return family + '\t' + member;
	}

	@Override
	String key(Feed f)
	{
		return key(f.member, f.family);
	}

	@Override
	Edit snapshot(Feed f)
	{
		return new Edit(f);
	}

	@Override
	String line(Feed f)
	{
		Saved s = new Saved();
		s.v = VERSION;
		s.hook = f.hook;
		s.member = f.member;
		s.family = f.family;
		s.first = f.first;
		s.last = f.last;
		s.id = f.messageId;
		s.username = f.username;
		s.cards = f.cards;
		s.net = f.net;
		s.moves = f.moves;
		s.lead = f.lead;
		s.extras = f.extras;
		// Gson escapes every newline inside a string, so one message is always one line.
		return gson.toJson(s);
	}

	@Override
	Feed parse(String line)
	{
		try
		{
			Saved s = gson.fromJson(line, Saved.class);
			return s != null && s.complete() ? new Feed(s) : null;
		}
		catch (JsonParseException | IllegalStateException | NumberFormatException e)
		{
			return null;
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Event banners: one title and one line per event, newest on top, each for
 * the configured time. Draws only what {@link ToastQueue} says is visible;
 * the text is built when the event arrives, not every frame.
 */
final class EventToastOverlay extends OverlayPanel
{
	private final ToastQueue toasts;
	private final GroupIronmanConfig config;
	private final ItemLookup lookup;
	private final Supplier<EasterEggs.Settings> eggs;

	EventToastOverlay(ToastQueue toasts, GroupIronmanConfig config, ItemLookup lookup,
		Supplier<EasterEggs.Settings> eggs)
	{
		this.toasts = toasts;
		this.config = config;
		this.lookup = lookup;
		this.eggs = eggs;
		setPosition(config.overlayPosition().position);
	}

	void reposition()
	{
		setPosition(config.overlayPosition().position);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<ToastQueue.Toast> visible = toasts.visible(System.currentTimeMillis(),
			TimeUnit.SECONDS.toMillis(config.overlayDurationSeconds()), config.overlayMaxStacked(), e -> true);
		if (visible.isEmpty())
		{
			return null;
		}
		EasterEggs.Settings egg = eggs.get();
		for (ToastQueue.Toast t : visible)
		{
			panelComponent.getChildren().add(TitleComponent.builder()
				.text(t.event.member + ": " + EventText.title(t.event))
				.color(new Color(t.event.type.category.colour))
				.build());
			panelComponent.getChildren().add(LineComponent.builder().left(EasterEggs.tagged(EventText.describe(t.event, lookup), t.event, egg))
				.build());
		}
		return super.render(graphics);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.function.Consumer;
import java.util.function.IntUnaryOperator;
import java.util.function.Predicate;
import net.runelite.api.gameval.VarbitID;

/**
 * Part C's detectors: what the game told this client, turned into at most one
 * event per occurrence. Pure: the client's values come in as arguments, and
 * events leave through one consumer that a kind's switch guards. Client
 * thread only.
 *
 * <p>Variables are polled, and the first poll after a login is only a
 * baseline, so a login's burst of values is never read as progress.
 */
final class EventWatchers
{
	/** Stands in for the skull icon among the polled variables. Negative, so no varbit can share it. */
	static final int SKULL = -1;
	static final int TICKS_PER_MINUTE = 100;
	/** 15 minutes (https://oldschool.runescape.wiki/w/Gravestone, 2026-11-09). Ticks only pass while logged in, as the grave's timer does. */
	static final int GRAVE_TICKS = 15 * TICKS_PER_MINUTE;
	/** Ticks after a death before what is still carried is counted: the respawn has moved the rest by then. */
	static final int DEATH_SETTLE_TICKS = 10;

	private static final Map<Integer, String> DIARIES = new HashMap<>();

	static
	{
		tier("Ardougne", VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE,
			VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE);
		tier("Desert", VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE,
			VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_DIARY_ELITE_COMPLETE);
		tier("Falador", VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE,
			VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_DIARY_ELITE_COMPLETE);
		tier("Fremennik", VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE,
			VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE);
		tier("Kandarin", VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE,
			VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE);
		tier("Karamja", VarbitID.ATJUN_EASY_DONE, VarbitID.ATJUN_MED_DONE, VarbitID.ATJUN_HARD_DONE,
			VarbitID.KARAMJA_DIARY_ELITE_COMPLETE);
		tier("Kourend", VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE,
			VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_DIARY_ELITE_COMPLETE);
		tier("Lumbridge", VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE,
			VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE);
		tier("Morytania", VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE,
			VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE);
		tier("Varrock", VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE,
			VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_DIARY_ELITE_COMPLETE);
		tier("Western", VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE,
			VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_DIARY_ELITE_COMPLETE);
		tier("Wilderness", VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE,
			VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE);
	}

	private final Consumer<GroupEvent> out;
	private final Predicate<GroupEvent.Type> wanted;
	private final Map<Integer, Integer> last = new HashMap<>();
	private final Map<String, Long> clueCounts = new LinkedHashMap<>();
	private boolean baselined;
	/** False while a login settles ({@link LoginGate}): polls only record. A new watcher counts. */
	private boolean counting = true;
	private boolean specialHeader;
	private String pendingClue;
	private String raid = "";
	private long raidKc;
	private String lastKcName = "";
	private long lastKcCount = -1;
	private Map<Integer, Integer> carriedAtDeath;
	private int settle;
	private int graveLeft;
	private boolean graveSeen;
	/** What the death cost, once counted: the grave's contents, as far as this client knows. */
	private Map<Integer, Integer> graveItems = Collections.emptyMap();
	private String graveWhere = "";
	private int graveWorld;
	private String deathWhere = "";
	private int deathWorld;
	private final SlayerWatch slayer = new SlayerWatch(this::emit);

	EventWatchers(Consumer<GroupEvent> out, Predicate<GroupEvent.Type> wanted)
	{
		this.out = out;
		this.wanted = wanted;
	}

	private static void tier(String area, int easy, int medium, int hard, int elite)
	{
		DIARIES.put(easy, area + " easy");
		DIARIES.put(medium, area + " medium");
		DIARIES.put(hard, area + " hard");
		DIARIES.put(elite, area + " elite");
	}

	private void emit(GroupEvent event)
	{
		if (wanted.test(event.type))
		{
			out.accept(event);
		}
	}

	/** Another account may log in next: every baseline starts over, and so does everything it was in the middle of. */
	void reset()
	{
		rebaseline();
		clueCounts.clear();
		specialHeader = false;
		pendingClue = null;
		raid = "";
		raidKc = 0;
		lastKcName = "";
		lastKcCount = -1;
		carriedAtDeath = null;
		settle = 0;
		graveLeft = 0;
		graveSeen = false;
		graveItems = Collections.emptyMap();
		slayer.reset();
	}

	/**
	 * The polled values only: the next poll is a baseline, and none counts until {@link #settle}. A hop or a lost
	 * connection keeps the rest (a grave's timer, a raid's count) for the same account.
	 */
	void rebaseline()
	{
		last.clear();
		baselined = false;
		counting = false;
	}

	/** A login is settling: polls only record until {@link #settle}, so a varbit sent a few ticks late is no rise. */
	void quiet()
	{
		counting = false;
	}

	/** The login has settled: a polled value that goes up from here on is an event. */
	void settle()
	{
		counting = true;
	}

	// ---- Chat ----

	/** One game line. {@code group}: other members of this group; {@code present}: players in the instance now. */
	void chat(String message, long now, String me, Set<String> group, Collection<String> present)
	{
		raidLine(message, now, me, group, present);
		EventText.Count clue = EventChat.clue(message);
		if (clue != null)
		{
			clueCounts.put(clue.name, clue.count);
			pendingClue = clue.name;
			return;
		}
		String best = EventChat.personalBest(message);
		if (best != null)
		{
			emit(GroupEvent.of(GroupEvent.Type.PERSONAL_BEST, now, me).text(best).build());
			return;
		}
		String[] task = EventChat.combatTask(message);
		if (task != null)
		{
			emit(GroupEvent.of(GroupEvent.Type.COMBAT_TASK, now, me).text(task[1]).detail(task[0]).build());
			return;
		}
		slayer.chat(message, now, me);
	}

	/** Each tick: the NPC dialogue open now (null text when none), for a master handing out a Slayer task. */
	void slayerDialog(String text, String npc, long now, String me)
	{
		slayer.dialog(text, npc, now, me);
	}

	/** Each tick, for a finished Slayer task whose streak line never came. */
	void slayerTick(long now, String me)
	{
		slayer.tick(now, me);
	}

	private void raidLine(String message, long now, String me, Set<String> group, Collection<String> present)
	{
		if (EventChat.isSpecialLootHeader(message))
		{
			specialHeader = true;
			return;
		}
		String[] loot = EventChat.raidSpecial(message);
		if (loot == null && specialHeader)
		{
			loot = EventChat.raidDash(message);
		}
		specialHeader = false;
		// A teammate's purple is theirs to post (BRIEF.md #18).
		if (loot != null && loot[0].equalsIgnoreCase(me))
		{
			emit(GroupEvent.of(GroupEvent.Type.RAID_UNIQUE, now, me).text(loot[1]).number(raidKc)
				.detail(raidDetail(me, group, present)).build());
		}
	}

	/** "Theatre of Blood; with Sam +1 other": names only for this group's members; anyone else is only counted. */
	private String raidDetail(String me, Set<String> group, Collection<String> present)
	{
		String with = TeamSummary.of(me, group, present).with();
		return raid.isEmpty() || with.isEmpty() ? raid + with : raid + "; " + with;
	}

	/** The raid's own count line, which comes before its loot line. */
	void raidCount(String name, long count)
	{
		raid = name;
		raidKc = count;
	}

	/** The clue reward screen: at most one event for each completed-count line. */
	void clueReward(Map<Integer, Integer> items, long value, long now, String me)
	{
		if (pendingClue == null)
		{
			return;
		}
		String tier = pendingClue;
		pendingClue = null;
		StringBuilder counts = new StringBuilder();
		for (Map.Entry<String, Long> e : clueCounts.entrySet())
		{
			counts.append(counts.length() == 0 ? "" : ", ").append(e.getKey()).append(' ').append(e.getValue());
		}
		emit(GroupEvent.of(GroupEvent.Type.CLUE, now, me).text(tier).items(items).number(value)
			.detail(counts.toString()).build());
	}

	/** A kill count line. The game can repeat one, so the same boss and count is one milestone. */
	void kill(String name, long count, int every, long now, String me)
	{
		boolean repeat = name.equalsIgnoreCase(lastKcName) && count == lastKcCount;
		lastKcName = name;
		lastKcCount = count;
		if (!repeat && every > 0 && count > 0 && count % every == 0)
		{
			emit(GroupEvent.of(GroupEvent.Type.KC_MILESTONE, now, me).text(name).number(count).build());
		}
	}

	// ---- Variables ----

	/** Every polled variable that went up since the last poll, as events. The first poll, and any while quiet, only record. */
	void poll(IntUnaryOperator read, long now, String me)
	{
		Map<Integer, Boolean> rose = new TreeMap<>();
		for (int id : polled())
		{
			int value = read.applyAsInt(id);
			Integer before = last.put(id, value);
			rose.put(id, baselined && before != null && value > before);
		}
		if (!baselined || !counting)
		{
			baselined = true;
			return;
		}
		fire(rose, read, now, me);
	}

	private static List<Integer> polled()
	{
		List<Integer> ids = new ArrayList<>(DIARIES.keySet());
		ids.add(SKULL);
		ids.add(VarbitID.INSIDE_WILDERNESS);
		ids.add(VarbitID.GIM_HARDCORE_DEATHS);
		return ids;
	}

	private void fire(Map<Integer, Boolean> rose, IntUnaryOperator read, long now, String me)
	{
		for (Map.Entry<Integer, String> diary : DIARIES.entrySet())
		{
			if (rose.get(diary.getKey()))
			{
				emit(GroupEvent.of(GroupEvent.Type.DIARY, now, me).text(diary.getValue()).build());
			}
		}
		if (rose.get(VarbitID.INSIDE_WILDERNESS))
		{
			emit(GroupEvent.of(GroupEvent.Type.WILDERNESS, now, me).text("entered the Wilderness").build());
		}
		if (rose.get(SKULL))
		{
			emit(GroupEvent.of(GroupEvent.Type.WILDERNESS, now, me).text("got skulled").build());
		}
		if (rose.get(VarbitID.GIM_HARDCORE_DEATHS))
		{
			int lives = read.applyAsInt(VarbitID.GIM_GROUPSIZE) - read.applyAsInt(VarbitID.GIM_HARDCORE_DEATHS);
			emit(GroupEvent.of(GroupEvent.Type.HC_LIFE_LOST, now, me).number(Math.max(0, lives)).build());
		}
	}

	// ---- Death and the gravestone ----

	/** The local player died, holding {@code carried}. Starts the value count and the gravestone's timer. */
	void died(Map<Integer, Integer> carried, String where, int world)
	{
		carriedAtDeath = new TreeMap<>(carried);
		settle = DEATH_SETTLE_TICKS;
		deathWhere = where;
		deathWorld = world;
		graveLeft = GRAVE_TICKS;
		graveSeen = false;
		graveItems = Collections.emptyMap();
		graveWhere = where;
		graveWorld = world;
	}

	/** Each tick after a death: once settled, what no longer is carried is what the death cost. */
	void deathTick(Map<Integer, Integer> carriedNow, ItemLookup lookup, long now, String me)
	{
		if (carriedAtDeath == null || --settle > 0)
		{
			return;
		}
		Map<Integer, Integer> lost = new TreeMap<>();
		for (Map.Entry<Integer, Integer> e : carriedAtDeath.entrySet())
		{
			int gone = e.getValue() - carriedNow.getOrDefault(e.getKey(), 0);
			if (gone > 0)
			{
				lost.put(e.getKey(), gone);
			}
		}
		carriedAtDeath = null;
		if (graveLeft > 0)
		{
			graveItems = lost;
			// Nothing left the player (nothing to lose, or a safe death): the game spawns no grave to warn about.
			if (lost.isEmpty())
			{
				graveLeft = 0;
			}
		}
		emit(GroupEvent.of(GroupEvent.Type.DEATH_VALUE, now, me).items(lost).number(EventText.value(lost, lookup))
			.location(deathWhere).world(deathWorld).detail("gravestone: 15 min").build());
	}

	/**
	 * Each tick while a grave may be out. {@code visible} is the game's grave varbit: once it has been seen on,
	 * its going off means the grave was collected. If it is never seen on, no grave spawned (a safe or instanced
	 * death) and nothing is warned (Board 2026-11-10: only warn when a gravestone exists for that death).
	 */
	void graveTick(int visible, int warnMinutes, long now, String me)
	{
		if (graveLeft <= 0)
		{
			return;
		}
		if (visible != 0)
		{
			graveSeen = true;
		}
		else if (graveSeen)
		{
			graveLeft = 0;
			return;
		}
		graveLeft--;
		if (graveLeft == warnMinutes * TICKS_PER_MINUTE)
		{
			graveLeft = 0;
			if (!graveSeen)
			{
				return;
			}
			emit(GroupEvent.of(GroupEvent.Type.GRAVESTONE_EXPIRING, now, me).number(warnMinutes).location(graveWhere)
				.world(graveWorld).items(graveItems).build());
		}
	}

	/** True while a grave is out and its warning has not gone yet. */
	boolean graveOut()
	{
		return graveLeft > 0;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.Consumer;
import java.util.function.IntUnaryOperator;
import java.util.function.Predicate;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Timers for this player's herb, tree and Hespori patches and bird houses.
 *
 * <p>Follows the core Time Tracking plugin (runelite-client, master, read
 * 2026-11-09, BSD 2-Clause; see THIRD_PARTY_NOTICES.md): the growth values and
 * cycles are {@code PatchImplementation} and {@code Produce}, the places are
 * {@code FarmingWorld}, the ready time is {@code FarmingTracker.getTickTime},
 * and the bird house rules are {@code BirdHouseTracker}.
 *
 * <p>Two things are not modelled. Time Tracking learns each account's growth
 * offset by watching a patch change, and without it a crop is called ready at
 * the unshifted cycle, which is no earlier than the true one. And a crop can
 * catch disease out of sight, so "ready" means it will have finished growing
 * if it stayed healthy, as in Time Tracking.
 *
 * <p>Pure: the client's values come in as arguments and events leave through
 * one consumer that a kind's switch guards. Client thread only.
 */
final class FarmRuns
{
	/** A patch's reading is rechecked this often while the player stands near it, as Time Tracking does. */
	static final long REFRESH_SECONDS = 5 * 60L;
	private static final int HERB_STAGES = 5;
	private static final int HERB_MINUTES = 20;
	private static final int TREE_MINUTES = 40;
	private static final int HESPORI_STAGES = 4;
	private static final int HESPORI_MINUTES = 640;
	private static final int BIRD_SECONDS = 50 * 60;
	/** Nine kinds of bird house, three values each ({@code BirdHouseState}). */
	private static final int BIRD_MAX_VALUE = 27;
	/** Dropping from three or four houses to none only happens when the varps have not arrived yet. */
	private static final int BIRD_MAX_REMOVED = 2;
	private static final int[] HERB_STARTS = {4, 11, 18, 25, 32, 39, 46, 53, 60, 68, 75, 82, 89, 96, 103, 192};
	private static final int[][] TREES = {{8, 5}, {15, 7}, {24, 9}, {35, 11}, {48, 13}};
	private static final int HESPORI_START = 4;
	private static final int PLANE_GROUND = 0;
	private static final List<Integer> FOSSIL_ISLAND = Arrays.asList(14650, 14651, 14652, 14906, 14907, 15162, 15163);
	private static final Bounds ANYWHERE = (x, y, plane) -> true;

	enum Kind
	{
		HERB("Herbs", GroupEvent.Type.FARMING),
		TREE("Trees", GroupEvent.Type.FARMING),
		HESPORI("Hespori", GroupEvent.Type.BIRDHOUSE),
		BIRD("Bird houses", GroupEvent.Type.BIRDHOUSE);

		final String label;
		final GroupEvent.Type type;

		Kind(String label, GroupEvent.Type type)
		{
			this.label = label;
			this.type = type;
		}
	}

	@FunctionalInterface
	private interface Bounds
	{
		boolean contains(int x, int y, int plane);
	}

	private static final class Patch
	{
		final String key;
		final String place;
		final int variable;
		final Kind kind;
		final Bounds bounds;

		Patch(String place, int region, int variable, Kind kind, Bounds bounds)
		{
			this.key = region + "." + variable;
			this.place = place;
			this.variable = variable;
			this.kind = kind;
			this.bounds = bounds;
		}
	}

	/** A crop still growing, and when it will have finished. */
	static final class Crop
	{
		final int stage;
		final int stages;
		private final int minutes;

		private Crop(int stage, int stages, int minutes)
		{
			this.stage = stage;
			this.stages = stages;
			this.minutes = minutes;
		}

		long readyAt(long seen)
		{
			if (minutes == 0)
			{
				return seen + BIRD_SECONDS;
			}
			long cycle = minutes * 60L;
			return seen - seen % cycle + (stages - 1 - stage) * cycle;
		}
	}

	private static final class Timer
	{
		final Patch patch;
		final int value;
		long seen;
		long readyAt;
		boolean fired;

		Timer(Patch patch, int value, long seen, long readyAt, boolean fired)
		{
			this.patch = patch;
			this.value = value;
			this.seen = seen;
			this.readyAt = readyAt;
			this.fired = fired;
		}
	}

	private static final Map<Integer, List<Patch>> PATCHES = new HashMap<>();
	private static final Map<String, Patch> BY_KEY = new HashMap<>();
	private static final List<Patch> BIRDS = new ArrayList<>();

	static
	{
		herb("Ardougne", VarbitID.FARMING_TRANSMIT_D, 10548);
		patch("Catherby", VarbitID.FARMING_TRANSMIT_D, Kind.HERB, FarmRuns::catherbyGround, 11062, 11061, 11318, 11317);
		herb("Civitas illa Fortis", VarbitID.FARMING_TRANSMIT_D, 6192, 6447, 6448, 6449, 6191, 6193);
		// Not on the region's edge: south of here is Port Sarim's spirit tree patch.
		patch("Falador", VarbitID.FARMING_TRANSMIT_D, Kind.HERB, (x, y, plane) -> y >= 3272, 12083);
		herb("Kourend", VarbitID.FARMING_TRANSMIT_D, 6967, 6711);
		herb("Morytania", VarbitID.FARMING_TRANSMIT_D, 14391, 14390);
		herb("Harmony", VarbitID.FARMING_TRANSMIT_B, 15148);
		herb("Troll Stronghold", VarbitID.FARMING_TRANSMIT_A, 11321);
		herb("Weiss", VarbitID.FARMING_TRANSMIT_A, 11325);
		herb("Farming Guild", VarbitID.FARMING_TRANSMIT_E, 4922, 5177, 5178, 5179, 4921, 4923, 4665, 4666, 4667);

		tree("Auburnvale", VarbitID.FARMING_TRANSMIT_A, 5427, 5428, 5684);
		tree("Falador", VarbitID.FARMING_TRANSMIT_A, 11828, 12084);
		tree("Gnome Stronghold", VarbitID.FARMING_TRANSMIT_A, 9781, 9782, 9526, 9525);
		tree("Lumbridge", VarbitID.FARMING_TRANSMIT_A, 12594, 12850);
		tree("Taverley", VarbitID.FARMING_TRANSMIT_A, 11573, 11829);
		tree("Varrock", VarbitID.FARMING_TRANSMIT_A, 12854, 12853);
		tree("Farming Guild", VarbitID.FARMING_TRANSMIT_G, 4922, 5177, 5178, 5179, 4921, 4923, 4665, 4666, 4667);

		patch("Farming Guild", VarbitID.FARMING_TRANSMIT_J, Kind.HESPORI, ANYWHERE, 5021);

		bird("Mushroom Meadow (North)", VarPlayerID.BIRDHOUSE_TRANSMIT_A);
		bird("Mushroom Meadow (South)", VarPlayerID.BIRDHOUSE_TRANSMIT_B);
		bird("Verdant Valley (Northeast)", VarPlayerID.BIRDHOUSE_TRANSMIT_C);
		bird("Verdant Valley (Southwest)", VarPlayerID.BIRDHOUSE_TRANSMIT_D);
	}

	private static boolean catherbyGround(int x, int y, int plane)
	{
		// Upstairs in this corner the same variables mean another patch.
		if (x >= 2816 && y < 3456)
		{
			return x < 2840 && y >= 3440 && plane == PLANE_GROUND;
		}
		return true;
	}

	private static void herb(String place, int variable, int... regions)
	{
		patch(place, variable, Kind.HERB, ANYWHERE, regions);
	}

	private static void tree(String place, int variable, int... regions)
	{
		patch(place, variable, Kind.TREE, ANYWHERE, regions);
	}

	private static void patch(String place, int variable, Kind kind, Bounds bounds, int... regions)
	{
		Patch patch = new Patch(place, regions[0], variable, kind, bounds);
		BY_KEY.put(patch.key, patch);
		for (int region : regions)
		{
			PATCHES.computeIfAbsent(region, r -> new ArrayList<>()).add(patch);
		}
	}

	private static void bird(String place, int varp)
	{
		Patch patch = new Patch(place, FOSSIL_ISLAND.get(1), varp, Kind.BIRD, ANYWHERE);
		BY_KEY.put(patch.key, patch);
		BIRDS.add(patch);
	}

	private final Consumer<GroupEvent> out;
	private final Predicate<GroupEvent.Type> wanted;
	private final Map<String, Timer> timers = new TreeMap<>();
	private boolean dirty;

	FarmRuns(Consumer<GroupEvent> out, Predicate<GroupEvent.Type> wanted)
	{
		this.out = out;
		this.wanted = wanted;
	}

	/** The crop for a patch variable's value; null for weeds, a ready crop, disease, or anything else not growing. */
	static Crop crop(Kind kind, int value)
	{
		switch (kind)
		{
			case HERB:
				return herbCrop(value);
			case TREE:
				return treeCrop(value);
			case HESPORI:
				return value >= HESPORI_START && value < HESPORI_START + HESPORI_STAGES - 1
					? new Crop(value - HESPORI_START, HESPORI_STAGES, HESPORI_MINUTES) : null;
			default:
				return value > 0 && value <= BIRD_MAX_VALUE && value % 3 == 0 ? new Crop(0, 1, 0) : null;
		}
	}

	private static Crop herbCrop(int value)
	{
		for (int start : HERB_STARTS)
		{
			if (value >= start && value < start + HERB_STAGES - 1)
			{
				return new Crop(value - start, HERB_STAGES, HERB_MINUTES);
			}
		}
		return null;
	}

	private static Crop treeCrop(int value)
	{
		for (int[] tree : TREES)
		{
			int start = tree[0];
			int stages = tree[1];
			if (value >= start && value < start + stages - 1)
			{
				return new Crop(value - start, stages, TREE_MINUTES);
			}
		}
		return null;
	}

	/** Reads the variables that mean something where the player is standing. */
	void observe(int region, int x, int y, int plane, IntUnaryOperator varbits, IntUnaryOperator varps, long now)
	{
		for (Patch patch : PATCHES.getOrDefault(region, Collections.emptyList()))
		{
			if (patch.bounds.contains(x, y, plane) && wanted.test(patch.kind.type))
			{
				record(patch, varbits.applyAsInt(patch.variable), now);
			}
		}
		if (plane == PLANE_GROUND && FOSSIL_ISLAND.contains(region) && wanted.test(GroupEvent.Type.BIRDHOUSE))
		{
			birds(varps, now);
		}
	}

	private void birds(IntUnaryOperator varps, long now)
	{
		int removed = 0;
		for (Patch patch : BIRDS)
		{
			if (varps.applyAsInt(patch.variable) <= 0 && timers.containsKey(patch.key))
			{
				removed++;
			}
		}
		if (removed > BIRD_MAX_REMOVED)
		{
			return;
		}
		for (Patch patch : BIRDS)
		{
			record(patch, varps.applyAsInt(patch.variable), now);
		}
	}

	private void record(Patch patch, int value, long now)
	{
		Timer timer = timers.get(patch.key);
		if (timer != null && timer.value == value)
		{
			refresh(timer, now);
			return;
		}
		Crop crop = crop(patch.kind, value);
		if (crop != null)
		{
			timers.put(patch.key, new Timer(patch, value, now, crop.readyAt(now), false));
			dirty = true;
		}
		else if (timers.remove(patch.key) != null)
		{
			dirty = true;
		}
	}

	private void refresh(Timer timer, long now)
	{
		if (timer.fired || timer.patch.kind == Kind.BIRD || now - timer.seen < REFRESH_SECONDS)
		{
			return;
		}
		Crop crop = crop(timer.patch.kind, timer.value);
		timer.seen = now;
		timer.readyAt = crop.readyAt(now);
		dirty = true;
	}

	/** Fires whatever has finished, one event per kind, once each. */
	void due(long now, String me)
	{
		Map<Kind, List<Timer>> ready = new EnumMap<>(Kind.class);
		for (Timer timer : timers.values())
		{
			if (!timer.fired && timer.readyAt <= now)
			{
				ready.computeIfAbsent(timer.patch.kind, k -> new ArrayList<>()).add(timer);
			}
		}
		if (birdStillGrowing(now))
		{
			ready.remove(Kind.BIRD);
		}
		ready.forEach((kind, done) -> fire(kind, done, now, me));
	}

	/** Bird houses are one job: Time Tracking reports them when the last has finished. */
	private boolean birdStillGrowing(long now)
	{
		return timers.values().stream().anyMatch(t -> t.patch.kind == Kind.BIRD && !t.fired && t.readyAt > now);
	}

	private void fire(Kind kind, List<Timer> done, long now, String me)
	{
		List<String> places = new ArrayList<>();
		for (Timer timer : done)
		{
			timer.fired = true;
			places.add(timer.patch.place);
		}
		dirty = true;
		if (wanted.test(kind.type))
		{
			out.accept(GroupEvent.of(kind.type, now * 1000L, me).text(kind.label).number(done.size())
				.detail(kind == Kind.BIRD ? "" : places(places)).build());
		}
	}

	/** The places, or a count when they would not fit in an event's text. */
	static String places(List<String> places)
	{
		String joined = String.join(", ", places);
		return joined.length() <= GroupEvent.MAX_TEXT ? joined : places.size() + " patches";
	}

	/** True once, after a change worth saving. */
	boolean takeDirty()
	{
		boolean was = dirty;
		dirty = false;
		return was;
	}

	String save()
	{
		StringBuilder saved = new StringBuilder();
		for (Timer t : timers.values())
		{
			saved.append(t.patch.key).append('=').append(t.value).append(',').append(t.seen).append(',')
				.append(t.readyAt).append(',').append(t.fired ? 1 : 0).append(';');
		}
		return saved.toString();
	}

	/** Restores saved timers; anything that does not read back is dropped. */
	static FarmRuns parse(String saved, Consumer<GroupEvent> out, Predicate<GroupEvent.Type> wanted)
	{
		FarmRuns farm = new FarmRuns(out, wanted);
		if (saved != null)
		{
			for (String entry : saved.split(";"))
			{
				farm.restore(entry);
			}
		}
		return farm;
	}

	private void restore(String entry)
	{
		String[] parts = entry.split("=", 2);
		Patch patch = BY_KEY.get(parts[0]);
		if (patch == null || parts.length != 2)
		{
			return;
		}
		String[] fields = parts[1].split(",");
		if (fields.length != 4)
		{
			return;
		}
		try
		{
			timers.put(patch.key, new Timer(patch, Integer.parseInt(fields[0]), Long.parseLong(fields[1]),
				Long.parseLong(fields[2]), "1".equals(fields[3])));
		}
		catch (NumberFormatException e)
		{
			// A damaged entry is the same as none: the next visit records it again.
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.List;

/**
 * The {@code ::find <item>} answer: who holds a matching item now (the
 * panel's "Who has it?") and who last moved it in or out of group storage.
 *
 * <p>{@code ::} rather than {@code !}: RuneLite's {@code ChatInputManager}
 * turns {@code ::} text into a {@code CommandExecuted} event and sends
 * nothing to the game, while a {@code !} command is only seen after the
 * message has gone out to public chat. The answer is shown to this player
 * only, as game messages.
 *
 * <p>Pure, so the text can be tested without a client.
 */
final class FindCommand
{
	static final String NAME = "find";
	static final int MAX_LINES = 5;
	static final int HISTORY_LIMIT = 3;

	private FindCommand()
	{
	}

	static List<String> answer(String query, List<GroupSearch.Source> sources, List<StorageChange> log,
		ItemLookup items, long now)
	{
		List<String> out = new ArrayList<>();
		String q = ItemQuery.normalize(query);
		if (ItemQuery.parse(q) == null)
		{
			out.add("Type at least " + GroupSearch.MIN_QUERY + " letters of an item name, e.g. ::find dragon hunter wand");
			return out;
		}

		List<String> lines = new ArrayList<>(GroupSearch.search(q, sources, items, now));
		lines.addAll(GroupSearch.history(q, log, items, now, HISTORY_LIMIT));
		if (lines.isEmpty())
		{
			out.add("Nothing found for '" + plain(query.trim()) + "'. Only members running GIM Utilities with sharing"
				+ " on are tracked, as of their last sync; trades and drops between members are not.");
			return out;
		}
		for (int i = 0; i < lines.size() && i < MAX_LINES; i++)
		{
			out.add(lines.get(i));
		}
		if (lines.size() > MAX_LINES)
		{
			out.add((lines.size() - MAX_LINES) + " more, see the GIM Utilities panel");
		}
		return out;
	}

	/**
	 * The chatbox answer, worded and coloured by {@code style}: a header naming the
	 * search ("Find trout:"), then one line per item and the storage history.
	 */
	static List<String> answer(String query, List<GroupSearch.Source> sources, List<StorageChange> log,
		ItemLookup items, long now, FindStyle style)
	{
		List<String> out = new ArrayList<>();
		String q = ItemQuery.normalize(query);
		if (ItemQuery.parse(q) == null)
		{
			out.add("Type at least " + GroupSearch.MIN_QUERY + " letters of an item name, e.g. ::find dragon hunter wand");
			return out;
		}
		String asked = FindStyle.paint(plain(query.trim()), style.query);
		List<String> lines = new ArrayList<>(GroupSearch.searchStyled(q, sources, items, now, style));
		lines.addAll(GroupSearch.historyStyled(q, log, items, now, HISTORY_LIMIT, style));
		if (lines.isEmpty())
		{
			out.add("Nothing found for " + asked + ". Only members running GIM Utilities with sharing on are"
				+ " tracked, as of their last sync; trades and drops between members are not.");
			return out;
		}
		out.add("Find " + asked + ":");
		for (int i = 0; i < lines.size() && i < MAX_LINES; i++)
		{
			out.add(lines.get(i));
		}
		if (lines.size() > MAX_LINES)
		{
			out.add((lines.size() - MAX_LINES) + " more, see the GIM Utilities panel");
		}
		return out;
	}

	/** The query as typed, without anything the chatbox would read as a tag. */
	static String plain(String text)
	{
		return text.replace("<", "").replace(">", "");
	}
}

package com.vinnyvangogh.groupironman;

import java.awt.Color;
import net.runelite.client.util.ColorUtil;

/**
 * How {@code ::find} answers read in the chatbox (Board 2026-11-04): the search
 * term and each place coloured by kind, and "your bank" rather than your own
 * name. The game's chat font has no bold, so emphasis is colour. Colours come
 * from the plugin settings; {@link #PLAIN} adds no tags, for tests and logs.
 */
final class FindStyle
{
	/** No colour tags. */
	static final FindStyle PLAIN = new FindStyle("", null, null, null, null, null, null);

	/** This player's name, so their own places read "your bank". */
	final String self;
	final Color query;
	final Color item;
	final Color yourBank;
	final Color memberBank;
	final Color storage;
	final Color carried;

	FindStyle(String self, Color query, Color item, Color yourBank, Color memberBank, Color storage, Color carried)
	{
		this.self = self == null ? "" : self;
		this.query = query;
		this.item = item;
		this.yourBank = yourBank;
		this.memberBank = memberBank;
		this.storage = storage;
		this.carried = carried;
	}

	static FindStyle of(GroupIronmanConfig config, String self)
	{
		// Item names in the chat's own colour unless asked (Board 2026-11-04: "a little too colourful").
		Color item = config.findColourItemNames() ? config.findItemColour() : null;
		return new FindStyle(self, config.findQueryColour(), item, config.findYourBankColour(),
			config.findMemberBankColour(), config.findStorageColour(), config.findCarriedColour());
	}

	boolean isYou(String member)
	{
		return !self.isEmpty() && self.equalsIgnoreCase(member);
	}

	/** {@code text} in {@code colour}, or as is when there is none. */
	static String paint(String text, Color colour)
	{
		return colour == null ? text : ColorUtil.wrapWithColorTag(text, colour);
	}

	/**
	 * Where a hit is, worded from the reader's side: "15 in your bank", "5 in Alex's
	 * bank", "140 in group storage", "1 equipped by Sam", "1 equipped by you".
	 */
	String place(GroupSearch.Hit h)
	{
		return place(h, Amounts.GAME);
	}

	/** {@link #place(GroupSearch.Hit)} with the amount in {@code amounts}: "450K in group storage". */
	String place(GroupSearch.Hit h, Amounts amounts)
	{
		String amount = amounts.of(h.quantity);
		if ("Group".equals(h.member))
		{
			return paint(amount + " in group " + h.where, storage);
		}
		boolean you = isYou(h.member);
		if ("equipped".equals(h.where))
		{
			return paint(amount + " equipped by " + (you ? "you" : h.member), carried);
		}
		String owner = you ? "your" : h.member + "'s";
		Color colour = "bank".equals(h.where) ? (you ? yourBank : memberBank) : carried;
		return paint(amount + " in " + owner + " " + h.where, colour);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.TreeMap;
import java.util.function.Predicate;

/**
 * Who in the group is online, and on which world, as the game itself shows it (Board 2026-11-11): the same list
 * as the in-game Group tab, so members without the plugin are shown too.
 *
 * <p>Read on the client thread from the game's own Ironman Group channel,
 * {@code client.getClanChannel(ClanID.GROUP_IRONMAN)}: every {@code ClanChannelMember} in it is online on
 * {@code getWorld()}, and a roster member ({@link GroupMembers}, from {@code getClanSettings}) not in it is
 * offline. Without the channel, the Friends list ({@code client.getFriendContainer()}, a {@code Friend}'s world
 * is above 0 while online) speaks for the members on it. Before either loads nothing is known.
 *
 * <p>Presence and world only: stats, items and the rest still come from the party. Immutable, so any thread may
 * read the one {@link GroupService} holds.
 */
final class GamePresence
{
	enum Source
	{
		NONE,
		CHANNEL,
		FRIENDS
	}

	enum State
	{
		ONLINE,
		OFFLINE,
		/** The game has not said: the channel has not loaded, or the member is not on the list read. */
		UNKNOWN
	}

	static final GamePresence UNKNOWN = new GamePresence(Source.NONE, Collections.emptyMap(), Collections.emptyMap());

	private final Source source;
	/** Every member the game speaks for, by {@link GroupMembers#key}: their name as the game spells it. */
	private final Map<String, String> covered;
	/** The online ones' worlds, by key. */
	private final Map<String, Integer> worlds;

	private GamePresence(Source source, Map<String, String> covered, Map<String, Integer> worlds)
	{
		this.source = source;
		this.covered = covered;
		this.worlds = worlds;
	}

	/**
	 * {@code channel}: the Group channel's members and worlds, null when it has not loaded. {@code friends}: the
	 * Friends list's names and worlds (0 offline), null when not loaded; read only without the channel.
	 */
	static GamePresence read(GroupMembers roster, Map<String, Integer> channel, Map<String, Integer> friends)
	{
		if (channel != null)
		{
			Map<String, String> covered = new HashMap<>();
			roster.names().forEach(n -> covered.put(GroupMembers.key(n), GroupMembers.display(n)));
			return of(Source.CHANNEL, covered, channel, n -> true);
		}
		if (friends != null && roster.known())
		{
			return of(Source.FRIENDS, new HashMap<>(), friends, roster::allows);
		}
		return UNKNOWN;
	}

	/** {@code listed}'s names (world 0 offline) that {@code wanted} keeps, on top of {@code covered}. */
	private static GamePresence of(Source source, Map<String, String> covered, Map<String, Integer> listed,
		Predicate<String> wanted)
	{
		Map<String, Integer> worlds = new HashMap<>();
		listed.forEach((name, world) ->
		{
			String key = GroupMembers.key(name);
			if (!key.isEmpty() && wanted.test(name))
			{
				covered.put(key, GroupMembers.display(name));
				if (world != null && world > 0)
				{
					worlds.put(key, world);
				}
			}
		});
		return new GamePresence(source, Collections.unmodifiableMap(covered), Collections.unmodifiableMap(worlds));
	}

	boolean known()
	{
		return source != Source.NONE;
	}

	Source source()
	{
		return source;
	}

	State state(String name)
	{
		String key = GroupMembers.key(name);
		if (worlds.containsKey(key))
		{
			return State.ONLINE;
		}
		return covered.containsKey(key) ? State.OFFLINE : State.UNKNOWN;
	}

	/** Those of {@code names} that {@code after} has online and {@code before} did not: just came online. */
	static List<String> cameOnline(Collection<String> names, GamePresence before, GamePresence after)
	{
		List<String> out = new ArrayList<>();
		for (String name : names)
		{
			if (after.state(name) == State.ONLINE && before.state(name) != State.ONLINE)
			{
				out.add(name);
			}
		}
		return out;
	}

	/** The world they are on, 0 when not online or not known. */
	int world(String name)
	{
		return worlds.getOrDefault(GroupMembers.key(name), 0);
	}

	/** Every member the game speaks for, online or not, as the game spells them. */
	Set<String> names()
	{
		return new HashSet<>(covered.values());
	}

	/** The online members and their worlds, sorted by name. */
	Map<String, Integer> online()
	{
		Map<String, Integer> out = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
		worlds.forEach((key, world) -> out.put(covered.get(key), world));
		return new LinkedHashMap<>(out);
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof GamePresence))
		{
			return false;
		}
		GamePresence p = (GamePresence) o;
		return source == p.source && covered.equals(p.covered) && worlds.equals(p.worlds);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(source, covered, worlds);
	}

	/**
	 * The others online, sorted by name, and their worlds (0 when not known): members whose clients are heard
	 * ({@code plugin}, from the party) unless the game says they logged out, and everyone the game says is on.
	 * The game's world wins. {@code self} is left out.
	 */
	static Map<String, Integer> othersOnline(Map<String, MemberStats> plugin, GamePresence game, String self)
	{
		Map<String, String> names = new HashMap<>();
		Map<String, Integer> worlds = new HashMap<>();
		plugin.forEach((name, stats) ->
		{
			if (game.state(name) != State.OFFLINE)
			{
				names.put(GroupMembers.key(name), name);
				worlds.put(GroupMembers.key(name), stats.world());
			}
		});
		game.worlds.forEach((key, world) ->
		{
			names.putIfAbsent(key, game.covered.get(key));
			worlds.put(key, world);
		});
		names.remove(GroupMembers.key(self));
		Map<String, Integer> out = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
		names.forEach((key, name) -> out.put(name, worlds.get(key)));
		return new LinkedHashMap<>(out);
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import static com.vinnyvangogh.groupironman.GroupCodec.flag;
import static com.vinnyvangogh.groupironman.GroupCodec.header;
import static com.vinnyvangogh.groupironman.GroupCodec.string;

/**
 * The three governance kinds inside a {@link VvgGroupIronmanMessage}, next to
 * {@link GroupCodec}'s six. A build without them reads them as an unknown kind
 * and ignores them.
 *
 * <ul>
 * <li>{@code roles}: {@link GroupRoles}, signed by the leader.</li>
 * <li>{@code gset}: {@link GroupSettings}, signed by the leader or an editor.
 * Holds the shared settings only; a webhook URL has no field here.</li>
 * <li>{@code member}: a member's public key and their posting opt-outs.</li>
 * <li>{@code gweb}: {@link GroupWebhooks}, signed by the leader only, and only ever sent once the leader has
 * turned on "Share webhooks with the group". The one kind that carries webhook URLs.</li>
 * </ul>
 *
 * <p>The same JSON is what {@link GroupService} keeps in the config between
 * sessions. Every list and map is capped, and the signature is checked by
 * {@link GroupGovernance}, not here.
 */
final class GovernanceCodec
{
	static final String ROLES = "roles";
	static final String SETTINGS = "gset";
	static final String MEMBER = "member";
	static final String WEBHOOKS = "gweb";
	/** A little over {@link GroupWebhooks#MAX_URL}: a longer field cannot be one the leader signed. */
	private static final int MAX_URL = GroupWebhooks.MAX_URL + 1;
	/** Longer than any RuneLite display name (12) and than any key in the schema. */
	private static final int MAX_NAME = 64;
	/** Well over the schema's size: a newer build's extra keys are read and then dropped. */
	private static final int MAX_VALUES = 400;

	private GovernanceCodec()
	{
	}

	/** Exactly one of the fields is set, by {@link #kind}. */
	static final class Message
	{
		final String kind;
		final GroupRoles roles;
		final GroupSettings settings;
		final String memberKey;
		final MemberPrefs prefs;
		final GroupWebhooks webhooks;

		private Message(String kind, GroupRoles roles, GroupSettings settings, String memberKey, MemberPrefs prefs)
		{
			this(kind, roles, settings, memberKey, prefs, null);
		}

		private Message(String kind, GroupRoles roles, GroupSettings settings, String memberKey, MemberPrefs prefs,
			GroupWebhooks webhooks)
		{
			this.kind = kind;
			this.roles = roles;
			this.settings = settings;
			this.memberKey = memberKey;
			this.prefs = prefs;
			this.webhooks = webhooks;
		}
	}

	static String encode(Gson gson, GroupWebhooks w)
	{
		JsonObject o = header(WEBHOOKS);
		o.addProperty("g", w.group);
		o.addProperty("ver", w.version);
		o.addProperty("ts", w.at);
		o.addProperty("by", w.by);
		o.addProperty("bk", w.byKey);
		o.addProperty("sh", w.shared);
		JsonObject hooks = new JsonObject();
		for (Map.Entry<Webhook, Webhooks.Setting> e : w.settings.entrySet())
		{
			JsonArray s = new JsonArray();
			s.add(e.getValue().url);
			s.add(e.getValue().mode.name());
			s.add(e.getValue().name);
			hooks.add(e.getKey().name(), s);
		}
		o.add("wh", hooks);
		o.addProperty("sig", w.signature);
		return gson.toJson(o);
	}

	static String encode(Gson gson, GroupRoles roles)
	{
		return gson.toJson(json(roles));
	}

	static String encode(Gson gson, GroupSettings settings)
	{
		return gson.toJson(json(settings));
	}

	static String encodeMember(Gson gson, String publicKey, MemberPrefs prefs)
	{
		JsonObject o = header(MEMBER);
		o.addProperty("pk", publicKey);
		o.addProperty("all", prefs.all);
		o.addProperty("np", MemberPrefs.format(prefs.noPost));
		return gson.toJson(o);
	}

	static JsonObject json(GroupRoles r)
	{
		JsonObject o = header(ROLES);
		o.addProperty("g", r.group);
		o.addProperty("ver", r.version);
		o.addProperty("ts", r.at);
		o.addProperty("ld", r.leader);
		o.addProperty("lk", r.leaderKey);
		JsonObject eds = new JsonObject();
		r.editors.forEach(eds::addProperty);
		o.add("ed", eds);
		o.addProperty("sig", r.signature);
		return o;
	}

	static JsonObject json(GroupSettings s)
	{
		JsonObject o = header(SETTINGS);
		o.addProperty("ver", s.version);
		o.addProperty("ts", s.at);
		o.addProperty("by", s.by);
		o.addProperty("bk", s.byKey);
		JsonObject vals = new JsonObject();
		s.values.forEach(vals::addProperty);
		o.add("val", vals);
		JsonArray hist = new JsonArray();
		for (GroupSettings.Change c : s.history)
		{
			JsonArray line = new JsonArray();
			line.add(c.at);
			line.add(c.by);
			line.add(c.key);
			line.add(c.from);
			line.add(c.to);
			hist.add(line);
		}
		o.add("h", hist);
		o.addProperty("sig", s.signature);
		return o;
	}

	/** The governance message in {@code json}, or null when it is not one (or not readable). */
	static Message decode(Gson gson, String json)
	{
		JsonObject root = GroupCodec.object(gson, json, GroupCodec.MAX_PAYLOAD_CHARS * 2);
		try
		{
			return root == null ? null : decode(root);
		}
		catch (RuntimeException e)
		{
			// Malformed JSON or a field of the wrong type: not a document anyone signed.
			return null;
		}
	}

	private static Message decode(JsonObject in)
	{
		switch (string(in, "k"))
		{
			case ROLES:
				return new Message(ROLES, roles(in), null, null, null);
			case SETTINGS:
				return new Message(SETTINGS, null, settings(in), null, null);
			case MEMBER:
				return new Message(MEMBER, null, null, string(in, "pk"), new MemberPrefs(flag(in, "all"),
					MemberPrefs.parse(string(in, "np")), MemberPrefs.NONE.mute));
			case WEBHOOKS:
				return new Message(WEBHOOKS, null, null, null, null, webhooks(in));
			default:
				return null;
		}
	}

	private static GroupRoles roles(JsonObject in)
	{
		Map<String, String> editors = new TreeMap<>();
		JsonElement eds = in.get("ed");
		if (eds != null && eds.isJsonObject())
		{
			for (Map.Entry<String, JsonElement> e : eds.getAsJsonObject().entrySet())
			{
				if (editors.size() > GroupRoles.MAX_EDITORS)
				{
					break;
				}
				editors.put(cap(e.getKey()), e.getValue().getAsString());
			}
		}
		return new GroupRoles(string(in, "g"), number(in, "ver"), number(in, "ts"), cap(string(in, "ld")),
			string(in, "lk"), editors, string(in, "sig"));
	}

	private static GroupSettings settings(JsonObject in)
	{
		Map<String, Long> values = new TreeMap<>();
		JsonElement vals = in.get("val");
		if (vals != null && vals.isJsonObject())
		{
			for (Map.Entry<String, JsonElement> e : vals.getAsJsonObject().entrySet())
			{
				if (values.size() >= MAX_VALUES)
				{
					break;
				}
				values.put(cap(e.getKey()), e.getValue().getAsLong());
			}
		}
		List<GroupSettings.Change> history = new ArrayList<>();
		JsonElement hist = in.get("h");
		if (hist != null && hist.isJsonArray())
		{
			for (JsonElement line : hist.getAsJsonArray())
			{
				if (history.size() >= GroupSettings.MAX_HISTORY)
				{
					break;
				}
				JsonArray a = line.getAsJsonArray();
				history.add(new GroupSettings.Change(a.get(0).getAsLong(), cap(a.get(1).getAsString()),
					cap(a.get(2).getAsString()), a.get(3).getAsLong(), a.get(4).getAsLong()));
			}
		}
		// Values are kept as signed, unsanitized, so the signature still checks; readers clamp on use.
		return new GroupSettings(number(in, "ver"), number(in, "ts"), cap(string(in, "by")), string(in, "bk"), values,
			history, string(in, "sig"));
	}

	/** As signed: a field that is no webhook or no poster-name choice this build knows fails the signature check. */
	private static GroupWebhooks webhooks(JsonObject in)
	{
		Map<Webhook, Webhooks.Setting> hooks = new EnumMap<>(Webhook.class);
		JsonElement wh = in.get("wh");
		if (wh != null && wh.isJsonObject())
		{
			for (Map.Entry<String, JsonElement> e : wh.getAsJsonObject().entrySet())
			{
				Webhook w = known(Webhook.values(), e.getKey());
				JsonArray a = e.getValue().getAsJsonArray();
				DiscordPosterName mode = known(DiscordPosterName.values(), a.get(1).getAsString());
				String url = a.get(0).getAsString();
				if (w != null && mode != null && url.length() <= MAX_URL)
				{
					hooks.put(w, new Webhooks.Setting(url, mode, cap(a.get(2).getAsString(), PosterNames.MAX * 2)));
				}
			}
		}
		return new GroupWebhooks(string(in, "g"), number(in, "ver"), number(in, "ts"), cap(string(in, "by")),
			string(in, "bk"), flag(in, "sh"), hooks, string(in, "sig"));
	}

	private static <E extends Enum<E>> E known(E[] values, String name)
	{
		for (E e : values)
		{
			if (e.name().equals(name))
			{
				return e;
			}
		}
		return null;
	}

	private static long number(JsonObject in, String field)
	{
		JsonElement e = in.get(field);
		return e == null || !e.isJsonPrimitive() ? 0 : e.getAsLong();
	}

	private static String cap(String s)
	{
		return cap(s, MAX_NAME);
	}

	private static String cap(String s, int max)
	{
		return s.length() > max ? s.substring(0, max) : s;
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.util.Map;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;

/**
 * {@link GroupGovernance} wired to the party and the config, without the
 * client: {@link GroupService} hands it a {@link Store} (the plugin's config
 * group), a send (party messages) and names it has already checked against the
 * in-game roster.
 *
 * <p><b>When it sends.</b> Never on its own timer: whatever changed is marked
 * and {@link #flush} sends it on the next game tick while connected. A member
 * joining (their {@code UserSync}) marks everything, which is how a member who
 * was offline picks up the latest roles and settings: any member online
 * resends them, and the signatures make it safe for anyone to relay.
 *
 * <p><b>What it keeps.</b> This client's key pair, the roles and the settings,
 * each under its own config key (no file of its own). Members' announces are
 * kept in memory only. The leader's shared webhooks ({@link GroupWebhooks})
 * are never put in the config: they go to {@code cache} (the group cache file)
 * and come back through {@link #restoreWebhooks}.
 */
@Slf4j
final class GovernanceSync
{
	static final String KEY_IDENTITY = "memberIdentity";
	static final String KEY_ROLES = "groupRoles";
	static final String KEY_SETTINGS = "groupSettings";

	/** The plugin's config group, as far as this needs it. */
	interface Store
	{
		String get(String key);

		/** {@code null} unsets the key. */
		void set(String key, String value);
	}

	private final Gson gson;
	private final Store store;
	private final Consumer<String> send;
	private final Runnable onChange;
	private final GroupGovernance governance;
	private final Consumer<String> cache;

	private boolean rolesDirty;
	private boolean settingsDirty;
	private boolean webhooksDirty;
	private boolean announceDirty = true;
	private String lastAnnounce;
	private String group = "";

	GovernanceSync(Gson gson, Store store, Consumer<String> send, Runnable onChange)
	{
		this(gson, store, send, onChange, json ->
		{
		});
	}

	/** {@code cache} keeps the leader's webhooks document between sessions, outside the config; null clears it. */
	GovernanceSync(Gson gson, Store store, Consumer<String> send, Runnable onChange, Consumer<String> cache)
	{
		this.gson = gson;
		this.store = store;
		this.send = send;
		this.onChange = onChange;
		this.cache = cache;
		GroupSigner.Identity id = GroupSigner.Identity.load(store.get(KEY_IDENTITY));
		if (id == null)
		{
			id = GroupSigner.Identity.create();
			store.set(KEY_IDENTITY, id.save());
		}
		governance = new GroupGovernance(id);
	}

	GroupGovernance governance()
	{
		return governance;
	}

	/** The in-game group, once known or when it changes: loads what was kept for it. */
	synchronized void group(String name)
	{
		String key = GroupMembers.key(name == null ? "" : name);
		if (key.equals(group))
		{
			return;
		}
		group = key;
		governance.group(name);
		GovernanceCodec.Message roles = GovernanceCodec.decode(gson, store.get(KEY_ROLES));
		GovernanceCodec.Message settings = GovernanceCodec.decode(gson, store.get(KEY_SETTINGS));
		governance.load(roles == null ? null : roles.roles, settings == null ? null : settings.settings);
		onChange.run();
	}

	/** A cheap look before decoding: every party message passes through here. */
	static boolean isGovernance(String payload)
	{
		return payload != null && (payload.contains("\"k\":\"" + GovernanceCodec.ROLES + "\"")
			|| payload.contains("\"k\":\"" + GovernanceCodec.SETTINGS + "\"")
			|| payload.contains("\"k\":\"" + GovernanceCodec.MEMBER + "\"")
			|| payload.contains("\"k\":\"" + GovernanceCodec.WEBHOOKS + "\""));
	}

	/** The webhooks document the group cache file held, once it is read. */
	void restoreWebhooks(String json)
	{
		GovernanceCodec.Message m = GovernanceCodec.decode(gson, json);
		if (m != null && GovernanceCodec.WEBHOOKS.equals(m.kind))
		{
			act(() ->
			{
				governance.receiveWebhooks(m.webhooks);
				return true;
			});
		}
	}

	/** A governance message from {@code name}, a roster member. False when it is not one. */
	boolean receive(String name, String payload)
	{
		GovernanceCodec.Message m = GovernanceCodec.decode(gson, payload);
		if (m == null)
		{
			return false;
		}
		GroupRoles rolesBefore = governance.roles();
		GroupSettings settingsBefore = governance.settings();
		GroupWebhooks webhooksBefore = governance.webhooks();
		GroupGovernance.Verdict v = apply(name, m);
		if (v == GroupGovernance.Verdict.REFUSED)
		{
			// The kind and the sender only: never the document, which may hold webhook URLs.
			log.debug("refused group {} from {}", m.kind, name);
		}
		keep(rolesBefore, settingsBefore, webhooksBefore);
		onChange.run();
		return true;
	}

	private GroupGovernance.Verdict apply(String name, GovernanceCodec.Message m)
	{
		switch (m.kind)
		{
			case GovernanceCodec.MEMBER:
				governance.receiveMember(name, m.memberKey, m.prefs);
				return null;
			case GovernanceCodec.ROLES:
				return governance.receiveRoles(m.roles);
			case GovernanceCodec.WEBHOOKS:
				return governance.receiveWebhooks(m.webhooks);
			default:
				return governance.receiveSettings(m.settings);
		}
	}

	/** Someone joined: they may have missed all of it. */
	synchronized void resendAll()
	{
		rolesDirty = true;
		settingsDirty = true;
		webhooksDirty = true;
		announceDirty = true;
	}

	/** This member's opt-outs, re-announced only when they changed. */
	synchronized void prefs(MemberPrefs prefs)
	{
		if (!announcement(prefs).equals(lastAnnounce))
		{
			announceDirty = true;
		}
	}

	/** Game tick, while connected to the group's party: sends whatever changed. */
	void flush(MemberPrefs prefs)
	{
		boolean announce;
		boolean roles;
		boolean settings;
		boolean webhooks;
		synchronized (this)
		{
			announce = announceDirty;
			roles = rolesDirty;
			settings = settingsDirty;
			webhooks = webhooksDirty;
			announceDirty = false;
			rolesDirty = false;
			settingsDirty = false;
			webhooksDirty = false;
		}
		if (announce)
		{
			lastAnnounce = announcement(prefs);
			send.accept(lastAnnounce);
		}
		GroupRoles r = governance.roles();
		if (roles && r != null)
		{
			send.accept(GovernanceCodec.encode(gson, r));
		}
		GroupSettings s = governance.settings();
		// After the roles, so a member who had neither can check the settings at once.
		if (settings && s != null)
		{
			send.accept(GovernanceCodec.encode(gson, s));
		}
		// Only once the leader has shared: a group that never did sends no webhooks document at all.
		GroupWebhooks w = governance.webhooks();
		if (webhooks && w != null)
		{
			send.accept(GovernanceCodec.encode(gson, w));
		}
	}

	private String announcement(MemberPrefs prefs)
	{
		return GovernanceCodec.encodeMember(gson, governance.publicKey(), prefs);
	}

	// ---- This player's actions; false when refused ----

	boolean claim(String self, long now)
	{
		return act(() -> governance.claim(self, now) != null);
	}

	boolean setEditor(String self, String name, boolean editor, long now)
	{
		return act(() -> governance.setEditor(self, name, editor, now) != null);
	}

	/** What "Save to group" did, so the tab can say why when it did not. */
	enum SaveResult
	{
		SAVED,
		/** Saved here; it goes out once this client joins group sync. */
		SAVED_OFFLINE,
		/** The group already holds exactly these values. */
		UNCHANGED,
		/** This client is not the leader or an editor (any more). */
		NOT_EDITOR,
		/** No player name yet: not logged in. */
		NOT_LOGGED_IN,
		/** Group settings have not started. */
		NOT_STARTED
	}

	SaveResult save(String self, Map<String, Long> values, long now)
	{
		GroupSettings before = governance.settings();
		if (!act(() -> governance.save(self, values, now) != null))
		{
			return SaveResult.NOT_EDITOR;
		}
		return governance.settings() == before ? SaveResult.UNCHANGED : SaveResult.SAVED;
	}

	/** The leader's "Share webhooks with the group", or a leader's webhook edit while it is on. */
	boolean shareWebhooks(String self, boolean share, Webhooks own, long now)
	{
		return act(() -> governance.shareWebhooks(self, share, own, now));
	}

	void forgetLeader()
	{
		act(() ->
		{
			governance.forgetLeader();
			return true;
		});
	}

	private boolean act(BooleanSupplier action)
	{
		GroupRoles rolesBefore = governance.roles();
		GroupSettings settingsBefore = governance.settings();
		GroupWebhooks webhooksBefore = governance.webhooks();
		boolean ok = action.getAsBoolean();
		if (ok)
		{
			// An unchanged document is the same object, so keep() writes and marks only what changed.
			keep(rolesBefore, settingsBefore, webhooksBefore);
			onChange.run();
		}
		return ok;
	}

	/** Writes, and marks for sending, whatever is no longer what it was. */
	private synchronized void keep(GroupRoles rolesBefore, GroupSettings settingsBefore, GroupWebhooks webhooksBefore)
	{
		GroupWebhooks w = governance.webhooks();
		if (w != webhooksBefore)
		{
			cache.accept(w == null ? null : GovernanceCodec.encode(gson, w));
			webhooksDirty |= w != null;
		}
		GroupRoles r = governance.roles();
		if (r != rolesBefore)
		{
			store.set(KEY_ROLES, r == null ? null : GovernanceCodec.encode(gson, r));
			rolesDirty |= r != null;
		}
		GroupSettings s = governance.settings();
		if (s != settingsBefore)
		{
			store.set(KEY_SETTINGS, s == null ? null : GovernanceCodec.encode(gson, s));
			settingsDirty |= s != null;
		}
	}
}

package com.vinnyvangogh.groupironman;

/**
 * Which picture the "Gravestone expiring" post carries (Board 2026-11-10: the
 * warning showed wherever the player stood five minutes before the grave ran
 * out, not where they died). Public, like every setting type: RuneLite reads
 * settings through a proxy that cannot see a package-private type
 * (ConfigKeysTest).
 */
public enum GraveScreenshot
{
	/**
	 * The frame taken for the death post, kept in memory only until the grave is gone. Labels stay short: the
	 * dropdown is as wide as its longest one and squeezes the setting's name beside it.
	 */
	DEATH("Where I died"),
	/** The frame drawn when the warning goes out. */
	CURRENT("Current view"),
	NONE("None");

	private final String label;

	GraveScreenshot(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.vinnyvangogh.groupironman;

/**
 * The death's screenshot, held in memory for the gravestone it belongs to, so
 * the "Gravestone expiring" post can show where the player died. Nothing here
 * is written anywhere: a client restart loses it, and the warning then goes
 * out without a picture.
 *
 * <p>Each death is a new grave. A frame that finishes encoding after its grave
 * was replaced or freed is dropped, so a slow encoder never pins an old image.
 * The frame encoder calls {@link #keep} off the client thread; everything else
 * is the client thread.
 */
final class GraveShot
{
	/** What the warning post attaches: {@code picture} false means none; a null {@code png} means the next frame. */
	static final class Choice
	{
		static final Choice NOTHING = new Choice(false, null);
		static final Choice NEXT_FRAME = new Choice(true, null);

		final boolean picture;
		final byte[] png;

		private Choice(boolean picture, byte[] png)
		{
			this.picture = picture;
			this.png = png;
		}
	}

	private int grave;
	private boolean asked;
	private volatile int live;
	private volatile byte[] png;

	/** A death: the previous grave's image, if any, is let go. Returns the new grave's key for {@link #keep}. */
	synchronized int died()
	{
		png = null;
		asked = false;
		live = ++grave;
		return grave;
	}

	/** The death's frame was requested for {@code key}'s grave; true the first time, so it is only asked once. */
	synchronized boolean ask(int key)
	{
		if (key == 0 || key != live || asked)
		{
			return false;
		}
		asked = true;
		return true;
	}

	/** The death's frame, encoded. Kept only while that grave is still the live one. */
	synchronized void keep(int key, byte[] frame)
	{
		if (key == live && live != 0 && frame != null)
		{
			png = frame;
		}
	}

	/** The grave expired, was looted, or the player logged out: the image goes. */
	synchronized void free()
	{
		png = null;
		live = 0;
	}

	/** The live grave's key; 0 when there is none. */
	int live()
	{
		return live;
	}

	/** True while an image is held. */
	boolean holding()
	{
		return png != null;
	}

	/** The picture for the warning post, by the setting. {@code screenshots}: "Attach a screenshot" is on. */
	Choice choose(GraveScreenshot mode, boolean screenshots)
	{
		if (!screenshots || mode == GraveScreenshot.NONE)
		{
			return Choice.NOTHING;
		}
		if (mode == GraveScreenshot.CURRENT)
		{
			return Choice.NEXT_FRAME;
		}
		byte[] held = png;
		return held == null ? Choice.NOTHING : new Choice(true, held);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collection;
import java.util.HashSet;
import java.util.Set;

/**
 * Whether the account logged in now is a member of the group this client is set up for (Board 2026-11-15).
 *
 * <p>The roster ({@link GroupMembers}) is read from the logged-in account's own Group Ironman clan, so on its own
 * it cannot tell an account that is in another group, or in none, from a member: every account is on its own
 * roster. What ties the client to one group is the group's name, saved the first time a member's roster is
 * read ({@link #bound}), and cleared when the group key changes. An account whose roster names another group,
 * or that has no group roster at all, is not a member: nothing is posted, logged or shared for it.
 *
 * <p>The first binding, on a client set up before this existed, is taken from what the client already holds
 * for its group, so the first login after an update being a non-member's cannot bind the wrong group: the
 * signed roles' group when saved, else a roster that has one of the members this client has heard from.
 */
final class GroupBinding
{
	enum Verdict
	{
		/** On the bound group's roster: everything runs. */
		MEMBER,
		/** Another group's roster, or not on it: nothing runs for this account. */
		NOT_MEMBER,
		/** No roster yet (loading, or an account with no group): nothing runs until it is known. */
		WAIT
	}

	static final class Result
	{
		final Verdict verdict;
		/** {@link GroupMembers#key} of the group to save as bound now, or null when nothing changes. */
		final String bind;

		Result(Verdict verdict, String bind)
		{
			this.verdict = verdict;
			this.bind = bind;
		}

		boolean member()
		{
			return verdict == Verdict.MEMBER;
		}
	}

	private GroupBinding()
	{
	}

	/**
	 * @param bound       the saved group ({@link GroupMembers#key}), "" or null when none is saved yet
	 * @param roster      the logged-in account's group roster, as the game shows it
	 * @param self        the logged-in account's name
	 * @param rolesGroup  the group the saved signed roles are for, "" or null when none are saved
	 * @param heard       the names of members this client holds data for (the group cache)
	 */
	static Result check(String bound, GroupMembers roster, String self, String rolesGroup, Collection<String> heard)
	{
		String me = GroupMembers.key(self);
		String group = GroupMembers.key(roster.group());
		if (!roster.known() || me.isEmpty() || group.isEmpty())
		{
			return new Result(Verdict.WAIT, null);
		}
		if (!roster.allows(self))
		{
			return new Result(Verdict.NOT_MEMBER, null);
		}
		String saved = bound == null ? "" : GroupMembers.key(bound);
		if (!saved.isEmpty())
		{
			return new Result(group.equals(saved) ? Verdict.MEMBER : Verdict.NOT_MEMBER, null);
		}
		String roles = rolesGroup == null ? "" : GroupMembers.key(rolesGroup);
		if (!roles.isEmpty())
		{
			return new Result(group.equals(roles) ? Verdict.MEMBER : Verdict.NOT_MEMBER, roles);
		}
		Set<String> others = new HashSet<>();
		if (heard != null)
		{
			heard.forEach(n -> others.add(GroupMembers.key(n)));
		}
		others.remove(me);
		others.remove("");
		if (others.isEmpty() || others.stream().anyMatch(roster::allows))
		{
			return new Result(Verdict.MEMBER, group);
		}
		// Holds other members' data, none of them on this roster: another group's account. A member binds it.
		return new Result(Verdict.NOT_MEMBER, null);
	}
}

package com.vinnyvangogh.groupironman;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Map;
import java.util.function.Supplier;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The combined group box: who is online and on which world, then the latest
 * events. Off by default ("Group box"). Online is what the game's Group channel
 * shows, plugin or not ({@link GamePresence}), and members heard from in the
 * last three minutes ({@link Presence}) unless the game says they left.
 */
final class GroupBoxOverlay extends OverlayPanel
{
	private static final Color ACTIVITY = new Color(0xE0, 0xB0, 0x40);
	private final ToastQueue toasts;
	private final GroupIronmanConfig config;
	private final GroupService group;
	private final Supplier<EasterEggs.Settings> eggs;

	GroupBoxOverlay(ToastQueue toasts, GroupIronmanConfig config, GroupService group,
		Supplier<EasterEggs.Settings> eggs)
	{
		this.toasts = toasts;
		this.config = config;
		this.group = group;
		this.eggs = eggs;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.overlayGroupBox())
		{
			return null;
		}
		long now = System.currentTimeMillis();
		panelComponent.getChildren().add(TitleComponent.builder().text("Group").build());
		Map<String, Integer> online = GamePresence.othersOnline(group.roster().onlineStats(now), group.presence(),
			group.self());
		if (online.isEmpty())
		{
			panelComponent.getChildren().add(LineComponent.builder().left("Nobody else online").leftColor(Color.GRAY)
				.build());
		}
		Map<String, ActivityState> activities = group.roster().activities(now);
		for (Map.Entry<String, Integer> e : online.entrySet())
		{
			int world = e.getValue();
			panelComponent.getChildren().add(LineComponent.builder().left(e.getKey())
				.right(world > 0 ? "W" + world : "").rightColor(Color.GREEN).build());
			ActivityState a = activities.get(e.getKey());
			if (a != null)
			{
				// Formatted when the state arrived, not here: this runs every frame.
				panelComponent.getChildren().add(LineComponent.builder().left(a.overlayLine()).leftColor(ACTIVITY)
					.build());
			}
		}
		EasterEggs.Settings egg = eggs.get();
		for (GroupEvent event : toasts.recent(config.overlayGroupBoxEvents()))
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(EasterEggs.tagged(EventText.sentence(event, group.lookup), event, egg)
					+ " (" + BoostText.ago(now, event.at) + ")")
				.leftColor(new Color(event.type.category.colour)).build());
		}
		return super.render(graphics);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.function.BiFunction;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The game's own Group channel broadcasts ({@code ChatMessageType.CLAN_GIM_MESSAGE}) as group events, so members
 * without the plugin get posted too (Board 2026-11-14). Pure: the engine decides who is a plugin user and who posts.
 *
 * <p><b>Sources.</b> The level-up and quest lines are the Board's own captures ("GroupOtt has reached Herblore level
 * 21.", "... has completed a quest: Black Knights' Fortress"). The pet line is Dink's
 * {@code PetNotifier.CLAN_REGEX} (pajlads/DinkPlugin, which reads {@code CLAN_GIM_MESSAGE} in
 * {@code DinkPlugin.onChatMessage}). The rest follow the game's clan broadcast wording as remembered and are
 * <b>unverified</b>: a line the game words differently is simply not posted, never posted wrong, and each needs one
 * in-game check (BRIEF.md, Phase 0 #27).
 *
 * <p>The chatbox shows a broadcast as "[GroupName] Alex has ..."; the bracketed group name is the sender, not part
 * of the message, but a leading one is tolerated in case a client passes it through.
 */
final class GroupBroadcasts
{
	/** The footer's note on a post made from a broadcast. */
	static final String SOURCE = "from the game's group broadcast";
	/** How long a posted broadcast is remembered, so a restart or a late claim never posts it again. */
	static final long REMEMBER_MS = 24L * 60 * 60 * 1000;
	/** Most broadcasts remembered at once; a busy group makes a few dozen a day. */
	static final int MAX_SEEN = 500;

	/** A display name: letters, digits, spaces, hyphens and underscores, at most 12 (the game's own rule). */
	private static final String NAME = "(?<m>[A-Za-z0-9 _-]{1,12})";
	private static final Pattern GROUP_TAG = Pattern.compile("^\\[[^]]*]\\s*");
	private static final Pattern NUMBER = Pattern.compile("[\\d,]+");

	private static final Map<Pattern, BiFunction<Matcher, Long, GroupEvent.Builder>> LINES = new LinkedHashMap<>();

	static
	{
		// Combat first: "has reached combat level 100" would otherwise read as a skill called "combat".
		line(NAME + " has reached combat level (?<n>\\d+)", (m, at) -> of(GroupEvent.Type.COMBAT_LEVEL, m, at)
			.number(number(m.group("n"))));
		line(NAME + " has reached a total level of (?<n>[\\d,]+)", (m, at) -> of(GroupEvent.Type.TOTAL_LEVEL, m, at)
			.number(number(m.group("n"))));
		line(NAME + " has reached the highest possible (?<s>[A-Za-z]+) level of 99", (m, at) ->
			of(GroupEvent.Type.MAXED, m, at).text(m.group("s")).number(ProgressTracker.MAX_LEVEL));
		line(NAME + " has reached (?<s>[A-Za-z]+) level (?<n>\\d+)", GroupBroadcasts::level);
		line(NAME + " has reached (?<n>[\\d,]+) XP in (?<s>[A-Za-z]+)", (m, at) ->
			of(GroupEvent.Type.XP_MILESTONE, m, at).text(m.group("s")).number(number(m.group("n"))));
		line(NAME + " has completed a quest: (?<q>.+)", (m, at) -> of(GroupEvent.Type.QUEST, m, at)
			.text(m.group("q")));
		line(NAME + " has completed an? (?<t>\\w+) combat task: (?<c>.+?)(?: \\(\\d+ points?\\))?", (m, at) ->
			of(GroupEvent.Type.COMBAT_TASK, m, at).text(m.group("c")).detail(m.group("t")));
		line(NAME + " has completed the (?<d>.+?) diary", (m, at) -> of(GroupEvent.Type.DIARY, m, at)
			.text(m.group("d")));
		line(NAME + " has achieved a new (?<b>.+?) personal best: (?<t>[\\d:.]+)", (m, at) ->
			of(GroupEvent.Type.PERSONAL_BEST, m, at).text(m.group("b") + " " + m.group("t")));
		line(NAME + " received a new collection log item: (?<i>.+?)(?: \\(\\d+/\\d+\\))?", (m, at) ->
			of(GroupEvent.Type.CLOG, m, at).text(m.group("i")));
		line(NAME + " (?:has a funny feeling like .+ followed|feels something weird sneaking into .+ backpack"
			+ "|feels like .+ acquired something special): (?<p>.+?)(?: at .+)?", (m, at) ->
			of(GroupEvent.Type.PET, m, at).text(m.group("p")));
		line(NAME + " has been defeated by (?<k>.+?)(?: in .+?)?(?: and lost .+)?", (m, at) ->
			of(GroupEvent.Type.DEATH, m, at).text(m.group("k")));
		line(NAME + " has died(?: .*)?", (m, at) -> of(GroupEvent.Type.DEATH, m, at));
	}

	private static final Pattern DROP = Pattern.compile("^" + NAME
		+ " received a drop: (?:(?<q>[\\d,]+) x )?(?<i>.+?)(?: \\([\\d,]+ coins\\))?$");

	private GroupBroadcasts()
	{
	}

	private static void line(String regex, BiFunction<Matcher, Long, GroupEvent.Builder> build)
	{
		LINES.put(Pattern.compile("^" + regex + "$"), build);
	}

	private static GroupEvent.Builder of(GroupEvent.Type type, Matcher m, long at)
	{
		return GroupEvent.of(type, at, m.group("m")).broadcast(true);
	}

	/** A 99 by the plain level line is the skill's 99, as the plugin's own tracker files it. */
	private static GroupEvent.Builder level(Matcher m, long at)
	{
		long n = number(m.group("n"));
		GroupEvent.Type type = n >= ProgressTracker.MAX_LEVEL ? GroupEvent.Type.MAXED : GroupEvent.Type.LEVEL_UP;
		return of(type, m, at).text(m.group("s")).number(n);
	}

	/**
	 * The event a broadcast line stands for, under the member it names; null for any other line. A drop needs its
	 * item's id from {@code itemId} (null when unknown, and then no event: a drop is its items).
	 */
	static GroupEvent parse(String message, long at, Function<String, Integer> itemId)
	{
		String text = clean(message);
		if (text.isEmpty())
		{
			return null;
		}
		GroupEvent drop = drop(text, at, itemId);
		if (drop != null)
		{
			return drop;
		}
		for (Map.Entry<Pattern, BiFunction<Matcher, Long, GroupEvent.Builder>> e : LINES.entrySet())
		{
			Matcher m = e.getKey().matcher(text);
			if (m.matches())
			{
				GroupEvent event = e.getValue().apply(m, at).build();
				return event.isValid() ? event : null;
			}
		}
		return null;
	}

	private static GroupEvent drop(String text, long at, Function<String, Integer> itemId)
	{
		Matcher m = DROP.matcher(text);
		if (!m.matches())
		{
			return null;
		}
		Integer id = itemId.apply(m.group("i").trim());
		long quantity = m.group("q") == null ? 1 : number(m.group("q"));
		if (id == null || quantity <= 0)
		{
			return null;
		}
		return of(GroupEvent.Type.DROP, m, at)
			.items(Collections.singletonMap(id, (int) Math.min(Integer.MAX_VALUE, quantity))).build();
	}

	/** Tags off, the game's non-breaking spaces as spaces, a leading "[Group]" and the closing full stop gone. */
	static String clean(String message)
	{
		String text = EventText.plain(message).replace(' ', ' ').trim();
		text = GROUP_TAG.matcher(text).replaceFirst("");
		return text.endsWith(".") ? text.substring(0, text.length() - 1).trim() : text;
	}

	private static long number(String digits)
	{
		Matcher m = NUMBER.matcher(digits == null ? "" : digits);
		if (!m.find())
		{
			return 0;
		}
		try
		{
			return Long.parseLong(m.group().replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	/** What one client does with a broadcast. */
	enum Action
	{
		/** Not a broadcast, or a plugin user's own (their client posts it). */
		SKIP,
		/**
		 * Log and overlays only: another plugin user posts it, it was posted already, or posting for members without
		 * the plugin is off.
		 */
		SHOW,
		/** Show it and post it: this client is the one poster. */
		POST
	}

	/**
	 * The rule (Board 2026-11-14): a member heard from over the group sync ({@code pluginUser}, the same rule as the
	 * board's "(no plugin)") posts their own events; for the rest, only the client that {@code posts} (the group
	 * setting is on and it {@link ChannelPosts#leads}) posts, and never one {@code seen} already holds.
	 */
	static Action decide(GroupEvent event, Predicate<String> pluginUser, boolean posts, Seen seen, long now)
	{
		if (event == null || pluginUser.test(event.member))
		{
			return Action.SKIP;
		}
		// Seen before (posted, or claimed by the poster ahead of this client's own line): shown, never posted again.
		boolean fresh = seen.add(key(event), now);
		return posts && fresh ? Action.POST : Action.SHOW;
	}

	/**
	 * What makes two sightings the same broadcast: the member, the kind, what it is about and the minute. Every
	 * plugin user sees the same line within a second or two, so they agree on it; a later identical line (the same
	 * drop again next minute) is a new one.
	 */
	static String key(GroupEvent e)
	{
		return (GroupMembers.key(e.member) + "|" + e.type.code + "|" + e.text.toLowerCase(Locale.ROOT) + "|"
			+ e.number + "|" + e.items.keySet() + "|" + e.at / 60_000L).replaceAll("[\\t\\n\\r]", " ");
	}

	/**
	 * The broadcasts this client has posted, or heard another plugin user post, in the last day. Saved so a restart
	 * does not post again, and fed by the party's "posted" claims so two clients never both post one.
	 * Not thread-safe: the engine holds it on the client thread.
	 */
	static final class Seen
	{
		private final LinkedHashMap<String, Long> keys = new LinkedHashMap<>();

		/** True the first time {@code key} is seen in {@link #REMEMBER_MS}; false for a repeat. */
		boolean add(String key, long now)
		{
			prune(now);
			if (key == null || key.isEmpty() || keys.containsKey(key))
			{
				return false;
			}
			keys.put(key, now);
			while (keys.size() > MAX_SEEN)
			{
				keys.remove(keys.keySet().iterator().next());
			}
			return true;
		}

		private void prune(long now)
		{
			keys.values().removeIf(at -> now - at > REMEMBER_MS || at > now + REMEMBER_MS);
		}

		/** One "time TAB key" line per broadcast. */
		String save()
		{
			StringBuilder out = new StringBuilder();
			keys.forEach((k, at) -> out.append(at).append('\t').append(k).append('\n'));
			return out.toString();
		}

		/** What {@link #save} wrote; a bad line is skipped, an empty or missing text is none. */
		static Seen load(String text, long now)
		{
			Seen seen = new Seen();
			if (text == null)
			{
				return seen;
			}
			for (String line : text.split("\n"))
			{
				int tab = line.indexOf('\t');
				long at = tab > 0 ? number(line.substring(0, tab)) : 0;
				if (at > 0)
				{
					seen.keys.put(line.substring(tab + 1), at);
				}
			}
			seen.prune(now);
			return seen;
		}
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.Function;

/**
 * What survives a restart: members' last banks, the storage log, the last
 * group storage contents, members' rune pouch, quiver and seed vault, the
 * drops log, the Log tab's feed of every event ({@code feed}), when each member was last heard from and last seen
 * online ({@code seen}, for the live board) and when this player last
 * played, as one JSON document. Each member's last stats (world, place, HP,
 * prayer, run, levels) and carried items are kept too, so an offline member's
 * card shows where they were and what they had the last time you were both
 * online. Hiscore levels for members who do not share stats ({@link HiscoreBook}) are kept with when they were
 * read, so they show across restarts too.
 *
 * <p>Pure, {@code String} in and out. The plugin reads and writes the file
 * ({@code .runelite/gim-utilities/group-cache.json}) off the client thread. A
 * file this build cannot read is treated as empty, never as an error: losing
 * a cache costs one bank visit per member.
 */
final class GroupCache
{
	static final int VERSION = 1;
	static final int MAX_MEMBERS = 50;
	/** A world number past this in the file is not a world: read as unknown. */
	private static final int MAX_WORLD = 65535;

	private GroupCache()
	{
	}

	/** One storage log entry. */
	private static JsonObject logEntry(StorageChange c)
	{
		JsonObject entry = new JsonObject();
		entry.addProperty("ts", c.at());
		entry.addProperty("by", c.member());
		entry.add("took", ItemCounts.toJson(c.took()));
		entry.add("dep", ItemCounts.toJson(c.deposited()));
		if (!c.shared())
		{
			// Only written when set, so a file without it reads as shared, as every visit was before.
			entry.addProperty("ns", true);
		}
		return entry;
	}

	static String write(Gson gson, GroupRoster roster)
	{
		return write(gson, roster, null);
	}

	/**
	 * With {@code webhooks}, the leader's signed {@link GroupWebhooks} document as the party carries it (null for
	 * none): the one place a member keeps the shared webhooks between sessions, never their RuneLite config.
	 */
	static String write(Gson gson, GroupRoster roster, String webhooks)
	{
		return write(gson, roster, webhooks, null);
	}

	/**
	 * With {@code shop}, the Shopping tab's lists, their history and members' quest progress ({@link
	 * ShoppingSync#toCache}); null for none. A build from before the Shopping tab ignores the key.
	 */
	static String write(Gson gson, GroupRoster roster, String webhooks, JsonObject shop)
	{
		JsonObject out = json(gson, roster);
		if (webhooks != null)
		{
			out.addProperty("gweb", webhooks);
		}
		if (shop != null)
		{
			out.add("shop", shop);
		}
		return gson.toJson(out);
	}

	/** The {@code shop} entry {@link #write} kept, or null when there is none or the text is unreadable. */
	static JsonElement shop(Gson gson, String json)
	{
		JsonObject root = root(gson, json);
		return root == null ? null : root.get("shop");
	}

	/** The document's JSON object; null for no text, unreadable text or anything but an object. */
	private static JsonObject root(Gson gson, String json)
	{
		return GroupCodec.object(gson, json, Integer.MAX_VALUE);
	}

	private static JsonObject json(Gson gson, GroupRoster roster)
	{
		JsonObject out = new JsonObject();
		out.addProperty("v", VERSION);

		out.add("banks", byMember(roster.banks(), b ->
		{
			JsonObject bank = new JsonObject();
			bank.addProperty("ts", b.takenAt());
			bank.add("i", ItemCounts.toJson(b.items()));
			return bank;
		}));

		JsonArray log = new JsonArray();
		for (StorageChange c : roster.log().entries())
		{
			log.add(logEntry(c));
		}
		out.add("log", log);

		if (roster.storageAt() >= 0)
		{
			JsonObject storage = new JsonObject();
			storage.addProperty("ts", roster.storageAt());
			storage.addProperty("by", roster.storageBy());
			storage.add("i", ItemCounts.toJson(roster.storageItems()));
			out.add("storage", storage);
		}

		out.add("extras", byMember(roster.extras(), e ->
		{
			JsonObject x = new JsonObject();
			x.add("rp", ItemCounts.toJson(e.runePouch));
			x.add("q", ItemCounts.toJson(e.quiver));
			x.add("sv", ItemCounts.toJson(e.seedVault));
			x.addProperty("svts", e.seedVaultAt);
			return x;
		}));

		JsonArray events = new JsonArray();
		for (GroupEvent e : roster.events().entries())
		{
			JsonObject entry = new JsonObject();
			entry.addProperty("t", e.type.code);
			entry.addProperty("ts", e.at);
			entry.addProperty("by", e.member);
			entry.addProperty("s", e.text);
			entry.add("i", ItemCounts.toJson(e.items));
			events.add(entry);
		}
		out.add("events", events);
		out.add("feed", feedJson(roster));
		out.add("heard", byMember(roster.lastHeard(), JsonPrimitive::new));
		// When each member was last seen online ({@link LastSeen}): ts, w the world, p plugin.
		out.add("seen", byMember(roster.lastSeen(), s ->
		{
			JsonObject seen = new JsonObject();
			seen.addProperty("ts", s.at);
			seen.addProperty("w", s.world);
			seen.addProperty("p", s.plugin);
			return seen;
		}));
		out.addProperty("played", roster.lastPlayed());

		// Round 2: the last stats and carried items per member, for offline cards. Stored as
		// the party payload itself so the one decoder (and its limits) reads both.
		out.add("stats", byMember(roster.allStats(), s -> new JsonPrimitive(GroupCodec.encodeStats(gson, s))));
		// The whole payload, slots included: counts alone drew a noted stack unnoted until the member
		// resent (Board 2026-11-14). A build from before slots ignores the extra fields.
		out.add("carried", byMember(roster.allCarried(), c -> new JsonPrimitive(GroupCodec.encodeCarried(gson, c))));
		// Each member's last hiscore lookup: {"name": {"ts": 1700000000000, "l": {"Attack": 99}}}.
		out.add("hiscores", byMember(roster.hiscores().all(), h ->
		{
			JsonObject entry = new JsonObject();
			entry.addProperty("ts", h.at);
			JsonObject levels = new JsonObject();
			h.levels.forEach(levels::addProperty);
			entry.add("l", levels);
			return entry;
		}));
		return out;
	}

	/** {@code {"name": entry, ...}} in the map's order. */
	private static <T> JsonObject byMember(Map<String, T> members, Function<T, JsonElement> entry)
	{
		JsonObject out = new JsonObject();
		members.forEach((name, value) -> out.add(name, entry.apply(value)));
		return out;
	}

	/**
	 * Each of the first {@link #MAX_MEMBERS} entries of a by-member object; nothing when {@code in} is not one (a
	 * file from before that key). An entry that is not readable still counts toward the limit.
	 */
	private static void eachMember(JsonElement in, BiConsumer<String, JsonElement> read)
	{
		if (in == null || !in.isJsonObject())
		{
			return;
		}
		int n = 0;
		for (Map.Entry<String, JsonElement> e : in.getAsJsonObject().entrySet())
		{
			if (n++ < MAX_MEMBERS)
			{
				read.accept(e.getKey(), e.getValue());
			}
		}
	}

	/** {@link #eachMember}, for the entries that are objects. */
	private static void eachMemberObject(JsonElement in, BiConsumer<String, JsonObject> read)
	{
		eachMember(in, (name, value) ->
		{
			if (value.isJsonObject())
			{
				read.accept(name, value.getAsJsonObject());
			}
		});
	}

	/** Each object in the array {@code in}; nothing when it is not an array. */
	private static void eachObject(JsonElement in, Consumer<JsonObject> read)
	{
		if (in == null || !in.isJsonArray())
		{
			return;
		}
		for (JsonElement item : in.getAsJsonArray())
		{
			if (item.isJsonObject())
			{
				read.accept(item.getAsJsonObject());
			}
		}
	}

	/** {@code by}, the member an entry is filed under; null when missing. */
	private static String by(JsonObject entry)
	{
		JsonElement by = entry.get("by");
		return by == null || !by.isJsonPrimitive() ? null : by.getAsString();
	}

	/** The numbers in {@code l}; {@link HiscoreBook#restore} drops the ones out of range. */
	private static Map<String, Integer> levelsFrom(JsonObject l)
	{
		Map<String, Integer> levels = new LinkedHashMap<>();
		for (Map.Entry<String, JsonElement> s : l.entrySet())
		{
			Long level = ItemCounts.longValue(s.getValue());
			if (level != null)
			{
				levels.put(s.getKey(), (int) Math.max(0, Math.min(level, Integer.MAX_VALUE)));
			}
		}
		return levels;
	}

	/**
	 * The Log tab's feed: every event as the party sends it ({@link GroupCodec#eventJson}),
	 * plus {@code by} and, for a storage summary, {@code tk} its withdrawals.
	 */
	private static JsonArray feedJson(GroupRoster roster)
	{
		JsonArray feed = new JsonArray();
		for (GroupEvent e : roster.feed().entries())
		{
			JsonObject entry = GroupCodec.eventJson(e);
			entry.addProperty("by", e.member);
			if (!e.taken.isEmpty())
			{
				entry.add("tk", ItemCounts.toJson(e.taken));
			}
			feed.add(entry);
		}
		return feed;
	}

	/** One {@code seen} entry; null without a time. */
	private static LastSeen lastSeen(JsonElement item)
	{
		if (!item.isJsonObject())
		{
			return null;
		}
		JsonObject s = item.getAsJsonObject();
		Long at = ItemCounts.longValue(s.get("ts"));
		if (at == null || at <= 0)
		{
			return null;
		}
		Long world = ItemCounts.longValue(s.get("w"));
		int w = world == null || world < 0 || world > MAX_WORLD ? 0 : world.intValue();
		return new LastSeen(at, w, isTrue(s.get("p")));
	}

	private static boolean isTrue(JsonElement p)
	{
		return p != null && p.isJsonPrimitive() && p.getAsJsonPrimitive().isBoolean() && p.getAsBoolean();
	}

	/**
	 * The feed. A file from before it existed has none: the feed starts from
	 * that file's drops log and storage log, so the Log tab keeps its history.
	 */
	private static void readFeed(JsonElement feed, GroupRoster roster)
	{
		if (feed == null || !feed.isJsonArray())
		{
			seedFeed(roster);
			return;
		}
		for (JsonElement item : feed.getAsJsonArray())
		{
			GroupEvent event = feedEvent(item);
			if (event != null)
			{
				roster.feed().add(event);
			}
		}
	}

	/** One feed entry; null when it has no member or is not an event this build reads. */
	private static GroupEvent feedEvent(JsonElement item)
	{
		String by = item.isJsonObject() ? by(item.getAsJsonObject()) : null;
		GroupEvent event = by == null ? null : GroupCodec.eventFrom(item.getAsJsonObject(), by);
		return event == null ? null : event.toBuilder()
			.taken(ItemCounts.fromJson(item.getAsJsonObject().get("tk"), GroupCodec.MAX_STORAGE_ITEMS)).build();
	}

	/** A feed from an older file's drops log and storage log, already read into {@code roster}. */
	private static void seedFeed(GroupRoster roster)
	{
		for (GroupEvent e : roster.events().entries())
		{
			roster.feed().add(e);
		}
		for (StorageChange c : roster.log().entries())
		{
			roster.feed().add(GroupEvent.of(GroupEvent.Type.STORAGE_SUMMARY, c.at(), c.member())
				.items(c.deposited()).taken(c.took()).build());
		}
	}

	private static void readPayloads(Gson gson, JsonElement in, GroupRoster roster)
	{
		eachMember(in, (name, value) ->
		{
			GroupCodec.Decoded d = value.isJsonPrimitive() ? GroupCodec.decode(gson, value.getAsString()) : null;
			if (d != null && d.kind == GroupCodec.Kind.STATS)
			{
				roster.putStats(name, d.stats);
			}
			else if (d != null && d.kind == GroupCodec.Kind.CARRIED)
			{
				roster.putCarried(name, d.carried);
			}
		});
	}

	/** The webhooks document {@link #write(Gson, GroupRoster, String)} kept, or null; its signature is checked later. */
	static String webhooks(Gson gson, String json)
	{
		JsonObject root = root(gson, json);
		JsonElement w = root == null ? null : root.get("gweb");
		return w != null && w.isJsonPrimitive() ? w.getAsString() : null;
	}

	/** Loads into {@code roster}. Returns false, leaving it untouched, when the text is unreadable. */
	static boolean read(Gson gson, String json, GroupRoster roster)
	{
		JsonObject in = root(gson, json);
		Long v = in == null ? null : ItemCounts.longValue(in.get("v"));
		if (v == null || v < 1)
		{
			return false;
		}

		eachMemberObject(in.get("banks"), (name, bank) ->
		{
			Long ts = ItemCounts.longValue(bank.get("ts"));
			if (ts != null)
			{
				roster.putBank(name, new BankSnapshot(ts, ItemCounts.fromJson(bank.get("i"), GroupCodec.MAX_BANK_ITEMS)));
			}
		});

		eachObject(in.get("log"), entry ->
		{
			Long ts = ItemCounts.longValue(entry.get("ts"));
			String by = by(entry);
			if (ts != null && by != null)
			{
				roster.log().add(new StorageChange(ts, by,
					ItemCounts.fromJson(entry.get("took"), GroupCodec.MAX_STORAGE_ITEMS),
					ItemCounts.fromJson(entry.get("dep"), GroupCodec.MAX_STORAGE_ITEMS),
					Collections.emptyMap(), !isTrue(entry.get("ns"))));
			}
		});

		JsonElement storage = in.get("storage");
		if (storage != null && storage.isJsonObject())
		{
			JsonObject s = storage.getAsJsonObject();
			Long ts = ItemCounts.longValue(s.get("ts"));
			String by = by(s);
			if (ts != null)
			{
				roster.restoreStorage(ts, by == null ? "" : by,
					ItemCounts.fromJson(s.get("i"), GroupCodec.MAX_STORAGE_ITEMS));
			}
		}

		// Part 3. A part 2 file has none of these keys and loads as before.
		eachMemberObject(in.get("extras"), (name, x) ->
		{
			Long svts = ItemCounts.longValue(x.get("svts"));
			roster.putExtras(name, new MemberExtras(
				ItemCounts.fromJson(x.get("rp"), GroupCodec.MAX_POUCH_ITEMS),
				ItemCounts.fromJson(x.get("q"), GroupCodec.MAX_QUIVER_ITEMS),
				ItemCounts.fromJson(x.get("sv"), GroupCodec.MAX_SEED_VAULT_ITEMS),
				svts == null ? -1 : svts));
		});

		eachObject(in.get("events"), entry ->
		{
			String by = by(entry);
			GroupEvent event = by == null ? null : GroupCodec.eventFrom(entry, by);
			if (event != null && event.type.logged())
			{
				roster.events().add(event);
			}
		});

		// After "log" and "events": an older file's feed starts from them.
		readFeed(in.get("feed"), roster);

		eachMember(in.get("heard"), (name, value) ->
		{
			Long at = ItemCounts.longValue(value);
			if (at != null && at > 0)
			{
				roster.heard(name, at);
			}
		});

		// A file from before last-seen was kept has none, and loads as before.
		eachMember(in.get("seen"), (name, value) ->
		{
			LastSeen s = lastSeen(value);
			if (s != null)
			{
				roster.seen(name, s);
			}
		});

		Long played = ItemCounts.longValue(in.get("played"));
		if (played != null && played > 0)
		{
			roster.markPlayed(played);
		}
		readPayloads(gson, in.get("stats"), roster);
		readPayloads(gson, in.get("carried"), roster);
		// A file from before hiscores has no key and loads as before.
		eachMemberObject(in.get("hiscores"), (name, entry) ->
		{
			Long ts = ItemCounts.longValue(entry.get("ts"));
			JsonElement l = entry.get("l");
			if (ts != null && l != null && l.isJsonObject())
			{
				roster.hiscores().restore(name, ts, levelsFrom(l.getAsJsonObject()));
			}
		});
		return true;
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

/**
 * The JSON inside a {@link VvgGroupIronmanMessage}: one of six kinds, each
 * tagged {@code k}.
 *
 * <ul>
 * <li>{@code bank}: one part of a bank snapshot. A bank is split into parts
 * so no single message exceeds {@link #MAX_PAYLOAD_CHARS}.</li>
 * <li>{@code carried}: inventory and worn items.</li>
 * <li>{@code storage}: one group storage visit, see {@link StorageChange}.</li>
 * <li>{@code stats}: live levels, status and position, see {@link MemberStats}.</li>
 * <li>{@code extras}: rune pouch, quiver and seed vault, see {@link MemberExtras}.</li>
 * <li>{@code events}: drops and new collection log slots, split like a bank,
 * see {@link GroupEvent}.</li>
 * </ul>
 *
 * <p><b>Why a size cap of our own.</b> RuneLite 1.12.39's {@code WSClient}
 * puts the Gson JSON of a party message into a protobuf {@code Party.Data}
 * and hands it to OkHttp's {@code WebSocket.send(ByteString)}; the client
 * itself imposes no limit. OkHttp 3.14.9 only refuses a send that would push
 * its outgoing queue past {@code RealWebSocket.MAX_QUEUE_SIZE} (16 MiB), and
 * the party relay's own limit is not published. So this plugin picks a budget
 * far below anything a relay is likely to enforce and splits to fit it.
 *
 * <p><b>Version tolerance</b>: any {@code v >= 1} is read, unknown kinds and fields are ignored, missing
 * fields decode to empty, and every list is capped.
 */
final class GroupCodec
{
	static final int PROTOCOL = 1;

	/** The largest payload this build will send in one message. */
	static final int MAX_PAYLOAD_CHARS = 6000;

	/** A bank holds at most 1,410 distinct items with every expansion bought; the rest is headroom. */
	static final int MAX_BANK_ITEMS = 1600;
	static final int MAX_BANK_PARTS = 16;
	static final int MAX_STORAGE_ITEMS = 500;
	static final int MAX_CARRIED_ITEMS = 64;
	/** The game's inventory: 28 slots. */
	static final int INVENTORY_SLOTS = 28;
	static final int MAX_SKILLS = 40;
	/** The fullest container tracked holds 36 (a coal bag with a Smithing cape); the rest is headroom. */
	static final int MAX_HELD = 100;
	/** Kinds of item one container can report; a basket of every log is under 20. */
	static final int MAX_HELD_KINDS = 30;

	/** Room for the header fields of a bank part, generously. */
	private static final int BANK_HEADER_CHARS = 120;

	/** The rune pouch has four slots, six with the divine upgrade; the rest is headroom. */
	static final int MAX_POUCH_ITEMS = 8;
	static final int MAX_QUIVER_ITEMS = 2;
	/**
	 * Chosen so the fullest extras message fits {@link #MAX_PAYLOAD_CHARS}: an
	 * item pair is at most 19 characters, and 250 of them is 4,750. The game has
	 * well under 250 kinds of seed.
	 */
	static final int MAX_SEED_VAULT_ITEMS = 250;
	static final int MAX_EVENTS_PER_MESSAGE = 100;
	/** World tiles stay well under this on both axes. */
	static final int MAX_COORD = 1 << 15;

	/** Room for {@code {"v":1,"k":"events","e":[]}} and change. */
	private static final int EVENTS_HEADER_CHARS = 40;

	/**
	 * The {@code k} on the wire. {@link #EXTRAS} and {@link #EVENTS} came in
	 * part 3; a part 2 build reads them as an unknown kind and ignores them.
	 */
	enum Kind
	{
		BANK, CARRIED, STORAGE, STATS, EXTRAS, EVENTS
	}

	/**
	 * The {@code k} of a "posted" claim ({@link #encodePosted}): not a {@link Kind}, as it is no member data;
	 * {@link #decode} reads it as unknown, like every older build does, and {@link #posted} reads it.
	 */
	static final String POSTED = "posted";
	/** Most broadcast keys one claim carries, and the longest key kept. */
	static final int MAX_POSTED = 20;
	static final int MAX_POSTED_CHARS = 200;

	/** One part of a split bank snapshot. */
	static final class BankPart
	{
		final long takenAt;
		final int part;
		final int of;
		final Map<Integer, Integer> items;

		BankPart(long takenAt, int part, int of, Map<Integer, Integer> items)
		{
			this.takenAt = takenAt;
			this.part = part;
			this.of = of;
			this.items = items;
		}
	}

	/** One inventory slot as the game holds it: the raw item id (noted stays noted), or empty. */
	static final class Slot
	{
		static final Slot EMPTY = new Slot(0, 0);

		final int id;
		final int quantity;

		private Slot(int id, int quantity)
		{
			this.id = id;
			this.quantity = quantity;
		}

		/** {@link #EMPTY} for the game's empty slot (id -1, quantity 0) and for anything that is not an item. */
		static Slot of(long id, long quantity)
		{
			if (id <= 0 || id >= ItemCounts.MAX_ITEM_ID || quantity <= 0)
			{
				return EMPTY;
			}
			return new Slot((int) id, (int) Math.min(Integer.MAX_VALUE, quantity));
		}

		boolean empty()
		{
			return id <= 0;
		}
	}

	/**
	 * What a carried log basket, fish barrel or coal bag holds, as its sender knows it: the count, and the
	 * items by canonical id when every one is known (empty otherwise, never a guess).
	 */
	static final class Held
	{
		final int count;
		final Map<Integer, Integer> items;

		Held(int count, Map<Integer, Integer> items)
		{
			this.count = count;
			this.items = ItemCounts.sorted(items);
		}
	}

	static final class Carried
	{
		/** Canonical counts (noted counted as the item): what Find, ::find and totals read. */
		final Map<Integer, Integer> inventory;
		final Map<Integer, Integer> worn;
		/**
		 * The inventory's {@link #INVENTORY_SLOTS} slots in the game's order, or empty when the sender's build
		 * shares only counts. Only the Group tab's inventory grid reads these.
		 */
		final List<Slot> slots;
		/** Known contents of carried containers; a container missing here is unknown. */
		final Map<SkillingContainer, Held> contents;

		Carried(Map<Integer, Integer> inventory, Map<Integer, Integer> worn)
		{
			this(inventory, worn, Collections.emptyList());
		}

		Carried(Map<Integer, Integer> inventory, Map<Integer, Integer> worn, List<Slot> slots)
		{
			this(inventory, worn, slots, Collections.emptyMap());
		}

		Carried(Map<Integer, Integer> inventory, Map<Integer, Integer> worn, List<Slot> slots,
			Map<SkillingContainer, Held> contents)
		{
			this.inventory = ItemCounts.sorted(inventory);
			this.worn = ItemCounts.sorted(worn);
			this.slots = inventorySlots(slots);
			this.contents = contents.isEmpty() ? Collections.emptyMap()
				: Collections.unmodifiableMap(new EnumMap<>(contents));
		}

		/** Every id carried: counted, in a slot or inside a container, for name lookups. */
		Set<Integer> ids()
		{
			Set<Integer> out = ItemCounts.ids(inventory, worn);
			out.addAll(slotIds());
			out.addAll(heldIds());
			return out;
		}

		/** The ids known inside containers, for name lookups (Find). */
		Set<Integer> heldIds()
		{
			Set<Integer> out = new TreeSet<>();
			for (Held h : contents.values())
			{
				out.addAll(h.items.keySet());
			}
			return out;
		}

		/** What {@code container} holds, or -1 when the sender does not know. */
		int inside(SkillingContainer container)
		{
			Held h = container == null ? null : contents.get(container);
			return h == null ? -1 : h.count;
		}

		/** The ids drawn in {@link #slots}, for name lookups. */
		Set<Integer> slotIds()
		{
			Set<Integer> out = new TreeSet<>();
			for (Slot s : slots)
			{
				if (!s.empty())
				{
					out.add(s.id);
				}
			}
			return out;
		}
	}

	/** Exactly {@link #INVENTORY_SLOTS} slots, cut or padded with empties; none stays none. */
	private static List<Slot> inventorySlots(List<Slot> slots)
	{
		if (slots.isEmpty())
		{
			return Collections.emptyList();
		}
		List<Slot> out = new ArrayList<>(INVENTORY_SLOTS);
		for (int i = 0; i < INVENTORY_SLOTS; i++)
		{
			Slot s = i < slots.size() ? slots.get(i) : null;
			out.add(s == null ? Slot.EMPTY : s);
		}
		return Collections.unmodifiableList(out);
	}

	/** Exactly one of the fields is set, matching {@link #kind}. */
	static final class Decoded
	{
		final Kind kind;
		final BankPart bank;
		final Carried carried;
		final StorageChange storage;
		final MemberStats stats;
		final MemberExtras extras;
		/** Each with an empty member: the receiver files them under the party member they came from. */
		final List<GroupEvent> events;

		private Decoded(Kind kind, BankPart bank, Carried carried, StorageChange storage, MemberStats stats,
			MemberExtras extras, List<GroupEvent> events)
		{
			this.kind = kind;
			this.bank = bank;
			this.carried = carried;
			this.storage = storage;
			this.stats = stats;
			this.extras = extras;
			this.events = events;
		}

		static Decoded of(BankPart bank)
		{
			return new Decoded(Kind.BANK, bank, null, null, null, null, null);
		}

		static Decoded of(Carried carried)
		{
			return new Decoded(Kind.CARRIED, null, carried, null, null, null, null);
		}

		static Decoded of(StorageChange storage)
		{
			return new Decoded(Kind.STORAGE, null, null, storage, null, null, null);
		}

		static Decoded of(MemberStats stats)
		{
			return new Decoded(Kind.STATS, null, null, null, stats, null, null);
		}

		static Decoded of(MemberExtras extras)
		{
			return new Decoded(Kind.EXTRAS, null, null, null, null, extras, null);
		}

		static Decoded of(List<GroupEvent> events)
		{
			return new Decoded(Kind.EVENTS, null, null, null, null, null, events);
		}
	}

	private GroupCodec()
	{
	}

	/** One payload per part, each within {@link #MAX_PAYLOAD_CHARS}. An empty bank is one empty part. */
	static List<String> encodeBank(Gson gson, BankSnapshot bank)
	{
		List<Map<Integer, Integer>> chunks = new ArrayList<>();
		Map<Integer, Integer> current = new TreeMap<>();
		int chars = BANK_HEADER_CHARS;
		int kept = 0;
		for (Map.Entry<Integer, Integer> e : bank.items().entrySet())
		{
			if (kept >= MAX_BANK_ITEMS)
			{
				break;
			}
			int pair = digits(e.getKey()) + digits(e.getValue()) + 2;
			if (chars + pair > MAX_PAYLOAD_CHARS && !current.isEmpty())
			{
				chunks.add(current);
				current = new TreeMap<>();
				chars = BANK_HEADER_CHARS;
			}
			current.put(e.getKey(), e.getValue());
			chars += pair;
			kept++;
		}
		chunks.add(current);

		List<String> out = new ArrayList<>();
		for (int i = 0; i < chunks.size() && i < MAX_BANK_PARTS; i++)
		{
			JsonObject o = header(Kind.BANK);
			o.addProperty("ts", bank.takenAt());
			o.addProperty("p", i);
			o.addProperty("n", Math.min(chunks.size(), MAX_BANK_PARTS));
			o.add("i", ItemCounts.toJson(chunks.get(i)));
			out.add(gson.toJson(o));
		}
		return out;
	}

	/** Counts only, the shape every build reads and a build from before slots sends. */
	static String encodeCarried(Gson gson, Map<Integer, Integer> inventory, Map<Integer, Integer> worn)
	{
		return encodeCarried(gson, inventory, worn, Collections.emptyList());
	}

	/**
	 * Counts in {@code inv} and {@code eq} exactly as before, plus {@code is}: the inventory slots in order as
	 * {@code [id, qty, ...]}, {@code 0, 0} for an empty slot, raw ids so a noted stack draws noted. A build from
	 * before slots ignores {@code is} as an unknown field and keeps showing counts. At most 28 pairs of numbers
	 * under 11 digits each: about 650 characters, well inside {@link #MAX_PAYLOAD_CHARS}.
	 */
	static String encodeCarried(Gson gson, Map<Integer, Integer> inventory, Map<Integer, Integer> worn,
		List<Slot> slots)
	{
		return encodeCarried(gson, new Carried(inventory, worn, slots));
	}

	/**
	 * As above, plus {@code cc}: what each carried container is known to hold, as
	 * {@code {"LOG_BASKET":{"n":19,"i":[id, qty, ...]}}}, {@code i} only when every item is known. A build
	 * from before contents ignores {@code cc} as an unknown field and draws no number.
	 */
	static String encodeCarried(Gson gson, Carried carried)
	{
		JsonObject o = carriedJson(carried.inventory, carried.worn, carried.slots);
		if (!carried.contents.isEmpty())
		{
			JsonObject cc = new JsonObject();
			for (Map.Entry<SkillingContainer, Held> e : carried.contents.entrySet())
			{
				JsonObject held = new JsonObject();
				held.addProperty("n", e.getValue().count);
				if (!e.getValue().items.isEmpty())
				{
					held.add("i", ItemCounts.toJson(e.getValue().items));
				}
				cc.add(e.getKey().name(), held);
			}
			o.add("cc", cc);
		}
		return gson.toJson(o);
	}

	private static JsonObject carriedJson(Map<Integer, Integer> inventory, Map<Integer, Integer> worn,
		List<Slot> slots)
	{
		JsonObject o = header(Kind.CARRIED);
		o.add("inv", ItemCounts.toJson(inventory));
		o.add("eq", ItemCounts.toJson(worn));
		List<Slot> kept = inventorySlots(slots);
		if (!kept.isEmpty())
		{
			JsonArray is = new JsonArray();
			for (Slot s : kept)
			{
				is.add(s.id);
				is.add(s.quantity);
			}
			o.add("is", is);
		}
		return o;
	}

	static String encodeStorage(Gson gson, StorageChange change)
	{
		JsonObject o = header(Kind.STORAGE);
		o.addProperty("ts", change.at());
		o.add("took", ItemCounts.toJson(change.took()));
		o.add("dep", ItemCounts.toJson(change.deposited()));
		o.add("now", ItemCounts.toJson(change.after()));
		return gson.toJson(o);
	}

	static String encodeStats(Gson gson, MemberStats stats)
	{
		JsonObject o = header(Kind.STATS);
		JsonObject skills = new JsonObject();
		for (Map.Entry<String, MemberStats.Level> e : stats.skills().entrySet())
		{
			JsonArray pair = new JsonArray();
			pair.add(e.getValue().real);
			pair.add(e.getValue().boosted);
			skills.add(e.getKey(), pair);
		}
		o.add("s", skills);
		o.addProperty("run", stats.runEnergy());
		o.addProperty("spec", stats.specialAttack());
		o.addProperty("w", stats.world());
		o.addProperty("r", stats.region());
		if (stats.hasPosition())
		{
			o.addProperty("x", stats.x());
			o.addProperty("y", stats.y());
			o.addProperty("pl", stats.plane());
		}
		return gson.toJson(o);
	}

	/** One message; the seed vault is cut to {@link #MAX_SEED_VAULT_ITEMS} so it always fits. */
	static String encodeExtras(Gson gson, MemberExtras extras)
	{
		JsonObject o = header(Kind.EXTRAS);
		o.add("rp", ItemCounts.toJson(first(extras.runePouch, MAX_POUCH_ITEMS)));
		o.add("q", ItemCounts.toJson(first(extras.quiver, MAX_QUIVER_ITEMS)));
		o.add("sv", ItemCounts.toJson(first(extras.seedVault, MAX_SEED_VAULT_ITEMS)));
		o.addProperty("svts", extras.seedVaultAt);
		return gson.toJson(o);
	}

	/**
	 * As many messages as it takes to fit {@link #MAX_PAYLOAD_CHARS}, none for
	 * no events. Sizes are measured on the JSON Gson actually writes, so names
	 * Gson escapes are counted at their escaped length.
	 */
	static List<String> encodeEvents(Gson gson, List<GroupEvent> events)
	{
		List<String> out = new ArrayList<>();
		JsonArray current = new JsonArray();
		int chars = EVENTS_HEADER_CHARS;
		for (GroupEvent e : events)
		{
			if (!e.type.travels())
			{
				continue;
			}
			JsonObject event = eventJson(e);
			int size = gson.toJson(event).length() + 1;
			if (current.size() > 0 && (chars + size > MAX_PAYLOAD_CHARS || current.size() >= MAX_EVENTS_PER_MESSAGE))
			{
				out.add(eventsPayload(gson, current));
				current = new JsonArray();
				chars = EVENTS_HEADER_CHARS;
			}
			current.add(event);
			chars += size;
		}
		if (current.size() > 0)
		{
			out.add(eventsPayload(gson, current));
		}
		return out;
	}

	/**
	 * One event: {@code t} type code, {@code ts}, {@code s} text, {@code i}
	 * items, and only when set {@code n} number, {@code x} detail, {@code w}
	 * world, {@code l} location. A 1.0.0 build reads {@code d} and {@code c}
	 * exactly as before and skips every other code.
	 */
	static JsonObject eventJson(GroupEvent e)
	{
		JsonObject event = new JsonObject();
		event.addProperty("t", e.type.code);
		event.addProperty("ts", e.at);
		event.addProperty("s", e.text);
		if (!e.items.isEmpty() || e.type == GroupEvent.Type.DROP)
		{
			event.add("i", ItemCounts.toJson(e.items));
		}
		if (e.number != 0)
		{
			event.addProperty("n", e.number);
		}
		if (!e.detail.isEmpty())
		{
			event.addProperty("x", e.detail);
		}
		if (e.world > 0)
		{
			event.addProperty("w", e.world);
		}
		if (!e.location.isEmpty())
		{
			event.addProperty("l", e.location);
		}
		return event;
	}

	/** The event in {@code o}, filed under {@code member}; null when a required field is missing or the code unknown. */
	static GroupEvent eventFrom(JsonObject o, String member)
	{
		Long ts = ItemCounts.longValue(o.get("ts"));
		GroupEvent.Type type = GroupEvent.Type.of(string(o.get("t")));
		JsonElement s = o.get("s");
		if (ts == null || ts < 0 || type == null || s == null || !s.isJsonPrimitive())
		{
			return null;
		}
		return GroupEvent.of(type, ts, member).text(s.getAsString())
			.items(ItemCounts.fromJson(o.get("i"), GroupEvent.MAX_DROP_ITEMS))
			.number(number(o.get("n"), Long.MIN_VALUE, Long.MAX_VALUE))
			.detail(string(o.get("x")))
			.world((int) number(o.get("w"), 0, MAX_COORD))
			.location(string(o.get("l")))
			.build();
	}

	private static String string(JsonElement e)
	{
		return e != null && e.isJsonPrimitive() ? e.getAsString() : "";
	}

	/** The whole number in {@code e}, 0 when missing or outside {@code min..max}. */
	private static long number(JsonElement e, long min, long max)
	{
		Long n = ItemCounts.longValue(e);
		return n == null || n < min || n > max ? 0 : n;
	}

	private static String eventsPayload(Gson gson, JsonArray events)
	{
		JsonObject o = header(Kind.EVENTS);
		o.add("e", events);
		return gson.toJson(o);
	}

	private static Map<Integer, Integer> first(Map<Integer, Integer> counts, int max)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		for (Map.Entry<Integer, Integer> e : new TreeMap<>(counts).entrySet())
		{
			if (out.size() >= max)
			{
				break;
			}
			out.put(e.getKey(), e.getValue());
		}
		return out;
	}

	/** The decoded message, or null when it is not one this build can read. */
	static Decoded decode(Gson gson, String json)
	{
		JsonObject in = object(gson, json, MAX_PAYLOAD_CHARS * 4);
		if (in == null)
		{
			return null;
		}
		Long v = ItemCounts.longValue(in.get("v"));
		if (v == null || v < 1)
		{
			return null;
		}
		JsonElement k = in.get("k");
		if (k == null || !k.isJsonPrimitive())
		{
			return null;
		}
		switch (k.getAsString())
		{
			case "bank":
				return decodeBank(in);
			case "carried":
				return Decoded.of(new Carried(
					ItemCounts.fromJson(in.get("inv"), MAX_CARRIED_ITEMS),
					ItemCounts.fromJson(in.get("eq"), MAX_CARRIED_ITEMS),
					slotsFrom(in.get("is")),
					contentsFrom(in.get("cc"))));
			case "storage":
				return Decoded.of(new StorageChange(
					longOr(in.get("ts"), 0),
					"",
					ItemCounts.fromJson(in.get("took"), MAX_STORAGE_ITEMS),
					ItemCounts.fromJson(in.get("dep"), MAX_STORAGE_ITEMS),
					ItemCounts.fromJson(in.get("now"), MAX_STORAGE_ITEMS)));
			case "stats":
				return decodeStats(in);
			case "extras":
				return Decoded.of(new MemberExtras(
					ItemCounts.fromJson(in.get("rp"), MAX_POUCH_ITEMS),
					ItemCounts.fromJson(in.get("q"), MAX_QUIVER_ITEMS),
					ItemCounts.fromJson(in.get("sv"), MAX_SEED_VAULT_ITEMS),
					longOr(in.get("svts"), -1)));
			case "events":
				return decodeEvents(in);
			default:
				// A kind from a newer build.
				return null;
		}
	}

	private static Decoded decodeBank(JsonObject in)
	{
		long ts = longOr(in.get("ts"), -1);
		long part = longOr(in.get("p"), -1);
		long of = longOr(in.get("n"), -1);
		if (ts < 0 || of < 1 || of > MAX_BANK_PARTS || part < 0 || part >= of)
		{
			return null;
		}
		Map<Integer, Integer> items = ItemCounts.fromJson(in.get("i"), MAX_BANK_ITEMS);
		return Decoded.of(new BankPart(ts, (int) part, (int) of, items));
	}

	/** A bad pair is an empty slot in its place, so the rest keep their positions; past 28 slots is dropped. */
	private static List<Slot> slotsFrom(JsonElement e)
	{
		List<Slot> out = new ArrayList<>();
		if (e == null || !e.isJsonArray())
		{
			return out;
		}
		JsonArray array = e.getAsJsonArray();
		for (int i = 0; i + 1 < array.size() && out.size() < INVENTORY_SLOTS; i += 2)
		{
			Long id = ItemCounts.longValue(array.get(i));
			Long qty = ItemCounts.longValue(array.get(i + 1));
			out.add(id == null || qty == null ? Slot.EMPTY : Slot.of(id, qty));
		}
		return out;
	}

	/**
	 * Containers from a newer build, and counts that cannot be a container's (negative, or past
	 * {@link #MAX_HELD}), are skipped one at a time; a missing {@code cc} is no container known.
	 */
	private static Map<SkillingContainer, Held> contentsFrom(JsonElement e)
	{
		Map<SkillingContainer, Held> out = new EnumMap<>(SkillingContainer.class);
		if (e == null || !e.isJsonObject())
		{
			return out;
		}
		for (Map.Entry<String, JsonElement> entry : e.getAsJsonObject().entrySet())
		{
			SkillingContainer kind = SkillingContainer.fromKey(entry.getKey());
			if (kind == null || !entry.getValue().isJsonObject())
			{
				continue;
			}
			JsonObject held = entry.getValue().getAsJsonObject();
			long n = longOr(held.get("n"), -1);
			if (n >= 0 && n <= MAX_HELD)
			{
				out.put(kind, new Held((int) n, ItemCounts.fromJson(held.get("i"), MAX_HELD_KINDS)));
			}
		}
		return out;
	}

	/** Bad events are skipped one at a time, like bad item pairs. */
	private static Decoded decodeEvents(JsonObject in)
	{
		List<GroupEvent> events = new ArrayList<>();
		JsonElement e = in.get("e");
		if (e != null && e.isJsonArray())
		{
			for (JsonElement item : e.getAsJsonArray())
			{
				if (events.size() >= MAX_EVENTS_PER_MESSAGE)
				{
					break;
				}
				if (!item.isJsonObject())
				{
					continue;
				}
				GroupEvent event = eventFrom(item.getAsJsonObject(), "");
				if (event != null && event.type.travels() && event.isValid())
				{
					events.add(event);
				}
			}
		}
		return Decoded.of(events);
	}

	/** {@code {"v":1,"k":"posted","p":[key, ...]}}: the game broadcasts this client just posted. */
	static String encodePosted(Gson gson, List<String> keys)
	{
		JsonObject o = header(POSTED);
		JsonArray p = new JsonArray();
		for (String key : keys)
		{
			if (p.size() < MAX_POSTED && key != null && !key.isEmpty() && key.length() <= MAX_POSTED_CHARS)
			{
				p.add(key);
			}
		}
		o.add("p", p);
		return gson.toJson(o);
	}

	/**
	 * The keys of a "posted" claim: strings only, each within {@link #MAX_POSTED_CHARS}, at most {@link #MAX_POSTED}.
	 * Null for any other payload.
	 */
	static List<String> posted(Gson gson, String json)
	{
		JsonObject in = object(gson, json, MAX_PAYLOAD_CHARS);
		JsonElement k = in == null ? null : in.get("k");
		if (k == null || !k.isJsonPrimitive() || !POSTED.equals(k.getAsString()))
		{
			return null;
		}
		return postedKeys(in.get("p"));
	}

	private static List<String> postedKeys(JsonElement p)
	{
		List<String> keys = new ArrayList<>();
		if (p == null || !p.isJsonArray())
		{
			return keys;
		}
		for (JsonElement item : p.getAsJsonArray())
		{
			if (keys.size() < MAX_POSTED && isPostedKey(item))
			{
				keys.add(item.getAsString());
			}
		}
		return keys;
	}

	private static boolean isPostedKey(JsonElement item)
	{
		if (!item.isJsonPrimitive() || !item.getAsJsonPrimitive().isString())
		{
			return false;
		}
		String key = item.getAsString();
		return !key.isEmpty() && key.length() <= MAX_POSTED_CHARS;
	}

	/** The payload's JSON object; null when it is empty, longer than {@code maxChars}, or not an object. */
	static JsonObject object(Gson gson, String json, int maxChars)
	{
		if (json == null || json.isEmpty() || json.length() > maxChars)
		{
			return null;
		}
		try
		{
			JsonElement root = gson.fromJson(json, JsonElement.class);
			return root != null && root.isJsonObject() ? root.getAsJsonObject() : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static Decoded decodeStats(JsonObject in)
	{
		Map<String, MemberStats.Level> skills = new LinkedHashMap<>();
		JsonElement s = in.get("s");
		if (s != null && s.isJsonObject())
		{
			for (Map.Entry<String, JsonElement> e : s.getAsJsonObject().entrySet())
			{
				if (skills.size() >= MAX_SKILLS || !e.getValue().isJsonArray())
				{
					continue;
				}
				JsonArray pair = e.getValue().getAsJsonArray();
				if (pair.size() < 2)
				{
					continue;
				}
				Long real = ItemCounts.longValue(pair.get(0));
				Long boosted = ItemCounts.longValue(pair.get(1));
				// Real levels are 1-99 (Hitpoints starts at 10); boosts never pass 99 + 30 or go below 0.
				if (real == null || boosted == null || real < 1 || real > 99 || boosted < 0 || boosted > 150)
				{
					continue;
				}
				String name = e.getKey().trim();
				if (!name.isEmpty() && name.length() <= 32)
				{
					skills.put(name, new MemberStats.Level(real.intValue(), boosted.intValue()));
				}
			}
		}
		return Decoded.of(new MemberStats(skills,
			clamp(longOr(in.get("run"), 0), 0, 100),
			clamp(longOr(in.get("spec"), 0), 0, 100),
			clamp(longOr(in.get("w"), 0), 0, 9999),
			clamp(longOr(in.get("r"), 0), 0, 1 << 16),
			clamp(longOr(in.get("x"), 0), 0, MAX_COORD),
			clamp(longOr(in.get("y"), 0), 0, MAX_COORD),
			clamp(longOr(in.get("pl"), 0), 0, 3)));
	}

	private static JsonObject header(Kind kind)
	{
		return header(kind.name().toLowerCase(Locale.ROOT));
	}

	/** {@code {"v":1,"k":kind}}, the start of every payload; also {@link ShoppingCodec}'s and {@link GovernanceCodec}'s. */
	static JsonObject header(String kind)
	{
		JsonObject o = new JsonObject();
		o.addProperty("v", PROTOCOL);
		o.addProperty("k", kind);
		return o;
	}

	/** {@code field} as a string, "" when missing or not a primitive. */
	static String string(JsonObject in, String field)
	{
		return string(in.get(field));
	}

	/** {@code field} is true; false when missing or not a primitive. */
	static boolean flag(JsonObject in, String field)
	{
		JsonElement e = in.get(field);
		return e != null && e.isJsonPrimitive() && e.getAsBoolean();
	}

	private static long longOr(JsonElement e, long fallback)
	{
		Long v = ItemCounts.longValue(e);
		return v == null ? fallback : v;
	}

	private static int clamp(long v, int lo, int hi)
	{
		return (int) Math.max(lo, Math.min(hi, v));
	}

	private static int digits(int n)
	{
		return Integer.toString(n).length();
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;

/**
 * One group event: a member's drop, collection log slot, pet, death, storage
 * visit, level, quest, login and so on. The one model every output reads: the
 * "since you last played" log (drops and collection log slots only), the
 * Discord webhook and the in-game overlays.
 *
 * <p>Fields per type: {@link #text} is the NPC, item, skill, quest or killer;
 * {@link #items} the items (a drop, a storage deposit); {@link #taken} only a
 * storage summary's withdrawals; {@link #number} the KC, level, XP, total,
 * QP, value, world or days, as {@link Type} says; {@link #detail} a short
 * extra line (Barrows set progress, a storage minimum).
 *
 * <p>{@link #at} is the sender's clock and is never adjusted on receipt: the
 * same event is resent whenever someone joins the party, and the time is what
 * lets {@link DropLog} recognise it.
 */
final class GroupEvent
{
	/** Which Discord webhook override an event goes to, and its embed colour. */
	enum Category
	{
		DROPS(0xF1C40F), DEATHS(0xC0392B), STORAGE(0xB8860B), PROGRESS(0x2ECC71), GROUP(0x3498DB),
		ACTIVITIES(0x9B59B6);

		final int colour;

		Category(int colour)
		{
			this.colour = colour;
		}
	}

	/** What an event must carry to be worth showing. */
	enum Need
	{
		ITEMS, TEXT, NOTHING
	}

	/**
	 * The kinds. {@code code} is the wire and cache tag: {@code d} and {@code c}
	 * are the 1.0.0 ones, and a 1.0.0 build skips any code it does not know.
	 * Every newer code has two letters, so none is a one-letter code a test or
	 * an older build treats as unknown.
	 * Storage kinds have no code that is ever sent: every receiver derives them
	 * from the storage change it already gets.
	 */
	enum Type
	{
		DROP("d", Category.DROPS, Need.ITEMS, false),
		CLOG("c", Category.DROPS, Need.TEXT, false),
		PET("pt", Category.DROPS, Need.NOTHING, true),
		UNIQUE("un", Category.DROPS, Need.ITEMS, false),
		DEATH("dt", Category.DEATHS, Need.NOTHING, false),
		STORAGE_DEPOSIT("sd", Category.STORAGE, Need.ITEMS, false),
		STORAGE_WITHDRAWAL("sw", Category.STORAGE, Need.ITEMS, false),
		STORAGE_SUMMARY("ss", Category.STORAGE, Need.NOTHING, false),
		STORAGE_MINIMUM("sm", Category.STORAGE, Need.TEXT, false),
		STORAGE_LAST("sl", Category.STORAGE, Need.ITEMS, false),
		LEVEL_UP("lv", Category.PROGRESS, Need.TEXT, false),
		MAXED("mx", Category.PROGRESS, Need.TEXT, true),
		XP_MILESTONE("xp", Category.PROGRESS, Need.TEXT, false),
		COMBAT_LEVEL("cb", Category.PROGRESS, Need.NOTHING, false),
		TOTAL_LEVEL("tl", Category.PROGRESS, Need.NOTHING, false),
		QUEST("qc", Category.PROGRESS, Need.TEXT, false),
		QUEST_POINTS("qp", Category.PROGRESS, Need.NOTHING, false),
		ONLINE("on", Category.GROUP, Need.TEXT, false),
		BACK("bk", Category.GROUP, Need.NOTHING, false),
		BARROWS("br", Category.ACTIVITIES, Need.ITEMS, false),
		RAID_UNIQUE("ru", Category.DROPS, Need.TEXT, true),
		CLUE("cl", Category.ACTIVITIES, Need.TEXT, false),
		DRY_STREAK("dr", Category.DROPS, Need.TEXT, false),
		DEATH_VALUE("dv", Category.DEATHS, Need.NOTHING, false),
		GRAVESTONE_EXPIRING("ge", Category.DEATHS, Need.NOTHING, false),
		HC_LIFE_LOST("hl", Category.DEATHS, Need.NOTHING, true),
		WILDERNESS("wl", Category.GROUP, Need.TEXT, false),
		DIARY("di", Category.PROGRESS, Need.TEXT, false),
		COMBAT_TASK("ca", Category.PROGRESS, Need.TEXT, false),
		KC_MILESTONE("km", Category.ACTIVITIES, Need.TEXT, false),
		PERSONAL_BEST("pb", Category.ACTIVITIES, Need.TEXT, false),
		WEEKLY_RECAP("wr", Category.GROUP, Need.TEXT, false),
		SLAYER("sy", Category.ACTIVITIES, Need.TEXT, false),
		FARMING("fr", Category.ACTIVITIES, Need.TEXT, false),
		BIRDHOUSE("bh", Category.ACTIVITIES, Need.TEXT, false),
		/** A Shopping tab request made, claimed or done: {@link RequestBoard}. */
		REQUEST("rq", Category.GROUP, Need.TEXT, false),
		/**
		 * A wave activity run ({@link WaveTracker}): {@link #text} the activity, {@link #number} the wave (start,
		 * milestone, death) or the kill count (completion, 0 for an early Colosseum claim), {@link #detail} the rest.
		 */
		ACTIVITY_START("as", Category.ACTIVITIES, Need.TEXT, false),
		ACTIVITY_WAVE("aw", Category.ACTIVITIES, Need.TEXT, false),
		ACTIVITY_COMPLETE("ac", Category.ACTIVITIES, Need.TEXT, false),
		ACTIVITY_DEATH("ad", Category.DEATHS, Need.TEXT, false);

		private static final Map<String, Type> BY_CODE = new HashMap<>();

		static
		{
			for (Type t : values())
			{
				BY_CODE.put(t.code, t);
			}
		}

		final String code;
		final Category category;
		final Need need;
		/** Worth the configured Discord mention. */
		final boolean big;

		Type(String code, Category category, Need need, boolean big)
		{
			this.code = code;
			this.category = category;
			this.need = need;
			this.big = big;
		}

		/** Null for a code this build does not know. */
		static Type of(String code)
		{
			return BY_CODE.get(code);
		}

		/** Storage kinds are derived on every client from the storage change; they never travel. */
		boolean travels()
		{
			return category != Category.STORAGE;
		}

		/** The "since you last played" log keeps these two only, as 1.0.0 did. */
		boolean logged()
		{
			return this == DROP || this == CLOG;
		}
	}

	/** Longest NPC or item name kept. The longest real ones are under 40. */
	static final int MAX_TEXT = 64;
	/** Most distinct items kept from one drop. */
	static final int MAX_DROP_ITEMS = 40;
	/** {@link #number} of a death that cost a Hardcore Group Ironman group a life. */
	static final long LIFE_LOST = 1;

	final Type type;
	final long at;
	final String member;
	/** The NPC for a drop, the item name for a collection log slot; see the class javadoc for the rest. */
	final String text;
	/** Item id to quantity; empty when the type has none. */
	final Map<Integer, Integer> items;
	/** A storage summary's withdrawals; empty for everything else. */
	final Map<Integer, Integer> taken;
	final long number;
	final String detail;
	/** The world the member was on, 0 when not known. */
	final int world;
	/** Where it happened, a region name; empty when not known. */
	final String location;
	/**
	 * A level-up's level before it, which one action can skip several of (low Prayer); 0 when not known, as for a
	 * member's event from the party. This client only: never sent, saved or compared.
	 */
	final long previous;
	/**
	 * Read from the game's own Group channel broadcast for a member without the plugin ({@link GroupBroadcasts}),
	 * not seen by their client. This client only: never sent, saved or compared.
	 */
	final boolean broadcast;

	private GroupEvent(Builder b)
	{
		this.type = b.type;
		this.at = b.at;
		this.member = b.member == null ? "" : b.member.trim();
		this.text = clip(b.text);
		this.items = capped(b.items);
		this.taken = capped(b.taken);
		this.number = b.number;
		this.detail = clip(b.detail);
		this.world = Math.max(0, b.world);
		this.location = clip(b.location);
		this.previous = Math.max(0, b.previous);
		this.broadcast = b.broadcast;
	}

	private static String clip(String text)
	{
		String t = text == null ? "" : text.trim();
		return t.length() > MAX_TEXT ? t.substring(0, MAX_TEXT) : t;
	}

	private static Map<Integer, Integer> capped(Map<Integer, Integer> items)
	{
		Map<Integer, Integer> kept = new TreeMap<>();
		if (items != null)
		{
			for (Map.Entry<Integer, Integer> e : items.entrySet())
			{
				if (kept.size() >= MAX_DROP_ITEMS)
				{
					break;
				}
				kept.put(e.getKey(), e.getValue());
			}
		}
		return Collections.unmodifiableMap(kept);
	}

	static Builder of(Type type, long at, String member)
	{
		return new Builder(type, at, member);
	}

	static GroupEvent drop(long at, String member, String npc, Map<Integer, Integer> items)
	{
		return of(Type.DROP, at, member).text(npc).items(items).build();
	}

	static GroupEvent clog(long at, String member, String item)
	{
		return of(Type.CLOG, at, member).text(item).build();
	}

	Builder toBuilder()
	{
		return of(type, at, member).text(text).items(items).taken(taken).number(number).detail(detail)
			.world(world).location(location).previous(previous).broadcast(broadcast);
	}

	GroupEvent withMember(String name)
	{
		return toBuilder().member(name).build();
	}

	/** Worth showing: a member, and what its type needs. */
	boolean isValid()
	{
		switch (type.need)
		{
			case ITEMS:
				// A drop names its NPC, as in 1.0.0, except a broadcast's (the game's line has none); storage kinds
				// have no text.
				return !items.isEmpty() && (type != Type.DROP || broadcast || !text.isEmpty());
			case TEXT:
				return !text.isEmpty();
			default:
				return true;
		}
	}

	/** Worth the Discord mention: a pet, a 99 or max total, a Hardcore group life lost. */
	boolean isBig()
	{
		return type.big || type == Type.DEATH && number == LIFE_LOST;
	}

	/** The same event seen twice, e.g. once live and once in a resend. */
	boolean sameAs(GroupEvent o)
	{
		return type == o.type && at == o.at && member.equalsIgnoreCase(o.member)
			&& text.toLowerCase(Locale.ROOT).equals(o.text.toLowerCase(Locale.ROOT)) && items.equals(o.items)
			&& number == o.number;
	}

	/** "Vorkath dropped 2 x Dragon bones" or "new collection log slot, Draconic visage". */
	String describe(ItemLookup lookup)
	{
		return EventText.describe(this, lookup);
	}

	static final class Builder
	{
		private final Type type;
		private final long at;
		private String member;
		private String text;
		private Map<Integer, Integer> items;
		private Map<Integer, Integer> taken;
		private long number;
		private String detail;
		private int world;
		private String location;
		private long previous;
		private boolean broadcast;

		private Builder(Type type, long at, String member)
		{
			this.type = type;
			this.at = at;
			this.member = member;
		}

		Builder member(String v)
		{
			member = v;
			return this;
		}

		Builder text(String v)
		{
			text = v;
			return this;
		}

		Builder items(Map<Integer, Integer> v)
		{
			items = v;
			return this;
		}

		Builder taken(Map<Integer, Integer> v)
		{
			taken = v;
			return this;
		}

		Builder number(long v)
		{
			number = v;
			return this;
		}

		Builder detail(String v)
		{
			detail = v;
			return this;
		}

		Builder world(int v)
		{
			world = v;
			return this;
		}

		Builder location(String v)
		{
			location = v;
			return this;
		}

		Builder previous(long v)
		{
			previous = v;
			return this;
		}

		Builder broadcast(boolean v)
		{
			broadcast = v;
			return this;
		}

		GroupEvent build()
		{
			return new GroupEvent(this);
		}
	}
}

