/**
 * GIM Utilities.
 *
 * <p>Opt-in group sharing over RuneLite Party: member banks, the group storage
 * log, live stats with boosts and where each member is, inventories and
 * equipment, rune pouch, quiver and seed vault, drops and collection log
 * slots, "who has it?" and {@code ::find}, storage minimums and world map
 * markers. The features live in {@link GroupService}, which this plugin
 * registers on the event bus; this class owns the side panel and its button.
 *
 * <p>Party traffic goes only through RuneLite's own {@code PartyService}. The
 * plugin's only network call of its own is the optional Discord webhook the
 * player sets ({@link GroupEventEngine}); it runs no server. It joins the
 * group's party by itself once there is a group key, so the Party plugin can
 * stay off. The key travels outside the game: "Copy group key" puts it on the
 * computer's clipboard for the player to send (e.g. in Discord) and "Paste
 * group key" saves one; the plugin never types into the game chatbox.
 */
@Slf4j
@PluginDescriptor(
	name = GroupIronmanPlugin.NAME,
	// The Plugin Hub name; getPluginDirectory() keeps the cache in .runelite/plugin-data/gim-utilities.
	internalName = "gim-utilities",
	// RuneLite moves the pre-Filepath cache folder (.runelite/gim-utilities) there on first use.
	legacyDataDirectory = GroupService.CACHE_DIR,
	description = "Share banks, group storage changes, stats and drops with your Group Ironman team over RuneLite Party",
	tags = {"group", "ironman", "gim", "party", "bank", "storage", "shared"}
)
public class GroupIronmanPlugin extends Plugin
{
	/** Shown in the plugin list and at the start of every chat line and notification this plugin writes. */
	static final String NAME = "GIM Utilities";

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private WSClient wsClient;

	@Inject
	private EventBus eventBus;

	@Inject
	private GroupIronmanConfig config;

	@Inject
	private GroupService group;

	@Inject
	private GroupEventEngine events;

	@Inject
	private MemberMapMarkers markers;

	@Inject
	private PartyDataService partyDataService;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private SpriteManager spriteManager;

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	/**
	 * The Shopping tab's open lists and items ({@link ShopFolds}), in the logged-in character's RuneLite profile:
	 * not a setting, never shown or sent. Frozen once published.
	 */
	static final String SHOPPING_OPEN_KEY = "shoppingOpen";

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private PluginManager pluginManager;

	/** Bank tiles for "Path to" an item in group storage; read once. */
	private final List<ItemPaths.Stop> banks = ItemPaths.loadBanks();
	/** The path handed to Shortest Path; null when not running. */
	private volatile PathSession paths;
	private GroupIronmanPanel panel;
	private NavigationButton navButton;
	private SidebarButton sidebar;

	@Provides
	GroupIronmanConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GroupIronmanConfig.class);
	}

	@Override
	protected void startUp()
	{
		wsClient.registerMessage(VvgGroupIronmanMessage.class);
		// Member names only travel when some plugin asks for them (PartyDataService sends
		// CHARACTER_NAME only while subscribed). Without the Party plugin, that is us.
		partyDataService.subscribe(this, PartyDataType.CHARACTER_NAME);
		eventBus.register(group);
		// Shortest Path is reached only through RuneLite's own PluginMessage: no reflection, no dependency.
		paths = new PathSession(new ShortestPathBridge(pluginManager::getPlugins,
			p -> p instanceof Plugin && pluginManager.isPluginEnabled((Plugin) p),
			ShortestPathBridge.clientThreadEventPoster(clientThread::invoke, eventBus::post)));
		panel = new GroupIronmanPanel(itemManager, skillIconManager, spriteManager, new GroupIronmanPanel.Actions()
		{
			@Override
			public void join()
			{
				clientThread.invokeLater(group::joinGroup);
			}

			@Override
			public void switchParty()
			{
				clientThread.invokeLater(group::switchToGroup);
			}

			@Override
			public void leave()
			{
				clientThread.invokeLater(group::leaveGroup);
			}

			@Override
			public void newKey()
			{
				group.newKey();
			}

			@Override
			public String groupKey()
			{
				return group.groupKey();
			}

			@Override
			public boolean pasteKey(String text)
			{
				// Pasting is the player's own click, so it joins once, right away.
				boolean saved = group.pasteKey(text);
				if (saved)
				{
					clientThread.invokeLater(group::joinGroup);
				}
				return saved;
			}

			@Override
			public void openSettings()
			{
				openOwnSettings();
			}

			@Override
			public void turnOnSharing()
			{
				group.turnOnSharing();
				// The player's own click, as Paste is: joins once, right away, now that sync is on.
				clientThread.invokeLater(group::joinGroup);
			}

			@Override
			public void postToDiscord()
			{
				group.postToDiscord();
			}

			@Override
			public boolean claim()
			{
				return group.claimLeadership();
			}

			@Override
			public boolean setEditor(String name, boolean editor)
			{
				return group.setEditor(name, editor);
			}

			@Override
			public GovernanceSync.SaveResult save(Map<String, Long> values)
			{
				return group.saveGroupSettings(values);
			}

			@Override
			public boolean shareWebhooks(boolean share)
			{
				return group.shareWebhooks(share);
			}

			@Override
			public void forgetLeader()
			{
				group.forgetLeader();
			}

			@Override
			public void optOut(GroupEvent.Type type, boolean overlay, boolean out)
			{
				group.optOut(type, overlay, out);
			}

			@Override
			public void optOutAll(boolean out)
			{
				group.optOutAll(out);
			}

			@Override
			public boolean addList(String name, String preset, List<String> picks, List<String> members,
				Map<Integer, Integer> items)
			{
				return group.addShoppingList(name, preset, picks, members, items);
			}

			@Override
			public boolean renameList(String id, String name)
			{
				return group.renameShoppingList(id, name);
			}

			@Override
			public boolean removeList(String id)
			{
				return group.removeShoppingList(id);
			}

			@Override
			public void searchItems(String query, Consumer<List<ShoppingTab.Hit>> done)
			{
				group.searchItems(query, done);
			}

			@Override
			public boolean addRequest(String name, Map<Integer, Integer> items)
			{
				return group.addRequest(name, items);
			}

			@Override
			public boolean renameRequest(String id, String name)
			{
				return group.renameRequest(id, name);
			}

			@Override
			public boolean removeRequest(String id)
			{
				return group.removeRequest(id);
			}

			@Override
			public boolean closeRequest(String id)
			{
				return group.closeRequest(id);
			}

			@Override
			public boolean closeRequestItem(String id, int itemId)
			{
				return group.closeRequestItem(id, itemId);
			}

			@Override
			public boolean claimRequest(String id, int itemId, boolean claimed)
			{
				return group.claimRequest(id, itemId, claimed);
			}

			@Override
			public String openLists()
			{
				return configManager.getRSProfileConfiguration(GroupIronmanConfig.GROUP, SHOPPING_OPEN_KEY);
			}

			@Override
			public void saveOpenLists(String keys)
			{
				if (keys == null)
				{
					configManager.unsetRSProfileConfiguration(GroupIronmanConfig.GROUP, SHOPPING_OPEN_KEY);
				}
				else
				{
					configManager.setRSProfileConfiguration(GroupIronmanConfig.GROUP, SHOPPING_OPEN_KEY, keys);
				}
			}

			@Override
			public String pathTo(ItemPaths.Target why, ItemPaths.Stop to)
			{
				PathSession s = paths;
				String said = s == null ? "" : s.go(why, to, group.here() != null);
				redraw();
				return said;
			}

			@Override
			public String clearPath()
			{
				PathSession s = paths;
				String said = s == null ? "" : s.stop();
				redraw();
				return said;
			}
		});
		navButton = NavigationButton.builder()
			.tooltip(NAME)
			.icon(icon())
			.priority(9)
			.panel(panel)
			.build();
		final NavigationButton button = navButton;
		sidebar = new SidebarButton(() -> clientToolbar.addNavigation(button),
			() -> clientToolbar.removeNavigation(button));
		group.startUp(this::redraw, this::getPluginDirectory);
		events.startUp(group);
		eventBus.register(events);
		sidebar.startUp();
		redraw();

		// Installed or turned on mid-session: no LOGGED_IN is coming, so say it now.
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invoke(this::postUpdateNotes);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			postUpdateNotes();
		}
	}

	/**
	 * Posts the welcome or "what's new" lines once per version (UpdateNotes), and
	 * stores the version as seen even with the setting off, so turning it on later
	 * does not bring back notes for an update long past. Client thread.
	 */
	private void postUpdateNotes()
	{
		final String lastSeen = config.lastSeenVersion();
		if (!UpdateNotes.needsRecord(lastSeen))
		{
			return;
		}
		configManager.setConfiguration(GroupIronmanConfig.GROUP, GroupIronmanConfig.KEY_LAST_SEEN_VERSION,
			UpdateNotes.VERSION);
		final List<String> lines = UpdateNotes.toShow(lastSeen, config.showUpdateNotes());
		for (int i = 0; i < lines.size(); i++)
		{
			final String message = new ChatMessageBuilder()
				.append(i == 0 ? ChatColorType.HIGHLIGHT : ChatColorType.NORMAL)
				.append(lines.get(i))
				.build();
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(message)
				.build());
		}
	}

	@Override
	protected void shutDown()
	{
		// Turning the plugin off takes its path with it.
		PathSession s = paths;
		paths = null;
		if (s != null)
		{
			s.stop();
		}
		wsClient.unregisterMessage(VvgGroupIronmanMessage.class);
		eventBus.unregister(events);
		events.shutDown();
		eventBus.unregister(group);
		group.shutDown();
		partyDataService.unsubscribe(this, PartyDataType.values());
		markers.clear();
		sidebar.shutDown();
		sidebar = null;
		panel = null;
		navButton = null;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// The plugin's own once-per-version bookkeeping changes nothing the features read.
		if (!GroupIronmanConfig.GROUP.equals(event.getGroup())
			|| GroupIronmanConfig.KEY_LAST_SEEN_VERSION.equals(event.getKey())
			|| GroupIronmanConfig.KEY_BOUND_GROUP.equals(event.getKey()))
		{
			return;
		}
		group.reloadConfig();
		events.reloadConfig();
		// The sidebar button stays whatever the switches say; the panel shows the change.
		redraw();
	}

	@Subscribe
	public void onPartyChanged(PartyChanged event)
	{
		group.onPartyChanged();
		redraw();
	}

	/**
	 * Opens this plugin's page in RuneLite's settings. Posts the event an overlay's
	 * "Configure" menu entry posts; RuneLite's ConfigPlugin handles it
	 * ({@code onOverlayMenuClicked}) by opening the settings panel on the overlay's
	 * plugin. The overlay is a stand-in that is never added or drawn.
	 */
	private void openOwnSettings()
	{
		Overlay self = new Overlay(this)
		{
			@Override
			public Dimension render(Graphics2D graphics)
			{
				return null;
			}
		};
		eventBus.post(new OverlayMenuClicked(new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, "", NAME),
			self));
	}

	private void redraw()
	{
		GroupIronmanPanel p = panel;
		if (p == null)
		{
			return;
		}
		GroupIronmanPanel.View view = new GroupIronmanPanel.View(group.syncState(), group.roster(), group.members(),
			group.lookup, group.switches(), group.regions(), group.since(), group.self(),
			group.presence(), settingsView(), group.anyOn(), group.sharingSettings(), shoppingView());
		SwingUtilities.invokeLater(() -> p.render(view));
		updateMarkers();
	}

	/** The Shopping tab's view, or null before the lists have started. */
	private ShoppingTab.View shoppingView()
	{
		ShoppingSync shop = group.shopping();
		if (shop == null)
		{
			return null;
		}
		List<ShoppingList> lists = shop.active();
		List<String> roster = new ArrayList<>(group.members().names());
		if (roster.isEmpty() && !group.self().isEmpty())
		{
			roster.add(group.self());
		}
		ShoppingBoard.Inputs in = group.shoppingInputs();
		List<ShoppingBoard.Card> cards = ShoppingBoard.of(lists, in);
		List<RequestBoard.Card> requests = group.requestCards();
		ItemPaths.Planner planner = ItemPaths.Planner.of(in, banks, group.here());
		// The path goes when its item is done, its list removed or its request closed.
		PathSession s = paths;
		if (s != null)
		{
			s.recheck(t -> ItemPaths.forTarget(t, cards, requests, planner));
		}
		return new ShoppingTab.View(cards, group.presets().presets(), roster, shop.history(),
			!group.self().isEmpty(), group.syncing(), requests, group.self(), planner,
			s == null ? "" : s.active());
	}

	/** The Settings tab's view, or null before group settings have started. */
	private GroupSettingsTab.View settingsView()
	{
		GroupGovernance g = group.governance();
		if (g == null)
		{
			return null;
		}
		String self = group.self();
		GroupSettingsSchema.Resolved values = group.groupValues();
		Map<String, Long> current = new TreeMap<>();
		for (GroupSettingsSchema.Setting s : GroupSettingsSchema.ALL)
		{
			current.put(s.key, values.value(s.key));
		}
		return GroupSettingsTab.View.of(g, self, group.members().names(), current, MemberPrefs.of(config),
			group.syncing());
	}

	/** Markers only add points to the world map; they never open it (that stays the player's click). */
	private void updateMarkers()
	{
		if (config.groupWorldMap() && config.groupShareStats() && group.syncing())
		{
			markers.update(group.roster().onlineStats(System.currentTimeMillis()), group.self());
		}
		else
		{
			markers.clear();
		}
	}

	/** A plain 16x16 three-figure badge, drawn rather than shipped: icon.png is still the scaffold's placeholder. */
	private static BufferedImage icon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setColor(new Color(0x2E, 0x6B, 0x3A));
		g.fillRoundRect(1, 1, 14, 14, 5, 5);
		g.setColor(new Color(0xE8, 0xE0, 0xC8));
		g.fillOval(2, 5, 4, 4);
		g.fillOval(6, 3, 4, 4);
		g.fillOval(10, 5, 4, 4);
		g.fillRect(2, 10, 12, 3);
		g.dispose();
		return image;
	}
}

package com.vinnyvangogh.groupironman;

import java.security.SecureRandom;
import java.util.Locale;
import java.util.Random;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;

/**
 * The group key: 128 random bits as 32 hex characters, generated once by the
 * first member to set up sync and shared with the others in group chat.
 *
 * <p>It is the only secret in the party passphrase. Everything else a group
 * has (its name, member names, join dates) is on the hiscores, so a passphrase
 * built only from those could be rebuilt by anyone. Party data is relayed to
 * everyone in the party, so this key is what keeps it inside the group.
 *
 * <p>Never logged and never sent anywhere except as part of the passphrase
 * handed to RuneLite's {@code PartyService}, and in the share line the player
 * sends to their own group chat themselves.
 */
final class GroupKey
{
	static final int HEX_LENGTH = 32;
	/** The tag a share line starts with, e.g. {@code [GIMU] 0123...}. */
	static final String TAG = "[GIMU]";

	private static final Pattern KEY = Pattern.compile("[0-9a-f]{" + HEX_LENGTH + "}");
	private static final Pattern SHARE_LINE = Pattern.compile("^\\s*\\[GIMU]\\s*([0-9a-fA-F]{" + HEX_LENGTH + "})\\s*$");
	private static final char[] HEX = "0123456789abcdef".toCharArray();

	private GroupKey()
	{
	}

	/** A new key from a {@link SecureRandom}. */
	static String generate()
	{
		return generate(new SecureRandom());
	}

	static String generate(Random random)
	{
		byte[] bytes = new byte[HEX_LENGTH / 2];
		random.nextBytes(bytes);
		StringBuilder out = new StringBuilder(HEX_LENGTH);
		for (byte b : bytes)
		{
			out.append(HEX[(b >> 4) & 0xF]).append(HEX[b & 0xF]);
		}
		return out.toString();
	}

	/** The key as stored: trimmed and lower-case, or "" when {@code text} is not a key. */
	static String normalize(String text)
	{
		if (text == null)
		{
			return "";
		}
		String key = text.trim().toLowerCase(Locale.ROOT);
		return KEY.matcher(key).matches() ? key : "";
	}

	static boolean isValid(String text)
	{
		return !normalize(text).isEmpty();
	}

	/** What the player pastes into group chat. */
	static String shareLine(String key)
	{
		return TAG + " " + normalize(key);
	}

	/**
	 * The key in what a member pasted: the bare key (as Copy group key gives it) or a
	 * share line, with surrounding spaces. "" when it is neither.
	 */
	static String fromPasted(String text)
	{
		String key = normalize(text);
		return key.isEmpty() ? parseShareLine(text) : key;
	}

	/** The key in a share line, or "" when {@code message} is not exactly one. */
	static String parseShareLine(String message)
	{
		if (message == null)
		{
			return "";
		}
		Matcher m = SHARE_LINE.matcher(message);
		return m.matches() ? m.group(1).toLowerCase(Locale.ROOT) : "";
	}

	/** True when {@code message} looks like a share line, valid or not. */
	static boolean looksLikeShareLine(String message)
	{
		return message != null && message.trim().startsWith(TAG);
	}

	/**
	 * The key in a chat line, read from group chat only: every member of a
	 * Group Ironman group is in it and nobody else is. "" for any other channel.
	 */
	static String keyFrom(ChatMessageType type, String message)
	{
		return type == ChatMessageType.CLAN_GIM_CHAT ? parseShareLine(message) : "";
	}

	/** Whether to drop a chat line from this player's chatbox: share lines in group chat, ours and others'. */
	static boolean hide(ChatMessageType type, String message)
	{
		return type == ChatMessageType.CLAN_GIM_CHAT && looksLikeShareLine(message);
	}

	/**
	 * The RuneLite party passphrase for {@code group} and {@code key}, or null
	 * without a valid key. The group name only keeps two groups that somehow
	 * share a key apart; the key is the secret.
	 */
	static String passphrase(String group, String key)
	{
		String k = normalize(key);
		if (k.isEmpty())
		{
			return null;
		}
		String g = group == null ? "" : group.trim().toLowerCase(Locale.ROOT).replace(' ', ' ');
		return "gimu:" + g + ":" + k;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Set;
import java.util.TreeSet;

/**
 * The in-game group roster, the allow-list for party data.
 *
 * <p>Read from the game's own Group Ironman clan:
 * {@code client.getClanSettings(ClanID.GROUP_IRONMAN).getMembers()}, falling
 * back to {@code client.getClanChannel(ClanID.GROUP_IRONMAN)} when settings
 * are not loaded. No hiscores or Wise Old Man calls for the roster: the roster
 * the game shows is authoritative and needs no network. (Hiscores only add
 * levels for members already on it: {@link HiscoreBook}.)
 *
 * <p>A party member whose name is not on it is ignored and listed as "Not in
 * your group", so a stranger who somehow has the passphrase sees nothing they
 * did not already have and gets nothing shown.
 */
final class GroupMembers
{
	private final String group;
	private final Set<String> names;
	private final Set<String> display;

	private GroupMembers(String group, Set<String> names, Set<String> display)
	{
		this.group = group;
		this.names = names;
		this.display = display;
	}

	static final GroupMembers UNKNOWN = new GroupMembers("", Collections.emptySet(), Collections.emptySet());

	/** {@code group} is the group's name; {@code members} as the game lists them. */
	static GroupMembers of(String group, Collection<String> members)
	{
		Set<String> names = new LinkedHashSet<>();
		Set<String> display = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
		if (members != null)
		{
			for (String m : members)
			{
				String key = key(m);
				if (!key.isEmpty())
				{
					names.add(key);
					display.add(clean(m));
				}
			}
		}
		return new GroupMembers(group == null ? "" : clean(group), Collections.unmodifiableSet(names),
			Collections.unmodifiableSet(display));
	}

	/** The group's name, "" when not known. */
	String group()
	{
		return group;
	}

	boolean known()
	{
		return !names.isEmpty();
	}

	/** What to do with party data from a member called {@code name}. */
	enum Verdict
	{
		ACCEPT,
		/** Not on a known roster: drop it and list them as "Not in your group". */
		STRANGER,
		/** The roster has not arrived yet: drop it quietly; members resend once it has. */
		WAIT
	}

	Verdict check(String name)
	{
		if (!known())
		{
			return Verdict.WAIT;
		}
		return allows(name) ? Verdict.ACCEPT : Verdict.STRANGER;
	}

	/** True when {@code name} is on the roster. An unknown roster allows nobody. */
	boolean allows(String name)
	{
		return names.contains(key(name));
	}

	/** The roster's names, sorted, as the game spells them. */
	Set<String> names()
	{
		return display;
	}

	/** Jagex names compare case-insensitively, and a space may arrive as a no-break space, '_' or '-'. */
	static String key(String name)
	{
		return clean(name).replace('_', ' ').replace('-', ' ').toLowerCase(Locale.ROOT);
	}

	/** A name as the game spells it, without chat icon tags. */
	static String display(String name)
	{
		return clean(name);
	}

	private static String clean(String name)
	{
		if (name == null)
		{
			return "";
		}
		return name.replaceAll("<[^>]*>", "").replace(' ', ' ').trim();
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * Decides which group payloads this client is willing to send, and is the
 * only place that decides it.
 *
 * <p>Each feature has its own switch and each is off by default. A switch that
 * is off means nothing of that kind leaves this client: not an empty payload,
 * no message at all.
 */
final class GroupOutbox
{
	static final class Switches
	{
		final boolean bank;
		final boolean storage;
		final boolean stats;
		final boolean carried;
		final boolean extras;
		final boolean drops;

		/** The part 2 switches, with the part 3 ones off. */
		Switches(boolean bank, boolean storage, boolean stats, boolean carried)
		{
			this(bank, storage, stats, carried, false, false);
		}

		Switches(boolean bank, boolean storage, boolean stats, boolean carried, boolean extras, boolean drops)
		{
			this.bank = bank;
			this.storage = storage;
			this.stats = stats;
			this.carried = carried;
			this.extras = extras;
			this.drops = drops;
		}

		boolean any()
		{
			return bank || storage || stats || carried || extras || drops;
		}
	}

	private GroupOutbox()
	{
	}

	static List<String> bank(Gson gson, Switches switches, BankSnapshot bank)
	{
		if (!switches.bank || bank == null)
		{
			return Collections.emptyList();
		}
		return GroupCodec.encodeBank(gson, bank);
	}

	/** Null when storage sharing is off or the visit changed nothing. */
	static String storage(Gson gson, Switches switches, StorageChange change)
	{
		if (!switches.storage || change == null || change.isEmpty())
		{
			return null;
		}
		return GroupCodec.encodeStorage(gson, change);
	}

	/**
	 * This player's own storage visit: always kept in {@code roster}'s log, so
	 * the own Log and Storage tabs show it; marked not shared, and null
	 * returned so nothing is sent, while storage sharing is off (Board
	 * 2026-11-13: a withdrawal made before ticking the switch looked lost).
	 */
	static String ownStorage(Gson gson, Switches switches, StorageChange change, GroupRoster roster)
	{
		StorageChange kept = switches.storage ? change : change.notShared();
		roster.putStorage(kept);
		return storage(gson, switches, kept);
	}

	static String stats(Gson gson, Switches switches, MemberStats stats)
	{
		if (!switches.stats || stats == null)
		{
			return null;
		}
		return GroupCodec.encodeStats(gson, stats);
	}

	static String carried(Gson gson, Switches switches, GroupCodec.Carried carried)
	{
		if (!switches.carried)
		{
			return null;
		}
		return GroupCodec.encodeCarried(gson, carried);
	}

	static String extras(Gson gson, Switches switches, MemberExtras extras)
	{
		if (!switches.extras || extras == null)
		{
			return null;
		}
		return GroupCodec.encodeExtras(gson, extras);
	}

	/**
	 * Pets, deaths, levels, quests, logins and Barrows chests: empty unless
	 * "Share group events" is on. Drops and collection log slots never go
	 * this way; they keep their own switch, {@link #events}.
	 */
	static List<String> groupEvents(Gson gson, boolean share, List<GroupEvent> events)
	{
		if (!share || events == null)
		{
			return Collections.emptyList();
		}
		List<GroupEvent> kept = new ArrayList<>();
		for (GroupEvent e : events)
		{
			if (e.type.travels() && !e.type.logged())
			{
				kept.add(e);
			}
		}
		return GroupCodec.encodeEvents(gson, kept);
	}

	/**
	 * This player's live activity ({@code "k":"activity"}): null unless synced and "Share group events" is on.
	 * With sharing off, the one exception is {@code clearOwed}: a clear frame, carrying nothing but "not in an
	 * activity", so members stop showing a run this player stopped sharing mid-way.
	 */
	static String activity(Gson gson, boolean sync, boolean share, ActivityState state, boolean clearOwed)
	{
		if (!sync || state == null)
		{
			return null;
		}
		if (share)
		{
			return ActivityCodec.encode(gson, state);
		}
		return clearOwed ? ActivityCodec.encode(gson, new ActivityState.Builder("", state.at).build()) : null;
	}

	/** Empty when drop sharing is off or there is nothing to send. */
	static List<String> events(Gson gson, Switches switches, List<GroupEvent> events)
	{
		if (!switches.drops || events == null)
		{
			return Collections.emptyList();
		}
		return GroupCodec.encodeEvents(gson, events);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collections;
import java.util.Map;
import java.util.TreeMap;

/**
 * Who leads the group and who may edit its settings, signed by the leader.
 *
 * <p>The leader is whoever claimed the group first (by creating its key, or
 * with "Claim leadership" on a group that has none yet, Board 2026-11-10).
 * Every client pins the leader's public key the first time it accepts this
 * document, and from then on accepts only newer versions signed by that same
 * key: a member cannot sign themselves in.
 *
 * <p>Immutable. Each editor is held with the public key the leader saw in
 * their announce, so an editor's settings are checked against that key.
 */
final class GroupRoles
{
	/** Plenty for a group of five; caps what a document can make a client hold. */
	static final int MAX_EDITORS = 16;

	/** {@link GroupMembers#key} of the group name. */
	final String group;
	final long version;
	final long at;
	final String leader;
	final String leaderKey;
	/** Display name to public key, sorted so the signed text is stable. */
	final Map<String, String> editors;
	final String signature;

	GroupRoles(String group, long version, long at, String leader, String leaderKey, Map<String, String> editors,
		String signature)
	{
		this.group = group;
		this.version = version;
		this.at = at;
		this.leader = leader;
		this.leaderKey = leaderKey;
		this.editors = Collections.unmodifiableMap(new TreeMap<>(editors));
		this.signature = signature;
	}

	/** Version 1, with {@code leader} as leader and no editors. */
	static GroupRoles claim(String group, String leader, GroupSigner.Identity id, long now)
	{
		return signed(GroupMembers.key(group), 1, now, GroupMembers.display(leader), id, new TreeMap<>());
	}

	/** The next version with {@code name} an editor (or not), signed by the leader's {@code id}. */
	GroupRoles withEditor(String name, String key, boolean editor, GroupSigner.Identity id, long now)
	{
		Map<String, String> next = new TreeMap<>(editors);
		next.keySet().removeIf(n -> GroupMembers.key(n).equals(GroupMembers.key(name)));
		if (editor)
		{
			next.put(GroupMembers.display(name), key);
		}
		return signed(group, version + 1, Math.max(now, at), leader, id, next);
	}

	private static GroupRoles signed(String group, long version, long at, String leader, GroupSigner.Identity id,
		Map<String, String> editors)
	{
		GroupRoles unsigned = new GroupRoles(group, version, at, leader, id.publicKey(), editors, "");
		return new GroupRoles(group, version, at, leader, id.publicKey(), editors, id.sign(unsigned.canonical()));
	}

	String canonical()
	{
		StringBuilder eds = new StringBuilder();
		for (Map.Entry<String, String> e : editors.entrySet())
		{
			eds.append(GroupSigner.canonical(e.getKey(), e.getValue()));
		}
		return GroupSigner.canonical("gimu-roles", 1, group, version, at, leader, leaderKey, eds);
	}

	/** Signed by the key it names as the leader's, and well formed. */
	boolean verify()
	{
		return version >= 1 && !leader.isEmpty() && editors.size() <= MAX_EDITORS
			&& GroupSigner.verify(leaderKey, canonical(), signature);
	}

	boolean isLeader(String name)
	{
		return GroupMembers.key(leader).equals(GroupMembers.key(name));
	}

	/** The key {@code name} was made editor with, or null when not an editor. */
	String editorKey(String name)
	{
		String k = GroupMembers.key(name);
		for (Map.Entry<String, String> e : editors.entrySet())
		{
			if (GroupMembers.key(e.getKey()).equals(k))
			{
				return e.getValue();
			}
		}
		return null;
	}

	/** Whether {@code name}, signing with {@code key}, may change the group's settings. */
	boolean mayEdit(String name, String key)
	{
		if (key == null)
		{
			return false;
		}
		return isLeader(name) ? key.equals(leaderKey) : key.equals(editorKey(name));
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Everything the group panel shows beyond builds: each member's last bank,
 * what they carry, their live stats, and group storage.
 *
 * <p>Keyed by display name, not party member id. Ids are new every time a
 * member joins a party, and a bank seen yesterday should still be there
 * today: that is the point of "last seen".
 *
 * <p>Written from the party thread and read on the Swing thread, so every map
 * is concurrent and every read returns a copy.
 */
final class GroupRoster
{
	private static final class Storage
	{
		final long at;
		final String by;
		final Map<Integer, Integer> items;

		Storage(long at, String by, Map<Integer, Integer> items)
		{
			this.at = at;
			this.by = by;
			this.items = items;
		}
	}

	private final Map<String, BankSnapshot> banks = new ConcurrentHashMap<>();
	private final Map<String, GroupCodec.Carried> carried = new ConcurrentHashMap<>();
	private final Map<String, MemberStats> stats = new ConcurrentHashMap<>();
	private final Map<String, MemberExtras> extras = new ConcurrentHashMap<>();
	private final Map<String, Long> heard = new ConcurrentHashMap<>();
	private final Map<String, LastSeen> seen = new ConcurrentHashMap<>();
	private final Set<String> strangers = ConcurrentHashMap.newKeySet();
	private final StorageLog log = new StorageLog();
	private final DropLog events = new DropLog();
	/** Every event, for the Log tab: see {@link ActivityLog}. */
	private final DropLog feed = ActivityLog.newFeed();
	/** Hiscore levels for members who do not share stats. */
	private final HiscoreBook hiscores = new HiscoreBook();
	private volatile Storage storage;
	/** When this player was last seen logged in, by this client; 0 when never. */
	private volatile long lastPlayed;

	/** What each member is doing in an activity now ({@link ActivityState}), this player included. */
	private final Map<String, ActivityState> activities = new ConcurrentHashMap<>();
	/** A member's activity not heard of for this long is gone: their client sends one each minute while in it. */
	static final long ACTIVITY_STALE_MS = 5 * 60_000L;

	/** {@code member}'s activity now; {@link ActivityState#NONE} (or any inactive state) removes it. */
	void putActivity(String member, ActivityState state)
	{
		if (state == null || !state.active())
		{
			activities.remove(member);
		}
		else
		{
			activities.put(member, state);
		}
	}

	/**
	 * Activities still current at {@code now}: each heard of in the last {@link #ACTIVITY_STALE_MS}, by its own
	 * time or by when its member was last heard from. A client that crashed mid-run sends no clear, so it ages out.
	 */
	Map<String, ActivityState> activities(long now)
	{
		Map<String, ActivityState> out = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
		activities.forEach((member, s) ->
		{
			long last = Math.max(s.at, heard.getOrDefault(member, 0L));
			if (now - last <= ACTIVITY_STALE_MS)
			{
				out.put(member, s);
			}
		});
		return out;
	}

	/** Something arrived from {@code member} at {@code at}. Only ever moves forward. */
	void heard(String member, long at)
	{
		heard.merge(member, at, Math::max);
	}

	Map<String, Long> lastHeard()
	{
		return new TreeMap<>(heard);
	}

	/** {@code member} was seen online ({@link LastSeen#merge}: only ever moves forward). */
	void seen(String member, LastSeen sighting)
	{
		seen.merge(member, sighting, LastSeen::merge);
	}

	/** When each member was last seen online, by this client or from the cache. */
	Map<String, LastSeen> lastSeen()
	{
		return new TreeMap<>(seen);
	}

	void markPlayed(long at)
	{
		lastPlayed = Math.max(lastPlayed, at);
	}

	long lastPlayed()
	{
		return lastPlayed;
	}

	/**
	 * Keeps the seed vault already known when the new one is unknown: a member
	 * who restarted and has not opened the vault since still has the same seeds.
	 */
	void putExtras(String member, MemberExtras incoming)
	{
		extras.merge(member, incoming, (old, now) ->
			now.seedVaultAt < 0 && old.seedVaultAt >= 0 ? now.withSeedVault(old.seedVault, old.seedVaultAt) : now);
	}

	Map<String, MemberExtras> extras()
	{
		return new TreeMap<>(extras);
	}

	void clearExtras()
	{
		extras.clear();
	}

	DropLog events()
	{
		return events;
	}

	HiscoreBook hiscores()
	{
		return hiscores;
	}

	/** Every group event, yours and members', newest first: the Log tab. */
	DropLog feed()
	{
		return feed;
	}

	/** How many members other than {@code self} were heard from recently. */
	int othersOnline(String self, long now)
	{
		int n = 0;
		for (Map.Entry<String, Long> e : heard.entrySet())
		{
			if (!e.getKey().equalsIgnoreCase(self) && Presence.online(e.getValue(), now))
			{
				n++;
			}
		}
		return n;
	}

	/** Positions of members heard from recently, for the world map. */
	Map<String, MemberStats> onlineStats(long now)
	{
		Map<String, MemberStats> out = new TreeMap<>();
		for (Map.Entry<String, MemberStats> e : stats.entrySet())
		{
			Long at = heard.get(e.getKey());
			if (at != null && Presence.online(at, now))
			{
				out.put(e.getKey(), e.getValue());
			}
		}
		return out;
	}

	/** Keeps the newer of the two, so a stale resend cannot replace a fresher bank. */
	boolean putBank(String member, BankSnapshot bank)
	{
		BankSnapshot old = banks.get(member);
		if (old != null && old.takenAt() >= bank.takenAt())
		{
			return false;
		}
		banks.put(member, bank);
		return true;
	}

	void putCarried(String member, GroupCodec.Carried items)
	{
		carried.put(member, items);
	}

	void putStats(String member, MemberStats s)
	{
		stats.put(member, s);
	}

	/** Every member's last stats, online or not. */
	Map<String, MemberStats> allStats()
	{
		return new TreeMap<>(stats);
	}

	/** Every member's last inventory and worn items, online or not. */
	Map<String, GroupCodec.Carried> allCarried()
	{
		return new TreeMap<>(carried);
	}

	/** A party member not on the in-game group roster sent something; it was dropped. */
	void stranger(String name)
	{
		strangers.add(name);
	}

	Set<String> strangers()
	{
		return new TreeSet<>(strangers);
	}

	void clearStrangers()
	{
		strangers.clear();
	}

	/** Records a storage visit in the log and, when it is the newest seen, as the current storage. */
	boolean putStorage(StorageChange change)
	{
		Storage s = storage;
		if (s == null || change.at() >= s.at)
		{
			storage = new Storage(change.at(), change.member(), change.after());
		}
		return log.add(change);
	}

	void clearLive()
	{
		clearCarried();
		clearStats();
	}

	void clearCarried()
	{
		carried.clear();
	}

	void clearStats()
	{
		stats.clear();
	}

	void clearAll()
	{
		clearLive();
		strangers.clear();
		banks.clear();
		log.clear();
		storage = null;
		extras.clear();
		heard.clear();
		seen.clear();
		events.clear();
		feed.clear();
		hiscores.clear();
		lastPlayed = 0;
	}

	Map<String, BankSnapshot> banks()
	{
		return new TreeMap<>(banks);
	}

	StorageLog log()
	{
		return log;
	}

	/** Current group storage contents, empty when never seen. */
	Map<Integer, Integer> storageItems()
	{
		Storage s = storage;
		return s == null ? Collections.emptyMap() : s.items;
	}

	long storageAt()
	{
		Storage s = storage;
		return s == null ? -1 : s.at;
	}

	void restoreStorage(long at, String by, Map<Integer, Integer> items)
	{
		storage = new Storage(at, by, ItemCounts.sorted(items));
	}

	String storageBy()
	{
		Storage s = storage;
		return s == null ? "" : s.by;
	}

	boolean hasAnything()
	{
		return !banks.isEmpty() || !carried.isEmpty() || !stats.isEmpty() || storage != null || !extras.isEmpty()
			|| !events.entries().isEmpty() || !feed.entries().isEmpty();
	}

	/** Everything "who has it?" searches. */
	List<GroupSearch.Source> searchSources()
	{
		List<GroupSearch.Source> out = new ArrayList<>();
		for (Map.Entry<String, BankSnapshot> e : banks().entrySet())
		{
			out.add(new GroupSearch.Source(e.getKey(), "bank", e.getValue().items(), e.getValue().takenAt()));
		}
		for (Map.Entry<String, GroupCodec.Carried> e : new TreeMap<>(carried).entrySet())
		{
			out.add(new GroupSearch.Source(e.getKey(), "inventory", e.getValue().inventory, -1));
			// Reads "GroupShip equipped 1" in ::find and the Find tab (Board 2026-11-04).
			out.add(new GroupSearch.Source(e.getKey(), "equipped", e.getValue().worn, -1));
			// "Yew logs: Alex log basket 14" (Board 2026-11-14), only where every item inside is known.
			for (Map.Entry<SkillingContainer, GroupCodec.Held> held : e.getValue().contents.entrySet())
			{
				out.add(new GroupSearch.Source(e.getKey(), held.getKey().label.toLowerCase(Locale.ROOT),
					held.getValue().items, -1));
			}
		}
		for (Map.Entry<String, MemberExtras> e : extras().entrySet())
		{
			out.add(new GroupSearch.Source(e.getKey(), "rune pouch", e.getValue().runePouch, -1));
			out.add(new GroupSearch.Source(e.getKey(), "quiver", e.getValue().quiver, -1));
			if (e.getValue().seedVaultAt >= 0)
			{
				out.add(new GroupSearch.Source(e.getKey(), "seed vault", e.getValue().seedVault,
					e.getValue().seedVaultAt));
			}
		}
		Storage s = storage;
		if (s != null)
		{
			out.add(new GroupSearch.Source("Group", "storage", s.items, s.at));
		}
		return out;
	}

	/** Every item id the panel may need a name for. */
	List<Integer> knownItemIds()
	{
		List<Integer> out = new ArrayList<>();
		for (GroupSearch.Source s : searchSources())
		{
			out.addAll(s.items.keySet());
		}
		for (StorageChange c : log.entries())
		{
			out.addAll(c.took().keySet());
			out.addAll(c.deposited().keySet());
		}
		for (GroupEvent e : events.entries())
		{
			out.addAll(e.items.keySet());
		}
		for (GroupEvent e : feed.entries())
		{
			out.addAll(e.items.keySet());
			out.addAll(e.taken.keySet());
		}
		return out;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * "Who has it?": an item name search across every member's last bank,
 * inventory and worn items, and group storage.
 */
final class GroupSearch
{
	static final int MIN_QUERY = 2;
	static final int MAX_RESULTS = 50;

	/** One place items can be: a member's bank, inventory or equipment, or group storage. */
	static final class Source
	{
		final String member;
		final String where;
		final Map<Integer, Integer> items;
		/** When the source was last seen, or -1 for "live". */
		final long seenAt;

		Source(String member, String where, Map<Integer, Integer> items, long seenAt)
		{
			this.member = member;
			this.where = where;
			this.items = items;
			this.seenAt = seenAt;
		}
	}

	/** One matching item in one place: "Grimy guam leaf 15 - Alex bank". */
	static final class Hit
	{
		final int itemId;
		final String name;
		final long quantity;
		final String member;
		final String where;
		/** As {@link Source#seenAt}. */
		final long seenAt;

		Hit(int itemId, String name, long quantity, String member, String where, long seenAt)
		{
			this.itemId = itemId;
			this.name = name;
			this.quantity = quantity;
			this.member = member;
			this.where = where;
			this.seenAt = seenAt;
		}
	}

	private GroupSearch()
	{
	}

	/**
	 * Every matching item in every source, sorted by item name and then in
	 * source order, at most {@link #MAX_RESULTS}. Items that share a name (a
	 * noted and an unnoted id) are added up per source. Fewer than
	 * {@link #MIN_QUERY} characters returns nothing rather than the whole
	 * group's holdings.
	 */
	static List<Hit> hits(String query, List<Source> sources, ItemLookup items)
	{
		List<Hit> out = new ArrayList<>();
		ItemQuery q = ItemQuery.parse(query);
		if (q == null)
		{
			return out;
		}
		Map<String, List<Hit>> byItem = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
		for (Source source : sources)
		{
			Map<String, long[]> byName = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
			for (Map.Entry<Integer, Integer> e : source.items.entrySet())
			{
				String name = items.name(e.getKey());
				if (q.matches(name))
				{
					// [id, quantity]: the first id seen stands for the icon.
					byName.computeIfAbsent(name, k -> new long[]{e.getKey(), 0})[1] += e.getValue();
				}
			}
			for (Map.Entry<String, long[]> e : byName.entrySet())
			{
				byItem.computeIfAbsent(e.getKey(), k -> new ArrayList<>()).add(new Hit((int) e.getValue()[0],
					e.getKey(), e.getValue()[1], source.member, source.where, source.seenAt));
			}
		}
		for (List<Hit> list : byItem.values())
		{
			for (Hit h : list)
			{
				if (out.size() >= MAX_RESULTS)
				{
					return out;
				}
				out.add(h);
			}
		}
		return out;
	}

	/**
	 * "Shark: Alex bank 120 (2h ago), Sam inventory 5", one line per matching
	 * item name, sorted by name: {@link #hits} as text for {@code ::find}.
	 */
	static List<String> search(String query, List<Source> sources, ItemLookup items, long now)
	{
		Map<String, List<String>> lines = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
		for (Hit h : hits(query, sources, items))
		{
			String when = h.seenAt < 0 ? "" : " (" + BoostText.ago(now, h.seenAt) + ")";
			lines.computeIfAbsent(h.name, k -> new ArrayList<>()).add(h.member + " " + h.where + " " + items.amount(h.quantity)
				+ when);
		}
		List<String> out = new ArrayList<>();
		for (Map.Entry<String, List<String>> e : lines.entrySet())
		{
			out.add(e.getKey() + ": " + String.join(", ", e.getValue()));
		}
		return out;
	}

	/**
	 * {@link #search} for the chatbox, worded and coloured by {@code style}:
	 * "Trout: 15 in your bank (just now), 140 in group storage (8m ago)".
	 */
	static List<String> searchStyled(String query, List<Source> sources, ItemLookup items, long now, FindStyle style)
	{
		Map<String, List<String>> lines = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
		for (Hit h : hits(query, sources, items))
		{
			String when = h.seenAt < 0 ? "" : " (" + BoostText.ago(now, h.seenAt) + ")";
			lines.computeIfAbsent(h.name, k -> new ArrayList<>()).add(style.place(h) + when);
		}
		List<String> out = new ArrayList<>();
		for (Map.Entry<String, List<String>> e : lines.entrySet())
		{
			out.add(FindStyle.paint(e.getKey(), style.item) + ": " + String.join(", ", e.getValue()));
		}
		return out;
	}

	/** {@link #history} for the chatbox: "You took 15 Trout from storage (8m ago)", in the storage colour. */
	static List<String> historyStyled(String query, List<StorageChange> log, ItemLookup items, long now, int limit,
		FindStyle style)
	{
		List<String> out = new ArrayList<>();
		ItemQuery q = ItemQuery.parse(query);
		if (q == null)
		{
			return out;
		}
		for (StorageChange c : log)
		{
			if (out.size() >= limit)
			{
				break;
			}
			Map<Integer, Integer> took = matching(c.took(), q, items);
			Map<Integer, Integer> deposited = matching(c.deposited(), q, items);
			List<String> parts = new ArrayList<>();
			if (!took.isEmpty())
			{
				parts.add("took " + StorageLog.describe(took, items) + " from storage");
			}
			if (!deposited.isEmpty())
			{
				parts.add("deposited " + StorageLog.describe(deposited, items) + " into storage");
			}
			if (!parts.isEmpty())
			{
				String who = style.isYou(c.member()) ? "You" : c.member();
				out.add(FindStyle.paint(who + " " + String.join(", ", parts), style.storage)
					+ " (" + BoostText.ago(now, c.at()) + ")");
			}
		}
		return out;
	}

	/**
	 * The newest storage log visits that took or deposited a matching item,
	 * newest first, at most {@code limit}: "Alex took 1 x Dragon hunter wand
	 * from storage (3d ago)". {@code log} is {@link StorageLog#entries()},
	 * already newest first.
	 */
	static List<String> history(String query, List<StorageChange> log, ItemLookup items, long now, int limit)
	{
		List<String> out = new ArrayList<>();
		ItemQuery q = ItemQuery.parse(query);
		if (q == null)
		{
			return out;
		}
		for (StorageChange c : log)
		{
			if (out.size() >= limit)
			{
				break;
			}
			Map<Integer, Integer> took = matching(c.took(), q, items);
			Map<Integer, Integer> deposited = matching(c.deposited(), q, items);
			List<String> parts = new ArrayList<>();
			if (!took.isEmpty())
			{
				parts.add("took " + StorageLog.describe(took, items) + " from storage");
			}
			if (!deposited.isEmpty())
			{
				parts.add("deposited " + StorageLog.describe(deposited, items) + " into storage");
			}
			if (!parts.isEmpty())
			{
				out.add(c.member() + " " + String.join(", ", parts) + " (" + BoostText.ago(now, c.at()) + ")");
			}
		}
		return out;
	}

	private static Map<Integer, Integer> matching(Map<Integer, Integer> counts, ItemQuery q, ItemLookup items)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		for (Map.Entry<Integer, Integer> e : counts.entrySet())
		{
			if (q.matches(items.name(e.getKey())))
			{
				out.put(e.getKey(), e.getValue());
			}
		}
		return out;
	}
}

