	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		statsDirty = true;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		ticksSinceStats++;
		ticksSinceCarried++;
		ticksSinceExtras++;
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			here = null;
			return;
		}
		here = position();
		long now = System.currentTimeMillis();
		refreshRoster();
		if (!member())
		{
			// Board 2026-11-15: an account not in the group gets nothing recorded, saved or sent.
			return;
		}
		watchStorageSave(now);
		if (!session)
		{
			session = true;
			extrasDirty = true;
			Player player = client.getLocalPlayer();
			if (player != null && player.getName() != null)
			{
				self = player.getName();
			}
			if (cacheLoaded)
			{
				// Before this tick's mark: the last time seen in the previous session.
				since = roster.lastPlayed();
			}
		}
		if (cacheLoaded)
		{
			roster.markPlayed(now);
		}
		recordSeen(now);
		pollQuests();
		shopAlert();
		sealRequests();
		carriedDirty |= containers.tick();
		GroupOutbox.Switches s = switches();
		updateCarried(s);
		if (!syncing())
		{
			return;
		}
		flushGovernance();

		if (s.stats)
		{
			pollStats(s);
		}

		if (s.extras && extrasDirty && ticksSinceExtras >= EXTRAS_INTERVAL_TICKS)
		{
			extrasDirty = false;
			sendExtras(s);
		}
	}

	/**
	 * Client thread. Re-reads the group roster from the game every few
	 * ticks. The first time it is known while syncing, asks members to resend:
	 * anything they sent before was dropped for want of a roster to check.
	 */
	private void refreshRoster()
	{
		if (++ticksSinceRoster < ROSTER_INTERVAL_TICKS)
		{
			return;
		}
		ticksSinceRoster = 0;
		GroupMembers now = readRoster();
		boolean first = !members.known() && now.known();
		boolean changed = !now.names().equals(members.names()) || !now.group().equals(members.group());
		members = now;
		boolean wasMember = member();
		checkMember(now);
		boolean isMember = member();
		changed |= wasMember != isMember;
		if (now.known() && isMember)
		{
			ifSet(governance, g -> g.group(now.group()));
		}
		// Anything members sent while this account was not one was dropped: ask again.
		if ((first || isMember && !wasMember) && syncing())
		{
			partyService.send(new UserSync());
		}
		if (changed)
		{
			onChange.run();
		}
		refreshPresence();
		if (isMember)
		{
			// Another group's roster is not looked up: its levels would land in this group's cache.
			hiscoresAfterRoster();
		}
	}

	/**
	 * Client thread, with each roster read: whether the account logged in is in this client's group
	 * ({@link GroupBinding}), binding the group on the first member's login. Says so once per login when it is not.
	 */
	private void checkMember(GroupMembers roster)
	{
		Player player = client.getLocalPlayer();
		String name = player == null || player.getName() == null ? "" : player.getName();
		String bound = getConfig(GroupIronmanConfig.KEY_BOUND_GROUP);
		boolean unbound = bound == null || bound.isEmpty();
		if (unbound && !cacheLoaded && !rebind)
		{
			// The members this client has heard from decide the first binding: not before the cache is read.
			memberName = "";
			return;
		}
		GroupBinding.Result r = rebind
			? GroupBinding.check(bound, roster, name, "", Collections.emptyList())
			: GroupBinding.check(bound, roster, name, savedRolesGroup(), heardNames());
		if (r.bind != null)
		{
			setConfig(GroupIronmanConfig.KEY_BOUND_GROUP, r.bind);
			rebind = false;
		}
		memberName = r.member() ? GroupMembers.key(name) : "";
		if (r.member())
		{
			rosterWaits = 0;
			return;
		}
		rosterWaits++;
		// A roster that is still loading waits quietly; one that never comes (no group) is said after ~30 s.
		boolean say = r.verdict == GroupBinding.Verdict.NOT_MEMBER || rosterWaits >= NOT_MEMBER_WAITS;
		if (say && !toldNotMember && !name.isEmpty())
		{
			toldNotMember = true;
			log.info("logged-in account is not in this client's group: nothing is posted, logged or shared for it");
			tell(name + (r.verdict == GroupBinding.Verdict.NOT_MEMBER
				? " isn't in the group this client is set up for" : " isn't on a Group Ironman group")
				+ ": nothing is posted to Discord, logged or shared for this account.");
		}
	}

	/** The group the saved signed roles are for ({@link GovernanceSync#KEY_ROLES}), "" when none are saved. */
	private String savedRolesGroup()
	{
		GovernanceCodec.Message m = GovernanceCodec.decode(gson, getConfig(GovernanceSync.KEY_ROLES));
		return m == null || m.roles == null || m.roles.group == null ? "" : m.roles.group;
	}

	/** Every member this client holds data for, from the group cache. */
	private Set<String> heardNames()
	{
		Set<String> out = new HashSet<>(roster.lastHeard().keySet());
		out.addAll(roster.allStats().keySet());
		return out;
	}

	/** Client thread. Once per login, every roster member, seen online or not; otherwise only failed lookups' retries. */
	private void hiscoresAfterRoster()
	{
		boolean login = hiscoresOnLogin && cacheLoaded && members.known();
		if (login)
		{
			hiscoresOnLogin = false;
		}
		lookUpHiscores(members.names(), login);
	}

	/**
	 * Client thread. Starts a hiscore lookup, on OkHttp's threads, for each of {@code names} that is not this
	 * player, shares no stats (shared data always wins) and is due ({@link HiscoreBook#begin}). {@code asked}:
	 * this player just logged in or these members just came online.
	 */
	private void lookUpHiscores(Collection<String> names, boolean asked)
	{
		if (!cacheLoaded || !anyOn() || names.isEmpty())
		{
			return;
		}
		Set<String> shared = new HashSet<>();
		roster.allStats().keySet().forEach(n -> shared.add(GroupMembers.key(n)));
		shared.add(GroupMembers.key(self));
		long now = System.currentTimeMillis();
		for (String name : names)
		{
			if (!shared.contains(GroupMembers.key(name)) && roster.hiscores().begin(name, now, asked))
			{
				hiscoreClient.lookupAsync(name, HiscoreEndpoint.NORMAL)
					.whenComplete((result, error) -> hiscoreDone(name, result, error));
			}
		}
	}

	/** OkHttp thread. A null result is a name not on the hiscores; it shows as unavailable, like an error. */
	private void hiscoreDone(String name, HiscoreResult result, Throwable error)
	{
		long now = System.currentTimeMillis();
		Map<String, Integer> levels = error == null ? HiscoreBook.levels(result) : Collections.emptyMap();
		if (levels.isEmpty())
		{
			log.debug("hiscore lookup for a group member failed", error);
			roster.hiscores().failed(name, now);
		}
		else
		{
			roster.hiscores().succeeded(name, levels, now);
			saveCache();
		}
		onChange.run();
	}

	/**
	 * Client thread: the Group channel changed, a member joined it or left it. RuneLite posts
	 * {@code ClanChannelChanged} (with {@code getClanId()}) when a channel loads or goes, and
	 * {@code ClanMemberJoined} / {@code ClanMemberLeft} (with {@code getClanChannel()}) as members log in and out.
	 */
	@Subscribe
	public void onClanChannelChanged(ClanChannelChanged event)
	{
		if (event.getClanId() == ClanID.GROUP_IRONMAN)
		{
			refreshPresence();
		}
	}

	@Subscribe
	public void onClanMemberJoined(ClanMemberJoined event)
	{
		groupChannelEvent(event.getClanChannel());
	}

	@Subscribe
	public void onClanMemberLeft(ClanMemberLeft event)
	{
		groupChannelEvent(event.getClanChannel());
	}

	private void groupChannelEvent(ClanChannel channel)
	{
		if (channel != null && channel == client.getClanChannel(ClanID.GROUP_IRONMAN))
		{
			refreshPresence();
		}
	}

	/**
	 * Client thread, each tick logged in: this player, and every member the game shows online (the Group channel,
	 * plugin or not), were seen now on their world. The live board's "last seen"; saved with the group cache.
	 */
	private void recordSeen(long now)
	{
		if (!self.isEmpty())
		{
			roster.seen(self, new LastSeen(now, client.getWorld(), true));
		}
		presence.online().forEach((name, world) -> roster.seen(name, new LastSeen(now, world, false)));
	}

	/** Who in the group is online and where, as the game shows it; {@link GamePresence#UNKNOWN} logged out. */
	GamePresence presence()
	{
		return presence;
	}

	/** Client thread. Re-reads {@link #presence} and, when it changed, tells the panel and the event engine. */
	private void refreshPresence()
	{
		// Another group's channel is not this group's: an account not in it shows, and posts, nobody online.
		GamePresence now = client.getGameState() == GameState.LOGGED_IN && member()
			? GamePresence.read(members, readChannel(), readFriends()) : GamePresence.UNKNOWN;
		if (now.equals(presence))
		{
			return;
		}
		GamePresence before = presence;
		presence = now;
		lookUpHiscores(GamePresence.cameOnline(members.names(), before, now), true);
		ifSet(events, e -> e.gamePresence(now));
		onChange.run();
	}

	/** Client thread. The Group channel's members and worlds, null before it loads. */
	private Map<String, Integer> readChannel()
	{
		ClanChannel channel = client.getClanChannel(ClanID.GROUP_IRONMAN);
		if (channel == null || channel.getMembers() == null)
		{
			return null;
		}
		Map<String, Integer> out = new HashMap<>();
		for (ClanChannelMember m : channel.getMembers())
		{
			out.put(m.getName(), m.getWorld());
		}
		return out;
	}

	/** Client thread. The Friends list's names and worlds (0 offline), null before it loads. */
	private Map<String, Integer> readFriends()
	{
		FriendContainer friends = client.getFriendContainer();
		if (friends == null || friends.getMembers() == null)
		{
			return null;
		}
		Map<String, Integer> out = new HashMap<>();
		for (Friend f : friends.getMembers())
		{
			if (f != null && f.getName() != null)
			{
				out.put(f.getName(), f.getWorld());
			}
		}
		return out;
	}

	/** Client thread. {@code ClanSettings} lists every member; the channel only those online, so it is the fallback. */
	private GroupMembers readRoster()
	{
		ClanSettings settings = client.getClanSettings(ClanID.GROUP_IRONMAN);
		if (settings != null && settings.getMembers() != null && !settings.getMembers().isEmpty())
		{
			List<String> names = new ArrayList<>();
			for (ClanMember m : settings.getMembers())
			{
				names.add(m.getName());
			}
			return GroupMembers.of(settings.getName(), names);
		}
		Map<String, Integer> online = readChannel();
		if (online != null)
		{
			return GroupMembers.of(client.getClanChannel(ClanID.GROUP_IRONMAN).getName(), online.keySet());
		}
		return GroupMembers.UNKNOWN;
	}

	/** Client thread. Run energy, special attack and location fire no StatChanged; poll the cheap ints. */
	private void pollStats(GroupOutbox.Switches s)
	{
		int run = client.getEnergy() / 100;
		int spec = client.getVarpValue(VarPlayerID.SA_ENERGY) / 10;
		int world = client.getWorld();
		WorldPoint at = position();
		int region = at == null ? 0 : at.getRegionID();
		int x = at == null ? 0 : at.getX();
		int y = at == null ? 0 : at.getY();
		int plane = at == null ? 0 : at.getPlane();
		if (run != lastRun || spec != lastSpec || world != lastWorld || region != lastRegion
			|| plane != lastPlane || Math.abs(x - lastX) + Math.abs(y - lastY) >= MOVE_TILES)
		{
			lastRun = run;
			lastSpec = spec;
			lastWorld = world;
			lastRegion = region;
			lastX = x;
			lastY = y;
			lastPlane = plane;
			statsDirty = true;
		}
		if (ticksSinceStats >= STATS_HEARTBEAT_TICKS)
		{
			// Nothing changed for a minute: send the same again so members still see us online.
			lastStatsSent = null;
			statsDirty = true;
		}
		if (statsDirty && ticksSinceStats >= STATS_INTERVAL_TICKS)
		{
			statsDirty = false;
			sendStats(s);
		}
	}

	/** Someone joined and asked for a resend. */
	@Subscribe
	public void onUserSync(UserSync event)
	{
		clientThread.invokeLater(() ->
		{
			resendLive();
			// Sent on the next tick: roles first, then the settings they authorise.
			resendShared();
			if (!syncing())
			{
				return;
			}
			if (lastBank != null)
			{
				GroupOutbox.bank(gson, switches(), lastBank).forEach(this::send);
			}
			// The joiner may have been offline for these: this is how "since you last played" works with no server.
			List<GroupEvent> mine = roster.events().recentBy(localName(), System.currentTimeMillis());
			GroupOutbox.events(gson, switches(), mine).forEach(this::send);
			if (lastActivity.active())
			{
				// A joiner mid-run sees it now, not at the next wave.
				shareActivity(lastActivity);
			}
		});
	}

	/** A member left: their stats and items stay as "last seen" for their offline card. */
	@Subscribe
	public void onUserPart(UserPart event)
	{
		assembler.forget(event.getMemberId());
		onChange.run();
	}

	void onPartyChanged()
	{
		resendShared();
		assembler.clear();
		roster.clearStrangers();
		resendLive();
		onChange.run();
	}

	/**
	 * Who sent {@code message}, or null when it must be dropped: our own
	 * echo, a party that is not this group's, a member with no name yet, or a
	 * name that is not on the in-game group roster.
	 */
	private String sender(VvgGroupIronmanMessage message)
	{
		PartyMember local = partyService.getLocalMember();
		if (!syncing() || local != null && local.getMemberId() == message.getMemberId())
		{
			return null;
		}
		PartyMember member = partyService.getMemberById(message.getMemberId());
		String name = member == null ? null : member.getDisplayName();
		if (name == null || name.trim().isEmpty() || !member.isLoggedIn())
		{
			// Banks and the log are kept by name across restarts; without a name there is nothing to file it under.
			log.debug("ignored group payload from unnamed member {}", message.getMemberId());
			return null;
		}
		GroupMembers.Verdict verdict = members.check(name);
		if (verdict == GroupMembers.Verdict.STRANGER)
		{
			roster.stranger(name);
			onChange.run();
		}
		return verdict == GroupMembers.Verdict.ACCEPT ? name : null;
	}

	@Subscribe
	public void onVvgGroupIronmanMessage(VvgGroupIronmanMessage message)
	{
		String name = sender(message);
		if (name == null)
		{
			return;
		}
		GroupCodec.Decoded decoded = GroupCodec.decode(gson, message.getPayload());
		if (decoded == null)
		{
			notData(name, message);
			return;
		}
		GroupOutbox.Switches s = switches();
		long now = System.currentTimeMillis();

		switch (decoded.kind)
		{
			case BANK:
				if (!s.bank)
				{
					return;
				}
				BankSnapshot bank = assembler.accept(message.getMemberId(), decoded.bank);
				if (bank != null && roster.putBank(name, new BankSnapshot(Math.min(bank.takenAt(), now), bank.items())))
				{
					resolve(bank.items().keySet());
					saveCache();
				}
				break;
			case CARRIED:
				if (!s.carried)
				{
					return;
				}
				roster.putCarried(name, decoded.carried);
				resolve(decoded.carried.ids());
				break;
			case STORAGE:
				if (!s.storage)
				{
					return;
				}
				StorageChange change = decoded.storage.withMember(name);
				change = new StorageChange(Math.min(change.at(), now), name, change.took(), change.deposited(),
					change.after());
				if (roster.putStorage(change))
				{
					resolve(ItemCounts.ids(change.after(), change.took(), change.deposited()));
					checkLowStock(change.after());
					memberStorage(change);
					saveCache();
				}
				break;
			case STATS:
				if (!s.stats)
				{
					return;
				}
				roster.putStats(name, decoded.stats);
				break;
			case EXTRAS:
				if (!s.extras)
				{
					return;
				}
				MemberExtras before = roster.extras().get(name);
				roster.putExtras(name, decoded.extras);
				resolve(ItemCounts.ids(decoded.extras.runePouch, decoded.extras.quiver, decoded.extras.seedVault));
				if (before == null || before.seedVaultAt != roster.extras().get(name).seedVaultAt)
				{
					// The pouch changes every cast; only a new seed vault is worth a disk write.
					saveCache();
				}
				break;
			case EVENTS:
				if (!receiveEvents(name, decoded.events, s))
				{
					return;
				}
				break;
			default:
				return;
		}
		// Anything accepted from a member means their client is running and in the party.
		roster.heard(name, now);
		onChange.run();
	}

	/**
	 * A payload {@link GroupCodec#decode} does not read: roles, group settings or an announce, a "posted" claim, or
	 * one from a newer build.
	 */
	private void notData(String name, VvgGroupIronmanMessage message)
	{
		GovernanceSync g = governance;
		String payload = message.getPayload();
		if (ActivityCodec.isActivity(payload))
		{
			receiveActivity(name, payload);
			return;
		}
		if (g != null && GovernanceSync.isGovernance(payload) && g.receive(name, payload))
		{
			roster.heard(name, System.currentTimeMillis());
			return;
		}
		ShoppingSync shop = shopping;
		if (shop != null && ShoppingSync.isShopping(payload) && shop.receive(name, payload))
		{
			roster.heard(name, System.currentTimeMillis());
			resolve(shoppingItemIds());
			return;
		}
		List<String> posted = GroupCodec.posted(gson, payload);
		if (posted != null)
		{
			receivePosted(posted);
			roster.heard(name, System.currentTimeMillis());
			return;
		}
		log.debug("ignored unreadable group payload from {}", message.getMemberId());
	}

	/** Game tick, connected: roles, settings and this member's announce, then shopping lists, whichever changed. */
	private void flushGovernance()
	{
		ifSet(governance, g -> g.flush(MemberPrefs.of(config)));
		ifSet(shopping, shop -> shop.flush(self));
	}

	/**
	 * A member's events. Drops and log slots go in the log under the drops
	 * switch, as in 1.0.0; the rest only under "Share group events". Each new
	 * one goes on to the engine for the overlays. False when this client
	 * takes none of them, so the member is not marked heard.
	 */
	private boolean receiveEvents(String name, List<GroupEvent> received, GroupOutbox.Switches s)
	{
		boolean share = config.groupShareEvents();
		if (!s.drops && !share)
		{
			return false;
		}
		boolean added = false;
		GroupEventEngine engine = events;
		for (GroupEvent e : received)
		{
			GroupEvent mine = e.withMember(name);
			boolean logged = e.type.logged();
			if (logged ? !s.drops || !roster.events().add(mine) : !share)
			{
				continue;
			}
			resolve(e.items.keySet());
			added |= logged;
			if (engine != null)
			{
				engine.member(mine);
			}
		}
		if (added)
		{
			saveCache();
		}
		return true;
	}

	/** A member's client posted these game broadcasts: this one never posts them too. */
	private void receivePosted(List<String> keys)
	{
		ifSet(events, e -> e.claimed(keys));
	}

	private void memberStorage(StorageChange change)
	{
		// Names resolve on the client thread; the value of a big move needs them.
		ifSet(events, e -> clientThread.invokeLater(() -> e.storage(change, false)));
	}

	/**
	 * Client thread. The game's "Saving..." loader (interface 293, child 1) is
	 * shown for every save, including one a close makes, so its first tick is
	 * a save; the same check the Group Ironmen Tracker plugin commits on.
	 */
	private void watchStorageSave(long now)
	{
		Widget loader = client.getWidget(InterfaceID.LOADING_ICON_MODAL, STORAGE_LOADER_TEXT);
		boolean saving = loader != null && !loader.isHidden()
			&& "Saving...".equalsIgnoreCase(Text.removeTags(loader.getText()));
		if (saving && !storageSaving)
		{
			commitStorage(storage.save(now, localName()));
		}
		storageSaving = saving;
	}

	/**
	 * Client thread. A save the game made, or the first contents of a visit
	 * differing from the last snapshot: the contents become the storage
	 * snapshot even when nothing moved, a change is logged locally whether or
	 * not sync is on, and only a change is sent.
	 */
	private void commitStorage(StorageChange change)
	{
		// Another group's storage is not this group's: not logged, not checked, not sent.
		if (change == null || !member())
		{
			return;
		}
		resolveNow(ItemCounts.ids(change.after(), change.took(), change.deposited()));

		// Minimums are checked on every own save, shared or not: the alert is for this player.
		checkLowStockNow(change.after(), true);
		ifSet(events, e -> e.storage(change, true));

		// Kept locally whether shared or not; with sharing off it is marked so and nothing is sent.
		String payload = GroupOutbox.ownStorage(gson, switches(), change, roster);
		if (payload != null && syncing())
		{
			send(payload);
		}
		saveCache();
		onChange.run();
	}

	/** Client thread. */
	private void closeBank()
	{
		GroupOutbox.Switches s = switches();
		if (!s.bank || !member())
		{
			return;
		}
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (bank == null)
		{
			return;
		}
		Map<Integer, Integer> items = counts(bank);
		BankSnapshot snapshot = new BankSnapshot(System.currentTimeMillis(), items);
		if (lastBank != null && lastBank.items().equals(snapshot.items()))
		{
			// Nothing moved since the last close; do not resend the whole bank.
			return;
		}
		lastBank = snapshot;
		resolveNow(items.keySet());
		roster.putBank(localName(), snapshot);
		if (syncing())
		{
			GroupOutbox.bank(gson, s, snapshot).forEach(this::send);
		}
		saveCache();
		onChange.run();
	}

	/** Client thread. */
	private void sendStats(GroupOutbox.Switches s)
	{
		Map<String, MemberStats.Level> skills = new LinkedHashMap<>();
		for (Skill skill : Skill.values())
		{
			if (skill == Skill.OVERALL)
			{
				continue;
			}
			skills.put(skill.getName(), new MemberStats.Level(client.getRealSkillLevel(skill),
				client.getBoostedSkillLevel(skill)));
		}
		MemberStats stats = new MemberStats(skills, lastRun, lastSpec, lastWorld, lastRegion, lastX, lastY, lastPlane);
		String payload = GroupOutbox.stats(gson, s, stats);
		if (payload == null || Objects.equals(payload, lastStatsSent))
		{
			return;
		}
		send(payload);
		lastStatsSent = payload;
		ticksSinceStats = 0;
		roster.putStats(localName(), stats);
		roster.heard(localName(), System.currentTimeMillis());
		onChange.run();
	}

	/** Client thread. */
	private void sendExtras(GroupOutbox.Switches s)
	{
		MemberExtras extras = new MemberExtras(runePouch(), quiver(), seedVault, seedVaultAt);
		String payload = GroupOutbox.extras(gson, s, extras);
		if (payload == null || Objects.equals(payload, lastExtrasSent))
		{
			return;
		}
		send(payload);
		lastExtrasSent = payload;
		ticksSinceExtras = 0;
		resolveNow(ItemCounts.ids(extras.runePouch, extras.quiver, extras.seedVault));
		roster.putExtras(localName(), extras);
		onChange.run();
	}

	/** Client thread. Rune type varbits index the RUNEPOUCH_RUNE enum, the way the base rune pouch plugin reads them. */
	private Map<Integer, Integer> runePouch()
	{
		Map<Integer, Integer> out = new TreeMap<>();
		EnumComposition runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runes == null)
		{
			return out;
		}
		for (int i = 0; i < POUCH_TYPES.length; i++)
		{
			int type = client.getVarbitValue(POUCH_TYPES[i]);
			int amount = client.getVarbitValue(POUCH_AMOUNTS[i]);
			if (type > 0 && amount > 0)
			{
				ItemCounts.add(out, runes.getIntValue(type), amount, itemManager::canonicalize);
			}
		}
		return out;
	}

	/** Client thread. Dizana's quiver's ammo: an item id and count in two varps, -1 or 0 when empty. */
	private Map<Integer, Integer> quiver()
	{
		Map<Integer, Integer> out = new TreeMap<>();
		ItemCounts.add(out, client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO),
			client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT), itemManager::canonicalize);
		return out;
	}

	/**
	 * Client thread. This player's own inventory, worn items and container contents onto their own card, joined
	 * or not (Board 2026-11-14: the card shows them while 'Not connected'); sent to the party only when syncing
	 * and shared.
	 */
	private void updateCarried(GroupOutbox.Switches s)
	{
		if (!carriedDirty || ticksSinceCarried < CARRIED_INTERVAL_TICKS)
		{
			return;
		}
		carriedDirty = false;
		ticksSinceCarried = 0;
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		GroupCodec.Carried carried = new GroupCodec.Carried(counts(inv),
			counts(client.getItemContainer(InventoryID.WORN)), inventorySlots(inv), containers.held());
		String local = GroupCodec.encodeCarried(gson, carried);
		if (!local.equals(lastCarriedLocal))
		{
			lastCarriedLocal = local;
			resolveNow(carried.ids());
			roster.putCarried(localName(), carried);
			onChange.run();
		}
		String payload = syncing() ? GroupOutbox.carried(gson, s, carried) : null;
		if (payload != null && !Objects.equals(payload, lastCarriedSent))
		{
			send(payload);
			lastCarriedSent = payload;
		}
	}

	/** Client thread. The inventory's slots in order with raw ids, so a noted stack draws noted; none without one. */
	private static List<GroupCodec.Slot> inventorySlots(ItemContainer container)
	{
		List<GroupCodec.Slot> out = new ArrayList<>();
		if (container == null)
		{
			return out;
		}
		for (Item item : container.getItems())
		{
			out.add(GroupCodec.Slot.of(item.getId(), item.getQuantity()));
		}
		// The game trims trailing empty slots; an inventory with nothing in it is still 28 empty slots.
		if (out.isEmpty())
		{
			out.add(GroupCodec.Slot.EMPTY);
		}
		return out;
	}

	/** Client thread. Counts by canonical id; bank fillers and placeholders are not items. */
	private Map<Integer, Integer> counts(ItemContainer container)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		if (container == null)
		{
			return out;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() == ItemID.BANK_FILLER)
			{
				continue;
			}
			ItemCounts.add(out, item.getId(), item.getQuantity(), itemManager::canonicalize);
		}
		return out;
	}

	/** Client thread. The real-world tile, also inside instances; null when not known. */
	private WorldPoint position()
	{
		Player player = client.getLocalPlayer();
		if (player == null || player.getLocalLocation() == null)
		{
			return null;
		}
		return WorldPoint.fromLocalInstance(client, player.getLocalLocation());
	}

	private String localName()
	{
		Player player = client.getLocalPlayer();
		if (player != null && player.getName() != null)
		{
			return player.getName();
		}
		PartyMember local = partyService.getLocalMember();
		return local != null && local.getDisplayName() != null ? local.getDisplayName() : "You";
	}

	private void checkLowStock(Map<Integer, Integer> storage)
	{
		if (lowStock.isEmpty())
		{
			return;
		}
		// Names only resolve on the client thread, and the check matches by name.
		clientThread.invokeLater(() -> checkLowStockNow(storage, false));
	}

	/** Client thread. {@code own}: this player's visit, the one whose client posts the event. */
	private void checkLowStockNow(Map<Integer, Integer> storage, boolean own)
	{
		if (lowStock.isEmpty())
		{
			return;
		}
		resolveNow(storage.keySet());
		GroupEventEngine engine = events;
		for (LowStock.Alert alert : lowStock.check(storage, lookup))
		{
			notifier.notify(GroupIronmanPlugin.NAME + ": " + alert.message());
			if (engine != null)
			{
				engine.minimum(alert, own);
			}
		}
	}

	/** Any thread: queues name and price lookups for ids not seen yet. */
	private void resolve(Collection<Integer> ids)
	{
		List<Integer> missing = new ArrayList<>();
		for (int id : ids)
		{
			// Names loaded from the disk cache come without a slot: look those up again too.
			if (!names.containsKey(id) || !slots.containsKey(id))
			{
				missing.add(id);
			}
		}
		if (!missing.isEmpty())
		{
			clientThread.invokeLater(() ->
			{
				resolveNow(missing);
				onChange.run();
			});
		}
	}

	/** Client thread. */
	private void resolveNow(Collection<Integer> ids)
	{
		for (int id : ids)
		{
			if (names.containsKey(id) && slots.containsKey(id))
			{
				continue;
			}
			ItemComposition item = itemManager.getItemComposition(id);
			String name = item == null ? null : item.getName();
			if (name != null && !name.isEmpty() && !"null".equalsIgnoreCase(name))
			{
				names.put(id, name);
				tradeable.put(id, item.isTradeable());
				prices.put(id, (long) itemManager.getItemPrice(id));
				ItemStats stats = itemManager.getItemStats(id);
				slots.put(id, stats == null || stats.getEquipment() == null ? -1 : stats.getEquipment().getSlot());
			}
		}
	}

	/** Executor thread. */
	private void loadCache()
	{
		try
		{
			if (!readCache())
			{
				return;
			}
		}
		finally
		{
			// Read before any tick marks this session as played.
			since = roster.lastPlayed();
			cacheLoaded = true;
		}
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				// Item definitions need a loaded cache; try again on a later tick.
				return false;
			}
			resolveNow(roster.knownItemIds());
			onChange.run();
			return true;
		});
	}

	/** Executor thread. False when there is no file or it cannot be read. */
	private boolean readCache()
	{
		try
		{
			String json = PluginFiles.read(cacheFile());
			if (json == null)
			{
				return false;
			}
			if (!GroupCache.read(gson, json, roster))
			{
				log.debug("group cache unreadable, starting empty");
				return false;
			}
			restoreWebhooks(GroupCache.webhooks(gson, json));
			ifSet(shopping, shop -> shop.fromCache(GroupCache.shop(gson, json), System.currentTimeMillis()));
			return true;
		}
		catch (Exception e)
		{
			log.debug("could not read group cache", e);
			return false;
		}
	}

	/** Executor thread. The cached webhooks document, checked like one from the party; a newer one held wins. */
	private void restoreWebhooks(String json)
	{
		GovernanceSync g = governance;
		if (json == null || g == null)
		{
			return;
		}
		if (cachedWebhooks == null)
		{
			// Kept as read until the governance accepts (or replaces) it, so a save before the roles load keeps it.
			cachedWebhooks = json;
		}
		g.restoreWebhooks(json);
	}

	private void saveCache()
	{
		if (!cacheLoaded)
		{
			// Whatever arrived meanwhile is in the roster and goes out with the first save after loading.
			return;
		}
		ShoppingSync shop = shopping;
		String json = GroupCache.write(gson, roster, cachedWebhooks, shop == null ? null : shop.toCache());
		executor.execute(() ->
		{
			try
			{
				PluginFiles.write(cacheFile(), json, "group-cache");
			}
			catch (Exception e)
			{
				log.debug("could not write group cache", e);
			}
		});
	}

	/** Executor thread. The cache inside the plugin's data directory (.runelite/plugin-data/gim-utilities). */
	private Filepath cacheFile() throws Exception
	{
		return dataFile(CACHE_FILE);
	}

	/** Executor thread. {@code name} inside the plugin's data directory. */
	Filepath dataFile(String name) throws Exception
	{
		return dataDirectory.call().joinSegment(name);
	}

	/** True once the group cache (roster, the leader's shared webhooks) has been read at startup. */
	boolean cacheLoaded()
	{
		return cacheLoaded;
	}

	// ---- The Shopping tab ----

	/** The shared lists, or null when not running. */
	ShoppingSync shopping()
	{
		return shopping;
	}

	ShopPresets presets()
	{
		return presets;
	}

	/** Where this player stood on the last game tick; null when logged out. Any thread. */
	WorldPoint here()
	{
		return here;
	}

	/** What a {@link ShoppingBoard} works from, as this client knows it now. Any thread. */
	ShoppingBoard.Inputs shoppingInputs()
	{
		ShoppingSync shop = shopping;
		QuestProgress mine = shop == null ? QuestProgress.UNKNOWN : shop.progress(self);
		return new ShoppingBoard.Inputs(questData, presets,
			member -> shop == null ? QuestProgress.UNKNOWN : shop.progress(member),
			ShopAllocation.Holdings.from(roster.searchSources()), id -> tradeable.getOrDefault(id, false),
			lookup::name, new ShopSources.Viewer(ownLevels, mine));
	}

	/** "Add list": false when not logged in, not started or the book is full. */
	boolean addShoppingList(String name, String preset, List<String> picks, List<String> members,
		Map<Integer, Integer> items)
	{
		boolean ok = !members.isEmpty() && asSelf(shopping, shop -> shop.add(ShoppingList.create(name, preset, picks,
			members, items, self, System.currentTimeMillis())));
		if (ok)
		{
			resolve(shoppingItemIds());
		}
		return ok;
	}

	boolean renameShoppingList(String id, String name)
	{
		return asSelf(shopping, shop -> shop.rename(id, name, self, System.currentTimeMillis()));
	}

	boolean removeShoppingList(String id)
	{
		return asSelf(shopping, shop -> shop.remove(id, self, System.currentTimeMillis()));
	}

	/** A custom list's item search, on the client thread; {@code done} gets tradeable matches, best first. */
	void searchItems(String query, Consumer<List<ShoppingTab.Hit>> done)
	{
		clientThread.invokeLater(() ->
		{
			List<ShoppingTab.Hit> hits = new ArrayList<>();
			for (ItemPrice p : itemManager.search(query))
			{
				if (hits.size() >= ShoppingTab.MAX_HITS)
				{
					break;
				}
				names.putIfAbsent(p.getId(), p.getName());
				hits.add(new ShoppingTab.Hit(p.getId(), p.getName()));
			}
			done.accept(hits);
		});
	}

	// ---- Requests: each member's own lists the group fills ----

	/** A request of this player's own; a blank name becomes "Name's requests". False when refused. */
	boolean addRequest(String name, Map<Integer, Integer> items)
	{
		ShoppingSync shop = shopping;
		if (shop == null || self.isEmpty())
		{
			return false;
		}
		long now = System.currentTimeMillis();
		RequestList r = RequestList.create(name, items, self, now);
		boolean ok = shop.addRequest(r);
		if (ok)
		{
			resolve(r.items.keySet());
			postRequest(RequestBoard.made(r, lookup::name, now));
		}
		return ok;
	}

	/** Owner only, as every request edit below. */
	boolean renameRequest(String id, String name)
	{
		return asSelf(shopping, shop -> shop.renameRequest(id, name, self, System.currentTimeMillis()));
	}

	boolean removeRequest(String id)
	{
		return asSelf(shopping, shop -> shop.removeRequest(id, self, System.currentTimeMillis()));
	}

	/** The owner closes the whole list by hand: no "done" post, since the group may not have it all. */
	boolean closeRequest(String id)
	{
		return asSelf(shopping, shop -> shop.closeRequest(id, self, System.currentTimeMillis()));
	}

	boolean closeRequestItem(String id, int itemId)
	{
		ShoppingSync shop = shopping;
		if (shop == null || self.isEmpty())
		{
			return false;
		}
		RequestList next = shop.closeItems(id, Collections.singleton(itemId), self, System.currentTimeMillis());
		postIfDone(next);
		return next != null;
	}

	/** "I'll get it" (or taking it back): anyone, on an open item. */
	boolean claimRequest(String id, int itemId, boolean claimed)
	{
		ShoppingSync shop = shopping;
		long now = System.currentTimeMillis();
		if (shop == null || self.isEmpty() || !shop.claim(id, itemId, self, claimed, now))
		{
			return false;
		}
		RequestList r = shop.request(id);
		if (claimed && r != null)
		{
			postRequest(RequestBoard.claimed(r, itemId, lookup.name(itemId), self, now));
		}
		return true;
	}

	/** Every request, worked out against what the group holds now. Any thread. */
	List<RequestBoard.Card> requestCards()
	{
		ShoppingSync shop = shopping;
		List<RequestBoard.Card> out = new ArrayList<>();
		if (shop == null)
		{
			return out;
		}
		ShopAllocation.Holdings holdings = ShopAllocation.Holdings.from(roster.searchSources());
		for (RequestList r : shop.requests())
		{
			out.add(RequestBoard.card(r, shop.claims(r.id), holdings, lookup::name));
		}
		return out;
	}

	/**
	 * Client thread, every {@link #SEAL_INTERVAL_TICKS}. Only the owner's client writes a request, so it is the
	 * one that closes items the group now holds enough of, and posts "done" (once) when that closes the list.
	 */
	private void sealRequests()
	{
		ShoppingSync shop = shopping;
		if (shop == null || self.isEmpty() || ++ticksSinceSeal < SEAL_INTERVAL_TICKS)
		{
			return;
		}
		ticksSinceSeal = 0;
		ShopAllocation.Holdings holdings = null;
		for (RequestList r : shop.requests())
		{
			if (!r.open() || !r.ownedBy(self))
			{
				continue;
			}
			if (holdings == null)
			{
				holdings = ShopAllocation.Holdings.from(roster.searchSources());
			}
			Set<Integer> reached = RequestBoard.reached(RequestBoard.card(r, Collections.emptyList(), holdings,
				lookup::name));
			postIfDone(shop.closeItems(r.id, reached, self, System.currentTimeMillis()));
		}
	}

	private void postIfDone(RequestList next)
	{
		if (next != null && next.closed)
		{
			postRequest(RequestBoard.done(next, next.at));
		}
	}

	/** One of this player's request events, to Discord and the banners under their own switches. */
	private void postRequest(GroupEvent event)
	{
		ifSet(events, e -> clientThread.invokeLater(() -> e.request(event)));
	}

	/** Someone joined or the party changed: roles, settings and every list, removals included, go out next tick. */
	private void resendShared()
	{
		ifSet(governance, GovernanceSync::resendAll);
		ifSet(shopping, ShoppingSync::resendAll);
	}

	/** Every item any live list may show, for names and whether it can change hands. */
	private Set<Integer> shoppingItemIds()
	{
		Set<Integer> ids = new HashSet<>();
		ShoppingSync shop = shopping;
		if (shop == null)
		{
			return ids;
		}
		for (RequestList r : shop.requests())
		{
			ids.addAll(r.items.keySet());
		}
		for (ShoppingList l : shop.active())
		{
			ids.addAll(l.items.keySet());
			ShopPresets.Preset p = l.custom() ? null : presets.preset(l.preset);
			if (p == null)
			{
				continue;
			}
			for (QuestData.Quest q : ShopNeeds.closure(questData, p.roots(l.picks)))
			{
				q.items().stream().filter(ShopNeeds::shoppable).forEach(i -> ids.add(i.itemId()));
			}
		}
		return ids;
	}

	/** Client thread. This player's quest progress and levels, every {@link #QUEST_INTERVAL_TICKS}. */
	private void pollQuests()
	{
		ShoppingSync shop = shopping;
		if (++ticksSinceQuests < QUEST_INTERVAL_TICKS || shop == null || self.isEmpty())
		{
			return;
		}
		ticksSinceQuests = 0;
		Map<String, Integer> levels = new HashMap<>();
		for (Skill skill : Skill.values())
		{
			if (skill != Skill.OVERALL)
			{
				levels.put(skill.getName(), client.getRealSkillLevel(skill));
			}
		}
		ownLevels = levels;
		shop.ownProgress(self, QuestStates.read(QuestStates.wanted(questData), q -> q.getState(client)));
		resolveNow(shoppingItemIds());
	}

	/** Client thread. "Shopping: shop alert": once per approach to a shop selling something still needed. */
	private void shopAlert()
	{
		if (!config.shoppingShopAlert() || ++ticksSinceShopAlert < SHOP_ALERT_INTERVAL_TICKS)
		{
			return;
		}
		ticksSinceShopAlert = 0;
		ShoppingSync shop = shopping;
		WorldPoint at = position();
		List<ShoppingList> lists = shop == null ? Collections.emptyList() : shop.active();
		if (at == null || lists.isEmpty())
		{
			return;
		}
		Map<String, List<ShopAllocation.Line>> shops = ShoppingBoard.byShop(ShoppingBoard.of(lists, shoppingInputs()));
		for (String name : shopVisits.arrived(at.getX(), at.getY(), at.getPlane(), shops.keySet(), questData))
		{
			tell(name + ": " + ShoppingBoard.describe(shops.get(name)) + ".");
		}
	}

	/** Kept for the panel: is any group feature on; false shows its "everything is off" notice. */
	boolean anyOn()
	{
		return switches().any() || !lowStock.isEmpty();
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;

/**
 * One version of the group's shared settings, signed by the leader or an
 * editor, with a short history of who changed what and when.
 *
 * <p><b>Last writer wins, by version.</b> Each save is the previous version
 * plus one. Two editors saving at once both make the same version; every
 * client then keeps the one {@link #newerThan} picks (later save time, then
 * the larger signature), so all clients settle on the same document whatever
 * order they hear them in. The losing edit is not merged; its author sees the
 * winner replace it and can save again.
 */
final class GroupSettings
{
	/** History entries kept: enough to see the last few changes, small enough for one party message. */
	static final int MAX_HISTORY = 12;
	/** A save touching more than this many settings is one history line ("changed 14 settings"). */
	static final int MAX_LINES_PER_SAVE = 4;
	/** The history key of a save summarised as a count. */
	static final String MANY = "*";

	/** One line of history. For {@link #MANY}, {@code to} is how many settings changed. */
	static final class Change
	{
		final long at;
		final String by;
		final String key;
		final long from;
		final long to;

		Change(long at, String by, String key, long from, long to)
		{
			this.at = at;
			this.by = by;
			this.key = key;
			this.from = from;
			this.to = to;
		}

		String canonical()
		{
			return GroupSigner.canonical(at, by, key, from, to);
		}
	}

	final long version;
	final long at;
	final String by;
	final String byKey;
	/** Known keys only, clamped: see {@link GroupSettingsSchema#sanitize}. */
	final Map<String, Long> values;
	/** Newest first. */
	final List<Change> history;
	final String signature;

	GroupSettings(long version, long at, String by, String byKey, Map<String, Long> values, List<Change> history,
		String signature)
	{
		this.version = version;
		this.at = at;
		this.by = by;
		this.byKey = byKey;
		this.values = Collections.unmodifiableMap(new TreeMap<>(values));
		this.history = Collections.unmodifiableList(new ArrayList<>(
			history.subList(0, Math.min(MAX_HISTORY, history.size()))));
		this.signature = signature;
	}

	/**
	 * The version after {@code previous} (null for the group's first), with
	 * {@code values}, signed by {@code by}'s {@code id}. Whether {@code by} may
	 * sign it is the caller's check ({@link GroupGovernance}).
	 */
	static GroupSettings next(GroupSettings previous, Map<String, Long> values, String by, GroupSigner.Identity id,
		long now)
	{
		Map<String, Long> clean = GroupSettingsSchema.sanitize(values);
		List<Change> history = new ArrayList<>();
		history.addAll(changes(previous, clean, by, now));
		if (previous != null)
		{
			history.addAll(previous.history);
		}
		long version = previous == null ? 1 : previous.version + 1;
		long at = previous == null ? now : Math.max(now, previous.at);
		return sign(version, at, by, id, clean, history);
	}

	/** The same values as a new version signed by {@code id}: after the editor who saved them is revoked. */
	GroupSettings resign(String leader, GroupSigner.Identity id, long now)
	{
		List<Change> history = new ArrayList<>();
		history.add(new Change(Math.max(now, at), leader, "resigned:" + by, 0, 0));
		history.addAll(this.history);
		return sign(version + 1, Math.max(now, at), leader, id, values, history);
	}

	private static GroupSettings sign(long version, long at, String by, GroupSigner.Identity id,
		Map<String, Long> values, List<Change> history)
	{
		GroupSettings unsigned = new GroupSettings(version, at, by, id.publicKey(), values, history, "");
		return new GroupSettings(version, at, by, id.publicKey(), values, unsigned.history,
			id.sign(unsigned.canonical()));
	}

	private static List<Change> changes(GroupSettings previous, Map<String, Long> values, String by, long now)
	{
		if (previous == null)
		{
			return Collections.singletonList(new Change(now, by, MANY, 0, values.size()));
		}
		List<Change> out = new ArrayList<>();
		for (Map.Entry<String, Long> e : values.entrySet())
		{
			Long before = previous.values.get(e.getKey());
			if (!e.getValue().equals(before))
			{
				out.add(new Change(now, by, e.getKey(), before == null ? 0 : before, e.getValue()));
			}
		}
		if (out.size() > MAX_LINES_PER_SAVE)
		{
			return Collections.singletonList(new Change(now, by, MANY, 0, out.size()));
		}
		return out;
	}

	String canonical()
	{
		StringBuilder vals = new StringBuilder();
		for (Map.Entry<String, Long> e : values.entrySet())
		{
			vals.append(GroupSigner.canonical(e.getKey(), e.getValue()));
		}
		StringBuilder hist = new StringBuilder();
		for (Change c : history)
		{
			hist.append(c.canonical());
		}
		return GroupSigner.canonical("gimu-settings", 1, version, at, by, byKey, vals, hist);
	}

	/** Signed by the key it names; whether that key may edit is {@link GroupRoles#mayEdit}. */
	boolean verify()
	{
		return version >= 1 && !by.isEmpty() && GroupSigner.verify(byKey, canonical(), signature);
	}

	/** Same values as {@code other} (or both have none). */
	boolean sameValues(Map<String, Long> other)
	{
		return Objects.equals(values, GroupSettingsSchema.sanitize(other));
	}

	/** The total order every client uses to pick one document: version, then save time, then signature. */
	boolean newerThan(GroupSettings other)
	{
		return other == null || newer(version, at, signature, other.version, other.at, other.signature);
	}

	/** The order of two signed documents: version, then save time, then signature. Shared with {@link GroupWebhooks}. */
	static boolean newer(long version, long at, String signature, long otherVersion, long otherAt, String otherSignature)
	{
		if (version != otherVersion)
		{
			return version > otherVersion;
		}
		if (at != otherAt)
		{
			return at > otherAt;
		}
		return signature.compareTo(otherSignature) > 0;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.Predicate;
import java.util.function.ToLongFunction;

/**
 * The settings a group shares: thresholds, which events post to Discord and
 * show as overlays, the daily digest, Easter eggs, quiet hours and the
 * offline grace. Each is one number (switches are 0 or 1) under a key, and
 * each knows how to read its value from a member's own config, which is how
 * a group's first settings are seeded from the leader's (and what a member
 * uses while their group has none).
 *
 * <p><b>What is not here, on purpose.</b> Webhook URLs, the mention, "Post to
 * Discord" itself, "Online status" and every "Share ..." switch stay each member's own: they
 * are where a member's posts go and what of theirs leaves their client, and a
 * webhook is a secret. {@code GroupSettingsSchemaTest} checks no key here
 * names one. The one way a webhook reaches members is the leader's own
 * opt-in, "Share webhooks with the group": a separate document signed by the
 * leader only ({@link GroupWebhooks}), never these settings, which editors sign too.
 */
final class GroupSettingsSchema
{
	static final String THRESHOLDS = "What counts";
	static final String DISCORD = "Discord: which events";
	static final String OVERLAY = "Overlays: which events";
	static final String DIGEST = "Daily digest";
	static final String TIMING = "Discord timing and extras";

	/** One shared setting. */
	static final class Setting
	{
		final String key;
		final String label;
		final String section;
		/** A switch, 0 or 1. */
		final boolean flag;
		final long min;
		final long max;
		final ToLongFunction<GroupIronmanConfig> seed;

		private Setting(String key, String label, String section, boolean flag, long min, long max,
			ToLongFunction<GroupIronmanConfig> seed)
		{
			this.key = key;
			this.label = label;
			this.section = section;
			this.flag = flag;
			this.min = min;
			this.max = max;
			this.seed = seed;
		}

		long clamp(long value)
		{
			return Math.max(min, Math.min(max, value));
		}
	}

	/**
	 * Logins and logouts post to Discord by this member's own "Online status"
	 * (posts or the live board), never by a group switch: one member per Group
	 * webhook keeps the board, and a group switch would post beside it.
	 */
	static final GroupEvent.Type OWN_DISCORD = GroupEvent.Type.ONLINE;
	/** "Post events for members without the plugin" ({@link GroupBroadcasts}), on by default. */
	static final String NO_PLUGIN_EVENTS = "discordNoPluginEvents";
	/** "Post every N waves" for wave activities ({@link WaveTracker}); 0 posts the final boss waves only. */
	static final String WAVE_EVERY = "eventWaveEvery";

	private static final long GP_MAX = Integer.MAX_VALUE;
	private static final Map<String, Setting> BY_KEY = new LinkedHashMap<>();
	/** In the order the panel lists them. */
	static final List<Setting> ALL;

	static
	{
		number("eventDropMinValue", "Valuable drop at least (gp)", 0, GP_MAX, GroupIronmanConfig::eventDropMinValue);
		number("eventStorageMinValue", "Big storage move at least (gp)", 0, GP_MAX,
			GroupIronmanConfig::eventStorageMinValue);
		number("eventLevelMin", "Level ups from level", 1, 99, GroupIronmanConfig::eventLevelMin);
		number("eventLevelEvery", "Post every N levels", 1, 98, GroupIronmanConfig::eventLevelEvery);
		number("eventBackAfterDays", "Back after (days)", 1, 365, GroupIronmanConfig::eventBackAfterDays);
		number("eventClueMinValue", "Clue reward at least (gp)", 0, GP_MAX, GroupIronmanConfig::eventClueMinValue);
		number("eventKcEvery", "Kill count milestone every", 0, 100_000, GroupIronmanConfig::eventKcEvery);
		number("eventGravestoneWarnMinutes", "Gravestone warning (minutes left)", 1, 14,
			GroupIronmanConfig::eventGravestoneWarnMinutes);
		number(WAVE_EVERY, "Post every N waves", 0, 100, GroupIronmanConfig::eventWaveEvery);

		for (GroupEvent.Type t : GroupEvent.Type.values())
		{
			if (t != OWN_DISCORD)
			{
				flag(discordKey(t), EventText.title(t), DISCORD, EventSettings.DISCORD.get(t));
			}
		}
		for (GroupEvent.Type t : GroupEvent.Type.values())
		{
			flag(overlayKey(t), EventText.title(t), OVERLAY, EventSettings.OVERLAY.get(t));
		}
		for (GroupEvent.Category c : GroupEvent.Category.values())
		{
			flag(digestKey(c), title(c.name()), DIGEST, EventSettings.DIGEST.get(c));
		}

		timing("discordDigestHour", "Digest hour", 0, 23, GroupIronmanConfig::discordDigestHour);
		timing("discordQuietStart", "Quiet hours from", 0, 23, GroupIronmanConfig::discordQuietStart);
		timing("discordQuietEnd", "Quiet hours until", 0, 23, GroupIronmanConfig::discordQuietEnd);
		timing("discordOfflineGrace", "Offline grace (minutes)", 0, 10, GroupIronmanConfig::discordOfflineGrace);
		flag("discordEasterEggs", "Easter eggs", TIMING, GroupIronmanConfig::discordEasterEggs);
		timing("discordLegendAt", "Legend at (gp)", 0, GP_MAX, GroupIronmanConfig::discordLegendAt);
		timing("discordFreeloaderAt", "Freeloader at (gp)", 0, GP_MAX, GroupIronmanConfig::discordFreeloaderAt);
		flag(NO_PLUGIN_EVENTS, "Post events for members without the plugin", TIMING,
			GroupIronmanConfig::discordNoPluginEvents);

		ALL = Collections.unmodifiableList(new ArrayList<>(BY_KEY.values()));
	}

	private GroupSettingsSchema()
	{
	}

	private static void number(String key, String label, long min, long max, ToLongFunction<GroupIronmanConfig> seed)
	{
		add(new Setting(key, label, THRESHOLDS, false, min, max, seed));
	}

	private static void timing(String key, String label, long min, long max, ToLongFunction<GroupIronmanConfig> seed)
	{
		add(new Setting(key, label, TIMING, false, min, max, seed));
	}

	private static void flag(String key, String label, String section, Predicate<GroupIronmanConfig> seed)
	{
		add(new Setting(key, label, section, true, 0, 1, c -> seed.test(c) ? 1 : 0));
	}

	private static void add(Setting s)
	{
		if (BY_KEY.put(s.key, s) != null)
		{
			throw new IllegalStateException("duplicate group setting " + s.key);
		}
	}

	private static String title(String enumName)
	{
		String lower = enumName.toLowerCase(Locale.ROOT).replace('_', ' ');
		return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
	}

	static String discordKey(GroupEvent.Type type)
	{
		return "discord." + type.code;
	}

	static String overlayKey(GroupEvent.Type type)
	{
		return "overlay." + type.code;
	}

	static String digestKey(GroupEvent.Category category)
	{
		return "digest." + category.name().toLowerCase(Locale.ROOT);
	}

	/** Null for a key this build does not know. */
	static Setting get(String key)
	{
		return BY_KEY.get(key);
	}

	/** Every group setting as {@code config} has it: what the first save publishes. */
	static Map<String, Long> seed(GroupIronmanConfig config)
	{
		Map<String, Long> out = new TreeMap<>();
		for (Setting s : ALL)
		{
			out.put(s.key, s.clamp(s.seed.applyAsLong(config)));
		}
		return out;
	}

	/** Known keys only, each clamped to its range: what a received document is reduced to. */
	static Map<String, Long> sanitize(Map<String, Long> values)
	{
		Map<String, Long> out = new TreeMap<>();
		for (Map.Entry<String, Long> e : values.entrySet())
		{
			Setting s = BY_KEY.get(e.getKey());
			if (s != null && e.getValue() != null)
			{
				out.put(s.key, s.clamp(e.getValue()));
			}
		}
		return out;
	}

	/** The value of each group setting now: the group's when it has settings, else this member's own config. */
	static final class Resolved
	{
		private final GroupIronmanConfig config;
		private final Map<String, Long> group;

		Resolved(GroupIronmanConfig config, GroupSettings settings)
		{
			this.config = config;
			this.group = settings == null ? Collections.emptyMap() : settings.values;
		}

		long value(String key)
		{
			Setting s = BY_KEY.get(key);
			if (s == null)
			{
				throw new IllegalArgumentException("not a group setting: " + key);
			}
			Long v = group.get(key);
			return v != null ? s.clamp(v) : s.clamp(s.seed.applyAsLong(config));
		}

		int intValue(String key)
		{
			return (int) Math.min(Integer.MAX_VALUE, value(key));
		}

		boolean on(String key)
		{
			return value(key) != 0;
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.TreeMap;
import java.util.function.Function;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComponent;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import static com.vinnyvangogh.groupironman.GroupIronmanPanel.heading;
import static com.vinnyvangogh.groupironman.GroupIronmanPanel.text;

/**
 * The panel's Settings tab: the group's shared settings (editable by the
 * leader and editors, read-only for everyone else), who changed what, the
 * leader's editor list, this member's own opt-outs, and the read-only grid of
 * who posts what.
 *
 * <p>Edits go into a draft and are only sent on "Save to group". The tab is
 * rebuilt only when what it shows changed, so a half-typed number survives
 * the many redraws member stats cause.
 */
final class GroupSettingsTab
{
	/** What the tab's buttons do. */
	interface Actions
	{
		boolean claim();

		boolean setEditor(String name, boolean editor);

		GovernanceSync.SaveResult save(Map<String, Long> values);

		/** The leader's "Share webhooks with the group"; false when refused. */
		boolean shareWebhooks(boolean share);

		void forgetLeader();

		void optOut(GroupEvent.Type type, boolean overlay, boolean out);

		void optOutAll(boolean out);
	}

	/** Everything the tab draws, captured with the rest of the panel's view. */
	static final class View
	{
		final GroupGovernance.Role role;
		final GroupRoles roles;
		final GroupSettings settings;
		final boolean unclaimed;
		final boolean syncing;
		final List<String> members;
		final String self;
		/** Each shared setting's value now: the group's, or this member's own while the group has none. */
		final Map<String, Long> current;
		final MemberPrefs mine;
		final Map<String, MemberPrefs> prefs;
		/** Members whose key this client has heard: only they can be made editor. */
		final Set<String> heard;
		/** Who shares the group's webhooks (the leader), or null when nobody does. Never a URL. */
		final String webhooksBy;

		View(GroupGovernance.Role role, GroupRoles roles, GroupSettings settings, boolean unclaimed, boolean syncing,
			List<String> members, String self, Map<String, Long> current, MemberPrefs mine,
			Map<String, MemberPrefs> prefs, Set<String> heard, String webhooksBy)
		{
			this.webhooksBy = webhooksBy;
			this.role = role;
			this.roles = roles;
			this.settings = settings;
			this.unclaimed = unclaimed;
			this.syncing = syncing;
			this.members = members;
			this.self = self;
			this.current = current;
			this.mine = mine;
			this.prefs = prefs;
			this.heard = heard;
		}

		/**
		 * The view from this client's governance: {@code roster} is the group's names,
		 * {@code current} each shared setting's value now. Never a webhook URL, only who shares them.
		 */
		static View of(GroupGovernance g, String self, Collection<String> roster, Map<String, Long> current,
			MemberPrefs mine, boolean syncing)
		{
			List<String> members = gridMembers(roster, self);
			Set<String> heard = new HashSet<>();
			for (String m : members)
			{
				if (g.knownKey(m) != null)
				{
					heard.add(m);
				}
			}
			GroupWebhooks shared = g.sharedWebhooks();
			return new View(g.myRole(self), g.roles(), g.settings(), g.unclaimed(), syncing, members, self, current,
				mine, g.prefs(), heard, shared == null ? null : shared.by);
		}

		boolean canEdit()
		{
			return role != GroupGovernance.Role.MEMBER;
		}

		/**
		 * Changes when anything drawn changes; the draft is not part of it. Only
		 * decides whether to rebuild: what replaces the draft is {@link SettingsDraft#update}.
		 */
		String signature()
		{
			return String.join("|", String.valueOf(role), roles == null ? "" : roles.signature,
				settings == null ? "" : settings.signature, String.valueOf(unclaimed), String.valueOf(syncing),
				String.valueOf(members), self, String.valueOf(mine.all), String.valueOf(mine.noPost),
				String.valueOf(mine.mute), String.valueOf(prefsText()), String.valueOf(heard),
				settings == null ? String.valueOf(current) : "", String.valueOf(webhooksBy));
		}

		private String prefsText()
		{
			StringBuilder out = new StringBuilder();
			for (Map.Entry<String, MemberPrefs> e : prefs.entrySet())
			{
				out.append(e.getKey()).append(e.getValue().all).append(e.getValue().noPost);
			}
			return out.toString();
		}
	}

	private static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR.darker();

	private final Actions actions;
	/** Redraws the panel; a button's result shows at once rather than at the next member update. */
	private final Runnable refresh;
	/** Section names the player opened (or closed, for those open by default). */
	private final Set<String> open = new HashSet<>();
	private final SettingsDraft draft = new SettingsDraft();
	/** The number inputs on screen: text typed into one is only in the draft once committed. */
	private final List<JSpinner> spinners = new ArrayList<>();
	private String drawn;
	private String note;

	GroupSettingsTab(Actions actions, Runnable refresh)
	{
		this.actions = actions;
		this.refresh = refresh;
	}

	/** Whether {@link #draw} would show something different from what is on screen. */
	boolean changed(View v)
	{
		return !Objects.equals(drawn, v.signature());
	}

	void draw(JPanel tab, View v, long now)
	{
		// A number typed but not yet committed would be lost with the old inputs.
		commitTyped();
		spinners.clear();
		draft.update(v.role, v.roles, v.settings, v.current);
		drawn = v.signature();
		drawHeader(tab, v, now);
		drawEditors(tab, v);
		drawWebhooks(tab, v);
		drawSettings(tab, v);
		drawHistory(tab, v, now);
		drawMine(tab, v);
		drawGrid(tab, v);
	}

	private void redraw(JPanel tab, View v)
	{
		tab.removeAll();
		drawn = null;
		draw(tab, v, System.currentTimeMillis());
		tab.revalidate();
		tab.repaint();
	}

	// ---- Leader, role, claim ----

	private void drawHeader(JPanel tab, View v, long now)
	{
		tab.add(heading("Group settings"));
		for (String line : SettingsModel.header(v.role, v.roles, v.settings, now))
		{
			tab.add(text(line, Color.WHITE));
		}
		if (!v.syncing)
		{
			tab.add(text("Join group sync to send or receive group settings.", MUTED));
		}
		if (note != null)
		{
			tab.add(text(note, ColorScheme.BRAND_ORANGE));
		}
		JPanel buttons = new JPanel(new GridLayout(0, 2, 2, 2));
		if (v.unclaimed)
		{
			buttons.add(button("Claim leadership", "Become your group's leader. Only works while your group has no"
				+ " leader; members accept it once they have heard from you.", () ->
				note = actions.claim() ? "You are the leader. Save group settings below." : "Could not claim: log in"
					+ " on your Group Ironman first."));
		}
		if (v.roles != null)
		{
			buttons.add(button("Forget leader", "This client only: forget who leads, e.g. if the leader lost their"
				+ " settings. The next claim you hear becomes your leader.", () ->
			{
				if (confirm("Forget your group's leader on this client? The next leader you hear from is trusted."))
				{
					actions.forgetLeader();
				}
			}));
		}
		tab.add(buttons);
	}

	// ---- Editors (leader only) ----

	private void drawEditors(JPanel tab, View v)
	{
		if (v.role != GroupGovernance.Role.LEADER)
		{
			return;
		}
		tab.add(heading("Editors"));
		tab.add(text("Editors can change group settings. Only you can add or remove them.", MUTED));
		for (String member : v.members)
		{
			if (GroupMembers.key(member).equals(GroupMembers.key(v.self)))
			{
				continue;
			}
			boolean editor = v.roles.editorKey(member) != null;
			boolean known = containsName(v.heard, member);
			JPanel row = new JPanel(new BorderLayout());
			row.add(text(member + (known ? "" : " (not heard from yet)"), Color.WHITE), BorderLayout.CENTER);
			JButton b = button(editor ? "Remove editor" : "Make editor", null,
				() -> note = actions.setEditor(member, !editor) ? null : "Could not change " + member + "'s role.");
			b.setEnabled(editor || known);
			row.add(b, BorderLayout.EAST);
			tab.add(row);
		}
	}

	// ---- Shared webhooks (the switch is the leader's only) ----

	private void drawWebhooks(JPanel tab, View v)
	{
		for (String line : SettingsModel.webhookLines(v.role, v.webhooksBy))
		{
			tab.add(text(line, MUTED));
		}
		if (v.role != GroupGovernance.Role.LEADER)
		{
			return;
		}
		JCheckBox box = new JCheckBox("Share webhooks with the group", v.webhooksBy != null);
		small(box);
		box.setToolTipText("Send your seven webhooks and poster names to every member, so they only tick 'Post to"
			+ " Discord'. Anyone with the group key can read them. Off, or a new group key, stops sending them.");
		box.addActionListener(e ->
		{
			boolean on = box.isSelected();
			if (on && !confirm("Send your Discord webhooks to every member? Anyone with the group key can read"
				+ " them. A member's own webhook still wins for that category."))
			{
				box.setSelected(false);
				return;
			}
			note = actions.shareWebhooks(on) ? null : "Could not change sharing: you are no longer the leader.";
			refresh.run();
		});
		tab.add(box);
	}

	// ---- The shared settings ----

	private void drawSettings(JPanel tab, View v)
	{
		if (!v.canEdit() && v.settings == null)
		{
			return;
		}
		tab.add(heading(v.canEdit() ? "Edit group settings" : "Your group's settings"));
		if (v.canEdit() && v.settings == null)
		{
			tab.add(text("Nothing saved yet: these are your own settings. Save to make them the group's.", MUTED));
		}
		if (v.canEdit() && draft.notice() != null)
		{
			tab.add(text(draft.notice(), ColorScheme.BRAND_ORANGE));
		}
		drawInputs(tab, v);
		if (v.canEdit())
		{
			JPanel buttons = new JPanel(new GridLayout(0, 2, 2, 2));
			buttons.add(button("Save to group", "Send these to every member. They replace each member's own.",
				this::save));
			buttons.add(button("Discard changes", null, () ->
			{
				draft.discard(v.current);
				note = null;
			}));
			tab.add(buttons);
		}
	}

	private void save()
	{
		commitTyped();
		GovernanceSync.SaveResult r = actions.save(new TreeMap<>(draft.values()));
		if (r == GovernanceSync.SaveResult.SAVED || r == GovernanceSync.SaveResult.SAVED_OFFLINE
			|| r == GovernanceSync.SaveResult.UNCHANGED)
		{
			draft.saved();
		}
		note = saveNote(r);
	}

	/** What the tab says after "Save to group": each refusal names its reason. */
	static String saveNote(GovernanceSync.SaveResult r)
	{
		switch (r)
		{
			case SAVED:
				return "Saved and sent to your group.";
			case SAVED_OFFLINE:
				return "Saved. It goes to your group when you join group sync.";
			case UNCHANGED:
				return "Nothing to save: these are already your group's settings.";
			case NOT_EDITOR:
				return "Not saved: you are no longer leader or editor.";
			case NOT_LOGGED_IN:
				return "Not saved: log in on your Group Ironman first.";
			default:
				return "Not saved: group settings are still starting. Try again in a moment.";
		}
	}

	/** Text typed into a number input counts once it parses; the Save button never takes focus to commit it. */
	private void commitTyped()
	{
		for (JSpinner s : spinners)
		{
			try
			{
				s.commitEdit();
			}
			catch (java.text.ParseException e)
			{
				// Not a number: the input keeps its last good value.
			}
		}
	}

	/** One collapsible section per schema section; only "What counts" starts open. */
	private void drawInputs(JPanel tab, View v)
	{
		String section = null;
		JPanel body = null;
		for (GroupSettingsSchema.Setting s : GroupSettingsSchema.ALL)
		{
			if (!s.section.equals(section))
			{
				section = s.section;
				body = collapsible(tab, section, !section.equals(GroupSettingsSchema.THRESHOLDS), v);
			}
			if (body != null)
			{
				body.add(input(s, v.canEdit()));
			}
		}
	}

	private JComponent input(GroupSettingsSchema.Setting s, boolean editable)
	{
		long value = draft.values().getOrDefault(s.key, 0L);
		if (s.flag)
		{
			JCheckBox box = new JCheckBox(s.label, value != 0);
			small(box);
			box.setEnabled(editable);
			box.addActionListener(e -> draft.put(s.key, box.isSelected() ? 1L : 0L));
			return box;
		}
		JPanel row = new JPanel(new BorderLayout());
		row.add(text(s.label, Color.WHITE), BorderLayout.CENTER);
		JSpinner spinner = new JSpinner(new SpinnerNumberModel(Long.valueOf(value), Long.valueOf(s.min),
			Long.valueOf(s.max), Long.valueOf(1)));
		spinner.setEnabled(editable);
		spinner.addChangeListener(e -> draft.put(s.key, ((Number) spinner.getValue()).longValue()));
		if (editable)
		{
			spinners.add(spinner);
		}
		row.add(spinner, BorderLayout.EAST);
		return row;
	}

	private void drawHistory(JPanel tab, View v, long now)
	{
		List<String> lines = SettingsModel.history(v.settings, now);
		if (lines.isEmpty())
		{
			return;
		}
		tab.add(heading("Recent changes"));
		for (String line : lines)
		{
			tab.add(text(line, MUTED));
		}
	}

	// ---- This member's own ----

	private void drawMine(JPanel tab, View v)
	{
		tab.add(heading("My events"));
		tab.add(text("Yours alone; the group cannot change these. Posting is your own events to Discord; showing is"
			+ " banners on your screen.", MUTED));
		JCheckBox all = new JCheckBox("Don't post my events", v.mine.all);
		small(all);
		all.addActionListener(e -> actions.optOutAll(all.isSelected()));
		tab.add(all);
		JPanel body = collapsible(tab, "Per event kind", true, v);
		if (body == null)
		{
			return;
		}
		for (GroupEvent.Type t : GroupEvent.Type.values())
		{
			JPanel row = new JPanel(new BorderLayout());
			row.add(text(EventText.title(t), Color.WHITE), BorderLayout.CENTER);
			JPanel boxes = new JPanel(new GridLayout(1, 2));
			boxes.add(optBox("Post", !v.mine.noPost.contains(t) && !v.mine.all, !v.mine.all,
				on -> actions.optOut(t, false, !on)));
			boxes.add(optBox("Show", !v.mine.mute.contains(t), true, on -> actions.optOut(t, true, !on)));
			row.add(boxes, BorderLayout.EAST);
			body.add(row);
		}
	}

	private static JCheckBox optBox(String label, boolean on, boolean enabled, java.util.function.Consumer<Boolean> set)
	{
		JCheckBox box = new JCheckBox(label, on);
		small(box);
		box.setEnabled(enabled);
		box.addActionListener(e -> set.accept(box.isSelected()));
		return box;
	}

	// ---- Who posts what (leader and editors, read-only) ----

	private void drawGrid(JPanel tab, View v)
	{
		if (!v.canEdit())
		{
			return;
		}
		JPanel body = collapsible(tab, "Who posts what", true, v);
		if (body == null)
		{
			return;
		}
		body.add(text("Each member's own choice; only they can change it. ? = not heard from yet.", MUTED));
		Map<String, MemberPrefs> prefs = new TreeMap<>(v.prefs);
		prefs.put(v.self, v.mine);
		SettingsModel.Grid grid = SettingsModel.grid(v.members, prefs);
		body.add(gridRow("", grid.members, Function.identity()));
		for (SettingsModel.GridRow r : grid.rows)
		{
			body.add(gridRow(r.label, r.cells, GroupSettingsTab::cell));
		}
	}

	private static <T> JComponent gridRow(String label, List<T> cells, Function<T, String> show)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.add(text(label, Color.WHITE), BorderLayout.CENTER);
		JPanel right = new JPanel(new GridLayout(1, Math.max(1, cells.size()), 2, 0));
		for (T c : cells)
		{
			right.add(Ui.label(show.apply(c), FontManager.getRunescapeSmallFont(), Color.WHITE));
		}
		row.add(right, BorderLayout.EAST);
		return row;
	}

	private static String cell(SettingsModel.Cell c)
	{
		switch (c)
		{
			case IN:
				return "yes";
			case OUT:
				return "no";
			default:
				return "?";
		}
	}

	// ---- Building blocks ----

	/** A section header that opens and closes; the body to fill, or null while closed. */
	private JPanel collapsible(JPanel tab, String name, boolean closedByDefault, View v)
	{
		boolean shown = closedByDefault ? open.contains(name) : !open.contains(name);
		JPanel parent = tab;
		JButton header = new JButton((shown ? "- " : "+ ") + name);
		header.setFont(FontManager.getRunescapeBoldFont());
		header.setForeground(ColorScheme.BRAND_ORANGE);
		header.setFocusable(false);
		header.setContentAreaFilled(false);
		header.setBorderPainted(false);
		header.setHorizontalAlignment(JButton.LEFT);
		header.addActionListener(e ->
		{
			if (!open.remove(name))
			{
				open.add(name);
			}
			redraw(parent, v);
		});
		tab.add(header);
		if (!shown)
		{
			return null;
		}
		JPanel body = new GroupIronmanPanel.Column();
		tab.add(body);
		return body;
	}

	private JButton button(String label, String tooltip, Runnable action)
	{
		return Ui.button(label, tooltip, () ->
		{
			action.run();
			drawn = null;
			refresh.run();
		});
	}

	private static boolean confirm(String question)
	{
		return JOptionPane.showConfirmDialog(null, question, "GIM Utilities", JOptionPane.YES_NO_OPTION)
			== JOptionPane.YES_OPTION;
	}

	private static boolean containsName(Set<String> names, String name)
	{
		String key = GroupMembers.key(name);
		for (String n : names)
		{
			if (GroupMembers.key(n).equals(key))
			{
				return true;
			}
		}
		return false;
	}

	private static void small(JComponent c)
	{
		c.setFont(FontManager.getRunescapeSmallFont());
		c.setForeground(Color.WHITE);
	}

	/** Names as the grid lists them: the roster, or this player alone before it is known. */
	static List<String> gridMembers(Collection<String> roster, String self)
	{
		List<String> out = new ArrayList<>(roster);
		if (out.isEmpty() && !self.isEmpty())
		{
			out.add(self);
		}
		return out;
	}
}

package com.vinnyvangogh.groupironman;

import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.KeyFactory;
import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.PrivateKey;
import java.security.PublicKey;
import java.security.SecureRandom;
import java.security.Signature;
import java.security.spec.ECGenParameterSpec;
import java.security.spec.PKCS8EncodedKeySpec;
import java.security.spec.X509EncodedKeySpec;
import java.util.Base64;

/**
 * Signatures for the group's roles and settings, so a member cannot promote
 * themselves or change the group's settings by sending a document of their own.
 *
 * <p>ECDSA on P-256 from the JDK's own {@code java.security} (SunEC, in every
 * Java 11+ runtime RuneLite ships); no library and no network. Each client
 * makes one key pair on first use and keeps it in its own RuneLite config. The
 * public half travels in the member's announce; the private half never leaves
 * the client and is never logged.
 */
final class GroupSigner
{
	private static final String CURVE = "secp256r1";
	private static final String ALGORITHM = "SHA256withECDSA";
	/** An X.509 P-256 public key is 91 bytes, 124 characters of base64; a little headroom. */
	static final int MAX_KEY_CHARS = 200;
	/** A DER P-256 signature is at most 72 bytes, 96 characters of base64. */
	static final int MAX_SIGNATURE_CHARS = 140;

	private GroupSigner()
	{
	}

	/** This client's key pair. */
	static final class Identity
	{
		private final String publicKey;
		private final PrivateKey privateKey;
		private final String savedPrivate;

		private Identity(String publicKey, PrivateKey privateKey, String savedPrivate)
		{
			this.publicKey = publicKey;
			this.privateKey = privateKey;
			this.savedPrivate = savedPrivate;
		}

		static Identity create()
		{
			try
			{
				KeyPairGenerator gen = KeyPairGenerator.getInstance("EC");
				gen.initialize(new ECGenParameterSpec(CURVE), new SecureRandom());
				KeyPair pair = gen.generateKeyPair();
				return new Identity(b64(pair.getPublic().getEncoded()), pair.getPrivate(),
					b64(pair.getPrivate().getEncoded()));
			}
			catch (GeneralSecurityException e)
			{
				throw new IllegalStateException("no P-256 in this Java runtime", e);
			}
		}

		/** The identity {@link #save} wrote, or null when {@code saved} is not one. */
		static Identity load(String saved)
		{
			if (saved == null)
			{
				return null;
			}
			int dot = saved.indexOf('.');
			if (dot <= 0)
			{
				return null;
			}
			String pub = saved.substring(0, dot);
			String priv = saved.substring(dot + 1);
			try
			{
				KeyFactory kf = KeyFactory.getInstance("EC");
				PrivateKey key = kf.generatePrivate(new PKCS8EncodedKeySpec(Base64.getDecoder().decode(priv)));
				kf.generatePublic(new X509EncodedKeySpec(Base64.getDecoder().decode(pub)));
				Identity id = new Identity(pub, key, priv);
				// A pair whose halves do not match would sign documents nobody accepts.
				return verify(pub, "check", id.sign("check")) ? id : null;
			}
			catch (GeneralSecurityException | IllegalArgumentException e)
			{
				return null;
			}
		}

		/** What goes in the config: public and private key, base64, joined by a dot. */
		String save()
		{
			return publicKey + "." + savedPrivate;
		}

		String publicKey()
		{
			return publicKey;
		}

		String sign(String text)
		{
			try
			{
				Signature s = Signature.getInstance(ALGORITHM);
				s.initSign(privateKey);
				s.update(text.getBytes(StandardCharsets.UTF_8));
				return b64(s.sign());
			}
			catch (GeneralSecurityException e)
			{
				throw new IllegalStateException("signing failed", e);
			}
		}

		@Override
		public String toString()
		{
			// Never the private key, even in a debug log.
			return "Identity[" + publicKey.substring(Math.max(0, publicKey.length() - 8)) + "]";
		}
	}

	/** True when {@code signature} is {@code publicKey}'s over {@code text}; false for anything malformed. */
	static boolean verify(String publicKey, String text, String signature)
	{
		if (publicKey == null || signature == null || text == null || publicKey.length() > MAX_KEY_CHARS
			|| signature.length() > MAX_SIGNATURE_CHARS)
		{
			return false;
		}
		try
		{
			PublicKey key = KeyFactory.getInstance("EC")
				.generatePublic(new X509EncodedKeySpec(Base64.getDecoder().decode(publicKey)));
			Signature s = Signature.getInstance(ALGORITHM);
			s.initVerify(key);
			s.update(text.getBytes(StandardCharsets.UTF_8));
			return s.verify(Base64.getDecoder().decode(signature));
		}
		catch (GeneralSecurityException | IllegalArgumentException e)
		{
			return false;
		}
	}

	/**
	 * The text a document is signed over: each part length-prefixed, so no
	 * name or value can be shifted from one field into the next.
	 */
	static String canonical(Object... parts)
	{
		StringBuilder out = new StringBuilder();
		for (Object part : parts)
		{
			String s = String.valueOf(part);
			out.append(s.length()).append(':').append(s).append(';');
		}
		return out.toString();
	}

	private static String b64(byte[] bytes)
	{
		return Base64.getEncoder().encodeToString(bytes);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Objects;

/**
 * Joining and leaving the group's RuneLite party, without the Party panel.
 *
 * <p>RuneLite's {@code PartyService} is a core client service, so this works
 * with the Party plugin turned off (and its overlays then stay hidden). The
 * passphrase comes from {@link GroupKey}; the player never types it.
 *
 * <p>Every join is a click. Joining a party on login or on a timer is a
 * rejected Plugin Hub feature ("Auto-rejoin for parties: would put undue
 * strain on the party servers"; Party Smarty, plugin-hub #19833, was closed
 * for it), so nothing here runs on its own except leaving.
 *
 * <p>Rules: a party the player joined themselves (raids, a friend) is never
 * replaced without them pressing "Switch"; on shutdown only a party this
 * plugin joined is left.
 */
final class GroupSync
{
	/** The slice of {@code PartyService} this needs, so the rules can be tested without a client. */
	interface Party
	{
		/** The passphrase of the party this client is in, or null when in none. */
		String passphrase();

		void changeParty(String passphrase);
	}

	enum State
	{
		/** "Sync with my group" is off: local data only. */
		OFF,
		/** No group key yet. */
		NO_KEY,
		/** Not logged in on a Group Ironman, so the group is not known. */
		NO_GROUP,
		/** Can join; waiting for the click. */
		READY,
		/** In this plugin's party for an older key: the key was changed or a new one arrived. */
		STALE,
		/** In a party the player joined themselves. */
		OTHER_PARTY,
		CONNECTED
	}

	private final Party party;
	/** The passphrase this plugin last joined, so shutdown leaves only that. */
	private String joined;

	GroupSync(Party party)
	{
		this.party = party;
	}

	/** The passphrase this group should use now, or null when it cannot be made yet. */
	static String target(boolean syncOn, String group, String key)
	{
		if (!syncOn || group == null || group.trim().isEmpty())
		{
			return null;
		}
		return GroupKey.passphrase(group, key);
	}

	State state(boolean syncOn, String group, String key)
	{
		if (!syncOn)
		{
			return State.OFF;
		}
		if (!GroupKey.isValid(key))
		{
			return State.NO_KEY;
		}
		String target = target(true, group, key);
		if (target == null)
		{
			return State.NO_GROUP;
		}
		String current = party.passphrase();
		if (current == null)
		{
			return State.READY;
		}
		if (current.equals(target))
		{
			return State.CONNECTED;
		}
		return ours(current) ? State.STALE : State.OTHER_PARTY;
	}

	/**
	 * The "Join group sync" click. Joins when not in a party or in this
	 * plugin's party for an old key; never leaves a party the player joined
	 * themselves (that is {@link #switchParty}). True when it joined.
	 */
	boolean join(boolean syncOn, String group, String key)
	{
		State s = state(syncOn, group, key);
		if (s != State.READY && s != State.STALE)
		{
			return false;
		}
		return change(target(syncOn, group, key));
	}

	/** The "Switch to group sync" click, shown only while in another party. */
	boolean switchParty(boolean syncOn, String group, String key)
	{
		if (state(syncOn, group, key) != State.OTHER_PARTY)
		{
			return false;
		}
		return change(target(syncOn, group, key));
	}

	/** Leaves the party only when it is the one this plugin joined. True when it left. */
	boolean leaveOwn()
	{
		String current = party.passphrase();
		if (joined == null || !joined.equals(current))
		{
			joined = null;
			return false;
		}
		joined = null;
		party.changeParty(null);
		return true;
	}

	/** Whether the party this client is in is one this plugin joined. */
	boolean inOwnParty()
	{
		return joined != null && joined.equals(party.passphrase());
	}

	private boolean change(String passphrase)
	{
		if (passphrase == null || Objects.equals(passphrase, party.passphrase()))
		{
			return false;
		}
		party.changeParty(passphrase);
		joined = passphrase;
		return true;
	}

	/** A GIM Utilities passphrase, for any key. */
	private static boolean ours(String passphrase)
	{
		return passphrase.startsWith("gimu:");
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;

/**
 * The leader's Discord webhooks, shared with the group (Board 2026-11-13: "Share webhooks with the group"). One
 * version, signed by the leader only (never an editor), carrying the seven webhooks' URLs and poster-name choices
 * while sharing is on, and nothing once it is turned off.
 *
 * <p><b>Who can read it.</b> Anyone in the group's party, which is anyone holding the group key: the same trust as
 * the key itself. It is never written into a member's RuneLite config, only kept in memory and in the group cache
 * file, and never logged: {@link #toString} names no URL.
 *
 * <p><b>Versions.</b> Each save is at least the previous version plus one, and at least the save time, so a leader
 * whose cache was lost still publishes a version newer than what members hold. Turning sharing off is a new version
 * with no webhooks, which is how members' copies are cleared on the next sync.
 */
final class GroupWebhooks
{
	/** Longer than any Discord webhook link; a longer field is dropped as not one. */
	static final int MAX_URL = 300;

	final String group;
	final long version;
	final long at;
	final String by;
	final String byKey;
	final boolean shared;
	/** Empty when not {@link #shared}; otherwise all seven, each URL a Discord webhook link or empty. */
	final Map<Webhook, Webhooks.Setting> settings;
	final String signature;

	GroupWebhooks(String group, long version, long at, String by, String byKey, boolean shared,
		Map<Webhook, Webhooks.Setting> settings, String signature)
	{
		this.group = group;
		this.version = version;
		this.at = at;
		this.by = by;
		this.byKey = byKey;
		this.shared = shared;
		Map<Webhook, Webhooks.Setting> s = new EnumMap<>(Webhook.class);
		if (shared)
		{
			s.putAll(settings);
		}
		this.settings = Collections.unmodifiableMap(s);
		this.signature = signature;
	}

	/**
	 * The version after {@code previous} (null for the first): {@code own}'s seven webhooks when {@code shared},
	 * none when not. Whether {@code by} may sign it is the caller's check ({@link GroupGovernance}).
	 */
	static GroupWebhooks next(GroupWebhooks previous, String group, boolean shared, Webhooks own, String by,
		GroupSigner.Identity id, long now)
	{
		Map<Webhook, Webhooks.Setting> s = new EnumMap<>(Webhook.class);
		if (shared)
		{
			for (Webhook w : Webhook.values())
			{
				s.put(w, clean(own.settings().get(w)));
			}
		}
		long version = Math.max(now, previous == null ? 1 : previous.version + 1);
		long at = previous == null ? now : Math.max(now, previous.at);
		GroupWebhooks unsigned = new GroupWebhooks(group, version, at, by, id.publicKey(), shared, s, "");
		return new GroupWebhooks(group, version, at, by, id.publicKey(), shared, s, id.sign(unsigned.canonical()));
	}

	/** A webhook as it travels: a URL only when it is a Discord webhook link, a name cut to Discord's limit. */
	static Webhooks.Setting clean(Webhooks.Setting s)
	{
		if (s == null)
		{
			return new Webhooks.Setting("", DiscordPosterName.WEBHOOK, "");
		}
		String url = s.url.length() <= MAX_URL && DiscordWebhook.valid(s.url) ? DiscordWebhook.clean(s.url) : "";
		return new Webhooks.Setting(url, s.mode, PosterNames.clean(s.name));
	}

	/** True when sharing {@code shared} with {@code own}'s webhooks would publish exactly what this holds. */
	boolean same(boolean shared, Webhooks own)
	{
		if (shared != this.shared)
		{
			return false;
		}
		if (!shared)
		{
			return true;
		}
		for (Webhook w : Webhook.values())
		{
			Webhooks.Setting mine = clean(own.settings().get(w));
			Webhooks.Setting held = settings.get(w);
			if (held == null || !mine.url.equals(held.url) || mine.mode != held.mode || !mine.name.equals(held.name))
			{
				return false;
			}
		}
		return true;
	}

	String canonical()
	{
		StringBuilder hooks = new StringBuilder();
		for (Map.Entry<Webhook, Webhooks.Setting> e : settings.entrySet())
		{
			Webhooks.Setting s = e.getValue();
			hooks.append(GroupSigner.canonical(e.getKey().name(), s.url, s.mode.name(), s.name));
		}
		return GroupSigner.canonical("gimu-webhooks", 1, group, version, at, by, byKey, shared ? 1 : 0, hooks);
	}

	/** Signed by the key it names; whether that key is the leader's is {@link GroupGovernance}'s check. */
	boolean verify()
	{
		return version >= 1 && !by.isEmpty() && GroupSigner.verify(byKey, canonical(), signature);
	}

	/** The total order every client uses to pick one document: version, then save time, then signature. */
	boolean newerThan(GroupWebhooks other)
	{
		return other == null || GroupSettings.newer(version, at, signature, other.version, other.at, other.signature);
	}

	@Override
	public String toString()
	{
		// Never a URL, even in a debug log.
		return "GroupWebhooks[v" + version + " by " + by + (shared ? ", shared" : ", not shared") + "]";
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;

/**
 * Skill levels from the OSRS hiscores for members who do not share their own (Board 2026-11-11): what the Group
 * tab shows for a member who never ran GIM Utilities. Shared plugin data always wins; the panel only reads this
 * when a member has no shared stats.
 *
 * <p>Looked up with RuneLite's own {@code HiscoreClient}, the lookup the base Hiscore plugin uses, never on the
 * client thread. Each member is looked up at most once every {@link #REFRESH_MS} (6 hours, Board), and only when
 * something asks: this player logging in, or the member coming online. A failed lookup is retried on its own,
 * after a backoff that doubles from {@link #FIRST_BACKOFF_MS} up to the same 6 hours, so a hiscore outage never
 * turns into a storm of requests.
 *
 * <p>Results are kept in the group cache, so a member's levels show across restarts with when they were read.
 * Failures are not kept: a restart starts the backoff over. Keyed by {@link GroupMembers#key}. Every method is
 * synchronized: lookups finish on OkHttp's threads, the panel reads on Swing's.
 */
final class HiscoreBook
{
	static final long REFRESH_MS = 6 * 60 * 60 * 1000L;
	static final long FIRST_BACKOFF_MS = 15 * 60 * 1000L;
	/** More skills than the game has, so a hostile cache file cannot grow the map without limit. */
	static final int MAX_SKILLS = 40;
	static final int MAX_LEVEL = 126;

	/** One successful lookup: when, and the level per skill as {@code Skill.getName()} spells it. */
	static final class Entry
	{
		final long at;
		final Map<String, Integer> levels;

		Entry(long at, Map<String, Integer> levels)
		{
			this.at = at;
			this.levels = Collections.unmodifiableMap(new LinkedHashMap<>(levels));
		}
	}

	private static final class Failure
	{
		final int count;
		final long at;

		Failure(int count, long at)
		{
			this.count = count;
			this.at = at;
		}
	}

	private final Map<String, Entry> entries = new HashMap<>();
	private final Map<String, Failure> failures = new HashMap<>();
	private final Set<String> inFlight = new HashSet<>();

	/**
	 * True, and the member marked as being looked up, when a lookup for {@code name} should start now.
	 * {@code asked}: this player just logged in or the member just came online. Without it only a failed
	 * lookup's retry can start.
	 */
	synchronized boolean begin(String name, long now, boolean asked)
	{
		String key = GroupMembers.key(name);
		if (key.isEmpty() || inFlight.contains(key))
		{
			return false;
		}
		Failure f = failures.get(key);
		boolean due = f != null ? now - f.at >= backoff(f.count) : asked && stale(entries.get(key), now);
		if (due)
		{
			inFlight.add(key);
		}
		return due;
	}

	private static boolean stale(Entry e, long now)
	{
		// A time in the future (a changed clock) counts as stale rather than blocking lookups for good.
		return e == null || now - e.at >= REFRESH_MS || now < e.at;
	}

	/** How long to wait after the {@code failures}th failure in a row: 15 min, 30 min, 1 h, ... at most 6 h. */
	static long backoff(int failures)
	{
		int doublings = Math.max(0, Math.min(failures - 1, 10));
		return Math.min(REFRESH_MS, FIRST_BACKOFF_MS << doublings);
	}

	synchronized void succeeded(String name, Map<String, Integer> levels, long now)
	{
		String key = GroupMembers.key(name);
		inFlight.remove(key);
		failures.remove(key);
		entries.put(key, new Entry(now, levels));
	}

	/** The lookup failed or the member is not on the hiscores. A level already read stays shown. */
	synchronized void failed(String name, long now)
	{
		String key = GroupMembers.key(name);
		inFlight.remove(key);
		Failure f = failures.get(key);
		failures.put(key, new Failure(f == null ? 1 : f.count + 1, now));
	}

	/** The last successful lookup for {@code name}, or null. */
	synchronized Entry entry(String name)
	{
		return entries.get(GroupMembers.key(name));
	}

	/** True when the last lookup for {@code name} failed. */
	synchronized boolean unavailable(String name)
	{
		return failures.containsKey(GroupMembers.key(name));
	}

	/** Every stored lookup, for the group cache. */
	synchronized Map<String, Entry> all()
	{
		return new TreeMap<>(entries);
	}

	/** From the group cache. Levels out of range, and skills past {@link #MAX_SKILLS}, are dropped. */
	synchronized void restore(String name, long at, Map<String, Integer> levels)
	{
		String key = GroupMembers.key(name);
		if (!key.isEmpty() && at > 0)
		{
			entries.put(key, new Entry(at, clean(levels)));
		}
	}

	synchronized void clear()
	{
		entries.clear();
		failures.clear();
		inFlight.clear();
	}

	static Map<String, Integer> clean(Map<String, Integer> levels)
	{
		Map<String, Integer> out = new LinkedHashMap<>();
		for (Map.Entry<String, Integer> e : levels.entrySet())
		{
			Integer level = e.getValue();
			if (out.size() < MAX_SKILLS && e.getKey() != null && level != null && level > 0 && level <= MAX_LEVEL)
			{
				out.put(e.getKey(), level);
			}
		}
		return out;
	}

	/**
	 * The skill levels in a hiscore result, named as {@code net.runelite.api.Skill.getName()} names them so they
	 * line up with shared stats. Unranked skills (level -1) are left out. Empty for a null result.
	 */
	static Map<String, Integer> levels(HiscoreResult result)
	{
		Map<String, Integer> out = new LinkedHashMap<>();
		if (result == null || result.getSkills() == null)
		{
			return out;
		}
		for (Map.Entry<HiscoreSkill, net.runelite.client.hiscore.Skill> e : result.getSkills().entrySet())
		{
			String name = skillName(e.getKey());
			if (name != null && e.getValue() != null)
			{
				out.put(name, e.getValue().getLevel());
			}
		}
		return clean(out);
	}

	private static String skillName(HiscoreSkill skill)
	{
		if (skill == null || skill.getType() != HiscoreSkillType.SKILL)
		{
			return null;
		}
		try
		{
			return net.runelite.api.Skill.valueOf(skill.name()).getName();
		}
		catch (IllegalArgumentException e)
		{
			// A skill the hiscores have and this client's API does not.
			return null;
		}
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonPrimitive;
import java.util.Collections;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.function.IntUnaryOperator;

/**
 * Item id to quantity, the one shape every group feature moves around.
 *
 * <p>Slots, tabs and order are deliberately thrown away: a bank snapshot, a
 * storage diff and a search all only care how many of each item there are.
 * Maps are sorted by id so two equal holdings encode to the same string.
 */
final class ItemCounts
{
	/** Ids above this are not items the game has; a peer sending one is broken. */
	static final int MAX_ITEM_ID = 1 << 20;

	private ItemCounts()
	{
	}

	/**
	 * Adds one slot to a tally, after mapping the id through {@code canonical}
	 * (noted to unnoted, placeholder to item). Empty slots, placeholders with
	 * quantity 0 and anything that canonicalises to an invalid id are skipped.
	 */
	static void add(Map<Integer, Integer> into, int id, int quantity, IntUnaryOperator canonical)
	{
		if (id <= 0 || quantity <= 0)
		{
			return;
		}
		int key = canonical.applyAsInt(id);
		if (key <= 0 || key >= MAX_ITEM_ID)
		{
			return;
		}
		into.merge(key, quantity, ItemCounts::saturatingAdd);
	}

	static int saturatingAdd(int a, int b)
	{
		long sum = (long) a + b;
		return sum > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) sum;
	}

	/** Every id in {@code maps}, for one batch of name lookups. */
	@SafeVarargs
	static Set<Integer> ids(Map<Integer, Integer>... maps)
	{
		Set<Integer> out = new TreeSet<>();
		for (Map<Integer, Integer> m : maps)
		{
			out.addAll(m.keySet());
		}
		return out;
	}

	static Map<Integer, Integer> sorted(Map<Integer, Integer> counts)
	{
		return Collections.unmodifiableMap(new TreeMap<>(counts));
	}

	/** {@code [id, qty, id, qty, ...]}, ascending by id. */
	static JsonArray toJson(Map<Integer, Integer> counts)
	{
		JsonArray out = new JsonArray();
		for (Map.Entry<Integer, Integer> e : new TreeMap<>(counts).entrySet())
		{
			out.add(e.getKey());
			out.add(e.getValue());
		}
		return out;
	}

	/**
	 * Reads a flat pair array from a peer. Bad pairs are dropped rather than
	 * failing the whole list, duplicates are summed, and at most {@code max}
	 * distinct items are kept.
	 */
	static Map<Integer, Integer> fromJson(JsonElement e, int max)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		if (e == null || !e.isJsonArray())
		{
			return out;
		}
		JsonArray array = e.getAsJsonArray();
		for (int i = 0; i + 1 < array.size(); i += 2)
		{
			Long id = longValue(array.get(i));
			Long qty = longValue(array.get(i + 1));
			if (id == null || qty == null || id <= 0 || id >= MAX_ITEM_ID || qty <= 0)
			{
				continue;
			}
			int key = id.intValue();
			if (!out.containsKey(key) && out.size() >= max)
			{
				continue;
			}
			int q = qty > Integer.MAX_VALUE ? Integer.MAX_VALUE : qty.intValue();
			out.merge(key, q, ItemCounts::saturatingAdd);
		}
		return out;
	}

	static Long longValue(JsonElement e)
	{
		if (e == null || !e.isJsonPrimitive() || !((JsonPrimitive) e).isNumber())
		{
			return null;
		}
		try
		{
			double d = e.getAsDouble();
			if (d != Math.floor(d) || Double.isInfinite(d))
			{
				return null;
			}
			return e.getAsLong();
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Monster drops for items the quest data does not name: the bundled {@code
 * item-drops.txt}, from the Old School RuneScape Wiki (see that file and
 * THIRD_PARTY_NOTICES.md). Without it a custom list's Dragon warhammer read "no
 * known shop or drop" though Lizardman shamans drop it (Board 2026-11-14).
 */
final class ItemDrops
{
	static final String RESOURCE = "item-drops.txt";
	private static final ItemDrops BUNDLED = parse(RegionNames.resource(RESOURCE));

	private final Map<Integer, List<ShopSources.Source>> drops;

	private ItemDrops(Map<Integer, List<ShopSources.Source>> drops)
	{
		this.drops = drops;
	}

	static ItemDrops bundled()
	{
		return BUNDLED;
	}

	/** The monsters that drop {@code itemId}, best rate first; empty when the table has none. */
	List<ShopSources.Source> of(int itemId)
	{
		return drops.getOrDefault(itemId, Collections.emptyList());
	}

	int size()
	{
		return drops.size();
	}

	/** "id|name|monster=rate|...", one item a line; "#" lines and anything malformed are skipped. */
	static ItemDrops parse(String text)
	{
		Map<Integer, List<ShopSources.Source>> out = new HashMap<>();
		for (String line : text.split("\n"))
		{
			String[] parts = line.trim().split("\\|");
			Integer id = line.trim().startsWith("#") || parts.length < 3 ? null : id(parts[0]);
			List<ShopSources.Source> sources = id == null ? Collections.emptyList() : sources(parts);
			if (!sources.isEmpty())
			{
				out.put(id, Collections.unmodifiableList(sources));
			}
		}
		return new ItemDrops(out);
	}

	private static Integer id(String text)
	{
		try
		{
			return Integer.parseInt(text.trim());
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** Every "monster=rate" after the id and name. */
	private static List<ShopSources.Source> sources(String[] parts)
	{
		List<ShopSources.Source> out = new ArrayList<>();
		for (int i = 2; i < parts.length; i++)
		{
			int eq = parts[i].indexOf('=');
			String monster = (eq < 0 ? parts[i] : parts[i].substring(0, eq)).trim();
			String rate = eq < 0 ? "" : parts[i].substring(eq + 1).trim();
			if (!monster.isEmpty())
			{
				out.add(new ShopSources.Source(false, monster, -1, rate));
			}
		}
		return out;
	}
}

package com.vinnyvangogh.groupironman;

/**
 * Item names and prices for the group panel.
 *
 * <p>An interface so the panel's text can be tested without an
 * {@code ItemManager}; the plugin's implementation answers from a cache it
 * fills on the client thread, because item compositions may only be read
 * there.
 */
interface ItemLookup
{
	/** The item's name, or a placeholder such as "item 1234" when it is not known yet. */
	String name(int id);

	/** Price per item in gp, 0 when unknown. */
	long price(int id);

	/** The equipment slot (EquipmentInventorySlot index) the item is worn in, or -1. */
	default int slot(int id)
	{
		return -1;
	}

	/**
	 * An item quantity or gp value as text: the game's "450K" here, the exact
	 * number or both through {@link Amounts#words}. Every line built from this
	 * lookup reads its amounts the same way.
	 */
	default String amount(long amount)
	{
		return Amounts.GAME.of(amount);
	}
}

package com.vinnyvangogh.groupironman;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;
import net.runelite.api.coords.WorldPoint;

/**
 * Where "Path to" sends the player for a shopping line or a requested item:
 * the shops this player can be served at that have a tile in the quest data
 * (the same {@link QuestData#shop} table the shop alert walks), and, when the
 * group holds some in group storage, the banks (group storage opens from the
 * regular bank interface: OSRS Wiki, "Group storage"). Nearest first from
 * where the player stands. Pure: the plugin captures the inputs.
 *
 * <p>Drops are never a target: the quest data names a monster's region, not a
 * tile. "Nearest" is the straight-line (Chebyshev) distance, as the game counts
 * steps; Shortest Path then finds the real way there, transports included.
 */
final class ItemPaths
{
	static final String BANKS_RESOURCE = "banks.tsv";
	/** Another floor costs this many tiles more: the stairs are rarely on the way. */
	static final int PLANE_COST = 50;

	private ItemPaths()
	{
	}

	/** One place to path to. */
	static final class Stop
	{
		final String name;
		final WorldPoint at;
		/** A bank, for an item in group storage. */
		final boolean bank;

		Stop(String name, WorldPoint at, boolean bank)
		{
			this.name = name;
			this.at = at;
			this.bank = bank;
		}

		/** "Path to: Varrock West bank". */
		String label()
		{
			return "Path to: " + name;
		}
	}

	/** What a path was asked for: one list line, a list's next stop, or one requested item. */
	static final class Target
	{
		enum Kind
		{
			LIST_ITEM, LIST_NEXT, REQUEST_ITEM
		}

		final Kind kind;
		final String id;
		final int itemId;

		private Target(Kind kind, String id, int itemId)
		{
			this.kind = kind;
			this.id = id;
			this.itemId = itemId;
		}

		static Target listItem(String listId, int itemId)
		{
			return new Target(Kind.LIST_ITEM, listId, itemId);
		}

		static Target next(String listId)
		{
			return new Target(Kind.LIST_NEXT, listId, 0);
		}

		static Target requestItem(String requestId, int itemId)
		{
			return new Target(Kind.REQUEST_ITEM, requestId, itemId);
		}

		@Override
		public boolean equals(Object o)
		{
			if (!(o instanceof Target))
			{
				return false;
			}
			Target t = (Target) o;
			return kind == t.kind && itemId == t.itemId && id.equals(t.id);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(kind, id, itemId);
		}
	}

	/** Everything a path is worked out from, captured once per redraw. */
	static final class Planner
	{
		final QuestData data;
		final ShopSources.Viewer viewer;
		final ShopAllocation.Holdings holdings;
		final List<Stop> banks;
		/** Where the player stands; null when logged out, and then the data's order stands. */
		final WorldPoint here;

		Planner(QuestData data, ShopSources.Viewer viewer, ShopAllocation.Holdings holdings, List<Stop> banks,
			WorldPoint here)
		{
			this.data = data;
			this.viewer = viewer;
			this.holdings = holdings;
			this.banks = banks;
			this.here = here;
		}

		static Planner of(ShoppingBoard.Inputs in, List<Stop> banks, WorldPoint here)
		{
			return new Planner(in.data, in.viewer, in.holdings, banks, here);
		}

		/** A list line: its shops while some is still to get, the banks while storage covers some. */
		List<Stop> shopping(ShoppingBoard.Row r)
		{
			List<Stop> out = new ArrayList<>();
			if (r.line.stillNeeded() > 0)
			{
				out.addAll(shops(r.sources));
			}
			if (r.line.storageUsed > 0)
			{
				out.addAll(banks);
			}
			return nearestFirst(out, here);
		}

		/** A requested item: nowhere once it is done or the request closed. */
		List<Stop> request(RequestList req, RequestBoard.Row r)
		{
			if (!req.open() || r.done())
			{
				return Collections.emptyList();
			}
			List<Stop> out = new ArrayList<>(shops(ShopSources.forViewer(data.item(r.itemId), viewer, data)));
			if (holdings.storage.getOrDefault(r.itemId, 0L) > 0)
			{
				out.addAll(banks);
			}
			return nearestFirst(out, here);
		}

		/** "Path to next": every line's stops, walked nearest-next from here. */
		List<Stop> next(ShoppingBoard.Card c)
		{
			List<List<Stop>> open = new ArrayList<>();
			for (ShoppingBoard.Row r : c.rows)
			{
				List<Stop> stops = shopping(r);
				if (!stops.isEmpty())
				{
					open.add(stops);
				}
			}
			return tour(open, here);
		}

		private List<Stop> shops(ShopSources.Options o)
		{
			List<Stop> out = new ArrayList<>();
			for (ShopSources.Source s : o.sources)
			{
				QuestData.Shop shop = s.shop ? data.shop(s.name) : null;
				// A shop the data gives no tile (0, 0) cannot be walked to.
				if (shop != null && (shop.x != 0 || shop.y != 0))
				{
					out.add(new Stop(s.name, new WorldPoint(shop.x, shop.y, shop.plane), false));
				}
			}
			return out;
		}
	}

	/** Where a target leads now; empty once its list, request or item is gone or done. */
	static List<Stop> forTarget(Target t, List<ShoppingBoard.Card> lists, List<RequestBoard.Card> requests,
		Planner p)
	{
		if (t.kind == Target.Kind.REQUEST_ITEM)
		{
			return forRequest(t, requests, p);
		}
		for (ShoppingBoard.Card c : lists)
		{
			if (c.list.id.equals(t.id))
			{
				return t.kind == Target.Kind.LIST_NEXT ? p.next(c) : forLine(t, c, p);
			}
		}
		return Collections.emptyList();
	}

	private static List<Stop> forLine(Target t, ShoppingBoard.Card c, Planner p)
	{
		for (ShoppingBoard.Row r : c.rows)
		{
			if (r.line.itemId == t.itemId)
			{
				return p.shopping(r);
			}
		}
		return Collections.emptyList();
	}

	private static List<Stop> forRequest(Target t, List<RequestBoard.Card> requests, Planner p)
	{
		for (RequestBoard.Card c : requests)
		{
			if (!c.request.id.equals(t.id))
			{
				continue;
			}
			for (RequestBoard.Row r : c.rows)
			{
				if (r.itemId == t.itemId)
				{
					return p.request(c.request, r);
				}
			}
		}
		return Collections.emptyList();
	}

	/** Steps from {@code from} to {@code to}, another floor costing {@link #PLANE_COST} more; 0 when not known. */
	static int cost(WorldPoint from, WorldPoint to)
	{
		if (from == null)
		{
			return 0;
		}
		int steps = Math.max(Math.abs(from.getX() - to.getX()), Math.abs(from.getY() - to.getY()));
		return steps + (from.getPlane() == to.getPlane() ? 0 : PLANE_COST);
	}

	/** Nearest first, each name once; the data's order breaks ties (and is all there is without a position). */
	static List<Stop> nearestFirst(List<Stop> stops, WorldPoint here)
	{
		Map<String, Stop> once = new LinkedHashMap<>();
		stops.forEach(s -> once.putIfAbsent(s.name, s));
		List<Stop> out = new ArrayList<>(once.values());
		out.sort(Comparator.comparingInt(s -> cost(here, s.at)));
		return out;
	}

	/**
	 * An efficient order through every line: the nearest stop any line can use,
	 * then the nearest from there, until each line has a stop. A stop serves
	 * every line it is a stop for. Greedy nearest-neighbour, not the shortest
	 * tour: good enough for a handful of shops, and it never sends the player
	 * past one stop to reach a farther one first.
	 */
	static List<Stop> tour(List<List<Stop>> lines, WorldPoint start)
	{
		List<List<Stop>> left = new ArrayList<>(lines);
		List<Stop> order = new ArrayList<>();
		WorldPoint from = start;
		while (!left.isEmpty())
		{
			Stop best = closest(left, from);
			order.add(best);
			left.removeIf(stops -> named(stops, best.name));
			from = best.at;
		}
		return order;
	}

	private static Stop closest(List<List<Stop>> lines, WorldPoint from)
	{
		Stop best = null;
		int bestCost = Integer.MAX_VALUE;
		for (List<Stop> stops : lines)
		{
			for (Stop s : stops)
			{
				int c = cost(from, s.at);
				if (c < bestCost)
				{
					best = s;
					bestCost = c;
				}
			}
		}
		return best;
	}

	static boolean named(List<Stop> stops, String name)
	{
		for (Stop s : stops)
		{
			if (s.name.equals(name))
			{
				return true;
			}
		}
		return false;
	}

	/** The bundled bank tiles; empty, never a failure, when the resource is missing. */
	static List<Stop> loadBanks()
	{
		try (InputStream in = ItemPaths.class.getResourceAsStream(BANKS_RESOURCE))
		{
			if (in == null)
			{
				return Collections.emptyList();
			}
			BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
			return parseBanks(reader.lines().collect(Collectors.toList()));
		}
		catch (IOException | UncheckedIOException e)
		{
			return Collections.emptyList();
		}
	}

	/** "x y plane&lt;TAB&gt;name" lines, '#' comments; a line that does not read is skipped. */
	static List<Stop> parseBanks(List<String> lines)
	{
		List<Stop> out = new ArrayList<>();
		for (String line : lines)
		{
			Stop s = bankLine(line);
			if (s != null)
			{
				out.add(s);
			}
		}
		return Collections.unmodifiableList(out);
	}

	private static Stop bankLine(String line)
	{
		String[] cols = line.split("\t");
		if (line.startsWith("#") || cols.length < 2)
		{
			return null;
		}
		String[] xyz = cols[0].trim().split(" ");
		try
		{
			return xyz.length != 3 ? null : new Stop(cols[1].trim() + " bank",
				new WorldPoint(Integer.parseInt(xyz[0]), Integer.parseInt(xyz[1]), Integer.parseInt(xyz[2])), true);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * The one item-name matcher behind both the panel's Find tab and
 * {@code ::find}, so the two can never disagree.
 *
 * <p>Case-insensitive. A name matches when it contains the whole query
 * ("guam" in "Grimy guam leaf"), or every word of it in any order ("leaf
 * grimy"), or what a common shorthand stands for ("ppot" for "Prayer
 * potion").
 */
final class ItemQuery
{
	/** Shorthand players type for items, each to the name text it stands for, from {@code item-aliases.txt}. */
	private static final Map<String, List<String>> ALIASES = new HashMap<>();

	static
	{
		for (String line : RegionNames.resource("item-aliases.txt").split("\n"))
		{
			int eq = line.indexOf('=');
			if (!line.startsWith("#") && eq > 0)
			{
				alias(line.substring(0, eq).trim(), line.substring(eq + 1).trim().split(","));
			}
		}
	}

	private final String whole;
	private final List<String> words;
	private final List<String> expansions;

	private ItemQuery(String whole)
	{
		this.whole = whole;
		List<String> w = new ArrayList<>();
		for (String part : whole.split("\\s+"))
		{
			if (!part.isEmpty())
			{
				w.add(part);
			}
		}
		this.words = Collections.unmodifiableList(w);
		List<String> x = ALIASES.get(whole);
		this.expansions = x == null ? Collections.emptyList() : x;
	}

	private static void alias(String shorthand, String... means)
	{
		List<String> list = new ArrayList<>();
		for (String m : means)
		{
			list.add(m.toLowerCase(Locale.ROOT));
		}
		ALIASES.put(shorthand, Collections.unmodifiableList(list));
	}

	/** Null when {@code text} is shorter than {@link GroupSearch#MIN_QUERY} once trimmed. */
	static ItemQuery parse(String text)
	{
		String q = normalize(text);
		return q.length() < GroupSearch.MIN_QUERY ? null : new ItemQuery(q);
	}

	static String normalize(String text)
	{
		return text == null ? "" : text.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
	}

	boolean matches(String itemName)
	{
		if (itemName == null)
		{
			return false;
		}
		String name = itemName.toLowerCase(Locale.ROOT).replace(' ', ' ');
		if (name.contains(whole))
		{
			return true;
		}
		for (String e : expansions)
		{
			if (name.contains(e))
			{
				return true;
			}
		}
		if (words.size() < 2)
		{
			return false;
		}
		for (String w : words)
		{
			if (!name.contains(w))
			{
				return false;
			}
		}
		return true;
	}

	/** The query as typed, normalized. */
	String text()
	{
		return whole;
	}
}

package com.vinnyvangogh.groupironman;

/**
 * When this client last saw a member online, and on which world: from their own client (the party), from this
 * player's own login, or from the game's Group channel for a member without the plugin. Kept in the group cache, so
 * the live board's "last seen" survives a restart. Immutable.
 */
final class LastSeen
{
	/** Epoch millis. */
	final long at;
	/** 0 when not known. */
	final int world;
	/** True once any sighting came from the member's own plugin client. */
	final boolean plugin;

	LastSeen(long at, int world, boolean plugin)
	{
		this.at = at;
		this.world = world;
		this.plugin = plugin;
	}

	/** The newer sighting's time and world (the older world when the newer has none); plugin once either had it. */
	static LastSeen merge(LastSeen a, LastSeen b)
	{
		LastSeen newer = b.at >= a.at ? b : a;
		LastSeen older = newer == b ? a : b;
		int world = newer.world > 0 ? newer.world : older.world;
		return new LastSeen(newer.at, world, a.plugin || b.plugin);
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.util.Collections;
import java.util.List;
import java.util.function.LongSupplier;
import java.util.function.Supplier;

/**
 * {@link LevelThreads}' decisions sent through the {@link DiscordSender}: a member's message's first post (kept by
 * its message id), its owed edits, and the new post that replaces a message Discord no longer has. Any thread.
 */
final class LevelPosts extends EditedPosts
{
	/** 'Combine level-ups' before Board 2026-11-14 made it 60: what an install that had the plugin keeps. */
	static final int OLD_DEFAULT_WINDOW = 30;

	private final LevelThreads threads;
	private final DiscordSender sender;
	private final Gson gson;
	private final Supplier<DiscordStyle> style;
	/** The Progress poster name ({@link PosterNames}); null for the webhook's own. */
	private final Supplier<String> poster;

	LevelPosts(DiscordSender sender, Gson gson, LongSupplier clock, Supplier<DiscordStyle> style,
		Supplier<String> poster)
	{
		this(new LevelThreads(), sender, gson, clock, style, poster);
	}

	private LevelPosts(LevelThreads threads, DiscordSender sender, Gson gson, LongSupplier clock,
		Supplier<DiscordStyle> style, Supplier<String> poster)
	{
		super(threads, clock);
		this.threads = threads;
		this.sender = sender;
		this.gson = gson;
		this.style = style;
		this.poster = poster;
	}

	/**
	 * The 'Combine level-ups' value to write once for this install, or null to leave it: an install that ran the
	 * plugin before ({@code upgrading}) and never set the value keeps the old default, so only new installs get 60
	 * (Board 2026-11-14). A value already stored, whatever it is, is the member's own and stays.
	 */
	static Integer windowToKeep(boolean upgrading, String stored)
	{
		return upgrading && stored == null ? OLD_DEFAULT_WINDOW : null;
	}

	/** One level-up into its member's message; see {@link #level(String, List, long, byte[], String)}. */
	void level(String url, GroupEvent level, long window, byte[] png, String firstJson)
	{
		level(url, Collections.singletonList(level), window, png, firstJson);
	}

	/**
	 * One moment's level-ups, all of one member, into that member's message. A new message with one card posts
	 * {@code firstJson} (the usual post for the moment, with its Easter egg and where it was) when there is one;
	 * one with more cards posts the cards. A joined one is edited by {@link #tick} in time.
	 */
	void level(String url, List<GroupEvent> levels, long window, byte[] png, String firstJson)
	{
		LevelThreads.Edit fresh = threads.level(levels, url, clock.getAsLong(), window, png);
		if (fresh != null)
		{
			post(fresh, fresh.cards.size() == 1 && firstJson != null ? firstJson : cards(fresh));
		}
	}

	/** Once a second: the edits owed now. */
	void tick()
	{
		for (LevelThreads.Edit edit : threads.due(clock.getAsLong()))
		{
			String json = DiscordWebhook.levelsEdit(gson, edit.member, edit.cards, style.get(), edit.png != null);
			sender.edit(edit.url, edit.messageId, json, edit.png, (status, id) -> refused(edit, status));
		}
	}

	private void refused(LevelThreads.Edit edit, int status)
	{
		LevelThreads.Edit again = threads.edited(edit.streak, status);
		if (again != null)
		{
			post(again, cards(again));
		}
	}

	/** The message as a new post: every card, under the Progress poster name. */
	private String cards(LevelThreads.Edit m)
	{
		return DiscordWebhook.levels(gson, m.member, m.cards, style.get(), m.png != null, poster.get());
	}

	private void post(LevelThreads.Edit m, String json)
	{
		if (json == null)
		{
			threads.posted(m.streak, 0, null, clock.getAsLong());
			return;
		}
		sender.post(m.url, json, m.png, (status, id) -> threads.posted(m.streak, status, id, clock.getAsLong()));
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * When a level-up's screenshot is taken (Board 2026-11-11): not the moment the level registers, which shows the
 * chatbox before "Congratulations, you've just advanced your Smithing level. You are now level 4." lands, but once
 * that line for the level is in, or {@link #WAIT} after the level-up, whichever is first. A second level of the
 * skill while one waits joins it, so both posts get the newer frame, but never past {@link #MAX_WAIT} after the
 * first. Pure and clock-driven; client thread only.
 */
final class LevelShot
{
	/** How long after the level-up a shot waits for its chat line. */
	static final long WAIT = 2_000;
	/** The longest any shot waits, however many levels join it. */
	static final long MAX_WAIT = 3_000;

	/** "Congratulations, you've just advanced your Smithing level. You are now level 4." */
	private static final Pattern ADVANCED = Pattern.compile(
		"^Congratulations, you've just advanced (?:your|a|an) (.+?) level\\. You are now level (\\d+)\\.?$");

	/** One skill's shot to take and the sends waiting for its frame. */
	static final class Held
	{
		final String skill;
		final long first;
		long level;
		long due;
		final List<Consumer<byte[]>> sends = new ArrayList<>();

		private Held(String skill, long first)
		{
			this.skill = skill;
			this.first = first;
		}
	}

	/** Waiting shots, by skill. */
	private final Map<String, Held> held = new HashMap<>();
	/** The highest level each skill's chat line has shown, and when. */
	private final Map<String, long[]> seen = new HashMap<>();

	/**
	 * A level-up's post, ready but for its picture: {@code send} gets the frame once the chat shows the level (or
	 * the wait is over). {@code at} is when the level registered.
	 */
	void hold(String skill, long level, long at, Consumer<byte[]> send)
	{
		String key = key(skill);
		Held h = held.get(key);
		if (h == null)
		{
			h = new Held(key, at);
			held.put(key, h);
		}
		h.level = Math.max(h.level, level);
		h.due = Math.min(Math.max(h.due, at + WAIT), h.first + MAX_WAIT);
		h.sends.add(send);
	}

	/** A game message: true when it was a level-up line, now seen. */
	boolean chat(String message, long now)
	{
		Matcher m = ADVANCED.matcher(EventText.plain(message));
		if (!m.matches())
		{
			return false;
		}
		String key = key(m.group(1));
		long level = Long.parseLong(m.group(2));
		long[] was = seen.get(key);
		if (was == null || level >= was[0])
		{
			seen.put(key, new long[]{level, now});
		}
		return true;
	}

	/** The shots to take now, removed: their chat line is in, or their wait is over. */
	List<Held> due(long now)
	{
		List<Held> out = new ArrayList<>();
		for (Iterator<Held> it = held.values().iterator(); it.hasNext(); )
		{
			Held h = it.next();
			if (now >= h.due || shown(h))
			{
				out.add(h);
				it.remove();
			}
		}
		// A line older than any wait can no longer belong to a level still to come.
		seen.values().removeIf(s -> now - s[1] > MAX_WAIT);
		return out;
	}

	/** Every waiting shot, removed: no more ticks are coming (a hop or a logout). */
	List<Held> drain()
	{
		List<Held> out = new ArrayList<>(held.values());
		held.clear();
		seen.clear();
		return out;
	}

	/** Shutdown: nothing is sent. */
	void clear()
	{
		held.clear();
		seen.clear();
	}

	private boolean shown(Held h)
	{
		long[] s = seen.get(h.skill);
		return s != null && s[0] >= h.level;
	}

	/** Skill names compared as the chat spells them: the event's "Runecraft" is the chat's "Runecrafting". */
	private static String key(String skill)
	{
		String k = skill.toLowerCase(Locale.ROOT);
		return k.equals("runecrafting") ? "runecraft" : k;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Set;
import java.util.concurrent.TimeUnit;

/**
 * A member's level-ups, one Discord message (Board 2026-11-14, final design): the message holds one embed card per
 * skill, and each card is edited in place on that skill's next level ("Thieving 44 → 46 (+2) in 10 min"). A new
 * skill adds a card; combat level is a card of its own. Cards are ordered by the most recent level-up first. A
 * message holds at most {@link #MAX_CARDS} cards (Discord's limit on embeds); a skill past that starts a new message.
 *
 * <p>How the message is posted, edited, refused, ended at a logout and kept across a restart is
 * {@link EditedThreads}'; this class says what a level adds to it. A saved line has every card's state.
 */
final class LevelThreads extends EditedThreads<LevelThreads.Streak, LevelThreads.Edit>
{
	private static final int MAX_LEVEL = 99;
	/** A combat level's card name: "Combat 99 → 101 (+2) in 10 min". */
	static final String COMBAT = "Combat";
	private static final String SEP = "\t";
	/** Marks a saved line of this format; a line saved by an earlier build is dropped. */
	private static final String VERSION = "L2";
	/** version, hook, member, first, last, message id; then each card's {@link Card#fields}. */
	private static final int HEAD_FIELDS = 6;
	private static final int CARD_FIELDS = 7;

	/** One skill's card in a message: its levels from the level before its first to its latest, and when. */
	static final class Card
	{
		final String skill;
		final long from;
		long to;
		final long firstAt;
		long lastAt;
		/** Level-ups it holds: one reads as the plain line, more as the span. */
		int ups;
		/** Read from the game's group broadcast: the footer says so. */
		boolean broadcast;

		private Card(String skill, long from, long to, long at, boolean broadcast)
		{
			this.skill = skill;
			this.from = from;
			this.to = to;
			this.firstAt = at;
			this.lastAt = at;
			this.ups = 1;
			this.broadcast = broadcast;
		}

		/** A saved card ({@link #fields}). */
		private Card(String[] f, int i)
		{
			if (f[i].isEmpty())
			{
				throw new NumberFormatException("no skill");
			}
			this.skill = f[i];
			this.from = Long.parseLong(f[i + 1]);
			this.to = Long.parseLong(f[i + 2]);
			this.firstAt = Long.parseLong(f[i + 3]);
			this.lastAt = Long.parseLong(f[i + 4]);
			this.ups = Integer.parseInt(f[i + 5]);
			this.broadcast = "1".equals(f[i + 6]);
		}

		private Card copy()
		{
			Card c = new Card(skill, from, to, firstAt, broadcast);
			c.lastAt = lastAt;
			c.ups = ups;
			return c;
		}

		boolean combat()
		{
			return COMBAT.equals(skill);
		}

		/** "Thieving level 45" for its first level; then "Thieving 44 → 46 (+2) in 10 min". */
		String text()
		{
			if (ups <= 1)
			{
				return combat() ? "combat level " + to : skill + " level " + to;
			}
			return LevelThreads.text(skill, from, to, lastAt - firstAt);
		}

		private void fields(List<String> f)
		{
			Collections.addAll(f, skill, Long.toString(from), Long.toString(to), Long.toString(firstAt),
				Long.toString(lastAt), Integer.toString(ups), broadcast ? "1" : "0");
		}
	}

	/** One member's message and its cards. Read and written only under the owner's lock. */
	static final class Streak extends EditedThreads.Message
	{
		/** Its cards, the most recently levelled first. */
		final List<Card> cards = new ArrayList<>();

		private Streak(String member, String url, long now, byte[] png)
		{
			super(member, url, now, png);
		}

		/** A saved streak ({@link #line}) back after a restart: posted, not busy, its next level an edit. */
		private Streak(String[] f)
		{
			super(f[1], f[2], Long.parseLong(f[3]), Long.parseLong(f[4]), f[5]);
			for (int i = HEAD_FIELDS; i < f.length; i += CARD_FIELDS)
			{
				cards.add(new Card(f, i));
			}
		}

		/** Whether a moment joins this message: same webhook, inside the window, and room for its cards. */
		private boolean joins(List<GroupEvent> events, String url, long now, long window)
		{
			return open(url, now, window) && fits(events);
		}

		/** A moment's levels into this message; true when any was new, and the message is then owed an edit. */
		private boolean join(List<GroupEvent> events, String url, long now, byte[] picture)
		{
			boolean grew = false;
			for (GroupEvent e : events)
			{
				grew |= add(e, now);
			}
			if (grew)
			{
				grew(url, now, picture);
			}
			return grew;
		}

		/** Whether {@code events} fit: the cards they would add stay within {@link #MAX_CARDS}. */
		private boolean fits(List<GroupEvent> events)
		{
			Set<String> skills = new HashSet<>();
			for (Card c : cards)
			{
				skills.add(c.skill);
			}
			for (GroupEvent e : events)
			{
				skills.add(skill(e));
			}
			return skills.size() <= MAX_CARDS;
		}

		/**
		 * A level into this message: its card moves to the top with the level raised, or a new card goes on top.
		 * True when it is a level the message did not hold yet (a repeat or an older level changes nothing).
		 */
		private boolean add(GroupEvent e, long now)
		{
			String skill = skill(e);
			for (Iterator<Card> i = cards.iterator(); i.hasNext(); )
			{
				Card c = i.next();
				if (c.skill.equals(skill))
				{
					if (e.number <= c.to)
					{
						return false;
					}
					i.remove();
					c.to = e.number;
					c.lastAt = now;
					c.ups++;
					c.broadcast = e.broadcast;
					cards.add(0, c);
					return true;
				}
			}
			// One action can gain several levels (low Prayer): the level before it, when the event knows it.
			cards.add(0, new Card(skill, e.previous > 0 ? e.previous : e.number - 1, e.number, now, e.broadcast));
			return true;
		}
	}

	/** What one post or edit of a message says, frozen when it is handed out: safe to read off the lock. */
	static final class Edit
	{
		final Streak streak;
		final String url;
		final String messageId;
		final String member;
		/** Copies of the message's cards, the most recently levelled first. */
		final List<Card> cards;
		final byte[] png;

		private Edit(Streak s)
		{
			this.streak = s;
			this.url = s.url;
			this.messageId = s.messageId;
			this.member = s.member;
			List<Card> copies = new ArrayList<>();
			for (Card c : s.cards.subList(0, Math.min(MAX_CARDS, s.cards.size())))
			{
				copies.add(c.copy());
			}
			this.cards = Collections.unmodifiableList(copies);
			this.png = s.png;
		}
	}

	/**
	 * The levels a plugin user's own moment is, when it can share their message: only skill level-ups below 99 and
	 * combat levels, in any number of skills (Board 2026-11-14: grouped per member). Null for anything else (a 99, a
	 * total level, an XP milestone in the same moment): that moment posts as it always has.
	 */
	static List<GroupEvent> combinable(List<GroupEvent> events)
	{
		if (events.isEmpty())
		{
			return null;
		}
		for (GroupEvent e : events)
		{
			if (!levelCard(e))
			{
				return null;
			}
		}
		return events;
	}

	/**
	 * A level the game's group broadcast read for a member without the plugin ({@link GroupBroadcasts}), when it can
	 * share a message: a skill's level below 99, or a combat level (Board 2026-11-14: "group levels should follow
	 * the same pattern too"). Null for anything else, and for a plugin user's own event, which {@link #combinable}
	 * decides. Only the client that posts the broadcast keeps the streak, so a new poster starts a new message.
	 */
	static GroupEvent combinableBroadcast(GroupEvent e)
	{
		return e != null && e.broadcast && levelCard(e) ? e : null;
	}

	/** A skill's level below 99, or a combat level: what a card is made of. */
	private static boolean levelCard(GroupEvent e)
	{
		return e.type == GroupEvent.Type.LEVEL_UP && e.number < MAX_LEVEL || e.type == GroupEvent.Type.COMBAT_LEVEL;
	}

	/** What a level is of: the skill, or "Combat" for a combat level (which names no skill). */
	private static String skill(GroupEvent e)
	{
		return e.type == GroupEvent.Type.COMBAT_LEVEL ? COMBAT : e.text;
	}

	/** One level; see {@link #level(List, String, long, long, byte[])}. */
	synchronized Edit level(GroupEvent e, String url, long now, long window, byte[] png)
	{
		return level(Collections.singletonList(e), url, now, window, png);
	}

	/**
	 * One moment's levels, all of one member, within {@code window} ms of that member's message's first post and
	 * with room for their cards: join it (null back; {@link #due} edits it in time). Otherwise a new message, its
	 * first post returned: send it and report back to {@link #posted} with {@link Edit#streak}.
	 */
	synchronized Edit level(List<GroupEvent> events, String url, long now, long window, byte[] png)
	{
		String member = events.get(0).member;
		Streak s = open.get(member);
		if (s != null && s.joins(events, url, now, window))
		{
			changed |= s.join(events, url, now, png);
			return null;
		}
		Streak fresh = new Streak(member, url, now, png);
		for (GroupEvent e : events)
		{
			fresh.add(e, now);
		}
		return start(fresh);
	}

	@Override
	String key(Streak s)
	{
		return s.member;
	}

	@Override
	Edit snapshot(Streak s)
	{
		return new Edit(s);
	}

	/** version, hook, member, first, last, message id, then each card; tab-separated. */
	@Override
	String line(Streak s)
	{
		List<String> f = new ArrayList<>();
		Collections.addAll(f, VERSION, s.hook, s.member, Long.toString(s.first), Long.toString(s.last), s.messageId);
		for (Card c : s.cards)
		{
			c.fields(f);
		}
		return String.join(SEP, f);
	}

	@Override
	Streak parse(String line)
	{
		String[] f = line.split(SEP, -1);
		int cards = (f.length - HEAD_FIELDS) / CARD_FIELDS;
		if (!VERSION.equals(f[0]) || cards < 1 || cards > MAX_CARDS
			|| (f.length - HEAD_FIELDS) % CARD_FIELDS != 0 || f[5].isEmpty())
		{
			return null;
		}
		try
		{
			return new Streak(f);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** "Prayer 23 → 25 (+2) in 4 min". */
	static String text(String skill, long from, long to, long spanMs)
	{
		return skill + ' ' + from + " → " + to + " (+" + (to - from) + ") " + span(spanMs);
	}

	private static String span(long ms)
	{
		long minutes = TimeUnit.MILLISECONDS.toMinutes(ms);
		if (minutes < 1)
		{
			return "in under a minute";
		}
		return minutes < 60 ? "in " + minutes + " min" : "in " + minutes / 60 + " h " + minutes % 60 + " min";
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import java.util.function.Predicate;

/**
 * The safety net under {@link LoginGate}: a login's first minute holds the events {@code counts} picks instead of
 * posting them. When the minute ends, a handful is posted as usual; more than that is the old account's or the
 * chat history's backlog read as new (Board 2026-11-15: an account switch posted four old diaries and three old
 * levels), and nothing is posted. Client thread only.
 */
final class LoginBurst
{
	/** How long after a login events are held. */
	static final long WINDOW_MS = TimeUnit.MINUTES.toMillis(1);
	/** Most held events still posted; one more and the whole minute is dropped. */
	static final int MAX_POSTS = 3;
	/** This player's own kinds a login could replay: progress, the collection log, counts and bests, Slayer. */
	static final Set<GroupEvent.Type> ACHIEVEMENTS = achievements();

	private final Predicate<GroupEvent.Type> counts;
	private final List<GroupEvent> held = new ArrayList<>();
	private long until;
	private int dropped;

	LoginBurst(Predicate<GroupEvent.Type> counts)
	{
		this.counts = counts;
	}

	private static Set<GroupEvent.Type> achievements()
	{
		Set<GroupEvent.Type> kinds = EnumSet.noneOf(GroupEvent.Type.class);
		for (GroupEvent.Type t : GroupEvent.Type.values())
		{
			if (t.category == GroupEvent.Category.PROGRESS)
			{
				kinds.add(t);
			}
		}
		kinds.addAll(EnumSet.of(GroupEvent.Type.CLOG, GroupEvent.Type.PERSONAL_BEST, GroupEvent.Type.KC_MILESTONE,
			GroupEvent.Type.SLAYER));
		return Collections.unmodifiableSet(kinds);
	}

	/** A login (or a new account) starts a minute; what is already held stays counted in it. */
	void open(long now)
	{
		until = now + WINDOW_MS;
	}

	/** True when {@code event} is held: one {@code counts} picks, inside a login's first minute. */
	boolean hold(GroupEvent event, long now)
	{
		if (now >= until || !counts.test(event.type))
		{
			return false;
		}
		held.add(event);
		return true;
	}

	/** Once the minute is over: what was held when it stayed a handful, nothing when it was a burst. */
	List<GroupEvent> due(long now)
	{
		if (now < until || held.isEmpty())
		{
			return Collections.emptyList();
		}
		List<GroupEvent> out = new ArrayList<>(held);
		held.clear();
		if (out.size() > MAX_POSTS)
		{
			dropped += out.size();
			return Collections.emptyList();
		}
		return out;
	}

	/** The session is over (logout, hop): the minute ends now. */
	List<GroupEvent> end()
	{
		until = 0;
		return due(0);
	}

	/** How many held events were dropped as a burst since the last call; for the log. */
	int takeDropped()
	{
		int n = dropped;
		dropped = 0;
		return n;
	}
}

package com.vinnyvangogh.groupironman;

import net.runelite.api.GameState;

/**
 * Whose values the progress baselines hold, and when they count. Nothing earned before this login ever posts
 * (Board 2026-11-15, after an account switch posted the other account's old diaries and levels to Discord):
 *
 * <ul>
 * <li>Every state that is not in the game ({@link #endsSession}: the login screen, logging in, a hop, a lost
 * connection) forgets every baseline. The reset runs first, before anything else the engine does then, so nothing
 * that throws on the way out can skip it.</li>
 * <li>A different account than the one baselined (its hash, from any event that reads it) forgets them too, so a
 * switch the game states never show still starts over.</li>
 * <li>After a login, variables wait {@link #VAR_WAIT_TICKS}, and until {@link #SETTLE_TICKS} every value (skills,
 * total, combat level, quest points, diaries) only records: the game's login burst, and a value it sends a few
 * ticks late, is never read as progress.</li>
 * </ul>
 * <p>{@link LoginBurst} is the net under all of this. Client thread only.
 */
final class LoginGate
{
	/** Ticks after a login before variables are read: the login's burst of values has settled by then. */
	static final int VAR_WAIT_TICKS = 5;
	/** Ticks after a login before any value counts as progress: about 9 seconds. */
	static final int SETTLE_TICKS = 15;
	/** {@code Client.getAccountHash()} when logged out. */
	static final long NO_ACCOUNT = -1;

	private final ProgressTracker progress;
	private final EventWatchers watchers;
	private final LoginBurst own;
	private final LoginBurst broadcasts;
	private long account = NO_ACCOUNT;
	private int varWait = -1;
	private int settle = -1;

	LoginGate(ProgressTracker progress, EventWatchers watchers, LoginBurst own, LoginBurst broadcasts)
	{
		this.progress = progress;
		this.watchers = watchers;
		this.own = own;
		this.broadcasts = broadcasts;
	}

	/** Every state but in the game: the next values may be another account's. */
	static boolean endsSession(GameState state)
	{
		return state != GameState.LOGGED_IN && state != GameState.LOADING;
	}

	/**
	 * Out of the game: every baseline starts over, and nothing is read until the next login. The watchers keep what
	 * is not a baseline (a grave's timer survives a hop); the engine resets them fully at the login screen.
	 */
	void startOver()
	{
		forget();
		account = NO_ACCOUNT;
		varWait = -1;
		settle = -1;
	}

	/** In the game, the profile changed: start over as if this were a new login. */
	void rebaseline(long now)
	{
		forget();
		begin(now);
	}

	private void forget()
	{
		progress.reset();
		watchers.rebaseline();
	}

	/**
	 * The account the client is logged in as now ({@code NO_ACCOUNT} when none: logged out, or a login still in
	 * progress). A different one than the baselines hold forgets them and starts a new login's wait; true then. No
	 * account after one was known is a session's end, whatever the game states said.
	 */
	boolean account(long hash, long now)
	{
		if (hash == account)
		{
			return false;
		}
		if (hash == NO_ACCOUNT)
		{
			startOver();
			return false;
		}
		boolean switched = account != NO_ACCOUNT;
		account = hash;
		if (switched)
		{
			// Another account: nothing the last one was in the middle of is this one's.
			progress.reset();
			watchers.reset();
		}
		if (switched || varWait < 0)
		{
			begin(now);
		}
		return switched;
	}

	/** The first tick of a login, with the player loaded. A login already begun keeps its wait. */
	void login(long now)
	{
		if (varWait < 0)
		{
			begin(now);
		}
	}

	private void begin(long now)
	{
		progress.quiet();
		watchers.quiet();
		varWait = VAR_WAIT_TICKS;
		settle = SETTLE_TICKS;
		own.open(now);
		broadcasts.open(now);
	}

	/** Each tick while logged in. True when variables may be read this tick. */
	boolean tick()
	{
		if (settle > 0 && --settle == 0)
		{
			progress.settle();
			watchers.settle();
		}
		if (varWait > 0)
		{
			varWait--;
			return false;
		}
		return varWait == 0;
	}

	/** Values are counted as progress again (the login's quiet ticks are over). */
	boolean settled()
	{
		return settle <= 0 && varWait == 0;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Group storage minimums the player typed in, and which of them a storage
 * close has just left short.
 *
 * <p>Text is one rule per line or comma, "Shark: 100". Items are matched by
 * name, case-insensitively, summing every id with that name, so the rule does
 * not care which dose or charge variant is stored under which id. An item
 * missing from storage counts as 0.
 *
 * <p>Each rule alerts once when it drops below its minimum and stays quiet
 * until storage is back at or above it, so every later visit does not repeat
 * the same notification.
 */
final class LowStock
{
	static final class Alert
	{
		final String item;
		final int have;
		final int minimum;

		Alert(String item, int have, int minimum)
		{
			this.item = item;
			this.have = have;
			this.minimum = minimum;
		}

		String message()
		{
			return "Group storage is low on " + item + ": " + Amounts.GAME.of(have) + " left, minimum "
				+ Amounts.GAME.of(minimum);
		}
	}

	static final int MAX_RULES = 50;

	private final Map<String, Integer> minimums;
	private final Map<String, String> displayNames;
	private final Set<String> alerted = new HashSet<>();

	private LowStock(Map<String, Integer> minimums, Map<String, String> displayNames)
	{
		this.minimums = minimums;
		this.displayNames = displayNames;
	}

	/** Lines that do not read as "name: number" with a positive number are ignored. */
	static LowStock parse(String text)
	{
		Map<String, Integer> minimums = new LinkedHashMap<>();
		Map<String, String> names = new LinkedHashMap<>();
		if (text != null)
		{
			for (String raw : text.split("[\\n,]"))
			{
				int colon = raw.lastIndexOf(':');
				if (colon <= 0 || minimums.size() >= MAX_RULES)
				{
					continue;
				}
				String name = raw.substring(0, colon).trim();
				String number = raw.substring(colon + 1).trim();
				int min;
				try
				{
					min = Integer.parseInt(number);
				}
				catch (NumberFormatException e)
				{
					continue;
				}
				if (name.isEmpty() || min <= 0)
				{
					continue;
				}
				String key = name.toLowerCase(Locale.ROOT);
				minimums.put(key, min);
				names.put(key, name);
			}
		}
		return new LowStock(minimums, names);
	}

	boolean isEmpty()
	{
		return minimums.isEmpty();
	}

	/** Rules newly below their minimum after this storage state. Updates which rules have alerted. */
	synchronized List<Alert> check(Map<Integer, Integer> storage, ItemLookup items)
	{
		Map<String, Integer> byName = new LinkedHashMap<>();
		for (Map.Entry<Integer, Integer> e : storage.entrySet())
		{
			String name = items.name(e.getKey()).toLowerCase(Locale.ROOT);
			byName.merge(name, e.getValue(), ItemCounts::saturatingAdd);
		}
		List<Alert> out = new ArrayList<>();
		for (Map.Entry<String, Integer> rule : minimums.entrySet())
		{
			int have = byName.getOrDefault(rule.getKey(), 0);
			if (have >= rule.getValue())
			{
				alerted.remove(rule.getKey());
			}
			else if (alerted.add(rule.getKey()))
			{
				out.add(new Alert(displayNames.get(rule.getKey()), have, rule.getValue()));
			}
		}
		return out;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Objects;
import java.util.Map;

/**
 * The item stores that are neither bank, inventory nor equipment: the rune
 * pouch, Dizana's quiver and the seed vault.
 *
 * <p>The rune pouch and quiver are read from varbits the game keeps current,
 * so they are always live. The seed vault is only known after this member has
 * opened it, so it carries its own "last seen" time, -1 when never seen; a
 * receiver keeps the vault it already knows rather than replacing it with an
 * unknown one ({@link GroupRoster#putExtras}).
 */
final class MemberExtras
{
	final Map<Integer, Integer> runePouch;
	final Map<Integer, Integer> quiver;
	final Map<Integer, Integer> seedVault;
	final long seedVaultAt;

	MemberExtras(Map<Integer, Integer> runePouch, Map<Integer, Integer> quiver, Map<Integer, Integer> seedVault,
		long seedVaultAt)
	{
		this.runePouch = ItemCounts.sorted(runePouch);
		this.quiver = ItemCounts.sorted(quiver);
		this.seedVault = ItemCounts.sorted(seedVault);
		this.seedVaultAt = seedVaultAt < 0 ? -1 : seedVaultAt;
	}

	MemberExtras withSeedVault(Map<Integer, Integer> vault, long at)
	{
		return new MemberExtras(runePouch, quiver, vault, at);
	}

	boolean isEmpty()
	{
		return runePouch.isEmpty() && quiver.isEmpty() && seedVault.isEmpty() && seedVaultAt < 0;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof MemberExtras))
		{
			return false;
		}
		MemberExtras m = (MemberExtras) o;
		return runePouch.equals(m.runePouch) && quiver.equals(m.quiver) && seedVault.equals(m.seedVault)
			&& seedVaultAt == m.seedVaultAt;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(runePouch, quiver, seedVault, seedVaultAt);
	}
}

package com.vinnyvangogh.groupironman;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

/**
 * Online members as markers on the game's world map, from the position in
 * their shared stats. Off unless the player turns on "Show members on world
 * map"; only members heard from in the last few minutes are drawn.
 *
 * <p>This is the in-game world map, not a map in the side panel: the client
 * has no map image a plugin can draw from without downloading tiles, and this
 * plugin makes no network calls.
 */
class MemberMapMarkers
{
	private static final BufferedImage DOT = dot();

	@Inject
	private WorldMapPointManager manager;

	private final Map<String, WorldMapPoint> points = new HashMap<>();

	/** Replaces the markers with {@code online}, leaving out {@code self}: the map already shows you. */
	synchronized void update(Map<String, MemberStats> online, String self)
	{
		Iterator<Map.Entry<String, WorldMapPoint>> it = points.entrySet().iterator();
		while (it.hasNext())
		{
			Map.Entry<String, WorldMapPoint> e = it.next();
			MemberStats s = online.get(e.getKey());
			if (s == null || !s.hasPosition() || !e.getValue().getWorldPoint().equals(at(s)))
			{
				manager.remove(e.getValue());
				it.remove();
			}
		}
		for (Map.Entry<String, MemberStats> e : online.entrySet())
		{
			if (points.containsKey(e.getKey()) || !e.getValue().hasPosition() || e.getKey().equalsIgnoreCase(self))
			{
				continue;
			}
			WorldMapPoint point = WorldMapPoint.builder()
				.worldPoint(at(e.getValue()))
				.image(DOT)
				.name(e.getKey())
				.tooltip(e.getKey())
				.snapToEdge(true)
				.jumpOnClick(true)
				.build();
			manager.add(point);
			points.put(e.getKey(), point);
		}
	}

	synchronized void clear()
	{
		for (WorldMapPoint point : points.values())
		{
			manager.remove(point);
		}
		points.clear();
	}

	private static WorldPoint at(MemberStats s)
	{
		return new WorldPoint(s.x(), s.y(), s.plane());
	}

	/** A 10x10 orange dot with a dark rim, drawn rather than shipped. */
	private static BufferedImage dot()
	{
		BufferedImage image = new BufferedImage(10, 10, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(0x2B, 0x2B, 0x2B));
		g.fillOval(0, 0, 10, 10);
		g.setColor(new Color(0xD4, 0x8A, 0x1E));
		g.fillOval(2, 2, 6, 6);
		g.dispose();
		return image;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;
import java.util.StringJoiner;

/**
 * One member's own opt-outs, applied on top of the group's settings and never
 * overridden by them: "Don't post my events", per-kind "don't post", and
 * overlay mutes.
 *
 * <p>"Post" means this member's own events to Discord (instant and digest):
 * the only posts a client ever makes. Overlay mutes hide a kind's banner on
 * this client only. The two posting choices travel in the member's announce so
 * the leader and editors can see a read-only grid; mutes stay local.
 */
final class MemberPrefs
{
	static final MemberPrefs NONE = new MemberPrefs(false, EnumSet.noneOf(GroupEvent.Type.class),
		EnumSet.noneOf(GroupEvent.Type.class));

	/** "Don't post my events": nothing of this member's goes to Discord. */
	final boolean all;
	final Set<GroupEvent.Type> noPost;
	final Set<GroupEvent.Type> mute;

	MemberPrefs(boolean all, Set<GroupEvent.Type> noPost, Set<GroupEvent.Type> mute)
	{
		this.all = all;
		this.noPost = Collections.unmodifiableSet(copy(noPost));
		this.mute = Collections.unmodifiableSet(copy(mute));
	}

	static MemberPrefs of(GroupIronmanConfig config)
	{
		return new MemberPrefs(config.eventOptOutAll(), parse(config.eventOptOutTypes()),
			parse(config.overlayMuteTypes()));
	}

	/** Whether this member's own events of {@code type} may be posted. */
	boolean posts(GroupEvent.Type type)
	{
		return !all && !noPost.contains(type);
	}

	/** Kinds by wire code, comma separated; unknown codes are skipped. */
	static Set<GroupEvent.Type> parse(String codes)
	{
		Set<GroupEvent.Type> out = EnumSet.noneOf(GroupEvent.Type.class);
		if (codes == null)
		{
			return out;
		}
		for (String code : codes.split(","))
		{
			GroupEvent.Type t = GroupEvent.Type.of(code.trim());
			if (t != null)
			{
				out.add(t);
			}
		}
		return out;
	}

	static String format(Set<GroupEvent.Type> types)
	{
		StringJoiner out = new StringJoiner(",");
		for (GroupEvent.Type t : copy(types))
		{
			out.add(t.code);
		}
		return out.toString();
	}

	private static Set<GroupEvent.Type> copy(Set<GroupEvent.Type> types)
	{
		return types.isEmpty() ? EnumSet.noneOf(GroupEvent.Type.class) : EnumSet.copyOf(types);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * A member's live state: real and boosted level per skill, run energy,
 * special attack, world and a coarse location.
 *
 * <p>Hitpoints and Prayer are not separate fields: current HP is the boosted
 * Hitpoints level and current prayer the boosted Prayer level, which is how
 * the game itself stores them.
 */
final class MemberStats
{
	/** Real and boosted level. */
	static final class Level
	{
		final int real;
		final int boosted;

		Level(int real, int boosted)
		{
			this.real = real;
			this.boosted = boosted;
		}

		@Override
		public boolean equals(Object o)
		{
			return o instanceof Level && ((Level) o).real == real && ((Level) o).boosted == boosted;
		}

		@Override
		public int hashCode()
		{
			return real * 1000 + boosted;
		}
	}

	private final Map<String, Level> skills;
	private final int runEnergy;
	private final int specialAttack;
	private final int world;
	private final int region;
	private final int x;
	private final int y;
	private final int plane;

	/** Without a position: what a part 2 sender sends. */
	MemberStats(Map<String, Level> skills, int runEnergy, int specialAttack, int world, int region)
	{
		this(skills, runEnergy, specialAttack, world, region, 0, 0, 0);
	}

	/**
	 * @param runEnergy percent, 0 to 100
	 * @param specialAttack percent, 0 to 100
	 * @param region the 64x64 map region id, or 0 when unknown
	 * @param x world tile x, or 0 when unknown (also inside instances, the real-world tile)
	 */
	MemberStats(Map<String, Level> skills, int runEnergy, int specialAttack, int world, int region, int x, int y,
		int plane)
	{
		this.skills = Collections.unmodifiableMap(new LinkedHashMap<>(skills));
		this.runEnergy = runEnergy;
		this.specialAttack = specialAttack;
		this.world = world;
		this.region = region;
		this.x = x;
		this.y = y;
		this.plane = plane;
	}

	int x()
	{
		return x;
	}

	int y()
	{
		return y;
	}

	int plane()
	{
		return plane;
	}

	boolean hasPosition()
	{
		return x > 0 && y > 0;
	}

	Map<String, Level> skills()
	{
		return skills;
	}

	int runEnergy()
	{
		return runEnergy;
	}

	int specialAttack()
	{
		return specialAttack;
	}

	int world()
	{
		return world;
	}

	int region()
	{
		return region;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof MemberStats))
		{
			return false;
		}
		MemberStats m = (MemberStats) o;
		return skills.equals(m.skills) && runEnergy == m.runEnergy && specialAttack == m.specialAttack
			&& world == m.world && region == m.region && x == m.x && y == m.y && plane == m.plane;
	}

	@Override
	public int hashCode()
	{
		return skills.hashCode() * 31 + runEnergy * 7 + specialAttack * 13 + world * 17 + region + x * 19 + y * 23
			+ plane;
	}
}

package com.vinnyvangogh.groupironman;

/**
 * How Discord hears about logins and logouts (Board 2026-11-10). Public, like every setting type: RuneLite reads
 * settings through a proxy that cannot see a package-private type (ConfigKeysTest).
 */
public enum OnlineStatus
{
	/** A post for each login and logout, with the offline grace. */
	POSTS("Posts"),
	/** One message in the Group channel, edited as members log in, log out or hop ({@link StatusBoard}). */
	LIVE_BOARD("Live board"),
	OFF("Off");

	private final String label;

	OnlineStatus(String label)
	{
		this.label = label;
	}

	/**
	 * What an install that had the older "Online and offline" switch keeps, the first time this setting exists:
	 * posts when it posted them, nothing when it used Discord without them. Null for an install that never used
	 * Discord, which takes the default, posts (Board 2026-11-10: a member opts into the live board).
	 */
	static OnlineStatus upgrading(boolean postedOnline, boolean usedDiscord)
	{
		if (postedOnline)
		{
			return POSTS;
		}
		return usedDiscord ? OFF : null;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

