	/** One titled icon grid inside a member card: "Worn", "Inventory", "Rune pouch", "Quiver". */
	static final class ItemGroup
	{
		final String title;
		final List<ItemCell> items;

		ItemGroup(String title, List<ItemCell> items)
		{
			this.title = title;
			this.items = items;
		}
	}

	static final class MemberCard
	{
		final String name;
		final boolean you;
		final boolean online;
		/** "Online - W302, Lumbridge" or "Offline - last seen W303, Draynor, 2h ago". */
		final String status;
		final List<Bar> bars;
		final List<SkillCell> skills;
		final List<ItemGroup> items;
		/** "Seed vault: 12 kinds, 340 seeds (seen 3d ago)", or null. */
		final String seedVault;
		/**
		 * Where the stats came from when the member shares none: "From hiscores, 2h ago", "Hiscores unavailable",
		 * or null for shared stats or nothing at all.
		 */
		final String source;

		MemberCard(String name, boolean you, boolean online, String status, List<Bar> bars, List<SkillCell> skills,
			List<ItemGroup> items, String seedVault, String source)
		{
			this.name = name;
			this.you = you;
			this.online = online;
			this.status = status;
			this.bars = bars;
			this.skills = skills;
			this.items = items;
			this.seedVault = seedVault;
			this.source = source;
		}
	}

	static final String FROM_HISCORES = "from hiscores";
	static final String ASSUMED = "assumed, not shared";

	static final class BankCard
	{
		final String member;
		/** "812 items, 45.2M gp, seen 2h ago". */
		final String summary;
		/** {@link #summary} with every digit, for its tooltip: "812 items, 45,201,337 gp, seen 2h ago". */
		final String exact;
		final long value;
		final List<ItemCell> items;

		BankCard(String member, String summary, String exact, long value, List<ItemCell> items)
		{
			this.member = member;
			this.summary = summary;
			this.exact = exact;
			this.value = value;
			this.items = items;
		}
	}

	static final class LogRow
	{
		/** "You deposited 5 Trout" or "Alex took 40K Coins". */
		final String text;
		/** {@link #text} with every digit, for its tooltip: "Alex took 40,000 Coins". */
		final String exact;
		final String ago;

		LogRow(String text, String exact, String ago)
		{
			this.text = text;
			this.exact = exact;
			this.ago = ago;
		}
	}

	static final class StorageView
	{
		/** "Last seen 3m ago, after You saved", or null when storage was never opened. */
		final String snapshot;
		final long value;
		final List<ItemCell> items;
		final List<LogRow> log;

		StorageView(String snapshot, long value, List<ItemCell> items, List<LogRow> log)
		{
			this.snapshot = snapshot;
			this.value = value;
			this.items = items;
			this.log = log;
		}
	}

	static final class FindRow
	{
		final int itemId;
		/** The stack's size, so the icon is the game's own pile for it. */
		final long quantity;
		/** "Coins - 450K in group storage". */
		final String text;
		/** {@link #text} with every digit: "Coins - 450,001 in group storage". */
		final String tooltip;
		/** "2h ago", or "" for live data. */
		final String ago;

		FindRow(int itemId, long quantity, String text, String tooltip, String ago)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.text = text;
			this.tooltip = tooltip;
			this.ago = ago;
		}
	}

	private PanelModel()
	{
	}

	/**
	 * One card per member: the in-game roster first, then anyone else this
	 * client holds data for, in {@link #MEMBER_ORDER}. Offline members keep
	 * their last stats and items.
	 */
	static List<MemberCard> members(GroupRoster group, Collection<String> roster, RegionNames regions, ItemLookup items,
		String self, long now)
	{
		return members(group, roster, regions, items, self, GamePresence.UNKNOWN, now);
	}

	/**
	 * As above, with online and world from the game's Group channel ({@link GamePresence}) where it knows them,
	 * so members without the plugin show too; party data still fills everything else.
	 */
	static List<MemberCard> members(GroupRoster group, Collection<String> roster, RegionNames regions, ItemLookup items,
		String self, GamePresence game, long now)
	{
		Map<String, MemberStats> stats = group.allStats();
		Map<String, GroupCodec.Carried> carried = group.allCarried();
		Map<String, MemberExtras> extras = group.extras();
		Map<String, Long> heard = group.lastHeard();

		Set<String> names = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
		names.addAll(roster);
		names.addAll(stats.keySet());
		names.addAll(carried.keySet());
		names.addAll(heard.keySet());

		List<MemberCard> out = new ArrayList<>();
		for (String name : names)
		{
			boolean you = name.equalsIgnoreCase(self);
			long at = heard.getOrDefault(name, 0L);
			GamePresence.State g = game.state(name);
			boolean online = g == GamePresence.State.ONLINE || g == GamePresence.State.UNKNOWN && Presence.online(at, now);
			MemberStats s = stats.get(name);
			String st = status(s, at, g, game.world(name), regions, now);
			List<ItemGroup> held = itemGroups(carried.get(name), extras.get(name), items);
			String vault = seedVault(extras.get(name), now);
			out.add(s != null
				? new MemberCard(name, you, online, st, bars(s), skills(s), held, vault, null)
				: fromHiscores(name, you, online, st, held, vault, group.hiscores(), now));
		}
		out.sort(MEMBER_ORDER);
		return out;
	}

	/**
	 * You, then members online, then offline and never-seen ones, each by name (Board 2026-11-13). Online is the
	 * card's own: the game's Group channel where it knows, plugin presence otherwise.
	 */
	static final Comparator<MemberCard> MEMBER_ORDER = Comparator.comparing((MemberCard c) -> !c.you)
		.thenComparing(c -> !c.online)
		.thenComparing(c -> c.name, String.CASE_INSENSITIVE_ORDER);

	/**
	 * A member who shares no stats: their levels from the hiscores, when looked up. Online, HP and Prayer show
	 * full at their hiscore level and Run and Spec at an assumed 100%, dimmed (Board 2026-11-11). Offline, levels
	 * only. Items are whatever they shared before, or none: nothing is made up.
	 */
	private static MemberCard fromHiscores(String name, boolean you, boolean online, String status,
		List<ItemGroup> held, String vault, HiscoreBook hiscores, long now)
	{
		HiscoreBook.Entry h = hiscores.entry(name);
		List<Bar> bars = h != null && online ? hiscoreBars(h) : new ArrayList<>();
		List<SkillCell> skills = new ArrayList<>();
		if (h != null)
		{
			Map<String, MemberStats.Level> levels = new TreeMap<>();
			h.levels.forEach((skill, level) -> levels.put(skill, new MemberStats.Level(level, level)));
			skills = skills(new MemberStats(levels, 0, 0, 0, 0));
		}
		return new MemberCard(name, you, online, status, bars, skills, held, vault,
			hiscoreSource(h, hiscores.unavailable(name), now));
	}

	static List<Bar> hiscoreBars(HiscoreBook.Entry h)
	{
		List<Bar> out = new ArrayList<>();
		Integer hp = h.levels.get("Hitpoints");
		Integer prayer = h.levels.get("Prayer");
		if (hp != null)
		{
			out.add(new Bar("HP", hp, hp, false, FROM_HISCORES));
		}
		if (prayer != null)
		{
			out.add(new Bar("Prayer", prayer, prayer, false, FROM_HISCORES));
		}
		out.add(new Bar("Run", 100, 100, true, ASSUMED));
		out.add(new Bar("Spec", 100, 100, true, ASSUMED));
		return out;
	}

	/** "From hiscores, 2h ago", with " (hiscores unavailable)" after a failed refresh; null when neither. */
	static String hiscoreSource(HiscoreBook.Entry h, boolean unavailable, long now)
	{
		if (h == null)
		{
			return unavailable ? "Hiscores unavailable" : null;
		}
		return "From hiscores, " + BoostText.ago(now, h.at) + (unavailable ? " (hiscores unavailable)" : "");
	}

	/**
	 * The card's line with the game's word on it: online on the game's world when only the game says so, offline
	 * when the game says so, and " (no plugin)" for a member whose client never reported.
	 */
	private static String status(MemberStats s, long heardAt, GamePresence.State game, int gameWorld,
		RegionNames regions, long now)
	{
		String tag = heardAt > 0 || s != null ? "" : " (no plugin)";
		boolean heard = Presence.online(heardAt, now);
		if (game == GamePresence.State.ONLINE && !heard)
		{
			return (gameWorld > 0 ? "Online - W" + gameWorld : "Online") + tag;
		}
		if (game == GamePresence.State.OFFLINE)
		{
			return heardAt > 0 ? status(s, heardAt, false, regions, now) : "Offline" + tag;
		}
		return status(s, heardAt, heard, regions, now);
	}

	static String status(MemberStats s, long heardAt, boolean online, RegionNames regions, long now)
	{
		String where = where(s, regions);
		if (online)
		{
			return where.isEmpty() ? "Online" : "Online - " + where;
		}
		if (heardAt <= 0)
		{
			return "Not seen yet";
		}
		return "Offline - last seen " + (where.isEmpty() ? "" : where + ", ") + BoostText.ago(now, heardAt);
	}

	/** "W302, Lumbridge", "W302", or "". */
	private static String where(MemberStats s, RegionNames regions)
	{
		if (s == null)
		{
			return "";
		}
		List<String> parts = new ArrayList<>();
		if (s.world() > 0)
		{
			parts.add("W" + s.world());
		}
		String place = regions.describe(s.region());
		if (place != null)
		{
			parts.add(place);
		}
		return String.join(", ", parts);
	}

	static List<Bar> bars(MemberStats s)
	{
		List<Bar> out = new ArrayList<>();
		if (s == null)
		{
			return out;
		}
		MemberStats.Level hp = s.skills().get("Hitpoints");
		MemberStats.Level prayer = s.skills().get("Prayer");
		if (hp != null)
		{
			out.add(new Bar("HP", hp.boosted, hp.real));
		}
		if (prayer != null)
		{
			out.add(new Bar("Prayer", prayer.boosted, prayer.real));
		}
		out.add(new Bar("Run", s.runEnergy(), 100));
		out.add(new Bar("Spec", s.specialAttack(), 100));
		return out;
	}

	/** In the skills tab's order; skills this build does not know go last. */
	static List<SkillCell> skills(MemberStats s)
	{
		List<SkillCell> out = new ArrayList<>();
		if (s == null)
		{
			return out;
		}
		Map<String, MemberStats.Level> left = new TreeMap<>(s.skills());
		for (String name : SKILL_ORDER)
		{
			MemberStats.Level l = left.remove(name);
			if (l != null)
			{
				out.add(new SkillCell(name, l.real, l.boosted));
			}
		}
		for (Map.Entry<String, MemberStats.Level> e : left.entrySet())
		{
			out.add(new SkillCell(e.getKey(), e.getValue().real, e.getValue().boosted));
		}
		return out;
	}

	private static List<ItemGroup> itemGroups(GroupCodec.Carried c, MemberExtras x, ItemLookup items)
	{
		List<ItemGroup> out = new ArrayList<>();
		if (c != null)
		{
			addGroup(out, "Worn", c.worn, items);
			if (c.slots.isEmpty() || c.inventory.isEmpty())
			{
				// A sender from before slots: one cell per item, as before.
				addGroup(out, "Inventory", c.inventory, items);
			}
			else
			{
				out.add(new ItemGroup("Inventory", slotCells(c, items)));
			}
		}
		if (x != null)
		{
			addGroup(out, "Rune pouch", x.runePouch, items);
			addGroup(out, "Quiver", x.quiver, items);
		}
		return out;
	}

	private static void addGroup(List<ItemGroup> out, String title, Map<Integer, Integer> counts, ItemLookup items)
	{
		if (!counts.isEmpty())
		{
			out.add(new ItemGroup(title, cells(counts, items, null, false)));
		}
	}

	/** One cell per slot in the game's order, {@link ItemCell#EMPTY} for an empty one; noted ids stay noted. */
	/** A known container's contents go on its slot (Board 2026-11-14); unknown draws no number. */
	static List<ItemCell> slotCells(GroupCodec.Carried c, ItemLookup items)
	{
		List<ItemCell> out = new ArrayList<>();
		for (GroupCodec.Slot s : c.slots)
		{
			if (s.empty())
			{
				out.add(ItemCell.EMPTY);
				continue;
			}
			String name = items.name(s.id);
			out.add(new ItemCell(s.id, name, s.quantity, items.price(s.id) * s.quantity,
				c.inside(SkillingContainer.fromItemName(name))));
		}
		return out;
	}

	private static String seedVault(MemberExtras x, long now)
	{
		if (x == null || x.seedVaultAt < 0)
		{
			return null;
		}
		long seeds = 0;
		for (int n : x.seedVault.values())
		{
			seeds += n;
		}
		return "Seed vault: " + x.seedVault.size() + " kinds, " + Amounts.GAME.of(seeds) + " seeds (seen "
			+ BoostText.ago(now, x.seedVaultAt) + ")";
	}

	/**
	 * Icon cells for {@code counts}, only the ones whose name matches
	 * {@code filter} when it is a query, in container order or, with
	 * {@code byValue}, most valuable stack first.
	 */
	static List<ItemCell> cells(Map<Integer, Integer> counts, ItemLookup items, String filter, boolean byValue)
	{
		ItemQuery q = ItemQuery.parse(filter);
		List<ItemCell> out = new ArrayList<>();
		for (Map.Entry<Integer, Integer> e : counts.entrySet())
		{
			String name = items.name(e.getKey());
			if (q == null || q.matches(name))
			{
				out.add(new ItemCell(e.getKey(), name, e.getValue(), items.price(e.getKey()) * e.getValue()));
			}
		}
		if (byValue)
		{
			out.sort(Comparator.comparingLong((ItemCell c) -> -c.value).thenComparing(c -> c.name));
		}
		return out;
	}

	private static long total(Map<Integer, Integer> counts, ItemLookup items)
	{
		long value = 0;
		for (Map.Entry<Integer, Integer> e : counts.entrySet())
		{
			value += items.price(e.getKey()) * e.getValue();
		}
		return value;
	}

	/** One card per member's last bank, sorted by name, each grid most valuable first and filtered by {@code filter}. */
	static List<BankCard> banks(GroupRoster group, ItemLookup items, String filter, long now)
	{
		List<BankCard> out = new ArrayList<>();
		for (Map.Entry<String, BankSnapshot> e : group.banks().entrySet())
		{
			Map<Integer, Integer> bank = e.getValue().items();
			long count = 0;
			for (int n : bank.values())
			{
				count += n;
			}
			long value = total(bank, items);
			String seen = " gp, seen " + BoostText.ago(now, e.getValue().takenAt());
			String summary = Amounts.GAME.of(count) + " items, " + Amounts.GAME.of(value) + seen;
			String exact = Amounts.EXACT.of(count) + " items, " + Amounts.EXACT.of(value) + seen;
			out.add(new BankCard(e.getKey(), summary, exact, value, cells(bank, items, filter, true)));
		}
		return out;
	}

	/** The last storage contents as seen, with when and by whom, and the change log as lines. */
	static StorageView storage(GroupRoster group, ItemLookup items, String self, String filter, long now)
	{
		List<LogRow> log = new ArrayList<>();
		for (StorageChange c : group.log().entries())
		{
			log.add(new LogRow(change(c, items, self), change(c, Amounts.EXACT.words(items), self),
				BoostText.ago(now, c.at())));
		}
		long at = group.storageAt();
		if (at < 0)
		{
			return new StorageView(null, 0, Collections.emptyList(), log);
		}
		String by = group.storageBy();
		String snapshot = "Last seen " + BoostText.ago(now, at)
			+ (by.isEmpty() ? "" : ", by " + (by.equalsIgnoreCase(self) ? "you" : by));
		Map<Integer, Integer> contents = group.storageItems();
		return new StorageView(snapshot, total(contents, items), cells(contents, items, filter, true), log);
	}

	/**
	 * "You deposited 5 Trout", "Alex took 2 Shark, deposited 100 Coal", and "You took 4 Prayer potion(4) (not
	 * shared: Share group storage changes is off)" for an own visit kept to this client.
	 */
	static String change(StorageChange c, ItemLookup items, String self)
	{
		List<String> parts = new ArrayList<>();
		if (!c.took().isEmpty())
		{
			parts.add("took " + counts(c.took(), items));
		}
		if (!c.deposited().isEmpty())
		{
			parts.add("deposited " + counts(c.deposited(), items));
		}
		String who = c.member().equalsIgnoreCase(self) ? "You" : c.member();
		return who + " " + String.join(", ", parts) + (c.shared() ? "" : " (" + StorageChange.NOT_SHARED + ")");
	}

	/** "5 Trout, 40K Coins", amounts in {@code items}' style. */
	static String counts(Map<Integer, Integer> counts, ItemLookup items)
	{
		List<String> parts = new ArrayList<>();
		for (Map.Entry<Integer, Integer> e : counts.entrySet())
		{
			parts.add(items.amount(e.getValue()) + " " + items.name(e.getKey()));
		}
		return String.join(", ", parts);
	}

	/** "Grimy guam leaf 15 - GroupShip bank", one row per item and place. */
	static List<FindRow> find(String query, GroupRoster group, ItemLookup items, long now)
	{
		return find(query, group, items, now, "");
	}

	/** Rows read from your side: "Trout - 15 in your bank", "Trout - 140 in group storage". */
	static List<FindRow> find(String query, GroupRoster group, ItemLookup items, long now, String self)
	{
		FindStyle words = new FindStyle(self, null, null, null, null, null, null);
		List<FindRow> out = new ArrayList<>();
		for (GroupSearch.Hit h : GroupSearch.hits(query, group.searchSources(), items))
		{
			out.add(new FindRow(h.itemId, h.quantity, h.name + " - " + words.place(h, Amounts.GAME),
				h.name + " - " + words.place(h, Amounts.EXACT), h.seenAt < 0 ? "" : BoostText.ago(now, h.seenAt)));
		}
		return out;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Function;

/**
 * The one path this plugin asked Shortest Path for, and what it was for. The
 * panel's buttons start it ({@link #go}) and stop it ({@link #stop}); each
 * redraw {@link #recheck}s it, so the path goes away by itself once the item is
 * done, its list is removed or the request closes, and "Path to next" moves on
 * to the next stop once the current one has nothing left to get.
 *
 * <p>Any thread: the panel calls it from Swing, redraws come from several
 * threads, and the bridge hands every post to the client thread itself.
 */
final class PathSession
{
	private final ShortestPathBridge bridge;
	private ItemPaths.Target target;
	private ItemPaths.Stop stop;

	PathSession(ShortestPathBridge bridge)
	{
		this.bridge = bridge;
	}

	/** Paths to {@code to} for {@code why}; the line the panel shows either way. */
	synchronized String go(ItemPaths.Target why, ItemPaths.Stop to, boolean located)
	{
		if (!located)
		{
			return "Log in first: the path starts where you stand.";
		}
		ShortestPathBridge.Availability a = bridge.availability();
		if (a != ShortestPathBridge.Availability.AVAILABLE)
		{
			return unavailable(a);
		}
		if (!send(to))
		{
			return "Shortest Path did not take the path: update it, or try again.";
		}
		target = why;
		stop = to;
		return to.label() + ".";
	}

	/** Clears the path; "Path cleared." or empty when there was none. */
	synchronized String stop()
	{
		if (target == null)
		{
			return "";
		}
		bridge.clear();
		forget();
		return "Path cleared.";
	}

	/**
	 * Checks the path against where its target leads now ({@code stops},
	 * nearest first). Still a stop for it: left alone, even if another is now
	 * nearer, so walking never re-routes. Not any more: the nearest remaining
	 * stop, or cleared when there is none.
	 *
	 * @return whether the path changed
	 */
	synchronized boolean recheck(Function<ItemPaths.Target, List<ItemPaths.Stop>> stops)
	{
		if (target == null)
		{
			return false;
		}
		List<ItemPaths.Stop> now = stops.apply(target);
		if (now == null)
		{
			now = Collections.emptyList();
		}
		if (ItemPaths.named(now, stop.name))
		{
			return false;
		}
		if (!now.isEmpty() && send(now.get(0)))
		{
			stop = now.get(0);
			return true;
		}
		bridge.clear();
		forget();
		return true;
	}

	/** The stop being pathed to; empty for none. */
	synchronized String active()
	{
		return stop == null ? "" : stop.name;
	}

	static String unavailable(ShortestPathBridge.Availability a)
	{
		switch (a)
		{
			case NOT_INSTALLED:
				return a.menuLabel() + ": get it from the Plugin Hub to path to items.";
			case NOT_ENABLED:
				return a.menuLabel() + ": turn it on in the plugin list to path to items.";
			default:
				return a.menuLabel() + ".";
		}
	}

	private boolean send(ItemPaths.Stop to)
	{
		AtomicReference<ShortestPathBridge.RouteOutcome> out = new AtomicReference<>();
		bridge.route(Collections.singleton(to.at), out::set);
		return out.get() == ShortestPathBridge.RouteOutcome.SENT;
	}

	private void forget()
	{
		target = null;
		stop = null;
	}
}

package com.vinnyvangogh.groupironman;

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardCopyOption;
import net.runelite.client.util.Filepath;

/**
 * The plugin's own files in its data directory (.runelite/plugin-data/gim-utilities), written the moment they
 * change. Unlike the RuneLite config, which keeps a change in memory and writes it every five minutes or at a
 * clean shutdown, a file written here survives the client being killed a second later.
 */
final class PluginFiles
{
	private PluginFiles()
	{
	}

	/** {@code file}'s text, or null when there is no such file. */
	static String read(Filepath file) throws IOException
	{
		if (!file.isFile())
		{
			return null;
		}
		try (InputStream in = file.openInputStream())
		{
			return new String(in.readAllBytes(), StandardCharsets.UTF_8);
		}
	}

	/** Writes a temp file beside {@code file}, then moves it over, so a crash never leaves half a file. */
	static void write(Filepath file, String text, String tempPrefix) throws IOException
	{
		Filepath dir = file.getParent();
		dir.createDirectories();
		Filepath tmp = dir.createTempFile(tempPrefix, ".tmp");
		try
		{
			try (OutputStream out = tmp.openOutputStream())
			{
				out.write(text.getBytes(StandardCharsets.UTF_8));
			}
			tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
		}
		finally
		{
			tmp.deleteIfExists();
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * The rules a Custom poster name must meet ({@link Webhooks#name} decides which name a post uses).
 *
 * <p>Discord's Execute Webhook takes a username of 1 to 80 characters and answers 400 to the names in
 * {@link #refused}, so a longer name is cut to 80 and a refused one is never sent: the post goes out under that
 * webhook's default name and the player gets one chat line naming the field, never the name. Pure, so the rules
 * and the once-only warning are tested.
 */
final class PosterNames
{
	/** Discord's limit on a webhook username. */
	static final int MAX = 80;
	private static final String[] REFUSED = {"discord", "clyde", "@", "#", ":", "```"};
	private static final List<String> EXACT = Arrays.asList("everyone", "here");

	/** Field label to the refused name already warned about. In memory only, never shown or logged. */
	private final Map<String, String> warned = new HashMap<>();

	/** Trimmed and cut to {@link #MAX} characters, never through a surrogate pair. Empty for null. */
	static String clean(String name)
	{
		String s = name == null ? "" : name.trim();
		if (s.length() > MAX)
		{
			int end = Character.isHighSurrogate(s.charAt(MAX - 1)) ? MAX - 1 : MAX;
			s = s.substring(0, end).trim();
		}
		return s;
	}

	/**
	 * Discord answers 400 to a webhook username containing "discord", "clyde", '@', '#', ':' or "```", or one
	 * that is exactly "everyone" or "here" (any case, checked after {@link #clean}).
	 */
	static boolean refused(String name)
	{
		String lower = name.toLowerCase(Locale.ROOT);
		if (EXACT.contains(lower))
		{
			return true;
		}
		for (String part : REFUSED)
		{
			if (lower.contains(part))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The chat lines to show now: one per Custom box (label to name, {@link Webhooks#customNames}) whose name
	 * Discord would refuse, once per name. A box that is cleared, fixed or no longer on Custom is forgotten, so
	 * breaking it again warns again.
	 */
	synchronized List<String> check(Map<String, String> fields)
	{
		List<String> out = new ArrayList<>();
		for (Map.Entry<String, String> field : fields.entrySet())
		{
			String value = clean(field.getValue());
			if (!refused(value))
			{
				warned.remove(field.getKey());
			}
			else if (!value.equals(warned.put(field.getKey(), value)))
			{
				out.add(message(field.getKey()));
			}
		}
		return out;
	}

	static String message(String label)
	{
		return GroupIronmanPlugin.NAME + ": the " + label + " Discord custom name can't contain 'discord', 'clyde',"
			+ " @, #, : or ```, or be 'everyone' or 'here'; posts use its default name instead";
	}
}

package com.vinnyvangogh.groupironman;

import java.util.concurrent.TimeUnit;

/**
 * Online or last seen, from when a member's client last sent anything.
 *
 * <p>A member sharing stats sends at least once a minute while logged in
 * ({@link GroupService#STATS_HEARTBEAT_TICKS}), so three minutes of silence
 * means they logged out, closed the client or left the party.
 */
final class Presence
{
	static final long ONLINE_MS = TimeUnit.MINUTES.toMillis(3);

	private Presence()
	{
	}

	static boolean online(long lastHeard, long now)
	{
		return lastHeard > 0 && now - lastHeard <= ONLINE_MS;
	}
}

package com.vinnyvangogh.groupironman;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.TimeUnit;

/**
 * Online and offline for this player (Board 2026-11-10, "a happy medium"):
 *
 * <ul>
 * <li>A logout starts a grace of 0 to 10 minutes. A login inside it (a quick
 * relog, a disconnect) says nothing at all, for the logout or the login.</li>
 * <li>Once the grace passes, one "offline" with the session length, stamped
 * with the logout, not the post.</li>
 * <li>A world hop is never a logout: the engine does not call {@link #logout}
 * for one.</li>
 * <li>At most one online/offline pair per {@link #PAIR_MS}: an offline is held
 * until that long after its online was posted, and a login while it is held
 * cancels it, so a flaky connection posts nothing and the channel never says
 * offline while the player is on.</li>
 * <li>A logout saved by a client that closed in the grace is posted on the
 * next start only while it is fresh ({@link #STALE_MS}); never hours later.</li>
 * </ul>
 *
 * The name is the one the login gave, so the post never says "You". Not
 * thread-safe: the engine holds the lock.
 */
final class PresenceDebounce
{
	static final int MAX_GRACE_MINUTES = 10;
	static final long PAIR_MS = TimeUnit.MINUTES.toMillis(10);
	static final long STALE_MS = TimeUnit.MINUTES.toMillis(15);
	/** What GroupService falls back to with no player; never a name to post. */
	private static final String NO_NAME = "You";
	private static final String SEP = "\t";
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("h:mm a", Locale.ENGLISH);

	private final ZoneId zone;
	private String member = "";
	private boolean online;
	private long sessionStart = -1;
	private long loggedOutAt = -1;
	private long onlinePostedAt = -1;
	private int world;
	private boolean dirty;

	PresenceDebounce(ZoneId zone)
	{
		this.zone = zone;
	}

	/**
	 * Logged in as {@code name} on {@code world}: the posts it makes, in order. Empty for a relog inside
	 * the grace or a hop; an offline first when a different account was still counted online.
	 */
	List<GroupEvent> login(long at, int world, String name, int graceMinutes)
	{
		if (name == null || name.isEmpty() || NO_NAME.equals(name))
		{
			return Collections.emptyList();
		}
		List<GroupEvent> out = new ArrayList<>(2);
		GroupEvent due = poll(at, graceMinutes);
		if (due != null)
		{
			out.add(due);
		}
		if (online && !member.equalsIgnoreCase(name))
		{
			// Another account on this client: the first one really left.
			out.add(offline(loggedOutAt < 0 ? at : loggedOutAt));
		}
		dirty = true;
		this.world = world;
		if (online)
		{
			loggedOutAt = -1;
			return out;
		}
		member = name;
		online = true;
		sessionStart = at;
		loggedOutAt = -1;
		onlinePostedAt = at;
		out.add(GroupEvent.of(GroupEvent.Type.ONLINE, at, name).text("online").world(world).build());
		return out;
	}

	/** At the login screen, or the client closing while logged in. Not for a world hop. */
	void logout(long at)
	{
		if (online && loggedOutAt < 0)
		{
			loggedOutAt = at;
			dirty = true;
		}
	}

	/** The plugin restarted while logged in: a saved logout was not one. */
	void resume()
	{
		if (loggedOutAt >= 0)
		{
			loggedOutAt = -1;
			dirty = true;
		}
	}

	/** The "offline" event once a logout is past the grace and the pair limit, else null. Called on a timer. */
	GroupEvent poll(long now, int graceMinutes)
	{
		if (!online || loggedOutAt < 0)
		{
			return null;
		}
		if (now - loggedOutAt > STALE_MS)
		{
			// Only reachable from a saved logout: timing too old to post honestly.
			clear();
			return null;
		}
		long grace = TimeUnit.MINUTES.toMillis(Math.max(0, Math.min(MAX_GRACE_MINUTES, graceMinutes)));
		long due = Math.max(loggedOutAt + grace, onlinePostedAt + PAIR_MS);
		return now < due ? null : offline(loggedOutAt);
	}

	private GroupEvent offline(long at)
	{
		long minutes = sessionStart < 0 ? -1 : Math.max(0, at - sessionStart) / TimeUnit.MINUTES.toMillis(1);
		GroupEvent e = GroupEvent.of(GroupEvent.Type.ONLINE, at, member).text("offline").world(world)
			.number(minutes).detail(CLOCK.format(Instant.ofEpochMilli(at).atZone(zone))).build();
		clear();
		return e;
	}

	private void clear()
	{
		online = false;
		loggedOutAt = -1;
		sessionStart = -1;
		dirty = true;
	}

	/** True once after any change, so the engine saves only then. */
	boolean takeDirty()
	{
		boolean was = dirty;
		dirty = false;
		return was;
	}

	/** "1h 12m", "45m", "under a minute". */
	static String played(long minutes)
	{
		if (minutes < 1)
		{
			return "under a minute";
		}
		return minutes < 60 ? minutes + "m" : minutes / 60 + "h " + minutes % 60 + "m";
	}

	/** One line for the config: empty when there is nothing worth keeping across a restart. */
	String save()
	{
		if (!online)
		{
			return "";
		}
		return String.join(SEP, member, Long.toString(sessionStart), Long.toString(loggedOutAt),
			Long.toString(onlinePostedAt), Integer.toString(world));
	}

	/** {@link #save}'s line back; anything unreadable is a fresh start, which posts no offline. */
	static PresenceDebounce parse(String saved, ZoneId zone)
	{
		PresenceDebounce p = new PresenceDebounce(zone);
		String[] f = saved == null ? new String[0] : saved.split(SEP, -1);
		if (f.length != 5 || f[0].isEmpty())
		{
			return p;
		}
		try
		{
			p.sessionStart = Long.parseLong(f[1]);
			p.loggedOutAt = Long.parseLong(f[2]);
			p.onlinePostedAt = Long.parseLong(f[3]);
			p.world = Integer.parseInt(f[4]);
			p.member = f[0];
			p.online = true;
		}
		catch (NumberFormatException e)
		{
			return new PresenceDebounce(zone);
		}
		return p;
	}

	/** "Back after N days": null unless {@code lastPlayed} is known and at least {@code days} ago. */
	static GroupEvent back(long lastPlayed, long now, int days, String member)
	{
		if (lastPlayed <= 0)
		{
			return null;
		}
		long away = (now - lastPlayed) / TimeUnit.DAYS.toMillis(1);
		return away >= days ? GroupEvent.of(GroupEvent.Type.BACK, now, member).number(away).build() : null;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Levels, XP, total, combat level and quest points, turned into progress
 * events by comparing each new value with the last one this session.
 *
 * <p>The game sends every skill when the player logs in. The first value of
 * each is only remembered, never an event, so a login does not announce
 * every level the player already had; {@link #reset} on logout starts over
 * (another account may log in next). The total is only judged once every
 * skill has a value, for the same reason.
 */
final class ProgressTracker
{
	static final long[] XP_MILESTONES = {1_000_000L, 10_000_000L, 200_000_000L};
	static final int TOTAL_STEP = 100;
	static final int QP_STEP = 25;
	static final int MAX_LEVEL = 99;

	private final int skills;
	private final Map<String, Integer> levels = new HashMap<>();
	private final Map<String, Long> xp = new HashMap<>();
	private int total = -1;
	private int combat = -1;
	private int qp = -1;
	/** False while a login settles ({@link LoginGate}): every value only records. A new tracker counts. */
	private boolean counting = true;

	/** {@code skills}: how many skills there are, OVERALL not counted. */
	ProgressTracker(int skills)
	{
		this.skills = skills;
	}

	/** Another account may log in next: forget every value, and count nothing until {@link #settle}. */
	void reset()
	{
		levels.clear();
		xp.clear();
		total = -1;
		combat = -1;
		qp = -1;
		counting = false;
	}

	/** A login is settling: values only record until {@link #settle}. */
	void quiet()
	{
		counting = false;
	}

	/** The login has settled: a value that goes up from here on is progress. */
	void settle()
	{
		counting = true;
	}

	/** A skill's real level and XP now. */
	List<GroupEvent> skill(String skill, int level, long experience, long at, String member)
	{
		List<GroupEvent> out = new ArrayList<>();
		Integer before = levels.put(skill, level);
		Long xpBefore = xp.put(skill, experience);
		levelUp(skill, level, before, at, member, out);
		milestones(skill, experience, xpBefore, at, member, out);
		// The total is kept while quiet too, so the first level after the login is judged against it.
		totals(at, member, out);
		if (!counting)
		{
			out.clear();
		}
		return out;
	}

	private static void levelUp(String skill, int level, Integer before, long at, String member, List<GroupEvent> out)
	{
		if (before == null || level <= before)
		{
			return;
		}
		out.add(GroupEvent.of(GroupEvent.Type.LEVEL_UP, at, member).text(skill).number(level).previous(before).build());
		if (level >= MAX_LEVEL && before < MAX_LEVEL)
		{
			out.add(GroupEvent.of(GroupEvent.Type.MAXED, at, member).text(skill).number(MAX_LEVEL).build());
		}
	}

	private static void milestones(String skill, long experience, Long xpBefore, long at, String member,
		List<GroupEvent> out)
	{
		if (xpBefore == null)
		{
			return;
		}
		for (long milestone : XP_MILESTONES)
		{
			if (xpBefore < milestone && experience >= milestone)
			{
				out.add(GroupEvent.of(GroupEvent.Type.XP_MILESTONE, at, member).text(skill).number(milestone).build());
			}
		}
	}

	private void totals(long at, String member, List<GroupEvent> out)
	{
		if (levels.size() < skills)
		{
			return;
		}
		int now = 0;
		for (int l : levels.values())
		{
			now += l;
		}
		int before = total;
		total = now;
		if (before < 0 || now <= before)
		{
			return;
		}
		if (now / TOTAL_STEP > before / TOTAL_STEP)
		{
			out.add(GroupEvent.of(GroupEvent.Type.TOTAL_LEVEL, at, member).number(now / TOTAL_STEP * TOTAL_STEP)
				.build());
		}
		int max = skills * MAX_LEVEL;
		if (now >= max && before < max)
		{
			out.add(GroupEvent.of(GroupEvent.Type.MAXED, at, member).text("total").number(now).build());
		}
	}

	/** The combat level now; null when it did not go up. */
	GroupEvent combat(int level, long at, String member)
	{
		int before = combat;
		combat = level;
		return counting && before > 0 && level > before
			? GroupEvent.of(GroupEvent.Type.COMBAT_LEVEL, at, member).number(level).build() : null;
	}

	/** Quest points now; a milestone event when they crossed a multiple of {@link #QP_STEP}. */
	GroupEvent questPoints(int points, long at, String member)
	{
		int before = qp;
		qp = points;
		return counting && before >= 0 && points / QP_STEP > before / QP_STEP
			? GroupEvent.of(GroupEvent.Type.QUEST_POINTS, at, member).number(points / QP_STEP * QP_STEP).build()
			: null;
	}
}

