	Map<String, String> source()
	{
		return source == null ? Collections.emptyMap() : Collections.unmodifiableMap(source);
	}

	List<Quest> quests()
	{
		return quests == null ? Collections.emptyList() : quests;
	}

	/** One quest by its exact name, or null. */
	Quest quest(String name)
	{
		if (byName == null)
		{
			Map<String, Quest> index = new LinkedHashMap<>();
			for (Quest q : quests())
			{
				index.put(q.name(), q);
			}
			byName = index;
		}
		return byName.get(name);
	}

	/** One carried quest by id, or null. */
	Quest quest(long id)
	{
		if (byId == null)
		{
			Map<Long, Quest> index = new LinkedHashMap<>();
			for (Quest q : quests())
			{
				index.put(q.id(), q);
			}
			byId = index;
		}
		return byId.get(id);
	}

	/** Any quest's name by id, carried or not; null when the source had no such quest. */
	String questName(long id)
	{
		return questNames == null ? null : questNames.get(Long.toString(id));
	}

	/** Every quest name the source knows, for judging shop gates. */
	Map<String, String> questNames()
	{
		return questNames == null ? Collections.emptyMap() : Collections.unmodifiableMap(questNames);
	}

	/**
	 * The first shoppable line anywhere in the data for this item, or null. Every line naming one item carries the
	 * same sources (Quest Path looks them up once per item), so any one stands for all; a custom list's item finds
	 * its shops this way.
	 */
	Item item(int itemId)
	{
		if (itemsById == null)
		{
			Map<Integer, Item> index = new LinkedHashMap<>();
			for (Quest q : quests())
			{
				for (Item i : q.items())
				{
					if (ShopNeeds.shoppable(i))
					{
						index.putIfAbsent(i.itemId(), i);
					}
				}
			}
			itemsById = index;
		}
		return itemsById.get(itemId);
	}

	/** One shop by exact name, or null when the data does not carry it. */
	Shop shop(String name)
	{
		if (shopsByName == null)
		{
			Map<String, Shop> index = new LinkedHashMap<>();
			for (Shop s : shops == null ? Collections.<Shop>emptyList() : shops)
			{
				index.put(s.name(), s);
			}
			shopsByName = index;
		}
		return shopsByName.get(name);
	}

	List<Shop> shops()
	{
		return shops == null ? Collections.emptyList() : shops;
	}

	List<DropLocation> dropLocations()
	{
		return dropLocations == null ? Collections.emptyList() : dropLocations;
	}

	/** The bundled data. Never fails: a missing or broken resource is empty data, and the tab says so. */
	static QuestData load(Gson gson)
	{
		try (InputStream in = QuestData.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				return empty();
			}
			return parse(gson, new InputStreamReader(in, StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			return empty();
		}
	}

	static QuestData parse(Gson gson, Reader reader) throws IOException
	{
		try
		{
			QuestData data = gson.fromJson(reader, QuestData.class);
			if (data == null)
			{
				throw new IOException("empty quest data");
			}
			return data;
		}
		catch (JsonParseException e)
		{
			throw new IOException("quest data did not parse: " + e.getMessage(), e);
		}
	}

	static QuestData empty()
	{
		return new QuestData();
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collection;
import java.util.Collections;
import java.util.Set;
import java.util.TreeSet;

/**
 * One member's quest progress, as far as the Shopping tab cares: which of the
 * bundled quests they have finished and which they have started. Read from
 * the game for this player; members send theirs as {@code qstate}
 * ({@link ShoppingCodec}).
 *
 * <p>{@link #UNKNOWN} is a member whose client never said: every quest counts
 * as not started, and the tab says so rather than pretending it knows.
 */
final class QuestProgress
{
	static final QuestProgress UNKNOWN = new QuestProgress(false, Collections.emptySet(), Collections.emptySet());

	private final boolean known;
	private final Set<String> finished;
	private final Set<String> started;

	private QuestProgress(boolean known, Collection<String> finished, Collection<String> started)
	{
		this.known = known;
		this.finished = Collections.unmodifiableSet(new TreeSet<>(finished));
		Set<String> s = new TreeSet<>(started);
		s.removeAll(this.finished);
		this.started = Collections.unmodifiableSet(s);
	}

	static QuestProgress of(Collection<String> finished, Collection<String> started)
	{
		return new QuestProgress(true, finished, started);
	}

	boolean known()
	{
		return known;
	}

	boolean finished(String quest)
	{
		return finished.contains(quest);
	}

	/** Started or finished. */
	boolean started(String quest)
	{
		return finished.contains(quest) || started.contains(quest);
	}

	Set<String> finished()
	{
		return finished;
	}

	/** Started and not finished. */
	Set<String> inProgress()
	{
		return started;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof QuestProgress))
		{
			return false;
		}
		QuestProgress p = (QuestProgress) o;
		return known == p.known && finished.equals(p.finished) && started.equals(p.started);
	}

	@Override
	public int hashCode()
	{
		return finished.hashCode() * 31 + started.hashCode() + (known ? 1 : 0);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;

/**
 * This player's progress in the bundled quests, read from the game: the quest
 * data names quests as the wiki does, and the game's {@link Quest} by its
 * {@link Quest#getName()}, which {@code QuestDataTest} holds to match for
 * every quest a preset reaches.
 */
final class QuestStates
{
	private static final Map<String, Quest> BY_NAME = new HashMap<>();

	static
	{
		for (Quest q : Quest.values())
		{
			BY_NAME.putIfAbsent(normal(q.getName()), q);
		}
	}

	private QuestStates()
	{
	}

	private static String normal(String name)
	{
		return name.replace('’', '\'').trim().toLowerCase(Locale.ROOT);
	}

	/**
	 * The game's quest for a data name, or null. The wiki names Recipe for Disaster's parts as pages,
	 * "Recipe for Disaster/Freeing the Mountain Dwarf"; the game as "Recipe for Disaster - Mountain Dwarf".
	 */
	static Quest quest(String name)
	{
		if (name == null)
		{
			return null;
		}
		Quest q = BY_NAME.get(normal(name));
		return q != null ? q : BY_NAME.get(normal(gameName(name)));
	}

	static String gameName(String wikiName)
	{
		int slash = wikiName.indexOf('/');
		if (slash < 0)
		{
			return wikiName;
		}
		String part = wikiName.substring(slash + 1);
		for (String verb : new String[]{"Freeing the ", "Freeing ", "Defeating the "})
		{
			if (part.startsWith(verb))
			{
				part = part.substring(verb.length());
				break;
			}
		}
		// The wiki frees "the Goblin generals"; the game names them.
		if ("Goblin generals".equals(part))
		{
			part = "Wartface & Bentnoze";
		}
		return wikiName.substring(0, slash) + " - " + part;
	}

	/** Every quest worth reading: those the data carries, and those any carried shop is behind. */
	static Set<String> wanted(QuestData data)
	{
		Set<String> out = new LinkedHashSet<>();
		for (QuestData.Quest q : data.quests())
		{
			out.add(q.name());
		}
		for (QuestData.Shop s : data.shops())
		{
			if (s.reachability() != null)
			{
				for (Long id : s.reachability().requiredQuestIds())
				{
					String name = id == null ? null : data.questName(id);
					if (name != null)
					{
						out.add(name);
					}
				}
			}
		}
		return out;
	}

	/** Client thread when {@code state} asks the game. A name the game does not know is left not started. */
	static QuestProgress read(Collection<String> names, Function<Quest, QuestState> state)
	{
		List<String> finished = new ArrayList<>();
		List<String> started = new ArrayList<>();
		for (String name : names)
		{
			Quest q = quest(name);
			QuestState s = q == null ? null : state.apply(q);
			if (s == QuestState.FINISHED)
			{
				finished.add(name);
			}
			else if (s == QuestState.IN_PROGRESS)
			{
				started.add(name);
			}
		}
		return QuestProgress.of(finished, started);
	}
}

package com.vinnyvangogh.groupironman;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * Map region id to a place name ("Lumbridge", "Vorkath", "Taverley Dungeon"),
 * from the bundled {@code regions.txt} and {@code regions-generated.txt}.
 *
 * <p>A region neither table names is described from where it is, never by its
 * number (Board 2026-11-14): see {@link #describe(int)}.
 */
final class RegionNames
{
	private final Map<Integer, String> names;

	private RegionNames(Map<Integer, String> names)
	{
		this.names = names;
	}

	/**
	 * The bundled tables: the hand-kept {@code regions.txt} first, so its names win, then
	 * {@code regions-generated.txt} (tools/regions/gen_regions.py). A missing or unreadable one counts as empty.
	 */
	static RegionNames load()
	{
		return parse(resource("regions.txt") + "\n" + resource("regions-generated.txt"));
	}

	/** A bundled text resource next to this class, or "" when missing or unreadable. */
	static String resource(String name)
	{
		// getResourceAsStream, never getResource: the resource is inside a jar, not a file.
		try (InputStream stream = RegionNames.class.getResourceAsStream(name))
		{
			if (stream == null)
			{
				return "";
			}
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			byte[] buf = new byte[8192];
			int n;
			while ((n = stream.read(buf)) > 0)
			{
				out.write(buf, 0, n);
			}
			return new String(out.toByteArray(), StandardCharsets.UTF_8);
		}
		catch (IOException e)
		{
			return "";
		}
	}

	/** {@code Name=id,id} per line; {@code #} comments; bad ids are skipped; the first name for an id wins. */
	static RegionNames parse(String text)
	{
		Map<Integer, String> out = new HashMap<>();
		for (String raw : text.split("\n"))
		{
			String line = raw.trim();
			int eq = line.lastIndexOf('=');
			if (line.isEmpty() || line.startsWith("#") || eq <= 0)
			{
				continue;
			}
			String name = line.substring(0, eq).trim();
			for (String id : line.substring(eq + 1).split(","))
			{
				try
				{
					out.putIfAbsent(Integer.parseInt(id.trim()), name);
				}
				catch (NumberFormatException e)
				{
					// One bad id does not lose the rest of the line.
				}
			}
		}
		return new RegionNames(out);
	}

	/** The place name, or null when the table does not know the region. */
	String name(int region)
	{
		return names.get(region);
	}

	int size()
	{
		return names.size();
	}

	/** Every region id the table names. */
	Set<Integer> ids()
	{
		return Collections.unmodifiableSet(names.keySet());
	}

	/**
	 * "Lumbridge"; for a region the table does not name, never its number: "Instance", "Wilderness lvl 17-24",
	 * "near Lumbridge", "under Lumbridge", "Underground" or "Unmapped area". Null when the region itself is
	 * unknown (0).
	 */
	String describe(int region)
	{
		if (region <= 0)
		{
			return null;
		}
		String name = name(region);
		if (name != null)
		{
			return name;
		}
		int rx = region >> 8;
		int ry = region & 0xFF;
		if (rx >= INSTANCE_REGION_X)
		{
			return "Instance";
		}
		String wild = wildernessLevels(rx, ry);
		if (wild != null)
		{
			return wild;
		}
		String near = nearest(rx, ry);
		if (near != null)
		{
			return "near " + near;
		}
		return ry >= CAVE_REGION_Y ? underground(rx, ry) : "Unmapped area";
	}

	/** A cave region: the place right above it, else the nearest named place above it. */
	private String underground(int rx, int ry)
	{
		int above = rx << 8 | (ry - SURFACE_TO_CAVE);
		String name = name(above);
		if (name != null)
		{
			return "under " + name;
		}
		String near = nearest(rx, ry - SURFACE_TO_CAVE);
		return near != null ? "underground near " + near : "Underground";
	}

	/**
	 * The nearest named region within {@link #NEAR_RADIUS} regions on the same map layer, never across the
	 * Wilderness border: straight-line distance, then the lower id, so the answer does not depend on map order.
	 */
	private String nearest(int rx, int ry)
	{
		int layer = layer(ry);
		boolean wild = wilderness(rx, ry) != null;
		int best = -1;
		int bestDistance = Integer.MAX_VALUE;
		for (int dx = -NEAR_RADIUS; dx <= NEAR_RADIUS; dx++)
		{
			for (int dy = -NEAR_RADIUS; dy <= NEAR_RADIUS; dy++)
			{
				int x = rx + dx;
				int y = ry + dy;
				int distance = dx * dx + dy * dy;
				boolean closer = distance < bestDistance || distance == bestDistance && (x << 8 | y) < best;
				if (closer && namedAlike(x, y, layer, wild))
				{
					best = x << 8 | y;
					bestDistance = distance;
				}
			}
		}
		return best < 0 ? null : names.get(best);
	}

	/** A named real-map region on the given layer and the given side of the Wilderness border. */
	private boolean namedAlike(int x, int y, int layer, boolean wild)
	{
		boolean onMap = x >= 0 && x < INSTANCE_REGION_X && y >= 0 && y <= 0xFF;
		return onMap && layer(y) == layer && (wilderness(x, y) != null) == wild && names.containsKey(x << 8 | y);
	}

	/** "Wilderness lvl 17-24" for a region inside the Wilderness, with " (underground)" below ground. */
	private static String wildernessLevels(int rx, int ry)
	{
		Integer base = wilderness(rx, ry);
		if (base == null)
		{
			return null;
		}
		int low = (ry * REGION_SIZE - base) / TILES_PER_LEVEL + 1;
		int high = (ry * REGION_SIZE + REGION_SIZE - 1 - base) / TILES_PER_LEVEL + 1;
		return "Wilderness lvl " + low + "-" + high + (base == WILDERNESS_CAVE_Y ? " (underground)" : "");
	}

	/** The southern edge (level 1) of the Wilderness layer this region is in, or null outside it. */
	private static Integer wilderness(int rx, int ry)
	{
		int x = rx * REGION_SIZE;
		if (x < WILDERNESS_WEST || x > WILDERNESS_EAST)
		{
			return null;
		}
		int y = ry * REGION_SIZE;
		for (int base : new int[]{WILDERNESS_SURFACE_Y, WILDERNESS_CAVE_Y})
		{
			if (y >= base && y < base + WILDERNESS_HEIGHT)
			{
				return base;
			}
		}
		return null;
	}

	/** 0 for the surface, 1 for the rows of special areas above it, 2 for the cave layer. */
	private static int layer(int ry)
	{
		return ry >= CAVE_REGION_Y ? 2 : ry >= SURFACE_TOP_REGION_Y ? 1 : 0;
	}

	private static final int REGION_SIZE = 64;
	/** Instanced maps are built from x 6400 east, past the edge of the real map. */
	private static final int INSTANCE_REGION_X = 100;
	/** The surface ends near y 4224; caves are the surface plus 6400 tiles (100 regions) north. */
	private static final int SURFACE_TOP_REGION_Y = 66;
	private static final int CAVE_REGION_Y = 140;
	private static final int SURFACE_TO_CAVE = 100;
	private static final int NEAR_RADIUS = 3;
	/** Wilderness: x 2944-3391, level 1 at y 3520 on the surface and y 9920 below it, 8 tiles a level. */
	private static final int WILDERNESS_WEST = 2944;
	private static final int WILDERNESS_EAST = 3391;
	private static final int WILDERNESS_SURFACE_Y = 3520;
	private static final int WILDERNESS_CAVE_Y = 9920;
	private static final int WILDERNESS_HEIGHT = 448;
	private static final int TILES_PER_LEVEL = 8;
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntFunction;

/**
 * What the Shopping tab shows for each member's request: per item, who asked,
 * how many, how many the group already holds (banks, inventories, everything
 * "Who has it?" searches, and group storage: {@link ShopAllocation.Holdings},
 * the shopping list's own counting, canonical ids) and who said they will get
 * it. Pure: the plugin captures the inputs, the panel draws the cards.
 *
 * <p>Also the request's Discord events, so the words are tested here.
 */
final class RequestBoard
{
	static final long KIND_MADE = 1;
	static final long KIND_CLAIMED = 2;
	static final long KIND_DONE = 3;
	/** Items named in a "made a request" post; the rest are a count. */
	private static final int NAMED = 3;

	/** One item of a request. */
	static final class Row
	{
		final int itemId;
		final String name;
		final long wanted;
		final long have;
		/** Closed for good by the owner, or sealed when the group held it. */
		final boolean closed;
		final List<String> claimedBy;

		Row(int itemId, String name, long wanted, long have, boolean closed, List<String> claimedBy)
		{
			this.itemId = itemId;
			this.name = name;
			this.wanted = wanted;
			this.have = have;
			this.closed = closed;
			this.claimedBy = Collections.unmodifiableList(claimedBy);
		}

		/** Closes by itself once the group holds the amount. */
		boolean done()
		{
			return closed || have >= wanted;
		}
	}

	/** One request, worked out. */
	static final class Card
	{
		final RequestList request;
		final List<Row> rows;

		Card(RequestList request, List<Row> rows)
		{
			this.request = request;
			this.rows = Collections.unmodifiableList(rows);
		}

		int done()
		{
			int n = 0;
			for (Row r : rows)
			{
				n += r.done() ? 1 : 0;
			}
			return n;
		}

		/** The whole list is done when every item is, or the owner closed it. */
		boolean allDone()
		{
			return request.closed || done() == rows.size();
		}
	}

	private RequestBoard()
	{
	}

	static Card card(RequestList r, List<RequestClaim> claims, ShopAllocation.Holdings holdings,
		IntFunction<String> names)
	{
		List<Row> rows = new ArrayList<>();
		for (Map.Entry<Integer, Integer> e : r.items.entrySet())
		{
			int id = e.getKey();
			List<String> by = new ArrayList<>();
			for (RequestClaim c : claims)
			{
				if (c.claimed && c.itemId == id && !by.contains(c.member))
				{
					by.add(c.member);
				}
			}
			rows.add(new Row(id, names.apply(id), e.getValue(), holdings.total(id), r.closed
				|| r.closedItems.contains(id), by));
		}
		return new Card(r, rows);
	}

	/** Items the group now holds enough of that are not yet sealed: what the owner's client closes. */
	static Set<Integer> reached(Card c)
	{
		Set<Integer> out = new LinkedHashSet<>();
		for (Row r : c.rows)
		{
			if (!r.closed && r.have >= r.wanted)
			{
				out.add(r.itemId);
			}
		}
		return out;
	}

	// ---- Discord ----

	/** The owner made a request: "made a request, 'Fire cape': 500 Shark, 20 Prayer potion(4)". */
	static GroupEvent made(RequestList r, IntFunction<String> names, long now)
	{
		List<String> parts = new ArrayList<>();
		for (Map.Entry<Integer, Integer> e : r.items.entrySet())
		{
			if (parts.size() < NAMED)
			{
				parts.add(Amounts.GAME.of(e.getValue()) + " " + names.apply(e.getKey()));
			}
		}
		int rest = r.items.size() - parts.size();
		String items = String.join(", ", parts) + (rest > 0 ? " and " + rest + " more" : "");
		return GroupEvent.of(GroupEvent.Type.REQUEST, now, r.owner).text(r.name).detail(items).number(KIND_MADE)
			.build();
	}

	/** A member claimed an item: "will get Shark for Alice's 'Fire cape'". */
	static GroupEvent claimed(RequestList r, int itemId, String itemName, String member, long now)
	{
		return GroupEvent.of(GroupEvent.Type.REQUEST, now, member).text(r.name).detail(itemName + " for " + r.owner)
			.number(KIND_CLAIMED).items(Collections.singletonMap(itemId, 1)).build();
	}

	/** The owner's request is done: "'Fire cape' is done: the group has it all". */
	static GroupEvent done(RequestList r, long now)
	{
		return GroupEvent.of(GroupEvent.Type.REQUEST, now, r.owner).text(r.name).number(KIND_DONE).build();
	}

	/** {@link EventText}'s line for a request event. */
	static String describe(GroupEvent e)
	{
		if (e.number == KIND_CLAIMED)
		{
			int cut = e.detail.lastIndexOf(" for ");
			return cut < 0 ? "will get " + e.detail + " ('" + e.text + "')"
				: "will get " + e.detail.substring(0, cut) + " for " + e.detail.substring(cut + 5) + "'s '" + e.text
				+ "'";
		}
		if (e.number == KIND_DONE)
		{
			return "'" + e.text + "' is done: the group has it all";
		}
		return "made a request, '" + e.text + "'" + (e.detail.isEmpty() ? "" : ": " + e.detail);
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Every member's requests and every claim on them, as this client holds them.
 * Part of {@link ShoppingSync}: it travels in the same party messages, is sent
 * on the same tick and kept in the same cache entry, so there is one sync path.
 * Not thread-safe by itself: {@link ShoppingSync} holds its lock around every
 * call.
 *
 * <p><b>Owner-only.</b> A request revision is taken only when it names the
 * same owner as the one held, so a member can never rewrite or remove another
 * member's list; claims are each member's own records and never touch it.
 */
final class RequestBook
{
	/** Requests kept, removed ones included; past it the oldest removed, then closed, one is forgotten. */
	static final int MAX_REQUESTS = 40;
	/** Claim records kept; a full book forgets ones on requests it no longer has, or taken-back ones. */
	static final int MAX_CLAIMS = 400;

	private final Map<String, RequestList> requests = new LinkedHashMap<>();
	/** By {@link RequestClaim#key}. */
	private final Map<String, RequestClaim> claims = new LinkedHashMap<>();
	private final Set<String> dirtyRequests = new LinkedHashSet<>();
	private final Set<String> dirtyClaims = new LinkedHashSet<>();

	/**
	 * Keeps {@code r} when it is newer than what is held and from the same owner; {@code own} marks it to send.
	 * Returns the history line ("" for nothing to say), or null when it was not taken.
	 */
	String accept(RequestList r, boolean own)
	{
		RequestList current = requests.get(r.id);
		if (!r.newerThan(current) || current != null && !current.ownedBy(r.owner))
		{
			return null;
		}
		if (current == null && !roomFor())
		{
			return null;
		}
		requests.put(r.id, r);
		if (own)
		{
			dirtyRequests.add(r.id);
		}
		return describe(current, r);
	}

	/** Keeps {@code c} when it is newer than this member's last word on that item; false when not taken. */
	boolean accept(RequestClaim c, boolean own)
	{
		RequestClaim current = claims.get(c.key());
		if (!c.newerThan(current) || current == null && !claimRoom())
		{
			return false;
		}
		claims.put(c.key(), c);
		if (own)
		{
			dirtyClaims.add(c.key());
		}
		return true;
	}

	/** "Alice asked for 'Fire cape'"; empty when there is nothing to say. */
	static String describe(RequestList before, RequestList after)
	{
		String who = after.owner;
		if (after.removed)
		{
			return before != null && before.removed ? "" : who + " removed '" + after.name + "'";
		}
		if (before == null)
		{
			return who + " asked for '" + after.name + "'";
		}
		if (after.closed && !before.closed)
		{
			return "'" + after.name + "' is done";
		}
		if (!before.name.equals(after.name))
		{
			return who + " renamed '" + before.name + "' to '" + after.name + "'";
		}
		return "";
	}

	RequestList get(String id)
	{
		return requests.get(id);
	}

	/** Not removed, oldest first; closed ones included so the group sees them done. */
	List<RequestList> live()
	{
		List<RequestList> out = new ArrayList<>();
		for (RequestList r : requests.values())
		{
			if (!r.removed)
			{
				out.add(r);
			}
		}
		out.sort((a, b) -> a.created != b.created ? Long.compare(a.created, b.created) : a.id.compareTo(b.id));
		return out;
	}

	/** Standing claims ("I'll get it") on {@code id}, in the order they came. */
	List<RequestClaim> claims(String id)
	{
		List<RequestClaim> out = new ArrayList<>();
		for (RequestClaim c : claims.values())
		{
			if (c.claimed && c.requestId.equals(id))
			{
				out.add(c);
			}
		}
		return out;
	}

	void resendAll()
	{
		dirtyRequests.addAll(requests.keySet());
		dirtyClaims.addAll(claims.keySet());
	}

	/** Everything marked to send, as party messages; the marks are cleared. */
	void drain(Gson gson, List<String> out)
	{
		for (String id : dirtyRequests)
		{
			RequestList r = requests.get(id);
			if (r != null)
			{
				out.add(ShoppingCodec.encode(gson, r));
			}
		}
		for (String key : dirtyClaims)
		{
			RequestClaim c = claims.get(key);
			if (c != null)
			{
				out.add(ShoppingCodec.encode(gson, c));
			}
		}
		dirtyRequests.clear();
		dirtyClaims.clear();
	}

	JsonArray requestsToCache(Gson gson)
	{
		JsonArray out = new JsonArray();
		requests.values().forEach(r -> out.add(ShoppingCodec.encode(gson, r)));
		return out;
	}

	JsonArray claimsToCache(Gson gson)
	{
		JsonArray out = new JsonArray();
		claims.values().forEach(c -> out.add(ShoppingCodec.encode(gson, c)));
		return out;
	}

	/** One cached record; a removal past {@code tombstoneMs} is dropped, and so is a claim on a request not held. */
	void fromCache(ShoppingCodec.Message m, long now, long tombstoneMs)
	{
		if (m == null)
		{
			return;
		}
		if (m.request != null && !(m.request.removed && now - m.request.at > tombstoneMs))
		{
			accept(m.request, false);
		}
		else if (m.claim != null && requests.containsKey(m.claim.requestId))
		{
			accept(m.claim, false);
		}
	}

	private boolean roomFor()
	{
		return ShoppingSync.makeRoom(requests, MAX_REQUESTS, r -> r.removed, r -> r.at)
			|| ShoppingSync.makeRoom(requests, MAX_REQUESTS, r -> r.closed, r -> r.at);
	}

	private boolean claimRoom()
	{
		return ShoppingSync.makeRoom(claims, MAX_CLAIMS, c -> !c.claimed || !requests.containsKey(c.requestId),
			c -> c.at);
	}
}

package com.vinnyvangogh.groupironman;

import java.awt.Color;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import net.runelite.client.game.ItemManager;

/**
 * The Shopping tab's request cards: each member's own list, what the group
 * holds of each item and who said they will get it. The owner renames,
 * closes or removes; anyone claims. Folded like the lists (Board 2026-11-14):
 * a header with a preview until opened. The words are static so tests read
 * them.
 */
final class RequestCards
{
	private static final Color MUTED = ShopCards.MUTED;
	private static final Color DONE = ShopCards.DONE;

	private final ShoppingTab.Actions actions;
	private final ItemManager items;
	/** Shows a refusal, or clears it with null. */
	private final Consumer<String> say;
	/** Folds and item lines, shared with the lists. */
	private final ShoppingTab tab;

	RequestCards(ShoppingTab.Actions actions, ItemManager items, Consumer<String> say, ShoppingTab tab)
	{
		this.actions = actions;
		this.items = items;
		this.say = say;
		this.tab = tab;
	}

	void draw(JPanel panel, List<RequestBoard.Card> cards, String self, ItemPaths.Planner paths)
	{
		if (cards.isEmpty())
		{
			return;
		}
		panel.add(GroupIronmanPanel.heading("Requests"));
		for (RequestBoard.Card c : cards)
		{
			panel.add(card(c, self, paths));
		}
	}

	private JPanel card(RequestBoard.Card c, String self, ItemPaths.Planner paths)
	{
		String key = ShopFolds.request(c.request.id);
		boolean open = tab.isOpen(key);
		List<RequestBoard.Row> needed = new ArrayList<>();
		List<RequestBoard.Row> done = new ArrayList<>();
		for (RequestBoard.Row r : c.rows)
		{
			(r.done() ? done : needed).add(r);
		}
		List<Integer> preview = new ArrayList<>();
		needed.forEach(r -> preview.add(r.itemId));
		JPanel box = Ui.card();
		int finished = c.request.closed ? c.rows.size() : c.done();
		ShopCards.header(box, c.request.name, open, finished, c.rows.size(), preview, items, () -> tab.fold(key));
		if (!open)
		{
			return box;
		}
		box.add(new ShopCards.Wrap(byline(c, System.currentTimeMillis()), MUTED, ShopCards.CARD_TEXT));
		boolean mine = c.request.ownedBy(self);
		if (mine)
		{
			box.add(ownerButtons(c.request));
		}
		for (RequestBoard.Row r : needed)
		{
			box.add(row(c.request, r, self, mine, stops(paths, c.request, r)));
		}
		tab.addDone(box, key, done.size(), () -> done.forEach(r -> box.add(row(c.request, r, self, mine,
			stops(paths, c.request, r)))));
		return box;
	}

	/** "Asked by Alice, 5 min ago. 1 of 2 done." or "... Done." */
	static String byline(RequestBoard.Card c, long now)
	{
		String state = c.request.closed ? "Closed." : c.allDone() ? "Done." : c.done() + " of " + c.rows.size()
			+ " done.";
		return "Asked by " + c.request.owner + ", " + BoostText.ago(now, c.request.created) + ". " + state;
	}

	/** "Shark  450 / 500". */
	static String summary(RequestBoard.Row r)
	{
		return r.name + "  " + Amounts.GAME.of(Math.min(r.have, r.wanted)) + " / " + Amounts.GAME.of(r.wanted);
	}

	/** "Need 50 more", "Done", or "Closed" when the owner closed it short. */
	static String needText(RequestBoard.Row r)
	{
		if (r.have >= r.wanted)
		{
			return "Done";
		}
		return r.closed ? "Closed" : "Need " + Amounts.GAME.of(r.wanted - r.have) + " more";
	}

	/** "Bob and Cat will get it"; empty when nobody said. */
	static String claimText(RequestBoard.Row r)
	{
		if (r.claimedBy.isEmpty())
		{
			return "";
		}
		List<String> names = r.claimedBy;
		String who = names.size() == 1 ? names.get(0)
			: String.join(", ", names.subList(0, names.size() - 1)) + " and " + names.get(names.size() - 1);
		return who + " will get it";
	}

	/** Where "Path to" leads for one requested item; empty without a planner. */
	private static List<ItemPaths.Stop> stops(ItemPaths.Planner paths, RequestList req, RequestBoard.Row r)
	{
		return paths == null ? Collections.emptyList() : paths.request(req, r);
	}

	private JPanel row(RequestList req, RequestBoard.Row r, String self, boolean mine, List<ItemPaths.Stop> stops)
	{
		JPanel words = new GroupIronmanPanel.Column();
		words.add(new ShopCards.Wrap(summary(r), r.done() ? DONE : Color.WHITE, ShopCards.ROW_TEXT));
		words.add(new ShopCards.Bar(Math.min(r.have, r.wanted), r.wanted, ShopCards.ROW_TEXT));
		words.add(new ShopCards.Wrap(needText(r), r.done() ? DONE : MUTED, ShopCards.ROW_TEXT));
		String claims = claimText(r);
		if (!claims.isEmpty())
		{
			words.add(new ShopCards.Wrap(claims, MUTED, ShopCards.ROW_TEXT));
		}
		if (req.open() && !r.done())
		{
			words.add(rowButtons(req, r, self, mine));
		}
		if (!stops.isEmpty())
		{
			ItemPaths.Stop to = stops.get(0);
			ItemPaths.Target why = ItemPaths.Target.requestItem(req.id, r.itemId);
			words.add(ShoppingTab.pathButton(to.label(), () -> say.accept(actions.pathTo(why, to))));
		}
		return tab.itemLine(r.itemId, words);
	}

	private JPanel rowButtons(RequestList req, RequestBoard.Row r, String self, boolean mine)
	{
		JPanel buttons = new JPanel(new GridLayout(1, 0, 2, 0));
		buttons.setOpaque(false);
		boolean claimed = claimedBy(r, self);
		buttons.add(Ui.button(claimed ? "Not getting it" : "I'll get it", null, () -> say.accept(
			actions.claimRequest(req.id, r.itemId, !claimed) ? null : "Not changed: log in first.")));
		if (mine)
		{
			buttons.add(Ui.button("Close item", null, () -> say.accept(
				actions.closeRequestItem(req.id, r.itemId) ? null : "Not closed: log in first.")));
		}
		return buttons;
	}

	static boolean claimedBy(RequestBoard.Row r, String self)
	{
		for (String m : r.claimedBy)
		{
			if (GroupMembers.key(m).equals(GroupMembers.key(self)))
			{
				return true;
			}
		}
		return false;
	}

	private JPanel ownerButtons(RequestList r)
	{
		JPanel row = new JPanel(new GridLayout(1, 0, 2, 0));
		row.setOpaque(false);
		row.add(Ui.button("Rename", null, () ->
		{
			String name = JOptionPane.showInputDialog(row, "New name for '" + r.name + "'", r.name);
			if (name != null)
			{
				say.accept(actions.renameRequest(r.id, name) ? null : "Not renamed: log in, and give it a new name.");
			}
		}));
		if (r.open())
		{
			row.add(Ui.button("Close", null, () -> say.accept(actions.closeRequest(r.id) ? null
				: "Not closed: log in first.")));
		}
		row.add(Ui.button("Remove", null, () ->
		{
			if (JOptionPane.showConfirmDialog(row, "Remove your request '" + r.name + "'?", "Remove request",
				JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION)
			{
				say.accept(actions.removeRequest(r.id) ? null : "Not removed: log in first.");
			}
		}));
		return row;
	}

	/** Changes when anything a request card draws changes. */
	static String signature(List<RequestBoard.Card> cards, String self, ItemPaths.Planner paths)
	{
		StringBuilder s = new StringBuilder(self);
		for (RequestBoard.Card c : cards)
		{
			s.append('|').append(c.request.id).append(c.request.rev);
			for (RequestBoard.Row r : c.rows)
			{
				s.append(summary(r)).append(needText(r)).append(claimText(r))
					.append(ShoppingTab.first(stops(paths, c.request, r)));
			}
		}
		return s.toString();
	}
}

package com.vinnyvangogh.groupironman;

/**
 * One member saying "I'll get it" for one item of a request, or taking it
 * back. Each member writes only their own claims, so the newest record for
 * a (request, item, member) wins ({@link #newerThan}) and two members
 * claiming the same item at once both keep their claim.
 */
final class RequestClaim
{
	final String requestId;
	final int itemId;
	final String member;
	final boolean claimed;
	final long at;

	RequestClaim(String requestId, int itemId, String member, boolean claimed, long at)
	{
		this.requestId = requestId;
		this.itemId = itemId;
		this.member = ShoppingList.cap(member, ShoppingList.MAX_TEXT);
		this.claimed = claimed;
		this.at = at;
	}

	/** One record per request, item and member, however the member's name is spelt. */
	String key()
	{
		return requestId + ":" + itemId + ":" + GroupMembers.key(member);
	}

	/** Later wins; at the same moment, taking a claim back wins, so every client lands on the same answer. */
	boolean newerThan(RequestClaim other)
	{
		if (other == null)
		{
			return true;
		}
		return at != other.at ? at > other.at : !claimed && other.claimed;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collection;
import java.util.Collections;
import java.util.Map;
import java.util.TreeSet;

/**
 * One member's request to the group: their own named list of items and how
 * many of each they want ("Fire cape": 500 sharks, 20 prayer potions). The
 * group fills it; see {@link RequestBoard} for what is held and claimed.
 *
 * <p>Only its {@link #owner} ever writes a revision, so revisions never
 * conflict: the newest wins ({@link #newerThan}), as {@link ShoppingList}'s
 * do, and a revision naming a different owner is never taken
 * ({@link RequestBook}). Claims are separate records ({@link RequestClaim})
 * so that anyone can claim without touching the owner's list.
 *
 * <p>Items close two ways: the owner closes one, or the owner's client
 * closes it once the group holds the amount ({@link #closedItems}). The list
 * is {@link #closed} when every item is.
 */
final class RequestList
{
	static final String ADDED = "added";
	static final String RENAMED = "renamed";
	static final String CLOSED = "closed";
	static final String REMOVED = "removed";

	final String id;
	final String owner;
	final String name;
	final Map<Integer, Integer> items;
	/** Items done for good: reached or closed by the owner. Only ever ids on {@link #items}. */
	final java.util.Set<Integer> closedItems;
	final boolean closed;
	final boolean removed;
	final long rev;
	final long at;
	final long created;
	final String action;

	RequestList(String id, String owner, String name, Map<Integer, Integer> items, Collection<Integer> closedItems,
		boolean closed, boolean removed, long rev, long at, long created, String action)
	{
		this.id = id;
		this.owner = ShoppingList.cap(owner, ShoppingList.MAX_TEXT);
		this.items = ShoppingList.capItems(items);
		this.name = defaultName(name, this.owner);
		TreeSet<Integer> shut = new TreeSet<>();
		for (Integer i : closedItems == null ? Collections.<Integer>emptySet() : closedItems)
		{
			if (i != null && this.items.containsKey(i))
			{
				shut.add(i);
			}
		}
		this.closedItems = Collections.unmodifiableSet(shut);
		this.closed = closed || !this.items.isEmpty() && shut.size() == this.items.size();
		this.removed = removed;
		this.rev = rev;
		this.at = at;
		this.created = created;
		this.action = ShoppingList.cap(action, 16);
	}

	/** A new request, revision 1; a blank name becomes "Alice's requests". */
	static RequestList create(String name, Map<Integer, Integer> items, String owner, long now)
	{
		return new RequestList(ShoppingList.newId(), owner, name, items, Collections.emptySet(), false, false, 1, now,
			now, ADDED);
	}

	static String defaultName(String name, String owner)
	{
		String n = ShoppingList.cap(name, ShoppingList.MAX_NAME);
		return n.isEmpty() ? ShoppingList.cap(owner + "'s requests", ShoppingList.MAX_NAME) : n;
	}

	boolean ownedBy(String member)
	{
		return member != null && !owner.isEmpty() && GroupMembers.key(owner).equals(GroupMembers.key(member));
	}

	/** Open for claims: not closed and not removed. */
	boolean open()
	{
		return !closed && !removed;
	}

	/** True when this revision should replace {@code other}: a higher revision, then later, then a removal. */
	boolean newerThan(RequestList other)
	{
		if (other == null)
		{
			return true;
		}
		int order = ShoppingList.order(rev, at, other.rev, other.at);
		return order != 0 ? order > 0 : removed && !other.removed || closed && !other.closed;
	}

	private RequestList next(String newName, Collection<Integer> shut, boolean close, boolean gone, long now,
		String newAction)
	{
		return new RequestList(id, owner, newName, items, shut, close, gone, rev + 1, Math.max(now, at), created,
			newAction);
	}

	RequestList renamed(String newName, long now)
	{
		return next(newName, closedItems, closed, false, now, RENAMED);
	}

	/** These items closed as well; the list closes with its last one. */
	RequestList withClosedItems(Collection<Integer> ids, long now)
	{
		TreeSet<Integer> shut = new TreeSet<>(closedItems);
		shut.addAll(ids);
		return next(name, shut, closed, false, now, CLOSED);
	}

	RequestList closedBy(long now)
	{
		return next(name, closedItems, true, false, now, CLOSED);
	}

	RequestList removedBy(long now)
	{
		return next(name, closedItems, closed, true, now, REMOVED);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Map;
import java.util.TreeMap;

/**
 * The Settings tab's unsaved edits, and when they give way to what the group
 * holds. Pure, so the rules are tested without Swing.
 *
 * <p>The draft is replaced only when this player's role or the group's roles
 * change, or when it holds no edits. Anything else the tab shows (who is
 * online, who has been heard, each member's opt-outs) never touches it: the
 * leader's Save once sent the old values because another member's announce
 * redrew the tab (Board 2026-11-13). A new settings version arriving under
 * unsaved edits keeps them and says so, so Save is a choice, not a surprise.
 */
final class SettingsDraft
{
	private Map<String, Long> values = new TreeMap<>();
	/** What the draft started from: edited means it differs from this. */
	private Map<String, Long> base = new TreeMap<>();
	private String roleKey;
	private String settingsKey = "";
	private String notice;

	/** The draft as the inputs show it. */
	Map<String, Long> values()
	{
		return values;
	}

	void put(String key, long value)
	{
		values.put(key, value);
	}

	/** True when the player changed something not yet saved. */
	boolean edited()
	{
		return !values.equals(base);
	}

	/** Why the draft no longer matches the group's, or null. */
	String notice()
	{
		return notice;
	}

	/**
	 * Every redraw: what this client holds now. {@code current} is each shared
	 * setting's value now, the group's or this member's own while it has none.
	 */
	void update(GroupGovernance.Role role, GroupRoles roles, GroupSettings settings, Map<String, Long> current)
	{
		String nowRoles = role + "|" + (roles == null ? "" : roles.signature);
		String nowSettings = settings == null ? "" : settings.signature;
		if (!nowRoles.equals(roleKey) || !edited() || values.equals(current))
		{
			adopt(current);
		}
		else if (settings != null && !nowSettings.equals(settingsKey))
		{
			notice = "Your group's settings changed (version " + settings.version + " by " + settings.by + ")."
				+ " Save will replace them, or Discard to see theirs.";
		}
		roleKey = nowRoles;
		settingsKey = nowSettings;
	}

	/** "Discard changes". */
	void discard(Map<String, Long> current)
	{
		adopt(current);
	}

	/** Save went through: the draft is now what the group holds. */
	void saved()
	{
		base = new TreeMap<>(values);
		notice = null;
	}

	private void adopt(Map<String, Long> current)
	{
		values = new TreeMap<>(current);
		base = new TreeMap<>(current);
		notice = null;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * What the panel's Settings tab shows, built without Swing so it is tested:
 * the header lines, the history in words, and the read-only opt-out grid the
 * leader and editors see (Board 2026-11-10: only a member changes their own
 * opt-outs).
 */
final class SettingsModel
{
	enum Cell
	{
		/** Posts this kind. */
		IN,
		/** Opted out, of this kind or of everything. */
		OUT,
		/** No announce heard from this member yet. */
		UNKNOWN
	}

	static final class GridRow
	{
		final GroupEvent.Type type;
		final String label;
		/** One per {@link Grid#members}, in order. */
		final List<Cell> cells;

		GridRow(GroupEvent.Type type, List<Cell> cells)
		{
			this.type = type;
			this.label = EventText.title(type);
			this.cells = Collections.unmodifiableList(cells);
		}
	}

	static final class Grid
	{
		final List<String> members;
		final List<GridRow> rows;

		Grid(List<String> members, List<GridRow> rows)
		{
			this.members = Collections.unmodifiableList(members);
			this.rows = Collections.unmodifiableList(rows);
		}
	}

	private SettingsModel()
	{
	}

	/** Event kind by member: who posts what. {@code prefs} is by display name, as announced. */
	static Grid grid(List<String> members, Map<String, MemberPrefs> prefs)
	{
		List<MemberPrefs> byMember = new ArrayList<>();
		for (String m : members)
		{
			byMember.add(find(prefs, m));
		}
		List<GridRow> rows = new ArrayList<>();
		for (GroupEvent.Type t : GroupEvent.Type.values())
		{
			List<Cell> cells = new ArrayList<>();
			for (MemberPrefs p : byMember)
			{
				cells.add(p == null ? Cell.UNKNOWN : p.posts(t) ? Cell.IN : Cell.OUT);
			}
			rows.add(new GridRow(t, cells));
		}
		return new Grid(new ArrayList<>(members), rows);
	}

	private static MemberPrefs find(Map<String, MemberPrefs> prefs, String name)
	{
		String key = GroupMembers.key(name);
		for (Map.Entry<String, MemberPrefs> e : prefs.entrySet())
		{
			if (GroupMembers.key(e.getKey()).equals(key))
			{
				return e.getValue();
			}
		}
		return null;
	}

	/** Who leads, this player's role, and the settings' version and last save. */
	static List<String> header(GroupGovernance.Role mine, GroupRoles roles, GroupSettings settings, long now)
	{
		List<String> out = new ArrayList<>();
		if (roles == null)
		{
			out.add("No group leader yet. Until one saves group settings, each member uses their own.");
			return out;
		}
		out.add("Leader: " + roles.leader + (roles.editors.isEmpty() ? ""
			: ". Editors: " + String.join(", ", roles.editors.keySet())));
		out.add("You are " + (mine == GroupGovernance.Role.LEADER ? "the leader"
			: mine == GroupGovernance.Role.EDITOR ? "an editor" : "a member: view only") + ".");
		if (settings == null)
		{
			out.add("No group settings saved yet: each member uses their own.");
		}
		else
		{
			out.add("Version " + settings.version + ", saved by " + settings.by + " " + BoostText.ago(now, settings.at)
				+ ".");
		}
		return out;
	}

	/**
	 * Shared webhooks in words: who shares them ({@code by}, null when nobody does), never a URL. A member is told
	 * their own webhook still wins and that 'Post to Discord' is theirs to tick; the leader is told who can read them.
	 */
	static List<String> webhookLines(GroupGovernance.Role mine, String by)
	{
		List<String> out = new ArrayList<>();
		if (mine == GroupGovernance.Role.LEADER)
		{
			out.add(by == null ? "Your webhooks are yours alone. Share them and members only tick 'Post to Discord'."
				: "Sharing your webhooks: anyone with the group key can read them.");
			return out;
		}
		if (by != null)
		{
			out.add("Using the group's webhooks (set by " + by + ").");
			out.add("A webhook you paste yourself wins for its category. Tick 'Post to Discord' to post.");
		}
		return out;
	}

	/** The history, newest first, in words. */
	static List<String> history(GroupSettings settings, long now)
	{
		List<String> out = new ArrayList<>();
		if (settings == null)
		{
			return out;
		}
		for (GroupSettings.Change c : settings.history)
		{
			out.add(c.by + " " + change(c) + " (" + BoostText.ago(now, c.at) + ")");
		}
		return out;
	}

	static String change(GroupSettings.Change c)
	{
		if (GroupSettings.MANY.equals(c.key))
		{
			return "set " + c.to + " settings";
		}
		if (c.key.startsWith("resigned:"))
		{
			return "re-signed the settings " + c.key.substring("resigned:".length()) + " saved";
		}
		GroupSettingsSchema.Setting s = GroupSettingsSchema.get(c.key);
		if (s == null)
		{
			return "changed " + c.key;
		}
		String where = s.section.equals(GroupSettingsSchema.THRESHOLDS) || s.section.equals(GroupSettingsSchema.TIMING)
			? "" : " (" + s.section + ")";
		if (s.flag)
		{
			return "turned " + (c.to != 0 ? "on" : "off") + " " + s.label + where;
		}
		return "changed " + s.label + " from " + c.from + " to " + c.to;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.function.BiConsumer;

/**
 * The panel's "Turn on sharing" card (Board 2026-11-13): a member who pastes
 * the group key is one click from fully set up, instead of ticking every Share
 * switch by hand. Nothing turns on without the click.
 *
 * <p>The card opens for a key when that key is pasted, or when sync is on with
 * a key and every Share switch is off. It stays open for that key while it
 * still has a button to offer; "Not now" closes it until the key changes. Swing
 * thread only.
 */
final class SharingPrompt
{
	/**
	 * What "Turn on sharing" sets to true, in the settings' own order: Sync with my group and every Share switch.
	 * Existing keys, read here and never renamed (ConfigKeysTest freezes them).
	 */
	static final List<String> SHARING_KEYS = Collections.unmodifiableList(Arrays.asList("groupSync",
		"groupShareBank", "groupShareStorage", "groupShareStats", "groupShareCarried", "groupShareExtras",
		"groupShareDrops", "groupShareEvents"));
	/** What "Post my events to Discord" sets to true. */
	static final String DISCORD_KEY = "discordEnabled";

	static final String TEXT = "Your group sees only what you share. 'Turn on sharing' ticks Sync with my group and"
		+ " every Share switch: bank, group storage changes, stats, inventory and equipment, pouch, quiver and vault,"
		+ " drops and collection log, and group events. Untick any of them later in settings.";

	/** The settings the card reads, captured with each redraw. */
	static final class Settings
	{
		/** The group key as saved, normalised; empty without one. */
		final String key;
		final boolean sync;
		/** At least one Share switch is on. */
		final boolean anyShare;
		/** Sync and every Share switch are on: nothing left for "Turn on sharing" to do. */
		final boolean allSharing;
		final boolean discordOn;
		/** A Discord webhook to post to: one of this player's own. */
		final boolean webhook;

		Settings(String key, boolean sync, boolean anyShare, boolean allSharing, boolean discordOn, boolean webhook)
		{
			this.key = key == null ? "" : key;
			this.sync = sync;
			this.anyShare = anyShare;
			this.allSharing = allSharing;
			this.discordOn = discordOn;
			this.webhook = webhook;
		}

		static Settings of(GroupIronmanConfig c)
		{
			boolean[] shares = {c.groupShareBank(), c.groupShareStorage(), c.groupShareStats(), c.groupShareCarried(),
				c.groupShareExtras(), c.groupShareDrops(), c.groupShareEvents()};
			boolean any = false;
			boolean all = true;
			for (boolean s : shares)
			{
				any |= s;
				all &= s;
			}
			return new Settings(GroupKey.normalize(c.groupKey()), c.groupSync(), any, all && c.groupSync(),
				c.discordEnabled(), anyWebhook(Webhooks.of(c)));
		}

		private static boolean anyWebhook(Webhooks hooks)
		{
			for (Webhook w : Webhook.values())
			{
				if (hooks.url(w) != null)
				{
					return true;
				}
			}
			return false;
		}
	}

	/** What the card shows: which of its two buttons. */
	static final class Card
	{
		final boolean sharing;
		final boolean discord;

		Card(boolean sharing, boolean discord)
		{
			this.sharing = sharing;
			this.discord = discord;
		}
	}

	/** "Turn on sharing": exactly {@link #SHARING_KEYS}, each set to true through {@code set}. */
	static void turnOnSharing(BiConsumer<String, Object> set)
	{
		for (String key : SHARING_KEYS)
		{
			set.accept(key, true);
		}
	}

	/** "Post my events to Discord": the Post to Discord switch only. */
	static void postToDiscord(BiConsumer<String, Object> set)
	{
		set.accept(DISCORD_KEY, true);
	}

	/** The key the card is open for; null when closed. */
	private String openFor;
	/** The key "Not now" was pressed for; null when never. */
	private String dismissedFor;

	/** A successful "Paste group key": opens the card for that key. */
	void pasted(String key)
	{
		if (key != null && !key.isEmpty())
		{
			openFor = key;
		}
	}

	/** "Not now": closed until the key changes. */
	void notNow(String key)
	{
		dismissedFor = key;
		openFor = null;
	}

	/** The card to draw now, or null for none. */
	Card card(Settings s)
	{
		if (s.key.isEmpty() || s.key.equals(dismissedFor))
		{
			return null;
		}
		if (s.sync && !s.anyShare)
		{
			openFor = s.key;
		}
		if (!s.key.equals(openFor))
		{
			return null;
		}
		Card card = new Card(!s.allSharing, s.webhook && !s.discordOn);
		if (!card.sharing && !card.discord)
		{
			// Done: a later change to one switch does not bring it back.
			openFor = null;
			return null;
		}
		return card;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.function.IntPredicate;

/**
 * What a group still has to get for one shopping list, item by item: "you all
 * need 6 buckets, the group holds 2, get 4".
 *
 * <p>Ported from Quest Path's {@code groupshop.GroupShoppingList}
 * (questpath-plugin ee638ff). Holdings are spent in the order a group would
 * spend them:
 * <ol>
 * <li><b>Your own first.</b> What a member holds covers their own need before
 * anyone else's. The only offset an untradeable item ever makes.</li>
 * <li><b>Then spares between members</b>: a member who needs none of an item
 * spares all of it. Every member of a Group Ironman group can trade with the
 * others, so there is no account-type check here.</li>
 * <li><b>Then group storage</b>, from the last snapshot anyone saw.</li>
 * </ol>
 *
 * <p>A member who shares no item counts is <em>unknown</em>: their need is in
 * {@link Line#unknownNeed()}, never in {@link Line#stillNeeded()}, because
 * telling the group to get what may be in that member's bank is the confident
 * wrong answer.
 */
final class ShopAllocation
{
	/** {@link GroupRoster#searchSources} files group storage under this. */
	static final String STORAGE_WHERE = "storage";

	private ShopAllocation()
	{
	}

	/** One member's part of one line. */
	static final class Share
	{
		final String member;
		final long need;
		final long held;
		final long received;
		final long fromStorage;
		final long shortBy;
		final boolean unknown;

		Share(String member, long need, long held, long received, long fromStorage, long shortBy, boolean unknown)
		{
			this.member = member;
			this.need = need;
			this.held = held;
			this.received = received;
			this.fromStorage = fromStorage;
			this.shortBy = shortBy;
			this.unknown = unknown;
		}
	}

	/** One item across the group. */
	static final class Line
	{
		final int itemId;
		final String name;
		final boolean tradeable;
		final boolean stated;
		final boolean obtainable;
		final Set<String> quests;
		final List<Share> shares;
		/** Everyone holding any, needed or not, in member order. */
		final Map<String, Long> holders;
		final long storageHeld;
		final long storageUsed;

		Line(int itemId, String name, boolean tradeable, boolean stated, boolean obtainable, Set<String> quests,
			List<Share> shares, Map<String, Long> holders, long storageHeld, long storageUsed)
		{
			this.itemId = itemId;
			this.name = name;
			this.tradeable = tradeable;
			this.stated = stated;
			this.obtainable = obtainable;
			this.quests = Collections.unmodifiableSet(quests);
			this.shares = Collections.unmodifiableList(shares);
			this.holders = Collections.unmodifiableMap(holders);
			this.storageHeld = storageHeld;
			this.storageUsed = storageUsed;
		}

		long totalNeeded()
		{
			long total = 0;
			for (Share s : shares)
			{
				total += s.need;
			}
			return total;
		}

		/** The headline: how many more the group has to get, members without shared items left out. */
		long stillNeeded()
		{
			long total = 0;
			for (Share s : shares)
			{
				total += s.shortBy;
			}
			return total;
		}

		/** Need from members who share no item counts, kept out of {@link #stillNeeded()}. */
		long unknownNeed()
		{
			long total = 0;
			for (Share s : shares)
			{
				total += s.unknown ? s.need : 0;
			}
			return total;
		}

		/** Ticked off: every known member is covered and nobody's need is unknown. */
		boolean done()
		{
			return stillNeeded() == 0 && unknownNeed() == 0;
		}

		/** What the group holds towards it: members' own and spares plus storage used. */
		long have()
		{
			return totalNeeded() - unknownNeed() - stillNeeded();
		}
	}

	/**
	 * Who holds what, as the group's shared data shows it. Names match the way the roster does ({@link
	 * GroupMembers#key}): "Iron_Bob" on a list and "Iron Bob" from the party are one member.
	 */
	static final class Holdings
	{
		/** By member key; a member absent here shares no item counts. */
		private final Map<String, Map<Integer, Long>> members = new LinkedHashMap<>();
		/** Each member key's name as the party spells it. */
		private final Map<String, String> names = new LinkedHashMap<>();
		/** Group storage as last seen; empty when nobody has seen it. */
		final Map<Integer, Long> storage;

		Holdings(Map<String, Map<Integer, Long>> members, Map<Integer, Long> storage)
		{
			members.forEach((name, items) ->
			{
				this.members.put(GroupMembers.key(name), items);
				this.names.putIfAbsent(GroupMembers.key(name), name);
			});
			this.storage = storage;
		}

		long held(String member, int itemId)
		{
			Map<Integer, Long> m = members.get(GroupMembers.key(member));
			return m == null ? 0 : m.getOrDefault(itemId, 0L);
		}

		/** What the whole group holds of {@code itemId}: every member who shares counts, and group storage. */
		long total(int itemId)
		{
			long sum = storage.getOrDefault(itemId, 0L);
			for (Map<Integer, Long> m : members.values())
			{
				sum += m.getOrDefault(itemId, 0L);
			}
			return sum;
		}

		boolean known(String member)
		{
			return members.containsKey(GroupMembers.key(member));
		}

		/**
		 * From everything "Who has it?" searches ({@link GroupRoster#searchSources}): each member's bank,
		 * inventory, equipment, rune pouch, quiver and seed vault added up, and group storage apart. Counts there
		 * are already canonical (noted counted as the item, {@link ItemCounts#add}).
		 */
		static Holdings from(List<GroupSearch.Source> sources)
		{
			Map<String, Map<Integer, Long>> members = new LinkedHashMap<>();
			Map<Integer, Long> storage = new LinkedHashMap<>();
			for (GroupSearch.Source s : sources)
			{
				Map<Integer, Long> into = STORAGE_WHERE.equals(s.where) ? storage
					: members.computeIfAbsent(s.member, k -> new LinkedHashMap<>());
				s.items.forEach((id, qty) -> into.merge(id, qty.longValue(), Long::sum));
			}
			return new Holdings(members, storage);
		}

		/** Every member who shares item counts, as the party spells them. */
		List<String> names()
		{
			return new ArrayList<>(names.values());
		}
	}

	/**
	 * @param needs every member the list is for, in display order, with what they need by item id
	 * @param tradeable false spends only each member's own holding; unknown items should answer false
	 */
	static List<Line> of(Map<String, Map<Integer, ShopNeeds.Need>> needs, Holdings holdings, IntPredicate tradeable)
	{
		Map<Integer, ShopNeeds.Need> items = new LinkedHashMap<>();
		for (Map<Integer, ShopNeeds.Need> m : needs.values())
		{
			for (ShopNeeds.Need n : m.values())
			{
				items.merge(n.itemId, n, ShopAllocation::describe);
			}
		}
		List<Line> lines = new ArrayList<>();
		for (ShopNeeds.Need item : items.values())
		{
			lines.add(new Allocation(item, needs, holdings, tradeable.test(item.itemId)).line());
		}
		lines.sort((a, b) -> a.name.compareToIgnoreCase(b.name));
		return lines;
	}

	/** Merges two members' needs for one item into the line's description; counts stay per member. */
	private static ShopNeeds.Need describe(ShopNeeds.Need a, ShopNeeds.Need b)
	{
		Set<String> quests = new TreeSet<>(a.quests);
		quests.addAll(b.quests);
		return new ShopNeeds.Need(a.itemId, a.name, 0, a.stated && b.stated, a.obtainable && b.obtainable, quests);
	}

	/** Spends holdings against one item's needs, in the order the class doc gives. */
	private static final class Allocation
	{
		private final ShopNeeds.Need item;
		private final Holdings holdings;
		private final boolean tradeable;
		private final List<String> order = new ArrayList<>();
		private final Map<String, long[]> slots = new LinkedHashMap<>();
		private final Map<String, Long> spare = new LinkedHashMap<>();
		private final long storageHeld;
		private long storageLeft;

		private static final int NEED = 0;
		private static final int HELD = 1;
		private static final int RECEIVED = 2;
		private static final int STORAGE = 3;
		private static final int SHORT = 4;

		Allocation(ShopNeeds.Need item, Map<String, Map<Integer, ShopNeeds.Need>> needs, Holdings holdings,
			boolean tradeable)
		{
			this.item = item;
			this.holdings = holdings;
			this.tradeable = tradeable;
			this.storageHeld = holdings.storage.getOrDefault(item.itemId, 0L);
			this.storageLeft = tradeable ? storageHeld : 0L;
			Set<String> keys = new java.util.HashSet<>();
			for (String m : needs.keySet())
			{
				order.add(m);
				keys.add(GroupMembers.key(m));
			}
			for (String m : holdings.names())
			{
				if (keys.add(GroupMembers.key(m)))
				{
					order.add(m);
				}
			}
			spendOwn(needs);
			if (tradeable)
			{
				pool();
				spendStorage();
			}
		}

		private void spendOwn(Map<String, Map<Integer, ShopNeeds.Need>> needs)
		{
			for (String member : order)
			{
				long held = holdings.held(member, item.itemId);
				Map<Integer, ShopNeeds.Need> theirs = needs.get(member);
				ShopNeeds.Need n = theirs == null ? null : theirs.get(item.itemId);
				long need = n == null ? 0 : n.count;
				long own = Math.min(held, need);
				boolean known = holdings.known(member);
				if (known && held > own)
				{
					spare.put(member, held - own);
				}
				if (need > 0)
				{
					slots.put(member, new long[]{need, held, 0L, 0L, known ? need - own : 0L});
				}
			}
		}

		private void pool()
		{
			for (Map.Entry<String, long[]> entry : slots.entrySet())
			{
				long[] slot = entry.getValue();
				for (String giver : order)
				{
					long available = spare.getOrDefault(giver, 0L);
					if (slot[SHORT] == 0 || giver.equals(entry.getKey()) || available == 0)
					{
						continue;
					}
					long given = Math.min(available, slot[SHORT]);
					spare.put(giver, available - given);
					slot[RECEIVED] += given;
					slot[SHORT] -= given;
				}
			}
		}

		private void spendStorage()
		{
			for (long[] slot : slots.values())
			{
				long taken = Math.min(storageLeft, slot[SHORT]);
				storageLeft -= taken;
				slot[STORAGE] += taken;
				slot[SHORT] -= taken;
			}
		}

		Line line()
		{
			List<Share> shares = new ArrayList<>();
			for (Map.Entry<String, long[]> entry : slots.entrySet())
			{
				long[] s = entry.getValue();
				shares.add(new Share(entry.getKey(), s[NEED], s[HELD], s[RECEIVED], s[STORAGE], s[SHORT],
					!holdings.known(entry.getKey())));
			}
			Map<String, Long> holders = new LinkedHashMap<>();
			for (String member : order)
			{
				long held = holdings.held(member, item.itemId);
				if (held > 0)
				{
					holders.put(member, held);
				}
			}
			long used = (tradeable ? storageHeld : 0L) - storageLeft;
			return new Line(item.itemId, item.name, tradeable, item.stated, item.obtainable, new TreeSet<>(item.quests),
				shares, holders, storageHeld, used);
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics;
import java.awt.Insets;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import javax.swing.plaf.basic.BasicHTML;
import javax.swing.text.View;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * The pieces every Shopping card is drawn from, lists and requests alike: a
 * header that folds the card with a one-line preview under it (Board
 * 2026-11-14), a thin progress bar, and text that wraps at the card's real
 * width.
 *
 * <p>Widths are in screen pixels. The tab's {@code <body style='width:175px'>}
 * labels are not: Swing's HTML reads CSS {@code px} as 1.3 screen pixels, so
 * that body is about 227 pixels wide and ran past a card's right edge ("For
 * GroupArk. Added by GroupShip, just r"). {@link Wrap} measures with the label's
 * own HTML view at a width given in pixels instead.
 */
final class ShopCards
{
	static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR.darker();
	static final Color DONE = ColorScheme.PROGRESS_COMPLETE_COLOR;
	/** The tab's content: the side panel (225) less the GIM panel's 8 + 8 border. */
	static final int TAB_TEXT = PluginPanel.PANEL_WIDTH - 16;
	/** Inside a card: less the card's 6 + 6 padding. */
	static final int CARD_TEXT = TAB_TEXT - 12;
	/** Beside a row's item icon (36) and gap (4). */
	static final int ROW_TEXT = CARD_TEXT - 40;
	/** Still-needed items whose icons the folded card shows. */
	static final int PREVIEW_ICONS = 3;

	private ShopCards()
	{
	}

	/** Plain text (escaped) that wraps at {@code width} screen pixels and asks for exactly the height it needs. */
	static final class Wrap extends JLabel
	{
		private final int width;

		Wrap(String text, Color color, int width)
		{
			super("<html>" + GroupIronmanPanel.escape(text) + "</html>");
			this.width = width;
			setFont(FontManager.getRunescapeSmallFont());
			setForeground(color);
			setVerticalAlignment(SwingConstants.TOP);
		}

		@Override
		public Dimension getPreferredSize()
		{
			View view = (View) getClientProperty(BasicHTML.propertyKey);
			Insets in = getInsets();
			if (view == null)
			{
				return super.getPreferredSize();
			}
			int icon = getIcon() == null ? 0 : getIcon().getIconWidth() + getIconTextGap();
			view.setSize(width - in.left - in.right - icon, 0);
			int height = (int) Math.ceil(view.getPreferredSpan(View.Y_AXIS));
			if (getIcon() != null)
			{
				height = Math.max(height, getIcon().getIconHeight());
			}
			return new Dimension(width, height + in.top + in.bottom);
		}

		@Override
		public Dimension getMaximumSize()
		{
			return getPreferredSize();
		}

		@Override
		public Dimension getMinimumSize()
		{
			return getPreferredSize();
		}
	}

	/** Text straight on the tab, outside any card. */
	static Wrap tabText(String text, Color color)
	{
		return new Wrap(text, color, TAB_TEXT);
	}

	/** A thin bar filled by {@code done} of {@code total}: green when full. */
	static final class Bar extends JComponent
	{
		private final long done;
		private final long total;

		Bar(long done, long total, int width)
		{
			this.done = done;
			this.total = total;
			Dimension d = new Dimension(width, 4);
			setPreferredSize(d);
			setMaximumSize(d);
			setMinimumSize(d);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			g.setColor(ColorScheme.DARK_GRAY_COLOR);
			g.fillRect(0, 0, getWidth(), getHeight());
			int fill = total <= 0 ? 0 : (int) Math.round(getWidth() * Math.min(1.0, done / (double) total));
			g.setColor(done >= total && total > 0 ? DONE : ColorScheme.BRAND_ORANGE);
			g.fillRect(0, 0, fill, getHeight());
		}
	}

	/** "0 of 39 done" / "Done: 39 of 39". */
	static String progress(int done, int total)
	{
		return done >= total && total > 0 ? "Done: " + done + " of " + total : done + " of " + total + " done";
	}

	/**
	 * The card's header: its title with the fold arrow (a click flips it), "3 of 39 done" and a bar, then while
	 * folded the first few still-needed items' icons and how many more.
	 */
	static void header(JPanel box, String title, boolean open, int done, int total, List<Integer> needed,
		ItemManager items, Runnable toggle)
	{
		Wrap name = new Wrap(title, done >= total && total > 0 ? DONE : Color.WHITE, CARD_TEXT);
		name.setIcon(new GroupIronmanPanel.Arrow(open));
		name.setIconTextGap(4);
		name.setFont(FontManager.getRunescapeBoldFont());
		Ui.clickable(name, toggle);
		box.add(name);
		box.add(new Wrap(progress(done, total), MUTED, CARD_TEXT));
		box.add(new Bar(done, total, CARD_TEXT));
		if (!open && !needed.isEmpty())
		{
			box.add(preview(needed, items, toggle));
		}
	}

	private static JPanel preview(List<Integer> needed, ItemManager items, Runnable toggle)
	{
		JPanel icons = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		icons.setOpaque(false);
		int shown = Math.min(PREVIEW_ICONS, needed.size());
		for (int id : needed.subList(0, shown))
		{
			JLabel icon = new JLabel();
			if (items != null)
			{
				items.getImage(id).addTo(icon);
			}
			icons.add(icon);
		}
		int more = needed.size() - shown;
		if (more > 0)
		{
			icons.add(Ui.label("+" + more + " more", FontManager.getRunescapeSmallFont(), MUTED));
		}
		icons.setMaximumSize(new Dimension(CARD_TEXT, 34));
		icons.setPreferredSize(new Dimension(CARD_TEXT, 34));
		Ui.clickable(icons, toggle);
		return icons;
	}

	/** "▸ 3 done": opens the card's finished items. */
	static JLabel doneToggle(int count, boolean open, Runnable toggle)
	{
		JLabel l = new JLabel(Amounts.GAME.of(count) + " done", new GroupIronmanPanel.Arrow(open), SwingConstants.LEFT);
		l.setIconTextGap(4);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(DONE);
		l.setBorder(new EmptyBorder(4, 0, 2, 0));
		Ui.clickable(l, toggle);
		return l;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collection;
import java.util.Set;
import java.util.TreeSet;

/**
 * What the player opened on the Shopping tab (Board 2026-11-14: lists start
 * collapsed with a preview, and opening one is remembered). Everything starts
 * closed: a list, a request, a list's "N done" section and an item's details.
 *
 * <p>Kept on this account only, never sent to the group: the plugin saves it in
 * the RuneLite profile of the logged-in character ({@link Store}). Keys of
 * lists that are gone are dropped on the next change, so the saved value never
 * grows past what is on screen.
 */
final class ShopFolds
{
	/** Where the open set is saved; {@code load} is null when nothing is (or no character is logged in). */
	interface Store
	{
		String load();

		void save(String value);
	}

	private final Store store;
	private final Set<String> open = new TreeSet<>();
	/** The saved value last read or written: a different one (another character) is read again. */
	private String seen;

	ShopFolds(Store store)
	{
		this.store = store;
	}

	static String list(String id)
	{
		return "l:" + id;
	}

	static String request(String id)
	{
		return "r:" + id;
	}

	/** A card's "N done" section. */
	static String done(String cardKey)
	{
		return "d:" + cardKey;
	}

	/** One item's details on one card. */
	static String item(String cardKey, int itemId)
	{
		return "i:" + cardKey + ":" + itemId;
	}

	boolean open(String key)
	{
		sync();
		return open.contains(key);
	}

	/** Opens a closed {@code key} or closes an open one, keeping only keys in {@code live}, then saves. */
	void toggle(String key, Collection<String> live)
	{
		sync();
		if (!open.remove(key))
		{
			open.add(key);
		}
		open.retainAll(live);
		seen = String.join(",", open);
		store.save(seen.isEmpty() ? null : seen);
	}

	private void sync()
	{
		String saved = store.load();
		if (saved == null || saved.equals(seen))
		{
			return;
		}
		open.clear();
		for (String key : saved.split(","))
		{
			if (!key.isEmpty())
			{
				open.add(key);
			}
		}
		seen = saved;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

/**
 * What one member needs for a preset: the item lines of the preset's quests
 * and every prerequisite they have not finished, merged by item.
 *
 * <p>Ported from Quest Path's {@code GroupShoppingNeeds} and {@code
 * ItemSplit} line rules (questpath-plugin ee638ff): optional lines, wiki lines
 * Quest Path could not match to an item, and category lines ("any pickaxe")
 * are not shopped for. A line with no stated count asks for one, and says
 * "at least" ({@link Need#stated()}).
 *
 * <p>A prerequisite only needs to be started (the wiki's "Started X") is
 * skipped once the member has started it. A finished quest is skipped with
 * everything behind it: the game would not have let them finish it otherwise.
 */
final class ShopNeeds
{
	private ShopNeeds()
	{
	}

	/** One item, across every quest that asks for it. */
	static final class Need
	{
		final int itemId;
		final String name;
		final long count;
		final boolean stated;
		final boolean obtainable;
		final Set<String> quests;

		Need(int itemId, String name, long count, boolean stated, boolean obtainable, Set<String> quests)
		{
			this.itemId = itemId;
			this.name = name;
			this.count = count;
			this.stated = stated;
			this.obtainable = obtainable;
			this.quests = Collections.unmodifiableSet(quests);
		}

		Need plus(Need other)
		{
			Set<String> q = new TreeSet<>(quests);
			q.addAll(other.quests);
			return new Need(itemId, name, count + other.count, stated && other.stated, obtainable && other.obtainable,
				q);
		}
	}

	/** The quests still to do for {@code roots}, prerequisites first. Roots the data lacks are skipped. */
	static List<QuestData.Quest> questsToDo(QuestData data, Collection<String> roots, QuestProgress progress)
	{
		Set<Long> seen = new LinkedHashSet<>();
		List<QuestData.Quest> out = new ArrayList<>();
		for (String root : roots)
		{
			QuestData.Quest q = data.quest(root);
			if (q != null)
			{
				visit(data, q, false, progress, seen, out);
			}
		}
		return out;
	}

	private static void visit(QuestData data, QuestData.Quest quest, boolean startedEnough, QuestProgress progress,
		Set<Long> seen, List<QuestData.Quest> out)
	{
		if (progress.finished(quest.name()) || startedEnough && progress.started(quest.name()) || !seen.add(quest.id()))
		{
			return;
		}
		for (long pre : quest.prerequisites())
		{
			QuestData.Quest p = data.quest(pre);
			if (p != null)
			{
				visit(data, p, quest.startedOnly(pre), progress, seen, out);
			}
		}
		out.add(quest);
	}

	/** Every quest {@code roots} reach, done or not: what the bundled data must carry. */
	static List<QuestData.Quest> closure(QuestData data, Collection<String> roots)
	{
		return questsToDo(data, roots, QuestProgress.UNKNOWN);
	}

	/** Whether a line is one to shop for; see the class doc. */
	static boolean shoppable(QuestData.Item item)
	{
		return !item.optional() && !item.unresolved() && !item.grouped() && !item.name().isEmpty()
			&& item.itemId() > 0;
	}

	/** One member's needs for {@code roots}, by item id, in quest order. */
	static Map<Integer, Need> forMember(QuestData data, Collection<String> roots, QuestProgress progress)
	{
		Map<Integer, Need> out = new LinkedHashMap<>();
		for (QuestData.Quest quest : questsToDo(data, roots, progress))
		{
			for (QuestData.Item item : quest.items())
			{
				if (!shoppable(item))
				{
					continue;
				}
				boolean stated = item.quantity() > 0;
				Need need = new Need(item.itemId(), item.name(), stated ? item.quantity() : 1, stated,
					item.obtainable(), Collections.singleton(quest.name()));
				out.merge(item.itemId(), need, Need::plus);
			}
		}
		return out;
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.annotations.SerializedName;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * The Shopping tab's prebuilt lists: one per build milestone, each naming the
 * quests it takes. A member's list is then those quests and every
 * prerequisite they have not done ({@link ShopNeeds}).
 *
 * <p>Read from {@code shopping-presets.json}, which {@code
 * scripts/gen-quest-items.py} also reads, so the bundled quest data always
 * carries every quest a preset reaches. The first build is the 1 Defence pure
 * (Board 2026-11-14); {@code QuestDataTest} fails if any quest a preset reaches
 * rewards Defence experience or needs Defence above 1.
 */
final class ShopPresets
{
	static final String RESOURCE = "shopping-presets.json";

	@SerializedName("presets")
	private List<Preset> presets;

	/** One milestone. */
	static final class Preset
	{
		@SerializedName("id")
		private String id;

		@SerializedName("name")
		private String name;

		@SerializedName("build")
		private String build;

		@SerializedName("note")
		private String note;

		@SerializedName("quests")
		private List<String> quests;

		@SerializedName("choose")
		private Choice choose;

		/** Stable: lists name their preset by this on the wire. */
		String id()
		{
			return id == null ? "" : id;
		}

		String name()
		{
			return name == null ? id() : name;
		}

		String build()
		{
			return build == null ? "" : build;
		}

		/** Shown under the list, e.g. which skill to pick for a reward; empty for none. */
		String note()
		{
			return note == null ? "" : note;
		}

		/** Always taken. */
		List<String> quests()
		{
			return quests == null ? Collections.emptyList() : quests;
		}

		/** Some of a set to pick from (Mithril gloves: 5 of 6 subquests), or null. */
		Choice choice()
		{
			return choose;
		}

		/**
		 * The quests this list is for: {@link #quests()} plus the picks. Picks
		 * that are not options are dropped; too few or too many fall back to the
		 * defaults, so a list never asks for the wrong number.
		 */
		List<String> roots(Collection<String> picks)
		{
			Set<String> out = new LinkedHashSet<>(quests());
			if (choose != null)
			{
				out.addAll(choose.valid(picks));
			}
			return new ArrayList<>(out);
		}
	}

	/** Pick {@code count} of {@code from}; {@code defaults} until the player changes them. */
	static final class Choice
	{
		@SerializedName("count")
		private int count;

		@SerializedName("from")
		private List<String> from;

		@SerializedName("defaults")
		private List<String> defaults;

		int count()
		{
			return count;
		}

		List<String> from()
		{
			return from == null ? Collections.emptyList() : from;
		}

		List<String> defaults()
		{
			return defaults == null ? Collections.emptyList() : defaults;
		}

		/** {@code picks} when it is exactly {@link #count} options, otherwise the defaults. */
		List<String> valid(Collection<String> picks)
		{
			if (picks == null)
			{
				return defaults();
			}
			Set<String> kept = new LinkedHashSet<>();
			for (String option : from())
			{
				if (picks.contains(option))
				{
					kept.add(option);
				}
			}
			return kept.size() == count ? new ArrayList<>(kept) : defaults();
		}
	}

	List<Preset> presets()
	{
		return presets == null ? Collections.emptyList() : presets;
	}

	/** One preset by id, or null (a list from a newer build naming one this build lacks). */
	Preset preset(String id)
	{
		for (Preset p : presets())
		{
			if (p.id().equals(id))
			{
				return p;
			}
		}
		return null;
	}

	static ShopPresets load(Gson gson)
	{
		try (InputStream in = ShopPresets.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				return new ShopPresets();
			}
			ShopPresets out = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), ShopPresets.class);
			return out == null ? new ShopPresets() : out;
		}
		catch (IOException | JsonParseException e)
		{
			return new ShopPresets();
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Where the player reading the list can get an item: the shops they can be
 * served at, with a price where the wiki gave one, and the monsters that drop
 * it. Group ironmen have no Grand Exchange, so it is never offered.
 *
 * <p>Ported from Quest Path's {@code groupshop.ItemSources} and {@code
 * ShopReachability} (questpath-plugin ee638ff). A shop behind a skill level or
 * a quest this player lacks is never listed, only counted ({@link
 * Options#unreachableShops}), so "no shop" and "no shop you can use" stay
 * different answers. A gate that cannot be judged (an unknown quest) counts as
 * closed, and a boostable gate is judged on the real level: walking to a shop
 * hoping for a boost is the wasted trip this exists to prevent.
 */
final class ShopSources
{
	/** "Shop: Tynan's Fishing Supplies (2 Coins)". */
	private static final Pattern SHOP_PRICE = Pattern.compile("^Shop: (.+) \\(([\\d,]+) Coins\\)$");
	private static final Pattern DROP = Pattern.compile("^Drop: (.+?)(?: \\((.+)\\))?$");

	private ShopSources()
	{
	}

	/** The player reading the list: real levels by lowercase skill name, and quest progress. */
	static final class Viewer
	{
		final Map<String, Integer> levels;
		final QuestProgress quests;

		Viewer(Map<String, Integer> levels, QuestProgress quests)
		{
			Map<String, Integer> lower = new HashMap<>();
			levels.forEach((k, v) -> lower.put(k.toLowerCase(Locale.ROOT), v));
			this.levels = Collections.unmodifiableMap(lower);
			this.quests = quests;
		}

		int level(String skill)
		{
			return levels.getOrDefault(skill.toLowerCase(Locale.ROOT), 1);
		}
	}

	/** One place to get an item. */
	static final class Source
	{
		final boolean shop;
		final String name;
		/** Coins, or -1 when the wiki line gave none. */
		final long price;
		/** Drop rate words ("Always", "1/128") or the region ("wilderness"); empty for none. */
		final String detail;

		Source(boolean shop, String name, long price, String detail)
		{
			this.shop = shop;
			this.name = name;
			this.price = price;
			this.detail = detail;
		}

		/** "Shop: Tynan's Fishing Supplies (2 gp)", "Drop: Goblin (Always)". */
		String describe()
		{
			String head = (shop ? "Shop: " : "Drop: ") + name;
			if (shop)
			{
				return price >= 0 ? head + " (" + Amounts.GAME.of(price) + " gp)" : head;
			}
			return detail.isEmpty() ? head : head + " (" + detail + ")";
		}
	}

	/** Every usable source, shops first, and how many shops were left out. */
	static final class Options
	{
		final List<Source> sources;
		final int unreachableShops;

		Options(List<Source> sources, int unreachableShops)
		{
			this.sources = Collections.unmodifiableList(sources);
			this.unreachableShops = unreachableShops;
		}
	}

	/** Why a shop will not serve the viewer, in the shop's own terms; empty when it will. */
	static String blockedBy(QuestData.Shop shop, Viewer viewer, QuestData data)
	{
		QuestData.Reachability gates = shop == null ? null : shop.reachability();
		if (gates == null || viewer == null)
		{
			return "";
		}
		List<String> blocked = new ArrayList<>();
		if (gates.unknown())
		{
			blocked.add("requirements Quest Path could not read");
		}
		for (QuestData.Level gate : gates.requiredSkills())
		{
			if (viewer.level(gate.skill()) < gate.level())
			{
				blocked.add(gate.level() + " " + gate.skill());
			}
		}
		for (Long id : gates.requiredQuestIds())
		{
			String missing = missingQuest(id, gates, viewer, data);
			if (missing != null)
			{
				blocked.add(missing);
			}
		}
		return String.join(", ", blocked);
	}

	/** The quest gate's name when the viewer has not met it, or null when they have. */
	private static String missingQuest(Long id, QuestData.Reachability gates, Viewer viewer, QuestData data)
	{
		String quest = id == null ? null : data.questName(id);
		if (quest == null)
		{
			return "an unknown quest";
		}
		boolean met = gates.startedOnly(id) ? viewer.quests.started(quest) : viewer.quests.finished(quest);
		return met ? null : quest;
	}

	/**
	 * Where {@code viewer} can get item {@code itemId}: the quest data's shops and drops ({@code item}, null when
	 * no quest names it), then the bundled wiki drop table ({@link ItemDrops}) for monsters it does not name.
	 */
	static Options forViewer(int itemId, QuestData.Item item, Viewer viewer, QuestData data, ItemDrops table)
	{
		Options quest = forViewer(item, viewer, data);
		List<Source> all = new ArrayList<>(quest.sources);
		all.addAll(table.of(itemId));
		return new Options(dedupe(all), quest.unreachableShops);
	}

	/** Where {@code viewer} can get {@code item}, as the quest data has it. */
	static Options forViewer(QuestData.Item item, Viewer viewer, QuestData data)
	{
		List<Source> out = new ArrayList<>();
		if (item == null)
		{
			return new Options(out, 0);
		}
		Map<String, Long> prices = prices(item.sources());
		int unreachable = 0;
		// The data repeats some shop names; each shop is judged once.
		for (String name : new java.util.LinkedHashSet<>(item.shopNames()))
		{
			QuestData.Shop shop = data.shop(name);
			if (shop != null && blockedBy(shop, viewer, data).isEmpty())
			{
				out.add(new Source(true, name, prices.getOrDefault(name, -1L), ""));
			}
			else
			{
				unreachable++;
			}
		}
		out.addAll(drops(item, data));
		return new Options(dedupe(out), unreachable);
	}

	/** The wiki's prices, by shop name, from its "Shop: X (N Coins)" lines. */
	static Map<String, Long> prices(List<String> sources)
	{
		Map<String, Long> out = new HashMap<>();
		for (String s : sources)
		{
			Matcher m = SHOP_PRICE.matcher(s);
			if (m.matches())
			{
				out.putIfAbsent(m.group(1), Long.parseLong(m.group(2).replace(",", "")));
			}
		}
		return out;
	}

	/** The wiki's own drop lines first (with their rate), then every other dropper it names. */
	private static List<Source> drops(QuestData.Item item, QuestData data)
	{
		Map<String, Source> out = new LinkedHashMap<>();
		for (String s : item.sources())
		{
			Matcher m = DROP.matcher(s);
			if (m.matches())
			{
				out.putIfAbsent(m.group(1), new Source(false, m.group(1), -1, m.group(2) == null ? "" : m.group(2)));
			}
		}
		for (String name : item.dropSourceNames())
		{
			out.putIfAbsent(name, new Source(false, name, -1, region(name, data)));
		}
		return new ArrayList<>(out.values());
	}

	/** "Wilderness" when the only known place for it is there: worth saying before anyone walks in. */
	private static String region(String monster, QuestData data)
	{
		boolean any = false;
		for (QuestData.DropLocation at : data.dropLocations())
		{
			if (at.sourceName().equals(monster))
			{
				if (!"wilderness".equalsIgnoreCase(at.region()))
				{
					return "";
				}
				any = true;
			}
		}
		return any ? "Wilderness" : "";
	}

	private static List<Source> dedupe(List<Source> sources)
	{
		Map<String, Source> out = new LinkedHashMap<>();
		for (Source s : sources)
		{
			out.putIfAbsent((s.shop ? "s:" : "d:") + s.name, s);
		}
		return new ArrayList<>(out.values());
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * When to say "this shop sells something your group still needs": once as
 * this player comes up on the shop, and not again until they have walked away.
 * The "Shopping: shop alert" setting is off by default; this only decides
 * when, {@link ShoppingBoard#byShop} decides which shops.
 *
 * <p>Like Quest Path's shop approach alert, from the shop's own tile in the
 * quest data. Client thread only.
 */
final class ShopVisits
{
	/** Tiles from the shop's tile that count as being at it. */
	static final int NEAR = 8;
	/** Tiles away that end a visit, so the next approach alerts again. */
	static final int LEFT = 20;

	private final Set<String> inside = new HashSet<>();

	/** The shops among {@code candidates} this player has just come up on. */
	List<String> arrived(int x, int y, int plane, Iterable<String> candidates, QuestData data)
	{
		List<String> out = new ArrayList<>();
		Set<String> seen = new HashSet<>();
		for (String name : candidates)
		{
			QuestData.Shop shop = data.shop(name);
			if (shop == null)
			{
				continue;
			}
			seen.add(name);
			int d = shop.plane == plane ? Math.max(Math.abs(shop.x - x), Math.abs(shop.y - y)) : Integer.MAX_VALUE;
			if (d <= NEAR && inside.add(name))
			{
				out.add(name);
			}
			else if (d > LEFT)
			{
				inside.remove(name);
			}
		}
		// A shop with nothing left to buy is forgotten too, so a new need there alerts on the next approach.
		inside.retainAll(seen);
		return out;
	}

	void reset()
	{
		inside.clear();
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;

/**
 * What the Shopping tab shows for each live list: every item line with what
 * the group still has to get, who holds what, and where this player can get
 * it. Pure: the plugin captures the inputs, the panel draws the cards.
 */
final class ShoppingBoard
{
	/** One item line, with where the viewer can get it. */
	static final class Row
	{
		final ShopAllocation.Line line;
		final ShopSources.Options sources;

		Row(ShopAllocation.Line line, ShopSources.Options sources)
		{
			this.line = line;
			this.sources = sources;
		}
	}

	/** One list, worked out. */
	static final class Card
	{
		final ShoppingList list;
		/** The preset, or null for a custom list or a preset this build lacks. */
		final ShopPresets.Preset preset;
		final List<Row> rows;
		/** Members on the list whose quest progress this client has not heard: every quest counts for them. */
		final List<String> progressUnknown;
		/** Members on the list who share no item counts: their need is not judged. */
		final List<String> itemsUnknown;

		Card(ShoppingList list, ShopPresets.Preset preset, List<Row> rows, List<String> progressUnknown,
			List<String> itemsUnknown)
		{
			this.list = list;
			this.preset = preset;
			this.rows = Collections.unmodifiableList(rows);
			this.progressUnknown = Collections.unmodifiableList(progressUnknown);
			this.itemsUnknown = Collections.unmodifiableList(itemsUnknown);
		}

		int done()
		{
			int n = 0;
			for (Row r : rows)
			{
				n += r.line.done() ? 1 : 0;
			}
			return n;
		}

		/** A preset the data has nothing left for, or a custom list with no items: nothing to show but that. */
		boolean empty()
		{
			return rows.isEmpty();
		}
	}

	/** Everything a board needs; captured on the client side. */
	static final class Inputs
	{
		final QuestData data;
		final ShopPresets presets;
		final Function<String, QuestProgress> progress;
		final ShopAllocation.Holdings holdings;
		final IntPredicate tradeable;
		final IntFunction<String> names;
		final ShopSources.Viewer viewer;

		Inputs(QuestData data, ShopPresets presets, Function<String, QuestProgress> progress,
			ShopAllocation.Holdings holdings, IntPredicate tradeable, IntFunction<String> names,
			ShopSources.Viewer viewer)
		{
			this.data = data;
			this.presets = presets;
			this.progress = progress;
			this.holdings = holdings;
			this.tradeable = tradeable;
			this.names = names;
			this.viewer = viewer;
		}
	}

	private ShoppingBoard()
	{
	}

	static List<Card> of(List<ShoppingList> lists, Inputs in)
	{
		List<Card> out = new ArrayList<>();
		for (ShoppingList l : lists)
		{
			out.add(card(l, in));
		}
		return out;
	}

	static Card card(ShoppingList list, Inputs in)
	{
		ShopPresets.Preset preset = list.custom() ? null : in.presets.preset(list.preset);
		Map<String, Map<Integer, ShopNeeds.Need>> needs = new LinkedHashMap<>();
		List<String> progressUnknown = new ArrayList<>();
		List<String> itemsUnknown = new ArrayList<>();
		for (String member : list.members)
		{
			if (preset != null)
			{
				QuestProgress p = in.progress.apply(member);
				if (!p.known())
				{
					progressUnknown.add(member);
				}
				needs.put(member, ShopNeeds.forMember(in.data, preset.roots(list.picks), p));
			}
			else
			{
				needs.put(member, custom(list, in.names));
			}
			if (!in.holdings.known(member))
			{
				itemsUnknown.add(member);
			}
		}
		List<Row> rows = new ArrayList<>();
		for (ShopAllocation.Line line : ShopAllocation.of(needs, in.holdings, in.tradeable))
		{
			rows.add(new Row(line, ShopSources.forViewer(line.itemId, in.data.item(line.itemId), in.viewer, in.data,
				ItemDrops.bundled())));
		}
		return new Card(list, preset, rows, progressUnknown, itemsUnknown);
	}

	private static Map<Integer, ShopNeeds.Need> custom(ShoppingList list, IntFunction<String> names)
	{
		Map<Integer, ShopNeeds.Need> out = new LinkedHashMap<>();
		list.items.forEach((id, qty) -> out.put(id, new ShopNeeds.Need(id, names.apply(id), qty, true, false,
			Collections.emptySet())));
		return out;
	}

	/**
	 * Shops this player can be served at, each with the still-needed lines it sells, across every list. A covered
	 * line, or one only members without shared items need, never makes a shop a candidate.
	 */
	static Map<String, List<ShopAllocation.Line>> byShop(List<Card> cards)
	{
		Map<String, List<ShopAllocation.Line>> out = new LinkedHashMap<>();
		for (Card c : cards)
		{
			for (Row r : c.rows)
			{
				if (r.line.stillNeeded() <= 0)
				{
					continue;
				}
				for (ShopSources.Source s : r.sources.sources)
				{
					if (s.shop)
					{
						out.computeIfAbsent(s.name, k -> new ArrayList<>()).add(r.line);
					}
				}
			}
		}
		return out;
	}

	/** "your group needs 4 more Bucket, 3 more Rope and 2 other items"; empty for no lines. */
	static String describe(List<ShopAllocation.Line> lines)
	{
		if (lines == null || lines.isEmpty())
		{
			return "";
		}
		StringBuilder text = new StringBuilder("your group needs ");
		int named = Math.min(3, lines.size());
		for (int i = 0; i < named; i++)
		{
			ShopAllocation.Line line = lines.get(i);
			text.append(i == 0 ? "" : ", ").append(Amounts.GAME.of(line.stillNeeded())).append(" more ")
				.append(line.name);
		}
		int rest = lines.size() - named;
		if (rest > 0)
		{
			text.append(" and ").append(rest).append(" other item").append(rest == 1 ? "" : "s");
		}
		return text.toString();
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import static com.vinnyvangogh.groupironman.GroupCodec.flag;
import static com.vinnyvangogh.groupironman.GroupCodec.header;
import static com.vinnyvangogh.groupironman.GroupCodec.string;

/**
 * The Shopping tab's two kinds inside a {@link VvgGroupIronmanMessage}, next
 * to {@link GroupCodec}'s and {@link GovernanceCodec}'s:
 *
 * <ul>
 * <li>{@code shop}: one {@link ShoppingList} revision, removals included.</li>
 * <li>{@code qstate}: the sender's progress in the bundled quests
 * ({@link QuestProgress}), so a preset counts only what each member still has
 * to do.</li>
 * <li>{@code req}: one {@link RequestList} revision, a member's own request.</li>
 * <li>{@code rqc}: one {@link RequestClaim}, a member's "I'll get it".</li>
 * </ul>
 *
 * <p>A build without the Shopping tab (gim-test-3 and older) reads all four as
 * an unknown kind and ignores them, and the first Shopping tab build looks
 * only for {@code shop} and {@code qstate}, so requests pass it by the same
 * way; this build ignores kinds it does not know the same way. Every field is
 * capped, and the same JSON is what the group cache keeps between sessions.
 */
final class ShoppingCodec
{
	static final String SHOP = "shop";
	static final String QUESTS = "qstate";
	static final String REQUEST = "req";
	static final String CLAIM = "rqc";
	/** Well over the bundled data's quest count; a newer build's extra names are read and then dropped. */
	static final int MAX_QUESTS = 300;

	private ShoppingCodec()
	{
	}

	/** A cheap look before decoding: every party message passes through here. */
	static boolean isShopping(String payload)
	{
		if (payload == null)
		{
			return false;
		}
		for (String kind : new String[]{SHOP, QUESTS, REQUEST, CLAIM})
		{
			if (payload.contains("\"k\":\"" + kind + "\""))
			{
				return true;
			}
		}
		return false;
	}

	/** Exactly one of the fields is set. */
	static final class Message
	{
		final ShoppingList list;
		final QuestProgress quests;
		final RequestList request;
		final RequestClaim claim;

		Message(ShoppingList list, QuestProgress quests)
		{
			this(list, quests, null, null);
		}

		Message(ShoppingList list, QuestProgress quests, RequestList request, RequestClaim claim)
		{
			this.list = list;
			this.quests = quests;
			this.request = request;
			this.claim = claim;
		}
	}

	static String encode(Gson gson, RequestList r)
	{
		JsonObject o = header(REQUEST);
		o.addProperty("id", r.id);
		o.addProperty("o", r.owner);
		o.addProperty("n", r.name);
		o.add("i", ItemCounts.toJson(r.items));
		JsonArray shut = new JsonArray();
		r.closedItems.forEach(shut::add);
		o.add("ci", shut);
		if (r.closed)
		{
			o.addProperty("cl", true);
		}
		if (r.removed)
		{
			o.addProperty("x", true);
		}
		o.addProperty("r", r.rev);
		o.addProperty("ts", r.at);
		o.addProperty("c", r.created);
		o.addProperty("a", r.action);
		return gson.toJson(o);
	}

	static String encode(Gson gson, RequestClaim c)
	{
		JsonObject o = header(CLAIM);
		o.addProperty("id", c.requestId);
		o.addProperty("i", c.itemId);
		o.addProperty("m", c.member);
		o.addProperty("y", c.claimed);
		o.addProperty("ts", c.at);
		return gson.toJson(o);
	}

	static String encode(Gson gson, ShoppingList l)
	{
		JsonObject o = header(SHOP);
		o.addProperty("id", l.id);
		o.addProperty("n", l.name);
		o.addProperty("p", l.preset);
		o.add("pk", strings(l.picks));
		o.add("m", strings(l.members));
		o.add("i", ItemCounts.toJson(l.items));
		o.addProperty("r", l.rev);
		o.addProperty("ts", l.at);
		o.addProperty("by", l.by);
		o.addProperty("a", l.action);
		if (l.removed)
		{
			o.addProperty("x", true);
		}
		o.addProperty("c", l.created);
		o.addProperty("cb", l.createdBy);
		return gson.toJson(o);
	}

	static String encode(Gson gson, QuestProgress p)
	{
		JsonObject o = header(QUESTS);
		o.add("f", strings(p.finished()));
		o.add("s", strings(p.inProgress()));
		return gson.toJson(o);
	}

	/** The message in {@code json}, or null when it is none of the kinds or not readable. */
	static Message decode(Gson gson, String json)
	{
		JsonObject in = GroupCodec.object(gson, json, GroupCodec.MAX_PAYLOAD_CHARS * 2);
		if (in == null)
		{
			return null;
		}
		try
		{
			return read(string(in, "k"), in);
		}
		catch (RuntimeException e)
		{
			// A field of the wrong type: not a list anyone sent.
			return null;
		}
	}

	private static Message read(String kind, JsonObject in)
	{
		switch (kind)
		{
			case SHOP:
				ShoppingList l = list(in);
				return l == null ? null : new Message(l, null);
			case REQUEST:
				RequestList r = request(in);
				return r == null ? null : new Message(null, null, r, null);
			case CLAIM:
				RequestClaim c = claim(in);
				return c == null ? null : new Message(null, null, null, c);
			case QUESTS:
				return new Message(null, QuestProgress.of(names(in.get("f")), names(in.get("s"))));
			default:
				return null;
		}
	}

	private static ShoppingList list(JsonObject in)
	{
		String id = string(in, "id");
		Long rev = ItemCounts.longValue(in.get("r"));
		Long at = ItemCounts.longValue(in.get("ts"));
		if (!ShoppingList.validId(id) || rev == null || rev < 1 || at == null || at < 0)
		{
			return null;
		}
		Long created = ItemCounts.longValue(in.get("c"));
		boolean removed = flag(in, "x");
		return new ShoppingList(id, string(in, "n"), string(in, "p"), names(in.get("pk")), names(in.get("m")),
			ItemCounts.fromJson(in.get("i"), ShoppingList.MAX_ITEMS), rev, at, string(in, "by"), string(in, "a"),
			removed, created == null ? at : created, string(in, "cb"));
	}

	private static RequestList request(JsonObject in)
	{
		String id = string(in, "id");
		String owner = string(in, "o");
		Long rev = ItemCounts.longValue(in.get("r"));
		Long at = ItemCounts.longValue(in.get("ts"));
		if (!ShoppingList.validId(id) || owner.trim().isEmpty() || rev == null || rev < 1 || at == null || at < 0)
		{
			return null;
		}
		Long created = ItemCounts.longValue(in.get("c"));
		return new RequestList(id, owner, string(in, "n"), ItemCounts.fromJson(in.get("i"), ShoppingList.MAX_ITEMS),
			ids(in.get("ci")), flag(in, "cl"), flag(in, "x"), rev, at, created == null ? at : created,
			string(in, "a"));
	}

	private static RequestClaim claim(JsonObject in)
	{
		String id = string(in, "id");
		String member = string(in, "m");
		Long item = ItemCounts.longValue(in.get("i"));
		Long at = ItemCounts.longValue(in.get("ts"));
		if (!ShoppingList.validId(id) || member.trim().isEmpty() || item == null || item <= 0
			|| item >= ItemCounts.MAX_ITEM_ID || at == null || at < 0)
		{
			return null;
		}
		return new RequestClaim(id, item.intValue(), member, flag(in, "y"), at);
	}

	private static List<Integer> ids(JsonElement e)
	{
		List<Integer> out = new ArrayList<>();
		if (e == null || !e.isJsonArray())
		{
			return out;
		}
		for (JsonElement i : e.getAsJsonArray())
		{
			Long id = out.size() < ShoppingList.MAX_ITEMS ? ItemCounts.longValue(i) : null;
			if (id != null && id > 0 && id < ItemCounts.MAX_ITEM_ID)
			{
				out.add(id.intValue());
			}
		}
		return out;
	}

	private static List<String> names(JsonElement e)
	{
		List<String> out = new ArrayList<>();
		if (e == null || !e.isJsonArray())
		{
			return out;
		}
		for (JsonElement s : e.getAsJsonArray())
		{
			if (out.size() >= MAX_QUESTS)
			{
				break;
			}
			if (s.isJsonPrimitive())
			{
				out.add(ShoppingList.cap(s.getAsString(), ShoppingList.MAX_TEXT));
			}
		}
		return out;
	}

	private static JsonArray strings(Collection<String> values)
	{
		JsonArray out = new JsonArray();
		values.forEach(out::add);
		return out;
	}
}

package com.vinnyvangogh.groupironman;

import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.regex.Pattern;

/**
 * One shared shopping list: a preset (with its picks) or custom items, for
 * one or more members. Immutable; every change is a new revision, and the
 * newest revision wins everywhere ({@link #newerThan}), so the group agrees
 * without a server.
 *
 * <p>A removed list stays as a tombstone ({@link #removed}) so the removal
 * reaches members who were offline, instead of their copy bringing it back.
 */
final class ShoppingList
{
	static final int MAX_NAME = 40;
	static final int MAX_MEMBERS = 10;
	static final int MAX_ITEMS = 60;
	static final int MAX_PICKS = 10;
	/** A display name is at most 12; quest names run longer. */
	static final int MAX_TEXT = 80;
	static final int MAX_QUANTITY = 1_000_000;
	private static final Pattern ID = Pattern.compile("[a-z0-9]{1,16}");
	private static final SecureRandom RANDOM = new SecureRandom();

	static final String ADDED = "added";
	static final String RENAMED = "renamed";
	static final String REMOVED = "removed";

	final String id;
	final String name;
	/** The preset's id, empty for a custom list. */
	final String preset;
	final List<String> picks;
	final List<String> members;
	/** A custom list's items, each per member. */
	final Map<Integer, Integer> items;
	final long rev;
	final long at;
	final String by;
	final String action;
	final boolean removed;
	final long created;
	final String createdBy;

	ShoppingList(String id, String name, String preset, Collection<String> picks, Collection<String> members,
		Map<Integer, Integer> items, long rev, long at, String by, String action, boolean removed, long created,
		String createdBy)
	{
		this.id = id;
		this.name = cap(name, MAX_NAME);
		this.preset = cap(preset, MAX_TEXT);
		this.picks = capList(picks, MAX_PICKS);
		this.members = capList(members, MAX_MEMBERS);
		this.items = capItems(items);
		this.rev = rev;
		this.at = at;
		this.by = cap(by, MAX_TEXT);
		this.action = cap(action, 16);
		this.removed = removed;
		this.created = created;
		this.createdBy = cap(createdBy, MAX_TEXT);
	}

	/** A new list, revision 1. */
	static ShoppingList create(String name, String preset, Collection<String> picks, Collection<String> members,
		Map<Integer, Integer> items, String self, long now)
	{
		return new ShoppingList(newId(), name, preset, picks, members, items, 1, now, self, ADDED, false, now, self);
	}

	static String newId()
	{
		return Long.toString(RANDOM.nextLong() & Long.MAX_VALUE, 36);
	}

	static boolean validId(String id)
	{
		return id != null && ID.matcher(id).matches();
	}

	boolean custom()
	{
		return preset.isEmpty();
	}

	/** True when this revision should replace {@code other}: a higher revision, then later, then by name. */
	boolean newerThan(ShoppingList other)
	{
		if (other == null)
		{
			return true;
		}
		int order = order(rev, at, other.rev, other.at);
		if (order != 0)
		{
			return order > 0;
		}
		return by.compareTo(other.by) > 0 || by.equals(other.by) && removed && !other.removed;
	}

	/** Revisions in order: the higher revision, then the later one; 0 on a tie. Requests share it. */
	static int order(long rev, long at, long otherRev, long otherAt)
	{
		return rev != otherRev ? Long.compare(rev, otherRev) : Long.compare(at, otherAt);
	}

	private ShoppingList next(String newName, Collection<String> newMembers, Map<Integer, Integer> newItems,
		String self, long now, String newAction, boolean gone)
	{
		return new ShoppingList(id, newName, preset, picks, newMembers, newItems, rev + 1, Math.max(now, at), self,
			newAction, gone, created, createdBy);
	}

	ShoppingList renamed(String newName, String self, long now)
	{
		return next(newName, members, items, self, now, RENAMED, false);
	}

	ShoppingList removedBy(String self, long now)
	{
		return next(name, members, items, self, now, REMOVED, true);
	}

	static String cap(String s, int max)
	{
		String t = s == null ? "" : s.trim();
		return t.length() > max ? t.substring(0, max) : t;
	}

	private static List<String> capList(Collection<String> in, int max)
	{
		List<String> out = new ArrayList<>();
		for (String s : in == null ? Collections.<String>emptyList() : in)
		{
			String t = cap(s, MAX_TEXT);
			if (!t.isEmpty() && !out.contains(t) && out.size() < max)
			{
				out.add(t);
			}
		}
		return Collections.unmodifiableList(out);
	}

	/** Real item ids with a positive count, at most {@link #MAX_ITEMS}; requests ({@link RequestList}) share it. */
	static Map<Integer, Integer> capItems(Map<Integer, Integer> in)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		for (Map.Entry<Integer, Integer> e : in == null ? Collections.<Integer, Integer>emptyMap().entrySet()
			: in.entrySet())
		{
			int id = e.getKey() == null ? 0 : e.getKey();
			int qty = e.getValue() == null ? 0 : e.getValue();
			if (id > 0 && id < ItemCounts.MAX_ITEM_ID && qty > 0 && out.size() < MAX_ITEMS)
			{
				out.put(id, Math.min(qty, MAX_QUANTITY));
			}
		}
		return Collections.unmodifiableMap(out);
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.function.Consumer;

/**
 * The group's shared shopping lists, and each member's quest progress, kept in
 * step over the party. No server: every client holds every list, the newest
 * revision of each wins ({@link ShoppingList#newerThan}), and a member who
 * joins is sent everything (their {@code UserSync}).
 *
 * <p><b>When it sends.</b> Never on a timer of its own: a change marks the
 * list, and {@link #flush} sends it on the next game tick while connected to
 * the group's party. This player's quest progress goes only while some list is
 * for them, so a fresh install that nobody has made a list for sends nothing.
 *
 * <p>Kept in the group cache file (the {@code shop} entry), never the config.
 * Thread-safe: party messages, the client thread and the panel all call in.
 */
final class ShoppingSync
{
	/** Lists kept, removed ones included; a full book refuses new lists rather than forgetting live ones. */
	static final int MAX_LISTS = 40;
	static final int MAX_HISTORY = 20;
	/** A removed list is forgotten after this long: every member has long since heard. */
	static final long TOMBSTONE_MS = 30L * 24 * 60 * 60 * 1000;

	/** One line of "who did what". */
	static final class Change
	{
		final long at;
		final String text;

		Change(long at, String text)
		{
			this.at = at;
			this.text = text;
		}
	}

	private final Gson gson;
	private final Consumer<String> send;
	private final Runnable onChange;
	private final Map<String, ShoppingList> lists = new LinkedHashMap<>();
	private final Deque<Change> history = new ArrayDeque<>();
	/** By {@link GroupMembers#key}. */
	private final Map<String, QuestProgress> progress = new TreeMap<>();
	private final Set<String> dirty = new LinkedHashSet<>();
	/** Members' requests and claims: the same messages, tick and cache entry as the lists. */
	private final RequestBook requests = new RequestBook();
	private boolean progressDirty;

	ShoppingSync(Gson gson, Consumer<String> send, Runnable onChange)
	{
		this.gson = gson;
		this.send = send;
		this.onChange = onChange;
	}

	/** A cheap look before decoding. */
	static boolean isShopping(String payload)
	{
		return ShoppingCodec.isShopping(payload);
	}

	// ---- This player's actions ----

	/** False when the book is full. */
	boolean add(ShoppingList list)
	{
		boolean ok;
		synchronized (this)
		{
			ok = accept(list, true);
		}
		if (ok)
		{
			onChange.run();
		}
		return ok;
	}

	/** Custom lists only: a preset's name is the preset's. False when there is no such live list. */
	boolean rename(String id, String name, String self, long now)
	{
		String clean = ShoppingList.cap(name, ShoppingList.MAX_NAME);
		return change(id, l -> l.custom() && !clean.isEmpty() && !clean.equals(l.name)
			? l.renamed(clean, self, now) : null);
	}

	boolean remove(String id, String self, long now)
	{
		return change(id, l -> l.removedBy(self, now));
	}

	private boolean change(String id, java.util.function.Function<ShoppingList, ShoppingList> edit)
	{
		boolean ok = false;
		synchronized (this)
		{
			ShoppingList current = lists.get(id);
			ShoppingList next = current == null || current.removed ? null : edit.apply(current);
			if (next != null)
			{
				ok = accept(next, true);
			}
		}
		if (ok)
		{
			onChange.run();
		}
		return ok;
	}

	// ---- This player's requests ----

	/** A new request of this player's own; false with no items or a full book. */
	boolean addRequest(RequestList r)
	{
		if (r.items.isEmpty() || r.removed)
		{
			return false;
		}
		boolean ok;
		synchronized (this)
		{
			ok = takeRequest(r, true);
		}
		return changed(ok);
	}

	boolean renameRequest(String id, String name, String self, long now)
	{
		String clean = ShoppingList.cap(name, ShoppingList.MAX_NAME);
		return editRequest(id, self, r -> !clean.isEmpty() && !clean.equals(r.name) ? r.renamed(clean, now)
			: null) != null;
	}

	boolean removeRequest(String id, String self, long now)
	{
		return editRequest(id, self, r -> r.removedBy(now)) != null;
	}

	/** The owner closes the whole list, done or not. */
	boolean closeRequest(String id, String self, long now)
	{
		return editRequest(id, self, r -> r.closed ? null : r.closedBy(now)) != null;
	}

	/**
	 * The owner closes these items (by hand, or because the group holds them); the list closes with its last.
	 * Returns the new revision, or null when nothing changed or this player is not the owner.
	 */
	RequestList closeItems(String id, Set<Integer> items, String self, long now)
	{
		return editRequest(id, self, r ->
		{
			Set<Integer> fresh = new LinkedHashSet<>(items);
			fresh.retainAll(r.items.keySet());
			fresh.removeAll(r.closedItems);
			return r.closed || fresh.isEmpty() ? null : r.withClosedItems(fresh, now);
		});
	}

	/** "I'll get it", or taking it back. Anyone may, on an open request's open item. */
	boolean claim(String id, int itemId, String self, boolean claimed, long now)
	{
		boolean ok;
		synchronized (this)
		{
			RequestList r = requests.get(id);
			ok = r != null && r.open() && r.items.containsKey(itemId) && !self.isEmpty()
				&& !(claimed && r.closedItems.contains(itemId))
				&& requests.accept(new RequestClaim(id, itemId, self, claimed, now), true);
		}
		return changed(ok);
	}

	/** The owner's edit of a live request; null when it is not theirs, not live, or the edit changes nothing. */
	private RequestList editRequest(String id, String self, java.util.function.Function<RequestList, RequestList> edit)
	{
		RequestList next;
		synchronized (this)
		{
			RequestList current = requests.get(id);
			next = current == null || current.removed || !current.ownedBy(self) ? null : edit.apply(current);
			if (next != null && !takeRequest(next, true))
			{
				next = null;
			}
		}
		changed(next != null);
		return next;
	}

	/** Holds the lock. */
	private boolean takeRequest(RequestList r, boolean own)
	{
		String text = requests.accept(r, own);
		if (text == null)
		{
			return false;
		}
		note(r.at, text);
		return true;
	}

	private boolean changed(boolean ok)
	{
		if (ok)
		{
			onChange.run();
		}
		return ok;
	}

	/** This player's quest progress as the game shows it; sent when it changed and some list is for them. */
	void ownProgress(String self, QuestProgress now)
	{
		synchronized (this)
		{
			if (self.isEmpty() || now.equals(progress.get(GroupMembers.key(self))))
			{
				return;
			}
			progress.put(GroupMembers.key(self), now);
			progressDirty = true;
		}
		onChange.run();
	}

	// ---- The party ----

	/** A shopping message from {@code member}, a roster member. False when it is not one. */
	boolean receive(String member, String payload)
	{
		ShoppingCodec.Message m = ShoppingCodec.decode(gson, payload);
		if (m == null)
		{
			return false;
		}
		synchronized (this)
		{
			if (m.list != null)
			{
				accept(m.list, false);
			}
			else if (m.request != null)
			{
				takeRequest(m.request, false);
			}
			else if (m.claim != null)
			{
				requests.accept(m.claim, false);
			}
			else
			{
				progress.put(GroupMembers.key(member), m.quests);
			}
		}
		onChange.run();
		return true;
	}

	/** Someone joined: they may have missed all of it, removals included. */
	synchronized void resendAll()
	{
		dirty.addAll(lists.keySet());
		requests.resendAll();
		progressDirty = true;
	}

	/** Game tick, connected: every list that changed, then this player's progress when a list is for them. */
	void flush(String self)
	{
		List<String> out = new ArrayList<>();
		synchronized (this)
		{
			for (String id : dirty)
			{
				ShoppingList l = lists.get(id);
				if (l != null)
				{
					out.add(ShoppingCodec.encode(gson, l));
				}
			}
			dirty.clear();
			requests.drain(gson, out);
			QuestProgress mine = progress.get(GroupMembers.key(self));
			if (progressDirty && mine != null && isFor(self))
			{
				out.add(ShoppingCodec.encode(gson, mine));
				progressDirty = false;
			}
		}
		out.forEach(send);
	}

	/** True when some live list names {@code member}. */
	synchronized boolean isFor(String member)
	{
		for (ShoppingList l : lists.values())
		{
			if (!l.removed && containsIgnoreCase(l.members, member))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean containsIgnoreCase(List<String> names, String name)
	{
		for (String n : names)
		{
			if (GroupMembers.key(n).equals(GroupMembers.key(name)))
			{
				return true;
			}
		}
		return false;
	}

	/** Keeps {@code list} when it is newer than what is held; {@code own} marks it to send. Holds the lock. */
	private boolean accept(ShoppingList list, boolean own)
	{
		ShoppingList current = lists.get(list.id);
		if (!list.newerThan(current))
		{
			return false;
		}
		if (current == null && !roomFor())
		{
			return false;
		}
		lists.put(list.id, list);
		record(current, list);
		if (own)
		{
			dirty.add(list.id);
		}
		return true;
	}

	/** Room for one more list, forgetting the oldest removed one if that makes room. */
	private boolean roomFor()
	{
		return makeRoom(lists, MAX_LISTS, l -> l.removed, l -> l.at);
	}

	/**
	 * True when {@code book} has room for one more entry under {@code max}, forgetting the oldest {@code spare}
	 * one if that makes room. Lists and requests both use it.
	 */
	static <T> boolean makeRoom(Map<String, T> book, int max, java.util.function.Predicate<T> spare,
		java.util.function.ToLongFunction<T> at)
	{
		if (book.size() < max)
		{
			return true;
		}
		String oldest = null;
		long oldestAt = Long.MAX_VALUE;
		for (Map.Entry<String, T> e : book.entrySet())
		{
			long when = at.applyAsLong(e.getValue());
			if (spare.test(e.getValue()) && (oldest == null || when < oldestAt))
			{
				oldest = e.getKey();
				oldestAt = when;
			}
		}
		if (oldest == null)
		{
			return false;
		}
		book.remove(oldest);
		return true;
	}

	private void record(ShoppingList before, ShoppingList after)
	{
		note(after.at, describe(before, after));
	}

	/** One line of history, newest first; an empty line is not kept. Holds the lock. */
	private void note(long at, String text)
	{
		if (text.isEmpty())
		{
			return;
		}
		history.addFirst(new Change(at, text));
		while (history.size() > MAX_HISTORY)
		{
			history.removeLast();
		}
	}

	/** "Bob renamed 'Ropes' to 'Ropes and buckets'"; empty when there is nothing to say. */
	static String describe(ShoppingList before, ShoppingList after)
	{
		String who = after.by.isEmpty() ? "Someone" : after.by;
		if (after.removed)
		{
			return before != null && before.removed ? "" : who + " removed '" + after.name + "'";
		}
		if (before == null || before.removed)
		{
			return who + " added '" + after.name + "' for " + String.join(", ", after.members);
		}
		if (!before.name.equals(after.name))
		{
			return who + " renamed '" + before.name + "' to '" + after.name + "'";
		}
		return who + " changed '" + after.name + "'";
	}

	// ---- What the tab draws ----

	/** Live lists, oldest first. */
	synchronized List<ShoppingList> active()
	{
		List<ShoppingList> out = new ArrayList<>();
		for (ShoppingList l : lists.values())
		{
			if (!l.removed)
			{
				out.add(l);
			}
		}
		out.sort((a, b) -> a.created != b.created ? Long.compare(a.created, b.created) : a.id.compareTo(b.id));
		return out;
	}

	synchronized ShoppingList list(String id)
	{
		return lists.get(id);
	}

	synchronized List<Change> history()
	{
		return new ArrayList<>(history);
	}

	/** Members' requests not removed, oldest first, closed ones included. */
	synchronized List<RequestList> requests()
	{
		return requests.live();
	}

	/** Any held revision, removed included; null when none. */
	synchronized RequestList request(String id)
	{
		return requests.get(id);
	}

	/** Standing claims on one request. */
	synchronized List<RequestClaim> claims(String id)
	{
		return requests.claims(id);
	}

	/** {@link QuestProgress#UNKNOWN} for a member whose client never said. */
	synchronized QuestProgress progress(String member)
	{
		QuestProgress p = progress.get(GroupMembers.key(member));
		return p == null ? QuestProgress.UNKNOWN : p;
	}

	// ---- The group cache ----

	/** The cache file's {@code shop} entry: every list (as its party message), the history and progress. */
	synchronized JsonObject toCache()
	{
		JsonObject out = new JsonObject();
		JsonArray ls = new JsonArray();
		lists.values().forEach(l -> ls.add(ShoppingCodec.encode(gson, l)));
		out.add("lists", ls);
		out.add("reqs", requests.requestsToCache(gson));
		out.add("claims", requests.claimsToCache(gson));
		JsonArray hist = new JsonArray();
		for (Change c : history)
		{
			JsonArray line = new JsonArray();
			line.add(c.at);
			line.add(c.text);
			hist.add(line);
		}
		out.add("hist", hist);
		JsonObject qp = new JsonObject();
		progress.forEach((member, p) -> qp.addProperty(member, ShoppingCodec.encode(gson, p)));
		out.add("qp", qp);
		return out;
	}

	/** Reads what {@link #toCache} wrote; anything unreadable is skipped. Removed lists past their time are dropped. */
	void fromCache(JsonElement e, long now)
	{
		if (e == null || !e.isJsonObject())
		{
			return;
		}
		JsonObject in = e.getAsJsonObject();
		synchronized (this)
		{
			for (String payload : strings(in.get("lists"), MAX_LISTS))
			{
				readList(payload, now);
			}
			// Requests before claims: a claim is kept only on a request held.
			for (String payload : strings(in.get("reqs"), RequestBook.MAX_REQUESTS))
			{
				requests.fromCache(ShoppingCodec.decode(gson, payload), now, TOMBSTONE_MS);
			}
			for (String payload : strings(in.get("claims"), RequestBook.MAX_CLAIMS))
			{
				requests.fromCache(ShoppingCodec.decode(gson, payload), now, TOMBSTONE_MS);
			}
			readHistory(in.get("hist"));
			readProgress(in.get("qp"));
		}
		onChange.run();
	}

	/** One cached list, unless it is a removal past its time or older than what is held. Holds the lock. */
	private void readList(String payload, long now)
	{
		ShoppingCodec.Message m = ShoppingCodec.decode(gson, payload);
		ShoppingList l = m == null ? null : m.list;
		if (l == null || l.removed && now - l.at > TOMBSTONE_MS)
		{
			return;
		}
		ShoppingList current = lists.get(l.id);
		if (l.newerThan(current) && (current != null || lists.size() < MAX_LISTS))
		{
			lists.put(l.id, l);
		}
	}

	private void readHistory(JsonElement e)
	{
		if (e == null || !e.isJsonArray() || !history.isEmpty())
		{
			return;
		}
		for (JsonElement line : e.getAsJsonArray())
		{
			Change c = history.size() < MAX_HISTORY ? change(line) : null;
			if (c != null)
			{
				history.addLast(c);
			}
		}
	}

	/** {@code [at, text]}, or null when it is not one. */
	private static Change change(JsonElement line)
	{
		JsonArray a = line.isJsonArray() ? line.getAsJsonArray() : null;
		if (a == null || a.size() < 2 || !a.get(1).isJsonPrimitive())
		{
			return null;
		}
		Long at = ItemCounts.longValue(a.get(0));
		return at == null ? null : new Change(at, ShoppingList.cap(a.get(1).getAsString(), 200));
	}

	private void readProgress(JsonElement e)
	{
		if (e == null || !e.isJsonObject())
		{
			return;
		}
		for (Map.Entry<String, JsonElement> m : e.getAsJsonObject().entrySet())
		{
			ShoppingCodec.Message p = m.getValue().isJsonPrimitive()
				? ShoppingCodec.decode(gson, m.getValue().getAsString()) : null;
			if (p != null && p.quests != null && progress.size() < GroupCache.MAX_MEMBERS)
			{
				progress.putIfAbsent(GroupMembers.key(m.getKey()), p.quests);
			}
		}
	}

	private static List<String> strings(JsonElement e, int max)
	{
		if (e == null || !e.isJsonArray())
		{
			return Collections.emptyList();
		}
		List<String> out = new ArrayList<>();
		for (JsonElement s : e.getAsJsonArray())
		{
			if (s.isJsonPrimitive() && out.size() < max)
			{
				out.add(s.getAsString());
			}
		}
		return out;
	}
}

package com.vinnyvangogh.groupironman;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.JTextField;
import javax.swing.SpinnerNumberModel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;

/**
 * The panel's Shopping tab: the group's shared shopping lists, each line what
 * the group still has to get after what members and group storage hold, who
 * holds it and where this player can get it; then the form that adds a list
 * (a build preset or custom items) for one or more members, and who changed
 * what.
 *
 * <p>Every list and request starts folded to a header with a preview: its
 * progress and the first still-needed items' icons (Board 2026-11-14: a 39-item
 * preset was too much). What the player opens is saved for the character
 * ({@link ShopFolds}). An open list shows still-needed items first, one compact
 * line each with the details behind a click, and its finished items folded into
 * "N done".
 *
 * <p>Rebuilt only when what it shows changed ({@link View#signature}) or a fold flipped, so a
 * half-typed list name or item search survives the many redraws member stats
 * cause. The form itself is built once and kept.
 */
final class ShoppingTab
{
	/** What the tab's buttons do; each false when refused. */
	interface Actions
	{
		boolean addList(String name, String preset, List<String> picks, List<String> members,
			Map<Integer, Integer> items);

		boolean renameList(String id, String name);

		boolean removeList(String id);

		/** Tradeable items matching {@code query}; {@code done} may be called on another thread. */
		void searchItems(String query, Consumer<List<Hit>> done);

		/** This player's own request; a blank name becomes "Name's requests". */
		boolean addRequest(String name, Map<Integer, Integer> items);

		boolean renameRequest(String id, String name);

		boolean removeRequest(String id);

		boolean closeRequest(String id);

		boolean closeRequestItem(String id, int itemId);

		/** "I'll get it", or taking it back. */
		boolean claimRequest(String id, int itemId, boolean claimed);

		/** What this player opened on the tab ({@link ShopFolds}), saved for this character; null when nothing is. */
		String openLists();

		/** Saves what is open for this character only; null clears it. Never sent to the group. */
		void saveOpenLists(String keys);

		/** Hands {@code to} to Shortest Path for {@code why}; the line to show. */
		String pathTo(ItemPaths.Target why, ItemPaths.Stop to);

		/** Clears the path; the line to show, empty when there was none. */
		String clearPath();
	}

	static final int MAX_HITS = 10;
	private static final Color MUTED = ShopCards.MUTED;
	private static final Color DONE = ShopCards.DONE;
	private static final String CUSTOM = "Custom list";
	private static final String REQUEST = "Request: ask the group";
	/** Entries before the presets in the kind box: custom, then request. */
	private static final int FIXED_KINDS = 2;
	/** Sources named in an item's details; the rest are a count. */
	private static final int SOURCES_SHOWN = 4;

	/** One item search result. */
	static final class Hit
	{
		final int id;
		final String name;

		Hit(int id, String name)
		{
			this.id = id;
			this.name = name;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}

	/** Everything the tab draws. */
	static final class View
	{
		final List<ShoppingBoard.Card> cards;
		final List<ShopPresets.Preset> presets;
		final List<String> roster;
		final List<ShoppingSync.Change> history;
		final boolean loggedIn;
		final boolean syncing;
		/** Members' requests, oldest first. */
		final List<RequestBoard.Card> requests;
		/** This player, for "mine" and "I'll get it"; empty when logged out. */
		final String self;
		/** Where "Path to" leads; null draws no path buttons. */
		final ItemPaths.Planner paths;
		/** The stop being pathed to; empty for none. */
		final String pathing;

		View(List<ShoppingBoard.Card> cards, List<ShopPresets.Preset> presets, List<String> roster,
			List<ShoppingSync.Change> history, boolean loggedIn, boolean syncing, List<RequestBoard.Card> requests,
			String self, ItemPaths.Planner paths, String pathing)
		{
			this.cards = cards;
			this.presets = presets;
			this.roster = roster;
			this.history = history;
			this.loggedIn = loggedIn;
			this.syncing = syncing;
			this.requests = requests;
			this.self = self;
			this.paths = paths;
			this.pathing = pathing;
		}

		/** Changes when anything drawn changes. */
		String signature()
		{
			StringBuilder s = new StringBuilder();
			s.append(roster).append(loggedIn).append(syncing).append(history.size()).append(pathing)
				.append(RequestCards.signature(requests, self, paths));
			for (ShoppingSync.Change c : history)
			{
				s.append(c.at).append(c.text);
			}
			for (ShoppingBoard.Card c : cards)
			{
				s.append('|').append(c.list.id).append(c.list.rev).append(c.progressUnknown).append(c.itemsUnknown)
					.append(paths == null ? "" : first(paths.next(c)));
				for (ShoppingBoard.Row r : c.rows)
				{
					s.append(summary(r.line)).append(needText(r.line)).append(details(r))
						.append(paths == null ? "" : first(paths.shopping(r)));
				}
			}
			return s.toString();
		}
	}

	/** The first stop's name, for signatures; empty for none. */
	static String first(List<ItemPaths.Stop> stops)
	{
		return stops.isEmpty() ? "" : stops.get(0).name;
	}

	private final Actions actions;
	private final ItemManager items;
	private final Runnable refresh;
	private final Form form = new Form();
	private final RequestCards requestCards;
	private final ShopFolds folds;
	/** Every fold key the last draw showed: a toggle keeps only these, so the saved set never outgrows the tab. */
	private final Set<String> live = new HashSet<>();
	private String drawn;
	private String note;
	/** A fold flipped: redraw even though the view did not change. */
	private boolean refold;

	ShoppingTab(Actions actions, ItemManager items, Runnable refresh)
	{
		this.actions = actions;
		this.items = items;
		this.refresh = refresh;
		this.folds = new ShopFolds(new ShopFolds.Store()
		{
			@Override
			public String load()
			{
				return actions.openLists();
			}

			@Override
			public void save(String value)
			{
				actions.saveOpenLists(value);
			}
		});
		this.requestCards = new RequestCards(actions, items, this::say, this);
	}

	/** Whether {@code v} would draw differently from what is on screen. */
	boolean changed(View v)
	{
		return !v.signature().equals(drawn) || note != null || refold;
	}

	void draw(JPanel tab, View v)
	{
		drawn = v.signature();
		refold = false;
		live.clear();
		if (note != null)
		{
			tab.add(ShopCards.tabText(note, Color.WHITE));
			note = null;
		}
		if (!v.pathing.isEmpty())
		{
			tab.add(GroupIronmanPanel.text("Pathing to " + v.pathing + " with Shortest Path.", MUTED));
			tab.add(Ui.wide(Ui.button("Stop path", null, () -> say(actions.clearPath()))));
		}
		requestCards.draw(tab, v.requests, v.self, v.paths);
		if (v.cards.isEmpty() && v.requests.isEmpty())
		{
			tab.add(GroupIronmanPanel.heading("No shopping lists yet"));
			tab.add(ShopCards.tabText("Add one below: a build milestone, like Mithril gloves for a 1 Defence"
				+ " pure, your own items, or a request the group fills for you. Every member running GIM Utilities"
				+ " sees it.", MUTED));
		}
		if (!v.cards.isEmpty())
		{
			tab.add(GroupIronmanPanel.heading("Lists"));
		}
		for (ShoppingBoard.Card c : v.cards)
		{
			tab.add(card(c, v.paths));
		}
		if (!v.syncing)
		{
			tab.add(ShopCards.tabText("Not in group sync: lists stay on this client until you join.", MUTED));
		}
		tab.add(form.panel(v));
		drawHistory(tab, v.history);
	}

	private void drawHistory(JPanel tab, List<ShoppingSync.Change> history)
	{
		if (history.isEmpty())
		{
			return;
		}
		tab.add(GroupIronmanPanel.heading("Changes"));
		long now = System.currentTimeMillis();
		for (ShoppingSync.Change c : history)
		{
			tab.add(ShopCards.tabText(c.text + " (" + BoostText.ago(now, c.at) + ")", MUTED));
		}
	}

	/** Whether {@code key} is drawn open; it joins the keys this draw shows. */
	boolean isOpen(String key)
	{
		live.add(key);
		return folds.open(key);
	}

	/** Flips {@code key} (a header, "N done" or an item was clicked) and redraws. */
	void fold(String key)
	{
		live.add(key);
		folds.toggle(key, live);
		refold = true;
		refresh.run();
	}

	// ---- A list ----

	/** Folded: the header and its preview. Open: who it is for, its buttons, still-needed items, then "N done". */
	private JPanel card(ShoppingBoard.Card c, ItemPaths.Planner paths)
	{
		String key = ShopFolds.list(c.list.id);
		boolean open = isOpen(key);
		List<ShoppingBoard.Row> needed = new ArrayList<>();
		List<ShoppingBoard.Row> done = new ArrayList<>();
		for (ShoppingBoard.Row r : c.rows)
		{
			(r.line.done() ? done : needed).add(r);
		}
		List<Integer> preview = new ArrayList<>();
		needed.forEach(r -> preview.add(r.line.itemId));
		JPanel box = Ui.card();
		ShopCards.header(box, c.list.name, open, c.done(), c.rows.size(), preview, items, () -> fold(key));
		if (!open)
		{
			return box;
		}
		box.add(new ShopCards.Wrap(byline(c.list, System.currentTimeMillis()), MUTED, ShopCards.CARD_TEXT));
		box.add(buttons(c.list));
		List<ItemPaths.Stop> tour = paths == null ? Collections.emptyList() : paths.next(c);
		if (!tour.isEmpty())
		{
			box.add(pathButton(nextLabel(tour), tour.get(0), ItemPaths.Target.next(c.list.id)));
		}
		for (String line : warnings(c))
		{
			box.add(new ShopCards.Wrap(line, ColorScheme.BRAND_ORANGE, ShopCards.CARD_TEXT));
		}
		if (c.empty())
		{
			box.add(new ShopCards.Wrap("Nothing to get: every quest is done, or the list is empty.", MUTED,
				ShopCards.CARD_TEXT));
		}
		for (ShoppingBoard.Row r : needed)
		{
			box.add(row(key, c.list.id, r, paths));
		}
		addDone(box, key, done.size(), () -> done.forEach(r -> box.add(row(key, c.list.id, r, paths))));
		return box;
	}

	/** "▸ N done", and the finished items under it once opened; nothing when none is finished. */
	void addDone(JPanel box, String cardKey, int count, Runnable drawRows)
	{
		if (count == 0)
		{
			return;
		}
		String key = ShopFolds.done(cardKey);
		boolean open = isOpen(key);
		box.add(ShopCards.doneToggle(count, open, () -> fold(key)));
		if (open)
		{
			drawRows.run();
		}
	}

	/** "Path to next: Harry's Fishing Shop (1 of 3 stops)". */
	static String nextLabel(List<ItemPaths.Stop> tour)
	{
		return "Path to next: " + tour.get(0).name + (tour.size() > 1 ? " (1 of " + tour.size() + " stops)" : "");
	}

	private JPanel pathButton(String label, ItemPaths.Stop to, ItemPaths.Target why)
	{
		return pathButton(label, () -> say(actions.pathTo(why, to)));
	}

	/** A full-width "Path to" button; the whole label is also its tooltip, for long shop names. */
	static JPanel pathButton(String label, Runnable action)
	{
		JPanel wrap = Ui.wide(Ui.button(label, label, action));
		wrap.setOpaque(false);
		return wrap;
	}

	/** "For Alice, Bob. Added by Bob, 5 min ago." or "... Renamed by Alice, ...". */
	static String byline(ShoppingList l, long now)
	{
		String what = ShoppingList.ADDED.equals(l.action) ? "Added" : capital(l.action);
		return "For " + String.join(", ", l.members) + ". " + what + " by " + l.by + ", " + BoostText.ago(now, l.at)
			+ ".";
	}

	private static String capital(String s)
	{
		return s.isEmpty() ? "Changed" : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}

	/** The preset's note, then what this client does not know. */
	static List<String> warnings(ShoppingBoard.Card c)
	{
		List<String> out = new ArrayList<>();
		if (c.preset != null && !c.preset.note().isEmpty())
		{
			out.add(c.preset.note());
		}
		if (!c.list.custom() && c.preset == null)
		{
			out.add("This list is from a newer GIM Utilities: update to see its items.");
		}
		if (!c.progressUnknown.isEmpty())
		{
			out.add("No quest progress from " + String.join(", ", c.progressUnknown)
				+ " yet: every quest counts for them until their client sends it.");
		}
		if (!c.itemsUnknown.isEmpty())
		{
			out.add(String.join(", ", c.itemsUnknown) + " share no items, so what they hold is not counted.");
		}
		return out;
	}

	/**
	 * One item, one compact line: its icon, "Air rune  12 / 30", a bar and "Need 18 more". A click (or the
	 * tooltip) shows the details: who holds it, where to get it, whether it can be traded. "Path to" under it.
	 */
	private JPanel row(String cardKey, String listId, ShoppingBoard.Row r, ItemPaths.Planner paths)
	{
		ShopAllocation.Line l = r.line;
		String key = ShopFolds.item(cardKey, l.itemId);
		boolean open = isOpen(key);
		List<String> details = details(r);
		JPanel words = new GroupIronmanPanel.Column();
		words.add(new ShopCards.Wrap(summary(l), l.done() ? DONE : Color.WHITE, ShopCards.ROW_TEXT));
		words.add(new ShopCards.Bar(l.have(), l.totalNeeded(), ShopCards.ROW_TEXT));
		ShopCards.Wrap need = new ShopCards.Wrap(needText(l), l.done() ? DONE : MUTED, ShopCards.ROW_TEXT);
		if (!details.isEmpty())
		{
			need.setIcon(new GroupIronmanPanel.Arrow(open));
			need.setIconTextGap(4);
		}
		words.add(need);
		if (open)
		{
			details.forEach(d -> words.add(new ShopCards.Wrap(d, MUTED, ShopCards.ROW_TEXT)));
		}
		List<ItemPaths.Stop> stops = paths == null ? Collections.emptyList() : paths.shopping(r);
		if (!stops.isEmpty())
		{
			words.add(pathButton(stops.get(0).label(), stops.get(0), ItemPaths.Target.listItem(listId, l.itemId)));
		}
		JPanel line = itemLine(l.itemId, words);
		if (!details.isEmpty())
		{
			line.setToolTipText("<html>" + GroupIronmanPanel.escape(String.join("\n", details)).replace("\n", "<br>")
				+ "</html>");
			Ui.clickable(line, () -> fold(key));
		}
		return line;
	}

	/** An item's icon on the left, {@code words} beside it. */
	JPanel itemLine(int itemId, JPanel words)
	{
		JPanel line = new JPanel(new BorderLayout(4, 0));
		line.setOpaque(false);
		line.setBorder(new EmptyBorder(3, 0, 3, 0));
		JLabel icon = new JLabel();
		icon.setVerticalAlignment(JLabel.TOP);
		if (items != null)
		{
			items.getImage(itemId).addTo(icon);
		}
		line.add(icon, BorderLayout.WEST);
		words.setOpaque(false);
		line.add(words, BorderLayout.CENTER);
		return line;
	}

	/** "Air rune  12 / 30": what the group holds towards it of everything needed, "30+" when the wiki gave no count. */
	static String summary(ShopAllocation.Line l)
	{
		return l.name + "  " + Amounts.GAME.of(l.have()) + " / " + Amounts.GAME.of(l.totalNeeded()) + (l.stated ? ""
			: "+");
	}

	/**
	 * "Need 18 more", "Done", or what a member who shares no items means for the count: "Need 18 more, plus 5 for
	 * Tin (shares no items, may already have them)". Their need is never in "more": it may be in their bank.
	 */
	static String needText(ShopAllocation.Line l)
	{
		if (l.done())
		{
			return "Done";
		}
		List<String> unseen = new ArrayList<>();
		for (ShopAllocation.Share s : l.shares)
		{
			if (s.unknown && s.need > 0)
			{
				unseen.add(s.member);
			}
		}
		String still = l.stillNeeded() > 0 ? "Need " + Amounts.GAME.of(l.stillNeeded()) + " more" : "";
		if (unseen.isEmpty())
		{
			return still;
		}
		String unknown = Amounts.GAME.of(l.unknownNeed()) + " for " + String.join(", ", unseen) + " ("
			+ (unseen.size() == 1 ? "shares" : "share") + " no items, may already have them)";
		return still.isEmpty() ? "Need " + unknown : still + ", plus " + unknown;
	}

	/** Behind the click: who holds it, whether it can be traded, a quest pickup, and where to get more. */
	static List<String> details(ShoppingBoard.Row r)
	{
		ShopAllocation.Line l = r.line;
		List<String> out = new ArrayList<>();
		String held = heldText(l);
		if (!held.isEmpty())
		{
			out.add(held);
		}
		if (!l.tradeable)
		{
			out.add("Can't be traded: each member's own copy counts only for them.");
		}
		if (l.obtainable)
		{
			out.add("Can also be picked up during the quest.");
		}
		if (!l.done())
		{
			out.add(sourceText(r.sources));
		}
		return out;
	}

	/** "Held by Alice 2, Bob 1, group storage 4"; empty when nobody holds any. */
	static String heldText(ShopAllocation.Line l)
	{
		Map<String, Long> all = new LinkedHashMap<>(l.holders);
		if (l.storageHeld > 0)
		{
			all.put("group storage", l.storageHeld);
		}
		if (all.isEmpty())
		{
			return "";
		}
		List<String> parts = new ArrayList<>();
		all.forEach((who, n) -> parts.add(who + " " + Amounts.GAME.of(n)));
		return "Held by " + String.join(", ", parts);
	}

	/** "Get: Shop: Tynan's Fishing Supplies (2 gp); Drop: Goblin (Always)" or why there is nowhere. */
	static String sourceText(ShopSources.Options o)
	{
		if (o.sources.isEmpty())
		{
			return o.unreachableShops > 0
				? "No shop you can use: " + o.unreachableShops + " need levels or quests you lack."
				: "Not sold in any shop, and no drop on file: check the wiki.";
		}
		List<String> parts = new ArrayList<>();
		for (ShopSources.Source s : o.sources.subList(0, Math.min(SOURCES_SHOWN, o.sources.size())))
		{
			parts.add(s.describe());
		}
		int more = o.sources.size() - parts.size();
		return "Get: " + String.join("; ", parts) + (more > 0 ? "; " + more + " more" : "");
	}

	private JPanel buttons(ShoppingList l)
	{
		JPanel row = new JPanel(new GridLayout(1, 0, 2, 0));
		row.setOpaque(false);
		if (l.custom())
		{
			row.add(Ui.button("Rename", null, () ->
			{
				String name = JOptionPane.showInputDialog(row, "New name for '" + l.name + "'", l.name);
				if (name != null)
				{
					say(actions.renameList(l.id, name) ? null : "Not renamed: log in, and give it a new name.");
				}
			}));
		}
		row.add(Ui.button("Remove", null, () ->
		{
			if (JOptionPane.showConfirmDialog(row, "Remove '" + l.name + "' for the whole group?", "Remove list",
				JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION)
			{
				say(actions.removeList(l.id) ? null : "Not removed: log in first.");
			}
		}));
		return row;
	}

	private void say(String text)
	{
		note = text == null || text.isEmpty() ? null : text;
		refresh.run();
	}

	// ---- The form ----

	/** "New list": kept between redraws so typing survives them. */
	private final class Form
	{
		private final JPanel panel = new GroupIronmanPanel.Column();
		private final JComboBox<String> kind = new JComboBox<>();
		private final JPanel picks = new GroupIronmanPanel.Column();
		private final JTextField name = new JTextField();
		private final JTextField query = new JTextField();
		private final JComboBox<Hit> hits = new JComboBox<>();
		private final JSpinner quantity = new JSpinner(new SpinnerNumberModel(1, 1, ShoppingList.MAX_QUANTITY, 1));
		private final JPanel staged = new GroupIronmanPanel.Column();
		private final JPanel custom = new GroupIronmanPanel.Column();
		private final JPanel members = new GroupIronmanPanel.Column();
		private final JLabel forLabel = ShopCards.tabText("For:", MUTED);
		private final JLabel nameLabel = ShopCards.tabText("Name", MUTED);
		private final Map<Integer, Integer> stagedItems = new LinkedHashMap<>();
		private final Map<Integer, String> stagedNames = new LinkedHashMap<>();
		private final List<JCheckBox> pickBoxes = new ArrayList<>();
		private final List<JCheckBox> memberBoxes = new ArrayList<>();
		private List<ShopPresets.Preset> presets = Collections.emptyList();
		private List<String> roster;

		Form()
		{
			panel.add(GroupIronmanPanel.heading("New list"));
			panel.add(kind);
			kind.addActionListener(e -> showKind());
			panel.add(picks);
			buildCustom();
			panel.add(custom);
			panel.add(forLabel);
			panel.add(members);
			panel.add(Ui.wide(Ui.button("Add list", null, this::submit)));
		}

		private void buildCustom()
		{
			custom.add(nameLabel);
			custom.add(name);
			custom.add(ShopCards.tabText("Item (tradeable items)", MUTED));
			JPanel search = new JPanel(new BorderLayout(2, 0));
			search.add(query, BorderLayout.CENTER);
			search.add(Ui.button("Search", null, this::search), BorderLayout.EAST);
			custom.add(search);
			custom.add(hits);
			JPanel add = new JPanel(new BorderLayout(2, 0));
			add.add(quantity, BorderLayout.CENTER);
			add.add(Ui.button("Add item", null, this::stage), BorderLayout.EAST);
			custom.add(add);
			custom.add(staged);
		}

		JPanel panel(View v)
		{
			if (!v.presets.equals(presets))
			{
				presets = v.presets;
				kind.removeAllItems();
				kind.addItem(CUSTOM);
				kind.addItem(REQUEST);
				presets.forEach(p -> kind.addItem(presetLabel(p)));
			}
			if (!v.roster.equals(roster))
			{
				roster = v.roster;
				members.removeAll();
				memberBoxes.clear();
				for (String m : roster)
				{
					JCheckBox box = new JCheckBox(m, true);
					memberBoxes.add(box);
					members.add(box);
				}
			}
			return panel;
		}

		private String presetLabel(ShopPresets.Preset p)
		{
			return p.build().isEmpty() ? p.name() : p.build() + ": " + p.name();
		}

		private ShopPresets.Preset selected()
		{
			int i = kind.getSelectedIndex() - FIXED_KINDS;
			return i >= 0 && i < presets.size() ? presets.get(i) : null;
		}

		/** A request is always this player's own: no members to tick, and the name may be left blank. */
		private boolean request()
		{
			return REQUEST.equals(kind.getSelectedItem());
		}

		private void showKind()
		{
			ShopPresets.Preset p = selected();
			custom.setVisible(p == null);
			forLabel.setVisible(!request());
			members.setVisible(!request());
			nameLabel.setText("<html>" + (request() ? "Name (blank: your name's requests)" : "Name") + "</html>");
			picks.removeAll();
			pickBoxes.clear();
			ShopPresets.Choice choice = p == null ? null : p.choice();
			if (choice != null)
			{
				picks.add(ShopCards.tabText("Pick " + choice.count() + ":", MUTED));
				for (String option : choice.from())
				{
					JCheckBox box = new JCheckBox(option, choice.defaults().contains(option));
					pickBoxes.add(box);
					picks.add(box);
				}
			}
			panel.revalidate();
			panel.repaint();
		}

		private void search()
		{
			String q = query.getText().trim();
			if (q.length() < 2)
			{
				return;
			}
			actions.searchItems(q, found -> SwingUtilities.invokeLater(() ->
			{
				hits.removeAllItems();
				found.forEach(hits::addItem);
			}));
		}

		private void stage()
		{
			Hit h = (Hit) hits.getSelectedItem();
			if (h == null || stagedItems.size() >= ShoppingList.MAX_ITEMS)
			{
				return;
			}
			stagedItems.merge(h.id, (Integer) quantity.getValue(), Integer::sum);
			stagedNames.put(h.id, h.name);
			redrawStaged();
		}

		private void redrawStaged()
		{
			staged.removeAll();
			for (Map.Entry<Integer, Integer> e : stagedItems.entrySet())
			{
				JPanel line = new JPanel(new BorderLayout(2, 0));
				line.add(new ShopCards.Wrap(Amounts.GAME.of(e.getValue()) + " x " + stagedNames.get(e.getKey()),
					Color.WHITE, ShopCards.TAB_TEXT - 40), BorderLayout.CENTER);
				int id = e.getKey();
				line.add(Ui.button("x", null, () ->
				{
					stagedItems.remove(id);
					redrawStaged();
				}), BorderLayout.EAST);
				staged.add(line);
			}
			panel.revalidate();
			panel.repaint();
		}

		private List<String> ticked(List<JCheckBox> boxes)
		{
			List<String> out = new ArrayList<>();
			boxes.stream().filter(JCheckBox::isSelected).forEach(b -> out.add(b.getText()));
			return out;
		}

		private void submit()
		{
			if (request())
			{
				submitRequest();
				return;
			}
			ShopPresets.Preset p = selected();
			String problem = problem(p);
			if (problem != null)
			{
				say(problem);
				return;
			}
			boolean ok = p == null
				? actions.addList(name.getText(), "", Collections.emptyList(), ticked(memberBoxes), stagedItems)
				: actions.addList(p.name(), p.id(), ticked(pickBoxes), ticked(memberBoxes), Collections.emptyMap());
			if (ok && p == null)
			{
				name.setText("");
				stagedItems.clear();
				redrawStaged();
			}
			say(ok ? null : "Not added: log in first (the group holds at most " + ShoppingSync.MAX_LISTS
				+ " lists).");
		}

		private void submitRequest()
		{
			if (stagedItems.isEmpty())
			{
				say("Add at least one item.");
				return;
			}
			boolean ok = actions.addRequest(name.getText(), stagedItems);
			if (ok)
			{
				name.setText("");
				stagedItems.clear();
				redrawStaged();
			}
			say(ok ? null : "Not added: log in first (the group holds at most " + RequestBook.MAX_REQUESTS
				+ " requests).");
		}

		/** Why the form cannot be sent as it is, or null. */
		private String problem(ShopPresets.Preset p)
		{
			if (ticked(memberBoxes).isEmpty())
			{
				return "Tick at least one member the list is for.";
			}
			if (p == null)
			{
				return name.getText().trim().isEmpty() ? "Give the list a name."
					: stagedItems.isEmpty() ? "Add at least one item." : null;
			}
			ShopPresets.Choice c = p.choice();
			return c != null && ticked(pickBoxes).size() != c.count() ? "Tick exactly " + c.count() + "." : null;
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collection;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.Predicate;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.events.PluginMessage;

/**
 * Hands world points to the Shortest Path plugin's own pathfinder.
 *
 * <p>Copied from Quest Path's {@code ShortestPathBridge}
 * (questpath-plugin {@code 80cdafb},
 * {@code src/main/java/com/vinnyvangogh/questpath/ShortestPathBridge.java}), with
 * its tests ({@code ShortestPathBridgeTest}). Only the package and the
 * player-facing words changed; every finding below was made there and is
 * carried over, not re-derived.
 *
 * <p>This class touches nothing in the plugin it talks to: no reflection, no
 * member access, no classloading. Shortest Path ({@code Skretzo/shortest-path})
 * listens for RuneLite's own {@code net.runelite.client.events.PluginMessage},
 * a public class shipped inside {@code runelite-client} itself, and documents
 * the messages for other plugins in its {@code docs/Cross-plugin-communication.md}
 * (read 2026-11-14): namespace {@code shortestpath}; {@code path} "shows a
 * path, replacing the current one" and takes a {@code target} that is one
 * {@code WorldPoint} or a collection of them; {@code clear} "removes the shown
 * path". Posting one is two calls against RuneLite's public API ({@code new
 * PluginMessage(namespace, name, data)} and {@code EventBus#post(Object)}).
 * Quest Path confirmed the constants and the {@code Set<WorldPoint>} branch
 * with {@code javap -c -p} against the installed jar's
 * {@code shortestpath/ShortestPathPlugin.class}.
 *
 * <p><b>What {@link RouteOutcome#SENT} proves.</b> The message went out built
 * exactly as Shortest Path's handler reads it. Not that a line is drawn on
 * screen: {@code EventBus#post} is fire-and-forget, and seeing the path still
 * needs a human at a running client.
 *
 * <p><b>Why {@link #availability()} degrades three ways.</b> The running
 * instance is found through a {@code Supplier<Collection<?>>} of loaded plugins
 * (production: {@code PluginManager#getPlugins}) matched by class name, the
 * same "is this plugin loaded" check RuneLite's own {@code PluginManager}
 * makes, with no reflective member access. A missing or disabled Shortest Path
 * must be visible and distinct: a silent no-op reads as "nothing needed".
 *
 * <p><b>{@link #eventPoster} must land the {@code EventBus#post} call on the
 * client thread.</b> Shortest Path's {@code onPluginMessage} asserts it is on
 * the client thread and does nothing to get there, and {@code EventBus#post}
 * calls subscribers on the caller's thread. Quest Path first wired a bare
 * {@code eventBus::post} from a Swing button and every click threw {@code
 * AssertionError}; build the poster with {@link #clientThreadEventPoster}.
 * That {@code AssertionError} is also why the catches below take {@code
 * RuntimeException | AssertionError}: {@code EventBus#post}'s per-subscriber
 * catch covers only {@code Exception}, never an {@code Error}.
 *
 * <p><b>Shortest Path clears its own path on arrival</b>, within its {@code
 * reachedDistance} (5 tiles by default), with no event to react to. This
 * plugin's {@code PathSession} clears or moves on only when the item itself is
 * done.
 */
@Slf4j
class ShortestPathBridge
{
	/** Shortest Path's own plugin class, matched by name. Confirmed against the installed jar. */
	static final String PLUGIN_CLASS_NAME = "shortestpath.ShortestPathPlugin";

	/**
	 * The {@code PluginMessage} name that clears Shortest Path's route.
	 *
	 * <p>A separate message from {@link #MESSAGE_NAME}: a {@code path} message
	 * with an empty target set does not clear, it re-sends the previous
	 * targets ({@code onPluginMessage} calls {@code restartPathfinding} with
	 * {@code pathfinder.getTargets()} when the set is empty). Quest Path shipped
	 * that bug once; the player's words were that "stop the route" made it
	 * "flick to the last one, then back, and stay".
	 */
	static final String CLEAR_MESSAGE_NAME = "clear";

	/** The {@code PluginMessage} namespace Shortest Path listens on ({@code ShortestPathPlugin.CONFIG_GROUP}). */
	static final String CONFIG_GROUP = "shortestpath";

	/** The {@code PluginMessage} name Shortest Path listens for ({@code ShortestPathPlugin.PLUGIN_MESSAGE_PATH}). */
	static final String MESSAGE_NAME = "path";

	/**
	 * The data-map key Shortest Path reads its destination set from
	 * ({@code ShortestPathPlugin.PLUGIN_MESSAGE_TARGET}). This class only ever
	 * sends a {@code Set<WorldPoint>}.
	 */
	static final String TARGET_KEY = "target";

	/** Whether a route can be handed to Shortest Path right now, and why not when it cannot. */
	enum Availability
	{
		/** Reachable. */
		AVAILABLE("Path to with Shortest Path"),
		NOT_INSTALLED("Shortest Path is not installed"),
		NOT_ENABLED("Shortest Path is not enabled"),
		/** Present and enabled, but something this class depends on did not resolve. */
		UNAVAILABLE("Shortest Path integration unavailable");

		private final String menuLabel;

		Availability(String menuLabel)
		{
			this.menuLabel = menuLabel;
		}

		/** The exact text to put in front of the player; doubles as the reason. */
		String menuLabel()
		{
			return menuLabel;
		}
	}

	/** What became of a {@link #route} call. */
	enum RouteOutcome
	{
		/** {@link #availability()} was not {@link Availability#AVAILABLE} when the call landed. */
		UNAVAILABLE,
		/** Called with an empty or null destination set: never posted, an empty set is not a route. */
		NO_DESTINATIONS,
		/**
		 * {@link #eventPoster} threw while this method could still see it. Off the
		 * client thread (the panel's buttons) the post is only enqueued, so this
		 * means the hand-off itself failed.
		 */
		CALL_FAILED,
		/**
		 * Handed to {@link #eventPoster} without throwing. <b>Not</b>
		 * confirmation that Shortest Path acted on it: there is no read-back.
		 */
		SENT,
	}

	private final Supplier<Collection<?>> plugins;
	private final Predicate<Object> pluginEnabled;
	private final String pluginClassName;

	/** Posts an event; in production built with {@link #clientThreadEventPoster}, never a bare {@code eventBus::post}. */
	private final Consumer<Object> eventPoster;

	/**
	 * Production wiring: the real plugin list, the real event bus.
	 *
	 * @param plugins every plugin RuneLite currently knows about, e.g. {@code pluginManager::getPlugins}
	 * @param pluginEnabled whether a given plugin instance is switched on
	 * @param eventPoster built with {@link #clientThreadEventPoster}
	 */
	ShortestPathBridge(Supplier<Collection<?>> plugins, Predicate<Object> pluginEnabled, Consumer<Object> eventPoster)
	{
		this(plugins, pluginEnabled, PLUGIN_CLASS_NAME, eventPoster);
	}

	/**
	 * Test seam: the plugin class name is overridable so a test can point
	 * {@link #findPlugin} at a fixture instead of a real Shortest Path, which is
	 * not on this project's classpath.
	 */
	ShortestPathBridge(Supplier<Collection<?>> plugins, Predicate<Object> pluginEnabled, String pluginClassName,
		Consumer<Object> eventPoster)
	{
		this.plugins = plugins;
		this.pluginEnabled = pluginEnabled;
		this.pluginClassName = pluginClassName;
		this.eventPoster = eventPoster;
	}

	/**
	 * A poster that always lands {@code post} on the client thread, whichever
	 * thread calls it. Takes the hand-off as a plain {@code Consumer<Runnable>}
	 * so a test can stand in for {@code ClientThread}; production passes
	 * {@code clientThread::invoke}.
	 */
	static Consumer<Object> clientThreadEventPoster(Consumer<Runnable> onClientThread, Consumer<Object> post)
	{
		return object -> onClientThread.accept(() -> post.accept(object));
	}

	/** Whether a route can be handed to Shortest Path right now, and why not when it cannot. */
	Availability availability()
	{
		Object plugin = findPlugin();
		if (plugin == null)
		{
			return Availability.NOT_INSTALLED;
		}
		if (!isEnabledSafely(plugin))
		{
			return Availability.NOT_ENABLED;
		}
		return Availability.AVAILABLE;
	}

	/**
	 * Clears whatever path Shortest Path is drawing, with its own {@code clear}
	 * message. Deliberately not {@code route(emptySet())}: see
	 * {@link #CLEAR_MESSAGE_NAME}.
	 *
	 * @return whether the message went out
	 */
	boolean clear()
	{
		if (availability() != Availability.AVAILABLE)
		{
			log.debug("Not clearing the Shortest Path route: {}", availability());
			return false;
		}
		try
		{
			eventPoster.accept(new PluginMessage(CONFIG_GROUP, CLEAR_MESSAGE_NAME, Map.of()));
			log.debug("Cleared the Shortest Path route");
			return true;
		}
		catch (RuntimeException | AssertionError e)
		{
			log.warn("Clearing the Shortest Path route threw", e);
			return false;
		}
	}

	/**
	 * Posts destinations to Shortest Path as one target set.
	 *
	 * @param destinations handed to Shortest Path as they are
	 * @param onOutcome called exactly once, before this method returns
	 */
	void route(Set<WorldPoint> destinations, Consumer<RouteOutcome> onOutcome)
	{
		if (availability() != Availability.AVAILABLE)
		{
			log.debug("Not sending a route to Shortest Path: {}", availability());
			onOutcome.accept(RouteOutcome.UNAVAILABLE);
			return;
		}
		if (destinations == null || destinations.isEmpty())
		{
			onOutcome.accept(RouteOutcome.NO_DESTINATIONS);
			return;
		}
		try
		{
			Map<String, Object> data = Map.of(TARGET_KEY, destinations);
			eventPoster.accept(new PluginMessage(CONFIG_GROUP, MESSAGE_NAME, data));
		}
		// Not Throwable: an OutOfMemoryError here is not "Shortest Path didn't get the route".
		catch (RuntimeException | AssertionError e)
		{
			log.warn("Posting PluginMessage(\"{}\", \"{}\", ...) with {} destination(s) failed"
				+ ": Shortest Path may be out of date", CONFIG_GROUP, MESSAGE_NAME, destinations.size(), e);
			onOutcome.accept(RouteOutcome.CALL_FAILED);
			return;
		}
		// The one place a "the button does nothing" report can be checked from the client log.
		log.info("Sent {} destination(s) to Shortest Path", destinations.size());
		onOutcome.accept(RouteOutcome.SENT);
	}

	private boolean isEnabledSafely(Object plugin)
	{
		try
		{
			return pluginEnabled.test(plugin);
		}
		catch (RuntimeException e)
		{
			log.warn("Could not read Shortest Path's enabled state", e);
			return false;
		}
	}

	private Object findPlugin()
	{
		Collection<?> loaded;
		try
		{
			loaded = plugins.get();
		}
		catch (RuntimeException e)
		{
			log.warn("Could not list loaded plugins while looking for Shortest Path", e);
			return null;
		}
		if (loaded == null)
		{
			return null;
		}
		for (Object candidate : loaded)
		{
			if (candidate != null && pluginClassName.equals(candidate.getClass().getName()))
			{
				return candidate;
			}
		}
		return null;
	}
}

package com.vinnyvangogh.groupironman;

/**
 * The sidebar button's lifecycle: added on startUp, removed on shutDown, and
 * never touched by a config change. With every switch off the panel shows a
 * notice instead of disappearing (Board 2026-11-13: a friend with every switch
 * off saw no panel at all and took the plugin for broken).
 */
final class SidebarButton
{
	static final String OFF_TEXT = "Everything is off. Turn on what you want to share.";
	static final String OFF_BUTTON = "Open GIM Utilities settings";

	private final Runnable add;
	private final Runnable remove;
	private boolean shown;

	SidebarButton(Runnable add, Runnable remove)
	{
		this.add = add;
		this.remove = remove;
	}

	void startUp()
	{
		if (!shown)
		{
			add.run();
			shown = true;
		}
	}

	void shutDown()
	{
		if (shown)
		{
			remove.run();
			shown = false;
		}
	}

	boolean shown()
	{
		return shown;
	}

	/** Whether the panel leads with the "everything is off" notice. */
	static boolean offNotice(boolean anyOn)
	{
		return !anyOn;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Locale;

/**
 * A carried container whose contents the game only tells through chat lines
 * and its Check dialog: log basket, fish barrel and coal bag. Their count is
 * drawn on the container's inventory slot (Board 2026-11-14).
 *
 * Copied from Combat Vitals' {@code SkillingContainer} (same author, not a
 * dependency), trimmed to the chat-tracked kinds. Capacities from the OSRS
 * wiki ("Log basket", "Fish barrel", "Coal bag", read 2026-11-14). The gem
 * bag, herb sack, seed box and essence pouches are left out: the first three
 * say nothing countable in chat, and the pouches' counts are already live in
 * varbits the game sends, which this plugin does not share yet; with no
 * number known, none is drawn.
 *
 * The enum name is what goes on the wire ({@code cc} in a carried message),
 * so it freezes with the first build that sends it.
 */
enum SkillingContainer
{
	/** Log basket and Forestry basket: 28 logs of any kind. */
	LOG_BASKET("Log basket", 28, "log basket", "forestry basket"),
	/** Fish barrel and Fish sack barrel: 28 raw fish of any kind. */
	FISH_BARREL("Fish barrel", 28, "fish barrel", "fish sack barrel"),
	/** 27 coal, 36 with a Smithing cape. */
	COAL_BAG("Coal bag", 27, "coal bag");

	static final int COAL_BAG_CAPE_CAPACITY = 36;
	private static final String OPEN = "open ";

	/** "Log basket": the container's name in Find ("log basket"). */
	final String label;
	final int capacity;
	private final String[] names;

	SkillingContainer(String label, int capacity, String... names)
	{
		this.label = label;
		this.capacity = capacity;
		this.names = names;
	}

	/** The container an item is, by its name, open or closed; null for anything else. */
	static SkillingContainer fromItemName(String name)
	{
		if (name == null)
		{
			return null;
		}
		String lower = name.toLowerCase(Locale.ROOT).trim();
		if (lower.startsWith(OPEN))
		{
			lower = lower.substring(OPEN.length());
		}
		for (SkillingContainer container : values())
		{
			for (String n : container.names)
			{
				if (n.equals(lower))
				{
					return container;
				}
			}
		}
		return null;
	}

	/** "Open log basket": gathered items go straight in while it is open. */
	static boolean isOpen(String name)
	{
		return name != null && name.toLowerCase(Locale.ROOT).startsWith(OPEN);
	}

	/** The kind a wire key names, or null for a key from a newer build. */
	static SkillingContainer fromKey(String key)
	{
		for (SkillingContainer container : values())
		{
			if (container.name().equals(key))
			{
				return container;
			}
		}
		return null;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Locale;
import java.util.function.Consumer;

/**
 * Slayer task posts (Board live test 2026-11-10): "New Slayer task: 19 x Icefiends (Turael)" and
 * "Slayer task done: Icefiends (streak 1, 2 points)". Pure; client thread.
 *
 * <ul>
 * <li>A new task is the master's dialogue, a partner's assignment, or the gem naming a task other than the one
 * this session already knows. The gem only repeats a task, so the first gem check after a login is a baseline,
 * and the same task is never posted twice.</li>
 * <li>A task is done on the streak line that sends you back to a Slayer master, named from the "You have
 * completed your task!" line before it. That line alone posts after {@link #DONE_WAIT_TICKS} ticks.</li>
 * </ul>
 *
 * <p>A new task's {@link GroupEvent#number} is its amount, at least 1; a finished task's is 0. {@link
 * GroupEvent#detail} is who gave it, or the streak.
 */
final class SlayerWatch
{
	/** Ticks the "You have completed your task!" line waits for its streak line. */
	static final int DONE_WAIT_TICKS = 2;

	private final Consumer<GroupEvent> out;
	/** The held task, lower case: null until this session has seen one, empty for none. */
	private String task;
	private String taskName = "";
	/** A finished task still waiting for its streak line. */
	private String killed;
	private int killedWait;
	private String lastDialog = "";

	SlayerWatch(Consumer<GroupEvent> out)
	{
		this.out = out;
	}

	void reset()
	{
		task = null;
		taskName = "";
		killed = null;
		killedWait = 0;
		lastDialog = "";
	}

	/** One game chat line. */
	void chat(String message, long now, String me)
	{
		String name = EventChat.slayerKilled(message);
		if (name != null)
		{
			killed = name;
			killedWait = DONE_WAIT_TICKS;
			return;
		}
		long[] done = EventChat.slayerDone(message);
		if (done != null)
		{
			done(streak(done[0], done[1]), now, me);
			return;
		}
		if (EventChat.slayerCleared(message))
		{
			held("");
			return;
		}
		assigned(EventChat.slayerChat(message), now, me);
	}

	/** Each tick: the NPC dialogue's text and speaker, null text when none is open. */
	void dialog(String text, String npc, long now, String me)
	{
		String line = text == null ? "" : text;
		if (line.equals(lastDialog))
		{
			return;
		}
		lastDialog = line;
		if (!line.isEmpty())
		{
			assigned(EventChat.slayerDialog(line, npc), now, me);
		}
	}

	/** Each tick: a finished task whose streak line never came posts on its own. */
	void tick(long now, String me)
	{
		if (killed != null && --killedWait <= 0)
		{
			done("", now, me);
		}
	}

	private void assigned(EventChat.SlayerTask t, long now, String me)
	{
		if (t == null)
		{
			return;
		}
		String was = task;
		boolean changed = was != null && !was.equals(key(t.name));
		held(t.name);
		if ((t.fresh || changed) && t.amount > 0)
		{
			out.accept(GroupEvent.of(GroupEvent.Type.SLAYER, now, me).text(t.name).number(t.amount).detail(t.from)
				.build());
		}
	}

	private void done(String detail, long now, String me)
	{
		String name = killed != null ? killed : taskName;
		killed = null;
		held("");
		out.accept(GroupEvent.of(GroupEvent.Type.SLAYER, now, me).text(name.isEmpty() ? "task" : name)
			.detail(detail).build());
	}

	private void held(String name)
	{
		task = key(name);
		taskName = name;
	}

	private static String key(String name)
	{
		return name.trim().toLowerCase(Locale.ROOT);
	}

	/** "streak 1, 2 points"; just the streak when the line gives no points. */
	static String streak(long streak, long points)
	{
		String s = "streak " + streak;
		return points < 0 ? s : s + ", " + points + (points == 1 ? " point" : " points");
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * The item whose icon the game draws for a stack (Board 2026-11-10: a coin
 * thumbnail was always one coin). Discord's thumbnails are RuneLite's static
 * icon per item id, so the pile is picked here by id.
 *
 * <p>The game keeps this as an item's {@code countObj}/{@code countCo} arrays
 * (runelite cache {@code ItemDefinition}); RuneLite's API {@code ItemComposition}
 * does not expose them, and {@code ItemManager.getImage(id, quantity, stackable)}
 * only passes the quantity to the client's sprite drawing. So the table below
 * mirrors the cache, and {@link #variant} is the cache's own selection loop
 * (runelite cache {@code ItemSpriteFactory.createSpritePixels}): above a stack
 * of one, the last threshold the quantity reaches wins. Ids are
 * {@code net.runelite.api.gameval.ItemID}: COINS 995, COINS_2..COINS_10000
 * 996..1004. An item not listed keeps its own id, as before.
 */
final class StackIcons
{
	private static final Map<Integer, long[][]> VARIANTS;

	static
	{
		Map<Integer, long[][]> v = new HashMap<>();
		// {countCo thresholds}, {countObj ids}
		v.put(995, new long[][]{{2, 3, 4, 5, 25, 100, 250, 1_000, 10_000}, {996, 997, 998, 999, 1000, 1001, 1002, 1003,
			1004}});
		VARIANTS = Collections.unmodifiableMap(v);
	}

	private StackIcons()
	{
	}

	/** The id whose icon shows a stack of {@code quantity} of {@code itemId}. */
	static int variant(int itemId, long quantity)
	{
		long[][] table = VARIANTS.get(itemId);
		if (table == null || quantity <= 1)
		{
			return itemId;
		}
		int out = itemId;
		for (int i = 0; i < table[0].length; i++)
		{
			if (quantity >= table[0][i])
			{
				out = (int) table[1][i];
			}
		}
		return out;
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.TreeSet;
import java.util.concurrent.TimeUnit;
import java.util.function.LongSupplier;
import java.util.function.Supplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The live online board (Board 2026-11-10): one message in the Group channel, one line per member, edited on
 * every login, logout and hop instead of a post for each.
 *
 * <p>Discord's webhook API (discord/discord-api-docs 36adecb, developers/resources/webhook.mdx): Execute Webhook
 * with {@code ?wait=true} "returns the created message body", whose {@code id} is kept; Edit Webhook Message is
 * {@code PATCH /webhooks/{id}/{token}/messages/{message.id}} and "edits a previously-sent webhook message from
 * the same token". It takes {@code content}, {@code embeds} and {@code allowed_mentions}, not {@code username}.
 *
 * <ul>
 * <li>The first send for a webhook posts the board and keeps its id ({@link #takeSaved}, this client's own file
 * only, never the party), keyed by the webhook's id from its URL. Every later send edits it, after a restart
 * too; an edit Discord answers 404 (deleted) posts a new one. Any new board deletes the ones before it.</li>
 * <li>Nothing is sent until the keeper says its inputs have settled ({@link #settle}), so a restart never posts
 * to the webhook the board is on for a moment before the leader's role and shared webhooks load.</li>
 * <li>Once a day (Board 2026-11-14, 'Repost board daily'), the first send after the keeper's midnight posts a
 * new board, then deletes the old one (Delete Webhook Message, {@code DELETE .../messages/{message.id}}) once
 * the new id is saved, so the board is back at the bottom of the channel and the channel still holds one.</li>
 * <li>At most one send per {@link #MIN_GAP_MS}, and none in quiet hours. Only the newest lines are ever sent,
 * and only when they changed.</li>
 * <li>"Last seen" is Discord's own relative timestamp ({@code <t:...:R>}), so the board stays right as time
 * passes without an edit.</li>
 * <li>Requests go through the {@link DiscordSender}'s queue like every post (its edit path for an edit), so the
 * board shares the queue's {@link DiscordQueue#PER_MINUTE} limit, its 429 and retry handling, and its
 * {@code thread_id}-keeping URLs. One request is with the queue at a time.</li>
 * </ul>
 *
 * The send state is guarded by this object: the timer sends, OkHttp's thread answers.
 */
final class StatusBoard
{
	static final long MIN_GAP_MS = TimeUnit.SECONDS.toMillis(10);

	/**
	 * Whether this client keeps the live board: 'Online status' is the board and the Online status webhook (or
	 * Main) is set. On a webhook the leader shares, only the leader's client does, so a group whose members all
	 * pick the board on the shared webhook still gets one board (each member's own pasted webhook is theirs, as
	 * before: the setting's description asks that only one member sharing a webhook turn the board on).
	 */
	static boolean keeps(OnlineStatus status, Webhooks webhooks, boolean leader)
	{
		if (status != OnlineStatus.LIVE_BOARD || webhooks.url(Webhook.ONLINE) == null)
		{
			return false;
		}
		return leader || !webhooks.fromGroup(Webhook.ONLINE);
	}
	static final String TITLE = "Group status";
	static final String ONLINE = "🟢";
	static final String OFFLINE = "🔴";
	static final String UNKNOWN = "⚪";
	/** After a member the game shows but whose client never reported: they do not run the plugin. */
	static final String NO_PLUGIN = " *(no plugin)*";
	/** The board's last line when no plugin user is online to keep it current (Board 2026-11-11). */
	static final String STALE = "Nobody with GIM Utilities is online, so these may be out of date";
	private static final String SEP = "\t";

	/** This client's own player, which it knows better than the party does. */
	static final class Self
	{
		final String name;
		final boolean online;
		final int world;
		/** When it logged out; 0 while online. */
		final long seenAt;

		Self(String name, boolean online, int world, long seenAt)
		{
			this.name = name;
			this.online = online;
			this.world = world;
			this.seenAt = seenAt;
		}
	}

	/** One request: the board posted, the one already posted edited, or yesterday's deleted. */
	static final class Send
	{
		final String url;
		/** Null to post a new board; the board to delete for a delete. */
		final String messageId;
		/** Null for a delete. */
		final String lines;
		final long changedAt;
		/** A daily repost: the board it replaces, deleted once the new one's id is saved; else null. */
		final String replaces;
		/** The keeper's day ({@link LocalDate#toEpochDay}) the request was made on. */
		final long day;
		final boolean delete;

		Send(String url, String messageId, String lines, long changedAt)
		{
			this(url, messageId, lines, changedAt, null, UNKNOWN_DAY, false);
		}

		private Send(String url, String messageId, String lines, long changedAt, String replaces, long day,
			boolean delete)
		{
			this.url = url.endsWith("/") ? url.substring(0, url.length() - 1) : url;
			this.messageId = messageId;
			this.lines = lines;
			this.changedAt = changedAt;
			this.replaces = replaces;
			this.day = day;
			this.delete = delete;
		}

		boolean create()
		{
			return messageId == null;
		}
	}

	/** The day of a board saved before daily reposts, or posted without them: the next repost brings it down. */
	private static final long UNKNOWN_DAY = Long.MIN_VALUE;
	/** The most earlier boards kept to delete; an older one past this is left. */
	static final int MAX_OLD = 5;
	/**
	 * How long after the session's first login before the board may send (Board 2026-11-14, reposted 3x): the
	 * leader's role, the shared webhooks and the group cache are in by then, so the first send goes to the webhook
	 * the board settles on, not the Main fallback a moment before.
	 */
	static final long SETTLE_MS = TimeUnit.SECONDS.toMillis(20);
	/** Webhook URL path: {@code /api/webhooks/{id}/{token}}. The id names the webhook in every URL form. */
	private static final Pattern HOOK = Pattern.compile("/webhooks/(\\d{1,20})/");
	private static final String DIGITS = "\\d{1,20}";

	private String url;
	/** The webhook the board lives on, as saved: "w" and its id from the URL; null with no webhook. */
	private String hook;
	private String messageId;
	/** The keeper's day the board was posted on. */
	private long postedDay = UNKNOWN_DAY;
	/** Earlier boards on this webhook, oldest first, to delete now that the newest one's id is saved. */
	private final List<String> oldIds = new ArrayList<>();
	private boolean idChanged;
	private boolean settled = true;
	private String lines;
	private long changedAt;
	private String sentLines;
	private long lastTry = Long.MIN_VALUE / 2;
	private long notBefore;
	private Send inFlight;

	/**
	 * The webhook the board lives on, null when there is none (Discord off, another mode). {@code saved} is the
	 * saved boards ({@link #merge} of {@link #takeSaved}'s lines), read only when the webhook changes; a different
	 * webhook starts a new board. The same webhook in another URL form ({@code thread_id}, a trailing slash,
	 * discordapp.com) is the same board.
	 */
	synchronized void target(String url, Supplier<String> saved)
	{
		String hook = hookOf(url);
		if (Objects.equals(hook, this.hook))
		{
			this.url = hook == null ? null : url;
			return;
		}
		this.url = hook == null ? null : url;
		this.hook = hook;
		restore(hook == null ? null : savedLine(url, hook, saved.get()));
		sentLines = null;
		inFlight = null;
	}

	/** Holding the lock: the saved fields ({@link #savedLine}) for the webhook just targeted; null for none. */
	private void restore(String[] f)
	{
		String[] g = f == null ? new String[]{hook} : f;
		messageId = g.length < 2 || g[1].isEmpty() ? null : g[1];
		postedDay = g.length < 3 || g[2].isEmpty() ? UNKNOWN_DAY : Long.parseLong(g[2]);
		oldIds.clear();
		if (g.length == 4 && !g[3].isEmpty())
		{
			oldIds.addAll(Arrays.asList(g[3].split(",")));
		}
		// A line saved under the old URL-hash tag is saved again under the webhook's id.
		idChanged = !Objects.equals(g[0], hook);
	}

	/**
	 * Whether the board may send yet: false holds every request (Board 2026-11-14). Set by the keeper each tick
	 * from {@link #settled(long, long, boolean)}; true until then, so a board without a keeper's say sends.
	 */
	synchronized void settle(boolean settled)
	{
		this.settled = settled;
	}

	/**
	 * True once the inputs that decide the board's webhook have settled: the session's first login was
	 * {@link #SETTLE_MS} ago ({@code loginAt}, 0 before one) and the saved boards and group cache are read.
	 */
	static boolean settled(long loginAt, long now, boolean loaded)
	{
		return loaded && loginAt > 0 && now - loginAt >= SETTLE_MS;
	}

	/** The saved tag for {@code url}'s webhook: "w" and the id in its path; null when it is not a webhook URL. */
	static String hookOf(String url)
	{
		Matcher m = url == null ? null : HOOK.matcher(url);
		return m != null && m.find() ? "w" + m.group(1) : null;
	}

	/** The board's lines now; the edit time moves only when they change. */
	synchronized void show(String now, long at)
	{
		if (!now.equals(lines))
		{
			lines = now;
			changedAt = at;
		}
	}

	/** {@link #next(long, boolean, long, boolean)} without daily reposts. */
	synchronized Send next(long now, boolean quiet)
	{
		return next(now, quiet, UNKNOWN_DAY, false);
	}

	/**
	 * The request to make now, or null: nothing new, one in flight, quiet hours, the gap or a Retry-After.
	 * {@code day} is the keeper's local day ({@link LocalDate#toEpochDay}); with {@code repost} on, the first send
	 * on a later day than the board was posted posts a new board instead of editing (Board 2026-11-14: Discord
	 * cannot move a message, so the board comes back to the bottom of the channel as a new one). Yesterday's is
	 * deleted after, once the new id is saved ({@link #takeSaved}): a failed post never leaves no board.
	 */
	synchronized Send next(long now, boolean quiet, long day, boolean repost)
	{
		if (held(now))
		{
			return null;
		}
		if (!oldIds.isEmpty() && !idChanged)
		{
			// Deleting makes no noise in the channel, so neither quiet hours nor the gap hold it.
			return send(now, new Send(url, oldIds.get(0), null, 0, null, day, true));
		}
		String replaces = repost ? reposting(day) : null;
		if (!due(replaces) || quiet || now - lastTry < MIN_GAP_MS)
		{
			return null;
		}
		return send(now, new Send(url, replaces == null ? messageId : null, lines, changedAt, replaces, day, false));
	}

	/** Holding the lock: no webhook, not settled yet, a request already out, or a Retry-After still running. */
	private boolean held(long now)
	{
		return url == null || !settled || inFlight != null || now < notBefore;
	}

	/** Holding the lock: the board a post on {@code day} replaces, when one was posted on an earlier day. */
	private String reposting(long day)
	{
		return day > postedDay ? messageId : null;
	}

	/** Holding the lock: there are lines to send, and they changed or the day's repost is due. */
	private boolean due(String replaces)
	{
		return lines != null && (replaces != null || !lines.equals(sentLines));
	}

	/** Holding the lock: {@code send} goes out now. */
	private Send send(long now, Send send)
	{
		lastTry = now;
		inFlight = send;
		return send;
	}

	/** How {@code send} went: an HTTP status (0 for none), the new message's id for a post, a 429's wait. */
	synchronized void done(Send send, int status, String newId, long retryAfterMs, long now)
	{
		if (send != inFlight)
		{
			// The webhook changed while it was out.
			return;
		}
		inFlight = null;
		if (send.delete)
		{
			deleted(send, status, retryAfterMs, now);
		}
		else if (status >= 200 && status < 300)
		{
			sent(send, newId);
		}
		else
		{
			failed(send, status, retryAfterMs, now);
		}
	}

	/** Holding the lock: Discord refused {@code send}, a post or an edit, or it never got there. */
	private void failed(Send send, int status, long retryAfterMs, long now)
	{
		if (status == 404 && !send.create())
		{
			// Deleted in Discord: the next send posts a new board.
			messageId = null;
			idChanged = true;
		}
		else if (status == 429)
		{
			waitRetryAfter(retryAfterMs, now);
		}
		else if (status >= 400)
		{
			// A bad or deleted webhook: retrying cannot fix it, so wait for the lines to change. A failed repost
			// keeps yesterday's board, edited, until tomorrow's.
			sentLines = send.lines;
			postedDay = send.replaces == null ? postedDay : send.day;
		}
	}

	/**
	 * Holding the lock: Discord took {@code send}; a post's answer carries the board's id. Every new board, for
	 * whatever reason it was posted, puts the one it follows on the list to delete (Board 2026-11-14: one board
	 * per webhook). A repost whose id is unreadable keeps editing the old board, which is then not deleted.
	 */
	private void sent(Send send, String newId)
	{
		sentLines = send.lines;
		if (!send.create())
		{
			return;
		}
		postedDay = send.day;
		if (newId != null)
		{
			addOld(messageId);
			messageId = newId;
			idChanged = true;
		}
	}

	/** Holding the lock: {@code id} joins the boards to delete, the oldest dropped past {@link #MAX_OLD}. */
	private void addOld(String id)
	{
		if (id == null || oldIds.contains(id))
		{
			return;
		}
		oldIds.add(id);
		while (oldIds.size() > MAX_OLD)
		{
			oldIds.remove(0);
		}
	}

	/**
	 * Holding the lock: how deleting an earlier board went. A 429 or a dropped request tries again; anything
	 * else, a 404 (already gone) too, is the end of it: a board that cannot be deleted is left.
	 */
	private void deleted(Send send, int status, long retryAfterMs, long now)
	{
		if (status == 429)
		{
			waitRetryAfter(retryAfterMs, now);
		}
		else if (status != DiscordQueue.DROPPED)
		{
			oldIds.remove(send.messageId);
			idChanged = true;
		}
	}

	/** Holding the lock: a 429 holds every request for its Retry-After, or the gap when it gave none. */
	private void waitRetryAfter(long retryAfterMs, long now)
	{
		notBefore = now + (retryAfterMs >= 0 ? retryAfterMs : MIN_GAP_MS);
	}

	/**
	 * This webhook's line to {@link #merge} into the saved boards when it changed since the last call, else null:
	 * the webhook's tag ({@link #hookOf}: its id, never the token), the board's id, the day it was posted, and the
	 * earlier boards still to delete, comma-separated. Empty fields at the end are left off; the tag alone
	 * forgets the webhook's board.
	 */
	synchronized String takeSaved()
	{
		if (!idChanged || hook == null)
		{
			return null;
		}
		idChanged = false;
		String id = messageId == null ? "" : messageId;
		String day = messageId == null || postedDay == UNKNOWN_DAY ? "" : Long.toString(postedDay);
		String line = hook + SEP + id + SEP + day + SEP + String.join(",", oldIds);
		while (line.endsWith(SEP))
		{
			line = line.substring(0, line.length() - SEP.length());
		}
		return line;
	}

	/**
	 * The saved boards with {@code line} ({@link #takeSaved}) in place of its webhook's old one: one line per
	 * webhook. Lines under the old URL-hash tag go, since a target reads them only once.
	 */
	static String merge(String saved, String line)
	{
		String hook = line.split(SEP, -1)[0];
		List<String> out = new ArrayList<>();
		for (String l : saved == null ? new String[0] : saved.split("\n"))
		{
			String tag = l.split(SEP, -1)[0];
			if (tag.startsWith("w") && !tag.equals(hook))
			{
				out.add(l);
			}
		}
		if (!line.equals(hook))
		{
			out.add(line);
		}
		return String.join("\n", out);
	}

	/** The tag lines were saved under before webhook ids: a hash of the whole URL, so any URL change lost it. */
	private static String legacyTag(String url)
	{
		return Integer.toHexString(url.hashCode());
	}

	/** This webhook's saved fields, else null: tag, id, and maybe the day and the boards to delete. */
	private static String[] savedLine(String url, String hook, String saved)
	{
		String[] legacy = null;
		for (String line : saved == null ? new String[0] : saved.split("\n"))
		{
			String[] f = line.split(SEP, -1);
			if (f[0].equals(hook) && wellFormed(f))
			{
				return f;
			}
			legacy = f[0].equals(legacyTag(url)) && wellFormed(f) ? f : legacy;
		}
		return legacy;
	}

	private static boolean wellFormed(String[] f)
	{
		if (f.length < 2 || f.length > 4)
		{
			return false;
		}
		boolean ok = f[1].isEmpty() || f[1].matches(DIGITS);
		// The day is parsed as a long, so it is held to 18 digits; ids stay text.
		ok &= f.length < 3 || f[2].isEmpty() || f[2].matches("\\d{1,18}");
		return ok && (f.length < 4 || f[3].isEmpty() || f[3].matches(DIGITS + "(," + DIGITS + ")*"));
	}

	// ---- What it says ----

	/** {@link #lines(GroupMembers, Map, Map, Self, GamePresence, long)} without the game's Group channel. */
	static String lines(GroupMembers roster, Map<String, Long> heard, Map<String, MemberStats> stats, Self self,
		long now)
	{
		return lines(roster, heard, stats, self, GamePresence.UNKNOWN, now);
	}

	/**
	 * One line per member: the game's roster when known, else everyone heard from or in the channel. When the
	 * game says ({@link GamePresence}, the in-game Group channel) a member is online or offline, that is the line,
	 * with " (no plugin)" for a member whose client was never heard from. Otherwise a member is online while their
	 * client is heard from ({@link Presence}), offline with when it last was, and unknown when it never was.
	 * Empty when there is no one to list.
	 */
	static String lines(GroupMembers roster, Map<String, Long> heard, Map<String, MemberStats> stats, Self self,
		GamePresence game, long now)
	{
		return lines(roster, heard, Collections.emptyMap(), stats, self, game, now);
	}

	/**
	 * As above, with {@code seen}: when this client last saw each member online ({@link LastSeen}, kept in the
	 * group cache). An offline member reads "last seen" that long ago, on the world they were on. When nobody
	 * running the plugin is online ({@link #nobodyOnline}) the board can be edited by no one, so it ends with
	 * {@link #STALE} and when that became true, and a member no one can see reads unknown with their last seen.
	 */
	static String lines(GroupMembers roster, Map<String, Long> heard, Map<String, LastSeen> seen,
		Map<String, MemberStats> stats, Self self, GamePresence game, long now)
	{
		return lines(roster, heard, seen, stats, self, game, Collections.emptyMap(), now);
	}

	/**
	 * As above, with {@code activities}: each online member's coarse activity clause by {@link GroupMembers#key}
	 * ({@link #activitySuffixes}), " - in Fight Caves, wave 35", appended to their online line only.
	 */
	static String lines(GroupMembers roster, Map<String, Long> heard, Map<String, LastSeen> seen,
		Map<String, MemberStats> stats, Self self, GamePresence game, Map<String, String> activities, long now)
	{
		List<String> base = baseLines(roster, heard, seen, stats, self, game, now);
		// The same names, in the same order, as baseLines' lines.
		List<String> names = new ArrayList<>(names(roster, heard, seen.keySet(), self, game));
		for (int i = 0; i < names.size() && i < base.size(); i++)
		{
			String suffix = activities.get(GroupMembers.key(names.get(i)));
			if (suffix != null && base.get(i).startsWith(ONLINE))
			{
				base.set(i, base.get(i) + suffix);
			}
		}
		return String.join("\n", base);
	}

	/**
	 * Board clauses for members in an activity: " - in Fight Caves, wave 35", the activity's coarse
	 * {@link ActivityState#board} (no percentages, so the message is not edited every few ticks). A member who opted
	 * out of activity posts ("Don't post my events", or "Activity started" not posted) is left off, and this player
	 * too unless they share group events: the board is Discord, and their choice covers it.
	 */
	static Map<String, String> activitySuffixes(Map<String, ActivityState> activities, Map<String, MemberPrefs> prefs,
		String self, MemberPrefs mine, boolean shareMine)
	{
		Map<String, MemberPrefs> prefsBy = new HashMap<>();
		prefs.forEach((name, p) -> prefsBy.put(GroupMembers.key(name), p));
		String selfKey = GroupMembers.key(self == null ? "" : self);
		Map<String, String> out = new HashMap<>();
		activities.forEach((name, s) ->
		{
			String key = GroupMembers.key(name);
			boolean you = key.equals(selfKey);
			MemberPrefs p = you ? mine : prefsBy.getOrDefault(key, MemberPrefs.NONE);
			if (s.active() && !s.board.isEmpty() && p.posts(GroupEvent.Type.ACTIVITY_START) && (!you || shareMine))
			{
				out.put(key, " - " + s.board);
			}
		});
		return out;
	}

	private static List<String> baseLines(GroupMembers roster, Map<String, Long> heard, Map<String, LastSeen> seen,
		Map<String, MemberStats> stats, Self self, GamePresence game, long now)
	{
		Map<String, Long> heardBy = new HashMap<>();
		heard.forEach((name, at) -> heardBy.merge(GroupMembers.key(name), at, Math::max));
		Map<String, LastSeen> seenBy = new HashMap<>();
		seen.forEach((name, s) -> seenBy.merge(GroupMembers.key(name), s, LastSeen::merge));
		Map<String, Integer> worldBy = new HashMap<>();
		stats.forEach((name, s) -> worldBy.put(GroupMembers.key(name), s.world()));
		List<String> out = new ArrayList<>();
		for (String name : names(roster, heard, seen.keySet(), self, game))
		{
			String key = GroupMembers.key(name);
			LastSeen last = seenBy.get(key);
			if (self != null && key.equals(GroupMembers.key(self.name)))
			{
				long at = Math.max(self.seenAt, last == null ? 0 : last.at);
				out.add(self.online ? online(name, self.world) : gone(OFFLINE, name, at, self.world));
				continue;
			}
			out.add(member(name, heardBy.getOrDefault(key, 0L), last, worldBy.get(key), game, now));
		}
		if (!out.isEmpty() && nobodyOnline(heardBy, self, game, now))
		{
			out.add(stale(heardBy, seenBy, self));
		}
		return out;
	}

	/** Another member's line: the game first, then their client, else unknown with when they were last seen. */
	private static String member(String name, long heardAt, LastSeen seen, Integer statsWorld, GamePresence game,
		long now)
	{
		boolean plugin = heardAt > 0 || statsWorld != null || seen != null && seen.plugin;
		long lastAt = Math.max(heardAt, seen == null ? 0 : seen.at);
		int lastWorld = lastWorld(heardAt, seen, statsWorld);
		String tag = plugin ? "" : NO_PLUGIN;
		switch (game.state(name))
		{
			case ONLINE:
				return online(name, game.world(name) > 0 ? game.world(name) : lastWorld) + tag;
			case OFFLINE:
				return gone(OFFLINE, name, lastAt, lastWorld) + tag;
			default:
				break;
		}
		if (Presence.online(heardAt, now))
		{
			return online(name, lastWorld);
		}
		if (plugin)
		{
			// Their own client would be heard from if they were on.
			return gone(OFFLINE, name, lastAt, lastWorld);
		}
		return lastAt > 0 ? gone(UNKNOWN, name, lastAt, lastWorld) + tag : UNKNOWN + " " + bold(name) + " unknown";
	}

	/** The world of the newer sighting: the game's or this client's, else their client's last stats. */
	private static int lastWorld(long heardAt, LastSeen seen, Integer statsWorld)
	{
		if (seen != null && seen.world > 0 && (seen.at >= heardAt || statsWorld == null))
		{
			return seen.world;
		}
		return statsWorld == null ? 0 : statsWorld;
	}

	/**
	 * True when no one running the plugin is online as far as this client knows: not this player, and no member
	 * heard from lately that the game does not say logged out. Then nothing can keep the board current.
	 */
	static boolean nobodyOnline(Map<String, Long> heardBy, Self self, GamePresence game, long now)
	{
		if (self != null && self.online)
		{
			return false;
		}
		String me = self == null ? null : GroupMembers.key(self.name);
		for (Map.Entry<String, Long> e : heardBy.entrySet())
		{
			if (!e.getKey().equals(me) && Presence.online(e.getValue(), now)
				&& game.state(e.getKey()) != GamePresence.State.OFFLINE)
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * The line under a board no one can edit: as of the last moment a plugin user was known online (this player's
	 * logout, or the last member heard from). Fixed, so the board is not edited again for it.
	 */
	private static String stale(Map<String, Long> heardBy, Map<String, LastSeen> seenBy, Self self)
	{
		long asOf = self == null ? 0 : self.seenAt;
		for (long at : heardBy.values())
		{
			asOf = Math.max(asOf, at);
		}
		for (LastSeen s : seenBy.values())
		{
			asOf = s.plugin ? Math.max(asOf, s.at) : asOf;
		}
		return "*" + STALE + (asOf > 0 ? " (as of " + when(asOf) + ")" : "") + "*";
	}

	private static Set<String> names(GroupMembers roster, Map<String, Long> heard, Set<String> seen, Self self,
		GamePresence game)
	{
		if (roster.known())
		{
			return roster.names();
		}
		Set<String> names = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
		names.addAll(heard.keySet());
		names.addAll(seen);
		names.addAll(game.names());
		if (self != null && !self.name.isEmpty())
		{
			names.add(self.name);
		}
		return new LinkedHashSet<>(names);
	}

	private static String online(String name, int world)
	{
		return ONLINE + " " + bold(name) + " online" + (world > 0 ? " (world " + world + ")" : "");
	}

	/** "last seen 2 hours ago on world 302", or "offline" when never seen; {@code icon} offline or unknown. */
	private static String gone(String icon, String name, long seenAt, int world)
	{
		if (seenAt <= 0)
		{
			return icon + " " + bold(name) + " offline";
		}
		return icon + " " + bold(name) + " last seen " + when(seenAt) + (world > 0 ? " on world " + world : "");
	}

	/** Discord's relative timestamp: "5 minutes ago", kept current by Discord itself. */
	private static String when(long at)
	{
		return "<t:" + at / 1000 + ":R>";
	}

	private static String bold(String name)
	{
		return "**" + name.replaceAll("([\\\\*_~`|>])", "\\\\$1") + "**";
	}

	/**
	 * The request body. Only the lines and the edit time go in: never the webhook. A new board is posted under
	 * {@code username}, the Group poster name ({@link PosterNames}), none when null; an edit takes no username.
	 */
	static String payload(Gson gson, Send send, DiscordStyle style, String username)
	{
		if (send.delete)
		{
			return null;
		}
		String text = send.lines + "\nUpdated " + when(send.changedAt);
		JsonObject o = new JsonObject();
		if (send.create() && username != null)
		{
			o.addProperty("username", username);
		}
		DiscordWebhook.allowMentions(o, false);
		JsonArray embeds = new JsonArray();
		if (style == DiscordStyle.PLAIN)
		{
			o.addProperty("content", "**" + TITLE + "**\n" + text);
		}
		else
		{
			JsonObject embed = new JsonObject();
			embed.addProperty("title", TITLE);
			embed.addProperty("description", text);
			embed.addProperty("color", GroupEvent.Category.GROUP.colour);
			JsonObject footer = new JsonObject();
			footer.addProperty("text", DiscordWebhook.USERNAME);
			embed.add("footer", footer);
			embeds.add(embed);
			if (!send.create())
			{
				// An edit after a switch from plain text clears the old text.
				o.addProperty("content", "");
			}
		}
		if (!send.create() || embeds.size() > 0)
		{
			// An edit after a switch to plain text clears the old embed.
			o.add("embeds", embeds);
		}
		return gson.toJson(o);
	}

	/**
	 * Queues {@code send} with the sender: a post that waits for its id, an edit, or a delete (no {@code json});
	 * the outcome to {@link #done}.
	 */
	void send(DiscordSender sender, Send send, String json, LongSupplier clock)
	{
		DiscordQueue.Result result = (status, id) -> done(send, status, id, -1, clock.getAsLong());
		if (send.delete)
		{
			sender.delete(send.url, send.messageId, result);
		}
		else if (send.create())
		{
			sender.post(send.url, json, null, result);
		}
		else
		{
			sender.edit(send.url, send.messageId, json, null, result);
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Map;

/**
 * One visit to group storage by one member: what they took, what they
 * deposited, and what was left in storage when they closed it.
 *
 * <p>{@code member} is filled in by the receiver from the party's own member
 * list, never read from the payload, so a peer cannot attribute a change to
 * somebody else.
 */
final class StorageChange
{
	/** Shown beside a visit this client kept to itself (Board 2026-11-13). */
	static final String NOT_SHARED = "not shared: Share group storage changes is off";

	private final long at;
	private final String member;
	private final Map<Integer, Integer> took;
	private final Map<Integer, Integer> deposited;
	private final Map<Integer, Integer> after;
	/** False for this player's own visit made while "Share group storage changes" was off: logged, never sent. */
	private final boolean shared;

	StorageChange(long at, String member, Map<Integer, Integer> took, Map<Integer, Integer> deposited,
		Map<Integer, Integer> after)
	{
		this(at, member, took, deposited, after, true);
	}

	StorageChange(long at, String member, Map<Integer, Integer> took, Map<Integer, Integer> deposited,
		Map<Integer, Integer> after, boolean shared)
	{
		this.at = at;
		this.member = member == null ? "" : member;
		this.took = ItemCounts.sorted(took);
		this.deposited = ItemCounts.sorted(deposited);
		this.after = ItemCounts.sorted(after);
		this.shared = shared;
	}

	long at()
	{
		return at;
	}

	String member()
	{
		return member;
	}

	Map<Integer, Integer> took()
	{
		return took;
	}

	Map<Integer, Integer> deposited()
	{
		return deposited;
	}

	/** Storage contents after the visit. */
	Map<Integer, Integer> after()
	{
		return after;
	}

	boolean isEmpty()
	{
		return took.isEmpty() && deposited.isEmpty();
	}

	boolean shared()
	{
		return shared;
	}

	StorageChange withMember(String name)
	{
		return new StorageChange(at, name, took, deposited, after, shared);
	}

	/** The same visit, kept on this client only. */
	StorageChange notShared()
	{
		return new StorageChange(at, member, took, deposited, after, false);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;

/**
 * What changed in group storage between the local player opening it and
 * closing it.
 *
 * <p>Works on counts, not slots: moving a stack to another slot is not a
 * change, taking 3 of a 10 stack is "took 3". Both sides should already be
 * canonicalised (see {@link ItemCounts#add}) so depositing noted items, which
 * the game stores unnoted, reads as a deposit of the item and not as one item
 * vanishing and another appearing.
 */
final class StorageDiff
{
	private StorageDiff()
	{
	}

	static StorageChange diff(long at, Map<Integer, Integer> before, Map<Integer, Integer> after)
	{
		Map<Integer, Integer> took = new TreeMap<>();
		Map<Integer, Integer> deposited = new TreeMap<>();
		TreeSet<Integer> ids = new TreeSet<>(before.keySet());
		ids.addAll(after.keySet());
		for (int id : ids)
		{
			long delta = (long) after.getOrDefault(id, 0) - before.getOrDefault(id, 0);
			if (delta > 0)
			{
				deposited.put(id, (int) Math.min(delta, Integer.MAX_VALUE));
			}
			else if (delta < 0)
			{
				took.put(id, (int) Math.min(-delta, Integer.MAX_VALUE));
			}
		}
		return new StorageChange(at, "", took, deposited, after);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;

/**
 * The rolling group storage change log: the newest {@link #MAX_ENTRIES}
 * visits, newest first.
 *
 * <p>Members' visits are here only from members running GIM Utilities with
 * storage sharing on. A member without it changes storage silently, and the
 * next visit by someone who has it sees the result as part of their own
 * "before". This player's own visits are always here; one made with sharing
 * off is marked {@link StorageChange#shared() not shared} and was never sent.
 */
final class StorageLog
{
	static final int MAX_ENTRIES = 200;

	private final LinkedList<StorageChange> entries = new LinkedList<>();

	/** Adds a visit. Empty visits and exact repeats (a duplicate delivery) are dropped. */
	synchronized boolean add(StorageChange change)
	{
		if (change.isEmpty())
		{
			return false;
		}
		int index = 0;
		for (StorageChange e : entries)
		{
			if (e.at() == change.at() && e.member().equalsIgnoreCase(change.member()))
			{
				return false;
			}
			if (e.at() < change.at())
			{
				break;
			}
			index++;
		}
		entries.add(index, change);
		while (entries.size() > MAX_ENTRIES)
		{
			entries.removeLast();
		}
		return true;
	}

	/** True when this member's visit at {@code at} is here and was kept to this client (not shared). */
	synchronized boolean notShared(long at, String member)
	{
		for (StorageChange e : entries)
		{
			if (e.at() == at && e.member().equalsIgnoreCase(member))
			{
				return !e.shared();
			}
		}
		return false;
	}

	synchronized List<StorageChange> entries()
	{
		return new ArrayList<>(entries);
	}

	synchronized void clear()
	{
		entries.clear();
	}

	/** "5 x Shark, 40K x Coins", for {@code ::find}'s storage history; amounts in {@code items}' style. */
	static String describe(Map<Integer, Integer> counts, ItemLookup items)
	{
		List<String> parts = new ArrayList<>();
		for (Map.Entry<Integer, Integer> e : counts.entrySet())
		{
			parts.add(items.amount(e.getValue()) + " x " + items.name(e.getKey()));
		}
		return String.join(", ", parts);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Map;

/**
 * One open group storage window: the contents the game sent first, then
 * every change up to each save.
 *
 * <p>The game only keeps what is saved (Board 2026-11-14: closing without
 * Save throws the changes away), and Save can be pressed more than once per
 * visit, so each save records what moved since the previous one and starts
 * the next diff from there. Closing records nothing: a save the game makes
 * as the window closes still arrives as a save, within {@link #LATE_SAVE_MS}.
 *
 * <p>Truth check: the first contents after the next open are what the game
 * actually kept. When they differ from what was last committed, they come
 * back as a snapshot (an empty change), never as a logged move. Pure, so the
 * log can be tested without a client.
 */
final class StorageSession
{
	/** How long after the window closes a "Saving..." still belongs to that visit. */
	static final long LATE_SAVE_MS = 5_000;

	private boolean open;
	/** The contents as of the open or the last save: what the game holds. */
	private Map<Integer, Integer> base;
	/** The contents now, saved or not. */
	private Map<Integer, Integer> latest;
	/** When the window closed; -1 while open or never opened. */
	private long closedAt = -1;
	/** What was last handed back to be committed as the storage snapshot; null this session. */
	private Map<Integer, Integer> committed;

	/** The storage interface opened: the next contents are the "before". */
	void open()
	{
		open = true;
		base = null;
		latest = null;
		closedAt = -1;
	}

	boolean isOpen()
	{
		return open;
	}

	/**
	 * The group storage container changed while open. The first contents of a
	 * visit are the game's truth: returned as a snapshot when they differ from
	 * what was last committed (or nothing was yet), null otherwise.
	 */
	StorageChange contents(long at, String member, Map<Integer, Integer> now)
	{
		if (!open)
		{
			return null;
		}
		Map<Integer, Integer> copy = ItemCounts.sorted(now);
		latest = copy;
		if (base != null)
		{
			return null;
		}
		base = copy;
		if (copy.equals(committed))
		{
			return null;
		}
		committed = copy;
		return StorageDiff.diff(at, copy, copy).withMember(member);
	}

	/**
	 * The game saved (Save, or "Saving..." shown): what moved since the last
	 * save (or the open), by {@code member}. Null when nothing arrived yet, or
	 * the window has been closed for longer than {@link #LATE_SAVE_MS}; an
	 * empty change when nothing moved, which still carries the contents as a
	 * snapshot.
	 */
	StorageChange save(long at, String member)
	{
		if (base == null || latest == null)
		{
			return null;
		}
		if (!open && (closedAt < 0 || at - closedAt > LATE_SAVE_MS))
		{
			return null;
		}
		StorageChange change = StorageDiff.diff(at, base, latest).withMember(member);
		base = latest;
		committed = latest;
		return change;
	}

	/** The window closed: nothing is recorded, unsaved changes are the game's to discard. */
	void close(long at)
	{
		if (open)
		{
			open = false;
			closedAt = at;
		}
	}

	/** Logged out or stopped: forget everything, including what was last committed. */
	void reset()
	{
		open = false;
		base = null;
		latest = null;
		closedAt = -1;
		committed = null;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * The panel header for each sync state: a title, what to do next, and the
 * buttons that do it. Pure, so every state's wording is tested.
 */
final class SyncHeader
{
	enum Button
	{
		JOIN("Join group sync", "Connect to your group's private party. Once per session; RuneLite does not allow"
			+ " plugins to rejoin parties on their own."),
		SWITCH("Switch to group sync", "Leave the party you are in and connect to your group's"),
		LEAVE("Leave", "Disconnect from your group's party"),
		CREATE_KEY("Create group key", "Make a new random key for your group; then copy and send the share line"),
		NEW_KEY("New key", "Replace the key, e.g. if it leaked. Share the new one; members must rejoin"),
		COPY_KEY("Copy group key", "Copies the key to your computer's clipboard to send to your group, e.g. in"
			+ " Discord. Anyone with it can join your group's sync, so share it only with your group"),
		PASTE_KEY("Paste group key", "Saves the key a member sent you, from your computer's clipboard. The plugin"
			+ " then joins your group's sync by itself");

		final String label;
		final String tooltip;

		Button(String label, String tooltip)
		{
			this.label = label;
			this.tooltip = tooltip;
		}
	}

	final String title;
	/** One line under the title, or null. */
	final String detail;
	/** Green when synced. */
	final boolean ok;
	final List<Button> buttons;

	private SyncHeader(String title, String detail, boolean ok, Button... buttons)
	{
		this.title = title;
		this.detail = detail;
		this.ok = ok;
		this.buttons = Collections.unmodifiableList(Arrays.asList(buttons));
	}

	/** {@code othersOnline}: members other than this player heard from in the last few minutes. */
	static SyncHeader of(GroupSync.State state, int othersOnline, GroupMembers members)
	{
		String group = members.group().isEmpty() ? "your group" : members.group();
		switch (state)
		{
			case OFF:
				return new SyncHeader("Sync off", "Solo: only what this client saw. Turn on 'Sync with my group' in"
					+ " settings to share.", false);
			case NO_KEY:
				return new SyncHeader("No group key yet", "One member creates a key and sends it to the group, e.g."
					+ " in Discord; everyone else copies it and presses Paste.", false, Button.CREATE_KEY,
					Button.PASTE_KEY);
			case NO_GROUP:
				return new SyncHeader("Waiting for your group", "Log in on your Group Ironman. The group roster"
					+ " comes from the game.", false, Button.COPY_KEY);
			case READY:
				return new SyncHeader("Not connected", "Press Join to sync with " + group + ".", false, Button.JOIN,
					Button.COPY_KEY);
			case STALE:
				return new SyncHeader("Group key changed", "Press Join to reconnect with the new key.", false,
					Button.JOIN, Button.COPY_KEY);
			case OTHER_PARTY:
				return new SyncHeader("In another party; GIM sync paused", "Nothing is sent to that party.", false,
					Button.SWITCH);
			case CONNECTED:
				// Counts you too (Board 2026-11-04: "zero members online, even though I'm online").
				return new SyncHeader("Connected, " + (othersOnline + 1) + " online"
					+ (othersOnline == 0 ? " (you)" : ""), "Synced with " + group + ". Only roster members are"
					+ " shown.", true,
					Button.COPY_KEY, Button.NEW_KEY, Button.LEAVE);
			default:
				throw new IllegalArgumentException(String.valueOf(state));
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Who a player is doing something with (docs/plans/activities.md §2.2): this group's members by name, everyone else
 * only as a count, never named (§1.3, "Transmitting names of non-group players"). One place for it: the raid unique's
 * "with Sam +1 other" ({@link EventWatchers}) and the activities' solo / duo / N-man / mass label.
 */
final class TeamSummary
{
	/** From this many players a place is a mass, not a team. */
	static final int MASS_FROM = 6;

	/** Group members with the player, in the order they were seen. */
	final List<String> named;
	/** Everyone else with the player: a count only. */
	final int others;

	private TeamSummary(List<String> named, int others)
	{
		this.named = Collections.unmodifiableList(named);
		this.others = others;
	}

	/** {@code present} is everyone seen here, the player included; {@code group} this group's in-game roster. */
	static TeamSummary of(String me, Collection<String> group, Collection<String> present)
	{
		Set<String> members = new HashSet<>();
		for (String g : group)
		{
			members.add(GroupMembers.key(g));
		}
		String self = GroupMembers.key(me == null ? "" : me);
		List<String> named = new ArrayList<>();
		int others = 0;
		for (String player : present)
		{
			String key = GroupMembers.key(player);
			if (key.equals(self))
			{
				continue;
			}
			if (members.contains(key))
			{
				named.add(player);
			}
			else
			{
				others++;
			}
		}
		return new TeamSummary(named, others);
	}

	/** The player and everyone with them. */
	int size()
	{
		return 1 + named.size() + others;
	}

	/** "with Sam, Pat +2 others", or empty when alone. */
	String with()
	{
		String team = String.join(", ", named);
		if (others > 0)
		{
			team += (team.isEmpty() ? "" : " ") + "+" + others + (others == 1 ? " other" : " others");
		}
		return team.isEmpty() ? "" : "with " + team;
	}

	/** "solo", "duo with Sam", "4-man (with Sam +2 others)" or "mass (48 players, with Sam)". */
	String mode()
	{
		int n = size();
		if (n == 1)
		{
			return "solo";
		}
		if (n == 2)
		{
			return "duo " + with();
		}
		if (n < MASS_FROM)
		{
			return n + "-man (" + with() + ")";
		}
		return "mass (" + n + " players" + (named.isEmpty() ? "" : ", with " + String.join(", ", named)) + ")";
	}
}

