package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.function.Predicate;

/**
 * The event banners on screen and the group box's latest events. Pure and
 * clock-driven, so showing, expiring and stacking are tested without a
 * client.
 *
 * <p><b>Situational kinds.</b> {@link #visible} takes a filter: today it lets
 * everything through, and a later part can hide a kind outside where it
 * matters (only in the Wilderness, only in a boss room) without changing how
 * banners are kept.
 */
final class ToastQueue
{
	/** Banners kept at most, whatever the setting; the group box keeps as many recent events. */
	static final int MAX_KEPT = 20;

	static final class Toast
	{
		final GroupEvent event;
		final long shownAt;

		Toast(GroupEvent event, long shownAt)
		{
			this.event = event;
			this.shownAt = shownAt;
		}
	}

	private final LinkedList<Toast> toasts = new LinkedList<>();
	private final LinkedList<GroupEvent> recent = new LinkedList<>();

	synchronized void add(GroupEvent event, long now)
	{
		toasts.addFirst(new Toast(event, now));
		recent.addFirst(event);
		while (toasts.size() > MAX_KEPT)
		{
			toasts.removeLast();
		}
		while (recent.size() > MAX_KEPT)
		{
			recent.removeLast();
		}
	}

	/** The newest {@code max} banners still within {@code durationMs}, newest first. Expired ones are dropped. */
	synchronized List<Toast> visible(long now, long durationMs, int max, Predicate<GroupEvent> situation)
	{
		List<Toast> out = new ArrayList<>();
		for (Iterator<Toast> it = toasts.iterator(); it.hasNext(); )
		{
			Toast t = it.next();
			if (now - t.shownAt >= durationMs)
			{
				it.remove();
			}
			else if (out.size() < max && situation.test(t.event))
			{
				out.add(t);
			}
		}
		return out;
	}

	/** The newest {@code max} events seen, banners expired or not, for the group box. */
	synchronized List<GroupEvent> recent(int max)
	{
		return new ArrayList<>(recent.subList(0, Math.min(max, recent.size())));
	}

	synchronized void clear()
	{
		toasts.clear();
		recent.clear();
	}
}

package com.vinnyvangogh.groupironman;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JToggleButton;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/** The side panel's small Swing building blocks, shared by every tab so each piece is built one way. */
final class Ui
{
	private Ui()
	{
	}

	/** A plain label in {@code font}, and in {@code color} unless that is null (the look and feel's own). */
	static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		if (color != null)
		{
			label.setForeground(color);
		}
		return label;
	}

	/** A small-font button that never takes focus; {@code tooltip} may be null. */
	static JButton button(String text, String tooltip, Runnable action)
	{
		JButton b = new JButton(text);
		b.setFont(FontManager.getRunescapeSmallFont());
		b.setFocusable(false);
		b.setToolTipText(tooltip);
		b.addActionListener(e -> action.run());
		return b;
	}

	/** A small-font toggle that never takes focus, {@code margin} pixels above and below its text. */
	static JToggleButton toggle(String text, boolean selected, int margin)
	{
		JToggleButton b = new JToggleButton(text, selected);
		b.setFont(FontManager.getRunescapeSmallFont());
		b.setFocusable(false);
		b.setMargin(new Insets(margin, 0, margin, 0));
		return b;
	}

	/** {@code c} alone in a row, stretched to its full width. */
	static JPanel wide(JComponent c)
	{
		JPanel row = new JPanel(new GridLayout(1, 1));
		row.add(c);
		return row;
	}

	/** An empty card: a dark box with padding, holding a column. */
	static JPanel card()
	{
		JPanel box = new GroupIronmanPanel.Column();
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setBorder(BorderFactory.createCompoundBorder(new EmptyBorder(0, 0, 6, 0), new EmptyBorder(6, 6, 6, 6)));
		return box;
	}

	/** Runs {@code action} when {@code c} is pressed. */
	static void onPress(JComponent c, Runnable action)
	{
		c.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				action.run();
			}
		});
	}

	/** {@link #onPress} with the hand cursor, so it looks clickable. */
	static void clickable(JComponent c, Runnable action)
	{
		c.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		onPress(c, action);
	}

	/** Puts {@code text} on the computer's clipboard. */
	static void copy(String text)
	{
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * The game-chat lines posted once per version: a welcome on a fresh install,
 * and a "what's new" list on the first login after an update.
 *
 * <p>Every published version stores itself as seen, so nothing stored always
 * means a fresh install, however the plugin was turned on: installed mid-session
 * or switched on before logging in (Board 2026-11-11). Combat Vitals needed a
 * logged-in check only because its 1.0.0 never stored a version.
 */
final class UpdateNotes
{
	/** Must match {@code version} in runelite-plugin.properties (UpdateNotesTest). */
	static final String VERSION = "1.0.0";

	static final String TITLE = GroupIronmanPlugin.NAME + " updated to " + VERSION + ", what's new:";

	/**
	 * What is new in {@link #VERSION}, one chat message each. Empty for the first
	 * release: an update to a version with no notes posts nothing.
	 */
	static final List<String> NOTES = Collections.emptyList();

	/** The fresh-install welcome, one chat message each (wording approved by the Board 2026-11-11). */
	static final List<String> WELCOME = Collections.unmodifiableList(Arrays.asList(
		"GIM Utilities is on. Everything starts off; turn on what you want.",
		"1. Group: open the GIM Utilities panel, Create group key, send it to your group; everyone Pastes it and"
			+ " clicks Join group sync.",
		"2. Discord: Server Settings > Integrations > Webhooks > Copy URL, paste it in Configure GIM Utilities >"
			+ " Discord: connection, and tick Post to Discord.",
		"3. You get: shared banks and storage log, ::find, member cards, the Log, and Discord posts + banners for"
			+ " drops, deaths, levels & more."
	));

	private UpdateNotes()
	{
	}

	/**
	 * What to post on this login, first line first; empty when nothing.
	 *
	 * @param lastSeen the stored last-seen version, "" when none
	 * @param enabled  the "Show update notes" setting
	 */
	static List<String> toShow(String lastSeen, boolean enabled)
	{
		if (!enabled || !needsRecord(lastSeen))
		{
			return Collections.emptyList();
		}
		if (isNullOrEmpty(lastSeen))
		{
			return WELCOME;
		}
		if (NOTES.isEmpty())
		{
			return Collections.emptyList();
		}
		final List<String> lines = new ArrayList<>(NOTES.size() + 1);
		lines.add(TITLE);
		lines.addAll(NOTES);
		return lines;
	}

	/** Whether this version still has to be stored as seen; true with the setting off too. */
	static boolean needsRecord(String lastSeen)
	{
		return !VERSION.equals(lastSeen);
	}

	private static boolean isNullOrEmpty(String s)
	{
		return s == null || s.isEmpty();
	}
}

package com.vinnyvangogh.groupironman;

import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * The one message GIM Utilities sends over RuneLite Party: banks, carried
 * items, group storage changes, live stats, extras and drops.
 *
 * <p>The relay routes by {@code getSimpleName()}, so the class name is the
 * message's type id, shared by every plugin on the client. It is
 * author-prefixed so it cannot meet another plugin's message: not Build
 * Guard's {@code BuildGuardGroupMessage} (both plugins may run side by side,
 * and neither receives, decodes or answers the other's traffic), and not a
 * generic name another group plugin might also pick. The body is one
 * versioned JSON string read by {@link GroupCodec}.
 *
 * <p><b>The class name is the wire contract.</b> Do not rename it, and keep it
 * when the plugin's display name changes.
 */
public class VvgGroupIronmanMessage extends PartyMemberMessage
{
	private String payload;

	public VvgGroupIronmanMessage()
	{
	}

	VvgGroupIronmanMessage(String payload)
	{
		this.payload = payload;
	}

	public String getPayload()
	{
		return payload;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Locale;
import java.util.function.Consumer;
import java.util.function.Supplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * This player's run through a wave activity: the TzHaar Fight Cave (63 waves), the Inferno (69) and the Fortis
 * Colosseum (12), as docs/plans/activities.md §2.4 A1/A2 specify. Pure: the engine feeds it the template region
 * (unwrapped with {@code WorldPoint.fromLocalInstance}), game messages, the player's own death and logouts, and it
 * keeps an {@link ActivityState} and emits the four activity events.
 *
 * <p>Only coarse status is read: the wave the game prints, time spent, completion and defeat. No attack, prayer,
 * spawn or hazard is ever tracked (§1.3).
 *
 * <p>Messages, from the base client and Hub plugins (tags removed with {@link EventText#plain}):
 * {@code Wave: N} starts each wave in all three (RuneLite's former FightCavePlugin {@code WAVE_PATTERN}; the Hub
 * fortis-colosseum {@code ColosseumStateTracker} reads the same line), {@code Wave N completed!} ends a Colosseum
 * wave and "Sol Heredit jumps down from his seat" starts wave 12 (fortis-colosseum), and the kill count line
 * ({@link EventText#killCount}) completes a run. "You have been defeated!" is the design doc's defeat line and is
 * not yet confirmed in game; the player's own death covers a defeat without it.
 */
final class WaveTracker
{
	enum Arena
	{
		FIGHT_CAVES("fight_caves", "Fight Caves", 9551, 63, "TzTok-Jad", 63),
		INFERNO("inferno", "The Inferno", 9043, 69, "TzKal-Zuk", 68),
		COLOSSEUM("colosseum", "Fortis Colosseum", 7216, 12, "Sol Heredit", 12);

		final String id;
		final String title;
		/** The template region ({@code regions.txt}), never the instance's own. */
		final int region;
		final int max;
		/** The kill count line's name that completes the run. */
		final String boss;
		/** From this wave on, every wave is a boss wave and always a milestone: Jad 63, Triple Jads 68, Sol 12. */
		final int bossFrom;

		Arena(String id, String title, int region, int max, String boss, int bossFrom)
		{
			this.id = id;
			this.title = title;
			this.region = region;
			this.max = max;
			this.boss = boss;
			this.bossFrom = bossFrom;
		}

		static Arena at(int region)
		{
			for (Arena a : values())
			{
				if (a.region == region)
				{
					return a;
				}
			}
			return null;
		}

		static Arena byId(String id)
		{
			for (Arena a : values())
			{
				if (a.id.equals(id))
				{
					return a;
				}
			}
			return null;
		}

		boolean bossWave(int wave)
		{
			return wave >= bossFrom;
		}
	}

	static final Pattern WAVE = Pattern.compile("^Wave: (\\d+)$");
	static final Pattern WAVE_DONE = Pattern.compile("^Wave (\\d+) completed!");
	static final String SOL_WAVE = "Sol Heredit jumps down from his seat";
	static final Pattern DEFEATED = Pattern.compile("^You have been defeated!?$");
	/** The run's time on a completion: "Duration: 1:02:33" (tags removed), never a Colosseum wave's own time. */
	static final Pattern DURATION = Pattern.compile("(?i)duration: ?([0-9:.]+)");
	/** A death this soon after a defeat line is the same death. */
	static final long SAME_DEATH_MS = 3_000;
	/** The live board moves only every this many waves (and on boss waves), so its message is not edited each wave. */
	static final int BOARD_STEP = 5;

	private final Consumer<GroupEvent> emit;
	private final Supplier<String> mode;

	private Arena arena;
	private int wave;
	private int completed;
	private long startedAt;
	/** Time in the run before {@link #resumedAt}. */
	private long activeMs;
	/** When the run's clock last started; 0 while paused (logged out) or restored and not yet back in. */
	private long resumedAt;
	private String runMode = "";
	private String mods = "";
	private long glory;
	private String duration;
	private long pendingKc;
	private long defeatedAt;
	private int region = -1;
	private int world;
	private int every = 10;
	private boolean changed;

	/** {@code emit} takes the activity events; {@code mode} is "solo" or the team, read when a run starts. */
	WaveTracker(Consumer<GroupEvent> emit, Supplier<String> mode)
	{
		this.emit = emit;
		this.mode = mode;
	}

	/** "Post every N waves"; 0 posts boss waves only. */
	void every(int n)
	{
		every = Math.max(0, n);
	}

	/** Each tick: where the player stands (template region, -1 while loading) and their world. */
	void region(int regionId, int world, long now, String me)
	{
		this.world = world;
		if (regionId < 0)
		{
			return;
		}
		region = regionId;
		if (arena == null)
		{
			return;
		}
		if (regionId == arena.region)
		{
			if (resumedAt == 0)
			{
				resumedAt = now;
				changed = true;
			}
			return;
		}
		leave(now, me);
	}

	/** Out of the arena alive: a Colosseum claim after a cleared wave, otherwise a quiet exit. */
	private void leave(long now, String me)
	{
		if (arena == Arena.COLOSSEUM && completed > 0 && resumedAt > 0)
		{
			emit.accept(event(GroupEvent.Type.ACTIVITY_COMPLETE, now, me).number(0)
				.detail("claimed loot after wave " + completed).build());
		}
		clear();
	}

	/** A game message: waves, a Colosseum wave cleared, the run's duration, a kill count, a defeat. */
	void chat(String message, long now, String me)
	{
		String text = EventText.plain(message);
		Matcher m = WAVE.matcher(text);
		if (m.matches())
		{
			wave(Integer.parseInt(m.group(1)), now, me);
			return;
		}
		if (text.contains(SOL_WAVE))
		{
			wave(Arena.COLOSSEUM.max, now, me);
			return;
		}
		Matcher done = WAVE_DONE.matcher(text);
		if (done.find())
		{
			completed = Integer.parseInt(done.group(1));
			return;
		}
		if (DEFEATED.matcher(text).matches())
		{
			defeat(now, me);
			return;
		}
		other(text);
	}

	/** A kill count that completes the run, or the run's duration line. */
	private void other(String text)
	{
		if (arena == null)
		{
			return;
		}
		EventText.Count kc = EventText.killCount(text);
		if (kc != null && kc.name.equalsIgnoreCase(arena.boss))
		{
			pendingKc = Math.max(1, kc.count);
			return;
		}
		Matcher d = DURATION.matcher(text);
		if (d.find())
		{
			duration = d.group(1);
		}
	}

	private void wave(int n, long now, String me)
	{
		Arena here = Arena.at(region);
		if (here == null || n < 1 || n > here.max)
		{
			return;
		}
		if (arena != here || n < wave)
		{
			start(here, n, now, me);
		}
		resumedAt = resumedAt == 0 ? now : resumedAt;
		// A wave printed again after a relog is not a second milestone.
		boolean fresh = n != wave;
		wave = n;
		changed = true;
		if (fresh && milestone(here, n))
		{
			emit.accept(event(GroupEvent.Type.ACTIVITY_WAVE, now, me).number(n).detail(phase()).build());
		}
	}

	/** Every {@link #every} waves, and every boss wave; never wave 1, which is the start. */
	private boolean milestone(Arena a, int n)
	{
		return n > 1 && (a.bossWave(n) || every > 0 && n % every == 0);
	}

	private void start(Arena a, int n, long now, String me)
	{
		clear();
		arena = a;
		startedAt = now;
		resumedAt = now;
		String m = mode.get();
		runMode = m == null ? "" : m;
		if (n == 1)
		{
			emit.accept(event(GroupEvent.Type.ACTIVITY_START, now, me).number(1).detail(runMode).build());
		}
	}

	/**
	 * The player's own death. True when it was inside a run (now, or a defeat line just before it): the
	 * activity death covers it, so the plain death post can be skipped.
	 */
	boolean died(long now, String me)
	{
		if (arena != null)
		{
			defeat(now, me);
			return true;
		}
		return defeatedAt > 0 && now - defeatedAt <= SAME_DEATH_MS;
	}

	private void defeat(long now, String me)
	{
		if (arena == null)
		{
			return;
		}
		emit.accept(event(GroupEvent.Type.ACTIVITY_DEATH, now, me).number(wave)
			.detail(join(phase(), ActivityState.duration(elapsed(now)), mods)).world(world).location(arena.title)
			.build());
		defeatedAt = now;
		clear();
	}

	/** Each tick: a completion, once its duration line had the chance to arrive on the same tick. */
	void tick(long now, String me)
	{
		if (arena == null || pendingKc == 0)
		{
			return;
		}
		String time = duration != null ? duration : ActivityState.duration(elapsed(now));
		emit.accept(event(GroupEvent.Type.ACTIVITY_COMPLETE, now, me).number(pendingKc)
			.detail(join(time, stats(), mods)).build());
		clear();
	}

	/** Logged out: the run's clock stops until the player is back in the arena. */
	void pause(long now)
	{
		if (arena != null && resumedAt > 0)
		{
			activeMs += now - resumedAt;
			resumedAt = 0;
			changed = true;
		}
	}

	/** The Colosseum's chosen modifiers ({@link ColosseumModifiers}) and glory, read while in a Colosseum run. */
	void colosseum(String chosen, long gloryNow)
	{
		if (arena != Arena.COLOSSEUM)
		{
			return;
		}
		String m = chosen == null ? "" : chosen;
		if (!m.equals(mods) || gloryNow != glory)
		{
			mods = m;
			glory = gloryNow;
			changed = true;
		}
	}

	private void clear()
	{
		changed |= arena != null;
		arena = null;
		wave = 0;
		completed = 0;
		activeMs = 0;
		resumedAt = 0;
		mods = "";
		glory = 0;
		duration = null;
		pendingKc = 0;
		runMode = "";
	}

	/** True once after anything the state shows changed. */
	boolean takeChanged()
	{
		boolean c = changed;
		changed = false;
		return c;
	}

	boolean active()
	{
		return arena != null;
	}

	long elapsed(long now)
	{
		return activeMs + (resumedAt > 0 ? Math.max(0, now - resumedAt) : 0);
	}

	/** The state to show and send. */
	ActivityState state(long now)
	{
		if (arena == null)
		{
			return new ActivityState.Builder("", now).build();
		}
		return new ActivityState.Builder(arena.id, now).cat(ActivityState.BOSS).name(arena.title).mode(runMode)
			.phase(wave > 0 ? phase() : "").board(board()).wave(wave).max(arena.max).startedAt(startedAt)
			.elapsedMs(elapsed(now)).stats(stats()).mods(mods).build();
	}

	private String phase()
	{
		return "wave " + wave + "/" + arena.max;
	}

	/** "in Fight Caves, wave 35": the wave rounded down to {@link #BOARD_STEP}, a boss wave exact. */
	private String board()
	{
		int shown = arena.bossWave(wave) ? wave : wave - wave % BOARD_STEP;
		return "in " + arena.title + (shown > 0 ? ", wave " + shown : "");
	}

	private String stats()
	{
		return glory > 0 ? String.format(Locale.ROOT, "%,d glory", glory) : "";
	}

	private GroupEvent.Builder event(GroupEvent.Type type, long now, String me)
	{
		return GroupEvent.of(type, now, me).text(arena.title);
	}

	private static String join(String... parts)
	{
		StringBuilder out = new StringBuilder();
		for (String p : parts)
		{
			if (p != null && !p.isEmpty())
			{
				out.append(out.length() == 0 ? "" : ", ").append(p);
			}
		}
		return out.toString();
	}

	/** The run, kept in the RuneLite profile so a logout mid-run resumes: "inferno,42,startedAt,activeMs,completed". */
	String save()
	{
		if (arena == null)
		{
			return "";
		}
		return arena.id + "," + wave + "," + startedAt + "," + activeMs + "," + completed;
	}

	/** A run {@link #save} kept; paused until the player is back in its arena. Anything unreadable is ignored. */
	void restore(String saved)
	{
		String[] p = saved == null ? new String[0] : saved.split(",");
		Arena a = p.length == 5 ? Arena.byId(p[0]) : null;
		if (a == null)
		{
			return;
		}
		try
		{
			int w = Integer.parseInt(p[1]);
			long started = Long.parseLong(p[2]);
			long active = Long.parseLong(p[3]);
			int done = Integer.parseInt(p[4]);
			clear();
			arena = a;
			wave = Math.max(0, Math.min(a.max, w));
			startedAt = started;
			activeMs = Math.max(0, active);
			completed = Math.max(0, done);
			runMode = mode.get() == null ? "" : mode.get();
		}
		catch (NumberFormatException e)
		{
			clear();
		}
	}

	/** A new account: nothing carries over. */
	void reset()
	{
		clear();
		defeatedAt = 0;
		region = -1;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.EnumMap;
import java.util.Map;

/**
 * The seven Discord webhooks, in the order the settings show them (Board 2026-11-11): Main, the fallback and home
 * of anything not listed, then six categories. Each category's URL may be left empty to post to Main's, and each
 * has its own poster name choice, kept even on Main's URL (Board pre-run answer).
 *
 * <p>The default names are RuneScape-flavoured, under Discord's 80 characters and free of the words Discord refuses
 * in a webhook username ({@link PosterNames#refused}); WebhooksTest holds them to that.
 *
 * <p>Separate from {@link GroupEvent.Category}, which picks embed colours, Log filters and digest ticks: the
 * webhooks are where a post goes, which the Board split differently.
 */
enum Webhook
{
	MAIN("main", "Town Crier"),
	ONLINE("online status", "World Hopper"),
	DROPS("drops & loot", "Party Pete"),
	PROGRESS("progress", "Skillcape Seller"),
	DEATHS("deaths & danger", "Death's Office"),
	STORAGE("group storage", "Gielinor Banker"),
	/** The daily digest only: no instant post comes here. */
	DIGEST("daily digest", "Varrock Herald");

	private static final Map<GroupEvent.Type, Webhook> BY_TYPE = new EnumMap<>(GroupEvent.Type.class);

	static
	{
		on(ONLINE, GroupEvent.Type.ONLINE);
		on(DROPS, GroupEvent.Type.DROP, GroupEvent.Type.CLOG, GroupEvent.Type.PET, GroupEvent.Type.UNIQUE,
			GroupEvent.Type.BARROWS, GroupEvent.Type.RAID_UNIQUE, GroupEvent.Type.STORAGE_LAST);
		on(PROGRESS, GroupEvent.Type.LEVEL_UP, GroupEvent.Type.MAXED, GroupEvent.Type.XP_MILESTONE,
			GroupEvent.Type.COMBAT_LEVEL, GroupEvent.Type.TOTAL_LEVEL, GroupEvent.Type.QUEST,
			GroupEvent.Type.QUEST_POINTS, GroupEvent.Type.ACTIVITY_START, GroupEvent.Type.ACTIVITY_WAVE,
			GroupEvent.Type.ACTIVITY_COMPLETE);
		on(DEATHS, GroupEvent.Type.DEATH, GroupEvent.Type.DEATH_VALUE, GroupEvent.Type.GRAVESTONE_EXPIRING,
			GroupEvent.Type.HC_LIFE_LOST, GroupEvent.Type.ACTIVITY_DEATH);
		on(STORAGE, GroupEvent.Type.STORAGE_DEPOSIT, GroupEvent.Type.STORAGE_WITHDRAWAL,
			GroupEvent.Type.STORAGE_SUMMARY, GroupEvent.Type.STORAGE_MINIMUM);
	}

	/** The word the chat warnings use for this webhook's fields. */
	final String label;
	/** The name 'Default name' posts under, and what the Custom box starts with. */
	final String defaultName;

	Webhook(String label, String defaultName)
	{
		this.label = label;
		this.defaultName = defaultName;
	}

	private static void on(Webhook webhook, GroupEvent.Type... types)
	{
		for (GroupEvent.Type t : types)
		{
			BY_TYPE.put(t, webhook);
		}
	}

	/** Where an event's instant post goes: its category's webhook, Main for anything not listed. Never null. */
	static Webhook of(GroupEvent.Type type)
	{
		return BY_TYPE.getOrDefault(type, MAIN);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Tells the player, once, that a webhook field is set but is not a Discord
 * webhook link, rather than posting nothing without a word. The line names
 * the field, never its value: a webhook URL holds the token that posts to
 * the channel. Pure, so the once-only rule is tested.
 */
final class WebhookWarnings
{
	/** Field label to the bad value already warned about. In memory only, never shown. */
	private final Map<String, String> warned = new HashMap<>();

	/**
	 * The chat lines to show now, for each field (label to value) that is set
	 * and invalid and has not been warned about with this value. A field that
	 * is cleared or fixed is forgotten, so breaking it again warns again.
	 */
	synchronized List<String> check(Map<String, String> fields)
	{
		List<String> out = new ArrayList<>();
		for (Map.Entry<String, String> field : fields.entrySet())
		{
			String value = DiscordWebhook.clean(field.getValue());
			if (value.isEmpty() || DiscordWebhook.valid(value))
			{
				warned.remove(field.getKey());
			}
			else if (!value.equals(warned.put(field.getKey(), value)))
			{
				out.add(message(field.getKey()));
			}
		}
		return out;
	}

	static String message(String label)
	{
		return GroupIronmanPlugin.NAME + ": the " + label + " Discord webhook isn't a valid Discord webhook link";
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

/**
 * The one place a post's webhook URL and poster name are decided. Every sender asks this, never a webhook setting
 * directly. Pure over a snapshot of the settings, so the rules are tested.
 *
 * <ul>
 * <li>URL: the webhook's own when set and valid, else Main's, else none (nothing is posted).</li>
 * <li>Name: the webhook's own choice, also when its URL fell back to Main's. Webhook's own sends no
 * {@code username}; Default name sends {@link Webhook#defaultName}; Custom sends the box, or the default name
 * when the box is blank or a name Discord refuses ({@link PosterNames#refused}).</li>
 * </ul>
 */
final class Webhooks
{
	/** One webhook's three settings, as typed. */
	static final class Setting
	{
		final String url;
		final DiscordPosterName mode;
		final String name;

		Setting(String url, DiscordPosterName mode, String name)
		{
			this.url = url == null ? "" : url;
			this.mode = mode == null ? DiscordPosterName.WEBHOOK : mode;
			this.name = name == null ? "" : name;
		}
	}

	private static final Setting UNSET = new Setting("", DiscordPosterName.WEBHOOK, "");

	private final Map<Webhook, Setting> settings;
	/** The webhooks whose setting came from the leader's shared ones ({@link #withGroup}), not this member's. */
	private final Set<Webhook> fromGroup;

	Webhooks(Map<Webhook, Setting> settings)
	{
		this(settings, EnumSet.noneOf(Webhook.class));
	}

	private Webhooks(Map<Webhook, Setting> settings, Set<Webhook> fromGroup)
	{
		this.settings = new EnumMap<>(Webhook.class);
		this.settings.putAll(settings);
		this.fromGroup = fromGroup.isEmpty() ? EnumSet.noneOf(Webhook.class) : EnumSet.copyOf(fromGroup);
	}

	/**
	 * These (a member's own) with the leader's shared webhooks filling in: per webhook, the member's own setting
	 * (URL and poster name) when its URL field is not empty, else the group's. Unchanged when the group shares
	 * none. Main's fallback then runs over the result, so an empty category still lands on Main (the member's own
	 * Main when set, else the group's).
	 */
	Webhooks withGroup(GroupWebhooks group)
	{
		if (group == null || !group.shared)
		{
			return this;
		}
		Map<Webhook, Setting> merged = new EnumMap<>(settings);
		Set<Webhook> borrowed = EnumSet.noneOf(Webhook.class);
		for (Map.Entry<Webhook, Setting> e : group.settings.entrySet())
		{
			if (DiscordWebhook.clean(setting(e.getKey()).url).isEmpty())
			{
				merged.put(e.getKey(), e.getValue());
				borrowed.add(e.getKey());
			}
		}
		return new Webhooks(merged, borrowed);
	}

	/** True when {@link #url}{@code (webhook)} is the leader's shared URL, not one this member typed. */
	boolean fromGroup(Webhook webhook)
	{
		Webhook used = DiscordWebhook.valid(setting(webhook).url) ? webhook : Webhook.MAIN;
		return fromGroup.contains(used) && url(webhook) != null;
	}

	private Setting setting(Webhook webhook)
	{
		return settings.getOrDefault(webhook, UNSET);
	}

	Map<Webhook, Setting> settings()
	{
		return Collections.unmodifiableMap(settings);
	}

	/** Where {@code webhook}'s posts go: its own URL, else Main's; null when neither is a Discord webhook. */
	String url(Webhook webhook)
	{
		String own = setting(webhook).url;
		if (DiscordWebhook.valid(own))
		{
			return DiscordWebhook.clean(own);
		}
		String main = setting(Webhook.MAIN).url;
		return DiscordWebhook.valid(main) ? DiscordWebhook.clean(main) : null;
	}

	/** The {@code username} {@code webhook}'s posts go out under; null sends none, so the webhook's own shows. */
	String name(Webhook webhook)
	{
		Setting s = setting(webhook);
		switch (s.mode)
		{
			case CUSTOM:
				String custom = PosterNames.clean(s.name);
				return custom.isEmpty() || PosterNames.refused(custom) ? webhook.defaultName : custom;
			case GIM_UTILITIES:
				return webhook.defaultName;
			default:
				return null;
		}
	}

	/** Every URL field, by the label its warning uses, in settings order. */
	Map<String, String> urlFields()
	{
		Map<String, String> out = new LinkedHashMap<>();
		for (Webhook w : Webhook.values())
		{
			out.put(w.label, setting(w).url);
		}
		return out;
	}

	/** Every Custom box by label; blank for a webhook not on Custom, whose box is unused and so never warns. */
	Map<String, String> customNames()
	{
		Map<String, String> out = new LinkedHashMap<>();
		for (Webhook w : Webhook.values())
		{
			Setting s = setting(w);
			out.put(w.label, s.mode == DiscordPosterName.CUSTOM ? s.name : "");
		}
		return out;
	}

	/** The seven webhooks' settings. The only reader of the webhook and poster-name keys. */
	static Webhooks of(GroupIronmanConfig config)
	{
		Map<Webhook, Setting> s = new EnumMap<>(Webhook.class);
		s.put(Webhook.MAIN, new Setting(config.discordWebhookUrl(), config.discordPosterName(),
			config.discordNameMain()));
		s.put(Webhook.ONLINE, new Setting(config.discordGroupUrl(), config.discordPosterOnline(),
			config.discordNameGroup()));
		s.put(Webhook.DROPS, new Setting(config.discordDropsUrl(), config.discordPosterDrops(),
			config.discordNameDrops()));
		s.put(Webhook.PROGRESS, new Setting(config.discordProgressUrl(), config.discordPosterProgress(),
			config.discordNameProgress()));
		s.put(Webhook.DEATHS, new Setting(config.discordDeathsUrl(), config.discordPosterDeaths(),
			config.discordNameDeaths()));
		s.put(Webhook.STORAGE, new Setting(config.discordStorageUrl(), config.discordPosterStorage(),
			config.discordNameStorage()));
		s.put(Webhook.DIGEST, new Setting(config.discordDigestUrl(), config.discordPosterDigest(),
			config.discordNameDigest()));
		return new Webhooks(s);
	}
}

package com.vinnyvangogh.groupironman;

import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.SpriteID;

/**
 * The game's own empty-slot silhouettes from the Worn Equipment tab, drawn in
 * a member card's worn grid where nothing is worn, so it reads as the
 * equipment screen (Board 2026-11-14). Loaded at run time through RuneLite's
 * {@code SpriteManager} from the game cache; no game art is bundled.
 *
 * <p>Sprite ids are RuneLite's {@link SpriteID} {@code EQUIPMENT_SLOT_*}
 * constants (runelite-api), keyed by {@link EquipmentInventorySlot} index.
 */
final class WornSlotIcons
{
	/** Equipment slot index to its silhouette's sprite id, in the worn tab's order. */
	static final Map<Integer, Integer> SPRITES;

	static
	{
		Map<Integer, Integer> m = new LinkedHashMap<>();
		m.put(EquipmentInventorySlot.HEAD.getSlotIdx(), SpriteID.EQUIPMENT_SLOT_HEAD);
		m.put(EquipmentInventorySlot.CAPE.getSlotIdx(), SpriteID.EQUIPMENT_SLOT_CAPE);
		m.put(EquipmentInventorySlot.AMULET.getSlotIdx(), SpriteID.EQUIPMENT_SLOT_NECK);
		m.put(EquipmentInventorySlot.AMMO.getSlotIdx(), SpriteID.EQUIPMENT_SLOT_AMMUNITION);
		m.put(EquipmentInventorySlot.WEAPON.getSlotIdx(), SpriteID.EQUIPMENT_SLOT_WEAPON);
		m.put(EquipmentInventorySlot.BODY.getSlotIdx(), SpriteID.EQUIPMENT_SLOT_TORSO);
		m.put(EquipmentInventorySlot.SHIELD.getSlotIdx(), SpriteID.EQUIPMENT_SLOT_SHIELD);
		m.put(EquipmentInventorySlot.LEGS.getSlotIdx(), SpriteID.EQUIPMENT_SLOT_LEGS);
		m.put(EquipmentInventorySlot.GLOVES.getSlotIdx(), SpriteID.EQUIPMENT_SLOT_HANDS);
		m.put(EquipmentInventorySlot.BOOTS.getSlotIdx(), SpriteID.EQUIPMENT_SLOT_FEET);
		m.put(EquipmentInventorySlot.RING.getSlotIdx(), SpriteID.EQUIPMENT_SLOT_RING);
		SPRITES = Collections.unmodifiableMap(m);
	}

	private WornSlotIcons()
	{
	}

	/** The silhouette sprite for an equipment slot, or -1 for none. */
	static int sprite(int slot)
	{
		return SPRITES.getOrDefault(slot, -1);
	}

	/** The grey a silhouette pixel of no brightness at all is lifted to. */
	private static final int LIFT = 96;

	/**
	 * {@code sprite} as a flat light grey with its own shape and alpha (Board 2026-11-14): the game draws these
	 * dark for its brown stone tab, and on the sidebar's dark grey they all but vanished. Grey and not
	 * white, so an empty slot still reads as empty beside a coloured item. Null stays null.
	 */
	static BufferedImage lighten(BufferedImage sprite)
	{
		if (sprite == null)
		{
			return null;
		}
		int w = sprite.getWidth();
		int h = sprite.getHeight();
		BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < h; y++)
		{
			for (int x = 0; x < w; x++)
			{
				int argb = sprite.getRGB(x, y);
				int alpha = argb >>> 24;
				if (alpha == 0)
				{
					continue;
				}
				int r = (argb >> 16) & 0xFF;
				int g = (argb >> 8) & 0xFF;
				int b = argb & 0xFF;
				int lum = (299 * r + 587 * g + 114 * b) / 1000;
				int v = Math.min(255, LIFT + lum / 2);
				out.setRGB(x, y, (alpha << 24) | (v << 16) | (v << 8) | v);
			}
		}
		return out;
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The live activity message and the four activity events on the wire (docs/plans/activities.md §5, §7 item 1),
 * including what a client from before this slice makes of them.
 */
public class ActivityCodecTest
{
	private static final Gson GSON = new Gson();

	static ActivityState inferno(long at)
	{
		return new ActivityState.Builder("inferno", at).name("The Inferno").mode("solo").phase("wave 42/69")
			.board("in The Inferno, wave 40").wave(42).max(69).startedAt(at - 3_600_000).elapsedMs(3_000_000)
			.build();
	}

	@Test
	public void roundTrips()
	{
		ActivityState back = ActivityCodec.decode(GSON, ActivityCodec.encode(GSON, inferno(5_000)));
		assertNotNull(back);
		assertEquals("inferno", back.id);
		assertEquals("The Inferno", back.name);
		assertEquals("wave 42/69", back.phase);
		assertEquals(42, back.wave);
		assertEquals(69, back.max);
		assertEquals(3_000_000, back.elapsedMs);
		assertEquals(5_000, back.at);
		assertTrue(back.bossing());
		assertEquals("The Inferno - wave 42/69 - solo", back.cardLine());
	}

	@Test
	public void clearFrameDecodesAsNotInAnActivity()
	{
		String json = ActivityCodec.encode(GSON, new ActivityState.Builder("", 9).build());
		assertEquals("{\"v\":1,\"k\":\"activity\",\"at\":9,\"id\":\"\"}", json);
		ActivityState back = ActivityCodec.decode(GSON, json);
		assertNotNull(back);
		assertFalse(back.active());
	}

	@Test
	public void stripsMarkupAndControlCharactersAndClipsStrings()
	{
		String json = "{\"v\":1,\"k\":\"activity\",\"at\":1,\"id\":\"inferno\",\"name\":\"<html><b>Inferno</b>\\u0007\","
			+ "\"mods\":\"" + repeat("x", 500) + "\",\"phase\":\"wave\\n1\"}";
		ActivityState back = ActivityCodec.decode(GSON, json);
		assertNotNull(back);
		assertFalse(back.name, back.name.contains("<"));
		assertFalse(back.name.contains("\u0007"));
		assertEquals(ActivityCodec.MAX_MODS, back.mods.length());
		assertEquals("wave1", back.phase);
	}

	@Test
	public void clampsNumbers()
	{
		String json = "{\"v\":1,\"k\":\"activity\",\"at\":1,\"id\":\"inferno\",\"name\":\"The Inferno\","
			+ "\"wave\":-5,\"max\":99999999,\"elapsedMs\":1e30}";
		ActivityState back = ActivityCodec.decode(GSON, json);
		assertNotNull(back);
		assertEquals(0, back.wave);
		assertEquals(ActivityCodec.MAX_WAVE, back.max);
		assertEquals(ActivityCodec.MAX_ELAPSED_MS, back.elapsedMs);
	}

	@Test
	public void rejectsMalformed()
	{
		assertNull(ActivityCodec.decode(GSON, null));
		assertNull(ActivityCodec.decode(GSON, "not json"));
		assertNull(ActivityCodec.decode(GSON, "[1,2]"));
		assertNull("no version", ActivityCodec.decode(GSON, "{\"k\":\"activity\",\"id\":\"\"}"));
		assertNull("no id", ActivityCodec.decode(GSON, "{\"v\":1,\"k\":\"activity\"}"));
		assertNull("bad id", ActivityCodec.decode(GSON, "{\"v\":1,\"k\":\"activity\",\"id\":\"../x\",\"name\":\"a\"}"));
		assertNull("no name", ActivityCodec.decode(GSON, "{\"v\":1,\"k\":\"activity\",\"id\":\"inferno\"}"));
		assertNull("another kind", ActivityCodec.decode(GSON, "{\"v\":1,\"k\":\"stats\",\"id\":\"\"}"));
		String huge = "{\"v\":1,\"k\":\"activity\",\"id\":\"inferno\",\"name\":\"" + repeat("y", 3000) + "\"}";
		assertNull("oversized", ActivityCodec.decode(GSON, huge));
	}

	@Test
	public void anUnknownCategoryIsBossing()
	{
		String json = "{\"v\":1,\"k\":\"activity\",\"at\":1,\"id\":\"tempoross\",\"name\":\"Tempoross\",\"cat\":\"x\"}";
		assertTrue(ActivityCodec.decode(GSON, json).bossing());
		String mini = "{\"v\":1,\"k\":\"activity\",\"at\":1,\"id\":\"ba\",\"name\":\"BA\",\"cat\":\"minigame\"}";
		assertFalse(ActivityCodec.decode(GSON, mini).bossing());
	}

	// ---- Older clients ----

	@Test
	public void anOlderClientsDataDecoderReturnsNullForTheActivityKind()
	{
		// GroupCodec.decode is what every client before this slice runs first; null sends it to notData, which
		// logs one debug line and drops it.
		assertNull(GroupCodec.decode(GSON, ActivityCodec.encode(GSON, inferno(1))));
		assertNull(GroupCodec.decode(GSON, ActivityCodec.encode(GSON, ActivityState.NONE)));
	}

	@Test
	public void activityEventsTravelAndAnOlderClientSkipsOnlyThem()
	{
		List<GroupEvent> events = Arrays.asList(
			GroupEvent.of(GroupEvent.Type.DEATH, 1, "Ember Fox").location("Lumbridge").build(),
			GroupEvent.of(GroupEvent.Type.ACTIVITY_WAVE, 2, "Ember Fox").text("The Inferno").number(60)
				.detail("wave 60/69").build(),
			GroupEvent.of(GroupEvent.Type.ACTIVITY_DEATH, 3, "Ember Fox").text("The Inferno").number(63).build(),
			GroupEvent.of(GroupEvent.Type.LEVEL_UP, 4, "Ember Fox").text("Attack").number(70).build());
		List<String> payloads = GroupOutbox.groupEvents(GSON, true, events);
		assertEquals(1, payloads.size());
		GroupCodec.Decoded now = GroupCodec.decode(GSON, payloads.get(0));
		assertEquals("this build reads all four", 4, now.events.size());
		assertEquals(GroupEvent.Type.ACTIVITY_WAVE, now.events.get(1).type);
		assertEquals(60, now.events.get(1).number);

		// An older build knows no "aw" or "ad": each is skipped on its own, its neighbours kept.
		String older = payloads.get(0).replace("\"aw\"", "\"zz\"").replace("\"ad\"", "\"zy\"");
		GroupCodec.Decoded old = GroupCodec.decode(GSON, older);
		assertEquals(2, old.events.size());
		assertEquals(GroupEvent.Type.DEATH, old.events.get(0).type);
		assertEquals(GroupEvent.Type.LEVEL_UP, old.events.get(1).type);
	}

	@Test
	public void anOlderMembersOptOutListSkipsTheNewCodes()
	{
		assertEquals(Collections.singleton(GroupEvent.Type.PET), MemberPrefs.parse("pt,zz"));
		assertTrue(MemberPrefs.parse("as,aw").contains(GroupEvent.Type.ACTIVITY_WAVE));
	}

	@Test
	public void isActivityLooksOnlyForTheKind()
	{
		assertTrue(ActivityCodec.isActivity(ActivityCodec.encode(GSON, inferno(1))));
		assertFalse(ActivityCodec.isActivity("{\"v\":1,\"k\":\"stats\"}"));
		assertFalse(ActivityCodec.isActivity(null));
	}

	static String repeat(String s, int n)
	{
		StringBuilder b = new StringBuilder();
		for (int i = 0; i < n; i++)
		{
			b.append(s);
		}
		return b.toString();
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.items;
import static com.vinnyvangogh.groupironman.FakeItems.SHARK;
import static com.vinnyvangogh.groupironman.FakeItems.TROUT;
import static com.vinnyvangogh.groupironman.FakeItems.WHIP;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** The sidebar Log: every event type lands in it, search, filters, sections, the bound and a restart. */
public class ActivityLogTest
{
	private static final long HOUR = TimeUnit.HOURS.toMillis(1);
	private static final long DAY = TimeUnit.DAYS.toMillis(1);
	private static final ZoneId UTC = ZoneOffset.UTC;
	/** Monday 10 Nov 2025, noon UTC, so "today" has room either side. */
	private static final long NOW = 1_762_776_000_000L;
	private static final Gson GSON = new Gson();

	private final FakeItems items = new FakeItems();

	private static GroupEvent drop(long at, String member, String npc, int id)
	{
		return GroupEvent.drop(at, member, npc, items(id, 1));
	}

	private static GroupEvent death(long at, String member, String place)
	{
		return GroupEvent.of(GroupEvent.Type.DEATH, at, member).location(place).build();
	}

	private static GroupEvent level(long at, String member, String skill, int lvl)
	{
		return GroupEvent.of(GroupEvent.Type.LEVEL_UP, at, member).text(skill).number(lvl).build();
	}

	/** Newest first, as the feed keeps them. */
	private List<GroupEvent> sample()
	{
		return Arrays.asList(
			level(NOW - HOUR, "Sam", "Attack", 80),
			death(NOW - 2 * HOUR, "Alex", "Lumbridge"),
			drop(NOW - 3 * HOUR, "Alex", "Vorkath", WHIP),
			GroupEvent.of(GroupEvent.Type.STORAGE_SUMMARY, NOW - 2 * DAY, "Sam").items(items(SHARK, 5))
				.taken(items(TROUT, 15)).build(),
			drop(NOW - 10 * DAY, "Sam", "Zulrah", SHARK));
	}

	// ---- Every type lands in the log, whatever the outputs ----

	@Test
	public void everyTypeIsLoggedWithEveryOutputOff()
	{
		List<GroupEvent> logged = new ArrayList<>();
		EventRouter router = new EventRouter(e ->
		{
		}, e ->
		{
		}, e ->
		{
		}, logged::add);
		EventSettings off = EventFixtures.settings(EventFixtures.none(), EventFixtures.none());
		for (GroupEvent.Type t : GroupEvent.Type.values())
		{
			router.route(EventFixtures.sample(t), true, off, items);
			router.route(EventFixtures.sample(t).withMember("Sam"), false, off, items);
		}
		EnumSet<GroupEvent.Type> seen = EnumSet.noneOf(GroupEvent.Type.class);
		for (GroupEvent e : logged)
		{
			seen.add(e.type);
		}
		assertEquals(EnumSet.allOf(GroupEvent.Type.class), seen);
		// Yours and members' alike.
		assertEquals(2 * GroupEvent.Type.values().length, logged.size());
	}

	@Test
	public void theLogGetsWhatTheThresholdsLeave()
	{
		List<GroupEvent> logged = new ArrayList<>();
		EventRouter router = new EventRouter(e ->
		{
		}, e ->
		{
		}, e ->
		{
		}, logged::add);
		EventSettings s = EventFixtures.settings(EventFixtures.none(), EventFixtures.none());
		// 3 sharks is 2,400 gp, under the 1M drop minimum: no valuable drop, so nothing logged.
		router.route(GroupEvent.drop(NOW, "Alex", "Zulrah", items(SHARK, 3)), true, s, items);
		assertTrue(logged.isEmpty());
	}

	@Test
	public void everyKindIsDetectedForTheLogButNotWhenOff()
	{
		EventSettings s = EventFixtures.settings(EventFixtures.none(), EventFixtures.none());
		for (GroupEvent.Type t : GroupEvent.Type.values())
		{
			assertFalse(s.wants(t));
			assertTrue(s.detects(t));
			assertFalse(EventSettings.OFF.detects(t));
		}
	}

	// ---- Search ----

	@Test
	public void searchMatchesMemberItemPlaceAndText()
	{
		List<GroupEvent> all = sample();
		assertEquals(3, filter(all, "sam").size());
		assertEquals(1, filter(all, "abyssal WHIP").size());
		assertEquals(1, filter(all, "lumbridge").size());
		assertEquals(1, filter(all, "attack level").size());
		// A storage summary's withdrawals are searchable too.
		assertEquals(1, filter(all, "trout").size());
		assertTrue(filter(all, "nothing like this").isEmpty());
		assertEquals(all.size(), filter(all, "  ").size());
	}

	private List<GroupEvent> filter(List<GroupEvent> all, String query)
	{
		return ActivityLog.filter(all, new ActivityLog.Filter(query, EnumSet.noneOf(GroupEvent.Category.class), "",
			ActivityLog.Range.ALL), items, NOW, UTC);
	}

	// ---- Filters ----

	@Test
	public void categoryChipsKeepTheirCategories()
	{
		List<GroupEvent> all = sample();
		assertEquals(2, byCategory(all, GroupEvent.Category.DROPS).size());
		assertEquals(1, byCategory(all, GroupEvent.Category.DEATHS).size());
		assertEquals(1, byCategory(all, GroupEvent.Category.STORAGE).size());
		assertEquals(1, byCategory(all, GroupEvent.Category.PROGRESS).size());
		assertTrue(byCategory(all, GroupEvent.Category.GROUP).isEmpty());
		assertTrue(byCategory(all, GroupEvent.Category.ACTIVITIES).isEmpty());
		assertEquals(3, byCategory(all, GroupEvent.Category.DROPS, GroupEvent.Category.DEATHS).size());
	}

	private List<GroupEvent> byCategory(List<GroupEvent> all, GroupEvent.Category first, GroupEvent.Category... rest)
	{
		return ActivityLog.filter(all, new ActivityLog.Filter("", EnumSet.of(first, rest), "", ActivityLog.Range.ALL),
			items, NOW, UTC);
	}

	@Test
	public void everyCategoryHasAChipLabel()
	{
		assertEquals("Drops", ActivityLog.label(GroupEvent.Category.DROPS));
		assertEquals("Activities", ActivityLog.label(GroupEvent.Category.ACTIVITIES));
	}

	@Test
	public void memberPickerKeepsOneMember()
	{
		List<GroupEvent> all = sample();
		List<GroupEvent> alex = ActivityLog.filter(all, new ActivityLog.Filter("", EnumSet.noneOf(
			GroupEvent.Category.class), "ALEX", ActivityLog.Range.ALL), items, NOW, UTC);
		assertEquals(2, alex.size());
		assertEquals(Arrays.asList("Alex", "Sam"), ActivityLog.members(all));
	}

	@Test
	public void timeRangeKeepsTodayOrTheLastWeek()
	{
		List<GroupEvent> all = sample();
		assertEquals(3, range(all, ActivityLog.Range.TODAY).size());
		assertEquals(4, range(all, ActivityLog.Range.WEEK).size());
		assertEquals(5, range(all, ActivityLog.Range.ALL).size());
	}

	private List<GroupEvent> range(List<GroupEvent> all, ActivityLog.Range r)
	{
		return ActivityLog.filter(all, new ActivityLog.Filter("", EnumSet.noneOf(GroupEvent.Category.class), "", r),
			items, NOW, UTC);
	}

	// ---- Sections and rows ----

	@Test
	public void sinceYouLastPlayedIsTheTopSectionThenDays()
	{
		List<ActivityLog.Section> s = ActivityLog.sections(sample(), NOW - 150 * 60_000L, "Sam", NOW, UTC);
		assertTrue(s.get(0).title.startsWith("Since you last played"));
		// Alex's death after it; Sam's own level up is not "new" to Sam.
		assertEquals(1, s.get(0).events.size());
		assertEquals(GroupEvent.Type.DEATH, s.get(0).events.get(0).type);
		assertEquals("Today", s.get(1).title);
		assertEquals(2, s.get(1).events.size());
		assertEquals("Sat 8 Nov", s.get(2).title);
		assertEquals("Fri 31 Oct", s.get(3).title);
	}

	@Test
	public void withoutALastPlayedTimeThereAreOnlyDays()
	{
		List<ActivityLog.Section> s = ActivityLog.sections(sample(), 0, "Sam", NOW, UTC);
		assertEquals("Today", s.get(0).title);
		assertEquals(3, s.get(0).events.size());
		assertEquals("Yesterday", ActivityLog.dayTitle(LocalDate.of(2025, 11, 9), LocalDate.of(2025, 11, 10)));
	}

	@Test
	public void rowHasGameAmountsShortAndFullOnHover()
	{
		GroupEvent e = GroupEvent.drop(NOW - HOUR, "Alex", "Vorkath", items(WHIP, 1, SHARK, 2));
		ActivityLog.Row r = ActivityLog.row(e, items, NOW, UTC);
		assertEquals(WHIP, r.itemId);
		assertNull(r.skill);
		assertEquals("1h ago", r.ago);
		assertTrue(r.text, r.text.contains("Abyssal whip"));
		assertTrue(r.full, r.full.startsWith("Valuable drop\nAlex: Vorkath dropped"));
		assertTrue(r.full, r.full.contains("\nValue: ") && r.full.contains("(1,501,600) gp"));
		assertTrue(r.full, r.full.endsWith("\n10 Nov 2025, 11:00"));
		assertTrue(r.copy, r.copy.startsWith("[10 Nov 2025, 11:00] Alex: Vorkath dropped"));
	}

	@Test
	public void levelRowsDrawTheirSkill()
	{
		assertEquals("Attack", ActivityLog.row(level(NOW, "Sam", "Attack", 80), items, NOW, UTC).skill);
		GroupEvent maxed = GroupEvent.of(GroupEvent.Type.MAXED, NOW, "Sam").text("total").number(2277).build();
		assertNull(ActivityLog.skillOf(maxed));
		assertEquals(-1, ActivityLog.row(maxed, items, NOW, UTC).itemId);
	}

	// ---- The bound ----

	@Test
	public void theFeedKeepsTheNewestTwoThousand()
	{
		DropLog feed = new DropLog(ActivityLog.MAX_ENTRIES, ActivityLog.MAX_AGE_MS, () -> NOW);
		for (int i = 0; i < ActivityLog.MAX_ENTRIES + 50; i++)
		{
			assertTrue(feed.add(level(NOW - (ActivityLog.MAX_ENTRIES + 50 - i) * 1000L, "Sam", "Attack", i)));
		}
		List<GroupEvent> kept = feed.entries();
		assertEquals(ActivityLog.MAX_ENTRIES, kept.size());
		assertEquals(NOW - 1000L, kept.get(0).at);
		assertEquals(NOW - ActivityLog.MAX_ENTRIES * 1000L, kept.get(kept.size() - 1).at);
	}

	@Test
	public void theFeedKeepsThirtyDays()
	{
		AtomicLong clock = new AtomicLong(NOW);
		DropLog feed = new DropLog(ActivityLog.MAX_ENTRIES, ActivityLog.MAX_AGE_MS, clock::get);
		assertFalse(feed.add(death(NOW - 31 * DAY, "Alex", "Lumbridge")));
		assertTrue(feed.add(death(NOW - 29 * DAY, "Alex", "Lumbridge")));
		assertTrue(feed.add(death(NOW - DAY, "Alex", "Varrock")));
		// Two days on, the oldest is past 30 days and goes with the next add.
		clock.set(NOW + 2 * DAY);
		assertTrue(feed.add(death(NOW, "Alex", "Falador")));
		assertEquals(2, feed.entries().size());
		assertEquals("Varrock", feed.entries().get(1).location);
	}

	@Test
	public void theFeedDropsAResend()
	{
		DropLog feed = ActivityLog.newFeed();
		long at = System.currentTimeMillis();
		assertTrue(feed.add(drop(at, "Alex", "Vorkath", WHIP)));
		assertFalse(feed.add(drop(at, "alex", "Vorkath", WHIP)));
	}

	// ---- Restart ----

	@Test
	public void aRestartKeepsTheLog()
	{
		long now = System.currentTimeMillis();
		GroupRoster before = new GroupRoster();
		GroupEvent summary = GroupEvent.of(GroupEvent.Type.STORAGE_SUMMARY, now - HOUR, "Sam").items(items(SHARK, 5))
			.taken(items(TROUT, 15)).build();
		GroupEvent offline = GroupEvent.of(GroupEvent.Type.ONLINE, now - 2 * HOUR, "Alex").text("offline")
			.number(3_600_000).world(302).detail("1:35 PM").build();
		GroupEvent dead = death(now - 3 * HOUR, "Alex", "Lumbridge").toBuilder().text("Vorkath").build();
		before.feed().add(summary);
		before.feed().add(offline);
		before.feed().add(dead);

		GroupRoster after = new GroupRoster();
		assertTrue(GroupCache.read(GSON, GroupCache.write(GSON, before), after));
		List<GroupEvent> kept = after.feed().entries();
		assertEquals(3, kept.size());
		assertTrue(kept.get(0).sameAs(summary));
		assertEquals(summary.taken, kept.get(0).taken);
		assertEquals(offline.detail, kept.get(1).detail);
		assertEquals(302, kept.get(1).world);
		assertEquals("Lumbridge", kept.get(2).location);
		assertEquals("Vorkath", kept.get(2).text);
	}

	@Test
	public void anOlderCacheStartsTheFeedFromItsDropsAndStorageLogs()
	{
		long now = System.currentTimeMillis();
		GroupRoster before = new GroupRoster();
		before.events().add(drop(now - HOUR, "Alex", "Vorkath", WHIP));
		before.putStorage(new StorageChange(now - 2 * HOUR, "Sam", items(TROUT, 15), items(SHARK, 5),
			Collections.emptyMap()));
		// What a build before the feed wrote: everything but the "feed" key.
		com.google.gson.JsonObject old = GSON.fromJson(GroupCache.write(GSON, before), com.google.gson.JsonObject.class);
		old.remove("feed");

		GroupRoster after = new GroupRoster();
		assertTrue(GroupCache.read(GSON, GSON.toJson(old), after));
		List<GroupEvent> feed = after.feed().entries();
		assertEquals(2, feed.size());
		assertEquals(GroupEvent.Type.DROP, feed.get(0).type);
		assertEquals(GroupEvent.Type.STORAGE_SUMMARY, feed.get(1).type);
		assertEquals(items(TROUT, 15), feed.get(1).taken);
	}

	@Test
	public void clearingTheGroupClearsTheFeed()
	{
		GroupRoster roster = new GroupRoster();
		roster.feed().add(death(System.currentTimeMillis(), "Alex", "Lumbridge"));
		assertTrue(roster.hasAnything());
		roster.clearAll();
		assertTrue(roster.feed().entries().isEmpty());
	}
}

