	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collections;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

public class BankAssemblerTest
{
	private static Map<Integer, Integer> one(int id, int qty)
	{
		Map<Integer, Integer> m = new TreeMap<>();
		m.put(id, qty);
		return m;
	}

	private static GroupCodec.BankPart part(long ts, int p, int n, int id)
	{
		return new GroupCodec.BankPart(ts, p, n, one(id, 1));
	}

	@Test
	public void partsCanArriveInAnyOrder()
	{
		BankAssembler a = new BankAssembler();
		assertNull(a.accept(1, part(10, 2, 3, 300)));
		assertNull(a.accept(1, part(10, 0, 3, 100)));
		BankSnapshot done = a.accept(1, part(10, 1, 3, 200));
		assertNotNull(done);
		assertEquals(3, done.items().size());
		assertEquals(10, done.takenAt());
	}

	@Test
	public void aDuplicatePartDoesNotCompleteEarly()
	{
		BankAssembler a = new BankAssembler();
		assertNull(a.accept(1, part(10, 0, 2, 100)));
		assertNull(a.accept(1, part(10, 0, 2, 100)));
		assertNotNull(a.accept(1, part(10, 1, 2, 200)));
	}

	@Test
	public void aNewerSnapshotDiscardsAnUnfinishedOlderOne()
	{
		BankAssembler a = new BankAssembler();
		assertNull(a.accept(1, part(10, 0, 2, 100)));
		assertNull(a.accept(1, part(20, 0, 2, 500)));
		// The old snapshot's second part arrives late and must not mix in.
		assertNull(a.accept(1, part(10, 1, 2, 200)));
		BankSnapshot done = a.accept(1, part(20, 1, 2, 600));
		assertEquals(20, done.takenAt());
		assertEquals(Collections.singleton(500), Collections.singleton(done.items().keySet().iterator().next()));
		assertEquals(2, done.items().size());
	}

	@Test
	public void membersAreAssembledSeparately()
	{
		BankAssembler a = new BankAssembler();
		assertNull(a.accept(1, part(10, 0, 2, 100)));
		assertNotNull(a.accept(2, part(10, 0, 1, 100)));
		assertNotNull(a.accept(1, part(10, 1, 2, 200)));
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Which bank cards in the Banks tab are open (Board 2026-11-13). */
public class BankFoldsTest
{
	private static final List<String> BANKS = Arrays.asList("Alex", "Sam", "Zed");

	@Test
	public void everyBankStartsOpen()
	{
		BankFolds f = new BankFolds();
		f.filter("");
		for (String b : BANKS)
		{
			assertTrue(b, f.open(b, true));
		}
		assertTrue(f.anyOpen(BANKS, name -> true));
	}

	@Test
	public void togglingOneBankLeavesTheOthers()
	{
		BankFolds f = new BankFolds();
		f.filter("");
		f.toggle("Sam", true);
		assertTrue(f.open("Alex", true));
		assertFalse(f.open("Sam", true));
		assertTrue(f.open("Zed", true));

		f.toggle("Sam", true);
		assertTrue(f.open("Sam", true));
	}

	@Test
	public void namesMatchWhateverTheCase()
	{
		BankFolds f = new BankFolds();
		f.filter("");
		f.toggle("Sam", true);
		assertFalse(f.open("sam", true));
	}

	@Test
	public void filterOpensMatchesFoldsTheRestAndClearingRestoresThePlayersChoice()
	{
		BankFolds f = new BankFolds();
		f.filter("");
		f.toggle("Alex", true); // the player folds Alex; Sam and Zed stay open

		f.filter("shark");
		assertTrue("a folded bank with a match opens", f.open("Alex", true));
		assertFalse("an open bank with no match folds", f.open("Sam", false));
		assertTrue(f.open("Zed", true));

		f.filter("");
		assertFalse("the player's fold is back", f.open("Alex", true));
		assertTrue(f.open("Sam", true));
		assertTrue(f.open("Zed", true));
	}

	@Test
	public void foldingWhileFilteringLastsOnlyForThatFilter()
	{
		BankFolds f = new BankFolds();
		f.filter("shark");
		f.toggle("Alex", true);
		assertFalse(f.open("Alex", true));

		f.filter("whip");
		assertTrue("a new filter starts from the matches again", f.open("Alex", true));

		f.filter("");
		assertTrue("the player's own choice was never touched", f.open("Alex", true));
	}

	@Test
	public void filterTooShortToSearchKeepsThePlayersChoice()
	{
		BankFolds f = new BankFolds();
		f.filter("");
		f.toggle("Alex", true);
		f.filter("s");
		assertFalse(f.open("Alex", true));
	}

	@Test
	public void collapseAllThenExpandAll()
	{
		BankFolds f = new BankFolds();
		f.filter("");
		f.setAll(BANKS, false);
		for (String b : BANKS)
		{
			assertFalse(b, f.open(b, true));
		}
		assertFalse(f.anyOpen(BANKS, name -> true));

		f.setAll(BANKS, true);
		for (String b : BANKS)
		{
			assertTrue(b, f.open(b, true));
		}
	}

	@Test
	public void collapseAllWhileFilteringIsUndoneByClearingTheFilter()
	{
		BankFolds f = new BankFolds();
		f.filter("shark");
		f.setAll(BANKS, false);
		assertFalse(f.open("Alex", true));

		f.filter("");
		assertTrue(f.open("Alex", true));
	}
}

