		"discordOfflineGrace", "discordBack", "discordBarrows", "overlayDurationSeconds", "overlayPosition",
		"overlayMaxStacked", "overlayGroupBox", "overlayGroupBoxEvents", "overlayValuableDrop", "overlayPet",
		"overlayCollectionLog", "overlayUntradeableUnique", "overlayDeath", "overlayStorageDeposit",
		"overlayStorageWithdrawal", "overlayStorageSummary", "overlayStorageMinimum", "overlayStorageLast",
		"overlayLevelUp", "overlayMaxed", "overlayXpMilestone", "overlayCombatLevel", "overlayTotalLevel",
		"overlayQuest", "overlayQuestPoints", "overlayOnline", "overlayBack", "overlayBarrows", "eventClueMinValue",
		"eventKcEvery", "eventGravestoneWarnMinutes", "discordRaidUnique", "discordClue", "discordDryStreak",
		"discordDeathValue", "discordGravestone", "discordHardcoreLife", "discordWilderness", "discordDiary",
		"discordCombatTask", "discordKcMilestone", "discordPersonalBest", "discordWeeklyRecap", "discordSlayer",
		"discordFarming", "discordBirdhouse", "overlayRaidUnique", "overlayClue", "overlayDryStreak",
		"overlayDeathValue", "overlayGravestone", "overlayHardcoreLife", "overlayWilderness", "overlayDiary",
		"overlayCombatTask", "overlayKcMilestone", "overlayPersonalBest", "overlayWeeklyRecap", "overlaySlayer",
		"overlayFarming", "overlayBirdhouse", "discordRequest", "overlayRequest", "discordDigestHour", "digestDrops", "digestDeaths", "digestStorage",
		"digestProgress", "digestGroup", "digestActivities", "showUpdateNotes", "lastSeenVersion"));

	private static final List<String> SECTION_ORDER = Arrays.asList("Group", "Discord: connection",
		"Discord: what to post", "Discord: how to post", "Discord: daily digest", "In-game", "Thresholds", "Advanced");

	/** Every section but Group starts closed, so a first install shows all eight names at once. */
	private static final Set<String> CLOSED = new HashSet<>(Arrays.asList("Discord: connection",
		"Discord: what to post", "Discord: how to post", "Discord: daily digest", "In-game", "Thresholds", "Advanced"));

	@Test
	public void theConfigGroupIsUnchanged()
	{
		assertEquals("gimutilities", GroupIronmanConfig.GROUP);
		assertEquals("gimutilities", GroupIronmanConfig.class.getAnnotation(ConfigGroup.class).value());
	}

	@Test
	public void everyPublishedKeyIsStillThere()
	{
		Set<String> keys = new HashSet<>();
		for (Method m : items())
		{
			keys.add(m.getAnnotation(ConfigItem.class).keyName());
		}
		Set<String> lost = new HashSet<>(PUBLISHED_KEYS);
		lost.removeAll(keys);
		assertTrue("published keys renamed or removed: " + lost, lost.isEmpty());
	}

	@Test
	public void exactlyEightSectionsInOrderWithOnlyGroupOpen() throws Exception
	{
		List<ConfigSection> sections = new ArrayList<>(sections().values());
		sections.sort(Comparator.comparingInt(ConfigSection::position));
		List<String> names = new ArrayList<>();
		Set<Integer> positions = new HashSet<>();
		for (ConfigSection s : sections)
		{
			names.add(s.name());
			assertTrue("duplicate section position " + s.position(), positions.add(s.position()));
			assertEquals(s.name() + " closed by default", CLOSED.contains(s.name()), s.closedByDefault());
			assertFalse(s.name() + " has no description", s.description().trim().isEmpty());
		}
		assertEquals(SECTION_ORDER, names);
	}

	@Test
	public void everySettingIsInOneOfTheSections() throws Exception
	{
		Set<String> sectionKeys = sections().keySet();
		for (Method m : items())
		{
			String section = m.getAnnotation(ConfigItem.class).section();
			assertTrue(m.getName() + " has no section, or an unknown one: '" + section + "'",
				sectionKeys.contains(section));
		}
	}

	@Test
	public void positionsAreUniqueWithinEachSection()
	{
		Map<String, Set<Integer>> seen = new HashMap<>();
		for (Method m : items())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			assertTrue(m.getName() + " shares position " + item.position() + " in " + item.section(),
				seen.computeIfAbsent(item.section(), k -> new HashSet<>()).add(item.position()));
		}
	}

	@Test
	public void onlineStatusIsAboutHowToPostNotWhichEvents()
	{
		assertEquals(GroupIronmanConfig.discordHowSection, sectionOf("discordOnlineStatus"));
		assertEquals(GroupIronmanConfig.discordHowSection, sectionOf("discordCombineLevels"));
		assertEquals(GroupIronmanConfig.discordHowSection, sectionOf("discordGravestoneScreenshot"));
		assertEquals(GroupIronmanConfig.discordConnectionSection, sectionOf("discordPosterName"));
	}

	@Test
	public void updateNotesSitLastInAdvancedAndTheSeenVersionIsHidden()
	{
		assertEquals(GroupIronmanConfig.advancedSection, sectionOf("showUpdateNotes"));
		assertEquals(7, item("showUpdateNotes").position());
		assertFalse(item("showUpdateNotes").hidden());
		assertEquals(GroupIronmanConfig.KEY_LAST_SEEN_VERSION, item("lastSeenVersion").keyName());
		assertTrue(item("lastSeenVersion").hidden());
	}

	private static ConfigItem item(String method)
	{
		return items().stream().filter(m -> m.getName().equals(method)).findFirst()
			.orElseThrow(AssertionError::new).getAnnotation(ConfigItem.class);
	}

	@Test
	public void everySettingHasAPlainNameAndDescription()
	{
		for (Method m : items())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			assertFalse(m.getName() + " has no name", item.name().trim().isEmpty());
			assertFalse(m.getName() + " has no description", item.description().trim().isEmpty());
		}
	}

	private static String sectionOf(String method)
	{
		return item(method).section();
	}

	/** Section key (the field's value) to its annotation. */
	private static Map<String, ConfigSection> sections() throws IllegalAccessException
	{
		Map<String, ConfigSection> out = new HashMap<>();
		for (Field f : GroupIronmanConfig.class.getFields())
		{
			ConfigSection s = f.getAnnotation(ConfigSection.class);
			if (s != null)
			{
				assertTrue("duplicate section key in " + f.getName(), out.put((String) f.get(null), s) == null);
			}
		}
		return out;
	}

	/** Every setting method, also used by ConfigFitTest. */
	static List<Method> items()
	{
		List<Method> out = new ArrayList<>();
		for (Method m : GroupIronmanConfig.class.getMethods())
		{
			if (m.isAnnotationPresent(ConfigItem.class))
			{
				out.add(m);
			}
		}
		return out;
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collections;
import java.util.EnumSet;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.SkillingContainer.COAL_BAG;
import static com.vinnyvangogh.groupironman.SkillingContainer.FISH_BARREL;
import static com.vinnyvangogh.groupironman.SkillingContainer.LOG_BASKET;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Log basket, fish barrel and coal bag counts from the game's own lines (copied
 * from Combat Vitals' ContainerContents), and the item names kept for Find.
 * Unknown stays unknown: no line, no number.
 */
public class ContainerContentsTest
{
	private static ContainerContents openBasket()
	{
		ContainerContents c = new ContainerContents();
		c.carried(EnumSet.of(LOG_BASKET), Collections.emptyMap());
		return c;
	}

	private static Map<String, Integer> named(Object... nameCount)
	{
		Map<String, Integer> out = new TreeMap<>();
		for (int i = 0; i < nameCount.length; i += 2)
		{
			out.put((String) nameCount[i], (Integer) nameCount[i + 1]);
		}
		return out;
	}

	// ---- Unknown stays unknown ----

	@Test
	public void unknownUntilTheGameSaysAndNoGuessFromGathering()
	{
		ContainerContents c = openBasket();
		assertEquals(-1, c.contents(LOG_BASKET));
		// Gathering into a basket of unknown contents is still unknown, not "1".
		assertFalse(c.message("You get some yew logs.", 10));
		assertEquals(-1, c.contents(LOG_BASKET));
		assertNull(c.named(LOG_BASKET));
	}

	@Test
	public void unrelatedAndNullLinesChangeNothing()
	{
		ContainerContents c = openBasket();
		assertFalse(c.message(null));
		assertFalse(c.message("Welcome to Old School RuneScape."));
		assertFalse(c.message("The basket is full of good intentions"));
		assertEquals(-1, c.contents(LOG_BASKET));
	}

	// ---- Message variants ----

	@Test
	public void checkDialogSumsEveryStackAndKeepsTheNames()
	{
		ContainerContents c = openBasket();
		assertTrue(c.message("The basket contains: 14 x Yew logs"));
		assertEquals(14, c.contents(LOG_BASKET));
		assertEquals(named("Yew logs", 14), c.named(LOG_BASKET));

		// Dialog lines joined with spaces, or a comma list: both read the same.
		assertTrue(c.message("The basket contains: 5 x Logs 3 x Oak logs"));
		assertEquals(8, c.contents(LOG_BASKET));
		assertEquals(named("Logs", 5, "Oak logs", 3), c.named(LOG_BASKET));
		assertTrue(c.message("The basket contains: 5 x Logs, 3 x Oak logs"));
		assertEquals(named("Logs", 5, "Oak logs", 3), c.named(LOG_BASKET));
	}

	@Test
	public void everyEmptyWordingIsZero()
	{
		String[] lines = {"You empty your basket.", "You empty your basket into the bank.", "Your basket is empty.",
			"The basket is empty."};
		for (String line : lines)
		{
			ContainerContents c = openBasket();
			c.message("The basket contains: 19 x Logs");
			assertTrue(line, c.message(line));
			assertEquals(line, 0, c.contents(LOG_BASKET));
			assertEquals(line, Collections.emptyMap(), c.named(LOG_BASKET));
		}
	}

	@Test
	public void gatheredIntoAnOpenBasketCountsOneAndNamesIt()
	{
		ContainerContents c = openBasket();
		c.message("The basket contains: 18 x Yew logs");
		assertTrue(c.message("You get some yew logs.", 20));
		assertEquals(19, c.contents(LOG_BASKET));
		assertEquals(named("Yew logs", 19), c.named(LOG_BASKET));
		assertTrue(c.message("You get some logs.", 21));
		assertEquals(named("Logs", 1, "Yew logs", 19), c.named(LOG_BASKET));
	}

	@Test
	public void aClosedBasketTakesNothing()
	{
		ContainerContents c = new ContainerContents();
		c.carried(EnumSet.noneOf(SkillingContainer.class), Collections.emptyMap());
		c.message("The basket contains: 3 x Logs");
		assertFalse(c.message("You get some logs.", 5));
		assertEquals(3, c.contents(LOG_BASKET));
	}

	@Test
	public void anUnnamedExtraLogKeepsTheCountButForgetsTheNames()
	{
		ContainerContents c = openBasket();
		c.message("The basket contains: 4 x Yew logs");
		assertTrue(c.message("The nature offerings enabled you to chop an extra log.", 7));
		assertEquals(5, c.contents(LOG_BASKET));
		assertNull("which log is not said, so Find says nothing", c.named(LOG_BASKET));
	}

	@Test
	public void anItemLandingInTheInventoryWhileOpenMeansFull()
	{
		ContainerContents c = openBasket();
		c.message("The basket contains: 20 x Logs");
		c.message("You get some logs.", 30);
		// The inventory grew on the same tick with no Fill or Empty: it missed the basket.
		assertTrue(c.inventoryChanged(10, 11, 30));
		assertEquals(28, c.contents(LOG_BASKET));
	}

	@Test
	public void fillAndEmptyMoveWhatTheInventoryShows()
	{
		ContainerContents c = openBasket();
		c.message("The basket contains: 10 x Logs");
		c.clicked(LOG_BASKET, "Fill", 40);
		assertTrue(c.inventoryChanged(12, 4, 41));
		assertEquals(18, c.contents(LOG_BASKET));
		assertNull("filled from the inventory: which logs is not said", c.named(LOG_BASKET));

		c.clicked(LOG_BASKET, "Empty", 50);
		assertTrue(c.inventoryChanged(4, 20, 50));
		assertEquals(2, c.contents(LOG_BASKET));

		c.clicked(LOG_BASKET, "Empty to bank", 60);
		assertEquals(0, c.contents(LOG_BASKET));
	}

	@Test
	public void coalBagWordingIncludingOne()
	{
		ContainerContents c = new ContainerContents();
		assertTrue(c.message("The coal bag contains 27 pieces of coal."));
		assertEquals(27, c.contents(COAL_BAG));
		assertEquals(named("Coal", 27), c.named(COAL_BAG));
		assertTrue(c.message("The coal bag still contains one piece of coal."));
		assertEquals(1, c.contents(COAL_BAG));
		assertTrue(c.message("The coal bag is now empty."));
		assertEquals(0, c.contents(COAL_BAG));
	}

	@Test
	public void barrelCheckFullAndCaughtFish()
	{
		ContainerContents c = new ContainerContents();
		c.carried(EnumSet.of(FISH_BARREL), Collections.emptyMap());
		assertTrue(c.message("The barrel contains: 3 x Raw trout, 2 x Raw salmon"));
		assertEquals(5, c.contents(FISH_BARREL));
		assertTrue(c.fishCaught(70));
		assertEquals(6, c.contents(FISH_BARREL));
		assertTrue(c.message("The barrel is full. It may be emptied at a bank."));
		assertEquals(28, c.contents(FISH_BARREL));
	}

	@Test
	public void restoredCountsNeverOverrideThisSession()
	{
		ContainerContents c = openBasket();
		c.message("The basket contains: 9 x Logs");
		c.restore(LOG_BASKET, 3);
		assertEquals(9, c.contents(LOG_BASKET));
		c.restore(FISH_BARREL, 12);
		assertEquals(12, c.contents(FISH_BARREL));
		assertNull("a restored count has no names", c.named(FISH_BARREL));
		c.clear();
		assertEquals(-1, c.contents(LOG_BASKET));
	}

	// ---- Which items are containers ----

	@Test
	public void containerNamesOpenOrClosed()
	{
		assertEquals(LOG_BASKET, SkillingContainer.fromItemName("Log basket"));
		assertEquals(LOG_BASKET, SkillingContainer.fromItemName("Open forestry basket"));
		assertEquals(FISH_BARREL, SkillingContainer.fromItemName("Fish sack barrel"));
		assertEquals(COAL_BAG, SkillingContainer.fromItemName("Coal bag"));
		assertNull(SkillingContainer.fromItemName("Logs"));
		assertNull(SkillingContainer.fromItemName(null));
		assertTrue(SkillingContainer.isOpen("Open log basket"));
		assertFalse(SkillingContainer.isOpen("Log basket"));
		assertEquals("Yew logs", ContainerContents.logName("yew "));
		assertEquals("Logs", ContainerContents.logName(null));
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static com.vinnyvangogh.groupironman.EventFixtures.items;
import static com.vinnyvangogh.groupironman.EventFixtures.none;
import static com.vinnyvangogh.groupironman.EventFixtures.sample;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The daily digest is in addition to instant posts: it never holds one back (Board 2026-11-10). */
public class DigestRoutingTest
{
	private final FakeItems items = new FakeItems();
	private final List<GroupEvent> discord = new ArrayList<>();
	private final List<GroupEvent> overlay = new ArrayList<>();
	private final List<GroupEvent> digest = new ArrayList<>();
	private final EventRouter router = new EventRouter(discord::add, overlay::add, digest::add);

	private static EventSettings settings(Set<GroupEvent.Type> instant, Set<GroupEvent.Category> digest)
	{
		return new EventSettings(instant, none(), 1_000_000, 1_000_000, 50, 7, false, 0, 100, 5, digest, 20);
	}

	@Test
	public void anInstantPostIsSentWhileItsDigestCategoryIsTicked()
	{
		EventSettings s = settings(EnumSet.of(GroupEvent.Type.DEATH), EnumSet.allOf(GroupEvent.Category.class));
		router.route(sample(GroupEvent.Type.DEATH), true, s, items);
		assertEquals("posted now", 1, discord.size());
		assertEquals("and in tonight's digest", 1, digest.size());
	}

	@Test
	public void theDigestHasTickedAndUntickedEventsOfItsCategory()
	{
		EventSettings s = settings(EnumSet.of(GroupEvent.Type.PET), EnumSet.of(GroupEvent.Category.DROPS));
		router.route(sample(GroupEvent.Type.PET), true, s, items);
		router.route(sample(GroupEvent.Type.CLOG), true, s, items);
		assertEquals("only the ticked pet posts now", 1, discord.size());
		assertEquals(GroupEvent.Type.PET, discord.get(0).type);
		assertEquals("the digest lists both", 2, digest.size());
	}

	@Test
	public void aDigestOnlyCategoryStillLandsInTheDigest()
	{
		EventSettings s = settings(none(), EnumSet.of(GroupEvent.Category.DEATHS));
		assertTrue("detected though no instant post wants it", s.wants(GroupEvent.Type.DEATH));
		assertFalse("other categories stay undetected", s.wants(GroupEvent.Type.PET));
		router.route(sample(GroupEvent.Type.DEATH), true, s, items);
		assertTrue(discord.isEmpty());
		assertEquals(1, digest.size());
	}

	@Test
	public void theDigestKeepsTheThresholdsMembersEventsAndTheRecapOut()
	{
		EventSettings s = settings(none(), EnumSet.allOf(GroupEvent.Category.class));
		router.route(GroupEvent.drop(NOW, "Alex", "Goblin", items(FakeItems.SHARK, 100)), true, s, items);
		router.route(sample(GroupEvent.Type.DEATH), false, s, items);
		router.route(sample(GroupEvent.Type.WEEKLY_RECAP), true, s, items);
		assertFalse("the recap is its own post", s.wants(GroupEvent.Type.WEEKLY_RECAP));
		assertTrue(digest.isEmpty());
	}

	@Test
	public void noDigestTickedMeansNoDigestLines()
	{
		EventSettings s = settings(EnumSet.of(GroupEvent.Type.DEATH), EnumSet.noneOf(GroupEvent.Category.class));
		router.route(sample(GroupEvent.Type.DEATH), true, s, items);
		assertEquals(1, discord.size());
		assertTrue(digest.isEmpty());
	}
}

package com.vinnyvangogh.groupironman;

import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The daily digest's queue and the digest and recap schedule. */
public class DigestTest
{
	private static final ZoneId UTC = ZoneOffset.UTC;

	private static long at(int day, int hour)
	{
		// 2026-11-02 is a Monday.
		return LocalDateTime.of(2026, 11, day, hour, 0).toInstant(ZoneOffset.UTC).toEpochMilli();
	}

	@Test
	public void theDailyDigestIsDueOnceAfterItsHour()
	{
		assertFalse("before the hour", Digest.dailyDue(at(3, 21), at(4, 19), 20, UTC));
		assertTrue(Digest.dailyDue(at(3, 21), at(4, 20), 20, UTC));
		assertFalse("already sent today", Digest.dailyDue(at(4, 20), at(4, 23), 20, UTC));
		assertTrue("a missed day still sends", Digest.dailyDue(at(1, 21), at(4, 22), 20, UTC));
	}

	@Test
	public void aFirstRunOnlySetsTheBaseline()
	{
		assertFalse(Digest.dailyDue(0, at(4, 22), 20, UTC));
		assertFalse(Digest.weeklyDue(0, at(9, 22), 20, UTC));
	}

	@Test
	public void theRecapIsDueMondaysAfterTheHour()
	{
		assertFalse("Sunday", Digest.weeklyDue(at(2, 21), at(8, 23), 20, UTC));
		assertFalse("Monday, too early", Digest.weeklyDue(at(2, 21), at(9, 19), 20, UTC));
		assertTrue(Digest.weeklyDue(at(2, 21), at(9, 20), 20, UTC));
		assertFalse("sent this week", Digest.weeklyDue(at(9, 20), at(10, 22), 20, UTC));
		assertTrue("logged in late in the week still sends", Digest.weeklyDue(at(2, 21), at(12, 9), 20, UTC));
	}

	@Test
	public void linesAreDrainedOncePerCategory()
	{
		Digest d = new Digest();
		d.add(GroupEvent.Category.DROPS, "Alex: one");
		d.add(GroupEvent.Category.DROPS, "Alex: two");
		d.add(GroupEvent.Category.DEATHS, "Alex: died");
		List<String> drops = d.drain(GroupEvent.Category.DROPS);
		assertEquals(2, drops.size());
		assertEquals("Alex: one", drops.get(0));
		assertTrue(d.drain(GroupEvent.Category.DROPS).isEmpty());
		assertEquals(1, d.drain(GroupEvent.Category.DEATHS).size());
	}

	@Test
	public void aFullDayKeepsTheNewestLines()
	{
		Digest d = new Digest();
		for (int i = 0; i < Digest.MAX_LINES + 5; i++)
		{
			d.add(GroupEvent.Category.DROPS, "line " + i);
		}
		List<String> lines = d.drain(GroupEvent.Category.DROPS);
		assertEquals(Digest.MAX_LINES, lines.size());
		assertEquals("line 5", lines.get(0));
	}

	@Test
	public void savedLinesSurviveARestart()
	{
		Digest d = new Digest();
		d.add(GroupEvent.Category.DROPS, "Alex: one");
		d.add(GroupEvent.Category.GROUP, "Alex: back");
		Digest back = Digest.parse(d.save());
		assertEquals("Alex: one", back.drain(GroupEvent.Category.DROPS).get(0));
		assertEquals("Alex: back", back.drain(GroupEvent.Category.GROUP).get(0));
		assertTrue(Digest.parse("nonsense\nNOPE\tline").drain(GroupEvent.Category.DROPS).isEmpty());
		assertTrue(Digest.parse(null).drain(GroupEvent.Category.DROPS).isEmpty());
	}

	@Test
	public void theRecapTalliesTheWeekAndStartsOver()
	{
		Digest.Week w = Digest.Week.parse("");
		w.xp(1_000_000);
		w.xp(1_250_000);
		w.drop();
		w.drop();
		w.kill();
		w.storage(true);
		w.storage(false);
		w.storage(false);
		Digest.Week saved = Digest.Week.parse(w.save());
		GroupEvent e = saved.recap(1L, "Alex");
		assertEquals(GroupEvent.Type.WEEKLY_RECAP, e.type);
		assertEquals(250_000, e.number);
		assertEquals("2 drops, 1 kills, 1 deposits, 2 withdrawals", e.text);
		saved.startOver();
		assertEquals(0, saved.recap(1L, "Alex").number);
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static com.vinnyvangogh.groupironman.EventFixtures.items;
import static com.vinnyvangogh.groupironman.EventFixtures.none;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * One moment, one Discord post: the events the router lets through for Discord
 * are held by {@link DiscordBatch} and posted as one by {@link DiscordMerge},
 * the way {@link GroupEventEngine} wires them.
 */
public class DiscordMergeTest
{
	private static final long STORAGE_MIN = 10_000;
	private static final EnumSet<GroupEvent.Type> STORAGE_ALL = EnumSet.of(GroupEvent.Type.STORAGE_DEPOSIT,
		GroupEvent.Type.STORAGE_WITHDRAWAL, GroupEvent.Type.STORAGE_SUMMARY, GroupEvent.Type.STORAGE_MINIMUM,
		GroupEvent.Type.STORAGE_LAST);

	private final FakeItems items = new FakeItems();
	/** The engine builds Discord posts with every digit kept: "40K (40,000)". */
	private final ItemLookup words = Amounts.BOTH.words(items);
	private final Gson gson = new Gson();
	private final DiscordBatch batch = new DiscordBatch();
	private final List<DiscordBatch.Pending> done = new ArrayList<>();
	private EventSettings settings;
	private long now = NOW;
	private final EventRouter router = new EventRouter(e -> batch.add(e, now,
		DiscordMerge.window(DiscordMerge.family(e.type), settings), done), e ->
	{
	});

	private static EventSettings discord(EnumSet<GroupEvent.Type> on)
	{
		return new EventSettings(on, none(), 1_000_000, STORAGE_MIN, 50, 7, false);
	}

	/** What the engine does with a storage visit: route each event, then lend the batch the whole visit. */
	private void visit(StorageChange change)
	{
		for (GroupEvent e : EventDetect.storage(change, items))
		{
			router.route(e, true, settings, items);
			if (e.type == GroupEvent.Type.STORAGE_SUMMARY)
			{
				batch.attach(e);
			}
		}
	}

	private List<DiscordMerge.Post> posts()
	{
		List<DiscordBatch.Pending> all = new ArrayList<>(done);
		all.addAll(batch.drain());
		List<DiscordMerge.Post> out = new ArrayList<>();
		for (DiscordBatch.Pending p : all)
		{
			DiscordMerge.Post post = DiscordMerge.merge(p.events, settings, words);
			if (post != null)
			{
				out.add(post);
			}
		}
		return out;
	}

	private JsonObject embed(DiscordMerge.Post post)
	{
		String json = DiscordWebhook.payload(gson, post, words, DiscordStyle.EMBED, "", true);
		return new JsonParser().parse(json).getAsJsonObject().getAsJsonArray("embeds").get(0).getAsJsonObject();
	}

	private static List<String> fieldNames(JsonObject embed)
	{
		List<String> out = new ArrayList<>();
		JsonArray fields = embed.getAsJsonArray("fields");
		for (int i = 0; fields != null && i < fields.size(); i++)
		{
			out.add(fields.get(i).getAsJsonObject().get("name").getAsString());
		}
		return out;
	}

	private static StorageChange change(Map<Integer, Integer> took, Map<Integer, Integer> deposited,
		Map<Integer, Integer> after)
	{
		return new StorageChange(NOW, "Alex", took, deposited, after);
	}

	// ---- Storage ----

	@Test
	public void aFortyThousandCoinWithdrawalPostsOnce()
	{
		// The Board's 2026-11-10 test: it posted "Big storage withdrawal" and "Group storage visit".
		settings = discord(STORAGE_ALL);
		visit(change(items(FakeItems.COINS, 40_000), items(), items(FakeItems.COINS, 5)));
		List<DiscordMerge.Post> posts = posts();
		assertEquals(1, posts.size());
		JsonObject embed = embed(posts.get(0));
		assertEquals("Alex: Big storage withdrawal", embed.get("title").getAsString());
		assertTrue(embed.get("description").getAsString(), embed.get("description").getAsString()
			.contains("took 40K (40,000) x Coins (big, 40K gp)"));
		assertEquals("attachment://screenshot.png", embed.getAsJsonObject("image").get("url").getAsString());
	}

	@Test
	public void aVisitWithBigAndSmallMovesPostsOnceListingBoth()
	{
		// The summary switch is off: the post still lists the small deposit.
		settings = discord(EnumSet.of(GroupEvent.Type.STORAGE_DEPOSIT, GroupEvent.Type.STORAGE_WITHDRAWAL));
		visit(change(items(FakeItems.COINS, 40_000), items(FakeItems.LOBSTER, 5), items(FakeItems.COINS, 5)));
		List<DiscordMerge.Post> posts = posts();
		assertEquals(1, posts.size());
		DiscordMerge.Post post = posts.get(0);
		assertEquals("Big storage withdrawal", post.title);
		assertTrue(post.description, post.description.contains("40K (40,000) x Coins (big"));
		assertTrue(post.description, post.description.contains("deposited 5 x Lobster"));
		assertFalse("a small move is not marked", post.description.contains("Lobster (big"));
		assertTrue(fieldNames(embed(post)).contains("Value"));
		// Net: 500 in, 40,000 out (Board 2026-11-15: the two sides are subtracted, never added).
		assertEquals("the visit's net", "-39.5K (39,500) gp (deposited 500, took 40K (40,000))", embed(post).getAsJsonArray("fields").get(0).getAsJsonObject()
			.get("value").getAsString());
	}

	@Test
	public void bigBothWaysIsABigStorageVisit()
	{
		settings = discord(STORAGE_ALL);
		visit(change(items(FakeItems.COINS, 40_000), items(FakeItems.WHIP, 1), items(FakeItems.COINS, 5)));
		List<DiscordMerge.Post> posts = posts();
		assertEquals(1, posts.size());
		assertEquals("Big storage visit", posts.get(0).title);
	}

	@Test
	public void aVisitWithNoBigMovesPostsTheSummaryWhenItIsOn()
	{
		settings = discord(STORAGE_ALL);
		visit(change(items(FakeItems.LOBSTER, 5), items(), items(FakeItems.LOBSTER, 5)));
		List<DiscordMerge.Post> posts = posts();
		assertEquals(1, posts.size());
		assertEquals("Group storage visit", posts.get(0).title);
		assertTrue(posts.get(0).description.contains("took 5 x Lobster"));
		assertFalse(posts.get(0).description.contains("(big"));
	}

	@Test
	public void aVisitWithNoBigMovesAndTheSummaryOffPostsNothing()
	{
		settings = discord(EnumSet.of(GroupEvent.Type.STORAGE_DEPOSIT, GroupEvent.Type.STORAGE_WITHDRAWAL));
		visit(change(items(FakeItems.LOBSTER, 5), items(), items(FakeItems.LOBSTER, 5)));
		assertTrue(posts().isEmpty());
	}

	@Test
	public void theMinimumAndTheLastOneFoldIntoTheVisitPost()
	{
		settings = discord(STORAGE_ALL);
		// The engine hears the minimum first (GroupService.commitStorage), then the visit.
		router.route(EventDetect.minimum(NOW, "Alex", new LowStock.Alert("Coins", 0, 100)), true, settings, items);
		visit(change(items(FakeItems.COINS, 40_000), items(), items()));
		List<DiscordMerge.Post> posts = posts();
		assertEquals(1, posts.size());
