package com.vinnyvangogh.groupironman;

import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.slf4j.LoggerFactory;
import static com.vinnyvangogh.groupironman.DiscordWebhookTest.URL;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The queue, rate limits, back-off and quiet hours, with a fake transport and clock: no network at all. */
public class DiscordSenderTest
{
	private static final long SEC = TimeUnit.SECONDS.toMillis(1);

	private long now = 1_000_000;
	private int hour = 12;
	private final List<DiscordQueue.Post> sent = new ArrayList<>();
	private final List<DiscordSender.Done> pending = new ArrayList<>();
	private final DiscordSender sender = new DiscordSender((post, done) ->
	{
		sent.add(post);
		pending.add(done);
	}, () -> now, () -> hour);

	private ListAppender<ILoggingEvent> logs;
	private Logger logger;

	@Before
	public void captureLogs()
	{
		logger = (Logger) LoggerFactory.getLogger(DiscordSender.class);
		logger.setLevel(Level.DEBUG);
		logs = new ListAppender<>();
		logs.start();
		logger.addAppender(logs);
	}

	@After
	public void releaseLogs()
	{
		logger.detachAppender(logs);
	}

	private void reply(int status, String retryAfter)
	{
		pending.remove(0).done(status, retryAfter);
	}

	@Test
	public void noUrlMeansNoNetwork()
	{
		sender.post(null, "{}", null);
		sender.post(Webhooks.of(new GroupIronmanConfig()
		{
		}).url(Webhook.DROPS), "{}", null);
		sender.pump();
		assertTrue(sent.isEmpty());
		assertEquals(0, sender.queued());
	}

	private static final String OTHER = "https://discord.com/api/webhooks/9/other-token";

	@Test
	public void eachWebhookHasItsOwnQueueSoOneBusyWebhookNeverHoldsAnother()
	{
		sender.post(URL, "a1", null);
		sender.post(URL, "a2", null);
		sender.post(OTHER, "b1", null);
		sender.pump();
		assertEquals("one in flight per webhook, both at once", 2, sent.size());
		assertEquals(3, sender.queued());
	}

	@Test
	public void a429OnOneWebhookBacksOffThatWebhookOnly()
	{
		sender.post(URL, "a1", null);
		sender.pump();
		reply(429, "30");
		sender.post(OTHER, "b1", null);
		sender.post(URL, "a2", null);
		now += SEC;
		sender.pump();
		assertEquals(2, sent.size());
		assertEquals("the other webhook still posts", "b1", sent.get(1).json);
		reply(204, null);
		sender.post(OTHER, "b2", null);
		now += SEC;
		sender.pump();
		assertEquals("b2", sent.get(2).json);
	}

	@Test
	public void theMinuteCapIsPerWebhook()
	{
		for (int i = 0; i < DiscordQueue.PER_MINUTE + 1; i++)
		{
			sender.post(URL, "a" + i, null);
			sender.post(OTHER, "b" + i, null);
		}
		for (int i = 0; i < 2 * DiscordQueue.PER_MINUTE; i++)
		{
			sender.pump();
			while (!pending.isEmpty())
			{
				reply(204, null);
			}
			now += SEC;
		}
		assertEquals("twenty a minute on each", 2 * DiscordQueue.PER_MINUTE, sent.size());
	}

	@Test
	public void postsGoOneAtATimeInOrder()
	{
		sender.post(URL, "a", null);
		sender.post(URL, "b", null);
		sender.pump();
		sender.pump();
		assertEquals("b waits for a", 1, sent.size());
		reply(204, null);
		sender.pump();
		assertEquals("b", sent.get(1).json);
	}

	@Test
	public void aFullQueueDropsTheOldest()
	{
		for (int i = 0; i < DiscordQueue.MAX_QUEUED + 5; i++)
		{
			sender.post(URL, "p" + i, null);
		}
		assertEquals(DiscordQueue.MAX_QUEUED, sender.queued());
		sender.pump();
		assertEquals("p5", sent.get(0).json);
	}

	@Test
	public void twentyAMinuteAtMost()
	{
		for (int i = 0; i < 30; i++)
		{
			sender.post(URL, "p" + i, null);
		}
		for (int i = 0; i < 30; i++)
		{
			sender.pump();
			if (!pending.isEmpty())
			{
				reply(204, null);
			}
			now += SEC;
		}
		assertEquals(DiscordQueue.PER_MINUTE, sent.size());
		now += 60 * SEC;
		sender.pump();
		assertEquals("the next minute sends again", DiscordQueue.PER_MINUTE + 1, sent.size());
	}

	@Test
	public void a429WaitsItsRetryAfterAndRetriesTheSamePost()
	{
		sender.post(URL, "a", null);
		sender.pump();
		reply(429, "2.5");
		sender.pump();
		now += 2 * SEC;
		sender.pump();
		assertEquals("still backing off", 1, sent.size());
		now += SEC;
		sender.pump();
		assertEquals(2, sent.size());
		assertEquals("a", sent.get(1).json);
	}

	@Test
	public void aServerErrorRetriesAFewTimesThenGivesUp()
	{
		sender.post(URL, "a", null);
		for (int i = 0; i < DiscordQueue.MAX_ATTEMPTS + 2; i++)
		{
			sender.pump();
			if (!pending.isEmpty())
			{
				reply(502, null);
			}
			now += DiscordQueue.RETRY_MS;
		}
		assertEquals(DiscordQueue.MAX_ATTEMPTS, sent.size());
		assertEquals(0, sender.queued());
	}

	@Test
	public void aDeletedWebhookIsNotRetried()
	{
		sender.post(URL, "a", null);
		sender.pump();
		reply(404, null);
		now += 10 * SEC;
		sender.pump();
		assertEquals(1, sent.size());
	}

	@Test
	public void quietHoursHoldPostsAndSendThemAfter()
	{
		sender.quietHours(22, 7);
		hour = 23;
		sender.post(URL, "a", null);
		sender.pump();
		hour = 3;
		sender.pump();
		assertTrue("held overnight", sent.isEmpty());
		assertEquals(1, sender.queued());
		hour = 7;
		sender.pump();
		assertEquals(1, sent.size());
	}

	@Test
	public void quietHoursAcrossMidnightAndOff()
	{
		assertTrue(DiscordQueue.quiet(23, 22, 7));
		assertTrue(DiscordQueue.quiet(0, 22, 7));
		assertFalse(DiscordQueue.quiet(7, 22, 7));
		assertTrue(DiscordQueue.quiet(13, 13, 14));
		assertFalse(DiscordQueue.quiet(14, 13, 14));
		assertFalse("equal hours: off", DiscordQueue.quiet(5, 0, 0));
	}

	@Test
	public void retryAfterIsSecondsPossiblyFractional()
	{
		assertEquals(2500, DiscordQueue.retryAfterMs("2.5"));
		assertEquals(1000, DiscordQueue.retryAfterMs("1"));
		assertEquals(-1, DiscordQueue.retryAfterMs(null));
		assertEquals(-1, DiscordQueue.retryAfterMs("soon"));
	}

	@Test
	public void theUrlIsNeverLogged()
	{
		sender.post(URL, "a", null);
		sender.pump();
		reply(0, null);
		now += DiscordQueue.RETRY_MS;
		sender.pump();
		reply(401, null);
		assertFalse("failures were logged", logs.list.isEmpty());
		for (ILoggingEvent e : logs.list)
		{
			assertFalse(e.getFormattedMessage().contains("webhooks"));
			assertFalse(e.getFormattedMessage().contains("AbC-def_GHI123"));
		}
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static com.vinnyvangogh.groupironman.EventFixtures.items;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DiscordWebhookTest
{
	static final String URL = "https://discord.com/api/webhooks/123456789012345678/AbC-def_GHI123";
	private final Gson gson = new Gson();
	private final FakeItems items = new FakeItems();

	@Test
	public void onlyDiscordWebhookUrlsAreAccepted()
	{
		assertTrue(DiscordWebhook.valid(URL));
		assertTrue(DiscordWebhook.valid("https://discordapp.com/api/webhooks/1/x"));
		assertTrue(DiscordWebhook.valid("https://canary.discord.com/api/webhooks/1/x"));
		assertFalse(DiscordWebhook.valid(""));
		assertFalse(DiscordWebhook.valid(null));
		assertFalse("not https", DiscordWebhook.valid("http://discord.com/api/webhooks/1/x"));
		assertFalse("another host", DiscordWebhook.valid("https://discord.com.evil.example/api/webhooks/1/x"));
		assertFalse("not a webhook", DiscordWebhook.valid("https://discord.com/channels/1/2"));
		assertFalse("no token", DiscordWebhook.valid("https://discord.com/api/webhooks/1/"));
	}

	@Test
	public void anEmbedHasTitleColourIconValueAndTime()
	{
		GroupEvent drop = GroupEvent.of(GroupEvent.Type.DROP, NOW, "Alex").text("Vorkath")
			.items(items(FakeItems.WHIP, 1)).number(120).world(302).build();
		JsonObject o = parse(DiscordWebhook.payload(gson, drop, items, DiscordStyle.EMBED, "<@&1>", false));
		assertEquals("GIM Utilities", o.get("username").getAsString());
		assertFalse("a drop is not big: no mention", o.has("content"));
		assertEquals(0, o.getAsJsonObject("allowed_mentions").getAsJsonArray("parse").size());
		JsonObject embed = o.getAsJsonArray("embeds").get(0).getAsJsonObject();
		assertEquals("Alex: Valuable drop", embed.get("title").getAsString());
		assertEquals("Vorkath dropped 1 x Abyssal whip, kill count 120", embed.get("description").getAsString());
		assertEquals(GroupEvent.Category.DROPS.colour, embed.get("color").getAsInt());
		assertEquals("https://static.runelite.net/cache/item/icon/4151.png",
			embed.getAsJsonObject("thumbnail").get("url").getAsString());
		assertEquals("2023-11-14T22:13:20Z", embed.get("timestamp").getAsString());
		assertEquals("Value", embed.getAsJsonArray("fields").get(0).getAsJsonObject().get("name").getAsString());
		assertEquals("1.5M (1,500,000) gp",
			embed.getAsJsonArray("fields").get(0).getAsJsonObject().get("value").getAsString());
		assertEquals("302", embed.getAsJsonArray("fields").get(1).getAsJsonObject().get("value").getAsString());
		assertFalse(embed.has("image"));
	}

	@Test
	public void coinsReadLikeTheGameWithTheExactAmountAndAPileIcon()
	{
		GroupEvent took = GroupEvent.of(GroupEvent.Type.STORAGE_WITHDRAWAL, NOW, "Alex")
			.items(items(FakeItems.COINS, 40_000)).build();
		JsonObject embed = parse(DiscordWebhook.payload(gson, took, items, DiscordStyle.EMBED, "", false))
			.getAsJsonArray("embeds").get(0).getAsJsonObject();
		// The exact total is in the Value field; the line's own total stays short so parentheses don't nest.
		assertEquals("took 40K (40,000) x Coins (40K gp) from group storage",
			embed.get("description").getAsString());
		assertEquals("40K (40,000) gp", embed.getAsJsonArray("fields").get(0).getAsJsonObject().get("value")
			.getAsString());
		assertEquals("the 10,000 coin pile, not one coin", "https://static.runelite.net/cache/item/icon/1004.png",
			embed.getAsJsonObject("thumbnail").get("url").getAsString());

		JsonObject plain = parse(DiscordWebhook.payload(gson, took, items, DiscordStyle.PLAIN, "", false));
		assertEquals("Alex: took 40K (40,000) x Coins (40K gp) from group storage",
			plain.get("content").getAsString());
	}

	@Test
	public void aBigEventMentionsAndMayPing()
	{
		GroupEvent pet = GroupEvent.of(GroupEvent.Type.PET, NOW, "Alex").build();
		JsonObject o = parse(DiscordWebhook.payload(gson, pet, items, DiscordStyle.EMBED, " <@&42> ", false));
		assertEquals("<@&42>", o.get("content").getAsString());
		assertEquals(2, o.getAsJsonObject("allowed_mentions").getAsJsonArray("parse").size());
		JsonObject none = parse(DiscordWebhook.payload(gson, pet, items, DiscordStyle.EMBED, "", false));
		assertFalse(none.has("content"));
	}

	@Test
	public void plainTextIsOneLine()
	{
		GroupEvent pet = GroupEvent.of(GroupEvent.Type.PET, NOW, "Alex").build();
		JsonObject o = parse(DiscordWebhook.payload(gson, pet, items, DiscordStyle.PLAIN, "<@1>", false));
		assertEquals("<@1> Alex: a pet!", o.get("content").getAsString());
		assertFalse(o.has("embeds"));
	}

	@Test
	public void aScreenshotIsTheEmbedImage()
	{
		GroupEvent pet = GroupEvent.of(GroupEvent.Type.PET, NOW, "Alex").build();
		JsonObject embed = parse(DiscordWebhook.payload(gson, pet, items, DiscordStyle.EMBED, "", true))
			.getAsJsonArray("embeds").get(0).getAsJsonObject();
		assertEquals("attachment://screenshot.png", embed.getAsJsonObject("image").get("url").getAsString());
	}

	@Test
	public void theMasterSwitchCarriesTheThirdPartyWarning() throws Exception
	{
		ConfigItem item = GroupIronmanConfig.class.getMethod("discordEnabled").getAnnotation(ConfigItem.class);
		assertEquals(DiscordWebhook.WARNING, item.warning());
		for (String url : new String[]{"discordWebhookUrl", "discordDropsUrl", "discordDeathsUrl", "discordStorageUrl",
			"discordProgressUrl", "discordGroupUrl", "discordActivitiesUrl"})
		{
			assertTrue(url + " is a secret field", GroupIronmanConfig.class.getMethod(url)
				.getAnnotation(ConfigItem.class).secret());
		}
	}

	private static JsonObject parse(String json)
	{
		return new JsonParser().parse(json).getAsJsonObject();
	}
}

package com.vinnyvangogh.groupironman;

import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.TimeUnit;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static com.vinnyvangogh.groupironman.FakeItems.*;

/** The "since you last played" log: members' drops and new collection log slots. */
public class DropLogTest
{
	private static final long HOUR = TimeUnit.HOURS.toMillis(1);
	private static final long NOW = 1_762_000_000_000L;

	private static Map<Integer, Integer> items(int... pairs)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			out.put(pairs[i], pairs[i + 1]);
		}
		return out;
	}

	@Test
	public void entriesAreNewestFirst()
	{
		DropLog log = new DropLog();
		log.add(GroupEvent.drop(NOW - 3 * HOUR, "Alex", "Vorkath", items(WHIP, 1)));
		log.add(GroupEvent.clog(NOW - HOUR, "Sam", "Draconic visage"));
		log.add(GroupEvent.drop(NOW - 2 * HOUR, "Sam", "Shark", items(SHARK, 3)));
		List<GroupEvent> entries = log.entries();
		assertEquals(3, entries.size());
		assertEquals(NOW - HOUR, entries.get(0).at);
		assertEquals(NOW - 3 * HOUR, entries.get(2).at);
	}

	@Test
	public void aResentEventIsNotLoggedTwice()
	{
		DropLog log = new DropLog();
		assertTrue(log.add(GroupEvent.drop(NOW, "Alex", "Vorkath", items(WHIP, 1))));
		// The same drop arriving again when a member rejoins and everyone resends.
		assertFalse(log.add(GroupEvent.drop(NOW, "alex", "Vorkath", items(WHIP, 1))));
		assertTrue(log.add(GroupEvent.clog(NOW, "Alex", "Abyssal whip")));
		assertFalse(log.add(GroupEvent.clog(NOW, "Alex", "abyssal whip")));
		assertEquals(2, log.entries().size());
	}

	@Test
	public void twoDifferentDropsInTheSameMillisecondAreBothKept()
	{
		DropLog log = new DropLog();
		assertTrue(log.add(GroupEvent.drop(NOW, "Alex", "Goblin", items(SHARK, 1))));
		assertTrue(log.add(GroupEvent.drop(NOW, "Alex", "Goblin", items(COAL, 1))));
		assertEquals(2, log.entries().size());
	}

	@Test
	public void emptyOrNamelessEventsAreDropped()
	{
