package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static com.vinnyvangogh.groupironman.EventFixtures.all;
import static com.vinnyvangogh.groupironman.EventFixtures.items;
import static com.vinnyvangogh.groupironman.EventFixtures.none;
import static com.vinnyvangogh.groupironman.EventFixtures.sample;
import static com.vinnyvangogh.groupironman.EventFixtures.settings;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class EventRouterTest
{
	private final FakeItems items = new FakeItems();
	private final List<GroupEvent> discord = new ArrayList<>();
	private final List<GroupEvent> overlay = new ArrayList<>();
	private final EventRouter router = new EventRouter(discord::add, overlay::add);

	@Test
	public void everyKindReachesEachOutputOnceWhenItsSwitchIsOn()
	{
		for (GroupEvent.Type t : GroupEvent.Type.values())
		{
			discord.clear();
			overlay.clear();
			GroupEvent e = sample(t);
			router.route(e, true, settings(EnumSet.of(t), EnumSet.of(t)), items);
			assertEquals(t + " to Discord", 1, discord.size());
			assertEquals(t + " to the overlay", 1, overlay.size());
			assertEquals(t, discord.get(0).type);
			assertEquals("Alex", overlay.get(0).member);
		}
	}

	@Test
	public void noKindReachesAnOutputWithItsSwitchOff()
	{
		for (GroupEvent.Type t : GroupEvent.Type.values())
		{
			EnumSet<GroupEvent.Type> others = EnumSet.complementOf(EnumSet.of(t));
			router.route(sample(t), true, settings(others, others), items);
			router.route(sample(t), true, EventSettings.OFF, items);
		}
		assertTrue(discord.isEmpty());
		assertTrue(overlay.isEmpty());
	}

	@Test
	public void onlyOwnEventsArePostedSoEachIsPostedOnce()
	{
		// Alex's client posts Alex's drop; Sam's client sees the same drop from the party and does not.
		GroupEvent drop = sample(GroupEvent.Type.DROP);
		router.route(drop, true, settings(all(), all()), items);
		router.route(drop, false, settings(all(), all()), items);
		assertEquals(1, discord.size());
		assertEquals("both clients show it", 2, overlay.size());
	}

	@Test
	public void aDropKeepsOnlyItsValuableStacks()
	{
		GroupEvent drop = GroupEvent.drop(NOW, "Alex", "Vorkath", items(FakeItems.WHIP, 1, FakeItems.SHARK, 5));
		router.route(drop, true, settings(all(), none()), items);
		assertEquals(items(FakeItems.WHIP, 1), discord.get(0).items);

		discord.clear();
		router.route(GroupEvent.drop(NOW, "Alex", "Goblin", items(FakeItems.SHARK, 100)), true,
			settings(all(), all()), items);
		assertTrue("80K of sharks is under 1M", discord.isEmpty() && overlay.isEmpty());
	}

	@Test
	public void levelAndStorageThresholds()
	{
		EventSettings s = settings(all(), none());
		router.route(GroupEvent.of(GroupEvent.Type.LEVEL_UP, NOW, "Alex").text("Attack").number(49).build(), true, s,
			items);
		router.route(GroupEvent.of(GroupEvent.Type.STORAGE_DEPOSIT, NOW, "Alex").items(items(FakeItems.SHARK, 1))
			.number(999_999).build(), true, s, items);
		assertTrue(discord.isEmpty());
		router.route(GroupEvent.of(GroupEvent.Type.LEVEL_UP, NOW, "Alex").text("Attack").number(50).build(), true, s,
			items);
		router.route(GroupEvent.of(GroupEvent.Type.STORAGE_WITHDRAWAL, NOW, "Alex").items(items(FakeItems.WHIP, 1))
			.number(1_000_000).build(), true, s, items);
		assertEquals(2, discord.size());
	}

	@Test
	public void unthresholdedKindsPassUnchanged()
	{
		GroupEvent pet = sample(GroupEvent.Type.PET);
		assertSame(pet, EventRouter.threshold(pet, settings(all(), all()), items));
	}

	@Test
	public void anEventWithNoMemberIsDropped()
	{
		router.route(GroupEvent.of(GroupEvent.Type.PET, NOW, "").build(), true, settings(all(), all()), items);
		assertTrue(discord.isEmpty() && overlay.isEmpty());
	}
}

package com.vinnyvangogh.groupironman;

import java.lang.reflect.Proxy;
import java.util.EnumSet;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class EventSettingsTest
{
	private static final GroupIronmanConfig DEFAULTS = new GroupIronmanConfig()
	{
	};

	@Test
	public void everyKindHasADiscordAndAnOverlaySwitch()
	{
		for (GroupEvent.Type t : GroupEvent.Type.values())
		{
			assertTrue(t + " Discord switch", EventSettings.DISCORD.containsKey(t));
			assertTrue(t + " overlay switch", EventSettings.OVERLAY.containsKey(t));
		}
	}

	@Test
	public void aFreshInstallWantsNothing()
	{
		EventSettings s = EventSettings.from(DEFAULTS);
		// Online status defaults to Posts (Board 2026-11-10); nothing posts until Discord is turned on.
		assertEquals(EnumSet.of(GroupEvent.Type.ONLINE), s.discord);
		assertTrue(s.overlay.isEmpty());
		assertFalse(s.share);
		for (GroupEvent.Type t : GroupEvent.Type.values())
		{
			assertEquals(t == GroupEvent.Type.ONLINE, s.wants(t));
		}
		assertEquals(1_000_000, s.dropMin);
		assertEquals(7, s.backAfterDays);
	}

	@Test
	public void eachSwitchTurnsOnItsOwnKindOnly()
	{
		// Through a config proxy, the way RuneLite reads settings: only discordPet and overlayDeath are on.
		GroupIronmanConfig config = (GroupIronmanConfig) Proxy.newProxyInstance(
			GroupIronmanConfig.class.getClassLoader(), new Class<?>[]{GroupIronmanConfig.class},
			(p, m, args) ->
			{
				if (m.getReturnType() == boolean.class)
				{
					return m.getName().equals("discordPet") || m.getName().equals("overlayDeath");
				}
				return m.getReturnType() == int.class ? 3 : null;
			});
		EventSettings s = EventSettings.from(config);
		assertEquals(EnumSet.of(GroupEvent.Type.PET), s.discord);
		assertEquals(EnumSet.of(GroupEvent.Type.DEATH), s.overlay);
		assertEquals(3, s.levelMin);
	}

	@Test
	public void eventTextCoversEveryKind()
	{
		FakeItems items = new FakeItems();
		for (GroupEvent.Type t : GroupEvent.Type.values())
		{
			assertTrue(t + " has words", EventText.covers(t));
			assertFalse(EventText.describe(EventFixtures.sample(t), items).isEmpty());
		}
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Each medium kind: detected from a game line or variable change, fires once, silent when its switch is off. */
public class EventWatchersTest
{
	private final List<GroupEvent> out = new ArrayList<>();
	private final Map<Integer, Integer> vars = new HashMap<>();
	private EnumSet<GroupEvent.Type> on;
	private EventWatchers watchers;

	@Before
	public void setUp()
	{
		on = EnumSet.allOf(GroupEvent.Type.class);
		watchers = new EventWatchers(out::add, t -> on.contains(t));
	}

	private void chat(String line)
	{
		watchers.chat(line, NOW, "Alex", Collections.singleton("Sam"), Arrays.asList("Alex", "Sam", "Stranger"));
	}

	private GroupEvent only()
	{
		assertEquals(1, out.size());
		return out.get(0);
	}

	private void silentWhenOff(GroupEvent.Type type, String line)
	{
		on.remove(type);
		out.clear();
		chat(line);
		assertTrue(type + " off is silent", out.isEmpty());
	}

	private void poll()
	{
		watchers.poll(id -> vars.getOrDefault(id, 0), NOW, "Alex");
	}

	@Test
	public void raidUniqueNamesTheTeamMembersInTheGroupAndCountsTheRest()
	{
		watchers.raidCount("Theatre of Blood", 12);
		chat("<col=ef20ff>Alex found something special: Scythe of vitur (uncharged)</col>");
		GroupEvent e = only();
		assertEquals(GroupEvent.Type.RAID_UNIQUE, e.type);
		assertEquals("Scythe of vitur (uncharged)", e.text);
		assertEquals(12, e.number);
		assertEquals("Theatre of Blood; with Sam +1 other", e.detail);
		assertTrue(e.isBig());
		silentWhenOff(GroupEvent.Type.RAID_UNIQUE, "Alex found something special: Scythe of vitur (uncharged)");
	}

	@Test
	public void aTeammatesPurpleIsTheirsToPost()
	{
		chat("Sam found something special: Scythe of vitur (uncharged)");
		assertTrue(out.isEmpty());
	}

	@Test
	public void chambersLootNeedsItsHeaderLine()
	{
		chat("Alex - Twisted bow");
		assertTrue("a bare dash line is not loot", out.isEmpty());
		chat("Special loot:");
		chat("Alex - Twisted bow");
		assertEquals("Twisted bow", only().text);
	}

	@Test
	public void clueCountsAreKeptByTierAndValuedByTheReward()
	{
		chat("You have completed <col=ff0000>42</col> medium Treasure Trails.");
		assertTrue("waits for the reward", out.isEmpty());
		watchers.clueReward(EventFixtures.items(FakeItems.WHIP, 1), 1_500_000, NOW, "Alex");
		GroupEvent e = only();
		assertEquals(GroupEvent.Type.CLUE, e.type);
		assertEquals("medium", e.text);
		assertEquals(1_500_000, e.number);
		assertEquals("medium 42", e.detail);
		out.clear();
		watchers.clueReward(EventFixtures.items(FakeItems.WHIP, 1), 1_500_000, NOW, "Alex");
		assertTrue("one reward per completed line", out.isEmpty());
		chat("You have completed 3 master Treasure Trails.");
		watchers.clueReward(EventFixtures.items(FakeItems.WHIP, 1), 5, NOW, "Alex");
		assertEquals("medium 42, master 3", only().detail);
	}

	@Test
	public void aClueBelowTheThresholdIsDroppedByTheRouter()
	{
		GroupEvent clue = GroupEvent.of(GroupEvent.Type.CLUE, NOW, "Alex").text("easy").number(10).build();
		EventSettings s = new EventSettings(EventFixtures.all(), EventFixtures.none(), 0, 0, 1, 7, false, 1_000,
			100, 5, EnumSet.noneOf(GroupEvent.Category.class), 20);
		assertNull(EventRouter.threshold(clue, s, new FakeItems()));
	}

	@Test
	public void kcMilestonesFireEveryNOnceEach()
	{
		watchers.kill("Vorkath", 99, 100, NOW, "Alex");
		assertTrue(out.isEmpty());
		watchers.kill("Vorkath", 100, 100, NOW, "Alex");
		GroupEvent e = only();
		assertEquals(GroupEvent.Type.KC_MILESTONE, e.type);
		assertEquals("Vorkath", e.text);
		assertEquals(100, e.number);
		out.clear();
		watchers.kill("Vorkath", 100, 100, NOW, "Alex");
		assertTrue("the same line twice is one milestone", out.isEmpty());
		on.remove(GroupEvent.Type.KC_MILESTONE);
		watchers.kill("Vorkath", 200, 100, NOW, "Alex");
		assertTrue(out.isEmpty());
	}

	@Test
	public void personalBestsCombatTasksAndSlayer()
	{
		chat("Fight duration: <col=ff0000>1:23</col> (new personal best)");
		assertEquals("1:23", only().text);
		assertEquals(GroupEvent.Type.PERSONAL_BEST, out.get(0).type);
		silentWhenOff(GroupEvent.Type.PERSONAL_BEST, "Fight duration: <col=ff0000>1:23</col> (new personal best)");
		on.add(GroupEvent.Type.PERSONAL_BEST);
		out.clear();
		chat("Fight duration: <col=ff0000>1:40</col>. Personal best: 1:23");
		assertTrue("not a new best", out.isEmpty());

		chat("Congratulations, you've completed an elite combat task: <col=06600c>Peach Conjurer</col> (4 points).");
		GroupEvent ca = only();
		assertEquals(GroupEvent.Type.COMBAT_TASK, ca.type);
		assertEquals("Peach Conjurer", ca.text);
		assertEquals("elite", ca.detail);
		silentWhenOff(GroupEvent.Type.COMBAT_TASK,
			"Congratulations, you've completed an elite combat task: <col=06600c>Peach Conjurer</col> (4 points).");

		on.add(GroupEvent.Type.COMBAT_TASK);
		out.clear();
		chat("You have completed your task! You killed 19 Icefiends. You gained 1,520 xp.");
		assertTrue("waits for its streak line", out.isEmpty());
		chat("You've completed 123 tasks and received 15 points, giving you a total of 240; return to a Slayer master.");
		GroupEvent done = only();
		assertEquals(GroupEvent.Type.SLAYER, done.type);
		assertEquals("Slayer task done: Icefiends (streak 123, 15 points)", EventText.describe(done, new FakeItems()));
		out.clear();
		chat("You have received a new Slayer assignment from Konar: Hellhounds (150)");
		assertEquals("Hellhounds", only().text);
		assertEquals(150, out.get(0).number);
		out.clear();
		chat("You're assigned to kill hellhounds; only 150 more to go.");
		assertTrue("the gem repeats the task it was given", out.isEmpty());
		silentWhenOff(GroupEvent.Type.SLAYER, "You have received a new Slayer assignment from Konar: Hellhounds (150)");
	}

	@Test
	public void firstPollIsABaselineNotAnEvent()
	{
		vars.put(EventWatchers.SKULL, 1);
		vars.put(net.runelite.api.gameval.VarbitID.INSIDE_WILDERNESS, 1);
		vars.put(net.runelite.api.gameval.VarbitID.VARROCK_DIARY_EASY_COMPLETE, 1);
		poll();
		assertTrue(out.isEmpty());
		poll();
		assertTrue("unchanged stays silent", out.isEmpty());
