		String junk = "nonsense;999.1=4,1,1,0;12083.x=4,1,1,0;" + FALADOR + "." + VarbitID.FARMING_TRANSMIT_D + "=abc,1,1,0";
		FarmRuns bad = FarmRuns.parse(junk, out::add, t -> true);
