package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.TimeUnit;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static com.vinnyvangogh.groupironman.FakeItems.*;

public class FindCommandTest
{
	private static final long NOW = TimeUnit.DAYS.toMillis(100);
	private static final FakeItems ITEMS = new FakeItems();
	private static final Gson GSON = new Gson();

	private static Map<Integer, Integer> items(int... pairs)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			out.put(pairs[i], pairs[i + 1]);
		}
		return out;
	}

	private static long daysAgo(int days)
	{
		return NOW - TimeUnit.DAYS.toMillis(days);
	}

	private static StorageChange took(long at, String member, Map<Integer, Integer> took)
	{
		return new StorageChange(at, member, took, items(), items());
	}

	@Test
	public void chatAnswerNamesTheSearchSaysYourAndColoursEachPlace()
	{
		// Board 2026-11-04: show the search, say "your bank" for yourself, colour each kind of place.
		java.awt.Color q = new java.awt.Color(0x11, 0x11, 0x11);
		java.awt.Color item = new java.awt.Color(0x22, 0x22, 0x22);
		java.awt.Color mine = new java.awt.Color(0x33, 0x33, 0x33);
		java.awt.Color theirs = new java.awt.Color(0x44, 0x44, 0x44);
		java.awt.Color storage = new java.awt.Color(0x55, 0x55, 0x55);
		java.awt.Color carried = new java.awt.Color(0x66, 0x66, 0x66);
		FindStyle style = new FindStyle("GroupShip", q, item, mine, theirs, storage, carried);

		GroupRoster roster = new GroupRoster();
		roster.putBank("GroupShip", new BankSnapshot(NOW, items(SHARK, 15)));
		roster.putBank("Alex", new BankSnapshot(NOW, items(SHARK, 2)));
		roster.putCarried("Sam", new GroupCodec.Carried(items(SHARK, 1), items(WHIP, 1)));
		roster.putStorage(new StorageChange(NOW - TimeUnit.MINUTES.toMillis(8), "GroupShip", items(SHARK, 3), items(),
			items(SHARK, 140)));

		List<String> out = FindCommand.answer("Shark", roster.searchSources(), roster.log().entries(), ITEMS, NOW, style);
		assertEquals("Find <col=111111>Shark</col>:", out.get(0));
		String line = out.get(1);
		assertTrue(line, line.startsWith("<col=222222>Shark</col>: "));
		assertTrue(line, line.contains("<col=333333>15 in your bank</col>"));
		assertTrue(line, line.contains("<col=444444>2 in Alex's bank</col>"));
		assertTrue(line, line.contains("<col=666666>1 in Sam's inventory</col>"));
		assertTrue(line, line.contains("<col=555555>140 in group storage</col>"));
		assertEquals("<col=555555>You took 3 x Shark from storage</col> (8m ago)", out.get(2));

		List<String> whip = FindCommand.answer("whip", roster.searchSources(), roster.log().entries(), ITEMS, NOW, style);
		assertTrue(whip.get(1), whip.get(1).contains("<col=666666>1 equipped by Sam</col>"));

		List<String> none = FindCommand.answer("dragon", roster.searchSources(), roster.log().entries(), ITEMS, NOW,
			style);
		assertTrue(none.get(0), none.get(0).startsWith("Nothing found for <col=111111>dragon</col>."));
		// A query with tag characters cannot inject markup.
		assertTrue(FindCommand.answer("<col=ff0000>sh", roster.searchSources(), roster.log().entries(), ITEMS, NOW,
			style).get(0).contains("col=ff0000sh"));
	}

	@Test
	public void answersCurrentHoldersThenWhoLastTookItFromStorage()
	{
		GroupRoster roster = new GroupRoster();
		roster.putBank("Sam", new BankSnapshot(NOW - TimeUnit.HOURS.toMillis(2), items(WHIP, 1)));
		roster.log().add(took(daysAgo(3), "Alex", items(WHIP, 1)));

		assertEquals(Arrays.asList(
			"Abyssal whip: Sam bank 1 (2h ago)",
			"Alex took 1 x Abyssal whip from storage (3d ago)"),
			FindCommand.answer("abyssal whip", roster.searchSources(), roster.log().entries(), ITEMS, NOW));
	}

	@Test
	public void matchesCaseInsensitivelyOnAnyPartOfTheName()
	{
		GroupRoster roster = new GroupRoster();
		roster.log().add(took(daysAgo(1), "Alex", items(WHIP, 1, SHARK, 5)));

		assertEquals(Collections.singletonList("Alex took 1 x Abyssal whip from storage (1d ago)"),
			FindCommand.answer("  WHIP ", roster.searchSources(), roster.log().entries(), ITEMS, NOW));
	}

	@Test
	public void historyIsNewestFirstMatchingOnlyAndLimited()
	{
		StorageLog log = new StorageLog();
		log.add(took(daysAgo(5), "Alex", items(SHARK, 1)));
		log.add(new StorageChange(daysAgo(4), "Sam", items(), items(SHARK, 20), items()));
		log.add(took(daysAgo(3), "Kim", items(COAL, 9)));
		log.add(took(daysAgo(2), "Alex", items(SHARK, 2, COAL, 1)));
		log.add(took(daysAgo(1), "Sam", items(SHARK, 3)));

		assertEquals(Arrays.asList(
			"Sam took 3 x Shark from storage (1d ago)",
			"Alex took 2 x Shark from storage (2d ago)",
			"Sam deposited 20 x Shark into storage (4d ago)"),
			GroupSearch.history("shark", log.entries(), ITEMS, NOW, 3));
		assertEquals(Collections.singletonList("Sam took 3 x Shark from storage (1d ago)"),
			GroupSearch.history("shark", log.entries(), ITEMS, NOW, 1));
	}

	@Test
	public void exactlyFiveLinesAreNotCut()
	{
		GroupRoster roster = new GroupRoster();
		roster.putBank("Alex", new BankSnapshot(daysAgo(1), items(PRAYER_POT_4, 10, PRAYER_POT_3, 2)));
		for (int i = 1; i <= 6; i++)
		{
			roster.log().add(took(daysAgo(i + 1), "Sam", items(PRAYER_POT_4, i)));
		}

		// 2 holder lines + HISTORY_LIMIT (3) history lines.
		List<String> out = FindCommand.answer("prayer", roster.searchSources(), roster.log().entries(), ITEMS, NOW);
		assertEquals(Arrays.asList(
			"Prayer potion(3): Alex bank 2 (1d ago)",
			"Prayer potion(4): Alex bank 10 (1d ago)",
			"Sam took 1 x Prayer potion(4) from storage (2d ago)",
			"Sam took 2 x Prayer potion(4) from storage (3d ago)",
			"Sam took 3 x Prayer potion(4) from storage (4d ago)"), out);
	}

	@Test
	public void moreThanFiveLinesAreCutAndPointAtThePanel()
	{
		// Unnamed ids read "item 90001".. so "item" matches all eight.
		Map<Integer, Integer> many = new TreeMap<>();
		for (int id = 1; id <= 8; id++)
		{
			many.put(90_000 + id, 1);
		}
		StorageLog log = new StorageLog();
		log.add(took(daysAgo(1), "Sam", items(90_001, 1)));

		List<String> out = FindCommand.answer("item",
			Collections.singletonList(new GroupSearch.Source("Alex", "bank", many, -1)), log.entries(), ITEMS, NOW);
		assertEquals(FindCommand.MAX_LINES + 1, out.size());
		assertEquals("item 90001: Alex bank 1", out.get(0));
		assertEquals("4 more, see the GIM Utilities panel", out.get(FindCommand.MAX_LINES));
	}

	@Test
	public void noMatchSaysSoAndNamesTheBlindSpots()
	{
		GroupRoster roster = new GroupRoster();
		roster.putBank("Alex", new BankSnapshot(daysAgo(1), items(SHARK, 1)));
		roster.log().add(took(daysAgo(1), "Alex", items(COAL, 1)));

		List<String> out = FindCommand.answer("dragon hunter wand", roster.searchSources(), roster.log().entries(),
			ITEMS, NOW);
		assertEquals(1, out.size());
		assertTrue(out.get(0).startsWith("Nothing found for 'dragon hunter wand'."));
		assertTrue(out.get(0).contains("Only members running GIM Utilities with sharing on are tracked"));
		assertTrue(out.get(0).contains("trades and drops between members are not"));
	}

	@Test
	public void theQueryIsEchoedWithoutChatTags()
	{
		List<String> out = FindCommand.answer("<col=ff0000>zz", Collections.<GroupSearch.Source>emptyList(),
			Collections.<StorageChange>emptyList(), ITEMS, NOW);
		assertTrue(out.get(0), out.get(0).startsWith("Nothing found for 'col=ff0000zz'."));
	}

	@Test
	public void aTooShortQueryAsksForMoreLetters()
	{
		GroupRoster roster = new GroupRoster();
		roster.putBank("Alex", new BankSnapshot(daysAgo(1), items(SHARK, 1)));
		roster.log().add(took(daysAgo(1), "Alex", items(SHARK, 1)));
		for (String q : Arrays.asList("s", " ", "", null))
		{
			assertEquals(Collections.singletonList(
				"Type at least 2 letters of an item name, e.g. ::find dragon hunter wand"),
				FindCommand.answer(q, roster.searchSources(), roster.log().entries(), ITEMS, NOW));
		}
		assertTrue(GroupSearch.history("s", roster.log().entries(), ITEMS, NOW, 3).isEmpty());
	}

	@Test
	public void theStorageLogSurvivesARestartStillCappedAt200()
	{
		GroupRoster before = new GroupRoster();
		for (int i = 0; i < StorageLog.MAX_ENTRIES + 25; i++)
		{
			before.log().add(took(daysAgo(30) +TimeUnit.MINUTES.toMillis(i), "Alex", items(SHARK, 1)));
		}
		before.log().add(took(daysAgo(3), "Alex", items(WHIP, 1)));
		assertEquals(StorageLog.MAX_ENTRIES, before.log().entries().size());

		GroupRoster after = new GroupRoster();
		assertTrue(GroupCache.read(GSON, GroupCache.write(GSON, before), after));
		assertEquals(StorageLog.MAX_ENTRIES, after.log().entries().size());
		assertEquals(Collections.singletonList("Alex took 1 x Abyssal whip from storage (3d ago)"),
			FindCommand.answer("whip", after.searchSources(), after.log().entries(), ITEMS, NOW));
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Online and world for every group member, from the game's own Ironman Group channel (Board 2026-11-11): members
 * in the channel are online on their world, roster members not in it are offline, and nothing is known before
 * the channel loads. The Friends list is the fallback.
 */
public class GamePresenceTest
{
	static final GroupMembers ROSTER = GroupMembers.of("Iron Pals",
		Arrays.asList("GroupOtt", "GroupArk", "GroupPNK", "GroupTrashy", "GroupShip"));

	static Map<String, Integer> worlds(Object... nameWorld)
	{
		Map<String, Integer> out = new LinkedHashMap<>();
		for (int i = 0; i < nameWorld.length; i += 2)
		{
			out.put((String) nameWorld[i], (Integer) nameWorld[i + 1]);
		}
		return out;
	}

	/** The screenshot: GroupOtt on W615 and GroupShip on W303, the other three '---'. */
	static GamePresence twoOfFive()
	{
		return GamePresence.read(ROSTER, worlds("GroupOtt", 615, "GroupShip", 303), null);
	}

	@Test
	public void channelMembersAreOnlineAndTheRestOfTheRosterOffline()
	{
		GamePresence game = twoOfFive();
		assertTrue(game.known());
		assertEquals(GamePresence.Source.CHANNEL, game.source());
		assertEquals(GamePresence.State.ONLINE, game.state("GroupOtt"));
		assertEquals(615, game.world("GroupOtt"));
		assertEquals(GamePresence.State.ONLINE, game.state("groupship"));
		assertEquals(303, game.world("GroupShip"));
		for (String off : Arrays.asList("GroupArk", "GroupPNK", "GroupTrashy"))
		{
			assertEquals(off, GamePresence.State.OFFLINE, game.state(off));
			assertEquals(0, game.world(off));
		}
		assertEquals(GamePresence.State.UNKNOWN, game.state("Stranger"));
		assertEquals(worlds("GroupOtt", 615, "GroupShip", 303), game.online());
	}

	@Test
	public void beforeTheChannelLoadsNothingIsKnown()
	{
		GamePresence game = GamePresence.read(ROSTER, null, null);
		assertFalse(game.known());
		assertEquals(GamePresence.State.UNKNOWN, game.state("GroupOtt"));
		assertTrue(game.online().isEmpty());
		assertFalse(GamePresence.UNKNOWN.known());
	}

	@Test
	public void theFriendsListIsTheFallbackOnlyWithoutTheChannel()
	{
		Map<String, Integer> friends = worlds("GroupOtt", 615, "GroupArk", 0, "Someone Else", 420);
		GamePresence game = GamePresence.read(ROSTER, null, friends);
		assertEquals(GamePresence.Source.FRIENDS, game.source());
		assertEquals(GamePresence.State.ONLINE, game.state("GroupOtt"));
		assertEquals(615, game.world("GroupOtt"));
		assertEquals(GamePresence.State.OFFLINE, game.state("GroupArk"));
		// Not a friend: the list says nothing about them.
		assertEquals(GamePresence.State.UNKNOWN, game.state("GroupPNK"));
		// A friend outside the group is never listed.
		assertEquals(GamePresence.State.UNKNOWN, game.state("Someone Else"));
		assertEquals(worlds("GroupOtt", 615), game.online());

		assertEquals(GamePresence.Source.CHANNEL, GamePresence.read(ROSTER, worlds("GroupShip", 303), friends).source());
		// Without the roster, friends cannot tell who is in the group.
		assertFalse(GamePresence.read(GroupMembers.UNKNOWN, null, friends).known());
	}

	@Test
	public void theChannelWithoutTheRosterSpeaksOnlyForWhoIsInIt()
	{
		GamePresence game = GamePresence.read(GroupMembers.UNKNOWN, worlds("GroupOtt", 615), null);
		assertEquals(GamePresence.State.ONLINE, game.state("GroupOtt"));
		assertEquals(GamePresence.State.UNKNOWN, game.state("GroupArk"));
	}

	@Test
	public void namesMatchTheWayTheGameSpellsThem()
	{
		GamePresence game = GamePresence.read(GroupMembers.of("g", Collections.singletonList("Iron Pal")),
			worlds("Iron Pal", 302), null);
		assertEquals(GamePresence.State.ONLINE, game.state("iron_pal"));
		assertEquals(worlds("Iron Pal", 302), game.online());
	}

	@Test
	public void othersOnlineJoinsThePluginAndTheGameWithoutYou()
	{
		Map<String, MemberStats> plugin = new LinkedHashMap<>();
		plugin.put("GroupShip", new MemberStats(Collections.emptyMap(), 100, 100, 300, 0));
		plugin.put("GroupArk", new MemberStats(Collections.emptyMap(), 100, 100, 330, 0));
		Map<String, Integer> others = GamePresence.othersOnline(plugin, twoOfFive(), "GroupShip");
		// GroupOtt from the game; GroupArk's client went quiet but the game says offline; you are left out.
		assertEquals(worlds("GroupOtt", 615), others);

		Map<String, Integer> unknown = GamePresence.othersOnline(plugin, GamePresence.UNKNOWN, "GroupShip");
		assertEquals(worlds("GroupArk", 330), unknown);
	}
}

