 * The headless stand-in for GIM Utilities' event handlers. {@code GroupService} and {@code GroupEventEngine} need
 * a live {@code Client} (local player, clan channel, party), so a JUnit run cannot start them. This rig subscribes
 * to the same events on a real {@code EventBus} and hands them to the same classes those handlers call
 * ({@link StorageSession}, {@link ProgressTracker}, {@link LevelPosts}, {@link EventRouter}, {@link ChannelPosts},
 * {@link GovernanceSync}), with a fake Discord transport and a scenario clock. Only the few lines of glue are its
 * own; everything a probe reports is the plugin's code.
 *
 * <p>Not covered here: DiscordBatch's merging of a moment's events, screenshots, and anything read from the
 * client (worlds, regions, kill counts). Those stay in their own unit tests and the in-game checklist.
 */
final class GimScenarioRig
{
	static final String WEBHOOK = "https://discord.com/api/webhooks/1/scenario";
	static final String GROUP = "Iron Pals";
	static final int GRACE_MINUTES = 2;
	private static final long LEVEL_WINDOW = TimeUnit.MINUTES.toMillis(30);
	private static final GroupIronmanConfig DEFAULTS = new GroupIronmanConfig()
	{
	};

	/** The clock every component reads; waits in a scenario move it. */
	long now = 1_700_000_000_000L;
	final String self;
	private final Gson gson = new Gson();
	private final FakeItems items = new FakeItems();
	private final EventSettings settings = new EventSettings(EventFixtures.all(), EventFixtures.all(), 1_000_000,
		1_000_000, 1, 7, false);

	private final StorageSession storage = new StorageSession();
	private final GroupRoster roster = new GroupRoster();
	private final ProgressTracker progress = new ProgressTracker(Skill.values().length - 1);
	private final List<DiscordQueue.Post> sent = new ArrayList<>();
	private final List<DiscordSender.Done> unanswered = new ArrayList<>();
	private final DiscordSender sender = new DiscordSender((post, done) ->
	{
		sent.add(post);
		unanswered.add(done);
	}, () -> now, () -> 12);
	private final LevelPosts levels = new LevelPosts(sender, gson, () -> now, () -> DiscordStyle.EMBED,
		() -> DiscordWebhook.USERNAME);
	private final List<String> overlay = new ArrayList<>();
	private final EventRouter router = new EventRouter(this::toDiscord, e -> overlay.add(EventText.sentence(e, items)));
	private final ChannelPosts channel = new ChannelPosts(ZoneOffset.UTC);
	private final Map<String, GovernanceClient> members = new HashMap<>();
	private final GovernanceClient me;
	private final List<String> saves = new ArrayList<>();
	private int messageIds;

	GimScenarioRig(String self)
	{
		this.self = self;
		this.me = new GovernanceClient(self, gson);
	}

	/** What a scenario's {@code expect} entries can check. */
	Probes probes()
	{
		return new Probes()
			.add("discord", this::discordLines)
			.add("overlay", () -> overlay)
			.add("storage.log", this::storageLog)
			.add("settings", this::settingsLines)
			.add("settings.saves", () -> saves);
	}

	// Group storage, as GroupService.onWidgetLoaded / onItemContainerChanged / onWidgetClosed.

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded e)
	{
		if (e.getGroupId() == InterfaceID.SHARED_BANK)
		{
			storage.open();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		if (e.getContainerId() == InventoryID.INV_GROUP_TEMP)
		{
			commit(storage.contents(now, self, counts(e.getItemContainer())));
		}
	}

	/**
	 * The scenarios' close stands for a close the game saves ("Saving..." shown, which GroupService
	 * commits on): the save is committed, then the window closes. A discarded visit is the service's
	 * own unit tests' job, not this rig's.
	 */
	@Subscribe
	public void onWidgetClosed(WidgetClosed e)
	{
		if (e.getGroupId() == InterfaceID.SHARED_BANK)
		{
			commit(storage.save(now, self));
			storage.close(now);
		}
	}

	private void commit(StorageChange change)
	{
		if (change != null)
		{
			roster.putStorage(change);
		}
	}

	private static Map<Integer, Integer> counts(ItemContainer container)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		for (Item item : container.getItems())
		{
			ItemCounts.add(out, item.getId(), item.getQuantity(), id -> id);
		}
		return out;
	}

	private List<String> storageLog()
	{
		List<String> out = new ArrayList<>();
		for (PanelModel.LogRow row : PanelModel.storage(roster, items, self, null, now).log)
		{
			out.add(row.text);
		}
		return out;
	}

	// Progress, as GroupEventEngine.onStatChanged and its level post.

	@Subscribe
	public void onStatChanged(StatChanged e)
	{
		if (e.getSkill() == Skill.OVERALL)
		{
			return;
		}
		for (GroupEvent event : progress.skill(e.getSkill().getName(), e.getLevel(), e.getXp(), now, self))
		{
			if (event.type == GroupEvent.Type.LEVEL_UP)
			{
				String json = DiscordWebhook.payload(gson, DiscordMerge.single(event, items), items,
					DiscordStyle.EMBED, "", false, null, DiscordWebhook.USERNAME);
				levels.level(WEBHOOK, event, LEVEL_WINDOW, null, json);
				overlay.add(EventText.sentence(event, items));
			}
			else
			{
				router.route(event, true, settings, items);
			}
		}
	}

	// A detected event of this player's own (a drop, a death), as GroupEventEngine.own routes it.

	@Subscribe
	public void onGroupEvent(GroupEvent e)
	{
		if (e.isValid())
		{
			router.route(e, self.equals(e.member), settings, items);
		}
	}

	private void toDiscord(GroupEvent e)
	{
		sender.post(WEBHOOK, DiscordWebhook.payload(gson, e, items, DiscordStyle.EMBED, "", false), null);
	}

	// Members' presence from the game's Group channel, as GroupEventEngine feeds ChannelPosts.

	/** The Group channel as the game shows it now; {@code plugin}: members whose own client posts for them. */
	static final class Channel
	{
		final Map<String, Integer> online;
		final Set<String> plugin;
		final List<String> roster;

		Channel(Map<String, Integer> online, Set<String> plugin, List<String> roster)
		{
			this.online = online;
			this.plugin = plugin;
			this.roster = roster;
		}
	}

	@Subscribe
	public void onChannel(Channel c)
	{
		GroupMembers group = GroupMembers.of(GROUP, c.roster);
		GamePresence game = GamePresence.read(group, c.online, null);
		for (GroupEvent e : channel.update(game, name -> c.plugin.contains(name), now, GRACE_MINUTES))
		{
			router.route(e, true, settings, items);
		}
	}

	// Group settings saved by another member and received over the party, as GovernanceSync does.

	static final class SettingsSave
	{
		final String member;
		final Map<String, Long> values;

		SettingsSave(String member, Map<String, Long> values)
		{
			this.member = member;
			this.values = values;
		}
	}

	@Subscribe
	public void onSettingsSave(SettingsSave s)
	{
		GovernanceClient them = members.computeIfAbsent(s.member, name ->
		{
			GovernanceClient c = new GovernanceClient(name, gson);
			// Joining the party: each announces itself to the other.
			c.tick(me);
			me.tick(c);
			c.sync.claim(name, now);
			return c;
		});
		Map<String, Long> values = GroupSettingsSchema.seed(DEFAULTS);
		values.putAll(s.values);
		saves.add(s.member + ": " + them.sync.save(s.member, values, now));
		them.tick(me);
	}

	private List<String> settingsLines()
	{
		GroupSettings got = me.sync.governance().settings();
		if (got == null)
		{
			return Collections.emptyList();
		}
		GroupSettingsSchema.Resolved resolved = new GroupSettingsSchema.Resolved(DEFAULTS, got);
		List<String> out = new ArrayList<>();
		for (GroupSettingsSchema.Setting s : GroupSettingsSchema.ALL)
		{
			out.add(s.key + "=" + resolved.value(s.key));
		}
		return out;
	}

	// The engine's once-a-second timer, run on each tick and when the scenario ends.

	@Subscribe
	public void onGameTick(GameTick t)
	{
		for (GroupEvent e : channel.poll(now, GRACE_MINUTES))
		{
			router.route(e, true, settings, items);
		}
		settle();
	}

	/** Sends what is owed and answers each request as Discord would, until nothing is left. */
	void settle()
	{
		for (int i = 0; i < 20; i++)
		{
			levels.tick();
			sender.pump();
			if (unanswered.isEmpty())
			{
				return;
			}
			List<DiscordSender.Done> answering = new ArrayList<>(unanswered);
			unanswered.clear();
			for (DiscordSender.Done done : answering)
			{
				done.done(200, null, "m" + (++messageIds));
			}
		}
	}

	/** "post: Alex: Level up | Prayer level 24", one line per request in order; an edit says "edit". */
	private List<String> discordLines()
	{
		List<String> out = new ArrayList<>();
		for (DiscordQueue.Post post : sent)
		{
			out.add((post.edit == null ? "post: " : "edit: ") + words(post.json));
		}
		return out;
	}

	private String words(String json)
	{
		JsonObject o = gson.fromJson(json, JsonObject.class);
		if (o.has("embeds") && o.getAsJsonArray("embeds").size() > 0)
		{
			JsonObject embed = o.getAsJsonArray("embeds").get(0).getAsJsonObject();
			String title = embed.has("title") ? embed.get("title").getAsString() : "";
			String description = embed.has("description") ? embed.get("description").getAsString() : "";
			return title + " | " + description;
		}
		return o.has("content") ? o.get("content").getAsString() : json;
	}
}

package com.vinnyvangogh.groupironman;

import com.vinnyvangogh.scenarios.EventKinds;
import com.vinnyvangogh.scenarios.Expectations;
import com.vinnyvangogh.scenarios.Scenario;
import com.vinnyvangogh.scenarios.ScenarioParser;
import com.vinnyvangogh.scenarios.ScenarioRun;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import net.runelite.client.eventbus.EventBus;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Every scenario in {@code src/test/resources/scenarios}, headless: its steps posted on a real RuneLite
 * {@link EventBus} to {@link GimScenarioRig}, then its {@code expect} entries checked. A new scenario file is run
 * here with no change to this class.
 */
@RunWith(Parameterized.class)
public class GimScenariosTest
{
	private static final EventKinds KINDS = GimEventKinds.kinds();

	@Parameterized.Parameters(name = "{0}")
	public static Collection<Object[]> scenarios()
	{
		List<Object[]> out = new ArrayList<>();
		for (Scenario s : ScenarioParser.loadAll(ScenarioParser.DEFAULT_DIR, KINDS))
		{
			out.add(new Object[]{s.source, s});
		}
		return out;
	}

	private final Scenario scenario;

	public GimScenariosTest(String file, Scenario scenario)
	{
		this.scenario = scenario;
	}

	@Test
	public void theRigDoesWhatTheScenarioExpects()
	{
		GimScenarioRig rig = new GimScenarioRig("GroupShip");
		// The bus logs and swallows a subscriber's exception; here it fails the scenario instead.
		List<Throwable> thrown = new ArrayList<>();
		EventBus bus = new EventBus(thrown::add);
		bus.register(rig);
		new ScenarioRun(scenario, KINDS, bus::post).runAll(ms -> rig.now += ms);
		rig.settle();
		List<String> failures = new ArrayList<>();
		thrown.forEach(t -> failures.add("a subscriber threw " + t));
		failures.addAll(Expectations.check(scenario, rig.probes()));
		assertTrue(scenario.name + ":\n  " + String.join("\n  ", failures), failures.isEmpty());
	}

	@Test
	public void everyScenarioSaysWhatItChecks()
	{
		assertTrue(scenario.source + " has no expect entries", !scenario.expect.isEmpty());
		assertTrue(scenario.source + " has no description", scenario.description != null);
		assertEquals("files are named NN-words.json", true, scenario.source.matches("\\d\\d-[a-z0-9-]+\\.json"));
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertTrue;

/**
 * One simulated client for the governance tests: its config store, its group cache file, what it sent, and its
 * sync. {@link #tick} hands what it sent to the others, as the party would.
 */
class GovernanceClient
{
	static final String GROUP = "GroupShip";

	final String name;
	final Map<String, String> config = new HashMap<>();
	final List<String> outbox = new ArrayList<>();
	/** The webhooks document as the group cache file keeps it. */
	String cache;
	GovernanceSync sync;
	private final Gson gson;

	GovernanceClient(String name, Gson gson)
	{
		this.name = name;
		this.gson = gson;
		start();
	}

	/** Starting the plugin: the config is read at once, the cache file a moment later. */
	void start()
	{
		sync = new GovernanceSync(gson, new GovernanceSync.Store()
		{
			@Override
			public String get(String key)
			{
				return config.get(key);
			}

			@Override
			public void set(String key, String value)
			{
				if (value == null)
				{
					config.remove(key);
				}
				else
				{
					config.put(key, value);
				}
			}
		}, outbox::add, () ->
		{
		}, json -> cache = json);
		sync.group(GROUP);
		if (cache != null)
		{
			sync.restoreWebhooks(cache);
		}
	}

	/** A game tick while connected: whatever is marked goes to {@code others}. */
	void tick(GovernanceClient... others)
	{
		tick(MemberPrefs.NONE, others);
	}

	/** As {@link #tick(GovernanceClient...)}, with this member's own opt-outs as they are now. */
	void tick(MemberPrefs prefs, GovernanceClient... others)
	{
		sync.flush(prefs);
		for (String payload : outbox)
		{
			assertTrue(GovernanceSync.isGovernance(payload));
			for (GovernanceClient o : others)
			{
				o.sync.receive(name, payload);
			}
		}
		outbox.clear();
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.util.Map;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Two simulated clients, each with its own config store, joined by a fake party. */
public class GovernanceSyncTest
{
	private static final GroupIronmanConfig DEFAULTS = new GroupIronmanConfig()
	{
	};

	/** One client: its config, what it sent, and its sync ({@link GovernanceClient}). */
	private final class Client extends GovernanceClient
	{
		Client(String name)
		{
			super(name, new Gson());
		}
	}

	private static Map<String, Long> levelMin(long level)
	{
		Map<String, Long> v = GroupSettingsSchema.seed(DEFAULTS);
		v.put("eventLevelMin", level);
		return v;
	}

	@Test
	public void aLeadersChangeReachesTheSecondMember()
	{
		Client alex = new Client("Alex");
		Client sam = new Client("Sam");
		alex.tick(sam);
		sam.tick(alex);

		assertTrue(alex.sync.claim("Alex", NOW));
		assertEquals(GovernanceSync.SaveResult.SAVED, alex.sync.save("Alex", levelMin(70), NOW + 1));
		assertEquals("Sam is not an editor", GovernanceSync.SaveResult.NOT_EDITOR,
			sam.sync.save("Sam", levelMin(5), NOW + 1));
		alex.tick(sam);

		GroupSettings got = sam.sync.governance().settings();
		assertNotNull(got);
		assertEquals(70, new GroupSettingsSchema.Resolved(DEFAULTS, got).value("eventLevelMin"));
		assertTrue("kept for Sam's next session", sam.config.containsKey(GovernanceSync.KEY_SETTINGS));
	}

	@Test
	public void anOfflineMemberPicksUpTheLatestWhenTheyJoin()
	{
		Client alex = new Client("Alex");
		Client sam = new Client("Sam");
		alex.tick(sam);
		sam.tick(alex);
		alex.sync.claim("Alex", NOW);
		alex.sync.save("Alex", levelMin(70), NOW + 1);
		alex.tick();
		alex.sync.save("Alex", levelMin(80), NOW + 2);
		alex.tick();
		assertNull("Sam was offline for both", sam.sync.governance().settings());

		// Sam joins: his UserSync makes Alex resend everything.
		alex.sync.resendAll();
		alex.tick(sam);
		assertEquals(2, sam.sync.governance().settings().version);
	}

	@Test
	public void rolesSettingsAndKeyPairSurviveARestart()
	{
		Client alex = new Client("Alex");
		alex.sync.claim("Alex", NOW);
		alex.sync.save("Alex", levelMin(70), NOW + 1);
		String key = alex.sync.governance().publicKey();
		alex.start();
		assertEquals(key, alex.sync.governance().publicKey());
		assertEquals(GroupGovernance.Role.LEADER, alex.sync.governance().myRole("Alex"));
		assertEquals(1, alex.sync.governance().settings().version);
	}

	@Test
	public void nothingSentCarriesAWebhookUnlessTheLeaderSharesNorEverThePrivateKey()
	{
		Client alex = new Client("Alex");
		alex.sync.claim("Alex", NOW);
		alex.sync.save("Alex", levelMin(70), NOW + 1);
		alex.sync.flush(MemberPrefs.NONE);
		String privateHalf = alex.config.get(GovernanceSync.KEY_IDENTITY).split("\\.")[1];
		for (String payload : alex.outbox)
		{
			assertFalse(payload.contains(privateHalf));
			assertFalse(payload.toLowerCase(java.util.Locale.ROOT).contains("webhook"));
		}
		assertEquals("announce, roles, settings", 3, alex.outbox.size());
		alex.outbox.clear();

		// Turning sharing off without ever having shared sends nothing either.
		assertTrue(alex.sync.shareWebhooks("Alex", false, Webhooks.of(DEFAULTS), NOW + 2));
		alex.sync.flush(MemberPrefs.NONE);
		assertTrue(alex.outbox.isEmpty());

		// The leader's "Share webhooks with the group": now, and only now, one document carries them.
		java.util.Map<Webhook, Webhooks.Setting> hooks = new java.util.EnumMap<>(Webhook.class);
		hooks.put(Webhook.MAIN, new Webhooks.Setting("https://discord.com/api/webhooks/1/SHAREDTOKEN",
			DiscordPosterName.WEBHOOK, ""));
		assertTrue(alex.sync.shareWebhooks("Alex", true, new Webhooks(hooks), NOW + 3));
		alex.sync.flush(MemberPrefs.NONE);
		assertEquals(1, alex.outbox.size());
		assertTrue(alex.outbox.get(0).contains("SHAREDTOKEN"));
		assertFalse(alex.outbox.get(0).contains(privateHalf));
		assertFalse("never in the leader's config either", alex.config.values().toString().contains("SHAREDTOKEN"));
	}

	private static Map<String, Long> current(Client c)
	{
		GroupSettingsSchema.Resolved r = new GroupSettingsSchema.Resolved(DEFAULTS, c.sync.governance().settings());
		Map<String, Long> out = new java.util.TreeMap<>();
		for (GroupSettingsSchema.Setting s : GroupSettingsSchema.ALL)
		{
			out.put(s.key, r.value(s.key));
		}
		return out;
	}

	/** One redraw of {@code c}'s Settings tab. */
	private static void redraw(SettingsDraft draft, Client c)
	{
		GroupGovernance g = c.sync.governance();
		draft.update(g.myRole(c.name), g.roles(), g.settings(), current(c));
	}

	/** Board 2026-11-13: Sam had the Settings tab open and Alex's Save did not take. */
	@Test
	public void theLeadersSaveTakesWhileAnotherMemberHasTheTabOpen()
	{
		Client alex = new Client("Alex");
		Client sam = new Client("Sam");
		alex.tick(sam);
		sam.tick(alex);
		alex.sync.claim("Alex", NOW);
		alex.sync.save("Alex", levelMin(50), NOW + 1);
		alex.tick(sam);

		SettingsDraft alexTab = new SettingsDraft();
		SettingsDraft samTab = new SettingsDraft();
		redraw(alexTab, alex);
		redraw(samTab, sam);
		alexTab.put("eventLevelMin", 70);

		// Sam, on his Settings tab, turns off posting his events; his client announces it.
		MemberPrefs out = new MemberPrefs(true, java.util.EnumSet.noneOf(GroupEvent.Type.class),
			java.util.EnumSet.noneOf(GroupEvent.Type.class));
		sam.sync.prefs(out);
		sam.tick(out, alex);
		// He rejoins the party too: everyone resends.
		alex.sync.resendAll();
		alex.tick(sam);
		sam.sync.resendAll();
		sam.tick(out, alex);
		redraw(alexTab, alex);
		redraw(samTab, sam);

		assertEquals(GovernanceSync.SaveResult.SAVED, alex.sync.save("Alex", alexTab.values(), NOW + 2));
		alexTab.saved();
		alex.tick(sam);
		redraw(alexTab, alex);
		redraw(samTab, sam);

		assertEquals(2, sam.sync.governance().settings().version);
		assertEquals(70L, (long) sam.sync.governance().settings().values.get("eventLevelMin"));
		assertEquals("Sam's tab shows what Alex saved", 70L, (long) samTab.values().get("eventLevelMin"));
		assertNull(alexTab.notice());
	}

	@Test
	public void saveSaysWhyItDidNotTake()
	{
		Client alex = new Client("Alex");
		Client sam = new Client("Sam");
		alex.tick(sam);
		sam.tick(alex);
		alex.sync.claim("Alex", NOW);
		alex.sync.setEditor("Alex", "Sam", true, NOW + 1);
		alex.tick(sam);
		assertEquals(GovernanceSync.SaveResult.SAVED, sam.sync.save("Sam", levelMin(60), NOW + 2));
		assertEquals(GovernanceSync.SaveResult.UNCHANGED, sam.sync.save("Sam", levelMin(60), NOW + 3));
		sam.tick(alex);

		alex.sync.setEditor("Alex", "Sam", false, NOW + 4);
		alex.tick(sam);
		assertEquals(GovernanceSync.SaveResult.NOT_EDITOR, sam.sync.save("Sam", levelMin(70), NOW + 5));
		assertEquals("Not saved: you are no longer leader or editor.",
			GroupSettingsTab.saveNote(GovernanceSync.SaveResult.NOT_EDITOR));
	}

	@Test
	public void everySaveResultHasItsOwnNote()
	{
		java.util.Set<String> notes = new java.util.HashSet<>();
		for (GovernanceSync.SaveResult r : GovernanceSync.SaveResult.values())
		{
			assertTrue(r + " has a note", notes.add(GroupSettingsTab.saveNote(r)));
		}
	}

	@Test
	public void anUnchangedAnnounceIsNotResent()
	{
		Client alex = new Client("Alex");
		alex.sync.flush(MemberPrefs.NONE);
		alex.outbox.clear();
		alex.sync.prefs(MemberPrefs.NONE);
		alex.sync.flush(MemberPrefs.NONE);
		assertTrue(alex.outbox.isEmpty());
		MemberPrefs out = new MemberPrefs(true, java.util.EnumSet.noneOf(GroupEvent.Type.class),
			java.util.EnumSet.noneOf(GroupEvent.Type.class));
		alex.sync.prefs(out);
		alex.sync.flush(out);
		assertEquals(1, alex.outbox.size());
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import org.junit.Before;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The gravestone warning's picture (Board 2026-11-10: it showed where the player stood at the warning, not where
 * they died). Wired the way GroupEventEngine wires it: the grave's frame is chosen when the warning is emitted,
 * then freed once the grave is no longer out.
 */
public class GraveShotTest
{
	private static final byte[] DEATH_FRAME = {1, 2, 3};
	private static final int WARN = 5;

	private final List<GroupEvent> out = new ArrayList<>();
	private final List<GraveShot.Choice> posted = new ArrayList<>();
	private GraveShot shot;
	private EventWatchers watchers;
	private GraveScreenshot mode = GraveScreenshot.DEATH;
	private boolean screenshots = true;

	@Before
	public void setUp()
	{
		shot = new GraveShot();
		watchers = new EventWatchers(e ->
		{
			out.add(e);
			if (e.type == GroupEvent.Type.GRAVESTONE_EXPIRING)
			{
				posted.add(shot.choose(mode, screenshots));
			}
		}, t -> true);
	}

	/** onActorDeath, then the death post's frame arriving from the encoder. */
	private void dieWithFrame(byte[] frame)
	{
		watchers.died(EventFixtures.items(FakeItems.WHIP, 1), "Lumbridge", 302);
		int grave = shot.died();
		assertTrue(shot.ask(grave));
		shot.keep(grave, frame);
	}

	/** The engine's watch(): a grave tick, then the frame goes once the grave is no longer out. */
	private void tick(int visible)
	{
		watchers.graveTick(visible, WARN, NOW, "Alex");
		if (!watchers.graveOut())
		{
			shot.free();
		}
	}

	private void runToWarning()
	{
		int warnAt = EventWatchers.GRAVE_TICKS - WARN * EventWatchers.TICKS_PER_MINUTE;
		for (int i = 0; i < warnAt; i++)
		{
			tick(1);
		}
		assertEquals(1, posted.size());
	}

	@Test
	public void theWarningUsesTheDeathFrame()
	{
		dieWithFrame(DEATH_FRAME);
		runToWarning();
		GraveShot.Choice c = posted.get(0);
		assertTrue(c.picture);
		assertArrayEquals(DEATH_FRAME, c.png);
	}

	@Test
	public void theFrameIsFreedOnceTheWarningIsPosted()
	{
		dieWithFrame(DEATH_FRAME);
		assertTrue(shot.holding());
		runToWarning();
		assertFalse(shot.holding());
	}

	@Test
	public void theFrameIsFreedWhenTheGraveIsLooted()
	{
		dieWithFrame(DEATH_FRAME);
		tick(1);
		assertTrue(shot.holding());
		tick(0);
		assertFalse(shot.holding());
		for (int i = 0; i < EventWatchers.GRAVE_TICKS; i++)
		{
			tick(0);
		}
		assertTrue("a looted grave never warns", posted.isEmpty());
	}

	@Test
	public void aDeathWithNothingLostPostsNoWarningAndFreesTheFrame()
	{
		// Board 2026-11-10: no gravestone, no "Gravestone expiring" post (Discord or overlay share this event).
		dieWithFrame(DEATH_FRAME);
		FakeItems items = new FakeItems();
		for (int i = 0; i < EventWatchers.DEATH_SETTLE_TICKS; i++)
		{
			watchers.deathTick(EventFixtures.items(FakeItems.WHIP, 1), items, NOW, "Alex");
		}
		tick(1);
		assertFalse("the death's frame is freed with no grave to hold it for", shot.holding());
		for (int i = 0; i < EventWatchers.GRAVE_TICKS; i++)
		{
			tick(1);
		}
		assertTrue(posted.isEmpty());
		assertTrue(out.stream().noneMatch(e -> e.type == GroupEvent.Type.GRAVESTONE_EXPIRING));
	}

	@Test
	public void afterARestartTheWarningHasNoPicture()
	{
		// A restart is a new GraveShot with nothing in it; the grave itself was known (a fresh death).
		watchers.died(EventFixtures.items(FakeItems.WHIP, 1), "Lumbridge", 302);
		shot.died();
		runToWarning();
		assertFalse(posted.get(0).picture);
		assertNull(posted.get(0).png);
	}

	@Test
	public void currentViewTakesTheNextFrame()
	{
		mode = GraveScreenshot.CURRENT;
		dieWithFrame(DEATH_FRAME);
		runToWarning();
		assertSame(GraveShot.Choice.NEXT_FRAME, posted.get(0));
		assertNull(posted.get(0).png);
	}

	@Test
	public void noneAttachesNothing()
	{
		mode = GraveScreenshot.NONE;
		dieWithFrame(DEATH_FRAME);
		runToWarning();
		assertFalse(posted.get(0).picture);
	}

	@Test
	public void screenshotsOffAttachesNothingWhateverTheSetting()
	{
		screenshots = false;
		for (GraveScreenshot m : GraveScreenshot.values())
		{
			assertFalse(m.name(), shot.choose(m, false).picture);
		}
		dieWithFrame(DEATH_FRAME);
		runToWarning();
		assertFalse(posted.get(0).picture);
	}

	@Test
	public void aLateFrameFromAnOlderGraveIsDropped()
	{
		int first = shot.died();
		shot.ask(first);
		int second = shot.died();
		shot.keep(first, DEATH_FRAME);
		assertFalse("the old grave's frame is not kept for the new one", shot.holding());
		shot.keep(second, DEATH_FRAME);
		assertTrue(shot.holding());
	}

	@Test
	public void aFrameAfterTheGraveIsGoneIsDropped()
	{
		int grave = shot.died();
		shot.free();
		shot.keep(grave, DEATH_FRAME);
		assertFalse(shot.holding());
		assertFalse("no grave, nothing to ask for", shot.ask(0));
	}

	@Test
	public void theFrameIsAskedForOncePerGrave()
	{
		int grave = shot.died();
		assertTrue(shot.ask(grave));
		assertFalse("the death value's later moment does not replace the death's frame", shot.ask(grave));
		assertTrue(shot.ask(shot.died()));
	}

	@Test
	public void theWarningListsTheTopItemsTheDeathLeft()
	{
		FakeItems items = new FakeItems();
		watchers.died(EventFixtures.items(FakeItems.WHIP, 1, FakeItems.SHARK, 10, FakeItems.COINS, 13_280,
			FakeItems.LOBSTER, 3, FakeItems.TROUT, 1), "Lumbridge", 302);
		shot.died();
		for (int i = 0; i < EventWatchers.DEATH_SETTLE_TICKS; i++)
		{
			watchers.deathTick(EventFixtures.items(), items, NOW, "Alex");
		}
		runToWarning();
		GroupEvent warning = out.get(out.size() - 1);
		assertEquals(GroupEvent.Type.GRAVESTONE_EXPIRING, warning.type);
		assertEquals(5, warning.items.size());
		assertEquals("gravestone at Lumbridge on world 302 has about 5 min left; in it: 1 x Abyssal whip,"
			+ " 13.2K x Coins, 10 x Shark and 2 more (1.52M gp)", EventText.describe(warning, items));
	}

	@Test
	public void aWarningWithoutACountedDeathListsNothing()
	{
		watchers.died(EventFixtures.items(FakeItems.WHIP, 1), "Lumbridge", 302);
		runToWarning();
		assertEquals("gravestone at Lumbridge on world 302 has about 5 min left",
			EventText.describe(out.get(0), new FakeItems()));
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Board 2026-11-15: an account not in the group the client is set up for gets nothing done for it. */
public class GroupBindingTest
{
	private static final GroupMembers OURS = GroupMembers.of("Iron Crew", Arrays.asList("Vinny", "Bea", "Cal"));
	private static final GroupMembers THEIRS = GroupMembers.of("Wreckers", Arrays.asList("Ship Wrek", "Mate"));
	private static final List<String> HEARD = Arrays.asList("Vinny", "Bea", "Cal");

	@Test
	public void anAccountInAnotherGroupIsNotAMember()
	{
		GroupBinding.Result r = GroupBinding.check("iron crew", THEIRS, "Ship Wrek", "", HEARD);
		assertEquals(GroupBinding.Verdict.NOT_MEMBER, r.verdict);
		assertFalse(r.member());
		assertNull(r.bind);
	}

	@Test
	public void anAccountWithNoGroupWaitsForeverAndIsNeverAMember()
	{
		GroupBinding.Result r = GroupBinding.check("iron crew", GroupMembers.UNKNOWN, "Ship Wrek", "", HEARD);
		assertEquals(GroupBinding.Verdict.WAIT, r.verdict);
		assertFalse(r.member());
	}

	@Test
	public void aMemberOfTheBoundGroupIsAMember()
	{
		GroupBinding.Result r = GroupBinding.check("Iron Crew", OURS, "bea", "", HEARD);
		assertTrue(r.member());
		assertNull(r.bind);
	}

	@Test
	public void nameNotOnItsOwnRosterIsNotAMember()
	{
		assertFalse(GroupBinding.check("iron crew", OURS, "Ship Wrek", "", HEARD).member());
	}

	@Test
	public void noNameYetWaits()
	{
		assertEquals(GroupBinding.Verdict.WAIT, GroupBinding.check("iron crew", OURS, "", "", HEARD).verdict);
	}

	@Test
	public void firstLoginOnAFreshClientBindsItsGroup()
	{
		GroupBinding.Result r = GroupBinding.check("", OURS, "Vinny", "", Collections.emptyList());
		assertTrue(r.member());
		assertEquals("iron crew", r.bind);
	}

	@Test
	public void savedRolesDecideTheFirstBindingNotTheAccountLoggedIn()
	{
		// Upgrade: the first login is the other group's account; the signed roles say which group is ours.
		GroupBinding.Result r = GroupBinding.check("", THEIRS, "Ship Wrek", "Iron Crew", HEARD);
		assertFalse(r.member());
		assertEquals("iron crew", r.bind);
	}

	@Test
	public void heardMembersDecideTheFirstBindingWithoutRoles()
	{
		// The cache already holds the other account's own card from before the fix: only it overlaps.
		List<String> polluted = Arrays.asList("Vinny", "Bea", "Ship Wrek");
		GroupBinding.Result wrong = GroupBinding.check("", THEIRS, "Ship Wrek", "", polluted);
		assertFalse(wrong.member());
		assertNull(wrong.bind);

		GroupBinding.Result right = GroupBinding.check("", OURS, "Cal", "", polluted);
		assertTrue(right.member());
		assertEquals("iron crew", right.bind);
	}

	@Test
	public void onlyOwnDataHeldBindsTheFirstGroup()
	{
		GroupBinding.Result r = GroupBinding.check("", OURS, "Vinny", "", Collections.singletonList("vinny"));
		assertTrue(r.member());
		assertEquals("iron crew", r.bind);
	}

	@Test
	public void switchingBackToAMemberIsAMemberAgain()
	{
		assertFalse(GroupBinding.check("iron crew", THEIRS, "Ship Wrek", "", HEARD).member());
		assertTrue(GroupBinding.check("iron crew", OURS, "Vinny", "", HEARD).member());
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.function.Function;
import java.util.function.Predicate;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static com.vinnyvangogh.groupironman.EventFixtures.all;
import static com.vinnyvangogh.groupironman.EventFixtures.none;
import static com.vinnyvangogh.groupironman.EventFixtures.settings;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** The game's Group channel broadcasts, posted for members without the plugin (Board 2026-11-14). */
public class GroupBroadcastsTest
{
	private static final Function<String, Integer> ITEMS = name ->
	{
		if ("Abyssal whip".equalsIgnoreCase(name))
		{
			return FakeItems.WHIP;
		}
		return "Shark".equalsIgnoreCase(name) ? Integer.valueOf(FakeItems.SHARK) : null;
	};
	private static final Predicate<String> NOBODY = n -> false;

	private static GroupEvent parse(String line)
	{
		return GroupBroadcasts.parse(line, NOW, ITEMS);
	}

	private static void is(String line, GroupEvent.Type type, String member, String text, long number)
	{
		GroupEvent e = parse(line);
		assertNotNull(line, e);
		assertEquals(line, type, e.type);
		assertEquals(line, member, e.member);
		assertEquals(line, text, e.text);
		assertEquals(line, number, e.number);
		assertTrue(line, e.broadcast);
	}

	// ---- Each format parses ----

	@Test
	public void theBoardsOwnCaptures()
	{
		is("GroupOtt has reached Herblore level 21.", GroupEvent.Type.LEVEL_UP, "GroupOtt", "Herblore", 21);
		is("GroupOtt has completed a quest: Black Knights' Fortress", GroupEvent.Type.QUEST, "GroupOtt",
			"Black Knights' Fortress", 0);
	}

	@Test
	public void theChatboxGroupTagTagsAndNonBreakingSpacesAreIgnored()
	{
		is("[GroupPures] GroupOtt has reached Herblore level 21.", GroupEvent.Type.LEVEL_UP, "GroupOtt", "Herblore",
			21);
		is("<col=ef1020>Iron Ott has reached Herblore level 21.</col>", GroupEvent.Type.LEVEL_UP, "Iron Ott",
			"Herblore", 21);
	}

	@Test
	public void levelKinds()
	{
		is("Alex has reached combat level 100.", GroupEvent.Type.COMBAT_LEVEL, "Alex", "", 100);
		is("Alex has reached a total level of 1,750.", GroupEvent.Type.TOTAL_LEVEL, "Alex", "", 1750);
		is("Alex has reached the highest possible Herblore level of 99.", GroupEvent.Type.MAXED, "Alex", "Herblore",
			99);
		is("Alex has reached Herblore level 99.", GroupEvent.Type.MAXED, "Alex", "Herblore", 99);
		is("Alex has reached 50,000,000 XP in Herblore.", GroupEvent.Type.XP_MILESTONE, "Alex", "Herblore",
			50_000_000);
	}

	@Test
	public void achievements()
	{
		GroupEvent task = parse("Alex has completed an Elite combat task: Perfect Zulrah (5 points).");
		assertEquals(GroupEvent.Type.COMBAT_TASK, task.type);
		assertEquals("Perfect Zulrah", task.text);
		assertEquals("Elite", task.detail);
		is("Alex has completed the Hard Ardougne diary.", GroupEvent.Type.DIARY, "Alex", "Hard Ardougne", 0);
		is("Alex has achieved a new Vorkath personal best: 1:23.40", GroupEvent.Type.PERSONAL_BEST, "Alex",
			"Vorkath 1:23.40", 0);
	}

	@Test
	public void dropsLogSlotsAndPets()
	{
		GroupEvent drop = parse("Alex received a drop: Abyssal whip (1,500,000 coins).");
		assertEquals(GroupEvent.Type.DROP, drop.type);
		assertEquals(Collections.singletonMap(FakeItems.WHIP, 1), drop.items);
		assertTrue("a broadcast drop names no NPC and is still a drop", drop.isValid());
		assertEquals(Collections.singletonMap(FakeItems.SHARK, 200),
			parse("Alex received a drop: 200 x Shark (160,000 coins).").items);
		assertNull("an item the client cannot name is no drop", parse("Alex received a drop: Mystery box"));

		is("Alex received a new collection log item: Dragon pickaxe (123/1477)", GroupEvent.Type.CLOG, "Alex",
			"Dragon pickaxe", 0);
		is("Alex has a funny feeling like he's being followed: Pet snakeling at 50 kill count.", GroupEvent.Type.PET,
			"Alex", "Pet snakeling", 0);
		is("Alex feels something weird sneaking into her backpack: Heron at 5,000,000 XP.", GroupEvent.Type.PET,
			"Alex", "Heron", 0);
		is("Alex has a funny feeling like he would have been followed: Baby mole at 120 kill count.",
			GroupEvent.Type.PET, "Alex", "Baby mole", 0);
	}

	@Test
	public void deaths()
	{
		is("Alex has been defeated by Vorkath in The Wilderness and lost (1,234 coins) worth of loot.",
			GroupEvent.Type.DEATH, "Alex", "Vorkath", 0);
		is("Alex has died and lost a group ironman life!", GroupEvent.Type.DEATH, "Alex", "", 0);
	}

	@Test
	public void otherLinesAreNothing()
	{
		for (String line : Arrays.asList(null, "", "anyone got guams?", "Alex has logged in.",
			"A name far too long for the game has reached Herblore level 21.", "[GIMU] 0123"))
		{
			assertNull(String.valueOf(line), parse(line));
		}
	}

	// ---- Plugin users, the one poster, dedupe ----

	@Test
	public void aPluginUsersBroadcastIsSkippedTheirClientPostsIt()
	{
		GroupEvent e = parse("Alex has reached Herblore level 21.");
		assertEquals(GroupBroadcasts.Action.SKIP, GroupBroadcasts.decide(e, n -> n.equalsIgnoreCase("alex"), true,
			new GroupBroadcasts.Seen(), NOW));
		assertEquals(GroupBroadcasts.Action.SKIP, GroupBroadcasts.decide(null, NOBODY, true,
			new GroupBroadcasts.Seen(), NOW));
	}

	@Test
	public void onlyTheChosenPosterPostsTheRestShowIt()
	{
		GroupEvent e = parse("Ott has reached Herblore level 21.");
		assertEquals(GroupBroadcasts.Action.POST, GroupBroadcasts.decide(e, NOBODY, true, new GroupBroadcasts.Seen(),
			NOW));
		assertEquals(GroupBroadcasts.Action.SHOW, GroupBroadcasts.decide(e, NOBODY, false, new GroupBroadcasts.Seen(),
			NOW));
	}

	@Test
	public void theLeaderPostsWhileOnlineElseTheFirstByName()
	{
		List<String> others = Arrays.asList("Alex", "Sam");
		assertTrue("the leader posts though Alex is first by name", ChannelPosts.leads("Zed", true, others, "Zed"));
		assertFalse("the leader is online: Alex does not post", ChannelPosts.leads("Alex", true,
			Arrays.asList("Zed", "Sam"), "Zed"));
		assertTrue("leader offline: first by name", ChannelPosts.leads("Alex", true, others.subList(1, 2), "Zed"));
		assertFalse(ChannelPosts.leads("Sam", true, Collections.singletonList("Alex"), "Zed"));
		assertTrue("no roles known: first by name", ChannelPosts.leads("Alex", true, others.subList(1, 2), ""));
		assertFalse("not in the party: posts only when it hears nobody", ChannelPosts.leads("Zed", false, others,
			"Zed"));
	}

	@Test
	public void aBroadcastIsPostedOnceAcrossARestart()
	{
		GroupEvent e = parse("Ott has completed a quest: Black Knights' Fortress");
		GroupBroadcasts.Seen seen = new GroupBroadcasts.Seen();
		assertEquals(GroupBroadcasts.Action.POST, GroupBroadcasts.decide(e, NOBODY, true, seen, NOW));
		assertEquals(GroupBroadcasts.Action.SHOW, GroupBroadcasts.decide(e, NOBODY, true, seen, NOW + 1000));

		GroupBroadcasts.Seen restarted = GroupBroadcasts.Seen.load(seen.save(), NOW + 60_000);
		assertEquals(GroupBroadcasts.Action.SHOW, GroupBroadcasts.decide(e, NOBODY, true, restarted, NOW + 60_000));
		GroupBroadcasts.Seen dayLater = GroupBroadcasts.Seen.load(seen.save(), NOW + GroupBroadcasts.REMEMBER_MS + 1);
		assertEquals("forgotten after a day", GroupBroadcasts.Action.POST,
			GroupBroadcasts.decide(e, NOBODY, true, dayLater, NOW + GroupBroadcasts.REMEMBER_MS + 1));
		assertEquals(0, GroupBroadcasts.Seen.load("junk\nno tab\n", NOW).save().length());
	}

	@Test
	public void anotherPostersClaimOverTheGroupSyncStopsASecondPost()
	{
		GroupEvent e = parse("Ott has reached Herblore level 21.");
		Gson gson = new Gson();
		String payload = GroupCodec.encodePosted(gson, Collections.singletonList(GroupBroadcasts.key(e)));
		assertNull("an older build's decoder reads it as an unknown kind", GroupCodec.decode(gson, payload));
		List<String> claim = GroupCodec.posted(gson, payload);
		assertEquals(Collections.singletonList(GroupBroadcasts.key(e)), claim);

		// Two clients both think they post (their views of who is online differ): the late one hears the claim.
		GroupBroadcasts.Seen late = new GroupBroadcasts.Seen();
		claim.forEach(k -> late.add(k, NOW));
		assertEquals(GroupBroadcasts.Action.SHOW, GroupBroadcasts.decide(e, NOBODY, true, late, NOW + 2000));
	}

	@Test
	public void theSameLineTheSameMinuteOnTwoClientsIsOneKeyANewMinuteIsAnother()
	{
		GroupEvent a = GroupBroadcasts.parse("Ott has reached Herblore level 21.", 120_000, ITEMS);
		GroupEvent b = GroupBroadcasts.parse("[GroupPures] OTT has reached Herblore level 21.", 121_500, ITEMS);
		GroupEvent c = GroupBroadcasts.parse("Ott has reached Herblore level 21.", 185_000, ITEMS);
		assertEquals(GroupBroadcasts.key(a), GroupBroadcasts.key(b));
		assertFalse(GroupBroadcasts.key(a).equals(GroupBroadcasts.key(c)));
	}

	@Test
	public void aClaimIsCappedAndReadOnlyAsStrings()
	{
		Gson gson = new Gson();
		List<String> many = new ArrayList<>();
		for (int i = 0; i < 50; i++)
		{
			many.add("k" + i);
		}
		assertEquals(GroupCodec.MAX_POSTED, GroupCodec.posted(gson, GroupCodec.encodePosted(gson, many)).size());
		assertEquals(Collections.singletonList("ok"), GroupCodec.posted(gson,
			"{\"v\":1,\"k\":\"posted\",\"p\":[1,{\"a\":1},\"ok\",\"\"]}"));
		assertNull("not a claim", GroupCodec.posted(gson, "{\"v\":1,\"k\":\"events\",\"e\":[]}"));
		assertNull(GroupCodec.posted(gson, "not json {"));
	}

	// ---- Toggles, N levels, the footer ----

	@Test
	public void theEventSwitchesAndPostEveryNLevelsApply()
	{
		List<GroupEvent> discord = new ArrayList<>();
		List<GroupEvent> overlay = new ArrayList<>();
		EventRouter router = new EventRouter(discord::add, overlay::add);
		FakeItems items = new FakeItems();
		EventSettings every5 = settings(all(), all()).levels(1, 5);
		router.post(parse("Ott has reached Herblore level 21."), every5, items);
		assertTrue("21 is not a multiple of 5", discord.isEmpty());
		router.post(parse("Ott has reached Herblore level 25."), every5, items);
		assertEquals(1, discord.size());
		assertTrue("posting never shows it a second time", overlay.isEmpty());

		discord.clear();
		router.post(parse("Ott has completed a quest: Cook's Assistant"), settings(EnumSet.complementOf(
			EnumSet.of(GroupEvent.Type.QUEST)), none()), items);
		assertTrue("Quest switched off", discord.isEmpty());
		router.post(parse("Ott received a drop: 2 x Shark (1,600 coins)."), settings(all(), none()), items);
		assertTrue("under the valuable drop minimum", discord.isEmpty());
		router.post(parse("Ott received a drop: Abyssal whip (1,500,000 coins)."), settings(all(), none()), items);
		assertEquals(1, discord.size());
	}

	@Test
	public void theFooterSaysWhereThePostCameFrom()
	{
		Gson gson = new Gson();
		FakeItems items = new FakeItems();
		GroupEvent e = parse("Ott has completed a quest: Cook's Assistant");
		// Gson writes the apostrophe as ', so the check is on the words after it.
		String marker = "group broadcast";
		String embed = DiscordWebhook.payload(gson, DiscordMerge.single(e, items), items, DiscordStyle.EMBED, "",
			false, null);
		assertTrue(embed, embed.contains(marker));
		String plain = DiscordWebhook.payload(gson, DiscordMerge.single(e, items), items, DiscordStyle.PLAIN, "",
			false, null);
		assertTrue(plain, plain.contains(marker));

		GroupEvent own = GroupEvent.of(GroupEvent.Type.QUEST, NOW, "Alex").text("Cook's Assistant").build();
		assertFalse(DiscordWebhook.payload(gson, DiscordMerge.single(own, items), items, DiscordStyle.EMBED, "",
			false, null).contains(marker));
		String drop = EventText.describe(parse("Ott received a drop: Abyssal whip (1,500,000 coins)."), items);
		assertTrue(drop, drop.startsWith("received a drop: 1 x Abyssal whip"));
	}

	@Test
	public void theGroupSettingIsOnByDefault()
	{
		GroupSettingsSchema.Setting s = GroupSettingsSchema.get(GroupSettingsSchema.NO_PLUGIN_EVENTS);
		assertNotNull(s);
		assertTrue(s.flag);
		GroupIronmanConfig defaults = new GroupIronmanConfig()
		{
		};
		assertTrue(new GroupSettingsSchema.Resolved(defaults, null).on(GroupSettingsSchema.NO_PLUGIN_EVENTS));
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static com.vinnyvangogh.groupironman.FakeItems.*;

/** Members' last banks, the storage log and storage survive a restart. */
public class GroupCacheTest
{
	private static final Gson GSON = new Gson();

	private static Map<Integer, Integer> items(int... pairs)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			out.put(pairs[i], pairs[i + 1]);
		}
		return out;
	}

	@Test
	public void banksLogAndStorageRoundTrip()
	{
		GroupRoster before = new GroupRoster();
		before.putBank("Alex", new BankSnapshot(100, items(SHARK, 120, COAL, 5)));
		before.putBank("Sam", new BankSnapshot(200, items(WHIP, 1)));
		before.putStorage(new StorageChange(300, "Sam", items(SHARK, 1), items(COAL, 9), items(SHARK, 40, COAL, 9)));
		before.putCarried("Sam", new GroupCodec.Carried(items(SHARK, 1), items()));

		GroupRoster after = new GroupRoster();
		assertTrue(GroupCache.read(GSON, GroupCache.write(GSON, before), after));

		assertEquals(before.banks(), after.banks());
		assertEquals(1, after.log().entries().size());
		assertEquals("Sam", after.log().entries().get(0).member());
		assertEquals(items(SHARK, 1), after.log().entries().get(0).took());
		assertEquals(items(SHARK, 40, COAL, 9), after.storageItems());
		assertEquals(300, after.storageAt());
		// Round 2 keeps carried items for offline cards: two banks, Sam's inventory and
		// equipment, and storage come back as search sources.
		assertEquals(5, after.searchSources().size());
		assertEquals(items(SHARK, 1), after.allCarried().get("Sam").inventory);
	}

	@Test
	public void anUnreadableFileLeavesTheRosterEmpty()
	{
		GroupRoster roster = new GroupRoster();
		assertFalse(GroupCache.read(GSON, "{{{", roster));
		assertFalse(GroupCache.read(GSON, "{\"banks\":{}}", roster));
		assertFalse(GroupCache.read(GSON, null, roster));
		assertFalse(roster.hasAnything());
	}

	@Test
	public void atMostFiftyMembersAreLookedAtPerSectionAndABadEntryCountsAsOne()
	{
		StringBuilder json = new StringBuilder("{\"v\":1,\"banks\":{\"Bad\":7");
		for (int i = 0; i < 60; i++)
		{
			json.append(",\"M").append(i).append("\":{\"ts\":1,\"i\":[385,1]}");
		}
		json.append("},\"heard\":{\"Alex\":5,\"Sam\":-1,\"Kim\":\"x\"},\"played\":9}");
		GroupRoster roster = new GroupRoster();
		assertTrue(GroupCache.read(GSON, json.toString(), roster));
		// "Bad" is not a bank, but it is still one of the fifty looked at.
		assertEquals(GroupCache.MAX_MEMBERS - 1, roster.banks().size());
		assertTrue(roster.banks().containsKey("M48"));
		assertFalse(roster.banks().containsKey("M49"));
		assertEquals(Long.valueOf(5), roster.lastHeard().get("Alex"));
		assertEquals(1, roster.lastHeard().size());
		assertEquals(9, roster.lastPlayed());
	}

	@Test
	public void extrasSeenHeardStatsAndHiscoresRoundTrip()
	{
		GroupRoster before = new GroupRoster();
		before.putExtras("Sam", new MemberExtras(items(SHARK, 2), items(), items(COAL, 3), 77));
		before.heard("Sam", 500);
		before.seen("Alex", new LastSeen(600, 302, true));
		before.markPlayed(700);
		GroupRoster after = new GroupRoster();
		String json = GroupCache.write(GSON, before, "hooks");
		assertTrue(GroupCache.read(GSON, json, after));
		assertEquals("hooks", GroupCache.webhooks(GSON, json));
		assertEquals(null, GroupCache.shop(GSON, json));
		assertEquals(items(COAL, 3), after.extras().get("Sam").seedVault);
		assertEquals(77, after.extras().get("Sam").seedVaultAt);
		assertEquals(Long.valueOf(500), after.lastHeard().get("Sam"));
		assertEquals(302, after.lastSeen().get("Alex").world);
		assertTrue(after.lastSeen().get("Alex").plugin);
		assertEquals(700, after.lastPlayed());
		// A second write of what was read is the same document.
		assertEquals(json, GroupCache.write(GSON, after, "hooks"));
	}

	@Test
	public void aNewerCacheWithExtraFieldsIsStillRead()
	{
		GroupRoster roster = new GroupRoster();
		assertTrue(GroupCache.read(GSON,
			"{\"v\":3,\"banks\":{\"Alex\":{\"ts\":5,\"i\":[385,2],\"tabs\":[1]}},\"pets\":[]}", roster));
		assertEquals(items(SHARK, 2), roster.banks().get("Alex").items());
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The group payloads on the wire: banks split to fit the size budget,
 * carried items, storage visits and stats, read back by a build that may be
 * older or newer than the sender.
 */
public class GroupCodecTest
{
	private static final Gson GSON = new Gson();

	private static Map<Integer, Integer> items(int... pairs)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			out.put(pairs[i], pairs[i + 1]);
		}
		return out;
	}

	/** A bank as big as the game allows, every stack at max cash so every number is as long as it gets. */
	private static BankSnapshot hugeBank()
	{
		Map<Integer, Integer> items = new TreeMap<>();
		for (int i = 0; i < 1410; i++)
		{
			items.put(30000 + i * 7, Integer.MAX_VALUE);
		}
		return new BankSnapshot(1_762_000_000_000L, items);
	}

	private static BankSnapshot reassemble(List<String> payloads)
	{
		BankAssembler assembler = new BankAssembler();
		BankSnapshot out = null;
		for (String p : payloads)
		{
			GroupCodec.Decoded d = GroupCodec.decode(GSON, p);
			assertNotNull(p, d);
			assertEquals(GroupCodec.Kind.BANK, d.kind);
			BankSnapshot done = assembler.accept(7L, d.bank);
			if (done != null)
			{
				out = done;
			}
		}
		return out;
	}

	@Test
	public void everyBankPartFitsTheSizeBudget()
	{
		List<String> parts = GroupCodec.encodeBank(GSON, hugeBank());
		assertTrue("a full bank needs splitting", parts.size() > 1);
		assertTrue(parts.size() <= GroupCodec.MAX_BANK_PARTS);
		for (String p : parts)
		{
			assertTrue("part is " + p.length() + " chars", p.length() <= GroupCodec.MAX_PAYLOAD_CHARS);
		}
	}

	@Test
	public void aSplitBankReassemblesExactly()
	{
		BankSnapshot bank = hugeBank();
		assertEquals(bank, reassemble(GroupCodec.encodeBank(GSON, bank)));
	}

	@Test
	public void aSmallBankIsOneMessage()
	{
		BankSnapshot bank = new BankSnapshot(5L, items(995, 1_000_000, 385, 300));
		List<String> parts = GroupCodec.encodeBank(GSON, bank);
		assertEquals(1, parts.size());
		assertEquals(bank, reassemble(parts));
	}

	@Test
	public void anEmptyBankStillSendsOnePart()
	{
		BankSnapshot bank = new BankSnapshot(5L, items());
		List<String> parts = GroupCodec.encodeBank(GSON, bank);
		assertEquals(1, parts.size());
		assertEquals(bank, reassemble(parts));
	}

	@Test
	public void storageVisitRoundTrips()
	{
		StorageChange change = new StorageChange(42L, "ignored", items(385, 5), items(453, 100), items(453, 100, 385, 15));
		GroupCodec.Decoded d = GroupCodec.decode(GSON, GroupCodec.encodeStorage(GSON, change));
		assertEquals(GroupCodec.Kind.STORAGE, d.kind);
		assertEquals(42L, d.storage.at());
		assertEquals(change.took(), d.storage.took());
		assertEquals(change.deposited(), d.storage.deposited());
		assertEquals(change.after(), d.storage.after());
		assertEquals("the sender never names who made the change", "", d.storage.member());
	}

	@Test
	public void statsRoundTrip()
	{
		Map<String, MemberStats.Level> skills = new LinkedHashMap<>();
		skills.put("Attack", new MemberStats.Level(90, 98));
		skills.put("Defence", new MemberStats.Level(1, 1));
		skills.put("Hitpoints", new MemberStats.Level(99, 71));
		MemberStats stats = new MemberStats(skills, 87, 50, 302, 12850);
		GroupCodec.Decoded d = GroupCodec.decode(GSON, GroupCodec.encodeStats(GSON, stats));
		assertEquals(GroupCodec.Kind.STATS, d.kind);
		assertEquals(stats, d.stats);
	}

	@Test
	public void carriedRoundTrips()
	{
		GroupCodec.Decoded d = GroupCodec.decode(GSON, GroupCodec.encodeCarried(GSON, items(385, 20), items(4151, 1)));
		assertEquals(GroupCodec.Kind.CARRIED, d.kind);
		assertEquals(items(385, 20), d.carried.inventory);
		assertEquals(items(4151, 1), d.carried.worn);
	}

	private static List<GroupCodec.Slot> slots(int... pairs)
	{
		List<GroupCodec.Slot> out = new java.util.ArrayList<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			out.add(GroupCodec.Slot.of(pairs[i], pairs[i + 1]));
		}
		return out;
	}

	@Test
	public void inventorySlotsTravelInOrderWithEmptiesAndRawIds()
	{
		// Coins, a gap, two potions, a noted shark stack (386): the counts say shark, the slot says noted shark.
		List<GroupCodec.Slot> sent = slots(995, 5000, 0, 0, 2434, 1, 2434, 1, 386, 10);
		String payload = GroupCodec.encodeCarried(GSON, items(995, 5000, 2434, 2, 385, 10), items(4151, 1), sent);
		GroupCodec.Decoded d = GroupCodec.decode(GSON, payload);
		assertEquals(GroupCodec.INVENTORY_SLOTS, d.carried.slots.size());
		assertEquals(995, d.carried.slots.get(0).id);
		assertEquals(5000, d.carried.slots.get(0).quantity);
		assertTrue(d.carried.slots.get(1).empty());
		assertEquals(2434, d.carried.slots.get(2).id);
		assertEquals(2434, d.carried.slots.get(3).id);
		assertEquals(386, d.carried.slots.get(4).id);
		assertEquals(10, d.carried.slots.get(4).quantity);
		for (int i = 5; i < GroupCodec.INVENTORY_SLOTS; i++)
		{
			assertTrue("slot " + i, d.carried.slots.get(i).empty());
		}
		assertEquals("counts stay canonical for Find and totals", items(995, 5000, 2434, 2, 385, 10), d.carried.inventory);
	}

	/** A build from before slots (gim-test-2) reads only inv and eq, so those must be exactly what it always got. */
	@Test
	public void theSlotMessageKeepsTheOldFieldsForAnOldReader()
	{
		Map<Integer, Integer> inv = items(2434, 14);
		Map<Integer, Integer> worn = items(4151, 1);
		int[] fourteen = new int[28];
		for (int i = 0; i < 28; i += 2)
		{
			fourteen[i] = 2434;
			fourteen[i + 1] = 1;
		}
		com.google.gson.JsonObject withSlots = GSON.fromJson(
			GroupCodec.encodeCarried(GSON, inv, worn, slots(fourteen)), com.google.gson.JsonObject.class);
		assertTrue(withSlots.has("is"));
		withSlots.remove("is");
		assertEquals("old fields and version unchanged", GroupCodec.encodeCarried(GSON, inv, worn), GSON.toJson(withSlots));

		GroupCodec.Decoded d = GroupCodec.decode(GSON, GroupCodec.encodeCarried(GSON, inv, worn, slots(fourteen)));
		assertEquals(inv, d.carried.inventory);
		assertEquals(worn, d.carried.worn);
	}

	@Test
	public void anOldCarriedMessageHasNoSlots()
	{
		GroupCodec.Decoded d = GroupCodec.decode(GSON, "{\"v\":1,\"k\":\"carried\",\"inv\":[2434,14],\"eq\":[]}");
		assertTrue(d.carried.slots.isEmpty());
		assertEquals(items(2434, 14), d.carried.inventory);
		assertTrue("no slots sent, none encoded", !GroupCodec.encodeCarried(GSON, items(1, 1), items()).contains("\"is\""));
	}

	@Test
	public void badSlotsBecomeEmptyInPlaceAndAPeerCannotSendMoreThan28()
	{
		StringBuilder sb = new StringBuilder("{\"v\":1,\"k\":\"carried\",\"inv\":[],\"eq\":[],\"is\":[-1,5,385,0,\"x\",1,995,7");
		for (int i = 0; i < 100; i++)
		{
			sb.append(",385,1");
		}
		sb.append("]}");
		List<GroupCodec.Slot> got = GroupCodec.decode(GSON, sb.toString()).carried.slots;
		assertEquals(GroupCodec.INVENTORY_SLOTS, got.size());
		assertTrue(got.get(0).empty());
		assertTrue(got.get(1).empty());
		assertTrue(got.get(2).empty());
		assertEquals(995, got.get(3).id);
		assertEquals(385, got.get(27).id);
		assertTrue("not an array: no slots", GroupCodec.decode(GSON,
			"{\"v\":1,\"k\":\"carried\",\"inv\":[],\"is\":{}}").carried.slots.isEmpty());
	}

	@Test
	public void aNewerSenderWithExtraFieldsIsStillRead()
	{
		String json = "{\"v\":7,\"k\":\"carried\",\"inv\":[385,3],\"eq\":[],\"future\":{\"x\":1},\"note\":\"hi\"}";
		GroupCodec.Decoded d = GroupCodec.decode(GSON, json);
		assertNotNull(d);
		assertEquals(items(385, 3), d.carried.inventory);
	}

	@Test
	public void anOlderSenderMissingFieldsDecodesToEmpty()
	{
		GroupCodec.Decoded d = GroupCodec.decode(GSON, "{\"v\":1,\"k\":\"stats\"}");
		assertNotNull(d);
		assertTrue(d.stats.skills().isEmpty());
		assertEquals(0, d.stats.world());
	}

	@Test
	public void aKindFromANewerBuildIsIgnored()
	{
		assertNull(GroupCodec.decode(GSON, "{\"v\":2,\"k\":\"pets\",\"i\":[1,1]}"));
	}

	@Test
	public void unversionedOrBrokenPayloadsAreIgnored()
	{
		assertNull(GroupCodec.decode(GSON, null));
		assertNull(GroupCodec.decode(GSON, ""));
		assertNull(GroupCodec.decode(GSON, "not json"));
		assertNull(GroupCodec.decode(GSON, "[1,2]"));
		assertNull(GroupCodec.decode(GSON, "{\"k\":\"carried\"}"));
		assertNull(GroupCodec.decode(GSON, "{\"v\":0,\"k\":\"carried\"}"));
		assertNull(GroupCodec.decode(GSON, "{\"v\":1}"));
	}

	@Test
	public void badItemPairsAreDroppedNotFatal()
	{
		String json = "{\"v\":1,\"k\":\"carried\",\"inv\":[385,3,-1,5,0,2,99,0,1.5,2,\"x\",4,9999999,1,995,10,7],\"eq\":{}}";
		GroupCodec.Decoded d = GroupCodec.decode(GSON, json);
		assertEquals(items(385, 3, 995, 10), d.carried.inventory);
		assertTrue(d.carried.worn.isEmpty());
	}

	@Test
	public void impossibleLevelsAreDropped()
	{
		String json = "{\"v\":1,\"k\":\"stats\",\"s\":{\"Attack\":[120,120],\"Magic\":[99,250],\"Prayer\":[70,43],\"X\":\"y\"},\"run\":500,\"spec\":-4}";
		GroupCodec.Decoded d = GroupCodec.decode(GSON, json);
		assertEquals(1, d.stats.skills().size());
		assertEquals(new MemberStats.Level(70, 43), d.stats.skills().get("Prayer"));
		assertEquals(100, d.stats.runEnergy());
		assertEquals(0, d.stats.specialAttack());
	}

	@Test
	public void badBankPartHeadersAreIgnored()
	{
		assertNull(GroupCodec.decode(GSON, "{\"v\":1,\"k\":\"bank\",\"ts\":1,\"p\":3,\"n\":3,\"i\":[]}"));
		assertNull(GroupCodec.decode(GSON, "{\"v\":1,\"k\":\"bank\",\"ts\":1,\"p\":0,\"n\":99,\"i\":[]}"));
		assertNull(GroupCodec.decode(GSON, "{\"v\":1,\"k\":\"bank\",\"p\":0,\"n\":1,\"i\":[]}"));
	}

	@Test
	public void aPeerCannotFloodTheCarriedList()
	{
		StringBuilder sb = new StringBuilder("{\"v\":1,\"k\":\"carried\",\"inv\":[");
		for (int i = 1; i <= 500; i++)
		{
			sb.append(i == 1 ? "" : ",").append(i).append(",1");
		}
		sb.append("]}");
		assertEquals(GroupCodec.MAX_CARRIED_ITEMS, GroupCodec.decode(GSON, sb.toString()).carried.inventory.size());
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static com.vinnyvangogh.groupironman.EventFixtures.sample;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Typed events on the party wire: round trip, the storage kinds stay home, a 1.0.0 payload still reads. */
public class GroupEventCodecTest
{
	private final Gson gson = new Gson();

	@Test
	public void everyTravellingKindRoundTripsWithItsFields()
	{
		List<GroupEvent> out = new ArrayList<>();
		for (GroupEvent.Type t : GroupEvent.Type.values())
		{
			out.add(sample(t).toBuilder().world(330).location("Lumbridge").detail("Dharok's 2/4").build());
		}
		List<GroupEvent> back = new ArrayList<>();
		for (String payload : GroupCodec.encodeEvents(gson, out))
		{
			back.addAll(GroupCodec.decode(gson, payload).events);
		}
		long travelling = out.stream().filter(e -> e.type.travels()).count();
		assertEquals(travelling, back.size());
		for (GroupEvent e : back)
		{
			assertTrue(e.type + " travels", e.type.travels());
			assertEquals("the receiver names the member", "", e.member);
			GroupEvent sent = out.stream().filter(o -> o.type == e.type).findFirst().orElseThrow(AssertionError::new);
			assertTrue(e.type + " same", sent.withMember("").sameAs(e));
			assertEquals(330, e.world);
			assertEquals("Lumbridge", e.location);
			assertEquals("Dharok's 2/4", e.detail);
		}
	}

	@Test
	public void aVersionOnePayloadStillReads()
	{
		String v1 = "{\"v\":1,\"k\":\"events\",\"e\":[{\"t\":\"d\",\"ts\":5,\"s\":\"Vorkath\",\"i\":[4151,1]},"
			+ "{\"t\":\"c\",\"ts\":6,\"s\":\"Draconic visage\"},{\"t\":\"zz\",\"ts\":7,\"s\":\"from the future\"}]}";
		List<GroupEvent> events = GroupCodec.decode(gson, v1).events;
		assertEquals("the unknown kind is skipped", 2, events.size());
		assertEquals(GroupEvent.Type.DROP, events.get(0).type);
		assertEquals(GroupEvent.Type.CLOG, events.get(1).type);
	}

	@Test
	public void aDropStillLooksAsOneDotZeroSentIt()
	{
		String json = GroupCodec.encodeEvents(gson, Collections.singletonList(
			GroupEvent.drop(NOW, "Me", "Vorkath", EventFixtures.items(FakeItems.WHIP, 1)))).get(0);
		assertTrue(json, json.contains("{\"t\":\"d\",\"ts\":" + NOW + ",\"s\":\"Vorkath\",\"i\":[4151,1]}"));
	}

	@Test
	public void groupEventsGoOnlyWithTheirSwitchAndNeverTheDropsOrStorage()
	{
		List<GroupEvent> all = new ArrayList<>(EventFixtures.samples().values());
		assertTrue(GroupOutbox.groupEvents(gson, false, all).isEmpty());
		List<GroupEvent> sent = new ArrayList<>();
		for (String payload : GroupOutbox.groupEvents(gson, true, all))
		{
			sent.addAll(GroupCodec.decode(gson, payload).events);
		}
		assertTrue(sent.stream().noneMatch(e -> e.type.logged() || !e.type.travels()));
		assertEquals(all.stream().filter(e -> e.type.travels() && !e.type.logged()).count(), sent.size());
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static com.vinnyvangogh.groupironman.FakeItems.*;

/**
 * The part 3 payloads: rune pouch, quiver and seed vault ("extras"), the
 * drops and collection log events, and the position added to stats.
 */
public class GroupExtrasCodecTest
{
	private static final Gson GSON = new Gson();
	private static final long NOW = 1_762_000_000_000L;

	private static Map<Integer, Integer> items(int... pairs)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			out.put(pairs[i], pairs[i + 1]);
		}
		return out;
	}

	@Test
	public void extrasRoundTrip()
	{
		MemberExtras extras = new MemberExtras(items(563, 1000, 560, 250), items(21326, 500), items(5295, 12), NOW);
		GroupCodec.Decoded d = GroupCodec.decode(GSON, GroupCodec.encodeExtras(GSON, extras));
		assertNotNull(d);
		assertEquals(GroupCodec.Kind.EXTRAS, d.kind);
		assertEquals(extras, d.extras);
	}

	@Test
	public void anUnknownSeedVaultStaysUnknown()
	{
		MemberExtras extras = new MemberExtras(items(563, 1), items(), items(), -1);
		GroupCodec.Decoded d = GroupCodec.decode(GSON, GroupCodec.encodeExtras(GSON, extras));
		assertEquals(-1, d.extras.seedVaultAt);
		assertTrue(d.extras.seedVault.isEmpty());
	}

	@Test
	public void theFullestExtrasFitTheSizeBudget()
	{
		Map<Integer, Integer> pouch = new TreeMap<>();
		for (int i = 0; i < 6; i++)
		{
			pouch.put(1_000_000 + i, Integer.MAX_VALUE);
		}
		Map<Integer, Integer> vault = new TreeMap<>();
		for (int i = 0; i < 1000; i++)
		{
			vault.put(1_000_000 + i, Integer.MAX_VALUE);
		}
		MemberExtras extras = new MemberExtras(pouch, items(1_048_000, Integer.MAX_VALUE), vault, Long.MAX_VALUE / 2);
		String payload = GroupCodec.encodeExtras(GSON, extras);
		assertTrue("payload is " + payload.length() + " chars", payload.length() <= GroupCodec.MAX_PAYLOAD_CHARS);
		assertEquals(GroupCodec.MAX_SEED_VAULT_ITEMS, GroupCodec.decode(GSON, payload).extras.seedVault.size());
	}

	@Test
	public void aPeerCannotFloodThePouch()
	{
		StringBuilder sb = new StringBuilder("{\"v\":1,\"k\":\"extras\",\"rp\":[");
		for (int i = 1; i <= 100; i++)
		{
			sb.append(i == 1 ? "" : ",").append(i).append(",1");
		}
		sb.append("],\"svts\":-1}");
		assertEquals(GroupCodec.MAX_POUCH_ITEMS, GroupCodec.decode(GSON, sb.toString()).extras.runePouch.size());
	}

	@Test
	public void eventsRoundTripWithoutTheSendersName()
	{
		List<GroupEvent> events = new ArrayList<>();
		events.add(GroupEvent.drop(NOW, "Me", "Vorkath", items(WHIP, 1, SHARK, 2)));
		events.add(GroupEvent.clog(NOW + 1, "Me", "Draconic visage"));
		List<String> payloads = GroupCodec.encodeEvents(GSON, events);
		assertEquals(1, payloads.size());
		GroupCodec.Decoded d = GroupCodec.decode(GSON, payloads.get(0));
		assertEquals(GroupCodec.Kind.EVENTS, d.kind);
		assertEquals(2, d.events.size());
		GroupEvent drop = d.events.get(0);
		assertEquals(GroupEvent.Type.DROP, drop.type);
		assertEquals(NOW, drop.at);
		assertEquals("Vorkath", drop.text);
		assertEquals(items(WHIP, 1, SHARK, 2), drop.items);
		assertEquals("the receiver files it under the party member it came from", "", drop.member);
		GroupEvent clog = d.events.get(1);
		assertEquals(GroupEvent.Type.CLOG, clog.type);
		assertEquals("Draconic visage", clog.text);
	}

	@Test
	public void manyEventsSplitAndEveryPartFits()
	{
		List<GroupEvent> events = new ArrayList<>();
		Map<Integer, Integer> loot = new TreeMap<>();
		for (int i = 0; i < GroupEvent.MAX_DROP_ITEMS; i++)
		{
			loot.put(1_000_000 + i, Integer.MAX_VALUE);
		}
		StringBuilder name = new StringBuilder();
		for (int i = 0; i < GroupEvent.MAX_TEXT; i++)
		{
			// Gson escapes '<' as six characters; the split must count what is actually sent.
			name.append('<');
		}
		for (int i = 0; i < DropLog.MAX_RESEND; i++)
		{
			events.add(GroupEvent.drop(NOW + i, "Me", name.toString(), loot));
		}
		List<String> payloads = GroupCodec.encodeEvents(GSON, events);
		assertTrue(payloads.size() > 1);
		int seen = 0;
		for (String p : payloads)
		{
			assertTrue("part is " + p.length() + " chars", p.length() <= GroupCodec.MAX_PAYLOAD_CHARS);
			seen += GroupCodec.decode(GSON, p).events.size();
		}
		assertEquals(events.size(), seen);
	}

	@Test
	public void noEventsMeansNoMessage()
	{
		assertTrue(GroupCodec.encodeEvents(GSON, Collections.emptyList()).isEmpty());
	}

	@Test
	public void badEventsAreDroppedNotFatal()
	{
		String json = "{\"v\":1,\"k\":\"events\",\"e\":[{\"t\":\"d\",\"ts\":5,\"s\":\"Goblin\",\"i\":[385,1]},"
			+ "{\"t\":\"x\",\"ts\":5,\"s\":\"?\"},{\"t\":\"c\",\"s\":\"no time\"},{\"t\":\"c\",\"ts\":6,\"s\":\"\"},7,"
			+ "{\"t\":\"d\",\"ts\":8,\"s\":\"Empty\",\"i\":[]}]}";
		GroupCodec.Decoded d = GroupCodec.decode(GSON, json);
		assertEquals(1, d.events.size());
		assertEquals("Goblin", d.events.get(0).text);
	}

	@Test
	public void statsCarryAPositionAndOldReadersIgnoreIt()
	{
		Map<String, MemberStats.Level> skills = new LinkedHashMap<>();
		skills.put("Attack", new MemberStats.Level(60, 60));
		MemberStats stats = new MemberStats(skills, 100, 100, 330, 12850, 3222, 3218, 0);
		GroupCodec.Decoded d = GroupCodec.decode(GSON, GroupCodec.encodeStats(GSON, stats));
		assertEquals(stats, d.stats);
		assertEquals(3222, d.stats.x());
		assertEquals(3218, d.stats.y());
	}

	@Test
	public void statsFromAPart2SenderHaveNoPosition()
	{
		GroupCodec.Decoded d = GroupCodec.decode(GSON, "{\"v\":1,\"k\":\"stats\",\"w\":301,\"r\":12850}");
		assertEquals(0, d.stats.x());
		assertEquals(0, d.stats.y());
		assertEquals(12850, d.stats.region());
	}

	@Test
	public void impossiblePositionsAreClamped()
	{
		GroupCodec.Decoded d = GroupCodec.decode(GSON, "{\"v\":1,\"k\":\"stats\",\"x\":-5,\"y\":99999999,\"pl\":9}");
		assertEquals(0, d.stats.x());
		assertEquals(GroupCodec.MAX_COORD, d.stats.y());
		assertEquals(3, d.stats.plane());
	}

	@Test
	public void aPart2ReaderIgnoresThePart3Kinds()
	{
		// What a part 2 build does with these: GroupCodec's default branch. Pinned so
		// nobody repurposes the names for something an old build would misread.
		assertNull(GroupCodec.decode(GSON, "{\"v\":1,\"k\":\"pets\"}"));
		assertNotNull(GroupCodec.decode(GSON, "{\"v\":1,\"k\":\"extras\"}"));
		assertNotNull(GroupCodec.decode(GSON, "{\"v\":1,\"k\":\"events\"}"));
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Before;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Roles and group settings between simulated members. Every document crosses
 * the "wire" through {@link GovernanceCodec}, as it does over the party.
 */
public class GroupGovernanceTest
{
	private static final String GROUP = "GroupShip";
	private static final GroupIronmanConfig DEFAULTS = new GroupIronmanConfig()
	{
	};
	private final Gson gson = new Gson();

	private GroupSigner.Identity alexId;
	private GroupSigner.Identity samId;
	private GroupSigner.Identity kimId;
	private GroupGovernance alex;
	private GroupGovernance sam;
	private GroupGovernance kim;

	@Before
	public void setUp()
	{
		alexId = GroupSigner.Identity.create();
		samId = GroupSigner.Identity.create();
		kimId = GroupSigner.Identity.create();
		alex = member(alexId);
		sam = member(samId);
		kim = member(kimId);
		// Each member's announce reaches the others, as on joining the party.
		for (GroupGovernance g : new GroupGovernance[]{alex, sam, kim})
		{
			g.receiveMember("Alex", alexId.publicKey(), MemberPrefs.NONE);
			g.receiveMember("Sam", samId.publicKey(), MemberPrefs.NONE);
			g.receiveMember("Kim", kimId.publicKey(), MemberPrefs.NONE);
		}
	}

	private static GroupGovernance member(GroupSigner.Identity id)
	{
		GroupGovernance g = new GroupGovernance(id);
		g.group(GROUP);
		return g;
	}

	private GroupRoles wire(GroupRoles roles)
	{
		return GovernanceCodec.decode(gson, GovernanceCodec.encode(gson, roles)).roles;
	}

	private GroupSettings wire(GroupSettings settings)
	{
		return GovernanceCodec.decode(gson, GovernanceCodec.encode(gson, settings)).settings;
	}

	private static Map<String, Long> values(long levelMin)
	{
		Map<String, Long> v = GroupSettingsSchema.seed(DEFAULTS);
		v.put("eventLevelMin", levelMin);
		return v;
	}

	// ---- Roles ----

	@Test
	public void theClaimantIsLeaderOnEveryClient()
	{
		GroupRoles roles = alex.claim("Alex", NOW);
		assertNotNull(roles);
		assertEquals(GroupGovernance.Role.LEADER, alex.myRole("Alex"));
		assertEquals(GroupGovernance.Verdict.ACCEPTED, sam.receiveRoles(wire(roles)));
		assertEquals(GroupGovernance.Role.LEADER, sam.role("Alex"));
		assertEquals(GroupGovernance.Role.MEMBER, sam.myRole("Sam"));
	}

	@Test
	public void aClaimedGroupCannotBeClaimedAgain()
	{
		sam.receiveRoles(wire(alex.claim("Alex", NOW)));
		assertNull("Sam's client refuses a second claim", sam.claim("Sam", NOW + 1));
		assertNull("and so does Alex's", alex.claim("Alex", NOW + 1));
	}

	@Test
	public void aMemberCannotSelfPromote()
	{
		sam.receiveRoles(wire(alex.claim("Alex", NOW)));
		kim.receiveRoles(wire(alex.roles()));

		// Sam signs a claim of his own with his own key: the pinned leader key does not match.
		GroupGovernance rogue = member(samId);
		rogue.receiveMember("Sam", samId.publicKey(), MemberPrefs.NONE);
		GroupRoles forged = rogue.claim("Sam", NOW + 5);
		assertEquals(GroupGovernance.Verdict.REFUSED, kim.receiveRoles(wire(forged)));
		assertEquals(GroupGovernance.Role.LEADER, kim.role("Alex"));

		// Sam edits Alex's roles to add himself as editor, without Alex's key to re-sign.
		JsonObject json = GovernanceCodec.json(alex.roles());
		json.getAsJsonObject("ed").addProperty("Sam", samId.publicKey());
		json.addProperty("ver", 9);
		GroupRoles tampered = GovernanceCodec.decode(gson, json.toString()).roles;
		assertEquals(GroupGovernance.Verdict.REFUSED, kim.receiveRoles(tampered));
		assertEquals(GroupGovernance.Role.MEMBER, kim.role("Sam"));

		// And his own client will not let him save.
		assertNull(sam.save("Sam", values(70), NOW + 6));
	}

	@Test
	public void aClaimNamingSomeoneElseWithTheWrongKeyIsRefused()
	{
		// Sam signs "Alex is leader" with Sam's key, hoping members pin a key he holds.
		GroupGovernance rogue = member(samId);
		rogue.receiveMember("Alex", samId.publicKey(), MemberPrefs.NONE);
		GroupRoles forged = rogue.claim("Alex", NOW);
		assertEquals(GroupGovernance.Verdict.REFUSED, kim.receiveRoles(wire(forged)));
		assertNull(kim.roles());
	}

	@Test
	public void aClaimWaitsUntilTheClaimantsKeyIsKnown()
	{
		GroupGovernance newcomer = member(GroupSigner.Identity.create());
		assertEquals(GroupGovernance.Verdict.PENDING, newcomer.receiveRoles(wire(alex.claim("Alex", NOW))));
		assertNull(newcomer.roles());
		newcomer.receiveMember("Alex", alexId.publicKey(), MemberPrefs.NONE);
		assertNotNull("applied once Alex's own announce arrives", newcomer.roles());
	}

	@Test
	public void rolesForAnotherGroupAreRefused()
	{
		GroupGovernance other = member(GroupSigner.Identity.create());
		other.group("Other group");
		other.receiveMember("Alex", alexId.publicKey(), MemberPrefs.NONE);
		assertEquals(GroupGovernance.Verdict.REFUSED, other.receiveRoles(wire(alex.claim("Alex", NOW))));
	}

	@Test
	public void onlyTheLeaderGrantsAndRevokesEditors()
	{
		sam.receiveRoles(wire(alex.claim("Alex", NOW)));
		assertNull("Sam is not leader", sam.setEditor("Sam", "Sam", true, NOW + 1));
		GroupRoles granted = alex.setEditor("Alex", "Sam", true, NOW + 1);
		assertNotNull(granted);
		assertEquals(GroupGovernance.Verdict.ACCEPTED, sam.receiveRoles(wire(granted)));
		assertEquals(GroupGovernance.Role.EDITOR, sam.myRole("Sam"));
		assertEquals(GroupGovernance.Verdict.STALE, sam.receiveRoles(wire(granted)));

		GroupRoles revoked = alex.setEditor("Alex", "Sam", false, NOW + 2);
		assertEquals(GroupGovernance.Verdict.ACCEPTED, sam.receiveRoles(wire(revoked)));
		assertEquals(GroupGovernance.Role.MEMBER, sam.myRole("Sam"));
	}

	@Test
	public void anEditorWhoseKeyIsUnknownCannotBeGranted()
	{
		alex.claim("Alex", NOW);
		assertNull(alex.setEditor("Alex", "Stranger", true, NOW + 1));
	}

	// ---- Settings ----

	@Test
	public void aNonEditorChangeIsRefused()
	{
		GroupRoles roles = alex.claim("Alex", NOW);
		sam.receiveRoles(wire(roles));
		kim.receiveRoles(wire(roles));
		assertNull("refused on Sam's own client", sam.save("Sam", values(70), NOW + 1));

		// A document Sam signs himself (a modified client) is refused by everyone else.
		GroupSettings forged = GroupSettings.next(null, values(70), "Sam", samId, NOW + 1);
		assertEquals(GroupGovernance.Verdict.REFUSED, kim.receiveSettings(wire(forged)));
		assertNull(kim.settings());
	}

	@Test
	public void aChangeSyncsToASecondMember()
	{
		GroupRoles roles = alex.claim("Alex", NOW);
		GroupSettings saved = alex.save("Alex", values(70), NOW + 1);
		assertNotNull(saved);
		assertEquals(1, saved.version);

		assertEquals(GroupGovernance.Verdict.ACCEPTED, sam.receiveRoles(wire(roles)));
		assertEquals(GroupGovernance.Verdict.ACCEPTED, sam.receiveSettings(wire(saved)));
		assertEquals(70, new GroupSettingsSchema.Resolved(DEFAULTS, sam.settings()).value("eventLevelMin"));
		assertEquals("Alex", sam.settings().by);
		assertEquals(NOW + 1, sam.settings().at);
	}

	@Test
	public void historySaysWhoChangedWhatAndWhen()
	{
		alex.claim("Alex", NOW);
		alex.save("Alex", values(70), NOW + 1);
		GroupSettings second = alex.save("Alex", values(80), NOW + 2);
		assertEquals(2, second.version);
		GroupSettings.Change last = second.history.get(0);
		assertEquals("Alex", last.by);
		assertEquals(NOW + 2, last.at);
		assertEquals("eventLevelMin", last.key);
		assertEquals(70, last.from);
		assertEquals(80, last.to);
	}

	@Test
	public void savingNothingNewKeepsTheVersion()
	{
		alex.claim("Alex", NOW);
		GroupSettings first = alex.save("Alex", values(70), NOW + 1);
		assertSame(first, alex.save("Alex", values(70), NOW + 2));
	}

	@Test
	public void anOfflineMemberPicksUpTheLatestAndIgnoresOlder()
	{
		GroupRoles roles = alex.claim("Alex", NOW);
		GroupSettings v1 = alex.save("Alex", values(70), NOW + 1);
		GroupSettings v2 = alex.save("Alex", values(80), NOW + 2);
		// Sam was offline for both; on joining, a member resends roles then the latest settings.
		sam.receiveRoles(wire(roles));
		assertEquals(GroupGovernance.Verdict.ACCEPTED, sam.receiveSettings(wire(v2)));
		assertEquals(GroupGovernance.Verdict.STALE, sam.receiveSettings(wire(v1)));
		assertEquals(2, sam.settings().version);
	}

	@Test
	public void settingsBeforeRolesWaitForThem()
	{
		GroupRoles roles = alex.claim("Alex", NOW);
		GroupSettings v1 = alex.save("Alex", values(70), NOW + 1);
		assertEquals(GroupGovernance.Verdict.PENDING, sam.receiveSettings(wire(v1)));
		assertNull(sam.settings());
		sam.receiveRoles(wire(roles));
		assertNotNull(sam.settings());
		assertEquals(1, sam.settings().version);
	}

	@Test
	public void aTamperedSettingsDocumentIsRefused()
	{
		GroupRoles roles = alex.claim("Alex", NOW);
		sam.receiveRoles(wire(roles));
		JsonObject json = GovernanceCodec.json(alex.save("Alex", values(70), NOW + 1));
		json.getAsJsonObject("val").addProperty("eventLevelMin", 1);
		assertEquals(GroupGovernance.Verdict.REFUSED,
			sam.receiveSettings(GovernanceCodec.decode(gson, json.toString()).settings));
	}

	@Test
	public void aVersionConflictConvergesOnOneWinnerInAnyOrder()
	{
		GroupRoles roles = alex.claim("Alex", NOW);
		roles = alex.setEditor("Alex", "Sam", true, NOW + 1);
		roles = alex.setEditor("Alex", "Kim", true, NOW + 2);
		GroupSettings base = alex.save("Alex", values(60), NOW + 3);
		for (GroupGovernance g : new GroupGovernance[]{sam, kim})
		{
			g.receiveRoles(wire(roles));
			g.receiveSettings(wire(base));
		}

		// Sam and Kim both edit version 1 at the same moment: two different version 2s.
		GroupSettings bySam = sam.save("Sam", values(70), NOW + 10);
		GroupSettings byKim = kim.save("Kim", values(80), NOW + 10);
		assertEquals(2, bySam.version);
		assertEquals(2, byKim.version);

		GroupGovernance lee = member(GroupSigner.Identity.create());
		GroupGovernance max = member(GroupSigner.Identity.create());
		for (GroupGovernance g : new GroupGovernance[]{lee, max})
		{
			g.receiveMember("Alex", alexId.publicKey(), MemberPrefs.NONE);
			g.receiveRoles(wire(roles));
		}
		lee.receiveSettings(wire(bySam));
		lee.receiveSettings(wire(byKim));
		max.receiveSettings(wire(byKim));
		max.receiveSettings(wire(bySam));
		alex.receiveSettings(wire(bySam));
		alex.receiveSettings(wire(byKim));
		sam.receiveSettings(wire(byKim));
		kim.receiveSettings(wire(bySam));

		String winner = lee.settings().signature;
		for (GroupGovernance g : new GroupGovernance[]{max, alex, sam, kim})
		{
			assertEquals("every client keeps the same version 2", winner, g.settings().signature);
		}
		// The next save builds on the winner, so nothing is lost silently: it is in the history.
		GroupSettings next = alex.save("Alex", values(90), NOW + 20);
		assertEquals(3, next.version);
	}

	@Test
	public void revokingAnEditorReSignsTheirSettingsSoLateJoinersAgree()
	{
		GroupRoles roles = alex.claim("Alex", NOW);
		roles = alex.setEditor("Alex", "Sam", true, NOW + 1);
		sam.receiveRoles(wire(roles));
		GroupSettings bySam = sam.save("Sam", values(70), NOW + 2);
		alex.receiveSettings(wire(bySam));

		GroupRoles revoked = alex.setEditor("Alex", "Sam", false, NOW + 3);
		GroupSettings resigned = alex.settings();
		assertEquals("Alex", resigned.by);
		assertEquals(bySam.version + 1, resigned.version);
		assertEquals(bySam.values, resigned.values);

		GroupGovernance late = member(GroupSigner.Identity.create());
		late.receiveMember("Alex", alexId.publicKey(), MemberPrefs.NONE);
		late.receiveRoles(wire(revoked));
		assertEquals(GroupGovernance.Verdict.REFUSED, late.receiveSettings(wire(bySam)));
		assertEquals(GroupGovernance.Verdict.ACCEPTED, late.receiveSettings(wire(resigned)));
		assertEquals(70, new GroupSettingsSchema.Resolved(DEFAULTS, late.settings()).value("eventLevelMin"));
	}

	@Test
	public void forgettingTheLeaderAllowsANewClaimOnThisClientOnly()
	{
		sam.receiveRoles(wire(alex.claim("Alex", NOW)));
		sam.forgetLeader();
		assertNull(sam.roles());
		assertTrue(sam.unclaimed());
		assertFalse(alex.unclaimed());
	}

	@Test
	public void membersPreferencesAreKeptForTheGrid()
	{
		MemberPrefs prefs = new MemberPrefs(false, java.util.EnumSet.of(GroupEvent.Type.DEATH),
			java.util.EnumSet.noneOf(GroupEvent.Type.class));
		alex.receiveMember("Sam", samId.publicKey(), prefs);
		Map<String, MemberPrefs> seen = new TreeMap<>(alex.prefs());
		assertFalse(seen.get("Sam").posts(GroupEvent.Type.DEATH));
		assertTrue(seen.get("Sam").posts(GroupEvent.Type.PET));
	}
}

