package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.lang.reflect.Proxy;
import java.util.Locale;
import java.util.Map;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class GroupSettingsSchemaTest
{
	private static final String SECRET = "https://discord.com/api/webhooks/123456/SECRETTOKEN";
	private static final GroupIronmanConfig DEFAULTS = new GroupIronmanConfig()
	{
	};

	/** Every switch on, every number 7, every text field the webhook URL. */
	private static GroupIronmanConfig everythingSet()
	{
		return (GroupIronmanConfig) Proxy.newProxyInstance(GroupIronmanConfig.class.getClassLoader(),
			new Class<?>[]{GroupIronmanConfig.class}, (p, m, args) ->
			{
				if (m.getReturnType() == boolean.class)
				{
					return true;
				}
				if (m.getReturnType() == int.class)
				{
					return 7;
				}
				return m.getReturnType() == String.class ? SECRET : null;
			});
	}

	/**
	 * The shared settings never carry a webhook, whoever saves them: a webhook travels only in the leader's
	 * separate "Share webhooks with the group" document ({@link GroupWebhooks}, SharedWebhooksTest).
	 */
	@Test
	public void aWebhookNeverTravelsInTheSettingsPayloadUnlessTheLeaderShares()
	{
		for (GroupSettingsSchema.Setting s : GroupSettingsSchema.ALL)
		{
			String key = s.key.toLowerCase(Locale.ROOT);
			assertFalse(s.key, key.contains("url") || key.contains("webhook") || key.contains("mention"));
		}
		GroupSigner.Identity leader = GroupSigner.Identity.create();
		GroupSettings doc = GroupSettings.next(null, GroupSettingsSchema.seed(everythingSet()), "Alex", leader, NOW);
		String payload = GovernanceCodec.encode(new Gson(), doc);
		assertFalse(payload, payload.contains("SECRETTOKEN"));
		assertFalse(payload, payload.contains("discord.com"));

		GroupWebhooks off = GroupWebhooks.next(null, "groupship", false, Webhooks.of(everythingSet()), "Alex", leader,
			NOW);
		assertFalse("sharing off carries none", GovernanceCodec.encode(new Gson(), off).contains("SECRETTOKEN"));
		GroupWebhooks on = GroupWebhooks.next(off, "groupship", true, Webhooks.of(everythingSet()), "Alex", leader,
			NOW + 1);
		assertTrue("the leader shares", GovernanceCodec.encode(new Gson(), on).contains("SECRETTOKEN"));
	}

	@Test
	public void theFirstLeaderSaveSeedsFromTheLeadersConfig()
	{
		Map<String, Long> seeded = GroupSettingsSchema.seed(everythingSet());
		assertEquals(GroupSettingsSchema.ALL.size(), seeded.size());
		assertEquals(7L, (long) seeded.get("eventLevelMin"));
		assertEquals(1L, (long) seeded.get(GroupSettingsSchema.discordKey(GroupEvent.Type.PET)));
		assertEquals(1L, (long) seeded.get(GroupSettingsSchema.overlayKey(GroupEvent.Type.DEATH)));
		assertEquals(1L, (long) seeded.get(GroupSettingsSchema.digestKey(GroupEvent.Category.DROPS)));

		Map<String, Long> defaults = GroupSettingsSchema.seed(DEFAULTS);
		assertEquals(0L, (long) defaults.get(GroupSettingsSchema.discordKey(GroupEvent.Type.PET)));
		assertEquals((long) DEFAULTS.eventDropMinValue(), (long) defaults.get("eventDropMinValue"));
	}

	@Test
	public void everyEventKindAndDigestCategoryIsAGroupSetting()
	{
		for (GroupEvent.Type t : GroupEvent.Type.values())
		{
			if (t != GroupSettingsSchema.OWN_DISCORD)
			{
				assertNotNull(GroupSettingsSchema.get(GroupSettingsSchema.discordKey(t)));
			}
			assertNotNull(GroupSettingsSchema.get(GroupSettingsSchema.overlayKey(t)));
		}
		for (GroupEvent.Category c : GroupEvent.Category.values())
		{
			assertNotNull(GroupSettingsSchema.get(GroupSettingsSchema.digestKey(c)));
		}
		for (String key : new String[]{"eventDropMinValue", "eventStorageMinValue", "eventLevelMin", "eventLevelEvery",
			"eventBackAfterDays", "eventClueMinValue", "eventKcEvery", "eventGravestoneWarnMinutes", "discordDigestHour",
			"discordQuietStart", "discordQuietEnd", "discordOfflineGrace", "discordEasterEggs", "discordLegendAt",
			"discordFreeloaderAt", "discordNoPluginEvents"})
		{
			assertNotNull(key, GroupSettingsSchema.get(key));
		}
	}

	@Test
	public void sanitizeClampsAndDropsUnknownKeys()
	{
		Map<String, Long> in = GroupSettingsSchema.seed(DEFAULTS);
		in.put("discordQuietStart", 99L);
		in.put("eventLevelEvery", 0L);
		in.put(GroupSettingsSchema.discordKey(GroupEvent.Type.PET), 5L);
		in.put("discordWebhookUrl", 1L);
		Map<String, Long> out = GroupSettingsSchema.sanitize(in);
		assertEquals(23L, (long) out.get("discordQuietStart"));
		assertEquals(1L, (long) out.get("eventLevelEvery"));
		assertEquals(1L, (long) out.get(GroupSettingsSchema.discordKey(GroupEvent.Type.PET)));
		assertFalse(out.containsKey("discordWebhookUrl"));
	}

	@Test
	public void withoutGroupSettingsEachMemberKeepsTheirOwnConfig()
	{
		GroupSettingsSchema.Resolved r = new GroupSettingsSchema.Resolved(everythingSet(), null);
		assertEquals(7, r.value("eventLevelMin"));
		assertTrue(r.on(GroupSettingsSchema.discordKey(GroupEvent.Type.PET)));
	}

	@Test
	public void groupSettingsOverrideTheMembersOwnConfig()
	{
		Map<String, Long> values = GroupSettingsSchema.seed(DEFAULTS);
		values.put("eventLevelMin", 70L);
		GroupSettings doc = GroupSettings.next(null, values, "Alex", GroupSigner.Identity.create(), NOW);
		GroupSettingsSchema.Resolved r = new GroupSettingsSchema.Resolved(everythingSet(), doc);
		assertEquals(70, r.value("eventLevelMin"));
		assertFalse("the group's switch, not this member's", r.on(GroupSettingsSchema.discordKey(GroupEvent.Type.PET)));
	}

	@Test
	public void theFullestDocumentFitsOneMessage()
	{
		GroupSigner.Identity id = GroupSigner.Identity.create();
		GroupSettings doc = null;
		for (int i = 0; i < 40; i++)
		{
			Map<String, Long> values = GroupSettingsSchema.seed(DEFAULTS);
			for (GroupSettingsSchema.Setting s : GroupSettingsSchema.ALL)
			{
				values.put(s.key, i % 2 == 0 ? s.max : s.min);
			}
			doc = GroupSettings.next(doc, values, "A twelve char", id, NOW + i);
		}
		String payload = GovernanceCodec.encode(new Gson(), doc);
		assertTrue(payload.length() + " chars", payload.length() < GroupCodec.MAX_PAYLOAD_CHARS);
		assertTrue(doc.history.size() <= GroupSettings.MAX_HISTORY);
	}
}

package com.vinnyvangogh.groupironman;

import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import org.slf4j.LoggerFactory;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class GroupSyncTest
{
	private static final String KEY = "00112233445566778899aabbccddeeff";
	private static final String GROUP = "GroupShip";

	/** Stands in for PartyService: remembers every change. */
	private static final class FakeParty implements GroupSync.Party
	{
		String current;
		final List<String> changes = new ArrayList<>();

		@Override
		public String passphrase()
		{
			return current;
		}

		@Override
		public void changeParty(String passphrase)
		{
			changes.add(passphrase);
			current = passphrase;
		}
	}

	@Test
	public void statesFollowTheSettingsTheKeyAndTheParty()
	{
		FakeParty party = new FakeParty();
		GroupSync sync = new GroupSync(party);
		assertEquals(GroupSync.State.OFF, sync.state(false, GROUP, KEY));
		assertEquals(GroupSync.State.NO_KEY, sync.state(true, GROUP, ""));
		assertEquals(GroupSync.State.NO_GROUP, sync.state(true, "", KEY));
		assertEquals(GroupSync.State.READY, sync.state(true, GROUP, KEY));
		party.current = "raids-with-friends";
		assertEquals(GroupSync.State.OTHER_PARTY, sync.state(true, GROUP, KEY));
		party.current = GroupKey.passphrase(GROUP, KEY);
		assertEquals(GroupSync.State.CONNECTED, sync.state(true, GROUP, KEY));
		party.current = GroupKey.passphrase(GROUP, "ffeeddccbbaa99887766554433221100");
		assertEquals("our own party with an old key", GroupSync.State.STALE, sync.state(true, GROUP, KEY));
	}

	@Test
	public void nothingJoinsWithoutTheClick()
	{
		FakeParty party = new FakeParty();
		GroupSync sync = new GroupSync(party);
		sync.state(true, GROUP, KEY);
		assertTrue(party.changes.isEmpty());
		assertTrue(sync.join(true, GROUP, KEY));
		assertEquals(GroupKey.passphrase(GROUP, KEY), party.current);
	}

	@Test
	public void joinNeverReplacesAPartyThePlayerJoined()
	{
		FakeParty party = new FakeParty();
		party.current = "raids-with-friends";
		GroupSync sync = new GroupSync(party);
		assertFalse(sync.join(true, GROUP, KEY));
		assertEquals("raids-with-friends", party.current);
		assertTrue(party.changes.isEmpty());

		// Only the explicit Switch button moves them.
		assertTrue(sync.switchParty(true, GROUP, KEY));
		assertEquals(GroupKey.passphrase(GROUP, KEY), party.current);
	}

	@Test
	public void switchDoesNothingUnlessInAnotherParty()
	{
		FakeParty party = new FakeParty();
		GroupSync sync = new GroupSync(party);
		assertFalse(sync.switchParty(true, GROUP, KEY));
		assertTrue(party.changes.isEmpty());
	}

	@Test
	public void leavesOnlyThePartyItJoined()
	{
		FakeParty party = new FakeParty();
		GroupSync sync = new GroupSync(party);
		assertFalse("never joined: nothing to leave", sync.leaveOwn());

		party.current = "raids-with-friends";
		assertFalse(sync.leaveOwn());
		assertEquals("raids-with-friends", party.current);

		party.current = null;
		sync.join(true, GROUP, KEY);
		assertTrue(sync.inOwnParty());
		assertTrue(sync.leaveOwn());
		assertNull(party.current);
	}

	@Test
	public void ifThePlayerMovedToAnotherPartyShutdownLeavesThemThere()
	{
		FakeParty party = new FakeParty();
		GroupSync sync = new GroupSync(party);
		sync.join(true, GROUP, KEY);
		// They joined a raid party from the Party panel afterwards.
		party.current = "raids-with-friends";
		assertFalse(sync.leaveOwn());
		assertEquals("raids-with-friends", party.current);
	}

	@Test
	public void aNewKeyRejoinsOnTheClickFromOurOwnOldParty()
	{
		FakeParty party = new FakeParty();
		GroupSync sync = new GroupSync(party);
		sync.join(true, GROUP, KEY);
		String newKey = "ffeeddccbbaa99887766554433221100";
		assertEquals(GroupSync.State.STALE, sync.state(true, GROUP, newKey));
		assertTrue(sync.join(true, GROUP, newKey));
		assertEquals(GroupKey.passphrase(GROUP, newKey), party.current);
	}

	@Test
	public void theKeyIsNeverLogged()
	{
		Logger root = (Logger) LoggerFactory.getLogger(org.slf4j.Logger.ROOT_LOGGER_NAME);
		ListAppender<ILoggingEvent> appender = new ListAppender<>();
		appender.start();
		root.addAppender(appender);
		try
		{
			FakeParty party = new FakeParty();
			GroupSync sync = new GroupSync(party);
			sync.state(true, GROUP, KEY);
			sync.join(true, GROUP, KEY);
			sync.leaveOwn();
			party.current = "x";
			sync.switchParty(true, GROUP, KEY);
			GroupKey.keyFrom(net.runelite.api.ChatMessageType.CLAN_GIM_CHAT, GroupKey.shareLine(KEY));
			GroupKey.passphrase(GROUP, KEY);
		}
		finally
		{
			root.detachAppender(appender);
		}
		for (ILoggingEvent e : appender.list)
		{
			assertFalse(e.getFormattedMessage(), e.getFormattedMessage().contains(KEY));
		}
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.Skill;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Hiscore levels for members without the plugin: the 6 h throttle, backoff, precedence and what the card shows. */
public class HiscoreBookTest
{
	private static final long NOW = TimeUnit.DAYS.toMillis(100);
	private static final long MIN = TimeUnit.MINUTES.toMillis(1);
	private static final long HOUR = TimeUnit.HOURS.toMillis(1);
	private static final RegionNames REGIONS = RegionNames.parse("");
	private static final FakeItems ITEMS = new FakeItems();

	private static Map<String, Integer> levels()
	{
		Map<String, Integer> out = new LinkedHashMap<>();
		out.put("Attack", 60);
		out.put("Hitpoints", 70);
		out.put("Prayer", 52);
		return out;
	}

	/** Bob is in the Group channel on W330; Alex is on the roster but offline. */
	private static GamePresence bobOnline()
	{
		GroupMembers roster = GroupMembers.of("Ship", Arrays.asList("Alex", "Bob", "Me"));
		Map<String, Integer> channel = new HashMap<>();
		channel.put("Bob", 330);
		channel.put("Me", 330);
		return GamePresence.read(roster, channel, null);
	}

	private static PanelModel.MemberCard card(GroupRoster roster, GamePresence game, String name)
	{
		List<PanelModel.MemberCard> cards = PanelModel.members(roster, Arrays.asList("Alex", "Bob", "Me"), REGIONS,
			ITEMS, "Me", game, NOW);
		for (PanelModel.MemberCard c : cards)
		{
			if (c.name.equals(name))
			{
				return c;
			}
		}
		throw new AssertionError("no card for " + name);
	}

	// ---- The throttle, with a fake clock ----

	@Test
	public void looksUpOnlyWhenAskedAndAtMostOnceEverySixHours()
	{
		HiscoreBook book = new HiscoreBook();
		assertFalse("no login or coming online: nothing starts", book.begin("Bob", NOW, false));
		assertTrue(book.begin("Bob", NOW, true));
		assertFalse("already in flight", book.begin("Bob", NOW, true));
		book.succeeded("Bob", levels(), NOW);

		assertFalse(book.begin("Bob", NOW + MIN, true));
		assertFalse("came online again 5h59m later", book.begin("bob", NOW + 6 * HOUR - MIN, true));
		assertTrue("6 h later, asked again", book.begin("Bob", NOW + 6 * HOUR, true));
	}

	@Test
	public void sixHoursPassingAloneStartsNothing()
	{
		HiscoreBook book = new HiscoreBook();
		book.begin("Bob", NOW, true);
		book.succeeded("Bob", levels(), NOW);
		assertFalse(book.begin("Bob", NOW + 7 * HOUR, false));
	}

	@Test
	public void namesMatchAsTheGameMatchesThem()
	{
		HiscoreBook book = new HiscoreBook();
		book.begin("Iron Bob", NOW, true);
		book.succeeded("Iron Bob", levels(), NOW);
		assertNotNull(book.entry("iron_bob"));
		assertFalse(book.begin("IRON-BOB", NOW + MIN, true));
	}

	@Test
	public void aClockThatWentBackDoesNotBlockLookupsForGood()
	{
		HiscoreBook book = new HiscoreBook();
		book.restore("Bob", NOW + 30 * 24 * HOUR, levels());
		assertTrue(book.begin("Bob", NOW, true));
	}

	// ---- Failures back off, never storm ----

	@Test
	public void aFailureRetriesOnItsOwnAfterABackoffThatDoublesUpToSixHours()
	{
		assertEquals(15 * MIN, HiscoreBook.backoff(1));
		assertEquals(30 * MIN, HiscoreBook.backoff(2));
		assertEquals(60 * MIN, HiscoreBook.backoff(3));
		assertEquals(6 * HOUR, HiscoreBook.backoff(6));
		assertEquals(6 * HOUR, HiscoreBook.backoff(1000));

		HiscoreBook book = new HiscoreBook();
		assertTrue(book.begin("Bob", NOW, true));
		book.failed("Bob", NOW);
		assertTrue(book.unavailable("Bob"));
		assertFalse("asking again does not skip the backoff", book.begin("Bob", NOW + 14 * MIN, true));
		assertTrue("retried without being asked", book.begin("Bob", NOW + 15 * MIN, false));
		book.failed("Bob", NOW + 15 * MIN);
		assertFalse(book.begin("Bob", NOW + 44 * MIN, false));
		assertTrue(book.begin("Bob", NOW + 45 * MIN, false));
		book.succeeded("Bob", levels(), NOW + 45 * MIN);
		assertFalse(book.unavailable("Bob"));
		assertFalse("back on the 6 h throttle", book.begin("Bob", NOW + 2 * HOUR, false));
	}

	@Test
	public void aFailedLookupShowsHiscoresUnavailableAndNoNumbers()
	{
		GroupRoster roster = new GroupRoster();
		roster.hiscores().begin("Bob", NOW, true);
		roster.hiscores().failed("Bob", NOW);

		PanelModel.MemberCard bob = card(roster, bobOnline(), "Bob");
		assertEquals("Hiscores unavailable", bob.source);
		assertTrue(bob.bars.isEmpty());
		assertTrue(bob.skills.isEmpty());
	}

	@Test
	public void aFailedRefreshKeepsTheLevelsAlreadyRead()
	{
		GroupRoster roster = new GroupRoster();
		roster.hiscores().restore("Bob", NOW - 7 * HOUR, levels());
		roster.hiscores().begin("Bob", NOW, true);
		roster.hiscores().failed("Bob", NOW);

		PanelModel.MemberCard bob = card(roster, bobOnline(), "Bob");
		assertEquals("From hiscores, 7h ago (hiscores unavailable)", bob.source);
		assertEquals(3, bob.skills.size());
	}

	// ---- What the card shows ----

	@Test
	public void anOnlineMemberWithoutThePluginShowsHiscoreLevelsAndDimmedAssumedRunAndSpec()
	{
		GroupRoster roster = new GroupRoster();
		roster.hiscores().restore("Bob", NOW - 2 * HOUR, levels());

		PanelModel.MemberCard bob = card(roster, bobOnline(), "Bob");
		assertTrue(bob.online);
		assertEquals("From hiscores, 2h ago", bob.source);
		assertEquals(4, bob.bars.size());

		PanelModel.Bar hp = bob.bars.get(0);
		assertEquals("70/70", hp.text());
		assertFalse(hp.assumed);
		assertEquals("HP 70/70 (from hiscores)", hp.tooltip());
		assertEquals("52/52", bob.bars.get(1).text());

		PanelModel.Bar run = bob.bars.get(2);
		PanelModel.Bar spec = bob.bars.get(3);
		assertEquals("Run", run.label);
		assertEquals("100/100", run.text());
		assertTrue(run.assumed);
		assertEquals("Run 100/100 (assumed, not shared)", run.tooltip());
		assertEquals("Spec", spec.label);
		assertTrue(spec.assumed);
		assertEquals("Spec 100/100 (assumed, not shared)", spec.tooltip());

		assertEquals("Attack", bob.skills.get(0).skill);
		assertEquals("60", bob.skills.get(0).text());
	}

	@Test
	public void anOfflineOrNeverSeenMemberShowsLevelsButNoOrbs()
	{
		GroupRoster roster = new GroupRoster();
		roster.hiscores().restore("Alex", NOW - HOUR, levels());

		PanelModel.MemberCard alex = card(roster, bobOnline(), "Alex");
		assertFalse(alex.online);
		assertTrue(alex.bars.isEmpty());
		assertEquals(3, alex.skills.size());
		assertEquals("From hiscores, 1h ago", alex.source);
	}

	@Test
	public void sharedPluginDataAlwaysWinsOverHiscores()
	{
		GroupRoster roster = new GroupRoster();
		Map<String, MemberStats.Level> shared = new LinkedHashMap<>();
		shared.put("Attack", new MemberStats.Level(99, 99));
		shared.put("Hitpoints", new MemberStats.Level(99, 80));
		roster.putStats("Bob", new MemberStats(shared, 40, 25, 330, 0));
		roster.heard("Bob", NOW - MIN);
		roster.hiscores().restore("Bob", NOW - HOUR, levels());

		PanelModel.MemberCard bob = card(roster, bobOnline(), "Bob");
		assertNull("no hiscore line when the member shares", bob.source);
		assertEquals("80/99", bob.bars.get(0).text());
		assertEquals("40/100", bob.bars.get(1).text());
		assertFalse(bob.bars.get(1).assumed);
		assertNull(bob.bars.get(1).note);
		assertEquals("99", bob.skills.get(0).text());
	}

	@Test
	public void aMemberWhoNeverSharedItemsHasNoItemsNotMadeUpOnes()
	{
		GroupRoster roster = new GroupRoster();
		roster.hiscores().restore("Bob", NOW - HOUR, levels());
		assertTrue(card(roster, bobOnline(), "Bob").items.isEmpty());
		assertTrue(card(roster, bobOnline(), "Alex").items.isEmpty());
	}

	@Test
	public void aMemberWhoSharedItemsBeforeKeepsThemWithHiscoreLevels()
	{
		GroupRoster roster = new GroupRoster();
		Map<Integer, Integer> inv = new LinkedHashMap<>();
		inv.put(FakeItems.SHARK, 5);
		roster.putCarried("Alex", new GroupCodec.Carried(inv, Collections.emptyMap()));
		roster.hiscores().restore("Alex", NOW - HOUR, levels());

		PanelModel.MemberCard alex = card(roster, bobOnline(), "Alex");
		assertEquals("Inventory", alex.items.get(0).title);
		assertEquals(3, alex.skills.size());
	}

	@Test
	public void nothingLookedUpShowsNoSourceLine()
	{
		assertNull(card(new GroupRoster(), bobOnline(), "Bob").source);
	}

	// ---- Reading a hiscore result, and the cache ----

	@Test
	public void readsSkillLevelsNamedAsSharedStatsAndSkipsUnrankedAndActivities()
	{
		Map<HiscoreSkill, Skill> skills = new EnumMap<>(HiscoreSkill.class);
		skills.put(HiscoreSkill.OVERALL, new Skill(1, 1500, 1L));
		skills.put(HiscoreSkill.ATTACK, new Skill(10, 60, 273_742L));
		skills.put(HiscoreSkill.RUNECRAFT, new Skill(-1, -1, -1L));
		skills.put(HiscoreSkill.HITPOINTS, new Skill(10, 70, 737_627L));
		skills.put(HiscoreSkill.ZULRAH, new Skill(5, 120, -1L));
		Map<String, Integer> out = HiscoreBook.levels(new HiscoreResult("Bob", skills));

		assertEquals(Integer.valueOf(60), out.get("Attack"));
		assertEquals(Integer.valueOf(70), out.get("Hitpoints"));
		assertEquals(2, out.size());
		assertTrue(HiscoreBook.levels(null).isEmpty());
	}

	@Test
	public void lookupsSurviveARestartWithWhenTheyWereRead()
	{
		GroupRoster before = new GroupRoster();
		before.hiscores().restore("Bob", NOW - 2 * HOUR, levels());
		before.hiscores().begin("Alex", NOW, true);
		before.hiscores().failed("Alex", NOW);
		Gson gson = new Gson();

		GroupRoster after = new GroupRoster();
		assertTrue(GroupCache.read(gson, GroupCache.write(gson, before), after));
		HiscoreBook.Entry bob = after.hiscores().entry("Bob");
		assertEquals(NOW - 2 * HOUR, bob.at);
		assertEquals(levels(), bob.levels);
		assertFalse("failures are not kept", after.hiscores().unavailable("Alex"));
		assertFalse("and still throttled after the restart", after.hiscores().begin("Bob", NOW, true));
	}

	@Test
	public void aHostileCacheEntryIsCleaned()
	{
		Gson gson = new Gson();
		String json = "{\"v\":1,\"hiscores\":{\"bob\":{\"ts\":5,\"l\":{\"Attack\":99,\"Magic\":9000,\"Prayer\":-3,"
			+ "\"Mining\":\"x\"}},\"alex\":{\"l\":{}},\"cat\":7}}";
		GroupRoster roster = new GroupRoster();
		assertTrue(GroupCache.read(gson, json, roster));
		assertEquals(Collections.singletonMap("Attack", 99), roster.hiscores().entry("Bob").levels);
		assertNull(roster.hiscores().entry("alex"));
	}

	@Test
	public void cameOnlineIsOnlyMembersWhoWereNotOnlineBefore()
	{
		GroupMembers roster = GroupMembers.of("Ship", Arrays.asList("Alex", "Bob"));
		Map<String, Integer> first = new HashMap<>();
		first.put("Alex", 301);
		Map<String, Integer> second = new HashMap<>(first);
		second.put("Bob", 302);
		GamePresence a = GamePresence.read(roster, first, null);
		GamePresence b = GamePresence.read(roster, second, null);

		assertEquals(Arrays.asList("Alex"), GamePresence.cameOnline(roster.names(), GamePresence.UNKNOWN, a));
		assertEquals(Arrays.asList("Bob"), GamePresence.cameOnline(roster.names(), a, b));
		assertTrue(GamePresence.cameOnline(roster.names(), b, a).isEmpty());
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The bundled wiki drop table, and that it reaches a list line no quest names. */
public class ItemDropsTest
{
	private static final int DRAGON_WARHAMMER = 13576;

	@Test
	public void dragonWarhammerIsALizardmanShamanDrop()
	{
		List<ShopSources.Source> drops = ItemDrops.bundled().of(DRAGON_WARHAMMER);
		assertEquals(1, drops.size());
		assertEquals("Drop: Lizardman shaman (1/3,000)", drops.get(0).describe());
	}

	@Test
	public void everyLineOfTheBundledTableParses()
	{
		String text = RegionNames.resource(ItemDrops.RESOURCE);
		long lines = text.lines().filter(l -> !l.trim().isEmpty() && !l.trim().startsWith("#")).count();
		assertTrue("the table is bundled", lines > 20);
		assertEquals("no line was skipped as malformed", lines, ItemDrops.bundled().size());
	}

	@Test
	public void aCustomItemNoQuestNamesGetsItsDropsNotNoKnownShop()
	{
		ShopSources.Viewer viewer = new ShopSources.Viewer(Collections.emptyMap(), QuestProgress.UNKNOWN);
		ShopSources.Options o = ShopSources.forViewer(DRAGON_WARHAMMER, null, viewer, QuestData.empty(),
			ItemDrops.bundled());
		assertEquals("Get: Drop: Lizardman shaman (1/3,000)", ShoppingTab.sourceText(o));
	}

	@Test
	public void anItemInNeitherSaysSoPlainly()
	{
		ShopSources.Viewer viewer = new ShopSources.Viewer(Collections.emptyMap(), QuestProgress.UNKNOWN);
		ShopSources.Options o = ShopSources.forViewer(1, null, viewer, QuestData.empty(), ItemDrops.bundled());
		assertTrue(o.sources.isEmpty());
		assertEquals("Not sold in any shop, and no drop on file: check the wiki.", ShoppingTab.sourceText(o));
	}

	@Test
	public void malformedLinesAreSkipped()
	{
		ItemDrops d = ItemDrops.parse("# note\nx|Bad|Goblin=1/2\n5|No drops\n7|Ok|Goblin=1/2|Imp\n");
		assertEquals(1, d.size());
		assertEquals(2, d.of(7).size());
		assertFalse(d.of(7).get(1).describe().contains("("));
	}
}

package com.vinnyvangogh.groupironman;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** "Path to": the nearest place to get each item, from where the player stands. */
public class ItemPathsTest
{
	private static final int NET = 305;
	private static final int ROPE = 954;
	private static final int SHARK = 385;

	/** Harry's is in Catherby, the Port Sarim shop in the south; the guild needs 68 Fishing. */
	private static final String DATA = "{"
		+ "\"quests\":[{\"id\":1,\"name\":\"Q\",\"items\":["
		+ "{\"name\":\"Big fishing net\",\"item_id\":305,\"sources\":[],"
		+ "\"shop_names\":[\"Fishing Guild Shop\",\"Harry's Fishing Shop\",\"Port Sarim shop\"]},"
		+ "{\"name\":\"Rope\",\"item_id\":954,\"sources\":[],\"shop_names\":[\"Port Sarim shop\",\"No tile shop\"]}]}],"
		+ "\"shops\":["
		+ "{\"name\":\"Fishing Guild Shop\",\"x\":2611,\"y\":3393,\"reachability\":{\"required_skills\":"
		+ "[{\"skill\":\"fishing\",\"level\":68}]}},"
		+ "{\"name\":\"Harry's Fishing Shop\",\"x\":2833,\"y\":3443},"
		+ "{\"name\":\"Port Sarim shop\",\"x\":3014,\"y\":3224},"
		+ "{\"name\":\"No tile shop\"}]}";

	private static final List<ItemPaths.Stop> BANKS = ItemPaths.parseBanks(Arrays.asList(
		"# comment",
		"3185 3438 0\tVarrock West",
		"2807 3441 0\tCatherby",
		"not a line",
		"3208 3220 2\tLumbridge Castle"));

	private static final WorldPoint CATHERBY = new WorldPoint(2810, 3440, 0);
	private static final WorldPoint PORT_SARIM = new WorldPoint(3010, 3210, 0);

	private static QuestData data() throws IOException
	{
		return ShopSourcesTest.data(DATA);
	}

	private static ShopSources.Viewer viewer()
	{
		return new ShopSources.Viewer(new HashMap<>(), QuestProgress.UNKNOWN);
	}

	private static ShopAllocation.Holdings holdings(int itemId, long alice, long storage)
	{
		Map<String, Map<Integer, Long>> held = new LinkedHashMap<>();
		held.put("Alice", Collections.singletonMap(itemId, alice));
		return new ShopAllocation.Holdings(held, Collections.singletonMap(itemId, storage));
	}

	private static ItemPaths.Planner planner(QuestData d, ShopAllocation.Holdings h, WorldPoint here)
	{
		return new ItemPaths.Planner(d, viewer(), h, BANKS, here);
	}

	/** One shopping row: Alice needs {@code need} of the item, holding {@code alice}, with {@code storage} in storage. */
	private static ShoppingBoard.Row row(QuestData d, int itemId, long need, long alice, long storage)
	{
		Map<String, Map<Integer, ShopNeeds.Need>> needs = new LinkedHashMap<>();
		needs.put("Alice", Collections.singletonMap(itemId,
			new ShopNeeds.Need(itemId, "Item", need, true, false, Collections.singleton("Q"))));
		ShopAllocation.Line line = ShopAllocation.of(needs, holdings(itemId, alice, storage), id -> true).get(0);
		return new ShoppingBoard.Row(line, ShopSources.forViewer(d.item(itemId), viewer(), d));
	}

	private static List<String> names(List<ItemPaths.Stop> stops)
	{
		List<String> out = new ArrayList<>();
		stops.forEach(s -> out.add(s.name));
		return out;
	}

	@Test
	public void theNearestShopComesFirstFromWhereThePlayerStands() throws IOException
	{
		QuestData d = data();
		ShoppingBoard.Row r = row(d, NET, 1, 0, 0);

		List<ItemPaths.Stop> fromCatherby = planner(d, holdings(NET, 0, 0), CATHERBY).shopping(r);
		assertEquals(Arrays.asList("Harry's Fishing Shop", "Port Sarim shop"), names(fromCatherby));
		assertEquals("Path to: Harry's Fishing Shop", fromCatherby.get(0).label());
		assertEquals(new WorldPoint(2833, 3443, 0), fromCatherby.get(0).at);

		List<ItemPaths.Stop> fromSarim = planner(d, holdings(NET, 0, 0), PORT_SARIM).shopping(r);
		assertEquals("Port Sarim shop", fromSarim.get(0).name);
	}

	/** A shop the player cannot be served at, or one with no tile, is never a target. */
	@Test
	public void gatedShopsAndShopsWithoutATileAreNeverTargets() throws IOException
	{
		QuestData d = data();
		WorldPoint atTheGuild = new WorldPoint(2611, 3393, 0);
		assertEquals(Arrays.asList("Harry's Fishing Shop", "Port Sarim shop"),
			names(planner(d, holdings(NET, 0, 0), atTheGuild).shopping(row(d, NET, 1, 0, 0))));
		assertEquals(Collections.singletonList("Port Sarim shop"),
			names(planner(d, holdings(ROPE, 0, 0), CATHERBY).shopping(row(d, ROPE, 1, 0, 0))));
	}

	/** Held in group storage: the nearest bank, since group storage opens from any bank. */
	@Test
	public void heldInGroupStorageGoesToTheNearestBank() throws IOException
	{
		QuestData d = data();
		// Storage covers it all: the line is done, but someone still has to take it out.
		ShoppingBoard.Row covered = row(d, SHARK, 5, 0, 5);
		List<ItemPaths.Stop> stops = planner(d, holdings(SHARK, 0, 5), new WorldPoint(3200, 3430, 0)).shopping(covered);
		assertEquals("Varrock West bank", stops.get(0).name);
		assertTrue(stops.get(0).bank);

		// Part from storage, part to buy: banks and shops compete, nearest wins.
		ShoppingBoard.Row partly = row(d, NET, 3, 0, 1);
		assertEquals("Catherby bank", planner(d, holdings(NET, 0, 1), CATHERBY).shopping(partly).get(0).name);
	}

	@Test
	public void aDoneLineWithNothingInStorageHasNowhereToGo() throws IOException
	{
		QuestData d = data();
		assertTrue(planner(d, holdings(NET, 1, 0), CATHERBY).shopping(row(d, NET, 1, 1, 0)).isEmpty());
	}

	/** Logged out: no position, so the data's order stands and nothing is dropped. */
	@Test
	public void withoutAPositionTheDataOrderStands() throws IOException
	{
		QuestData d = data();
		assertEquals(Arrays.asList("Harry's Fishing Shop", "Port Sarim shop"),
			names(planner(d, holdings(NET, 0, 0), null).shopping(row(d, NET, 1, 0, 0))));
	}

	@Test
	public void anotherPlaneCostsExtra()
	{
		List<ItemPaths.Stop> stops = ItemPaths.nearestFirst(BANKS, new WorldPoint(3208, 3220, 0));
		// Lumbridge Castle's bank is right above, on plane 2; Varrock West is 218 tiles away.
		assertEquals("Lumbridge Castle bank", stops.get(0).name);
		assertTrue(ItemPaths.cost(new WorldPoint(3208, 3220, 0), stops.get(0).at) > 0);
	}

	private static RequestList request(boolean closed, int itemId)
	{
		return new RequestList("r1", "Alice", "Mine", Collections.singletonMap(itemId, 5), Collections.emptySet(),
			closed, false, 1, 1L, 1L, RequestList.ADDED);
	}

	private static RequestBoard.Row requestRow(int itemId, long have)
	{
		return new RequestBoard.Row(itemId, "Item", 5, have, false, Collections.emptyList());
	}

	@Test
	public void requestItemsPathToShopsOrToStorage() throws IOException
	{
		QuestData d = data();
		// A shop item, nothing held: the shop.
		assertEquals("Harry's Fishing Shop",
			planner(d, holdings(NET, 0, 0), CATHERBY).request(request(false, NET), requestRow(NET, 0)).get(0).name);
		// No shop in the data, some in storage: a bank.
		assertEquals("Catherby bank",
			planner(d, holdings(SHARK, 0, 2), CATHERBY).request(request(false, SHARK), requestRow(SHARK, 2)).get(0).name);
		// No shop, nothing in storage: nowhere.
		assertTrue(planner(d, holdings(SHARK, 2, 0), CATHERBY).request(request(false, SHARK), requestRow(SHARK, 2))
			.isEmpty());
		// Done, or the request is closed: nowhere.
		assertTrue(planner(d, holdings(NET, 5, 0), CATHERBY).request(request(false, NET), requestRow(NET, 5)).isEmpty());
		assertTrue(planner(d, holdings(NET, 0, 0), CATHERBY).request(request(true, NET), requestRow(NET, 0)).isEmpty());
	}

	/** "Path to next": nearest stop first, then nearest from there; one stop serves every item it sells. */
	@Test
	public void theTourWalksNearestNextAndSharesStops()
	{
		ItemPaths.Stop harry = new ItemPaths.Stop("Harry's", new WorldPoint(2833, 3443, 0), false);
		ItemPaths.Stop sarim = new ItemPaths.Stop("Sarim", new WorldPoint(3014, 3224, 0), false);
		ItemPaths.Stop varrock = new ItemPaths.Stop("Varrock", new WorldPoint(3185, 3438, 0), false);
		List<List<ItemPaths.Stop>> needs = Arrays.asList(
			Arrays.asList(varrock),
			Arrays.asList(sarim, harry),
			Arrays.asList(sarim));

		assertEquals(Arrays.asList("Harry's", "Sarim", "Varrock"), names(ItemPaths.tour(needs, CATHERBY)));
		assertEquals(Arrays.asList("Varrock", "Sarim"), names(ItemPaths.tour(needs, new WorldPoint(3190, 3440, 0))));
		assertTrue(ItemPaths.tour(Collections.emptyList(), CATHERBY).isEmpty());
	}

	@Test
	public void aTargetWhoseListIsGoneHasNowhereToGo() throws IOException
	{
		QuestData d = data();
		ItemPaths.Planner p = planner(d, holdings(NET, 0, 0), CATHERBY);
		assertTrue(ItemPaths.forTarget(ItemPaths.Target.listItem("gone", NET), Collections.emptyList(),
			Collections.emptyList(), p).isEmpty());
		assertTrue(ItemPaths.forTarget(ItemPaths.Target.next("gone"), Collections.emptyList(),
			Collections.emptyList(), p).isEmpty());
		assertTrue(ItemPaths.forTarget(ItemPaths.Target.requestItem("gone", NET), Collections.emptyList(),
			Collections.emptyList(), p).isEmpty());
	}

	@Test
	public void aRequestTargetResolvesThroughItsCard() throws IOException
	{
		QuestData d = data();
		ItemPaths.Planner p = planner(d, holdings(NET, 0, 0), CATHERBY);
		RequestBoard.Card open = new RequestBoard.Card(request(false, NET), Collections.singletonList(requestRow(NET, 0)));
		assertEquals("Harry's Fishing Shop", ItemPaths.forTarget(ItemPaths.Target.requestItem("r1", NET),
			Collections.emptyList(), Collections.singletonList(open), p).get(0).name);
	}

	@Test
	public void theBundledBankTableLoads()
	{
		List<ItemPaths.Stop> banks = ItemPaths.loadBanks();
		assertTrue("expected the bundled banks, got " + banks.size(), banks.size() >= 20);
		assertTrue(names(banks).contains("Lumbridge Castle bank"));
		for (ItemPaths.Stop b : banks)
		{
			assertTrue(b.name, b.bank);
		}
	}

	@Test
	public void targetsAreEqualByWhatTheyPointAt()
	{
		assertEquals(ItemPaths.Target.listItem("a", 1), ItemPaths.Target.listItem("a", 1));
		assertTrue(!ItemPaths.Target.listItem("a", 1).equals(ItemPaths.Target.requestItem("a", 1)));
		assertEquals(ItemPaths.Target.next("a").hashCode(), ItemPaths.Target.next("a").hashCode());
	}
}

package com.vinnyvangogh.groupironman;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static com.vinnyvangogh.groupironman.FakeItems.*;

/** One search engine for the panel and ::find, and ::find never opens anything. */
public class ItemQueryTest
{
	private static final FakeItems ITEMS = new FakeItems();
	private static final long NOW = 1_000_000_000L;

	private static Map<Integer, Integer> items(int... pairs)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			out.put(pairs[i], pairs[i + 1]);
		}
		return out;
	}

	@Test
	public void guamFindsEveryGuamItem()
	{
		ItemQuery q = ItemQuery.parse("guam");
		assertTrue(q.matches("Grimy guam leaf"));
		assertTrue(q.matches("Guam leaf"));
		assertTrue(q.matches("Guam potion (unf)"));
		assertFalse(q.matches("Ranarr weed"));
	}

	@Test
	public void caseWordsInAnyOrderAndAliases()
	{
		assertTrue(ItemQuery.parse("GUAM").matches("Grimy guam leaf"));
		assertTrue(ItemQuery.parse("leaf grimy").matches("Grimy guam leaf"));
		assertTrue(ItemQuery.parse("  grimy   guam ").matches("Grimy guam leaf"));
		assertTrue(ItemQuery.parse("ppot").matches("Prayer potion(4)"));
		assertTrue(ItemQuery.parse("dwh").matches("Dragon warhammer"));
		assertFalse("one word must still match", ItemQuery.parse("leaf ranarr").matches("Grimy guam leaf"));
		assertNull(ItemQuery.parse("g"));
		assertNull(ItemQuery.parse(null));
	}

	@Test
	public void findCommandAndThePanelGiveTheSameAnswer()
	{
		GroupRoster roster = new GroupRoster();
		roster.putBank("GroupShip", new BankSnapshot(NOW - 60_000, items(GRIMY_GUAM, 15, GUAM_UNF, 3, SHARK, 9)));

		List<PanelModel.FindRow> panel = PanelModel.find("guam", roster, ITEMS, NOW);
		assertEquals(2, panel.size());
		assertEquals("Grimy guam leaf - 15 in GroupShip's bank", panel.get(0).text);
		assertEquals(GRIMY_GUAM, panel.get(0).itemId);
		assertEquals("Guam potion (unf) - 3 in GroupShip's bank", panel.get(1).text);

		List<String> chat = FindCommand.answer("guam", roster.searchSources(), roster.log().entries(), ITEMS, NOW);
		assertEquals(2, chat.size());
		assertEquals("Grimy guam leaf: GroupShip bank 15 (1m ago)", chat.get(0));
		assertEquals("Guam potion (unf): GroupShip bank 3 (1m ago)", chat.get(1));
	}

	@Test
	public void findCommandOnlyReturnsText()
	{
		// The ::find answer is computed from data alone: no client, nothing to open.
		List<String> out = FindCommand.answer("guam", Collections.emptyList(), Collections.emptyList(), ITEMS, NOW);
		assertEquals(1, out.size());
		assertTrue(out.get(0), out.get(0).startsWith("Nothing found for 'guam'"));
	}

	@Test
	public void nothingButTheMapMarkersTouchesTheWorldMap() throws Exception
	{
		// ::find and the panel search must never open the world map. Only the markers
		// class may use world map APIs, and it only adds points (opened by the player's click).
		Path dir = Paths.get("src/main/java/com/vinnyvangogh/groupironman");
		List<String> offenders = new ArrayList<>();
		try (Stream<Path> files = Files.list(dir))
		{
			for (Path p : files.collect(Collectors.toList()))
			{
				String name = p.getFileName().toString();
				String code = new String(Files.readAllBytes(p), StandardCharsets.UTF_8);
				// World map APIs, not the 'groupWorldMap' setting's name.
				boolean map = code.replace("groupWorldMap", "").matches("(?s).*(WorldMap|WORLDMAP|Worldmap).*");
				if (map && !name.equals("MemberMapMarkers.java"))
				{
					offenders.add(name);
				}
			}
		}
		assertEquals(Collections.emptyList(), offenders);
		String markers = new String(Files.readAllBytes(dir.resolve("MemberMapMarkers.java")), StandardCharsets.UTF_8);
		assertFalse(markers.contains("setWorldMap") || markers.contains("openWorldMap") || markers.contains("runScript"));
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static com.vinnyvangogh.groupironman.EventFixtures.all;
import static com.vinnyvangogh.groupironman.EventFixtures.settings;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/** "Post every N levels": a group setting, for Discord and the overlay alike. */
public class LevelEveryTest
{
	private final FakeItems items = new FakeItems();
	private final List<Long> discord = new ArrayList<>();
	private final List<Long> overlay = new ArrayList<>();
	private final EventRouter router = new EventRouter(e -> discord.add(e.number), e -> overlay.add(e.number));

	private void levels(EventSettings s, int from, int to)
	{
		for (int level = from; level <= to; level++)
		{
			router.route(GroupEvent.of(GroupEvent.Type.LEVEL_UP, NOW, "Alex").text("Attack").number(level).build(), true,
				s, items);
		}
	}

	@Test
	public void everyLevelWhenNIsOne()
	{
		levels(settings(all(), all()).levels(60, 1), 58, 64);
		assertEquals(java.util.Arrays.asList(60L, 61L, 62L, 63L, 64L), discord);
		assertEquals(discord, overlay);
	}

	@Test
	public void everyFifthLevelFromTheMinimum()
	{
		levels(settings(all(), all()).levels(60, 5), 59, 66);
		assertEquals(java.util.Arrays.asList(60L, 65L), discord);
		assertEquals(discord, overlay);
	}

	@Test
	public void ninetyNineAlwaysPosts()
	{
		levels(settings(all(), all()).levels(60, 5), 97, 99);
		assertEquals(java.util.Collections.singletonList(99L), discord);
		assertEquals(discord, overlay);
	}

	@Test
	public void otherProgressKindsIgnoreN()
	{
		EventSettings s = settings(all(), all()).levels(60, 7);
		for (GroupEvent.Type t : new GroupEvent.Type[]{GroupEvent.Type.MAXED, GroupEvent.Type.COMBAT_LEVEL,
			GroupEvent.Type.TOTAL_LEVEL})
		{
			router.route(EventFixtures.sample(t), true, s, items);
		}
		assertEquals(3, discord.size());
	}

	private void jump(EventSettings s, int previous, int level)
	{
		router.route(GroupEvent.of(GroupEvent.Type.LEVEL_UP, NOW, "Alex").text("Prayer").number(level)
			.previous(previous).build(), true, s, items);
	}

	@Test
	public void aJumpOverAMultipleCounts()
	{
		EventSettings s = settings(all(), all()).levels(1, 5);
		jump(s, 3, 7);
		jump(s, 7, 9);
		jump(s, 9, 10);
		jump(s, 10, 14);
		jump(s, 14, 21);
		assertEquals("3 → 7 crossed 5, 9 → 10 lands on 10, 14 → 21 crossed 15 and 20",
			java.util.Arrays.asList(7L, 10L, 21L), discord);
		assertEquals(discord, overlay);
	}

	@Test
	public void aMembersEventWithoutThePreviousLevelUsesOneBelow()
	{
		EventSettings s = settings(all(), all()).levels(1, 5);
		jump(s, 0, 10);
		jump(s, 0, 11);
		assertEquals(java.util.Collections.singletonList(10L), discord);
	}

	/**
	 * Decision for "Combine level-ups": every-N runs first, so a streak's post
	 * only ever sees the levels that pass it (one post for 60, edited at 65).
	 * The streak reads its start from the first level that passed.
	 */
	@Test
	public void combineLevelUpsOnlySeesLevelsThatPass()
	{
		List<GroupEvent> posted = new ArrayList<>();
		EventRouter levels = new EventRouter(posted::add, e -> { });
		EventSettings s = settings(all(), all()).levels(60, 5);
		for (int level = 59; level <= 66; level++)
		{
			levels.route(GroupEvent.of(GroupEvent.Type.LEVEL_UP, NOW, "Alex").text("Attack").number(level)
				.previous(level - 1).build(), true, s, items);
		}
		assertEquals(2, posted.size());
		LevelThreads threads = new LevelThreads();
		long window = 30 * 60_000L;
		LevelThreads.Edit first = threads.level(posted.get(0), "u", NOW, window, null);
		assertNotNull("60 starts the post", first);
		assertNull("65 joins it", threads.level(posted.get(1), "u", NOW + 60_000, window, null));
		LevelThreads.Streak streak = first.streak;
		assertEquals(1, streak.cards.size());
		assertEquals(59, streak.cards.get(0).from);
		assertEquals(65, streak.cards.get(0).to);
		assertEquals("Attack 59 → 65 (+6) in 1 min", streak.cards.get(0).text());
	}

	@Test
	public void theDefaultIsEveryLevel()
	{
		GroupIronmanConfig defaults = new GroupIronmanConfig()
		{
		};
		assertEquals(1, defaults.eventLevelEvery());
		assertEquals(1, EventSettings.from(defaults).levelEvery);
		assertEquals(1, settings(all(), all()).levelEvery);
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.TimeUnit;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.DiscordWebhookTest.URL;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Level-ups of one skill as one post edited in place, through the real sender with a fake transport and clock. */
public class LevelPostsTest
{
	private static final long SEC = TimeUnit.SECONDS.toMillis(1);
	private static final long WINDOW = TimeUnit.MINUTES.toMillis(30);

	private final Gson gson = new Gson();
	private long now = 1_000_000;
	private final FakeTransport fake = new FakeTransport(() -> now);
	private final List<DiscordQueue.Post> sent = fake.sent;
	private final List<DiscordSender.Done> pending = fake.pending;
	private final DiscordSender sender = fake.sender;
	/** The Progress poster name the replacement post is sent under. */
	private String poster = "Iron Pals";
	private DiscordStyle style = DiscordStyle.EMBED;
	private LevelPosts levels = client();

	/** A client's level posts; a second one is the same client after a restart. */
	private LevelPosts client()
	{
		return new LevelPosts(sender, gson, () -> now, () -> style, () -> poster);
	}

	private static GroupEvent level(String skill, int n)
	{
		return GroupEvent.of(GroupEvent.Type.LEVEL_UP, 0, "Alex").text(skill).number(n).build();
	}

	/** A level-up that knows the level before it, as the tracker's own events do. */
	private static GroupEvent level(String skill, int from, int n)
	{
		return GroupEvent.of(GroupEvent.Type.LEVEL_UP, 0, "Alex").text(skill).number(n).previous(from).build();
	}

	private void gain(int n)
	{
		levels.level(URL, level("Prayer", n), WINDOW, null, "first " + n);
	}

	/** The engine's once-a-second tick: owed edits, then the next post. */
	private void tick()
	{
		levels.tick();
		sender.pump();
	}

	private void reply(int status, String messageId)
	{
		fake.reply(status, messageId);
	}

	/** The top card's words. */
	private static String description(DiscordQueue.Post post)
	{
		return cards(post).get(0);
	}

	/** Every card's words, top first. */
	private static List<String> cards(DiscordQueue.Post post)
	{
		List<String> out = new ArrayList<>();
		for (JsonElement embed : embeds(post))
		{
			out.add(embed.getAsJsonObject().get("description").getAsString());
		}
		return out;
	}

	private static JsonArray embeds(DiscordQueue.Post post)
	{
		return new Gson().fromJson(post.json, JsonObject.class).getAsJsonArray("embeds");
	}

	@Test
	public void threeLevelsAreOnePostAndTwoEditsEndingAtTheLast()
	{
		gain(24);
		tick();
		assertEquals("first 24", sent.get(0).json);
		assertNull(sent.get(0).edit);
		assertTrue("waits for the message id", DiscordSender.target(sent.get(0)).endsWith("?wait=true"));
		reply(200, "m1");

		now += 15 * SEC;
		gain(25);
		tick();
		reply(200, null);
		now += 15 * SEC;
		gain(26);
		tick();
		reply(200, null);

		assertEquals(3, sent.size());
		assertEquals("m1", sent.get(1).edit);
		assertEquals("m1", sent.get(2).edit);
		assertEquals("Prayer 23 → 25 (+2) in under a minute", description(sent.get(1)));
		assertEquals("Prayer 23 → 26 (+3) in under a minute", description(sent.get(2)));
		assertEquals(URL + "/messages/m1", DiscordSender.target(sent.get(2)));
		assertFalse("an edit takes no username", sent.get(2).json.contains("username"));
	}

	@Test
	public void aLevelOutsideTheWindowIsANewPost()
	{
		gain(24);
		tick();
		reply(200, "m1");
		now += WINDOW + SEC;
		gain(25);
		tick();
		assertEquals(2, sent.size());
		assertNull("a new post, not an edit", sent.get(1).edit);
		assertEquals("first 25", sent.get(1).json);
	}

	@Test
	public void aNinetyNineOrTotalLevelIsNeverCombinedButSkillsAndCombatAre()
	{
		assertNotNull(LevelThreads.combinable(Collections.singletonList(level("Prayer", 25))));
		assertNull("a 99", LevelThreads.combinable(Arrays.asList(level("Prayer", 99),
			GroupEvent.of(GroupEvent.Type.MAXED, 0, "Alex").text("Prayer").number(99).build())));
		assertNull("a 99 with its post switched off", LevelThreads.combinable(
			Collections.singletonList(level("Prayer", 99))));
		assertNull("a total level", LevelThreads.combinable(Arrays.asList(level("Prayer", 50),
			GroupEvent.of(GroupEvent.Type.TOTAL_LEVEL, 0, "Alex").number(1000).build())));
		assertNull("nothing", LevelThreads.combinable(Collections.emptyList()));
		assertEquals("a level with its combat level", 2, LevelThreads.combinable(Arrays.asList(level("Prayer", 50),
			GroupEvent.of(GroupEvent.Type.COMBAT_LEVEL, 0, "Alex").number(90).build())).size());
		assertEquals("two skills", 2, LevelThreads.combinable(Arrays.asList(level("Attack", 50),
			level("Hitpoints", 50))).size());
	}

	@Test
	public void aRefusedEditPostsANewMessageAndTracksThatOne()
	{
		gain(24);
		tick();
		reply(200, "m1");
		now += 15 * SEC;
		gain(25);
		tick();
		reply(404, null);
		tick();
		assertEquals(3, sent.size());
		assertNull("posted anew", sent.get(2).edit);
		assertTrue(DiscordSender.target(sent.get(2)).endsWith("?wait=true"));
		assertEquals("Prayer 23 → 25 (+2) in under a minute", description(sent.get(2)));
		assertEquals("a new post is sent under the Progress poster name", "Iron Pals",
			gson.fromJson(sent.get(2).json, JsonObject.class).get("username").getAsString());
		reply(200, "m2");

		now += 15 * SEC;
		gain(26);
		tick();
		assertEquals("m2", sent.get(3).edit);
	}

	@Test
	public void editsAreAtMostOneEveryTenSecondsAndFoldQuickerLevels()
	{
		long start = now;
		gain(24);
		tick();
		reply(200, "m1");
		for (int n = 25; n <= 27; n++)
		{
			now += 2 * SEC;
			gain(n);
			tick();
		}
		assertEquals("no edit inside ten seconds", 1, sent.size());
		now = start + LevelThreads.EDIT_GAP;
		tick();
		assertEquals(2, sent.size());
		assertEquals("Prayer 23 → 27 (+4) in under a minute", description(sent.get(1)));
		reply(200, null);
		now += SEC;
		gain(28);
		tick();
		assertEquals("the next edit waits its ten seconds too", 2, sent.size());
		now += LevelThreads.EDIT_GAP;
		tick();
		assertEquals(3, sent.size());
	}

	@Test
	public void aLevelDuringTheFirstPostWaitsForItsId()
	{
		gain(24);
		tick();
		now += 15 * SEC;
		gain(25);
		tick();
		assertEquals("nothing to edit yet", 1, sent.size());
		reply(200, "m1");
		now += LevelThreads.EDIT_GAP;
		tick();
		assertEquals("m1", sent.get(1).edit);
	}

	@Test
	public void aLogoutStartsANewPostButAnOwedEditStillGoes()
	{
		gain(24);
		tick();
		reply(200, "m1");
		now += 2 * SEC;
		gain(25);
		levels.close();
		now += LevelThreads.EDIT_GAP;
		gain(26);
		tick();
		reply(200, "m2");
		tick();
		assertEquals(3, sent.size());
		assertNull("after the logout, a new post", sent.get(1).edit);
		assertEquals("first 26", sent.get(1).json);
		assertEquals("the owed edit", "m1", sent.get(2).edit);
		assertEquals("Prayer 23 → 25 (+2) in under a minute", description(sent.get(2)));
	}

	@Test
	public void severalLevelsFromOneActionReadFromTheLevelBefore()
	{
		ProgressTracker tracker = new ProgressTracker(23);
		tracker.skill("Prayer", 3, 0, 0, "Alex");
		GroupEvent bones = tracker.skill("Prayer", 6, 1_000, 1, "Alex").get(0);
		assertEquals("the tracker carries the level before", 3, bones.previous);
		assertEquals(3, bones.toBuilder().build().previous);

		levels.level(URL, bones, WINDOW, null, "first 6");
		tick();
		reply(200, "m1");
		now += 15 * SEC;
		levels.level(URL, level("Prayer", 6, 7), WINDOW, null, "first 7");
		tick();
		assertEquals("Prayer 3 → 7 (+4) in under a minute", description(sent.get(1)));
	}

	@Test
	public void aMembersLevelWithoutTheLevelBeforeReadsOneBelow()
	{
		assertEquals(0, level("Prayer", 25).previous);
		gain(25);
		tick();
		reply(200, "m1");
		now += 15 * SEC;
		gain(26);
		tick();
		assertEquals("Prayer 24 → 26 (+2) in under a minute", description(sent.get(1)));
	}

	@Test
	public void theWebhooksOwnNameSendsNoUsername()
	{
		poster = null;
		gain(24);
		tick();
		reply(200, "m1");
		now += 15 * SEC;
		gain(25);
		tick();
		reply(404, null);
		tick();
		assertNull(sent.get(2).edit);
		assertFalse(sent.get(2).json.contains("username"));
	}

	/** Posts Prayer 24 as m1, then gains 25 so its edit is in flight. */
	private void editInFlight()
	{
		gain(24);
		tick();
		reply(200, "m1");
		now += 15 * SEC;
		gain(25);
		tick();
		assertEquals("m1", sent.get(sent.size() - 1).edit);
	}

	/**
	 * The edit in flight lost for good: every one of the queue's {@link DiscordQueue#MAX_ATTEMPTS} tries answered
	 * 503. Returns how many requests went meanwhile: the retries, plus the streak's next edit if it lives on.
	 */
	private int loseEdit()
	{
		int before = sent.size();
		for (int attempt = 1; attempt <= DiscordQueue.MAX_ATTEMPTS; attempt++)
		{
			assertEquals("m1", sent.get(sent.size() - 1).edit);
			reply(503, null);
			now += LevelThreads.EDIT_GAP;
			tick();
		}
		return sent.size() - before;
	}

	@Test
	public void threeLostEditsEndTheStreakAndTheNextLevelPostsFresh()
	{
		editInFlight();
		assertEquals("lost once: tried again", DiscordQueue.MAX_ATTEMPTS, loseEdit());
		assertEquals("lost twice: tried again", DiscordQueue.MAX_ATTEMPTS, loseEdit());
		assertEquals("lost a third time: the streak ends", DiscordQueue.MAX_ATTEMPTS - 1, loseEdit());
		now += LevelThreads.EDIT_GAP;
		tick();
		assertTrue(pending.isEmpty());

		now += 15 * SEC;
		gain(28);
		tick();
