package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The level-up picture (Board 2026-11-11: Smithing 1 → 4 showed the chat of level 3). Driven the way
 * GroupEventEngine drives it: a moment's post is held when the batch flushes it, the chat and every game tick ask
 * for the shots due, and each due shot is one frame for every post waiting on it. The "frame" here is the time it
 * was taken, so a test can tell which one a post got.
 */
public class LevelShotTest
{
	private static final String CONGRATS = "Congratulations, you've just advanced your Smithing level. You are now level ";
	private static final long TICK = 600;

	private final LevelShot shot = new LevelShot();
	private final List<long[]> sent = new ArrayList<>();

	/** A post that records the frame it was sent with, and its own tag. */
	private Consumer<byte[]> post(long tag)
	{
		return png -> sent.add(new long[]{tag, png == null ? -1 : png[0]});
	}

	/** One frame per due shot, stamped with the time it was taken. */
	private int shoot(long now)
	{
		List<LevelShot.Held> due = shot.due(now);
		for (LevelShot.Held h : due)
		{
			byte[] frame = {(byte) ((now - NOW) / 100)};
			h.sends.forEach(s -> s.accept(frame));
		}
		return due.size();
	}

	@Test
	public void waitsForTheChatLineAndShootsOnIt()
	{
		// The level registers at NOW; the batch flushes the moment 1.2 s later, before the chat line is in.
		shot.hold("Smithing", 4, NOW, post(1));
		assertEquals(0, shoot(NOW + 1_200));
		assertTrue(shot.chat(CONGRATS + "4.", NOW + 1_500));
		assertEquals(1, shoot(NOW + 1_500));
		assertEquals(1, sent.size());
		assertEquals(15, sent.get(0)[1]);
	}

	@Test
	public void aChatLineAlreadyInShootsAtOnce()
	{
		// The game's line usually lands on the same tick the level registers, ahead of the batch's flush.
		shot.chat("<col=ff0000>" + CONGRATS + "4.</col>", NOW + 100);
		shot.hold("Smithing", 4, NOW, post(1));
		assertEquals(1, shoot(NOW + 1_200));
	}

	@Test
	public void noChatLineShootsAtTwoSeconds()
	{
		shot.hold("Smithing", 4, NOW, post(1));
		for (long t = NOW; t < NOW + LevelShot.WAIT; t += TICK)
		{
			assertEquals("before " + LevelShot.WAIT + " ms at +" + (t - NOW), 0, shoot(t));
		}
		assertEquals(1, shoot(NOW + LevelShot.WAIT));
		assertEquals(20, sent.get(0)[1]);
	}

	@Test
	public void anOlderLevelsLineDoesNotCount()
	{
		shot.chat(CONGRATS + "3.", NOW - 500);
		shot.hold("Smithing", 4, NOW, post(1));
		assertEquals(0, shoot(NOW + 1_200));
	}

	@Test
	public void anotherSkillsLineDoesNotCount()
	{
		shot.hold("Smithing", 4, NOW, post(1));
		shot.chat("Congratulations, you've just advanced your Mining level. You are now level 4.", NOW + 300);
		assertEquals(0, shoot(NOW + 300));
	}

	@Test
	public void aSecondLevelWithinTheWaitGetsTheNewerFrameForBoth()
	{
		shot.hold("Smithing", 3, NOW, post(3));
		// Level 4 a second later: its moment starts and flushes the level-3 one (the batch's repeat rule).
		shot.hold("Smithing", 4, NOW + 1_000, post(4));
		shot.chat(CONGRATS + "3.", NOW + 1_100);
		assertEquals("level 3's line is not level 4's", 0, shoot(NOW + 1_100));
		shot.chat(CONGRATS + "4.", NOW + 1_700);
		assertEquals(1, shoot(NOW + 1_700));
		assertEquals(2, sent.size());
		assertArrayEquals(new long[]{3, 17}, sent.get(0));
		assertArrayEquals(new long[]{4, 17}, sent.get(1));
	}

	@Test
	public void theWaitIsCappedAtThreeSecondsFromTheFirstLevel()
	{
		shot.hold("Smithing", 3, NOW, post(3));
		shot.hold("Smithing", 4, NOW + 1_800, post(4));
		assertEquals(0, shoot(NOW + 2_900));
		assertEquals(1, shoot(NOW + LevelShot.MAX_WAIT));
		assertEquals(2, sent.size());
	}

	@Test
	public void runecraftMatchesTheChatsRunecrafting()
	{
		shot.hold("Runecraft", 10, NOW, post(1));
		shot.chat("Congratulations, you've just advanced your Runecrafting level. You are now level 10.", NOW + 200);
		assertEquals(1, shoot(NOW + 200));
	}

	@Test
	public void otherChatIsNotALevelLine()
	{
		assertFalse(shot.chat("Your Vorkath kill count is: 120.", NOW));
	}

	@Test
	public void aHopOrLogoutShootsEverythingWaiting()
	{
		shot.hold("Smithing", 4, NOW, post(1));
		shot.hold("Mining", 9, NOW, post(2));
		assertEquals(2, shot.drain().size());
		assertEquals(0, shoot(NOW + 5_000));
	}

	@Test
	public void theCombinedPostsEditCarriesTheNewerFrame()
	{
		// Wired as the engine's combineLevels does: each held send is a level into its streak.
		LevelThreads threads = new LevelThreads();
		GroupEvent three = GroupEvent.of(GroupEvent.Type.LEVEL_UP, NOW, "Me").text("Smithing").number(3).previous(2)
			.build();
		GroupEvent four = GroupEvent.of(GroupEvent.Type.LEVEL_UP, NOW + 1_000, "Me").text("Smithing").number(4)
			.previous(3).build();
		List<LevelThreads.Edit> fresh = new ArrayList<>();
		long window = 600_000;
		shot.hold("Smithing", 3, NOW, png -> fresh.add(threads.level(three, "url", NOW + 1_700, window, png)));
		shot.hold("Smithing", 4, NOW + 1_000, png -> assertNull(threads.level(four, "url", NOW + 1_700, window, png)));
		shot.chat(CONGRATS + "4.", NOW + 1_700);
		shoot(NOW + 1_700);
		threads.posted(fresh.get(0).streak, 200, "msg", NOW + 2_000);
		List<LevelThreads.Edit> edits = threads.due(NOW + 2_000 + LevelThreads.EDIT_GAP);
		assertEquals(1, edits.size());
		assertEquals(17, edits.get(0).png[0]);
		assertEquals(17, fresh.get(0).streak.png[0]);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.List;
import org.junit.Before;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The net under {@link LoginGate}: a login's first minute posts a handful, never a burst. */
public class LoginBurstTest
{
	private LoginBurst burst;

	@Before
	public void login()
	{
		burst = new LoginBurst(LoginBurst.ACHIEVEMENTS::contains);
		burst.open(NOW);
	}

	private static GroupEvent diary(String text)
	{
		return GroupEvent.of(GroupEvent.Type.DIARY, NOW, "Ship Wrek").text(text).build();
	}

	@Test
	public void aFiveAchievementLoginPostsNothing()
	{
		for (String d : new String[]{"Karamja medium", "Lumbridge easy", "Varrock easy", "Ardougne easy"})
		{
			assertTrue(burst.hold(diary(d), NOW + 1_000));
		}
		assertTrue(burst.hold(GroupEvent.of(GroupEvent.Type.TOTAL_LEVEL, NOW, "Ship Wrek").number(700).build(),
			NOW + 2_000));
		assertTrue("still inside the minute", burst.due(NOW + 30_000).isEmpty());
		assertTrue("a burst is dropped", burst.due(NOW + LoginBurst.WINDOW_MS).isEmpty());
		assertEquals(5, burst.takeDropped());
		assertEquals(0, burst.takeDropped());
	}

	@Test
	public void aHandfulPostsOnceTheMinuteIsOver()
	{
		for (int i = 0; i < LoginBurst.MAX_POSTS; i++)
		{
			burst.hold(diary("Varrock easy"), NOW + i);
		}
		List<GroupEvent> out = burst.due(NOW + LoginBurst.WINDOW_MS);
		assertEquals(LoginBurst.MAX_POSTS, out.size());
		assertEquals(0, burst.takeDropped());
		assertTrue("posted once", burst.due(NOW + LoginBurst.WINDOW_MS + 1).isEmpty());
	}

	@Test
	public void afterTheMinuteAndForOtherKindsNothingIsHeld()
	{
		assertFalse("an online post is no achievement",
			burst.hold(GroupEvent.of(GroupEvent.Type.ONLINE, NOW, "Ship Wrek").text("online").build(), NOW + 1));
		assertFalse("a mid-session diary posts at once", burst.hold(diary("Falador easy"), NOW + LoginBurst.WINDOW_MS));
	}

	@Test
	public void aLogoutInsideTheMinuteSettlesItThen()
	{
		burst.hold(diary("Varrock easy"), NOW + 1);
		assertEquals(1, burst.end().size());
		assertFalse("the window is closed", burst.hold(diary("Falador easy"), NOW + 2));
	}

	@Test
	public void memberBroadcastsCountEveryKind()
	{
		LoginBurst members = new LoginBurst(t -> true);
		members.open(NOW);
		assertTrue(members.hold(GroupEvent.of(GroupEvent.Type.DROP, NOW, "GroupOtt").broadcast(true).build(), NOW));
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.GameState;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Board 2026-11-15: switching accounts posted the other account's long-done diaries (Karamja medium, Lumbridge
 * easy, Varrock easy, Ardougne easy) and a "Total level 700" with three level-ups. Each test drives the engine's
 * order of events (game states, StatChanged, ticks with their variable polls) through the real tracker and
 * watchers, as {@link GroupEventEngine} wires them: nothing earned before a login ever comes out.
 */
public class LoginGateTest
{
	private static final long A = 111L;
	private static final long B = 222L;
	/** Skills enough to judge a total: the tracker is built for exactly these. */
	private static final String[] SKILLS = {"Firemaking", "Crafting", "Smithing", "Attack"};
	private static final int[] DIARIES = {VarbitID.ATJUN_MED_DONE, VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE,
		VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE};

	private final List<GroupEvent> out = new ArrayList<>();
	private final Map<Integer, Integer> vars = new HashMap<>();
	private ProgressTracker progress;
	private EventWatchers watchers;
	private LoginBurst ownBurst;
	private LoginGate gate;
	private long hash = LoginGate.NO_ACCOUNT;
	private boolean loginPending;

	@Before
	public void setUp()
	{
		progress = new ProgressTracker(SKILLS.length);
		watchers = new EventWatchers(out::add, t -> true);
		ownBurst = new LoginBurst(LoginBurst.ACHIEVEMENTS::contains);
		gate = new LoginGate(progress, watchers, ownBurst, new LoginBurst(t -> true));
	}

	// ---- The engine's handlers, in its order ----

	private void state(GameState state)
	{
		if (LoginGate.endsSession(state))
		{
			gate.startOver();
		}
		if (state == GameState.LOGGED_IN)
		{
			loginPending = true;
		}
	}

	private void stat(String skill, int level)
	{
		gate.account(hash, NOW);
		out.addAll(progress.skill(skill, level, (long) level * 1000, NOW, "Ship Wrek"));
	}

	private void tick()
	{
		gate.account(hash, NOW);
		if (loginPending)
		{
			loginPending = false;
			gate.login(NOW);
		}
		if (gate.tick())
		{
			watchers.poll(id -> vars.getOrDefault(id, 0), NOW, "Ship Wrek");
		}
	}

	private void ticks(int n)
	{
		for (int i = 0; i < n; i++)
		{
			tick();
		}
	}

	/** A logged in for a while: low on the three skills, no diaries, and every value settled. */
	private void accountAPlayed()
	{
		hash = A;
		state(GameState.LOGGING_IN);
		state(GameState.LOADING);
		state(GameState.LOGGED_IN);
		stats(60, 60, 50, 70);
		ticks(LoginGate.SETTLE_TICKS + 5);
		assertTrue(gate.settled());
		assertTrue(out.isEmpty());
	}

	private void stats(int... levels)
	{
		for (int i = 0; i < SKILLS.length; i++)
		{
			stat(SKILLS[i], levels[i]);
		}
	}

	/** B's values as the game sends them: the levels the Board's post showed, its four done diaries. */
	private void accountBArrives()
	{
		hash = B;
		stats(65, 65, 53, 70);
		for (int id : DIARIES)
		{
			vars.put(id, 1);
		}
	}

	private void assertNothingPosted()
	{
		ticks(LoginGate.SETTLE_TICKS + 5);
		assertTrue("old achievements posted: " + out, out.isEmpty());
	}

	// ---- Account switches post nothing ----

	@Test
	public void logoutThenAnotherAccountWithDoneDiariesPostsNothing()
	{
		accountAPlayed();
		state(GameState.LOGIN_SCREEN);
		hash = LoginGate.NO_ACCOUNT;
		state(GameState.LOGGING_IN);
		state(GameState.LOADING);
		state(GameState.LOGGED_IN);
		accountBArrives();
		assertNothingPosted();
	}

	@Test
	public void aWorldHopIntoAnotherAccountPostsNothing()
	{
		accountAPlayed();
		state(GameState.HOPPING);
		state(GameState.LOADING);
		state(GameState.LOGGED_IN);
		accountBArrives();
		assertNothingPosted();
	}

	@Test
	public void aLostConnectionThenAnotherAccountPostsNothing()
	{
		accountAPlayed();
		state(GameState.CONNECTION_LOST);
		state(GameState.LOGGED_IN);
		accountBArrives();
		assertNothingPosted();
	}

	@Test
	public void aSwitchNoGameStateShowedPostsNothing()
	{
		// The old engine's path: the only reset sat at the end of the LOGIN_SCREEN branch, so any switch that did
		// not reach it (or a handler that threw before it) left A's values as B's baseline.
		accountAPlayed();
		accountBArrives();
		assertNothingPosted();
	}

	@Test
	public void aSwitchWhoseStatsComeBeforeTheAccountIsKnownPostsNothing()
	{
		accountAPlayed();
		// Mid-login the client knows no account yet; B's stats are already arriving.
		hash = LoginGate.NO_ACCOUNT;
		stats(65, 65, 53, 70);
		hash = B;
		state(GameState.LOGGED_IN);
		for (int id : DIARIES)
		{
			vars.put(id, 1);
		}
		assertNothingPosted();
	}

	@Test
	public void varbitsArrivingTicksLatePostNothing()
	{
		accountAPlayed();
		state(GameState.LOGIN_SCREEN);
		hash = B;
		state(GameState.LOGGING_IN);
		state(GameState.LOGGED_IN);
		stats(65, 65, 53, 70);
		// The first polls read 0 for every diary: the game has not sent them yet.
		ticks(LoginGate.VAR_WAIT_TICKS + 3);
		for (int id : DIARIES)
		{
			vars.put(id, 1);
		}
		assertNothingPosted();
	}

	@Test
	public void statsSentTwiceAtLoginPostNothing()
	{
		hash = B;
		state(GameState.LOGGING_IN);
		state(GameState.LOGGED_IN);
		// A default value first, then the real one a moment later.
		stats(1, 1, 1, 1);
		tick();
		stats(65, 65, 53, 70);
		assertNothingPosted();
	}

	// ---- Real progress still posts ----

	@Test
	public void aDiaryCompletedMidSessionStillPosts()
	{
		accountAPlayed();
		vars.put(VarbitID.VARROCK_DIARY_EASY_COMPLETE, 1);
		tick();
		assertEquals(1, out.size());
		assertEquals(GroupEvent.Type.DIARY, out.get(0).type);
		assertEquals("Varrock easy", out.get(0).text);
	}

	@Test
	public void aLevelAndTotalMidSessionStillPost()
	{
		accountAPlayed();
		// 60 + 60 + 50 + 70 = 240; Firemaking to 120 crosses 300.
		stat("Firemaking", 120);
		Map<GroupEvent.Type, Long> kinds = new LinkedHashMap<>();
		out.forEach(e -> kinds.put(e.type, e.number));
		assertEquals(Long.valueOf(120), kinds.get(GroupEvent.Type.LEVEL_UP));
		assertEquals(Long.valueOf(300), kinds.get(GroupEvent.Type.TOTAL_LEVEL));
	}

	@Test
	public void theNewAccountsOwnProgressPostsOnceSettled()
	{
		accountAPlayed();
		state(GameState.LOGIN_SCREEN);
		hash = B;
		state(GameState.LOGGING_IN);
		state(GameState.LOGGED_IN);
		accountBArrives();
		assertNothingPosted();
		vars.put(VarbitID.FALADOR_DIARY_EASY_COMPLETE, 1);
		stat("Smithing", 54);
		tick();
		assertEquals(2, out.size());
	}

	@Test
	public void aProfileChangeMidSessionReBaselines()
	{
		accountAPlayed();
		// The RuneLite profile changed under the same account hash: its values are a new baseline.
		gate.rebaseline(NOW);
		stats(65, 65, 53, 70);
		for (int id : DIARIES)
		{
			vars.put(id, 1);
		}
		assertNothingPosted();
	}

	@Test
	public void aHopKeepsTheGraveTimerAnAccountSwitchDoesNot()
	{
		accountAPlayed();
		watchers.died(new HashMap<>(), "Lumbridge", 301);
		state(GameState.HOPPING);
		state(GameState.LOADING);
		state(GameState.LOGGED_IN);
		ticks(2);
		assertTrue("same account, same grave", watchers.graveOut());
		hash = B;
		tick();
		assertTrue("another account's grave is not this one's", !watchers.graveOut());
	}

	@Test
	public void theLoginScreenHopsAndLostConnectionsEndASessionLoadingDoesNot()
	{
		assertTrue(LoginGate.endsSession(GameState.LOGIN_SCREEN));
		assertTrue(LoginGate.endsSession(GameState.LOGGING_IN));
		assertTrue(LoginGate.endsSession(GameState.HOPPING));
		assertTrue(LoginGate.endsSession(GameState.CONNECTION_LOST));
		assertTrue(!LoginGate.endsSession(GameState.LOADING));
		assertTrue(!LoginGate.endsSession(GameState.LOGGED_IN));
	}

	@Test
	public void aLoginOpensTheBurstWindow()
	{
		accountAPlayed();
		GroupEvent diary = GroupEvent.of(GroupEvent.Type.DIARY, NOW, "Ship Wrek").text("Varrock easy").build();
		assertTrue("held in the login's first minute", ownBurst.hold(diary, NOW + 1));
	}
}

package com.vinnyvangogh.groupironman;

import java.util.List;
