package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.events.PluginMessage;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** What "Path to" says and sends, and that the path goes away when the item is done. */
public class PathSessionTest
{
	private static class FakePlugin
	{
	}

	private static final ItemPaths.Stop HARRY = new ItemPaths.Stop("Harry's Fishing Shop",
		new WorldPoint(2833, 3443, 0), false);
	private static final ItemPaths.Stop SARIM = new ItemPaths.Stop("Port Sarim shop", new WorldPoint(3014, 3224, 0),
		false);
	private static final ItemPaths.Target NET = ItemPaths.Target.listItem("list", 305);

	private final List<Object> posted = new ArrayList<>();

	private PathSession session(boolean installed, boolean enabled)
	{
		List<Object> plugins = installed ? Collections.singletonList(new FakePlugin()) : Collections.emptyList();
		return new PathSession(new ShortestPathBridge(() -> plugins, p -> enabled, FakePlugin.class.getName(),
			posted::add));
	}

	private PluginMessage last()
	{
		return (PluginMessage) posted.get(posted.size() - 1);
	}

	@Test
	public void sendsTheStopsTileAndNamesIt()
	{
		PathSession s = session(true, true);
		assertEquals("Path to: Harry's Fishing Shop.", s.go(NET, HARRY, true));
		assertEquals(1, posted.size());
		assertEquals("path", last().getName());
		assertEquals(Set.of(HARRY.at), last().getData().get("target"));
		assertEquals("Harry's Fishing Shop", s.active());
	}

	@Test
	public void noShortestPathSaysSoAndSendsNothing()
	{
		PathSession s = session(false, true);
		assertEquals("Shortest Path is not installed: get it from the Plugin Hub to path to items.",
			s.go(NET, HARRY, true));
		assertTrue(posted.isEmpty());
		assertEquals("", s.active());

		PathSession off = session(true, false);
		assertEquals("Shortest Path is not enabled: turn it on in the plugin list to path to items.",
			off.go(NET, HARRY, true));
		assertTrue(posted.isEmpty());
	}

	@Test
	public void noShortestPathNeverThrowsOnClearOrRecheck()
	{
		PathSession s = session(false, true);
		assertEquals("", s.stop());
		assertFalse(s.recheck(t -> Collections.emptyList()));
		assertTrue(posted.isEmpty());
	}

	@Test
	public void loggedOutHasNowhereToStartFrom()
	{
		PathSession s = session(true, true);
		assertEquals("Log in first: the path starts where you stand.", s.go(NET, HARRY, false));
		assertTrue(posted.isEmpty());
	}

	@Test
	public void aShortestPathThatThrowsIsReportedNotRaised()
	{
		PathSession s = new PathSession(new ShortestPathBridge(() -> Collections.singletonList(new FakePlugin()),
			p -> true, FakePlugin.class.getName(), e ->
			{
				throw new AssertionError("not on the client thread");
			}));
		assertEquals("Shortest Path did not take the path: update it, or try again.", s.go(NET, HARRY, true));
		assertEquals("", s.active());
	}

	@Test
	public void doneItemClearsThePath()
	{
		PathSession s = session(true, true);
		s.go(NET, HARRY, true);
		assertTrue(s.recheck(t -> Collections.emptyList()));
		assertEquals("clear", last().getName());
		assertEquals("", s.active());
		// Nothing active: a second recheck sends nothing.
		int before = posted.size();
		assertFalse(s.recheck(t -> Collections.emptyList()));
		assertEquals(before, posted.size());
	}

	/** Still needed and the shop still sells it: the path stays as it is, even if another shop is now nearer. */
	@Test
	public void stillNeededLeavesThePathAlone()
	{
		PathSession s = session(true, true);
		s.go(NET, HARRY, true);
		assertFalse(s.recheck(t -> Arrays.asList(SARIM, HARRY)));
		assertEquals(1, posted.size());
		assertEquals("Harry's Fishing Shop", s.active());
	}

	/** "Path to next": once the stop has nothing left to get, on to the nearest remaining one. */
	@Test
	public void stopWithNothingLeftMovesOnToTheNext()
	{
		PathSession s = session(true, true);
		s.go(ItemPaths.Target.next("list"), HARRY, true);
		assertTrue(s.recheck(t -> Collections.singletonList(SARIM)));
		assertEquals("path", last().getName());
		assertEquals(Set.of(SARIM.at), last().getData().get("target"));
		assertEquals("Port Sarim shop", s.active());
	}

	@Test
	public void stopClearsOnce()
	{
		PathSession s = session(true, true);
		s.go(NET, HARRY, true);
		assertEquals("Path cleared.", s.stop());
		assertEquals("clear", last().getName());
		assertEquals("", s.stop());
		assertEquals(2, posted.size());
	}
}

package com.vinnyvangogh.groupironman;

import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.plugins.PluginDescriptor;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * GIM Utilities split out of Build Guard and both may run in the same client,
 * so nothing this plugin stores or sends may collide with Build Guard's. These
 * pin the names Build Guard uses as literals: they are its frozen identity and
 * this repo no longer has its classes.
 */
public class PluginIdentityTest
{
	private static final String BUILD_GUARD_CONFIG_GROUP = "build-guard";
	private static final String BUILD_GUARD_CACHE_DIR = "build-guard";
	private static final String[] BUILD_GUARD_MESSAGE_TYPES = {"BuildGuardPartyMessage", "BuildGuardGroupMessage"};
	/** The Hub plugin "Group Iron Man" (Spedwards, slug group-ironman) already owns this group. */
	private static final String HUB_GROUP_IRON_MAN_CONFIG_GROUP = "groupironman";

	/** Every setting at its default, the way a fresh install sees them. */
	private static final GroupIronmanConfig DEFAULTS = new GroupIronmanConfig()
	{
	};

	@Test
	public void configGroupIsItsOwnAndNotBuildGuards()
	{
		assertEquals("gimutilities", GroupIronmanConfig.GROUP);
		assertEquals(GroupIronmanConfig.GROUP, GroupIronmanConfig.class.getAnnotation(ConfigGroup.class).value());
		assertNotEquals(BUILD_GUARD_CONFIG_GROUP, GroupIronmanConfig.GROUP);
		assertNotEquals(HUB_GROUP_IRON_MAN_CONFIG_GROUP, GroupIronmanConfig.GROUP);
	}

	@Test
	public void partyMessageTypeIsDistinctFromBuildGuards()
	{
		// The party relay routes by simple class name, so the name is the type id.
		String type = VvgGroupIronmanMessage.class.getSimpleName();
		assertEquals("VvgGroupIronmanMessage", type);
		for (String theirs : BUILD_GUARD_MESSAGE_TYPES)
		{
			assertNotEquals(theirs, type);
		}
	}

	@Test
	public void cacheFolderIsNotBuildGuards()
	{
		assertEquals("gim-utilities", GroupService.CACHE_DIR);
		assertNotEquals(BUILD_GUARD_CACHE_DIR, GroupService.CACHE_DIR);
	}

	@Test
	public void pluginIsNamedGimUtilities()
	{
		assertEquals("GIM Utilities", GroupIronmanPlugin.class.getAnnotation(PluginDescriptor.class).name());
	}

	@Test
	public void everySwitchDefaultsToOff() throws Exception
	{
		List<String> on = new ArrayList<>();
		int switches = 0;
		for (Method m : GroupIronmanConfig.class.getDeclaredMethods())
		{
			if (m.getAnnotation(ConfigItem.class) == null || m.getReturnType() != boolean.class)
			{
				continue;
			}
			switches++;
			if ((Boolean) m.invoke(DEFAULTS))
			{
				on.add(m.getName());
			}
		}
		// Six share switches, the world map, ::find, "Sync with my group" and "Colour item names" (a ::find
		// look, off): a new switch must be added here on purpose. Sync is the one switch on by default (Board,
		// round 2): it does nothing without a group key, and even with one nothing is sent until the player
		// presses Join. Part A of the group events adds 44 more, every one off: "Share group events", "Post to
		// Discord", "Attach a screenshot", "Group box", and a Discord and an overlay switch per event kind.
		// Part C adds 15 kinds (a Discord and an overlay switch each) and one digest switch per category.
		// "Easter eggs" (Discord section) adds one more, off. "Show update notes" (Advanced) is the second switch
		// on by default (Board 2026-11-11): it only writes the welcome or what's new in the game chat, once per
		// version, and sends nothing anywhere. Group settings add "Don't post my events", off: a member's own
		// opt-out, never something the group turns on for them. "Repost board daily" (Discord) is the third
		// switch on by default (Board 2026-11-14): it only acts when the live board is already on. "Members without
		// the plugin" (Discord) is the fourth (Board 2026-11-14, "default on"): it only acts when posting is on,
		// and posts the game's own Group broadcasts the group already sees in its chat. "Shopping: shop alert"
		// (In-game, Board 2026-11-14) adds one more, off: a chat line near a shop selling something a list still
		// needs. Shopping requests (Board 2026-11-14) are one more kind, so two more switches, both off.
		// Live activities Slice A adds four kinds (start, wave, completion, death): eight more switches, all off.
		assertEquals(10 + 4 + 2 * GroupEvent.Type.values().length + GroupEvent.Category.values().length + 1 + 1 + 1
			+ 1 + 1 + 1, switches);
		assertEquals(106, switches);
		List<String> expectedOn = Arrays.asList("discordNoPluginEvents", "discordRepostBoard", "groupSync",
			"showUpdateNotes");
		Collections.sort(on);
		assertEquals(expectedOn, on);
		assertEquals("", DEFAULTS.groupLowStock());
		assertEquals("no key on a fresh install", "", DEFAULTS.groupKey());
	}

	@Test
	public void pluginStartsWithAllFeaturesOff()
	{
		// What GroupService.switches() and anyOn() build from the config on startUp.
		GroupOutbox.Switches s = new GroupOutbox.Switches(DEFAULTS.groupShareBank(), DEFAULTS.groupShareStorage(),
			DEFAULTS.groupShareStats(), DEFAULTS.groupShareCarried(), DEFAULTS.groupShareExtras(),
			DEFAULTS.groupShareDrops());
		assertFalse(s.any());
		assertTrue(LowStock.parse(DEFAULTS.groupLowStock()).isEmpty());
		assertFalse(DEFAULTS.groupWorldMap());
		assertFalse(DEFAULTS.groupFindCommand());
		// Sync on but no key: the panel says "No group key yet" and nothing joins or sends.
		assertEquals(GroupSync.State.NO_KEY, new GroupSync(new GroupSync.Party()
		{
			@Override
			public String passphrase()
			{
				return null;
			}

			@Override
			public void changeParty(String passphrase)
			{
				throw new AssertionError("joined on a fresh install");
			}
		}).state(DEFAULTS.groupSync(), "GroupShip", DEFAULTS.groupKey()));
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static com.vinnyvangogh.groupironman.EventFixtures.items;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The rules a Custom poster name must meet, and how a name lands in a post. Which name is used: WebhooksTest. */
public class PosterNamesTest
{
	private final Gson gson = new Gson();
	private final FakeItems items = new FakeItems();

	private JsonObject post(String username)
	{
		GroupEvent drop = GroupEvent.of(GroupEvent.Type.DROP, NOW, "Alex").text("Vorkath")
			.items(items(FakeItems.WHIP, 1)).number(120).build();
		ItemLookup lookup = Amounts.BOTH.words(items);
		return parse(DiscordWebhook.payload(gson, DiscordMerge.single(drop, lookup), lookup, DiscordStyle.EMBED, "",
			false, null, username));
	}

	private static JsonObject parse(String json)
	{
		return new JsonParser().parse(json).getAsJsonObject();
	}

	@Test
	public void noNameSendsNoUsernameKey()
	{
		JsonObject o = post(null);
		assertFalse("Discord shows the webhook's own name", o.has("username"));
		assertFalse("and its own avatar", o.has("avatar_url"));
		assertEquals("the footer still says where it came from", "GIM Utilities",
			o.getAsJsonArray("embeds").get(0).getAsJsonObject().getAsJsonObject("footer").get("text").getAsString());
		assertEquals("Party Pete", post("Party Pete").get("username").getAsString());
	}

	@Test
	public void aNameOver80CharactersIsTrimmed()
	{
		String longName = "  " + repeat('a', 100) + "  ";
		assertEquals(repeat('a', 80), PosterNames.clean(longName));
		assertEquals("never half a surrogate pair", 79, PosterNames.clean(repeat('c', 79) + "😀").length());
		assertEquals("cut, then trimmed", repeat('d', 70), PosterNames.clean(repeat('d', 70) + repeat(' ', 20) + "x"));
	}

	@Test
	public void namesDiscordRejectsAreRefused()
	{
		assertTrue(PosterNames.refused("Discord Bot"));
		assertTrue(PosterNames.refused("my CLYDE"));
		assertTrue(PosterNames.refused("xdIsCoRdx"));
		assertFalse(PosterNames.refused("Gringotts Bot"));
		assertFalse("blank is not refused: it means the default name", PosterNames.refused(""));
	}

	@Test
	public void namesWithMentionsOrMarkdownAreRefused()
	{
		for (String bad : new String[]{"Loot @ Home", "Bank#1", "Time: now", "a ```code``` bot", "everyone",
			"Here", " EVERYONE "})
		{
			assertTrue(bad, PosterNames.refused(PosterNames.clean(bad)));
		}
		assertFalse("only exactly everyone or here", PosterNames.refused("everyone's bot"));
		assertFalse(PosterNames.refused("Over here"));
		assertFalse("one or two backticks are fine", PosterNames.refused("a `b` c"));
		assertFalse("an apostrophe is fine", PosterNames.refused("Death's Office"));

		PosterNames warnings = new PosterNames();
		Map<String, String> fields = new LinkedHashMap<>();
		fields.put("group storage", "Bank#1");
		List<String> lines = warnings.check(fields);
		assertEquals(Collections.singletonList(PosterNames.message("group storage")), lines);
		assertFalse("never the name itself", lines.get(0).contains("Bank#1"));
		assertTrue("once", warnings.check(fields).isEmpty());
	}

	@Test
	public void aRefusedNameGetsOneChatWarningNamingTheField()
	{
		PosterNames warnings = new PosterNames();
		Map<String, String> fields = new LinkedHashMap<>();
		fields.put("main", "Clyde");
		fields.put("deaths & danger", "Death Bot");
		List<String> lines = warnings.check(fields);
		assertEquals(1, lines.size());
		assertEquals(PosterNames.message("main"), lines.get(0));
		assertTrue(lines.get(0).contains("'discord'"));
		assertTrue(lines.get(0).contains("'clyde'"));
		assertTrue(lines.get(0).contains("default name"));
		assertFalse("never the name itself", lines.get(0).contains("Clyde"));
		assertTrue("once", warnings.check(fields).isEmpty());
		fields.put("main", "Main Bot");
		assertTrue(warnings.check(fields).isEmpty());
		fields.put("main", "Discord");
		assertEquals("broken again, warned again", 1, warnings.check(fields).size());
		fields.put("main", "");
		assertTrue("off Custom (blank), forgotten", warnings.check(fields).isEmpty());
		fields.put("main", "Discord");
		assertEquals("back on Custom, warned again", 1, warnings.check(fields).size());
	}

	@Test
	public void theDigestUsesThePosterName()
	{
		List<String> lines = Collections.singletonList("Alex: took 1 x Abyssal whip");
		JsonObject own = parse(DiscordWebhook.digest(gson, GroupEvent.Category.STORAGE, lines, null));
		assertFalse(own.has("username"));
		JsonObject named = parse(DiscordWebhook.digest(gson, GroupEvent.Category.STORAGE, lines, "Varrock Herald"));
		assertEquals("Varrock Herald", named.get("username").getAsString());
	}

	@Test
	public void theWebhooksOwnNameIsTheDefaultChoice()
	{
		GroupIronmanConfig defaults = new GroupIronmanConfig()
		{
		};
		assertEquals(DiscordPosterName.WEBHOOK, defaults.discordPosterName());
		assertEquals("Webhook's own", DiscordPosterName.WEBHOOK.toString());
		assertEquals("saved under the constant's name, not the label", "WEBHOOK", DiscordPosterName.WEBHOOK.name());
	}

	private static String repeat(char c, int n)
	{
		StringBuilder s = new StringBuilder();
		for (int i = 0; i < n; i++)
		{
			s.append(c);
		}
		return s.toString();
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Online and offline for Discord (Board 2026-11-10): a short grace after a
 * logout, nothing for a hop or quick relog, one offline with the session
 * length, and never "You" or a swapped title. {@code NOW} is 22:13 UTC.
 */
public class PresenceDebounceTest
{
	private static final long MIN = TimeUnit.MINUTES.toMillis(1);
	private static final int GRACE = 2;
	private final PresenceDebounce p = new PresenceDebounce(ZoneOffset.UTC);
	/** Everything the debounce asked to post, in order: what Discord would get. */
	private final List<GroupEvent> posted = new ArrayList<>();

	private void login(long at, int world, String member, int grace)
	{
		posted.addAll(p.login(at, world, member, grace));
	}

	/** The executor's once-a-second poll, from {@code from} to {@code to}. */
	private void tickThrough(long from, long to, int grace)
	{
		for (long t = from; t <= to; t += 1000)
		{
			GroupEvent e = p.poll(t, grace);
			if (e != null)
			{
				posted.add(e);
			}
		}
	}

	private static boolean offline(GroupEvent e)
	{
		return "offline".equals(e.text);
	}

	@Test
	public void loginIsOnlineWithTheWorldAndTheName()
	{
		login(NOW, 302, "GroupShip", GRACE);
		assertEquals(1, posted.size());
		GroupEvent e = posted.get(0);
		assertEquals(GroupEvent.Type.ONLINE, e.type);
		assertEquals("online", e.text);
		assertEquals("GroupShip", e.member);
		assertEquals("Online", EventText.title(e));
		assertEquals("GroupShip: is online on world 302", EventText.sentence(e, new FakeItems()));
	}

	@Test
	public void relogWithinTheGracePostsNothing()
	{
		login(NOW, 302, "GroupShip", GRACE);
		posted.clear();
		p.logout(NOW + 60 * MIN);
		tickThrough(NOW + 60 * MIN, NOW + 61 * MIN, GRACE);
		login(NOW + 61 * MIN + 59_000, 330, "GroupShip", GRACE);
		tickThrough(NOW + 62 * MIN, NOW + 75 * MIN, GRACE);
		assertTrue("no offline and no online: " + posted, posted.isEmpty());
	}

	@Test
	public void offThreeMinutesIsOneOfflineWithTitleNameAndSession()
	{
		login(NOW, 303, "GroupShip", GRACE);
		posted.clear();
		long out = NOW + 72 * MIN;
		p.logout(out);
		tickThrough(out, out + 3 * MIN, GRACE);
		assertEquals(1, posted.size());
		GroupEvent off = posted.get(0);
		assertTrue(offline(off));
		assertEquals("GroupShip", off.member);
		assertEquals("stamped with the logout, not the post", out, off.at);
		assertEquals("Offline", EventText.title(off));
		assertEquals("GroupShip: offline, played 1h 12m on world 303, logged off at 11:25 PM",
			EventText.sentence(off, new FakeItems()));
		assertNull("only once", p.poll(out + 60 * MIN, GRACE));
	}

	@Test
	public void offlineWaitsForTheGraceThenPosts()
	{
		login(NOW, 303, "GroupShip", GRACE);
		posted.clear();
		long out = NOW + 30 * MIN;
		p.logout(out);
		assertNull(p.poll(out + GRACE * MIN - 1, GRACE));
		assertTrue(offline(p.poll(out + GRACE * MIN, GRACE)));
	}

	@Test
	public void aLoginAfterTheOfflineIsOneOnline()
	{
		login(NOW, 303, "GroupShip", GRACE);
		long out = NOW + 72 * MIN;
		p.logout(out);
		tickThrough(out, out + 3 * MIN, GRACE);
		posted.clear();
		login(out + 5 * MIN, 420, "GroupShip", GRACE);
		assertEquals(1, posted.size());
		assertEquals("online", posted.get(0).text);
		assertEquals(420, posted.get(0).world);
	}

	@Test
	public void aWorldHopIsNothingEvenWithNoGrace()
	{
		login(NOW, 302, "GroupShip", 0);
		posted.clear();
		// A hop is LOGGED_IN -> HOPPING -> LOGGED_IN: the engine never calls logout for it.
		login(NOW + 20 * MIN, 330, "GroupShip", 0);
		tickThrough(NOW + 20 * MIN, NOW + 40 * MIN, 0);
		assertTrue(posted.isEmpty());
		p.logout(NOW + 41 * MIN);
		assertEquals("the hop moved the world", 330, p.poll(NOW + 41 * MIN, 0).world);
	}

	@Test
	public void graceZeroPostsAtOnce()
	{
		login(NOW, 302, "GroupShip", 0);
		posted.clear();
		p.logout(NOW + 45 * MIN);
		GroupEvent off = p.poll(NOW + 45 * MIN, 0);
		assertTrue(offline(off));
		assertEquals("GroupShip: offline, played 45m on world 302, logged off at 10:58 PM",
			EventText.sentence(off, new FakeItems()));
		login(NOW + 46 * MIN, 302, "GroupShip", 0);
		assertEquals("online", posted.get(0).text);
	}

	@Test
	public void aFlakyConnectionIsAtMostOnePairPerTenMinutes()
	{
		login(NOW, 302, "GroupShip", 0);
		// Drops and comes back every minute and a half: the offline is held until ten minutes after the online.
		for (int i = 0; i < 6; i++)
		{
			long out = NOW + (i * 90 + 30) * 1000L;
			p.logout(out);
			tickThrough(out, out + 60_000, 0);
			login(out + 60_000, 302, "GroupShip", 0);
		}
		assertEquals("just the first online", 1, posted.size());
		p.logout(NOW + 9 * MIN + 30_000);
		tickThrough(NOW + 9 * MIN + 30_000, NOW + 11 * MIN, 0);
		assertEquals(2, posted.size());
		GroupEvent off = posted.get(1);
		assertTrue(offline(off));
		assertEquals("posted no sooner than ten minutes after the online", NOW + 9 * MIN + 30_000, off.at);
	}

	@Test
	public void titleIsNeverYouAndNeverSwapped()
	{
		login(NOW, 303, "GroupShip", GRACE);
		p.logout(NOW + 30 * MIN);
		tickThrough(NOW + 30 * MIN, NOW + 33 * MIN, GRACE);
		login(NOW + 40 * MIN, 303, "GroupShip", GRACE);
		assertEquals(3, posted.size());
		Gson gson = new Gson();
		String[] titles = {"GroupShip: Online", "GroupShip: Offline", "GroupShip: Online"};
		for (int i = 0; i < 3; i++)
		{
			GroupEvent e = posted.get(i);
			JsonObject o = new JsonParser().parse(
				DiscordWebhook.payload(gson, e, new FakeItems(), DiscordStyle.EMBED, "", false)).getAsJsonObject();
			JsonObject embed = o.getAsJsonArray("embeds").get(0).getAsJsonObject();
			assertEquals(titles[i], embed.get("title").getAsString());
			String description = embed.get("description").getAsString();
			assertFalse(description, description.contains("You"));
			assertEquals(i == 1, description.startsWith("offline"));
			String plain = new JsonParser().parse(
				DiscordWebhook.payload(gson, e, new FakeItems(), DiscordStyle.PLAIN, "", false))
				.getAsJsonObject().get("content").getAsString();
			assertTrue(plain, plain.startsWith("GroupShip: " + (i == 1 ? "offline" : "is online")));
		}
	}

	@Test
	public void aLoginWithNoNameIsIgnored()
	{
		login(NOW, 303, "", GRACE);
		login(NOW, 303, null, GRACE);
		login(NOW, 303, "You", GRACE);
		assertTrue(posted.isEmpty());
	}

	@Test
	public void anotherAccountLoggingInPostsTheFirstOneOffline()
	{
		login(NOW, 303, "GroupShip", GRACE);
		p.logout(NOW + 30 * MIN);
		login(NOW + 31 * MIN, 303, "Alt", GRACE);
		assertEquals(3, posted.size());
		assertEquals("GroupShip", posted.get(1).member);
		assertTrue(offline(posted.get(1)));
		assertEquals("Alt", posted.get(2).member);
		assertEquals("online", posted.get(2).text);
	}

	@Test
	public void clientClosedInTheGracePostsOnNextStartWhenFresh()
	{
		login(NOW, 303, "GroupShip", GRACE);
		posted.clear();
		long closed = NOW + 60 * MIN;
		p.logout(closed);
		String saved = p.save();

		PresenceDebounce fresh = PresenceDebounce.parse(saved, ZoneOffset.UTC);
		GroupEvent off = fresh.poll(closed + 5 * MIN, GRACE);
		assertTrue(offline(off));
		assertEquals("GroupShip", off.member);
		assertEquals("played 1h 0m", 60, off.number);

		PresenceDebounce stale = PresenceDebounce.parse(saved, ZoneOffset.UTC);
		assertNull("never a stale offline hours later", stale.poll(closed + 3 * TimeUnit.HOURS.toMillis(1), GRACE));
		assertNull(stale.poll(closed + 4 * TimeUnit.HOURS.toMillis(1), GRACE));
	}

	@Test
	public void closedAndBackWithinTheGraceIsNothing()
	{
		login(NOW, 303, "GroupShip", GRACE);
		posted.clear();
		p.logout(NOW + 60 * MIN);
		PresenceDebounce restored = PresenceDebounce.parse(p.save(), ZoneOffset.UTC);
		assertTrue(restored.login(NOW + 61 * MIN, 303, "GroupShip", GRACE).isEmpty());
		assertNull(restored.poll(NOW + 90 * MIN, GRACE));
	}

	@Test
	public void unknownTimingIsSkipped()
	{
		assertNull(PresenceDebounce.parse(null, ZoneOffset.UTC).poll(NOW, GRACE));
		assertNull(PresenceDebounce.parse("garbage", ZoneOffset.UTC).poll(NOW, GRACE));
		assertNull(PresenceDebounce.parse("", ZoneOffset.UTC).poll(NOW, GRACE));
	}

	@Test
	public void restartWhileLoggedInIsNotALogout()
	{
		login(NOW, 303, "GroupShip", GRACE);
		posted.clear();
		p.logout(NOW + 60 * MIN);
		PresenceDebounce restored = PresenceDebounce.parse(p.save(), ZoneOffset.UTC);
		restored.resume();
		assertNull(restored.poll(NOW + 90 * MIN, GRACE));
		assertTrue(restored.login(NOW + 90 * MIN, 303, "GroupShip", GRACE).isEmpty());
	}

	@Test
	public void graceIsClampedToTenMinutes()
	{
		login(NOW, 303, "GroupShip", 99);
		p.logout(NOW + 60 * MIN);
		assertTrue(offline(p.poll(NOW + 70 * MIN, 99)));
	}

	@Test
	public void sessionLength()
	{
		assertEquals("under a minute", PresenceDebounce.played(0));
		assertEquals("45m", PresenceDebounce.played(45));
		assertEquals("1h 0m", PresenceDebounce.played(60));
		assertEquals("1h 12m", PresenceDebounce.played(72));
	}

	@Test
	public void backAfterDays()
	{
		long day = TimeUnit.DAYS.toMillis(1);
		assertNull(PresenceDebounce.back(0, NOW, 7, "Alex"));
		assertNull(PresenceDebounce.back(NOW - 6 * day, NOW, 7, "Alex"));
		GroupEvent back = PresenceDebounce.back(NOW - 9 * day - 5, NOW, 7, "Alex");
		assertEquals(GroupEvent.Type.BACK, back.type);
		assertEquals(9, back.number);
	}
}

package com.vinnyvangogh.groupironman;

import java.util.List;
import org.junit.Before;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ProgressTrackerTest
{
	private static final String[] SKILLS = {"Attack", "Strength", "Defence"};
	private ProgressTracker tracker;

	@Before
	public void login()
	{
		tracker = new ProgressTracker(SKILLS.length);
		for (String s : SKILLS)
		{
			assertTrue("the login burst is only remembered", tracker.skill(s, 90, 5_400_000, NOW, "Alex").isEmpty());
		}
	}

	@Test
	public void aLevelUpIsOneEventWithSkillAndLevel()
	{
		List<GroupEvent> out = tracker.skill("Attack", 91, 5_902_831, NOW, "Alex");
		assertEquals(1, out.size());
		GroupEvent e = out.get(0);
		assertEquals(GroupEvent.Type.LEVEL_UP, e.type);
		assertEquals("Attack", e.text);
		assertEquals(91, e.number);
		assertEquals("Alex", e.member);
		assertTrue("XP alone is not a level", tracker.skill("Attack", 91, 5_910_000, NOW, "Alex").isEmpty());
	}

	@Test
	public void ninetyNineIsAlsoMaxed()
	{
		List<GroupEvent> out = tracker.skill("Attack", 99, 13_034_431, NOW, "Alex");
		assertEquals(GroupEvent.Type.LEVEL_UP, out.get(0).type);
		assertEquals(GroupEvent.Type.MAXED, out.get(1).type);
		assertEquals("Attack", out.get(1).text);
		assertEquals("crossed 10M too", GroupEvent.Type.XP_MILESTONE, out.get(2).type);
		assertEquals(10_000_000L, out.get(2).number);
	}

	@Test
	public void xpMilestonesFireOnceEach()
	{
		ProgressTracker t = new ProgressTracker(1);
		t.skill("Mining", 99, 199_000_000, NOW, "Alex");
		List<GroupEvent> out = t.skill("Mining", 99, 200_000_000, NOW, "Alex");
		assertEquals(1, out.size());
		assertEquals(200_000_000L, out.get(0).number);
		assertTrue(t.skill("Mining", 99, 200_000_000, NOW, "Alex").isEmpty());
	}

	@Test
	public void totalLevelEveryHundredAndMaxTotal()
	{
		ProgressTracker t = new ProgressTracker(2);
		t.skill("Attack", 99, 13_034_431, NOW, "Alex");
		t.skill("Strength", 98, 11_805_606, NOW, "Alex");
		List<GroupEvent> out = t.skill("Strength", 99, 13_034_431, NOW, "Alex");
		assertTrue(out.stream().anyMatch(e -> e.type == GroupEvent.Type.MAXED && "total".equals(e.text)
			&& e.number == 198));
		assertTrue("197 to 198 crosses no hundred", out.stream().noneMatch(e -> e.type == GroupEvent.Type.TOTAL_LEVEL));

		ProgressTracker h = new ProgressTracker(2);
		h.skill("Attack", 50, 0, NOW, "Alex");
		h.skill("Strength", 49, 0, NOW, "Alex");
		GroupEvent total = h.skill("Strength", 50, 0, NOW, "Alex").stream()
			.filter(e -> e.type == GroupEvent.Type.TOTAL_LEVEL).findFirst().orElse(null);
		assertNotNull(total);
		assertEquals(100, total.number);
	}

	@Test
	public void combatAndQuestPoints()
	{
		assertNull("first value is the baseline", tracker.combat(100, NOW, "Alex"));
		assertNull(tracker.combat(100, NOW, "Alex"));
		assertEquals(101, tracker.combat(101, NOW, "Alex").number);

		assertNull(tracker.questPoints(49, NOW, "Alex"));
		assertNull(tracker.questPoints(49, NOW, "Alex"));
		GroupEvent qp = tracker.questPoints(51, NOW, "Alex");
		assertEquals(GroupEvent.Type.QUEST_POINTS, qp.type);
		assertEquals(50, qp.number);
	}

	@Test
	public void aResetForgetsTheBaseline()
	{
		tracker.reset();
		assertTrue("another account's levels are a baseline, not level ups",
			tracker.skill("Attack", 99, 13_034_431, NOW, "Sam").isEmpty());
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Deque;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The bundled quest data and the 1 Defence presets built on it. The Defence check is the one that produced the
 * preset list (Board 2026-11-14): no quest a preset reaches, prerequisites included, may reward Defence experience
 * or need Defence above 1.
 */
public class QuestDataTest
{
	private static final Gson GSON = new Gson();
	private static final QuestData DATA = QuestData.load(GSON);
	private static final ShopPresets PRESETS = ShopPresets.load(GSON);

	private static final String COOKS_ASSISTANT = "Cook's Assistant";
	private static final String RFD = "Recipe for Disaster/";
	private static final int BUCKET = 1925;
	private static final int MILK = 1927;
	private static final int EGG = 1944;
	private static final int FLOUR = 1933;

	/** Every quest {@code roots} reach, walked here independently of {@link ShopNeeds}. */
	private static Set<String> walk(List<String> roots)
	{
		Set<String> out = new HashSet<>();
		Deque<QuestData.Quest> todo = new ArrayDeque<>();
		for (String r : roots)
		{
			QuestData.Quest q = DATA.quest(r);
			assertNotNull("bundled data lacks " + r, q);
			todo.add(q);
		}
		while (!todo.isEmpty())
		{
			QuestData.Quest q = todo.pop();
			if (out.add(q.name()))
			{
				for (long pre : q.prerequisites())
				{
					QuestData.Quest p = DATA.quest(pre);
					assertNotNull(q.name() + " names prerequisite " + pre + ", which the data lacks", p);
					todo.add(p);
				}
			}
		}
		return out;
	}

	/** A preset's quests and every option it can be picked with. */
	private static List<String> everyRoot(ShopPresets.Preset p)
	{
		List<String> roots = new ArrayList<>(p.quests());
		if (p.choice() != null)
		{
			roots.addAll(p.choice().from());
		}
		return roots;
	}

	private static ShopPresets.Preset mithrilGloves()
	{
		ShopPresets.Preset p = PRESETS.preset("mithril-gloves");
		assertNotNull(p);
		return p;
	}

	@Test
	public void theDataSaysWhereItCameFrom()
	{
		assertEquals("VinnyVanGogh/questpath-plugin", DATA.source().get("repo"));
		assertEquals("ee638ff", DATA.source().get("commit"));
		assertEquals("src/main/resources/com/vinnyvangogh/questpath/quests.json", DATA.source().get("path"));
		assertTrue(DATA.questNames().size() >= DATA.quests().size());
	}

	/** Every quest in the closure of {@code roots} that rewards Defence xp or needs Defence above 1. */
	private static List<String> defenceProblems(QuestData data, List<String> roots)
	{
		List<String> problems = new ArrayList<>();
		for (QuestData.Quest q : ShopNeeds.closure(data, roots))
		{
			q.rewards().stream().filter(r -> "defence".equalsIgnoreCase(r.skill()) && r.xp() > 0)
				.forEach(r -> problems.add(q.name() + " rewards " + r.xp() + " Defence xp"));
			q.requirements().stream().filter(r -> "defence".equalsIgnoreCase(r.skill()) && r.level() > 1)
				.forEach(r -> problems.add(q.name() + " needs " + r.level() + " Defence"));
		}
		return problems;
	}

	@Test
	public void noPresetQuestRewardsDefenceOrNeedsIt()
	{
		assertFalse(PRESETS.presets().isEmpty());
		List<String> problems = new ArrayList<>();
		for (ShopPresets.Preset p : PRESETS.presets())
		{
			// The independent walk first, so a missing prerequisite fails loudly rather than shrinking the closure.
			assertEquals(walk(everyRoot(p)).size(), ShopNeeds.closure(DATA, everyRoot(p)).size());
			defenceProblems(DATA, everyRoot(p)).forEach(s -> problems.add(p.name() + ": " + s));
		}
		assertEquals(Collections.emptyList(), problems);
	}

	@Test
	public void theDefenceCheckCatchesAPrerequisiteThatRewardsDefence() throws Exception
	{
		// Sir Amik Varze's shape: the subquest itself is clean, a prerequisite (Nature Spirit) is not.
		QuestData d = ShopSourcesTest.data("{\"quests\":["
			+ "{\"id\":157,\"name\":\"RFD/Sir Amik\",\"prerequisites\":[55]},"
			+ "{\"id\":55,\"name\":\"Nature Spirit\",\"rewards\":[{\"skill\":\"defence\",\"xp\":2000}]},"
			+ "{\"id\":9,\"name\":\"Needs Defence\",\"requirements\":[{\"skill\":\"defence\",\"level\":30}]}]}");
		assertEquals(Collections.singletonList("Nature Spirit rewards 2000.0 Defence xp"),
			defenceProblems(d, Collections.singletonList("RFD/Sir Amik")));
		assertEquals(1, defenceProblems(d, Collections.singletonList("Needs Defence")).size());
	}

	@Test
	public void theNinePresetsAreThe1DefenceMilestones()
	{
		List<String> ids = new ArrayList<>();
		PRESETS.presets().forEach(p -> ids.add(p.id()));
		assertEquals(Arrays.asList("mithril-gloves", "avas-accumulator", "ancient-magicks", "dragon-scimitar",
			"dragon-dagger", "climbing-boots", "ibans-staff", "god-books", "waterfall-quest"), ids);
		for (ShopPresets.Preset p : PRESETS.presets())
		{
			for (String quest : everyRoot(p))
			{
				assertNotNull(p.name() + ": " + quest + " is not in the bundled data", DATA.quest(quest));
				assertNotNull(p.name() + ": the game has no quest for " + quest, QuestStates.quest(quest));
			}
		}
	}

	@Test
	public void mithrilGlovesPicksFiveOfSixWithAwowogeiToSwapIn()
	{
		ShopPresets.Choice c = mithrilGloves().choice();
		assertEquals(5, c.count());
		assertEquals(6, c.from().size());
		assertEquals(5, c.defaults().size());
		assertFalse(c.defaults().contains(RFD + "Freeing King Awowogei"));
		for (String banned : Arrays.asList("Sir Amik", "Lumbridge Guide", "Culinaromancer"))
		{
			c.from().forEach(option -> assertFalse(option, option.contains(banned)));
		}
		assertTrue(mithrilGloves().roots(null).containsAll(c.defaults()));
		assertTrue("four picks fall back to the defaults",
			mithrilGloves().roots(c.defaults().subList(0, 4)).containsAll(c.defaults()));
	}

	/** Item lines for {@code roots} with nothing done, counted here straight from the data. */
	private static Map<Integer, Long> expected(List<String> roots)
	{
		Map<Integer, Long> out = new TreeMap<>();
		for (String name : walk(roots))
		{
			for (QuestData.Item i : DATA.quest(name).items())
			{
				if (!i.optional() && !i.unresolved() && !i.grouped() && i.itemId() > 0)
				{
					out.merge(i.itemId(), (long) Math.max(1, i.quantity()), Long::sum);
				}
			}
		}
		return out;
	}

	private static Map<Integer, Long> counts(Map<Integer, ShopNeeds.Need> needs)
	{
		Map<Integer, Long> out = new TreeMap<>();
		needs.forEach((id, n) -> out.put(id, n.count));
		return out;
	}

	@Test
	public void mithrilGlovesLinesMatchTheDataForAMemberWithNothingDone()
	{
		List<String> roots = mithrilGloves().roots(null);
		Map<Integer, ShopNeeds.Need> needs = ShopNeeds.forMember(DATA, roots, QuestProgress.UNKNOWN);

		assertEquals(expected(roots), counts(needs));
		// Cook's Assistant's milk, egg and flour are there; its bucket is optional and is not.
		assertTrue(needs.containsKey(MILK));
		assertTrue(needs.containsKey(EGG));
		assertTrue(needs.containsKey(FLOUR));
		assertFalse(needs.containsKey(BUCKET));
		assertTrue(needs.get(MILK).quests.contains(COOKS_ASSISTANT));
	}

	@Test
	public void theListShrinksAsQuestsAreDone()
	{
		List<String> roots = mithrilGloves().roots(null);
		Map<Integer, Long> none = counts(ShopNeeds.forMember(DATA, roots, QuestProgress.UNKNOWN));
		Map<Integer, Long> afterCooks = counts(ShopNeeds.forMember(DATA, roots,
			QuestProgress.of(Collections.singleton(COOKS_ASSISTANT), Collections.emptySet())));

		assertEquals(none.get(MILK) - 1, (long) afterCooks.get(MILK));
		assertEquals(none.get(EGG) - 1, (long) afterCooks.getOrDefault(EGG, 0L));
		long totalNone = none.values().stream().mapToLong(Long::longValue).sum();
		long totalAfter = afterCooks.values().stream().mapToLong(Long::longValue).sum();
		assertTrue(totalAfter < totalNone);

		QuestProgress all = QuestProgress.of(walk(roots), Collections.emptySet());
		assertTrue("everything done leaves nothing to get", ShopNeeds.forMember(DATA, roots, all).isEmpty());
	}

	@Test
	public void swappingInAwowogeiBringsMonkeyMadness()
	{
		List<String> picks = new ArrayList<>(mithrilGloves().choice().defaults());
		picks.remove(RFD + "Freeing Skrach Uglogwee");
		picks.add(RFD + "Freeing King Awowogei");
		List<String> roots = mithrilGloves().roots(picks);
		Set<String> quests = new HashSet<>();
		ShopNeeds.questsToDo(DATA, roots, QuestProgress.UNKNOWN).forEach(q -> quests.add(q.name()));
		assertTrue(quests.contains("Monkey Madness I"));
		assertFalse(quests.contains("Big Chompy Bird Hunting"));
		assertEquals(expected(roots), counts(ShopNeeds.forMember(DATA, roots, QuestProgress.UNKNOWN)));
	}

	@Test
	public void prerequisitesComeBeforeTheQuestsThatNeedThem()
	{
		List<QuestData.Quest> order = ShopNeeds.questsToDo(DATA, Collections.singletonList("Desert Treasure I"),
			QuestProgress.UNKNOWN);
		Map<String, Integer> at = new LinkedHashMap<>();
		for (int i = 0; i < order.size(); i++)
		{
			at.put(order.get(i).name(), i);
		}
		assertTrue(at.get("Death Plateau") < at.get("Troll Stronghold"));
		assertTrue(at.get("Troll Stronghold") < at.get("Desert Treasure I"));
	}

	@Test
	public void aCarriedShopNamesAQuestTheDataKnows()
	{
		for (QuestData.Shop s : DATA.shops())
		{
			if (s.reachability() != null)
			{
				for (Long id : s.reachability().requiredQuestIds())
				{
					assertNotNull(s.name() + " is behind quest " + id, DATA.questName(id));
				}
			}
		}
	}
}

package com.vinnyvangogh.groupironman;

import com.vinnyvangogh.testkit.ui.ConfigPanelHarness;
import com.vinnyvangogh.testkit.ui.RuneLiteLook;
import com.vinnyvangogh.testkit.ui.SwingDriver;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Supplier;
import javax.imageio.ImageIO;
import javax.swing.AbstractButton;
import javax.swing.JToggleButton;
import net.runelite.client.ui.ColorScheme;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Renders the README's screenshots from the shot list, each at a fixed size,
 * from made-up scenes (no real account names). Headless.
 *
 * <p>{@code ./gradlew screenshots} writes them into docs/images. In
 * {@code ./gradlew test} the same code writes to build/screenshots, so a
 * change that breaks a shot fails the build rather than the README.
 *
 * <p>Item icons are placeholders with the item's initials: the game cache is
 * not available outside the client. The shots chosen for the README are the
 * ones that read without real icons.
 */
public class ReadmeShots
{
	/** Shots are drawn at the sidebar's width and saved at twice the size, so they stay sharp on a retina screen. */
	static final double SCALE = 2.0;
	static final int WIDTH = GimPanelFixture.PANEL_WIDTH;
	static final Color BACKGROUND = ColorScheme.DARK_GRAY_COLOR;

	/** Name, then the shot's height in panel pixels: every shot of one name is always the same size. */
	static final Map<String, Integer> SHOTS = new LinkedHashMap<>();

	static
	{
		SHOTS.put("settings-tab-leader", 760);
		SHOTS.put("settings-tab-member", 640);
		SHOTS.put("settings-who-posts", 760);
		SHOTS.put("panel-group-hiscores", 760);
		SHOTS.put("storage-log", 520);
		SHOTS.put("settings-discord-connection", 640);
		SHOTS.put("settings-thresholds-advanced", 760);
	}

	@Before
	public void lookLikeRuneLite()
	{
		SwingDriver.onEdt(RuneLiteLook::install);
	}

	static File outputDir()
	{
		String dir = System.getProperty("screenshots.dir");
		return dir != null && !dir.isEmpty() ? new File(dir) : new File("build/screenshots");
	}

	@Test
	public void rendersEveryShotAtItsFixedSize() throws Exception
	{
		Map<String, Supplier<BufferedImage>> renders = new LinkedHashMap<>();
		renders.put("settings-tab-leader", ReadmeShots::settingsLeader);
		renders.put("settings-tab-member", ReadmeShots::settingsMember);
		renders.put("settings-who-posts", ReadmeShots::whoPosts);
		renders.put("panel-group-hiscores", ReadmeShots::groupHiscores);
		renders.put("storage-log", ReadmeShots::storageLog);
		renders.put("settings-discord-connection", ReadmeShots::discordConnection);
		renders.put("settings-thresholds-advanced", ReadmeShots::thresholdsAdvanced);
		assertEquals("every shot in the list has a render", SHOTS.keySet(), renders.keySet());

		File dir = outputDir();
		for (Map.Entry<String, Supplier<BufferedImage>> e : renders.entrySet())
		{
			int w = (int) Math.round(WIDTH * SCALE);
			int h = (int) Math.round(SHOTS.get(e.getKey()) * SCALE);
			BufferedImage shot = SwingDriver.onEdt(() -> SwingDriver.fit(e.getValue().get(), w, h, BACKGROUND));
			File file = new File(dir, e.getKey() + ".png");
			SwingDriver.writePng(shot, file);
			BufferedImage back = ImageIO.read(file);
			assertEquals(e.getKey(), w, back.getWidth());
			assertEquals(e.getKey(), h, back.getHeight());
			assertTrue(e.getKey() + " is not blank", notBlank(back));
		}
	}

	private static boolean notBlank(BufferedImage img)
	{
		int first = img.getRGB(0, 0);
		for (int y = 0; y < img.getHeight(); y += 4)
		{
			for (int x = 0; x < img.getWidth(); x += 4)
			{
				if (img.getRGB(x, y) != first)
				{
					return true;
				}
			}
		}
		return false;
	}

	// ---- The shots ----

	private static BufferedImage panelShot(GimPanelFixture f)
	{
		return f.ui.render(WIDTH, 0, SCALE);
	}

	private static GimPanelFixture settingsTab(String self)
	{
		GimPanelFixture.Scene s = GimPanelFixture.groupScene();
		s.self = self;
		s.settings = new GimPanelFixture.Governance().led(GimPanelFixture.SELF, GimPanelFixture.MOSS, s.now)
			.view(self, true);
		return new GimPanelFixture().show(s).tab("Settings");
	}

	static BufferedImage settingsLeader()
	{
		return panelShot(settingsTab(GimPanelFixture.SELF));
	}

	static BufferedImage settingsMember()
	{
		return panelShot(settingsTab(GimPanelFixture.WREN));
	}

	/** The leader's grid of who posts what, from its header down: it sits below everything else in the tab. */
	static BufferedImage whoPosts()
	{
		GimPanelFixture f = settingsTab(GimPanelFixture.SELF);
		f.ui.click("- " + GroupSettingsSchema.THRESHOLDS);
		f.ui.click("+ Who posts what");
		BufferedImage full = panelShot(f);
		int top = f.ui.yOf(f.ui.button("- Who posts what")) - 4;
		return SwingDriver.from(full, (int) Math.round(top * SCALE));
	}

	static BufferedImage groupHiscores()
	{
		return panelShot(new GimPanelFixture().show(GimPanelFixture.groupScene()));
	}

	/** The Log with the Storage chip ticked. */
	static BufferedImage storageLog()
	{
		GimPanelFixture f = new GimPanelFixture().show(GimPanelFixture.logScene()).tab("Log");
		AbstractButton chip = f.ui.all(JToggleButton.class).stream()
			.filter(b -> "Storage".equals(b.getText()) && b.getToolTipText() != null)
			.findFirst().orElseThrow(() -> new AssertionError("no Storage chip"));
		f.ui.click(chip);
		return panelShot(f);
	}

	static BufferedImage discordConnection()
	{
		ConfigPanelHarness h = ConfigPanelHarness.of("GIM Utilities", GimPanelFixture.DEFAULTS, discordOn());
		h.setOpen("Discord: connection", true);
		return SwingDriver.stack(WIDTH, CONFIG_PAD, SCALE, BACKGROUND, h.section("Discord: connection"));
	}

	static BufferedImage thresholdsAdvanced()
	{
		ConfigPanelHarness h = ConfigPanelHarness.of("GIM Utilities", GimPanelFixture.DEFAULTS,
			Collections.emptyMap());
		h.setOpen("Thresholds", true);
		h.setOpen("Advanced", true);
		return SwingDriver.stack(WIDTH, CONFIG_PAD, SCALE, BACKGROUND, h.section("Thresholds"),
			h.section("Advanced"));
	}

	/** The margin RuneLite's settings page puts around its sections. */
	static final int CONFIG_PAD = 6;

	/** Post to Discord ticked and made-up webhooks, so the fields show as filled secrets. */
	private static Map<String, Object> discordOn()
	{
		Map<String, Object> v = new LinkedHashMap<>();
		v.put("discordEnabled", true);
		String hook = "https://discord.com/api/webhooks/0/made-up";
		for (String key : new String[]{"discordWebhookUrl", "discordGroupUrl", "discordDropsUrl", "discordProgressUrl",
			"discordDeathsUrl", "discordStorageUrl", "discordDigestUrl"})
		{
			v.put(key, hook);
		}
		return v;
	}
}

package com.vinnyvangogh.groupironman;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Region id to place name, from the bundled table. */
public class RegionNamesTest
{
	@Test
	public void theBundledTableLoadsAndKnowsLumbridge()
	{
		RegionNames names = RegionNames.load();
		assertTrue("the table should have hundreds of regions, has " + names.size(), names.size() > 500);
		assertEquals("Lumbridge", names.name(12850));
		assertEquals("Varrock", names.name(12853));
		assertEquals("Grand Exchange", names.name(12598));
		assertEquals("Vorkath", names.name(9023));
	}

	/** Board 2026-11-10: a death at the Chaos Temple read "region 11835". */
	@Test
	public void wildernessPlacesHaveNames()
	{
		RegionNames names = RegionNames.load();
		assertEquals("Chaos Temple", names.describe(11835));
		assertEquals("Ferox Enclave", names.name(12600));
		assertEquals("Edgeville Wilderness", names.name(12343));
		assertEquals("Lava Maze", names.name(12348));
		assertEquals("Graveyard of Shadows", names.name(12601));
		assertEquals("Bandit Camp (Wilderness)", names.name(12089));
		assertEquals("Mage Arena", names.name(12349));
		// The desert's Bandit Camp keeps its name; the city section comes first.
		assertEquals("Bandit Camp", names.name(12590));
		// Every other Wilderness region says so rather than a number.
		for (int x = 46; x <= 52; x++)
		{
			for (int y = 55; y <= 61; y++)
			{
				assertTrue(x + "," + y, names.name(x << 8 | y) != null);
			}
		}
		assertEquals("Wilderness", names.name(12093));
		assertEquals("Edgeville", names.name(12342));
	}

	@Test
	public void anUnknownRegionHasNoName()
	{
		assertNull(RegionNames.load().name(1));
		assertNull(RegionNames.load().name(0));
	}

	/** Board 2026-11-14: a member card read "Offline - last seen W315, region 13470". */
	@Test
	public void region13470IsTheWildernessSlayerCave()
	{
		RegionNames names = RegionNames.load();
		assertEquals("Wilderness Slayer Cave", names.name(13470));
		assertEquals("Wilderness Slayer Cave", names.describe(13470));
	}

	@Test
	public void theGeneratedTableLoadsThroughGetResourceAsStream() throws Exception
	{
		String text = resource("regions-generated.txt");
		assertTrue(text.startsWith("# GENERATED by tools/regions/gen_regions.py"));
		// A generated id regions.txt does not name: Mastering Mixology comes only from RuneLite's minigame list.
		assertEquals("Mastering Mixology", RegionNames.load().name(5421));
	}

	/** Every id either table lists resolves to a name, and the hand table wins where both list one. */
	@Test
	public void everyRegionInTheTablesResolves() throws Exception
	{
		RegionNames names = RegionNames.load();
		RegionNames hand = RegionNames.parse(resource("regions.txt"));
		RegionNames generated = RegionNames.parse(resource("regions-generated.txt"));
		assertTrue(generated.size() > 0);
		for (int id : generated.ids())
		{
			String expected = hand.name(id) != null ? hand.name(id) : generated.name(id);
			assertEquals("region " + id, expected, names.name(id));
		}
		for (int id : hand.ids())
		{
			assertEquals("region " + id, hand.name(id), names.describe(id));
		}
	}

	@Test
	public void anUnknownRegionNeverRendersItsNumber()
	{
		RegionNames full = RegionNames.load();
		RegionNames empty = RegionNames.parse("");
		for (int rx = 0; rx < 256; rx += 3)
		{
			for (int ry = 0; ry < 256; ry += 3)
			{
				int id = rx << 8 | ry;
				if (id == 0)
				{
					continue;
				}
				for (RegionNames names : new RegionNames[]{full, empty})
				{
					String text = names.describe(id);
					assertNotNull(String.valueOf(id), text);
					assertFalse(id + " -> " + text, text.matches(".*\\bregion \\d+.*"));
					// Wilderness levels are at most two digits; a region id is three to five.
					assertFalse(id + " -> " + text, text.matches(".*\\d{3,}.*"));
				}
			}
		}
	}

	@Test
	public void anUnknownRegionIsNamedAfterItsNearestNamedNeighbour()
	{
		// Lumbridge is region 50,50; Draynor is 50,52 (two regions north).
		RegionNames names = RegionNames.parse("Lumbridge=" + (50 << 8 | 50) + "\nDraynor=" + (50 << 8 | 52) + "\n");
		assertEquals("near Lumbridge", names.describe(51 << 8 | 50));
		assertEquals("near Draynor", names.describe(50 << 8 | 53));
		assertEquals("near Draynor", names.describe(51 << 8 | 54));
		// Equal distance: the lower region id wins, so the answer never depends on map order.
		assertEquals("near Lumbridge", names.describe(50 << 8 | 51));
		// Too far from anything named: a broad area, still no number.
		assertEquals("Unmapped area", names.describe(30 << 8 | 30));
	}

	@Test
	public void aNeighbourOnTheSurfaceDoesNotNameACaveBelowIt()
	{
		RegionNames names = RegionNames.parse("Lumbridge=" + (50 << 8 | 50) + "\n");
		// 100 regions north of Lumbridge is the cave layer under it (y + 6400).
		assertEquals("under Lumbridge", names.describe(50 << 8 | 150));
		assertEquals("underground near Lumbridge", names.describe(51 << 8 | 150));
		assertEquals("Underground", RegionNames.parse("").describe(20 << 8 | 150));
	}

	@Test
	public void theWildernessSaysItsLevel()
	{
		RegionNames empty = RegionNames.parse("");
		// Surface: level = (y - 3520) / 8 + 1. Region 50,55 is y 3520-3583: levels 1-8.
		assertEquals("Wilderness lvl 1-8", empty.describe(50 << 8 | 55));
		assertEquals("Wilderness lvl 49-56", empty.describe(50 << 8 | 61));
		// Underground: level = (y - 9920) / 8 + 1. Region 52,158 is y 10112-10175: levels 25-32.
		assertEquals("Wilderness lvl 25-32 (underground)", empty.describe(52 << 8 | 158));
		// A Wilderness name nearby does not replace the level: proximity is a guess, the level is not.
		RegionNames named = RegionNames.parse("Lava Maze=" + (48 << 8 | 60) + "\n");
		assertEquals("Wilderness lvl 33-40", named.describe(48 << 8 | 59));
	}

	@Test
	public void anInstanceSaysSo()
	{
		// Instanced maps are built at x >= 6400 (region x >= 100) on the surface rows.
		assertEquals("Instance", RegionNames.parse("").describe(120 << 8 | 40));
		assertEquals("Instance", RegionNames.load().describe(120 << 8 | 40));
	}

	/** Through RegionNames' own getResourceAsStream reader; "" there means the resource did not load. */
	private static String resource(String name)
	{
		String text = RegionNames.resource(name);
		assertFalse(name + " did not load", text.isEmpty());
		return text;
	}

	@Test
	public void theFirstNameForARegionWins()
	{
		RegionNames names = RegionNames.parse("# comment\nCity=1,2\n\nDungeon=2,3\nbroken line\nBad=x,4\n");
		assertEquals("City", names.name(1));
		assertEquals("City", names.name(2));
		assertEquals("Dungeon", names.name(3));
		assertEquals("Bad", names.name(4));
		assertEquals(4, names.size());
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Requests: each member's own named lists the group fills. They travel on the
 * Shopping tab's sync ({@link ShoppingSync}), are edited only by their owner,
 * claimed by anyone, and close when the group holds what was asked.
 */
public class RequestsTest
{
	private static final int SHARK = 385;
	private static final int PRAYER = 2434;
	private final Gson gson = new Gson();

	/** One simulated client, as in {@code ShoppingSyncTest}. */
	private final class Client extends ShoppingClient
	{
		Client(String name)
		{
			super(gson, name);
		}
	}

	private static Map<Integer, Integer> fireCape()
	{
		Map<Integer, Integer> items = new TreeMap<>();
		items.put(SHARK, 500);
		items.put(PRAYER, 20);
		return items;
	}

	private static ShopAllocation.Holdings holdings(String member, int id, long qty, long inStorage)
	{
		Map<String, Map<Integer, Long>> members = new LinkedHashMap<>();
		Map<Integer, Long> m = new TreeMap<>();
		m.put(id, qty);
		members.put(member, m);
		Map<Integer, Long> storage = new TreeMap<>();
		storage.put(id, inStorage);
		return new ShopAllocation.Holdings(members, storage);
	}

	private static ShopAllocation.Holdings nothing()
	{
		return new ShopAllocation.Holdings(Collections.emptyMap(), Collections.emptyMap());
	}

	private static RequestBoard.Row row(RequestBoard.Card c, int id)
	{
		for (RequestBoard.Row r : c.rows)
		{
			if (r.itemId == id)
			{
				return r;
			}
		}
		throw new AssertionError("no row for " + id);
	}

	// ---- Named and unnamed lists ----

	@Test
	public void aNamedRequestKeepsItsName()
	{
		RequestList r = RequestList.create("Fire cape", fireCape(), "Alice", 1000);
		assertEquals("Fire cape", r.name);
		assertEquals("Alice", r.owner);
		assertEquals(Integer.valueOf(500), r.items.get(SHARK));
		assertFalse(r.closed);
	}

	@Test
	public void anUnnamedRequestIsNamedForItsOwner()
	{
		assertEquals("Alice's requests", RequestList.create("  ", fireCape(), "Alice", 1000).name);
		assertEquals("Alice's requests", RequestList.create(null, fireCape(), "Alice", 1000).name);
	}

	@Test
	public void eachMemberHasTheirOwnListsAndTheyReachTheGroup()
	{
		Client alice = new Client("Alice");
		Client bob = new Client("Bob");
		assertTrue(alice.sync.addRequest(RequestList.create("Fire cape", fireCape(), "Alice", 1000)));
		assertTrue(bob.sync.addRequest(RequestList.create("", Collections.singletonMap(SHARK, 100), "Bob", 1100)));
		alice.tick(bob);
		bob.tick(alice);

		for (Client c : new Client[]{alice, bob})
		{
			List<RequestList> live = c.sync.requests();
			assertEquals(2, live.size());
			assertEquals("Fire cape", live.get(0).name);
			assertEquals("Alice", live.get(0).owner);
			assertEquals("Bob's requests", live.get(1).name);
			assertEquals("Bob", live.get(1).owner);
		}
		assertEquals("Bob asked for 'Bob's requests'", alice.sync.history().get(0).text);
	}

	@Test
	public void aRequestWithNoItemsIsRefused()
	{
		Client alice = new Client("Alice");
		assertFalse(alice.sync.addRequest(RequestList.create("Empty", Collections.emptyMap(), "Alice", 1000)));
		assertTrue(alice.sync.requests().isEmpty());
	}

	// ---- Counting ----

	@Test
	public void countsFollowWhatTheGroupHolds()
	{
		RequestList r = RequestList.create("Fire cape", fireCape(), "Alice", 1000);
		RequestBoard.Card before = RequestBoard.card(r, Collections.emptyList(), nothing(), id -> "item " + id);
		assertEquals(0, row(before, SHARK).have);
		assertEquals(500, row(before, SHARK).wanted);
		assertFalse(row(before, SHARK).done());

		// Bob's bank and inventory (one source total) plus group storage, canonical ids as the shopping list counts.
		RequestBoard.Card after = RequestBoard.card(r, Collections.emptyList(), holdings("Bob", SHARK, 300, 150),
			id -> "item " + id);
		assertEquals(450, row(after, SHARK).have);
		assertFalse(row(after, SHARK).done());
		assertEquals(0, after.done());
	}

	@Test
	public void anItemClosesByItselfOnceTheGroupHoldsTheAmount()
	{
		RequestList r = RequestList.create("Fire cape", fireCape(), "Alice", 1000);
		RequestBoard.Card c = RequestBoard.card(r, Collections.emptyList(), holdings("Bob", SHARK, 400, 100),
			id -> "item " + id);
		assertTrue(row(c, SHARK).done());
		assertFalse(row(c, PRAYER).done());
		assertFalse("one item still open", c.done() == c.rows.size());
		assertEquals(Collections.singleton(SHARK), RequestBoard.reached(c));
	}

	@Test
	public void theOwnerSealsReachedItemsAndTheListClosesWhenAllAreDone()
	{
		Client alice = new Client("Alice");
		RequestList r = RequestList.create("Fire cape", Collections.singletonMap(SHARK, 500), "Alice", 1000);
		alice.sync.addRequest(r);
		RequestBoard.Card c = RequestBoard.card(alice.sync.request(r.id), Collections.emptyList(),
			holdings("Bob", SHARK, 500, 0), id -> "Shark");
		assertTrue(c.allDone());

		RequestList sealed = alice.sync.closeItems(r.id, RequestBoard.reached(c), "Alice", 2000);
		assertNotNull(sealed);
		assertTrue("every item done closes the whole list", sealed.closed);
		assertTrue(sealed.closedItems.contains(SHARK));

		// Sealed: it stays done when the sharks are eaten.
		RequestBoard.Card later = RequestBoard.card(alice.sync.request(r.id), Collections.emptyList(), nothing(),
			id -> "Shark");
		assertTrue(row(later, SHARK).done());
		assertTrue(later.allDone());
	}

	@Test
	public void theOwnerCanCloseAnItemTheGroupDoesNotHold()
	{
		Client alice = new Client("Alice");
		RequestList r = RequestList.create("Fire cape", fireCape(), "Alice", 1000);
		alice.sync.addRequest(r);
		RequestList next = alice.sync.closeItems(r.id, Collections.singleton(PRAYER), "Alice", 2000);
		assertNotNull(next);
		assertFalse(next.closed);
		RequestBoard.Card c = RequestBoard.card(next, Collections.emptyList(), nothing(), id -> "x");
		assertTrue(row(c, PRAYER).done());
		assertFalse(row(c, SHARK).done());
	}

	// ---- Claims ----

	@Test
	public void anyoneCanClaimAndUnclaim()
	{
		Client alice = new Client("Alice");
		Client bob = new Client("Bob");
		RequestList r = RequestList.create("Fire cape", fireCape(), "Alice", 1000);
		alice.sync.addRequest(r);
		alice.tick(bob);

		assertTrue(bob.sync.claim(r.id, SHARK, "Bob", true, 2000));
		bob.tick(alice);
		RequestBoard.Card c = RequestBoard.card(alice.sync.request(r.id), alice.sync.claims(r.id), nothing(),
			id -> "Shark");
		assertEquals(Collections.singletonList("Bob"), row(c, SHARK).claimedBy);
		assertTrue(row(c, PRAYER).claimedBy.isEmpty());

		assertTrue(bob.sync.claim(r.id, SHARK, "Bob", false, 3000));
		bob.tick(alice);
		c = RequestBoard.card(alice.sync.request(r.id), alice.sync.claims(r.id), nothing(), id -> "Shark");
		assertTrue(row(c, SHARK).claimedBy.isEmpty());
	}

	@Test
	public void twoMembersCanClaimTheSameItemWithoutLosingEitherClaim()
	{
		Client alice = new Client("Alice");
		Client bob = new Client("Bob");
		Client cat = new Client("Cat");
		RequestList r = RequestList.create("Fire cape", fireCape(), "Alice", 1000);
		alice.sync.addRequest(r);
		alice.tick(bob, cat);
		bob.sync.claim(r.id, SHARK, "Bob", true, 2000);
		cat.sync.claim(r.id, SHARK, "Cat", true, 2000);
		bob.tick(alice, cat);
		cat.tick(alice, bob);
		for (Client c : new Client[]{alice, bob, cat})
		{
			RequestBoard.Card card = RequestBoard.card(c.sync.request(r.id), c.sync.claims(r.id), nothing(), id -> "x");
			assertEquals(c.name, 2, row(card, SHARK).claimedBy.size());
		}
	}

	@Test
	public void anOlderClaimNeverUndoesANewerOne()
	{
		Client alice = new Client("Alice");
		RequestList r = RequestList.create("Fire cape", fireCape(), "Alice", 1000);
		alice.sync.addRequest(r);
		assertTrue(alice.sync.receive("Bob", ShoppingCodec.encode(gson, new RequestClaim(r.id, SHARK, "Bob", false,
			3000))));
		alice.sync.receive("Bob", ShoppingCodec.encode(gson, new RequestClaim(r.id, SHARK, "Bob", true, 2000)));
		assertTrue(alice.sync.claims(r.id).isEmpty() || !alice.sync.claims(r.id).get(0).claimed);
	}

	@Test
	public void claimingAClosedOrMissingRequestIsRefused()
	{
		Client alice = new Client("Alice");
		assertFalse(alice.sync.claim("nosuch", SHARK, "Alice", true, 1000));
		RequestList r = RequestList.create("Fire cape", Collections.singletonMap(SHARK, 1), "Alice", 1000);
		alice.sync.addRequest(r);
		assertFalse("not an item on the list", alice.sync.claim(r.id, PRAYER, "Alice", true, 1500));
		alice.sync.closeRequest(r.id, "Alice", 2000);
		assertFalse(alice.sync.claim(r.id, SHARK, "Alice", true, 3000));
	}

	// ---- Owner-only edits ----

	@Test
	public void onlyTheOwnerEditsTheirList()
	{
		Client alice = new Client("Alice");
		Client bob = new Client("Bob");
		RequestList r = RequestList.create("Fire cape", fireCape(), "Alice", 1000);
		alice.sync.addRequest(r);
		alice.tick(bob);

		assertFalse(bob.sync.renameRequest(r.id, "Bob's now", "Bob", 2000));
		assertFalse(bob.sync.removeRequest(r.id, "Bob", 2000));
		assertFalse(bob.sync.closeRequest(r.id, "Bob", 2000));
		assertNull(bob.sync.closeItems(r.id, Collections.singleton(SHARK), "Bob", 2000));
		assertEquals("Fire cape", bob.sync.request(r.id).name);

		assertTrue(alice.sync.renameRequest(r.id, "Inferno cape", "Alice", 2000));
		alice.tick(bob);
		assertEquals("Inferno cape", bob.sync.request(r.id).name);
		assertTrue(alice.sync.removeRequest(r.id, "Alice", 3000));
		alice.tick(bob);
		assertTrue(bob.sync.requests().isEmpty());
	}

	@Test
	public void aRevisionNamingAnotherOwnerIsIgnored()
	{
		Client alice = new Client("Alice");
		RequestList r = RequestList.create("Fire cape", fireCape(), "Alice", 1000);
		alice.sync.addRequest(r);
		// A forged revision: same id, higher rev, a different owner.
		RequestList forged = new RequestList(r.id, "Mallory", "Mine now", r.items, Collections.emptySet(), false,
			false, 5, 9000, r.created, RequestList.RENAMED);
		alice.sync.receive("Mallory", ShoppingCodec.encode(gson, forged));
		assertEquals("Fire cape", alice.sync.request(r.id).name);
		assertEquals("Alice", alice.sync.request(r.id).owner);
	}

	@Test
	public void ownerNamesMatchTheWayTheRosterDoes()
	{
		Client alice = new Client("Iron Alice");
		RequestList r = RequestList.create("Fire cape", fireCape(), "Iron Alice", 1000);
		alice.sync.addRequest(r);
		assertTrue(alice.sync.renameRequest(r.id, "Cape", "Iron_Alice", 2000));
	}

	// ---- The wire and older clients ----

	@Test
	public void requestsAndClaimsRoundTrip()
	{
		RequestList r = RequestList.create("Fire cape", fireCape(), "Alice", 1000)
			.withClosedItems(Collections.singleton(PRAYER), 2000);
		ShoppingCodec.Message m = ShoppingCodec.decode(gson, ShoppingCodec.encode(gson, r));
		assertNotNull(m);
		assertNotNull(m.request);
		assertEquals(r.id, m.request.id);
		assertEquals("Alice", m.request.owner);
		assertEquals(r.items, m.request.items);
		assertEquals(Collections.singleton(PRAYER), m.request.closedItems);
		assertEquals(2, m.request.rev);

		RequestClaim claim = new RequestClaim(r.id, SHARK, "Bob", true, 3000);
		ShoppingCodec.Message cm = ShoppingCodec.decode(gson, ShoppingCodec.encode(gson, claim));
		assertNotNull(cm.claim);
		assertEquals("Bob", cm.claim.member);
		assertEquals(SHARK, cm.claim.itemId);
		assertTrue(cm.claim.claimed);
	}

	@Test
	public void olderClientsIgnoreRequestsSafely()
	{
		RequestList r = RequestList.create("Fire cape", fireCape(), "Alice", 1000);
		for (String payload : new String[]{ShoppingCodec.encode(gson, r),
			ShoppingCodec.encode(gson, new RequestClaim(r.id, SHARK, "Bob", true, 2000))})
		{
			// gim-test-3 and older: no Shopping tab at all.
			assertNull(GroupCodec.decode(gson, payload));
			assertNull(GroupCodec.posted(gson, payload));
			assertFalse(GovernanceSync.isGovernance(payload));
			assertNull(GovernanceCodec.decode(gson, payload));
			// The first Shopping tab build looked for these two kinds only, then dropped anything else.
			assertFalse(payload.contains("\"k\":\"shop\"") || payload.contains("\"k\":\"qstate\""));
			assertTrue(ShoppingCodec.isShopping(payload));
		}
	}

	@Test
	public void anOlderShoppingListStillReadsAndRequestsNeverBecomeLists()
	{
		Client alice = new Client("Alice");
		ShoppingList old = ShoppingList.create("Ropes", "", Collections.emptyList(), Collections.singletonList("Alice"),
			Collections.singletonMap(954, 2), "Bob", 1000);
		assertTrue(alice.sync.receive("Bob", ShoppingCodec.encode(gson, old)));
		alice.sync.receive("Bob", ShoppingCodec.encode(gson, RequestList.create("Cape", fireCape(), "Bob", 1000)));
		assertEquals(1, alice.sync.active().size());
		assertEquals(1, alice.sync.requests().size());
	}

	@Test
	public void badRequestPayloadsAreDropped()
	{
		assertNull(ShoppingCodec.decode(gson, "{\"v\":1,\"k\":\"req\",\"id\":\"BAD ID\",\"o\":\"A\",\"r\":1,\"ts\":1}"));
		assertNull(ShoppingCodec.decode(gson, "{\"v\":1,\"k\":\"req\",\"id\":\"abc\",\"o\":\"\",\"r\":1,\"ts\":1}"));
		assertNull(ShoppingCodec.decode(gson, "{\"v\":1,\"k\":\"rqc\",\"id\":\"abc\",\"i\":0,\"m\":\"Bob\",\"ts\":1}"));
		assertNull(ShoppingCodec.decode(gson, "{\"v\":1,\"k\":\"rqc\",\"id\":\"abc\",\"i\":\"x\",\"m\":\"Bob\"}"));
	}

	@Test
	public void aJoiningMemberGetsRequestsAndClaims()
	{
		Client alice = new Client("Alice");
		Client bob = new Client("Bob");
		RequestList r = RequestList.create("Fire cape", fireCape(), "Alice", 1000);
		alice.sync.addRequest(r);
		alice.sync.claim(r.id, SHARK, "Alice", true, 1500);
		alice.sync.flush("Alice");
		alice.sent.clear();

		alice.sync.resendAll();
		alice.tick(bob);
		assertEquals(1, bob.sync.requests().size());
		assertEquals(1, bob.sync.claims(r.id).size());
	}

	@Test
	public void theCacheKeepsRequestsAndClaims()
	{
		Client alice = new Client("Alice");
		RequestList r = RequestList.create("Fire cape", fireCape(), "Alice", 1000);
		alice.sync.addRequest(r);
		alice.sync.claim(r.id, SHARK, "Bob", true, 1500);
		JsonObject cache = alice.sync.toCache();

		Client again = new Client("Alice");
		again.sync.fromCache(cache, 2000);
		assertEquals("Fire cape", again.sync.request(r.id).name);
		assertEquals(1, again.sync.claims(r.id).size());
	}

	// ---- The panel's words ----

	@Test
	public void theCardSaysWhatIsLeftAndWhoIsGettingIt()
	{
		RequestList r = RequestList.create("Fire cape", fireCape(), "Alice", 1000);
		List<RequestClaim> claims = new ArrayList<>();
		claims.add(new RequestClaim(r.id, SHARK, "Bob", true, 2000));
		claims.add(new RequestClaim(r.id, SHARK, "Cat", true, 2001));
		RequestBoard.Card c = RequestBoard.card(r, claims, holdings("Bob", SHARK, 300, 150),
			id -> id == SHARK ? "Shark" : "Prayer potion(4)");
		assertEquals("Shark  450 / 500", RequestCards.summary(row(c, SHARK)));
		assertEquals("Need 50 more", RequestCards.needText(row(c, SHARK)));
		assertEquals("Bob and Cat will get it", RequestCards.claimText(row(c, SHARK)));
		assertEquals("", RequestCards.claimText(row(c, PRAYER)));
		assertTrue(RequestCards.claimedBy(row(c, SHARK), "cat"));
		assertEquals("Asked by Alice, " + BoostText.ago(1000, 1000) + ". 0 of 2 done.", RequestCards.byline(c, 1000));
	}

	// ---- Discord ----

	@Test
	public void theDiscordPostIsOffByDefault()
	{
		GroupIronmanConfig defaults = new GroupIronmanConfig()
		{
		};
		assertFalse(defaults.discordRequest());
		assertFalse(defaults.overlayRequest());
		assertEquals(Webhook.MAIN, Webhook.of(GroupEvent.Type.REQUEST));
	}

	@Test
	public void eachRequestEventReadsAsASentence()
	{
		RequestList r = RequestList.create("Fire cape", fireCape(), "Alice", 1000);
		GroupEvent made = RequestBoard.made(r, id -> id == SHARK ? "Shark" : "Prayer potion(4)", 1000);
		assertEquals("Alice", made.member);
		assertTrue(made.isValid());
		assertEquals("made a request, 'Fire cape': 500 Shark, 20 Prayer potion(4)", EventText.describe(made, null));

		GroupEvent claimed = RequestBoard.claimed(r, SHARK, "Shark", "Bob", 2000);
		assertEquals("Bob", claimed.member);
		assertEquals("will get Shark for Alice's 'Fire cape'", EventText.describe(claimed, null));

		GroupEvent done = RequestBoard.done(r, 3000);
		assertEquals("Alice", done.member);
		assertEquals("'Fire cape' is done: the group has it all", EventText.describe(done, null));
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Map;
import java.util.TreeMap;
import org.junit.Before;
import org.junit.Test;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The Settings tab's draft: what survives a redraw and what replaces it
 * (Board 2026-11-13: the leader's Save sent the old values while another
 * member had the tab open, because any redraw threw the draft away).
 */
public class SettingsDraftTest
{
	private static final GroupIronmanConfig DEFAULTS = new GroupIronmanConfig()
	{
	};

	private GroupSigner.Identity alexId;
	private GroupSigner.Identity samId;
	private GroupGovernance alex;
	private GroupGovernance sam;
	private final SettingsDraft draft = new SettingsDraft();

	@Before
	public void setUp()
	{
		alexId = GroupSigner.Identity.create();
		samId = GroupSigner.Identity.create();
		alex = new GroupGovernance(alexId);
		sam = new GroupGovernance(samId);
		for (GroupGovernance g : new GroupGovernance[]{alex, sam})
		{
			g.group("GroupShip");
			g.receiveMember("Alex", alexId.publicKey(), MemberPrefs.NONE);
			g.receiveMember("Sam", samId.publicKey(), MemberPrefs.NONE);
		}
		alex.claim("Alex", NOW);
		sam.receiveRoles(alex.roles());
	}

	private static Map<String, Long> values(long levelMin)
	{
		Map<String, Long> v = GroupSettingsSchema.seed(DEFAULTS);
		v.put("eventLevelMin", levelMin);
		return v;
	}

	private static Map<String, Long> current(GroupGovernance g)
	{
		GroupSettingsSchema.Resolved r = new GroupSettingsSchema.Resolved(DEFAULTS, g.settings());
		Map<String, Long> out = new TreeMap<>();
		for (GroupSettingsSchema.Setting s : GroupSettingsSchema.ALL)
		{
			out.put(s.key, r.value(s.key));
		}
		return out;
	}

	/** One redraw of Alex's tab, with whatever Alex's client holds now. */
	private void redrawAlex()
	{
		draft.update(alex.myRole("Alex"), alex.roles(), alex.settings(), current(alex));
	}

	@Test
	public void anotherMembersPrefsOrPresenceDoNotTouchTheDraft()
	{
		alex.save("Alex", values(50), NOW + 1);
		redrawAlex();
		draft.put("eventLevelMin", 70);

		// Sam opens the tab, toggles an opt-out and comes online: his announce arrives, the panel redraws.
		MemberPrefs out = new MemberPrefs(true, java.util.EnumSet.noneOf(GroupEvent.Type.class),
			java.util.EnumSet.noneOf(GroupEvent.Type.class));
		alex.receiveMember("Sam", samId.publicKey(), out);
		redrawAlex();
		redrawAlex();

		assertEquals(70L, (long) draft.values().get("eventLevelMin"));
		assertNull(draft.notice());
		GroupSettings saved = alex.save("Alex", draft.values(), NOW + 2);
		assertEquals(70L, (long) saved.values.get("eventLevelMin"));
	}

	@Test
	public void anUneditedDraftFollowsTheGroup()
	{
		alex.save("Alex", values(50), NOW + 1);
		redrawAlex();
		alex.save("Alex", values(60), NOW + 2);
		redrawAlex();
		assertEquals(60L, (long) draft.values().get("eventLevelMin"));
		assertFalse(draft.edited());
		assertNull(draft.notice());
	}

	@Test
	public void aNewVersionUnderADraftKeepsItAndSaysSo()
	{
		alex.setEditor("Alex", "Sam", true, NOW + 1);
		sam.receiveRoles(alex.roles());
		alex.save("Alex", values(50), NOW + 2);
		sam.receiveSettings(alex.settings());
		redrawAlex();
		draft.put("eventLevelMin", 70);

		alex.receiveSettings(sam.save("Sam", values(80), NOW + 3));
		redrawAlex();

		assertEquals("the draft is kept", 70L, (long) draft.values().get("eventLevelMin"));
		assertEquals("Your group's settings changed (version 2 by Sam). Save will replace them, or Discard to"
			+ " see theirs.", draft.notice());

		draft.discard(current(alex));
		assertEquals(80L, (long) draft.values().get("eventLevelMin"));
		assertNull(draft.notice());
	}

	@Test
	public void savingClearsTheNoticeAndOwnSaveDoesNotRaiseOne()
	{
		alex.save("Alex", values(50), NOW + 1);
		redrawAlex();
		draft.put("eventLevelMin", 70);
		assertTrue(draft.edited());
		alex.save("Alex", draft.values(), NOW + 2);
		// The redraw from the save can come before the tab hears the result.
		redrawAlex();
		assertNull("our own save is not someone else's change", draft.notice());
		draft.saved();
		redrawAlex();
		assertFalse(draft.edited());
		assertNull(draft.notice());
	}

	@Test
	public void losingTheRoleResetsTheDraft()
	{
		alex.setEditor("Alex", "Sam", true, NOW + 1);
		sam.receiveRoles(alex.roles());
		draft.update(sam.myRole("Sam"), sam.roles(), sam.settings(), current(sam));
		draft.put("eventLevelMin", 70);

		alex.setEditor("Alex", "Sam", false, NOW + 2);
		sam.receiveRoles(alex.roles());
		draft.update(sam.myRole("Sam"), sam.roles(), sam.settings(), current(sam));

		assertEquals(GroupGovernance.Role.MEMBER, sam.myRole("Sam"));
		assertFalse(draft.edited());
		assertEquals(current(sam).get("eventLevelMin"), draft.values().get("eventLevelMin"));
	}
}

package com.vinnyvangogh.groupironman;

import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;
import com.google.gson.Gson;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import org.slf4j.LoggerFactory;
import static com.vinnyvangogh.groupironman.EventFixtures.NOW;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * "Share webhooks with the group" (Board 2026-11-13): the leader's webhooks reach members inside a signed group
 * document; nothing else may share them, a member's own webhook wins, and a member never keeps them in config.
 */
public class SharedWebhooksTest
{
	private static final String GROUP = GovernanceClient.GROUP;
	private static final String TOKEN = "LEADERSECRETTOKEN";
	private static final String MAIN = "https://discord.com/api/webhooks/111/" + TOKEN + "main";
	private static final String PROGRESS = "https://discord.com/api/webhooks/222/" + TOKEN + "progress";
	private static final String ONLINE = "https://discord.com/api/webhooks/333/" + TOKEN + "online";
	private static final String OWN_DROPS = "https://discord.com/api/webhooks/444/membersowndrops";
	private static final String OWN_ONLINE = "https://discord.com/api/webhooks/555/membersownonline";
	private final Gson gson = new Gson();

	/** One client ({@link GovernanceClient}), with the leader's shared webhooks it holds. */
	private static final class Client extends GovernanceClient
	{
		Client(String name)
		{
			super(name, new Gson());
		}

		GroupWebhooks shared()
		{
			return sync.governance().sharedWebhooks();
		}
	}

	private static Webhooks leaderHooks()
	{
		Map<Webhook, Webhooks.Setting> s = new EnumMap<>(Webhook.class);
		s.put(Webhook.MAIN, new Webhooks.Setting(MAIN, DiscordPosterName.GIM_UTILITIES, ""));
		s.put(Webhook.PROGRESS, new Webhooks.Setting(PROGRESS, DiscordPosterName.CUSTOM, "Leader's Levels"));
		s.put(Webhook.ONLINE, new Webhooks.Setting(ONLINE, DiscordPosterName.WEBHOOK, ""));
		return new Webhooks(s);
	}

	private static Webhooks none()
	{
		return new Webhooks(new EnumMap<>(Webhook.class));
	}

	/** A member's own webhooks: just {@code url} in {@code webhook}'s field. */
	private static Webhooks own(Webhook webhook, String url)
	{
		Map<Webhook, Webhooks.Setting> mine = new EnumMap<>(Webhook.class);
		mine.put(webhook, new Webhooks.Setting(url, DiscordPosterName.WEBHOOK, ""));
		return new Webhooks(mine);
	}

	/** Alex leads, Sam is an editor, Kim is a member; each has heard the others. */
	private Client[] group()
	{
		Client alex = new Client("Alex");
		Client sam = new Client("Sam");
		Client kim = new Client("Kim");
		alex.tick(sam, kim);
		sam.tick(alex, kim);
		kim.tick(alex, sam);
		assertTrue(alex.sync.claim("Alex", NOW));
		assertTrue(alex.sync.setEditor("Alex", "Sam", true, NOW + 1));
		alex.tick(sam, kim);
		assertEquals(GroupGovernance.Role.EDITOR, sam.sync.governance().myRole("Sam"));
		return new Client[]{alex, sam, kim};
	}

	/** {@link #group}, with Alex sharing {@link #leaderHooks} and everyone having heard it. */
	private Client[] sharing()
	{
		Client[] c = group();
		assertTrue(c[0].sync.shareWebhooks("Alex", true, leaderHooks(), NOW + 2));
		c[0].tick(c[1], c[2]);
		assertNotNull(c[2].shared());
		return c;
	}

	private static boolean anyWebhooksDocument(List<String> payloads)
	{
		for (String p : payloads)
		{
			if (p.contains("\"k\":\"" + GovernanceCodec.WEBHOOKS + "\""))
			{
				return true;
			}
		}
		return false;
	}

	@Test
	public void onlyTheLeaderMayTurnSharingOn()
	{
		Client[] c = group();
		Client sam = c[1];
		Client kim = c[2];
		assertFalse("an editor may not", sam.sync.shareWebhooks("Sam", true, leaderHooks(), NOW + 2));
		assertFalse("a member may not", kim.sync.shareWebhooks("Kim", true, leaderHooks(), NOW + 2));
		sam.sync.flush(MemberPrefs.NONE);
		kim.sync.flush(MemberPrefs.NONE);
		assertFalse(anyWebhooksDocument(sam.outbox));
		assertFalse(anyWebhooksDocument(kim.outbox));
		assertNull(sam.sync.governance().webhooks());
		assertNull(kim.sync.governance().webhooks());
	}

	@Test
	public void aDocumentSignedByAnEditorOrAnotherKeyIsRefused()
	{
		Client[] c = group();
		Client alex = c[0];
		Client kim = c[2];
		GroupSigner.Identity stranger = GroupSigner.Identity.create();
		// Signed in Sam's (the editor's) name, and in the leader's name with a key that is not the leader's.
		GroupWebhooks byEditor = GroupWebhooks.next(null, GroupMembers.key(GROUP), true, leaderHooks(), "Sam",
			stranger, NOW + 5);
		GroupWebhooks forged = GroupWebhooks.next(null, GroupMembers.key(GROUP), true, leaderHooks(), "Alex",
			stranger, NOW + 5);
		assertEquals(GroupGovernance.Verdict.REFUSED, kim.sync.governance().receiveWebhooks(byEditor));
		assertEquals(GroupGovernance.Verdict.REFUSED, kim.sync.governance().receiveWebhooks(forged));
		assertNull(kim.shared());

		// A real one, then the same with a URL swapped: the signature no longer checks.
		assertTrue(alex.sync.shareWebhooks("Alex", true, leaderHooks(), NOW + 6));
		GroupWebhooks real = alex.sync.governance().webhooks();
		Map<Webhook, Webhooks.Setting> swapped = new EnumMap<>(real.settings);
		swapped.put(Webhook.MAIN, new Webhooks.Setting(OWN_DROPS, DiscordPosterName.WEBHOOK, ""));
		GroupWebhooks tampered = new GroupWebhooks(real.group, real.version + 1, real.at, real.by, real.byKey, true,
			swapped, real.signature);
		assertEquals(GroupGovernance.Verdict.REFUSED, kim.sync.governance().receiveWebhooks(tampered));
	}

	@Test
	public void aMemberGetsTheLeadersWebhooksButNeverInConfigOrLogs()
	{
		Client[] c = group();
		Client alex = c[0];
		Client kim = c[2];
		Logger root = (Logger) LoggerFactory.getLogger(org.slf4j.Logger.ROOT_LOGGER_NAME);
		ListAppender<ILoggingEvent> appender = new ListAppender<>();
		appender.start();
		root.addAppender(appender);
		try
		{
			assertTrue(alex.sync.shareWebhooks("Alex", true, leaderHooks(), NOW + 2));
			alex.tick(kim);
			// A copy with a broken signature is refused, which logs: the log must not carry its URLs either.
			GroupWebhooks real = alex.sync.governance().webhooks();
			kim.sync.receive("Alex", GovernanceCodec.encode(gson, new GroupWebhooks(real.group, real.version + 1,
				real.at, real.by, real.byKey, true, real.settings, "bad")));
			kim.start();
		}
		finally
		{
			root.detachAppender(appender);
		}

		GroupWebhooks got = kim.shared();
		assertNotNull("read back from the group cache after a restart", got);
		assertEquals("Alex", got.by);
		assertEquals(PROGRESS, got.settings.get(Webhook.PROGRESS).url);
		for (Map.Entry<String, String> e : kim.config.entrySet())
		{
			assertFalse(e.getKey(), e.getValue().contains(TOKEN));
		}
		assertTrue("kept in the group cache instead", kim.cache.contains(TOKEN));
		for (ILoggingEvent e : appender.list)
		{
			assertFalse(e.getFormattedMessage(), e.getFormattedMessage().contains(TOKEN));
		}
		assertFalse(got.toString().contains(TOKEN));
		assertFalse(SettingsModel.webhookLines(GroupGovernance.Role.MEMBER, got.by).toString().contains(TOKEN));
		assertEquals("Using the group's webhooks (set by Alex).",
			SettingsModel.webhookLines(GroupGovernance.Role.MEMBER, got.by).get(0));
	}

	@Test
	public void aMembersOwnWebhookWinsForItsCategory()
	{
		Client kim = sharing()[2];
		Webhooks merged = own(Webhook.DROPS, OWN_DROPS).withGroup(kim.shared());

		assertEquals("own wins", OWN_DROPS, merged.url(Webhook.DROPS));
		assertFalse(merged.fromGroup(Webhook.DROPS));
		assertEquals("the group's where the member left it empty", PROGRESS, merged.url(Webhook.PROGRESS));
		assertTrue(merged.fromGroup(Webhook.PROGRESS));
		assertEquals("with the leader's poster name", "Leader's Levels", merged.name(Webhook.PROGRESS));
		assertEquals("an empty category lands on the group's Main", MAIN, merged.url(Webhook.DEATHS));
		assertEquals("the group's choice for Main", Webhook.MAIN.defaultName, merged.name(Webhook.MAIN));
		assertNull("the group's choice for Deaths: Webhook's own", merged.name(Webhook.DEATHS));
		assertNull("not shared: nothing to fill in", none().withGroup(null).url(Webhook.MAIN));
	}

	@Test
	public void turningSharingOffClearsMembersCopiesOnTheNextSync()
	{
		Client[] c = sharing();
		Client alex = c[0];
		Client kim = c[2];
		assertTrue(alex.sync.shareWebhooks("Alex", false, leaderHooks(), NOW + 3));
		alex.tick(kim);
		assertNull(kim.shared());
		assertNull(none().withGroup(kim.sync.governance().webhooks()).url(Webhook.MAIN));
		assertFalse("the cached copy is the off version, without URLs", kim.cache.contains(TOKEN));
		kim.start();
		assertNull("and stays off after a restart", kim.shared());
	}

	@Test
	public void theLeadersEditWhileSharingIsANewerVersionAndNoEditSendsNothing()
	{
		Client[] c = sharing();
		Client alex = c[0];
		Client kim = c[2];
		GroupWebhooks first = alex.sync.governance().webhooks();

		assertTrue(alex.sync.shareWebhooks("Alex", true, leaderHooks(), NOW + 3));
		assertSame("unchanged: the same document", first, alex.sync.governance().webhooks());
		alex.sync.flush(MemberPrefs.NONE);
		assertFalse(anyWebhooksDocument(alex.outbox));
		alex.outbox.clear();

		Map<Webhook, Webhooks.Setting> edited = new EnumMap<>(leaderHooks().settings());
		edited.put(Webhook.MAIN, new Webhooks.Setting(OWN_DROPS, DiscordPosterName.WEBHOOK, ""));
		alex.sync.shareWebhooks("Alex", true, new Webhooks(edited), NOW + 4);
		alex.tick(kim);
		assertTrue(kim.shared().version > first.version);
		assertEquals(OWN_DROPS, kim.shared().settings.get(Webhook.MAIN).url);
	}

	@Test
	public void theLiveBoardOnTheSharedWebhookIsPostedByTheLeaderOnly()
	{
		Client[] c = sharing();
		int keepers = 0;
		for (Client client : c)
		{
			boolean leader = client.sync.governance().myRole(client.name) == GroupGovernance.Role.LEADER;
			Webhooks own = leader ? leaderHooks() : none();
			Webhooks hooks = own.withGroup(client.shared());
			assertEquals(ONLINE, hooks.url(Webhook.ONLINE));
			if (StatusBoard.keeps(OnlineStatus.LIVE_BOARD, hooks, leader))
			{
				keepers++;
			}
		}
		assertEquals("one board for the group", 1, keepers);

		// A member's own pasted Online status webhook is theirs, as before sharing existed.
		assertTrue(StatusBoard.keeps(OnlineStatus.LIVE_BOARD, own(Webhook.ONLINE, OWN_ONLINE).withGroup(c[2].shared()),
			false));
		assertFalse(StatusBoard.keeps(OnlineStatus.POSTS, leaderHooks(), true));
	}

	@Test
	public void aNewLeaderDropsTheOldLeadersWebhooks()
	{
		Client kim = sharing()[2];
		kim.sync.forgetLeader();
		assertNull("no leader, no shared webhooks", kim.shared());
	}

	@Test
	public void theFullestDocumentFitsOneMessage()
	{
		Map<Webhook, Webhooks.Setting> s = new EnumMap<>(Webhook.class);
		String longName = new String(new char[PosterNames.MAX]).replace('\0', 'n');
		for (Webhook w : Webhook.values())
		{
			String url = "https://canary.discordapp.com/api/webhooks/123456789012345678901/"
				+ new String(new char[68]).replace('\0', 'x');
			s.put(w, new Webhooks.Setting(url, DiscordPosterName.CUSTOM, longName));
		}
		GroupWebhooks doc = GroupWebhooks.next(null, "a twelve char", true, new Webhooks(s), "A twelve char",
			GroupSigner.Identity.create(), NOW);
		String payload = GovernanceCodec.encode(gson, doc);
		assertTrue(payload.length() + " chars", payload.length() < GroupCodec.MAX_PAYLOAD_CHARS);
		GroupWebhooks back = GovernanceCodec.decode(gson, payload).webhooks;
		assertTrue("survives the round trip with its signature", back.verify());
		assertEquals(7, back.settings.size());
	}
}

package com.vinnyvangogh.groupironman;

import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** The "Turn on sharing" card: one click after pasting the key, nothing on without it (Board 2026-11-13). */
public class SharingPromptTest
{
	private static final String KEY = GroupKey.generate();
	private static final String OTHER_KEY = GroupKey.generate();

	/** Sync and every Share switch off, no webhook. */
	private static SharingPrompt.Settings allOff(String key)
	{
		return new SharingPrompt.Settings(key, false, false, false, false, false);
	}

	/** Sync on, every Share switch off. */
	private static SharingPrompt.Settings syncOnly(String key, boolean webhook)
	{
		return new SharingPrompt.Settings(key, true, false, false, false, webhook);
	}

	private static SharingPrompt.Settings allSharing(String key, boolean webhook, boolean discordOn)
	{
		return new SharingPrompt.Settings(key, true, true, true, discordOn, webhook);
	}

	@Test
	public void shownAfterAKeyPasteWithTheSwitchesOff()
	{
		SharingPrompt p = new SharingPrompt();
		assertNull("sync off, nothing pasted: no card", p.card(allOff(KEY)));
		p.pasted(KEY);
		SharingPrompt.Card card = p.card(allOff(KEY));
		assertNotNull(card);
		assertTrue(card.sharing);
		assertFalse("no webhook, no Discord button", card.discord);
	}

	@Test
	public void shownWhileSyncIsOnAndEveryShareSwitchIsOff()
	{
		SharingPrompt p = new SharingPrompt();
		assertNotNull(p.card(syncOnly(KEY, false)));
	}

	@Test
	public void neverShownWithoutAKey()
	{
		SharingPrompt p = new SharingPrompt();
		p.pasted("");
		assertNull(p.card(syncOnly("", false)));
	}

	@Test
	public void hiddenAfterTurnOnSharingAndStaysHidden()
	{
		SharingPrompt p = new SharingPrompt();
		p.pasted(KEY);
		assertNotNull(p.card(allOff(KEY)));
		assertNull(p.card(allSharing(KEY, false, false)));
		// The player later unticks one switch: the card does not come back to nag.
		assertNull(p.card(new SharingPrompt.Settings(KEY, true, true, false, false, false)));
	}

	@Test
	public void notNowHidesItUntilTheKeyChanges()
	{
		SharingPrompt p = new SharingPrompt();
		p.pasted(KEY);
		p.notNow(KEY);
		assertNull(p.card(allOff(KEY)));
		assertNull("not even while sync is on with every switch off", p.card(syncOnly(KEY, false)));
		p.pasted(OTHER_KEY);
		assertNotNull("a new key brings it back", p.card(allOff(OTHER_KEY)));
	}

	@Test
	public void theDiscordButtonShowsOnlyWithAWebhook()
	{
		SharingPrompt p = new SharingPrompt();
		assertFalse(p.card(syncOnly(KEY, false)).discord);
		assertTrue(p.card(syncOnly(KEY, true)).discord);
		assertFalse("already posting", p.card(new SharingPrompt.Settings(KEY, true, false, false, true, true)).discord);
	}

	@Test
	public void afterTurnOnSharingTheDiscordButtonStaysUntilUsed()
	{
		SharingPrompt p = new SharingPrompt();
		p.pasted(KEY);
		SharingPrompt.Card card = p.card(allSharing(KEY, true, false));
		assertNotNull(card);
		assertFalse(card.sharing);
