package com.vinnyvangogh.groupironman;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Group holdings subtract from what a list needs: own first, then spares, then storage. */
public class ShopAllocationTest
{
	private static final int ROPE = 954;
	private static final int ROPE_NOTED = 955;
	private static final int AMULET = 1478;

	private static ShopNeeds.Need need(int id, String name, long count)
	{
		return new ShopNeeds.Need(id, name, count, true, false, Collections.singleton("Quest"));
	}

	private static Map<String, Map<Integer, ShopNeeds.Need>> needs(String... members)
	{
		Map<String, Map<Integer, ShopNeeds.Need>> out = new LinkedHashMap<>();
		for (String m : members)
		{
			Map<Integer, ShopNeeds.Need> n = new LinkedHashMap<>();
			n.put(ROPE, need(ROPE, "Rope", 2));
			out.put(m, n);
		}
		return out;
	}

	private static Map<Integer, Long> items(int id, long qty)
	{
		Map<Integer, Long> m = new TreeMap<>();
		m.put(id, qty);
		return m;
	}

	@Test
	public void holdingsSubtractAcrossMembersAndStorage()
	{
		Map<String, Map<Integer, Long>> held = new LinkedHashMap<>();
		held.put("Alice", items(ROPE, 1));
		held.put("Bob", Collections.emptyMap());
		held.put("Cara", items(ROPE, 1));
		ShopAllocation.Holdings h = new ShopAllocation.Holdings(held, items(ROPE, 1));

		ShopAllocation.Line line = ShopAllocation.of(needs("Alice", "Bob"), h, id -> true).get(0);

		assertEquals(4, line.totalNeeded());
		// Alice's own 1, Cara's spare 1 (she needs none), then 1 from storage: 3 held, 1 to get.
		assertEquals(3, line.have());
		assertEquals(1, line.stillNeeded());
		assertEquals(1, line.storageUsed);
		assertFalse(line.done());
		assertEquals(Arrays.asList("Alice", "Cara"), Arrays.asList(line.holders.keySet().toArray()));
	}

	@Test
	public void aLineTicksOffWhenTheGroupHoldsEnough()
	{
		Map<String, Map<Integer, Long>> held = new LinkedHashMap<>();
		held.put("Alice", items(ROPE, 4));
		held.put("Bob", Collections.emptyMap());
		ShopAllocation.Line line = ShopAllocation.of(needs("Alice", "Bob"), new ShopAllocation.Holdings(held,
			Collections.emptyMap()), id -> true).get(0);
		assertTrue(line.done());
		assertEquals(0, line.stillNeeded());
	}

	@Test
	public void untradeableItemsOnlyCountTheirOwnHolder()
	{
		Map<String, Map<Integer, Long>> held = new LinkedHashMap<>();
		held.put("Alice", items(ROPE, 4));
		held.put("Bob", Collections.emptyMap());
		ShopAllocation.Line line = ShopAllocation.of(needs("Alice", "Bob"), new ShopAllocation.Holdings(held,
			items(ROPE, 10)), id -> false).get(0);
		assertEquals(2, line.stillNeeded());
		assertEquals(0, line.storageUsed);
	}

	@Test
	public void aMemberWhoSharesNoItemsIsNotJudged()
	{
		Map<String, Map<Integer, Long>> held = new LinkedHashMap<>();
		held.put("Alice", Collections.emptyMap());
		ShopAllocation.Line line = ShopAllocation.of(needs("Alice", "Bob"), new ShopAllocation.Holdings(held,
			Collections.emptyMap()), id -> true).get(0);
		assertEquals(2, line.stillNeeded());
		assertEquals(2, line.unknownNeed());
		assertFalse(line.done());
	}

	@Test
	public void notedItemsCountAsTheItem()
	{
		Map<Integer, Integer> bank = new TreeMap<>();
		// The capture path: every container slot goes through ItemCounts.add with the item manager's canonicalize.
		ItemCounts.add(bank, ROPE_NOTED, 3, id -> id == ROPE_NOTED ? ROPE : id);
		ItemCounts.add(bank, ROPE, 1, id -> id == ROPE_NOTED ? ROPE : id);
		List<GroupSearch.Source> sources = Arrays.asList(
			new GroupSearch.Source("Alice", "bank", bank, 1L),
			new GroupSearch.Source("Group", ShopAllocation.STORAGE_WHERE, Collections.singletonMap(AMULET, 1), 1L));

		ShopAllocation.Holdings h = ShopAllocation.Holdings.from(sources);

		assertEquals(4, h.held("Alice", ROPE));
		assertEquals(Long.valueOf(1), h.storage.get(AMULET));
		assertFalse("storage is not a member", h.known("Group"));
	}

	@Test
	public void membersMatchTheWayTheRosterDoes()
	{
		Map<String, Map<Integer, Long>> held = new LinkedHashMap<>();
		held.put("Iron Bob", items(ROPE, 2));
		ShopAllocation.Holdings h = new ShopAllocation.Holdings(held, Collections.emptyMap());
		assertTrue(h.known("iron_bob"));
		assertEquals(2, h.held("Iron_Bob", ROPE));
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** What the Shopping tab remembers as open, per character. */
public class ShopFoldsTest
{
	/** The RuneLite profile of whoever is logged in, as a plain value. */
	private static final class Profile implements ShopFolds.Store
	{
		String value;

		@Override
		public String load()
		{
			return value;
		}

		@Override
		public void save(String v)
		{
			value = v;
		}
	}

	@Test
	public void everythingStartsClosed()
	{
		ShopFolds f = new ShopFolds(new Profile());
		assertFalse(f.open(ShopFolds.list("abc")));
		assertFalse(f.open(ShopFolds.request("abc")));
	}

	@Test
	public void openingIsSavedAndReadBackByANewTab()
	{
		Profile p = new Profile();
		new ShopFolds(p).toggle(ShopFolds.list("abc"), Collections.singleton(ShopFolds.list("abc")));
		assertEquals("l:abc", p.value);
		assertTrue("a restarted client reads it back", new ShopFolds(p).open(ShopFolds.list("abc")));
	}

	@Test
	public void closingTheLastOneClearsTheSavedValue()
	{
		Profile p = new Profile();
		ShopFolds f = new ShopFolds(p);
		f.toggle("l:abc", Collections.singleton("l:abc"));
		f.toggle("l:abc", Collections.singleton("l:abc"));
		assertFalse(f.open("l:abc"));
		assertNull(p.value);
	}

	@Test
	public void goneListsAreDroppedOnTheNextChange()
	{
		Profile p = new Profile();
		p.value = "l:gone,l:kept";
		ShopFolds f = new ShopFolds(p);
		f.toggle("r:new", Arrays.asList("l:kept", "r:new"));
		assertEquals("l:kept,r:new", p.value);
	}

	@Test
	public void anotherCharactersSavedValueIsReadWhenItChanges()
	{
		Profile p = new Profile();
		ShopFolds f = new ShopFolds(p);
		f.toggle("l:mine", Collections.singleton("l:mine"));
		p.value = "l:theirs";
		assertTrue(f.open("l:theirs"));
		assertFalse(f.open("l:mine"));
	}

	@Test
	public void keysDoNotCollideAcrossKinds()
	{
		assertEquals("i:l:abc:954", ShopFolds.item(ShopFolds.list("abc"), 954));
		assertEquals("d:r:abc", ShopFolds.done(ShopFolds.request("abc")));
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.StringReader;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** An ironman sees only the shops they can be served at, with the wiki's price, and the monsters that drop it. */
public class ShopSourcesTest
{
	private static final String DATA = "{"
		+ "\"quests\":[{\"id\":1,\"name\":\"Fishing quest\",\"items\":[{\"name\":\"Big fishing net\",\"item_id\":305,"
		+ "\"sources\":[\"Shop: Fishing Guild Shop (20 Coins)\",\"Shop: Harry's Fishing Shop (25 Coins)\","
		+ "\"Drop: Goblin (1/128)\"],"
		+ "\"shop_names\":[\"Fishing Guild Shop\",\"Harry's Fishing Shop\",\"Zoo shop\",\"Nowhere shop\"],"
		+ "\"drop_source_names\":[\"Goblin\",\"Revenant imp\"]}]}],"
		+ "\"quest_names\":{\"1\":\"Fishing quest\",\"2\":\"Zogre Flesh Eaters\"},"
		+ "\"shops\":["
		+ "{\"name\":\"Fishing Guild Shop\",\"x\":2611,\"y\":3393,\"reachability\":{\"required_skills\":"
		+ "[{\"skill\":\"fishing\",\"level\":68,\"boostable\":true}]}},"
		+ "{\"name\":\"Harry's Fishing Shop\",\"x\":2833,\"y\":3443},"
		+ "{\"name\":\"Zoo shop\",\"x\":1,\"y\":1,\"reachability\":{\"required_quest_ids\":[2],"
		+ "\"required_quest_ids_started_only\":[2]}}],"
		+ "\"drop_locations\":[{\"source_name\":\"Revenant imp\",\"region\":\"wilderness\"},"
		+ "{\"source_name\":\"Goblin\",\"region\":\"general\"}]}";

	static QuestData data(String json) throws IOException
	{
		return QuestData.parse(new Gson(), new StringReader(json));
	}

	private static ShopSources.Viewer viewer(int fishing, QuestProgress quests)
	{
		Map<String, Integer> levels = new HashMap<>();
		levels.put("Fishing", fishing);
		return new ShopSources.Viewer(levels, quests);
	}

	private static String describe(List<ShopSources.Source> sources)
	{
		StringBuilder s = new StringBuilder();
		for (ShopSources.Source src : sources)
		{
			s.append(src.describe()).append('|');
		}
		return s.toString();
	}

	@Test
	public void shopsBehindLevelsOrQuestsAreLeftOutAndCounted() throws IOException
	{
		QuestData d = data(DATA);
		ShopSources.Options o = ShopSources.forViewer(d.item(305), viewer(59, QuestProgress.UNKNOWN), d);
		assertEquals("Shop: Harry's Fishing Shop (25 gp)|Drop: Goblin (1/128)|Drop: Revenant imp (Wilderness)|",
			describe(o.sources));
		// Guild (68 Fishing), the zoo (Zogre Flesh Eaters not started) and one with no tile.
		assertEquals(3, o.unreachableShops);
	}

	@Test
	public void meetingTheGatesOpensTheShops() throws IOException
	{
		QuestData d = data(DATA);
		QuestProgress started = QuestProgress.of(Collections.emptySet(), Collections.singleton("Zogre Flesh Eaters"));
		ShopSources.Options o = ShopSources.forViewer(d.item(305), viewer(68, started), d);
		assertTrue(describe(o.sources).startsWith("Shop: Fishing Guild Shop (20 gp)|Shop: Harry's Fishing Shop (25 gp)|"
			+ "Shop: Zoo shop|"));
		assertEquals(1, o.unreachableShops);
	}

	@Test
	public void whyAShopWillNotServe() throws IOException
	{
		QuestData d = data(DATA);
		assertEquals("68 fishing", ShopSources.blockedBy(d.shop("Fishing Guild Shop"),
			viewer(59, QuestProgress.UNKNOWN), d));
		assertEquals("Zogre Flesh Eaters", ShopSources.blockedBy(d.shop("Zoo shop"),
			viewer(59, QuestProgress.UNKNOWN), d));
		assertEquals("", ShopSources.blockedBy(d.shop("Harry's Fishing Shop"), viewer(1, QuestProgress.UNKNOWN), d));
	}

	@Test
	public void theShopAlertSaysItOncePerVisit() throws IOException
	{
		QuestData d = data(DATA);
		ShopVisits visits = new ShopVisits();
		List<String> harry = Collections.singletonList("Harry's Fishing Shop");
		assertTrue(visits.arrived(2800, 3443, 0, harry, d).isEmpty());
		assertEquals(harry, visits.arrived(2830, 3440, 0, harry, d));
		assertTrue("still there", visits.arrived(2833, 3443, 0, harry, d).isEmpty());
		assertTrue("upstairs is not there", new ShopVisits().arrived(2833, 3443, 1, harry, d).isEmpty());
		visits.arrived(2700, 3443, 0, harry, d);
		assertEquals("back again", harry, visits.arrived(2833, 3443, 0, harry, d));
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;
import static org.junit.Assert.assertTrue;

/** One simulated client for the Shopping tab's sync: its book, and what it sent. */
class ShoppingClient
{
	final String name;
	final List<String> sent = new ArrayList<>();
	final ShoppingSync sync;

	ShoppingClient(Gson gson, String name)
	{
		this.name = name;
		this.sync = new ShoppingSync(gson, sent::add, () ->
		{
		});
	}

	/** A game tick while connected: whatever it sends reaches {@code to}. */
	void tick(ShoppingClient... to)
	{
		sync.flush(name);
		for (String payload : sent)
		{
			for (ShoppingClient c : to)
			{
				assertTrue(c.sync.receive(name, payload));
			}
		}
		sent.clear();
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The two Shopping kinds on the wire, and that they leave older clients alone: a gim-test-3 build reads every
 * payload through {@link GroupCodec} and then {@link GovernanceCodec}, and both must drop these as unknown.
 */
public class ShoppingCodecTest
{
	private final Gson gson = new Gson();

	private ShoppingList list()
	{
		Map<Integer, Integer> items = new TreeMap<>();
		items.put(954, 2);
		items.put(1925, 1);
		return ShoppingList.create("Ropes & buckets", "", Collections.emptyList(), Arrays.asList("Alice", "Bob"),
			items, "Alice", 1_700_000_000_000L);
	}

	@Test
	public void aListRoundTrips()
	{
		ShoppingList l = list().removedBy("Bob", 1_700_000_000_500L);
		ShoppingList back = ShoppingCodec.decode(gson, ShoppingCodec.encode(gson, l)).list;
		assertEquals(l.id, back.id);
		assertEquals(l.name, back.name);
		assertEquals(l.members, back.members);
		assertEquals(l.items, back.items);
		assertEquals(2, back.rev);
		assertEquals("Bob", back.by);
		assertEquals(ShoppingList.REMOVED, back.action);
		assertTrue(back.removed);
		assertEquals("Alice", back.createdBy);
	}

	@Test
	public void aPresetListCarriesItsPicks()
	{
		ShoppingList l = ShoppingList.create("Mithril gloves", "mithril-gloves", Arrays.asList("a", "b"),
			Collections.singletonList("Alice"), Collections.emptyMap(), "Alice", 5);
		ShoppingList back = ShoppingCodec.decode(gson, ShoppingCodec.encode(gson, l)).list;
		assertEquals("mithril-gloves", back.preset);
		assertEquals(Arrays.asList("a", "b"), back.picks);
		assertFalse(back.custom());
	}

	@Test
	public void questProgressRoundTrips()
	{
		QuestProgress p = QuestProgress.of(Arrays.asList("Cook's Assistant", "Lost City"),
			Collections.singletonList("Waterfall Quest"));
		QuestProgress back = ShoppingCodec.decode(gson, ShoppingCodec.encode(gson, p)).quests;
		assertEquals(p, back);
		assertTrue(back.started("Cook's Assistant"));
		assertTrue(back.started("Waterfall Quest"));
		assertFalse(back.finished("Waterfall Quest"));
	}

	@Test
	public void olderClientsIgnoreBothKinds()
	{
		for (String payload : Arrays.asList(ShoppingCodec.encode(gson, list()),
			ShoppingCodec.encode(gson, QuestProgress.of(Collections.singleton("Lost City"), Collections.emptySet()))))
		{
			assertNull("GroupCodec drops an unknown kind", GroupCodec.decode(gson, payload));
			assertFalse(GovernanceSync.isGovernance(payload));
			assertNull("GovernanceCodec drops an unknown kind", GovernanceCodec.decode(gson, payload));
			assertTrue(ShoppingCodec.isShopping(payload));
		}
	}

	@Test
	public void otherKindsAndBadPayloadsAreNotShopping()
	{
		String stats = GroupCodec.encodeStats(gson, new MemberStats(Collections.emptyMap(), 0, 0, 0, 0, 0, 0, 0));
		assertFalse(ShoppingCodec.isShopping(stats));
		assertNull(ShoppingCodec.decode(gson, stats));
		assertNull(ShoppingCodec.decode(gson, "{\"v\":1,\"k\":\"shop2\"}"));
		assertNull(ShoppingCodec.decode(gson, "{\"v\":1,\"k\":\"shop\",\"id\":\"BAD ID\",\"r\":1,\"ts\":1}"));
		assertNull(ShoppingCodec.decode(gson, "{\"v\":1,\"k\":\"shop\",\"id\":\"abc\",\"r\":0,\"ts\":1}"));
		assertNull(ShoppingCodec.decode(gson, "not json"));
	}

	@Test
	public void everyFieldIsCapped()
	{
		StringBuilder longName = new StringBuilder();
		for (int i = 0; i < 100; i++)
		{
			longName.append('x');
		}
		ShoppingList l = ShoppingList.create(longName.toString(), "", Collections.emptyList(),
			Collections.nCopies(1, "Alice"), Collections.emptyMap(), "Alice", 1);
		assertEquals(ShoppingList.MAX_NAME, l.name.length());
		assertTrue(ShoppingCodec.encode(gson, l).length() < GroupCodec.MAX_PAYLOAD_CHARS);
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Lists reach a second client over the party, and removals and renames follow them. */
public class ShoppingSyncTest
{
	private final Gson gson = new Gson();

	/** One simulated client ({@link ShoppingClient}), named. */
	private final class Client
	{
		final ShoppingClient c;
		final String name;
		final List<String> sent;
		final ShoppingSync sync;

		Client(String name)
		{
			this.c = new ShoppingClient(gson, name);
			this.name = name;
			this.sent = c.sent;
			this.sync = c.sync;
		}

		void tick(Client... to)
		{
			ShoppingClient[] out = new ShoppingClient[to.length];
			for (int i = 0; i < to.length; i++)
			{
				out[i] = to[i].c;
			}
			c.tick(out);
		}
	}

	private static Map<Integer, Integer> ropes()
	{
		Map<Integer, Integer> items = new TreeMap<>();
		items.put(954, 2);
		return items;
	}

	private ShoppingList custom(String by, long at)
	{
		return ShoppingList.create("Ropes", "", Collections.emptyList(), Arrays.asList("Alice", "Bob"), ropes(), by, at);
	}

	@Test
	public void aListReachesASecondClient()
	{
		Client alice = new Client("Alice");
		Client bob = new Client("Bob");
		assertTrue(alice.sync.add(custom("Alice", 1000)));
		alice.tick(bob);

		List<ShoppingList> lists = bob.sync.active();
		assertEquals(1, lists.size());
		assertEquals("Ropes", lists.get(0).name);
		assertEquals(Integer.valueOf(2), lists.get(0).items.get(954));
		assertEquals("Alice added 'Ropes' for Alice, Bob", bob.sync.history().get(0).text);
	}

	@Test
	public void renameAndRemovalFollowTheList()
	{
		Client alice = new Client("Alice");
		Client bob = new Client("Bob");
		ShoppingList list = custom("Alice", 1000);
		alice.sync.add(list);
		alice.tick(bob);

		assertTrue(bob.sync.rename(list.id, "Ropes for Lost City", "Bob", 2000));
		bob.tick(alice);
		assertEquals("Ropes for Lost City", alice.sync.active().get(0).name);
		assertEquals("Bob renamed 'Ropes' to 'Ropes for Lost City'", alice.sync.history().get(0).text);

		assertTrue(alice.sync.remove(list.id, "Alice", 3000));
		alice.tick(bob);
		assertTrue(bob.sync.active().isEmpty());
		assertEquals("Alice removed 'Ropes for Lost City'", bob.sync.history().get(0).text);
	}

	@Test
	public void aStaleCopyNeverBringsARemovedListBack()
	{
		Client alice = new Client("Alice");
		Client bob = new Client("Bob");
		ShoppingList list = custom("Alice", 1000);
		alice.sync.add(list);
		alice.tick(bob);
		alice.sync.remove(list.id, "Alice", 2000);
		alice.tick();

		// Bob was offline for the removal and resends his older copy when Alice joins.
		bob.sync.resendAll();
		bob.tick(alice);
		assertTrue(alice.sync.active().isEmpty());

		// And Alice's resend to him carries the removal.
		alice.sync.resendAll();
		alice.tick(bob);
		assertTrue(bob.sync.active().isEmpty());
	}

	@Test
	public void aJoiningMemberGetsEveryList()
	{
		Client alice = new Client("Alice");
		Client cara = new Client("Cara");
		alice.sync.add(custom("Alice", 1000));
		alice.sync.add(custom("Alice", 1001));
		alice.tick();

		alice.sync.resendAll();
		alice.tick(cara);
		assertEquals(2, cara.sync.active().size());
	}

	@Test
	public void presetsCannotBeRenamed()
	{
		Client alice = new Client("Alice");
		ShoppingList preset = ShoppingList.create("Mithril gloves", "mithril-gloves", Collections.emptyList(),
			Collections.singletonList("Alice"), Collections.emptyMap(), "Alice", 1000);
		alice.sync.add(preset);
		assertFalse(alice.sync.rename(preset.id, "Gloves", "Alice", 2000));
	}

	@Test
	public void questProgressGoesOnlyWhileAListIsForThatMember()
	{
		Client alice = new Client("Alice");
		Client bob = new Client("Bob");
		alice.sync.ownProgress("Alice", QuestProgress.of(Collections.singleton("Cook's Assistant"),
			Collections.emptySet()));
		alice.sync.flush("Alice");
		assertTrue("a fresh install with no list for this member sends nothing", alice.sent.isEmpty());

		alice.sync.add(ShoppingList.create("Mithril gloves", "mithril-gloves", Collections.emptyList(),
			Collections.singletonList("Alice"), Collections.emptyMap(), "Alice", 1000));
		alice.tick(bob);
		assertTrue(bob.sync.progress("Alice").known());
		assertTrue(bob.sync.progress("alice").finished("Cook's Assistant"));
		assertFalse(bob.sync.progress("Cara").known());
	}

	@Test
	public void theCacheKeepsListsHistoryAndProgress()
	{
		Client alice = new Client("Alice");
		ShoppingList list = custom("Alice", 1000);
		alice.sync.add(list);
		alice.sync.ownProgress("Alice", QuestProgress.of(Collections.singleton("Lost City"), Collections.emptySet()));
		JsonObject cache = alice.sync.toCache();
		String file = GroupCache.write(gson, new GroupRoster(), null, cache);

		Client again = new Client("Alice");
		again.sync.fromCache(GroupCache.shop(gson, file), 2000);
		assertEquals(list.id, again.sync.active().get(0).id);
		assertEquals(1, again.sync.history().size());
		assertTrue(again.sync.progress("Alice").finished("Lost City"));
	}

	@Test
	public void aCacheFromBeforeShoppingHasNoEntry()
	{
		assertNull(GroupCache.shop(gson, GroupCache.write(gson, new GroupRoster())));
	}

	@Test
	public void removedListsAreForgottenAfterAMonth()
	{
		Client alice = new Client("Alice");
		ShoppingList list = custom("Alice", 1000);
		alice.sync.add(list);
		alice.sync.remove(list.id, "Alice", 2000);
		JsonObject cache = alice.sync.toCache();

		Client later = new Client("Alice");
		later.sync.fromCache(cache, 2000 + ShoppingSync.TOMBSTONE_MS + 1);
		assertNull(later.sync.list(list.id));
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

/** What each Shopping line says: one compact line, plain words, details behind a click. */
public class ShoppingTabTextTest
{
	private static ShopAllocation.Line line(long need, long heldByAlice, long storage, boolean stated)
	{
		Map<String, Map<Integer, ShopNeeds.Need>> needs = new LinkedHashMap<>();
		needs.put("Alice", Collections.singletonMap(954,
			new ShopNeeds.Need(954, "Rope", need, stated, false, Collections.singleton("Q"))));
		Map<String, Map<Integer, Long>> held = new LinkedHashMap<>();
		held.put("Alice", Collections.singletonMap(954, heldByAlice));
		return ShopAllocation.of(needs, new ShopAllocation.Holdings(held, Collections.singletonMap(954, storage)),
			id -> true).get(0);
	}

	/** Alice needs 5 and holds 1; Tin needs 3 and shares no items. */
	private static ShopAllocation.Line withUnshared(long aliceHolds)
	{
		Map<String, Map<Integer, ShopNeeds.Need>> needs = new LinkedHashMap<>();
		needs.put("Alice", Collections.singletonMap(954,
			new ShopNeeds.Need(954, "Rope", 5, true, false, Collections.singleton("Q"))));
		needs.put("Tin", Collections.singletonMap(954,
			new ShopNeeds.Need(954, "Rope", 3, true, false, Collections.singleton("Q"))));
		return ShopAllocation.of(needs, new ShopAllocation.Holdings(Collections.singletonMap("Alice",
			Collections.singletonMap(954, aliceHolds)), Collections.emptyMap()), id -> true).get(0);
	}

	private static ShoppingBoard.Row row(ShopAllocation.Line l)
	{
		return new ShoppingBoard.Row(l, new ShopSources.Options(Collections.emptyList(), 0));
	}

	@Test
	public void aLineSaysHaveOfNeedThenHowManyMore()
	{
		assertEquals("Rope  3 / 5", ShoppingTab.summary(line(5, 1, 2, true)));
		assertEquals("Need 2 more", ShoppingTab.needText(line(5, 1, 2, true)));
		assertEquals("Rope  0 / 30", ShoppingTab.summary(line(30, 0, 0, true)));
		assertEquals("Need 30 more", ShoppingTab.needText(line(30, 0, 0, true)));
	}

	@Test
	public void aDoneLineSaysDoneAndAnUnstatedCountIsAPlus()
	{
		assertEquals("Rope  1 / 1+", ShoppingTab.summary(line(1, 1, 0, false)));
		assertEquals("Done", ShoppingTab.needText(line(1, 1, 0, false)));
	}

	@Test
	public void aMemberWhoSharesNoItemsIsExplainedNotJudged()
	{
		assertEquals("Need 4 more, plus 3 for Tin (shares no items, may already have them)",
			ShoppingTab.needText(withUnshared(1)));
		assertEquals("Need 3 for Tin (shares no items, may already have them)", ShoppingTab.needText(withUnshared(5)));
	}

	@Test
	public void detailsSayWhoHoldsItAndWhereToGetIt()
	{
		assertEquals(Arrays.asList("Held by Alice 1, group storage 2",
			"Not sold in any shop, and no drop on file: check the wiki."), ShoppingTab.details(row(line(5, 1, 2, true))));
		// Done: nothing more to get, so no "where".
		assertEquals(Collections.singletonList("Held by group storage 1"), ShoppingTab.details(row(line(1, 0, 1, true))));
		assertEquals("", ShoppingTab.heldText(line(5, 0, 0, true)));
	}

	@Test
	public void whereToGetIt()
	{
		ShopSources.Options o = new ShopSources.Options(Arrays.asList(
			new ShopSources.Source(true, "General Store", 5, ""),
			new ShopSources.Source(false, "Goblin", -1, "Always"),
			new ShopSources.Source(false, "Imp", -1, ""),
			new ShopSources.Source(false, "Rat", -1, ""),
			new ShopSources.Source(false, "Cow", -1, "")), 1);
		assertEquals("Get: Shop: General Store (5 gp); Drop: Goblin (Always); Drop: Imp; Drop: Rat; 1 more",
			ShoppingTab.sourceText(o));
		assertEquals("No shop you can use: 2 need levels or quests you lack.",
			ShoppingTab.sourceText(new ShopSources.Options(Collections.emptyList(), 2)));
	}

	@Test
	public void theBylineSaysWhoDidIt()
	{
		ShoppingList l = ShoppingList.create("Ropes", "", Collections.emptyList(), Arrays.asList("Alice", "Bob"),
			Collections.singletonMap(954, 1), "Alice", 0).renamed("More ropes", "Bob", 0);
		assertEquals("For Alice, Bob. Renamed by Bob, " + BoostText.ago(0, 0) + ".", ShoppingTab.byline(l, 0));
	}

	@Test
	public void progressReadsAsDoneOfTotal()
	{
		assertEquals("0 of 39 done", ShopCards.progress(0, 39));
		assertEquals("Done: 39 of 39", ShopCards.progress(39, 39));
	}
}

package com.vinnyvangogh.groupironman;

import com.vinnyvangogh.testkit.ui.RuneLiteLook;
