	public void aNonKeeperNeverReposts()
	{
		// The engine targets no webhook unless StatusBoard.keeps (SharedWebhooksTest pins who keeps it).
		postedOn(DAY, NOW);
		board.target(null, () -> saved);
		board.show("b", NOW + GAP);
		assertNull(board.next(NOW + GAP, false, DAY + 1, true));
		assertNull(board.next(NOW + 10 * GAP, false, DAY + 2, true));
	}

	@Test
	public void quietHoursHoldTheRepostUntilTheFirstAllowedSend()
	{
		postedOn(DAY, NOW);
		board.show("b", NOW + GAP);
		assertNull("quiet hours", board.next(NOW + GAP, true, DAY + 1, true));
		StatusBoard.Send post = board.next(NOW + 2 * GAP, false, DAY + 1, true);
		assertTrue("the first allowed send reposts", post.create());
		assertEquals("111", post.replaces);
	}

	@Test
	public void aRestartKeepsTheBoardsDayAndAPendingDelete()
	{
		postedOn(DAY, NOW);
		StatusBoard sameDay = new StatusBoard();
		sameDay.target(URL, () -> saved);
		sameDay.show("b", NOW);
		assertFalse("posted today: a restart edits", sameDay.next(NOW, false, DAY, true).create());

		board.done(repost(DAY + 1, NOW + GAP), 200, "222", -1, NOW + GAP);
		saved = board.takeSaved();
		StatusBoard restarted = new StatusBoard();
		restarted.target(URL, () -> saved);
		StatusBoard.Send delete = restarted.next(NOW + GAP, false, DAY + 1, true);
		assertTrue("closed before the delete: it still goes", delete.delete);
		assertEquals("111", delete.messageId);
	}

	@Test
	public void aBoardSavedBeforeDailyRepostsIsRepostedOnItsFirstSend()
	{
		saved = Integer.toHexString(URL.hashCode()) + "\t111";
		target(URL);
		board.show("a", NOW);
		StatusBoard.Send send = board.next(NOW, false, DAY, true);
		assertTrue("its day is unknown, so it is brought down", send.create());
		assertEquals("111", send.replaces);
	}

	@Test
	public void theRepostAndDeleteGoThroughTheSendersQueue()
	{
		String thread = URL + "?thread_id=42";
		board.target(thread, () -> null);
		board.show("a", now);
		sendOn(DAY);
		answers.remove(0).done(200, null, "111");
		board.takeSaved();

		now += GAP;
		sendOn(DAY + 1);
		DiscordQueue.Post post = requests.get(1);
		assertNull("the repost is a post", post.edit);
		assertEquals(URL + "?thread_id=42&wait=true", DiscordSender.target(post));
		answers.remove(0).done(200, null, "222");
		board.takeSaved();

		sendOn(DAY + 1);
		DiscordQueue.Post delete = requests.get(2);
		assertTrue(delete.delete);
		assertEquals("Delete Webhook Message, in the thread", URL + "/messages/111?thread_id=42",
			DiscordSender.target(delete));
		assertEquals("DELETE", DiscordSender.request(delete).method());
		assertEquals("PATCH", DiscordSender.request(new DiscordQueue.Post(URL, "{}", null, "1", null)).method());
		assertEquals("POST", DiscordSender.request(post).method());
		answers.remove(0).done(204, null);
		assertTrue(board.takeSaved().endsWith("\t222\t" + (DAY + 1)));
	}

	private void sendOn(long day)
	{
		StatusBoard.Send send = board.next(now, false, day, true);
		board.send(sender, send, StatusBoard.payload(GSON, send, DiscordStyle.EMBED, null), () -> now);
		sender.pump();
	}

	@Test
	public void anUpgradeKeepsWhatItsOldSwitchDid()
	{
		assertEquals(OnlineStatus.POSTS, OnlineStatus.upgrading(true, true));
		assertEquals(OnlineStatus.OFF, OnlineStatus.upgrading(false, true));
		assertNull("a new install takes the default", OnlineStatus.upgrading(false, false));
		assertEquals("a new install posts; a member opts into the board (Board 2026-11-10)", OnlineStatus.POSTS,
			new GroupIronmanConfig()
			{
			}.discordOnlineStatus());
		assertFalse("the board is not a post", EventSettings.from(new GroupIronmanConfig()
		{
			@Override
			public OnlineStatus discordOnlineStatus()
			{
				return OnlineStatus.LIVE_BOARD;
			}
		}).discord.contains(GroupEvent.Type.ONLINE));
	}
}

package com.vinnyvangogh.groupironman;

import java.util.Map;
import java.util.TreeMap;
import java.util.function.IntUnaryOperator;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Group storage open versus close. Slots are given as id/quantity pairs in
 * slot order, the way the game's container hands them over.
 */
public class StorageDiffTest
{
	private static final int SHARK = 385;
	private static final int SHARK_NOTED = 386;
	private static final int COAL = 453;
	private static final int COAL_NOTED = 454;
	private static final int RUNE_SCIM = 1333;

	/** Stands in for ItemManager.canonicalize: noted ids map to the unnoted one. */
	private static final IntUnaryOperator UNNOTE = id -> id == SHARK_NOTED ? SHARK : id == COAL_NOTED ? COAL : id;

	private static Map<Integer, Integer> slots(int... pairs)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			ItemCounts.add(out, pairs[i], pairs[i + 1], UNNOTE);
		}
		return out;
	}

	private static Map<Integer, Integer> counts(int... pairs)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			out.put(pairs[i], pairs[i + 1]);
		}
		return out;
	}

	@Test
	public void movingAStackToAnotherSlotIsNoChange()
	{
		StorageChange c = StorageDiff.diff(1, slots(SHARK, 10, -1, 0, COAL, 5), slots(COAL, 5, SHARK, 10, -1, 0));
		assertTrue(c.isEmpty());
	}

	@Test
	public void takingPartOfAStackIsTookThatMany()
	{
		StorageChange c = StorageDiff.diff(1, slots(SHARK, 10), slots(SHARK, 7));
		assertEquals(counts(SHARK, 3), c.took());
		assertTrue(c.deposited().isEmpty());
	}

	@Test
	public void addingToAStackIsDepositedThatMany()
	{
		StorageChange c = StorageDiff.diff(1, slots(COAL, 100), slots(COAL, 250));
		assertEquals(counts(COAL, 150), c.deposited());
	}

	@Test
	public void takingAWholeStackAndAddingANewOne()
	{
		StorageChange c = StorageDiff.diff(1, slots(RUNE_SCIM, 1, SHARK, 4), slots(SHARK, 4, COAL, 20));
		assertEquals(counts(RUNE_SCIM, 1), c.took());
		assertEquals(counts(COAL, 20), c.deposited());
		assertEquals(counts(SHARK, 4, COAL, 20), c.after());
	}

	@Test
	public void notedAndUnnotedAreTheSameItem()
	{
		// Before: 5 sharks unnoted. After the deposit of 20 noted, the game shows 25 sharks.
		StorageChange c = StorageDiff.diff(1, slots(SHARK, 5), slots(SHARK, 5, SHARK_NOTED, 20));
		assertEquals(counts(SHARK, 20), c.deposited());
		assertTrue(c.took().isEmpty());
	}

	@Test
	public void aNotedStackSwappedForTheSameUnnotedCountIsNoChange()
	{
		StorageChange c = StorageDiff.diff(1, slots(COAL_NOTED, 30), slots(COAL, 30));
		assertTrue(c.isEmpty());
	}

	@Test
	public void splitStacksAreSummed()
	{
		// Two partial stacks of the same item (unstackables) count together.
		StorageChange c = StorageDiff.diff(1, slots(RUNE_SCIM, 1, RUNE_SCIM, 1, RUNE_SCIM, 1), slots(RUNE_SCIM, 1));
		assertEquals(counts(RUNE_SCIM, 2), c.took());
	}

	@Test
	public void emptySlotsAndPlaceholdersAreIgnored()
	{
		assertEquals(counts(SHARK, 2), slots(-1, 1, 0, 5, SHARK, 2, COAL, 0));
	}
}

package com.vinnyvangogh.groupironman;

import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.TimeUnit;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static com.vinnyvangogh.groupironman.FakeItems.*;

public class StorageLogTest
{
	private static Map<Integer, Integer> items(int... pairs)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			out.put(pairs[i], pairs[i + 1]);
		}
		return out;
	}

	private static StorageChange took(long at, String who)
	{
		return new StorageChange(at, who, items(SHARK, 1), items(), items());
	}

	@Test
	public void keepsOnlyTheNewest200()
	{
		StorageLog log = new StorageLog();
		for (int i = 1; i <= 250; i++)
		{
			log.add(took(i, "Alex"));
		}
		List<StorageChange> entries = log.entries();
		assertEquals(StorageLog.MAX_ENTRIES, entries.size());
		assertEquals(250, entries.get(0).at());
		assertEquals(51, entries.get(entries.size() - 1).at());
	}

	@Test
	public void newestFirstEvenWhenDeliveredOutOfOrder()
	{
		StorageLog log = new StorageLog();
		log.add(took(10, "Alex"));
		log.add(took(30, "Sam"));
		log.add(took(20, "Jo"));
		assertEquals(30, log.entries().get(0).at());
		assertEquals(20, log.entries().get(1).at());
		assertEquals(10, log.entries().get(2).at());
	}

	@Test
	public void aDuplicateDeliveryIsDropped()
	{
		StorageLog log = new StorageLog();
		log.add(took(10, "Alex"));
		assertFalse(log.add(took(10, "alex")));
		assertEquals(1, log.entries().size());
	}

	@Test
	public void aVisitThatChangedNothingIsNotLogged()
	{
		StorageLog log = new StorageLog();
		assertFalse(log.add(new StorageChange(1, "Alex", items(), items(), items(SHARK, 4))));
	}

	@Test
	public void rowsSayWhoTookAndDepositedWithYouForThisPlayer()
	{
		GroupRoster roster = new GroupRoster();
		long now = TimeUnit.DAYS.toMillis(5);
		roster.putStorage(new StorageChange(now - TimeUnit.MINUTES.toMillis(3), "Alex", items(SHARK, 5),
			items(COAL, 100, RUNE_SCIM, 1), items()));
		roster.putStorage(new StorageChange(now - TimeUnit.MINUTES.toMillis(1), "Me", items(), items(COAL, 2), items()));
		List<PanelModel.LogRow> rows = PanelModel.storage(roster, new FakeItems(), "me", null, now).log;
		assertEquals("You deposited 2 Coal", rows.get(0).text);
		assertEquals("1m ago", rows.get(0).ago);
		assertEquals("Alex took 5 Shark, deposited 100 Coal, 1 Rune scimitar", rows.get(1).text);
		assertEquals("3m ago", rows.get(1).ago);
	}
}

package com.vinnyvangogh.groupironman;

import com.google.gson.Gson;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static com.vinnyvangogh.groupironman.FakeItems.*;

/**
 * An own group storage visit made with "Share group storage changes" off is kept on this client, marked not
 * shared, and nothing is sent (Board 2026-11-13: a friend's withdrawal before ticking the switch looked lost).
 */
public class StorageNotSharedTest
{
	private static final Gson GSON = new Gson();
	private static final ZoneId UTC = ZoneOffset.UTC;
	private static final long NOW = 1_762_776_000_000L;
	private static final GroupOutbox.Switches STORAGE_OFF = new GroupOutbox.Switches(true, false, true, true, true,
		true);
	private static final GroupOutbox.Switches STORAGE_ON = new GroupOutbox.Switches(false, true, false, false);

	private final FakeItems items = new FakeItems();

	private static Map<Integer, Integer> items(int... pairs)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			out.put(pairs[i], pairs[i + 1]);
		}
		return out;
	}

	private static StorageChange tookPots(long at)
	{
		return new StorageChange(at, "Friend", items(PRAYER_POT_4, 4), items(), items(PRAYER_POT_4, 6));
	}

	@Test
	public void withTheSwitchOffTheVisitIsLoggedLocallyAndNothingIsSent()
	{
		GroupRoster roster = new GroupRoster();
		String payload = GroupOutbox.ownStorage(GSON, STORAGE_OFF, tookPots(NOW), roster);

		assertNull("nothing goes to the outbox", payload);
		assertEquals(1, roster.log().entries().size());
		StorageChange kept = roster.log().entries().get(0);
		assertFalse(kept.shared());
		assertEquals(items(PRAYER_POT_4, 4), kept.took());
		assertEquals("the own Storage tab shows what this client saw", NOW, roster.storageAt());
		assertTrue(roster.log().notShared(NOW, "friend"));
	}

	@Test
	public void withTheSwitchOnBehaviourIsUnchanged()
	{
		GroupRoster roster = new GroupRoster();
		StorageChange change = tookPots(NOW);
		String payload = GroupOutbox.ownStorage(GSON, STORAGE_ON, change, roster);

		assertEquals(GroupOutbox.storage(GSON, STORAGE_ON, change), payload);
		assertNotNull(payload);
		assertTrue(roster.log().entries().get(0).shared());
		assertFalse(roster.log().notShared(NOW, "Friend"));
		assertEquals("Friend took 4 Prayer potion(4)", PanelModel.change(roster.log().entries().get(0), items, ""));
	}

	@Test
	public void theStorageTabLineSaysWhyItWasNotShared()
	{
		GroupRoster roster = new GroupRoster();
		GroupOutbox.ownStorage(GSON, STORAGE_OFF, tookPots(NOW), roster);
		assertEquals("You took 4 Prayer potion(4) (not shared: Share group storage changes is off)",
			PanelModel.change(roster.log().entries().get(0), items, "Friend"));
	}

	@Test
	public void theLogTabRowSaysWhyItWasNotShared()
	{
		GroupRoster roster = new GroupRoster();
		GroupOutbox.ownStorage(GSON, STORAGE_OFF, tookPots(NOW), roster);
		GroupEvent summary = GroupEvent.of(GroupEvent.Type.STORAGE_SUMMARY, NOW, "Friend")
			.taken(items(PRAYER_POT_4, 4)).build();

		ActivityLog.Row row = ActivityLog.row(summary, items, NOW, UTC, roster.log());
		assertTrue(row.text, row.text.endsWith("(" + StorageChange.NOT_SHARED + ")"));
		assertTrue(row.full, row.full.contains(StorageChange.NOT_SHARED));
		assertTrue(row.copy, row.copy.contains(StorageChange.NOT_SHARED));
	}

	@Test
	public void otherRowsAreNotMarked()
	{
		GroupRoster roster = new GroupRoster();
		GroupOutbox.ownStorage(GSON, STORAGE_OFF, tookPots(NOW), roster);
		GroupEvent otherVisit = GroupEvent.of(GroupEvent.Type.STORAGE_SUMMARY, NOW - 1, "Friend")
			.taken(items(SHARK, 1)).build();
		GroupEvent drop = GroupEvent.drop(NOW, "Friend", "Goblin", items(COINS, 5));

		assertFalse(ActivityLog.row(otherVisit, items, NOW, UTC, roster.log()).text.contains(StorageChange.NOT_SHARED));
		assertFalse("only storage rows", ActivityLog.row(drop, items, NOW, UTC, roster.log()).text
			.contains(StorageChange.NOT_SHARED));
		assertEquals(ActivityLog.row(drop, items, NOW, UTC).text, ActivityLog.row(drop, items, NOW, UTC,
			roster.log()).text);
	}

	@Test
	public void theMarkSurvivesARestart()
	{
		GroupRoster before = new GroupRoster();
		GroupOutbox.ownStorage(GSON, STORAGE_OFF, tookPots(NOW), before);
		before.putStorage(new StorageChange(NOW + 5, "Sam", items(SHARK, 1), items(), items()));

		GroupRoster after = new GroupRoster();
		assertTrue(GroupCache.read(GSON, GroupCache.write(GSON, before), after));
		assertEquals(2, after.log().entries().size());
		assertTrue(after.log().notShared(NOW, "Friend"));
		assertFalse(after.log().notShared(NOW + 5, "Sam"));
	}

	@Test
	public void anOlderFileWithoutTheMarkReadsAsShared()
	{
		GroupRoster before = new GroupRoster();
		before.putStorage(tookPots(NOW));
		String json = GroupCache.write(GSON, before);
		assertFalse("only written when set", json.contains("\"ns\""));

		GroupRoster after = new GroupRoster();
		assertTrue(GroupCache.read(GSON, json, after));
		assertTrue(after.log().entries().get(0).shared());
	}

	@Test
	public void aMemberRenameKeepsTheMark()
	{
		assertFalse(tookPots(NOW).notShared().withMember("Other").shared());
	}
}

package com.vinnyvangogh.groupironman;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static com.vinnyvangogh.groupironman.FakeItems.*;

/**
 * The group storage log as the Board tested it: open, look, deposit, Save.
 * Only what the game saved is logged (Board 2026-11-14: 1,000 logs deposited
 * and walked away from without Save were posted, though the game threw them away).
 */
public class StorageSessionTest
{
	private static final FakeItems ITEMS = new FakeItems();
	private static final long NOW = 1_000_000_000L;
	/** Logs: the Board's 1,000 that were never saved. Unknown to FakeItems, which is fine for counts. */
	private static final int LOGS = 1511;

	private static Map<Integer, Integer> items(int... pairs)
	{
		Map<Integer, Integer> out = new TreeMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			out.put(pairs[i], pairs[i + 1]);
		}
		return out;
	}

	/** What GroupService does with each change the session hands back: the roster and the would-be posts. */
	private static final class Sink
	{
		final GroupRoster roster = new GroupRoster();
		final List<StorageChange> posted = new ArrayList<>();

		void commit(StorageChange change)
		{
			if (change == null)
			{
				return;
			}
			roster.putStorage(change);
			if (!EventDetect.storage(change, ITEMS).isEmpty())
			{
				posted.add(change);
			}
		}

		List<PanelModel.LogRow> log(long now)
		{
			return PanelModel.storage(roster, ITEMS, "me", null, now).log;
		}

		/** Open with 40 Sharks, then 5 Trout deposited and not yet saved. */
		StorageSession depositFiveTrout()
		{
			StorageSession s = new StorageSession();
			s.open();
			commit(s.contents(NOW, "Me", items(SHARK, 40)));
			commit(s.contents(NOW, "Me", items(SHARK, 40, TROUT, 5)));
			return s;
		}

		Map<Integer, Integer> snapshot()
		{
			return roster.storageItems();
		}
	}

	// --- Failure cases first -------------------------------------------------

	@Test
	public void depositThenCloseWithoutSavePostsNothingAndKeepsTheSnapshot()
	{
		Sink sink = new Sink();
		StorageSession s = new StorageSession();
		s.open();
		sink.commit(s.contents(NOW, "Me", items(SHARK, 40)));
		sink.commit(s.contents(NOW, "Me", items(SHARK, 40, LOGS, 1_000)));
		s.close(NOW + 1_000);

		assertTrue("nothing posted", sink.posted.isEmpty());
		assertTrue("nothing logged", sink.log(NOW + 1_000).isEmpty());
		assertEquals("snapshot is what the game kept", items(SHARK, 40), sink.snapshot());
	}

	@Test
	public void depositSaveDepositMoreThenCloseWithoutSavePostsOnlyTheSavedPart()
	{
		Sink sink = new Sink();
		StorageSession s = sink.depositFiveTrout();
		sink.commit(s.save(NOW + 1, "Me"));
		sink.commit(s.contents(NOW + 2, "Me", items(SHARK, 40, TROUT, 5, COAL, 9)));
		s.close(NOW + 3);

		assertEquals(1, sink.posted.size());
		assertEquals(items(TROUT, 5), sink.posted.get(0).deposited());
		assertEquals(items(SHARK, 40, TROUT, 5), sink.snapshot());
	}

	@Test
	public void containerThatDisagreesOnTheNextOpenCorrectsTheSnapshotWithoutAPost()
	{
		Sink sink = new Sink();
		StorageSession s = sink.depositFiveTrout();
		sink.commit(s.save(NOW + 1, "Me"));
		s.close(NOW + 2);
		assertEquals(1, sink.posted.size());

		// The save did not stick: the server's next contents are the old ones.
		s.open();
		StorageChange correction = s.contents(NOW + 60_000, "Me", items(SHARK, 40));
		assertNotNull(correction);
		assertTrue("a correction is a snapshot, never a change", correction.isEmpty());
		sink.commit(correction);
		assertEquals("no second post", 1, sink.posted.size());
		assertEquals(items(SHARK, 40), sink.snapshot());
	}

	@Test
	public void nextOpenMatchingWhatWasCommittedRecordsNothing()
	{
		StorageSession s = new StorageSession();
		s.open();
		s.contents(NOW, "Me", items(SHARK, 40));
		s.contents(NOW, "Me", items(SHARK, 40, LOGS, 1_000));
		s.close(NOW + 1);
		s.open();
		assertNull("discarded deposit, contents as committed", s.contents(NOW + 5_000, "Me", items(SHARK, 40)));
	}

	@Test
	public void aSaveLongAfterTheCloseIsNotThisVisits()
	{
		StorageSession s = new StorageSession();
		s.open();
		s.contents(NOW, "Me", items(SHARK, 40));
		s.contents(NOW, "Me", items(SHARK, 40, LOGS, 1_000));
		s.close(NOW);
		assertNull(s.save(NOW + StorageSession.LATE_SAVE_MS + 1, "Me"));
	}

	@Test
	public void nothingIsLoggedBeforeTheGameSendsTheContentsOrWhileClosed()
	{
		StorageSession s = new StorageSession();
		assertNull("never opened: ignored", s.contents(NOW, "Me", items(SHARK, 1)));
		assertNull("closed: ignored", s.save(NOW, "Me"));
		s.open();
		assertNull("open, nothing arrived yet", s.save(NOW, "Me"));
	}

	// --- Saves that do happen -------------------------------------------------

	@Test
	public void depositSaveCloseLogsExactlyOneLine()
	{
		Sink sink = new Sink();
		StorageSession s = sink.depositFiveTrout();
		sink.commit(s.save(NOW, "Me"));
		// The "Saving..." the same Save shows: nothing new moved.
		sink.commit(s.save(NOW + 600, "Me"));
		s.close(NOW + 1_000);

		assertEquals(1, sink.posted.size());
		List<PanelModel.LogRow> log = sink.log(NOW + 1_000);
		assertEquals(1, log.size());
		assertEquals("You deposited 5 Trout", log.get(0).text);
	}

	@Test
	public void aClosePathTheGameSavesOnPostsOnce()
	{
		Sink sink = new Sink();
		StorageSession s = sink.depositFiveTrout();
		s.close(NOW + 600);
		// "Saving..." shows just after the window closed.
		sink.commit(s.save(NOW + 1_200, "Me"));
		sink.commit(s.save(NOW + 1_800, "Me"));

		assertEquals(1, sink.posted.size());
		assertEquals(items(TROUT, 5), sink.posted.get(0).deposited());
		assertEquals(items(SHARK, 40, TROUT, 5), sink.snapshot());

		// And the next open agrees, so there is nothing to correct.
		s.open();
		assertNull(s.contents(NOW + 60_000, "Me", items(SHARK, 40, TROUT, 5)));
	}

	@Test
	public void openAndCloseWithNoChangeShowsTheSnapshotAndNoChangeLine()
	{
		Sink sink = new Sink();
		StorageSession s = new StorageSession();
		s.open();
		StorageChange snapshot = s.contents(NOW, "Me", items(SHARK, 40, COAL, 10));
		assertNotNull("the first contents of a session are recorded", snapshot);
		assertTrue(snapshot.isEmpty());
		sink.commit(snapshot);
		s.close(NOW);

		PanelModel.StorageView view = PanelModel.storage(sink.roster, ITEMS, "Me", null, NOW);
		assertEquals("Last seen just now, by you", view.snapshot);
		assertEquals(2, view.items.size());
		assertEquals("most valuable stack first", SHARK, view.items.get(0).id);
		assertTrue(view.log.isEmpty());
	}

	@Test
	public void eachSaveLogsWhatMovedSinceTheLastOne()
	{
		StorageSession s = new StorageSession();
		s.open();
		s.contents(NOW, "Me", items(SHARK, 40));
		s.contents(NOW, "Me", items(SHARK, 30));
		assertEquals(items(SHARK, 10), s.save(NOW, "Me").took());
		s.contents(NOW, "Me", items(SHARK, 30, COAL, 2));
		StorageChange second = s.save(NOW + 1, "Me");
		assertTrue(second.took().isEmpty());
		assertEquals(items(COAL, 2), second.deposited());
	}
}

package com.vinnyvangogh.groupironman;

import static org.junit.Assert.assertEquals;

import java.util.Collections;
import java.util.Map;
import org.junit.Test;

/**
 * A storage post's Value is what the visit left in storage: deposited minus taken. The Board's post (took 10 trout,
 * deposited 100 yew logs) read 9,480 gp, the two sides added, where 9,120 was right.
 */
public class StorageValueTest
{
	private final ItemLookup words = Amounts.BOTH.words(new FakeItems());

	private static DiscordMerge.Post storage(Map<Integer, Integer> deposited, Map<Integer, Integer> taken)
	{
		return new DiscordMerge.Post(null, "Group storage visit", "", Collections.emptyMap(),
			Collections.emptyList(), false, deposited, taken);
	}

	@Test
	public void bothSidesShowTheNetAndEachSide()
	{
		// 12 sharks in (12 x 800 = 9,600), 6 trout out (6 x 30 = 180): 9,420 left, never 9,780.
		String v = DiscordMerge.valueText(storage(Collections.singletonMap(FakeItems.SHARK, 12),
			Collections.singletonMap(FakeItems.TROUT, 6)), words);
		assertEquals(words.amount(9_420) + " gp (deposited " + words.amount(9_600) + ", took " + words.amount(180)
			+ ")", v);
	}

	@Test
	public void takingMoreThanDepositingIsNegative()
	{
		String v = DiscordMerge.valueText(storage(Collections.singletonMap(FakeItems.TROUT, 1),
			Collections.singletonMap(FakeItems.SHARK, 2)), words);
		assertEquals("-" + words.amount(1_570) + " gp (deposited " + words.amount(30) + ", took "
			+ words.amount(1_600) + ")", v);
	}

	@Test
	public void oneSideOnly()
	{
		assertEquals(words.amount(180) + " gp taken", DiscordMerge.valueText(storage(Collections.emptyMap(),
			Collections.singletonMap(FakeItems.TROUT, 6)), words));
		assertEquals(words.amount(9_600) + " gp", DiscordMerge.valueText(storage(
			Collections.singletonMap(FakeItems.SHARK, 12), Collections.emptyMap()), words));
	}

	@Test
	public void otherPostsStillSumTheirItems()
	{
		DiscordMerge.Post drop = new DiscordMerge.Post(null, "Drop", "", Collections.singletonMap(FakeItems.SHARK, 2),
			Collections.emptyList(), false);
		assertEquals(words.amount(1_600) + " gp", DiscordMerge.valueText(drop, words));
	}
}

package com.vinnyvangogh.groupironman;

