		s.put(Webhook.MAIN, url("not a link"));
		s.put(Webhook.DROPS, url(DROPS));
		Webhooks w = of(s);
		assertNull(w.url(Webhook.PROGRESS));
		assertEquals("a category with its own still posts", DROPS, w.url(Webhook.DROPS));
	}

