	@Test
	public void theSevenWebhooksSitInOrderInDiscordConnection()
	{
		String[] order = {"discordEnabled",
			"discordWebhookUrl", "discordPosterName", "discordNameMain",
			"discordGroupUrl", "discordPosterOnline", "discordNameGroup",
			"discordDropsUrl", "discordPosterDrops", "discordNameDrops",
			"discordProgressUrl", "discordPosterProgress", "discordNameProgress",
			"discordDeathsUrl", "discordPosterDeaths", "discordNameDeaths",
			"discordStorageUrl", "discordPosterStorage", "discordNameStorage",
			"discordDigestUrl", "discordPosterDigest", "discordNameDigest"};
		Map<String, ConfigItem> items = new HashMap<>();
		for (Method m : ConfigLayoutTest.items())
		{
			items.put(m.getName(), m.getAnnotation(ConfigItem.class));
		}
		Set<Integer> seen = new HashSet<>();
		for (int i = 0; i < order.length; i++)
		{
			ConfigItem item = items.get(order[i]);
			assertNotNull(order[i], item);
			assertEquals(order[i], GroupIronmanConfig.discordConnectionSection, item.section());
			assertEquals(order[i] + " position", i, item.position());
			assertFalse(order[i] + " shown", item.hidden());
			assertTrue(seen.add(item.position()));
			if (order[i].endsWith("Url"))
			{
				assertTrue(order[i] + " is a secret field", item.secret());
			}
		}
		assertTrue("the retired Activities webhook is kept, hidden", items.get("discordActivitiesUrl").hidden());
		assertTrue(items.get("discordNameActivities").hidden());
	}

	private static Map<String, String> keysByMethod()
	{
		Map<String, String> out = new HashMap<>();
		for (Method m : ConfigLayoutTest.items())
		{
			out.put(m.getName(), m.getAnnotation(ConfigItem.class).keyName());
		}
		return out;
	}
}

package com.vinnyvangogh.scenarios;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.party.events.UserPart;

/**
 * RuneLite events that are plain values, so a scenario can build them with no game behind them. Each is built
 * with the constructor or setters RuneLite's own code uses (Lombok {@code @Value} / {@code @Data} classes in
 * runelite-api and runelite-client); see TESTING.md for the table of what can and cannot be faked.
 *
 * <p>Not here, on purpose: {@code ActorDeath} and {@code NpcLootReceived} need a live {@code Actor} / {@code NPC},
 * and plugins compare them to {@code client.getLocalPlayer()}; a stand-in would never be "you". Fake those at the
 * plugin's own seam (a plugin kind) instead.
 */
final class CoreKinds
{
	private static final String NO_TICKS = "a fake GameTick would run every plugin an extra tick; the game ticks for "
		+ "you in the client";
	private static final String NO_GAME_STATE = "a fake game state change would make every plugin think you logged "
		+ "in or out";

	private CoreKinds()
	{
	}

	static void register(EventKinds kinds)
	{
		kinds.add("chat", f -> new ChatMessage(null, f.enumValue("type", ChatMessageType.class), f.string("name", ""),
			f.string("message"), f.string("sender", null), f.integer("timestamp", 0)));
		kinds.add("stat", f ->
		{
			int level = f.integer("level");
			return new StatChanged(f.enumValue("skill", Skill.class), f.integer("xp", 0), level,
				f.integer("boosted", level));
		});
		kinds.add("container", f -> new ItemContainerChanged(f.integer("id"),
			new FakeItemContainer(f.integer("id"), items(f.items("items")))));
		kinds.add("widgetLoaded", f ->
		{
			WidgetLoaded e = new WidgetLoaded();
			e.setGroupId(f.integer("group"));
			return e;
		});
		kinds.add("widgetClosed", f -> new WidgetClosed(f.integer("group"), f.integer("modalMode", 0),
			f.bool("unload", true)));
		kinds.add("varbit", f -> varbit(f.integer("varbit"), -1, f.integer("value")));
		kinds.add("varp", f -> varbit(-1, f.integer("varp"), f.integer("value")));
		kinds.add("userPart", f -> new UserPart(f.longValue("memberId", 0)));
		kinds.add("tick", EventFactory.headless(NO_TICKS, f -> new GameTick()));
		kinds.add("gameState", EventFactory.headless(NO_GAME_STATE, f ->
		{
			GameStateChanged e = new GameStateChanged();
			e.setGameState(f.enumValue("state", GameState.class));
			return e;
		}));
	}

	private static VarbitChanged varbit(int varbitId, int varpId, int value)
	{
		VarbitChanged e = new VarbitChanged();
		e.setVarbitId(varbitId);
		e.setVarpId(varpId);
		e.setValue(value);
		return e;
	}

	private static List<Item> items(Map<Integer, Integer> counts)
	{
		List<Item> out = new ArrayList<>();
		counts.forEach((id, qty) -> out.add(new Item(id, qty)));
		return out;
	}
}

package com.vinnyvangogh.scenarios;

/**
 * Builds the event one step posts. One per kind; a plugin adds its own with {@link EventKinds#add}.
 *
 * <p>Return what the plugin's {@code @Subscribe} methods take: a RuneLite event, or an object of the plugin's own
 * that only a headless rig subscribes to (then say so in {@link #headlessOnly}).
 */
@FunctionalInterface
public interface EventFactory
{
	Object create(Fields fields);

	/**
	 * Null when the event is safe to post into the developer client's real EventBus. Otherwise why not: the panel
	 * skips the step and shows this. Every plugin sees a posted event, not only the one under test.
	 */
	default String headlessOnly()
	{
		return null;
	}

	/** A factory whose events only a headless rig receives. */
	static EventFactory headless(String why, EventFactory factory)
	{
		return new EventFactory()
		{
			@Override
			public Object create(Fields fields)
			{
				return factory.create(fields);
			}

			@Override
			public String headlessOnly()
			{
				return why;
			}
		};
	}
}

package com.vinnyvangogh.scenarios;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * The event kinds a plugin's scenarios may use, and the named constants their fields may use.
 *
 * <p>Start from {@link #core()} (RuneLite's own events, {@link CoreKinds}) and {@link #add} the plugin's.
 * Adding a kind never replaces one: two factories answering to one name would make a scenario mean whichever
 * registered last.
 */
public final class EventKinds
{
	private final Map<String, EventFactory> factories = new TreeMap<>();
	private final Map<String, Integer> constants = new TreeMap<>();

	/** The RuneLite events every plugin can post. */
	public static EventKinds core()
	{
		EventKinds kinds = new EventKinds();
		CoreKinds.register(kinds);
		return kinds;
	}

	public EventKinds add(String kind, EventFactory factory)
	{
		if (factories.containsKey(kind))
		{
			throw new ScenarioException("event kind '" + kind + "' is already registered");
		}
		factories.put(kind, factory);
		return this;
	}

	/** A name a scenario can write instead of a number: an interface, inventory or item id. */
	public EventKinds constant(String name, int value)
	{
		Integer was = constants.put(name, value);
		if (was != null && was != value)
		{
			throw new ScenarioException("constant '" + name + "' is already " + was + ", not " + value);
		}
		return this;
	}

	/** The factory for {@code kind}, refusing an unknown kind with the list of known ones. */
	EventFactory factory(String kind)
	{
		EventFactory f = factories.get(kind);
		if (f == null)
		{
			throw new ScenarioException("unknown kind '" + kind + "'; known kinds: " + names()
				+ ". A new kind is one EventFactory registered with EventKinds.add (see TESTING.md).");
		}
		return f;
	}

	public List<String> names()
	{
		return Collections.unmodifiableList(new ArrayList<>(factories.keySet()));
	}

	Integer constantValue(String name)
	{
		return constants.get(name);
	}

	List<String> constantNames()
	{
		return new ArrayList<>(constants.keySet());
	}
}

package com.vinnyvangogh.scenarios;

import java.util.ArrayList;
import java.util.List;

/** Checks a scenario's {@code expect} entries against the probes; each failure says what was seen instead. */
public final class Expectations
{
	private Expectations()
	{
	}

	/** Empty when every expectation holds. */
	public static List<String> check(Scenario scenario, Probes probes)
	{
		List<String> failures = new ArrayList<>();
		for (Scenario.Expect e : scenario.expect)
		{
			String failure = check(e, probes);
			if (failure != null)
			{
				failures.add(scenario.source + ": expect " + e.number + ": " + failure);
			}
		}
		return failures;
	}

	private static String check(Scenario.Expect e, Probes probes)
	{
		List<String> lines = probes.lines(e.probe);
		if (lines == null)
		{
			return "unknown probe '" + e.probe + "'; known probes: " + probes.names();
		}
		if (e.contains != null && lines.stream().noneMatch(l -> l.contains(e.contains)))
		{
			return "no line of '" + e.probe + "' contains '" + e.contains + "'; saw " + lines;
		}
		if (e.absent != null && lines.stream().anyMatch(l -> l.contains(e.absent)))
		{
			return "a line of '" + e.probe + "' contains '" + e.absent + "', expected none; saw " + lines;
		}
		if (e.count != null && lines.size() != e.count)
		{
			return "'" + e.probe + "' has " + lines.size() + " lines, expected count " + e.count + "; saw " + lines;
		}
		return null;
	}
}

package com.vinnyvangogh.scenarios;

import java.util.List;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Node;

/**
 * An {@link ItemContainer} holding a fixed list of items, for an {@code ItemContainerChanged} with no game behind
 * it, answered the way the game's container answers.
 */
public final class FakeItemContainer implements ItemContainer
{
	private final int id;
	private final Item[] items;

	public FakeItemContainer(int id, List<Item> items)
	{
		this.id = id;
		this.items = items.toArray(new Item[0]);
	}

	@Override
	public int getId()
	{
		return id;
	}

	@Override
	public Item[] getItems()
	{
		return items.clone();
	}

	@Override
	public Item getItem(int slot)
	{
		return slot >= 0 && slot < items.length ? items[slot] : null;
	}

	@Override
	public boolean contains(int itemId)
	{
		return find(itemId) >= 0;
	}

	@Override
	public int count(int itemId)
	{
		int n = 0;
		for (Item item : items)
		{
			if (item.getId() == itemId)
			{
				n += item.getQuantity();
			}
		}
		return n;
	}

	@Override
	public int size()
	{
		return items.length;
	}

	@Override
	public int count()
	{
		int n = 0;
		for (Item item : items)
		{
			if (item.getId() >= 0)
			{
				n++;
			}
		}
		return n;
	}

	// ItemContainer is also a Node of the game's hash table. Not in any table.

	@Override
	public Node getNext()
	{
		return null;
	}

	@Override
	public Node getPrevious()
	{
		return null;
	}

	@Override
	public long getHash()
	{
		return id;
	}

	@Override
	public int find(int itemId)
	{
		for (int i = 0; i < items.length; i++)
		{
			if (items[i].getId() == itemId)
			{
				return i;
			}
		}
		return -1;
	}
}

package com.vinnyvangogh.scenarios;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * A step's fields, read with types. Every getter refuses a missing or wrong value with a message naming the step,
 * so a typo in a scenario fails at parse time with "step 3 (stat): missing field 'level'".
 *
 * <p>Wherever a number is read, a name registered with {@link EventKinds#constant} works too
 * ({@code "group": "SHARED_BANK"}), so scenarios read as words rather than interface ids.
 */
public final class Fields
{
	private final Step step;
	private final EventKinds kinds;

	Fields(Step step, EventKinds kinds)
	{
		this.step = step;
		this.kinds = kinds;
	}

	public boolean has(String key)
	{
		return step.fields.has(key) && !step.fields.get(key).isJsonNull();
	}

	public String string(String key)
	{
		JsonElement e = need(key);
		if (!e.isJsonPrimitive())
		{
			throw wrong(key, "a string");
		}
		return e.getAsString();
	}

	public String string(String key, String fallback)
	{
		return has(key) ? string(key) : fallback;
	}

	public int integer(String key)
	{
		return Math.toIntExact(number(need(key), key));
	}

	public int integer(String key, int fallback)
	{
		return has(key) ? integer(key) : fallback;
	}

	public long longValue(String key, long fallback)
	{
		return has(key) ? number(need(key), key) : fallback;
	}

	public boolean bool(String key, boolean fallback)
	{
		if (!has(key))
		{
			return fallback;
		}
		JsonElement e = need(key);
		if (!e.isJsonPrimitive() || !((JsonPrimitive) e).isBoolean())
		{
			throw wrong(key, "true or false");
		}
		return e.getAsBoolean();
	}

	/** An enum constant by name, case-sensitive as RuneLite spells them ({@code PRAYER}, {@code GAMEMESSAGE}). */
	public <E extends Enum<E>> E enumValue(String key, Class<E> type)
	{
		String name = string(key);
		for (E e : type.getEnumConstants())
		{
			if (e.name().equals(name))
			{
				return e;
			}
		}
		throw fail("field '" + key + "' is '" + name + "', not a " + type.getSimpleName() + "; one of "
			+ Arrays.toString(type.getEnumConstants()));
	}

	/** {@code {"SHARK": 3, "995": 100}}: item (id or constant) to quantity, in file order. */
	public Map<Integer, Integer> items(String key)
	{
		JsonElement e = need(key);
		if (!e.isJsonObject())
		{
			throw wrong(key, "an object of item to quantity");
		}
		Map<Integer, Integer> out = new LinkedHashMap<>();
		for (Map.Entry<String, JsonElement> entry : ((JsonObject) e).entrySet())
		{
			int id = constantOrNumber(entry.getKey(), key);
			out.put(id, Math.toIntExact(number(entry.getValue(), key + "." + entry.getKey())));
		}
		return out;
	}

	/** {@code {"GroupOtt": 615}}: names to numbers (or constants), in file order. */
	public Map<String, Integer> named(String key)
	{
		JsonElement e = need(key);
		if (!e.isJsonObject())
		{
			throw wrong(key, "an object of name to number");
		}
		Map<String, Integer> out = new LinkedHashMap<>();
		for (Map.Entry<String, JsonElement> entry : ((JsonObject) e).entrySet())
		{
			out.put(entry.getKey(), Math.toIntExact(number(entry.getValue(), key + "." + entry.getKey())));
		}
		return out;
	}

	/** {@code {"eventLevelMin": 70}}: keys to longs, in file order. */
	public Map<String, Long> longs(String key)
	{
		JsonElement e = need(key);
		if (!e.isJsonObject())
		{
			throw wrong(key, "an object of key to number");
		}
		Map<String, Long> out = new LinkedHashMap<>();
		for (Map.Entry<String, JsonElement> entry : ((JsonObject) e).entrySet())
		{
			out.put(entry.getKey(), number(entry.getValue(), key + "." + entry.getKey()));
		}
		return out;
	}

	/** {@code ["Alex", "Sam"]}; empty when the field is absent. */
	public List<String> strings(String key)
	{
		List<String> out = new ArrayList<>();
		if (!has(key))
		{
			return out;
		}
		JsonElement e = need(key);
		if (!e.isJsonArray())
		{
			throw wrong(key, "a list of strings");
		}
		for (JsonElement item : e.getAsJsonArray())
		{
			out.add(item.getAsString());
		}
		return out;
	}

	/** A refusal about this step, for a factory's own checks. */
	public ScenarioException fail(String why)
	{
		return new ScenarioException(step.label() + ": " + why);
	}

	private JsonElement need(String key)
	{
		if (!has(key))
		{
			throw fail("missing field '" + key + "'");
		}
		return step.fields.get(key);
	}

	private long number(JsonElement e, String key)
	{
		if (!e.isJsonPrimitive())
		{
			throw wrong(key, "a number or a constant name");
		}
		JsonPrimitive p = (JsonPrimitive) e;
		if (p.isNumber())
		{
			return p.getAsLong();
		}
		return constantOrNumber(p.getAsString(), key);
	}

	private int constantOrNumber(String text, String key)
	{
		Integer constant = kinds.constantValue(text);
		if (constant != null)
		{
			return constant;
		}
		try
		{
			return Integer.parseInt(text.trim());
		}
		catch (NumberFormatException ex)
		{
			throw fail("field '" + key + "': unknown constant '" + text + "'; known: " + kinds.constantNames());
		}
	}

	private ScenarioException wrong(String key, String expected)
	{
		return fail("field '" + key + "' must be " + expected + ", not " + step.fields.get(key));
	}
}

package com.vinnyvangogh.scenarios;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.Supplier;

/**
 * Named views of what the plugin did, as lines of text: the Discord posts a fake sender captured, the panel's log
 * rows, a setting's value. A scenario's {@code expect} entries check these by name.
 */
public final class Probes
{
	private final Map<String, Supplier<List<String>>> probes = new TreeMap<>();

	public Probes add(String name, Supplier<List<String>> lines)
	{
		if (probes.put(name, lines) != null)
		{
			throw new ScenarioException("probe '" + name + "' is already registered");
		}
		return this;
	}

	/** The probe's lines now; null when there is no such probe. */
	List<String> lines(String name)
	{
		Supplier<List<String>> p = probes.get(name);
		return p == null ? null : new ArrayList<>(p.get());
	}

	List<String> names()
	{
		return new ArrayList<>(probes.keySet());
	}
}

package com.vinnyvangogh.scenarios;

import java.util.Collections;
import java.util.List;

/** A named list of steps, read from one JSON file, and what the plugin should have done once they all fired. */
public final class Scenario
{
	/** The file it came from, for messages. */
	public final String source;
	public final String name;
	public final String description;
	public final List<Step> steps;
	public final List<Expect> expect;

	Scenario(String source, String name, String description, List<Step> steps, List<Expect> expect)
	{
		this.source = source;
		this.name = name;
		this.description = description;
		this.steps = Collections.unmodifiableList(steps);
		this.expect = Collections.unmodifiableList(expect);
	}

	@Override
	public String toString()
	{
		return name;
	}

	/** One check on a probe's lines: one of contains, absent or count is set. */
	public static final class Expect
	{
		public final int number;
		public final String probe;
		public final String contains;
		public final String absent;
		public final Integer count;

		Expect(int number, String probe, String contains, String absent, Integer count)
		{
			this.number = number;
			this.probe = probe;
			this.contains = contains;
			this.absent = absent;
			this.count = count;
		}
	}
}

package com.vinnyvangogh.scenarios;

/** A scenario that cannot be read or run, with a message that says where and why. */
public class ScenarioException extends RuntimeException
{
	public ScenarioException(String message)
	{
		super(message);
	}

	public ScenarioException(String message, Throwable cause)
	{
		super(message, cause);
	}
}

package com.vinnyvangogh.scenarios;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.party.events.UserPart;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/** The harness itself: parsing, refusing what it does not know, firing in order, and checking outputs. */
public class ScenarioHarnessTest
{
	private final EventKinds kinds = EventKinds.core().constant("BANK", 12).constant("SHARK", 385);

	private Scenario parse(String json)
	{
		return ScenarioParser.parse(json, "test.json", kinds);
	}

	private static String refusal(Runnable r)
	{
		try
		{
			r.run();
		}
		catch (ScenarioException e)
		{
			return e.getMessage();
		}
		fail("expected a ScenarioException");
		return null;
	}

	@Test
	public void parsesNameDescriptionStepsWaitsAndExpectations()
	{
		Scenario s = parse("{\"name\":\"Visit\",\"description\":\"Open and close\",\"steps\":["
			+ "{\"kind\":\"widgetLoaded\",\"group\":\"BANK\"},"
			+ "{\"kind\":\"widgetClosed\",\"group\":12,\"wait\":600,\"note\":\"close it\"}],"
			+ "\"expect\":[{\"probe\":\"log\",\"contains\":\"closed\"},{\"probe\":\"log\",\"count\":1}]}");
		assertEquals("Visit", s.name);
		assertEquals("Open and close", s.description);
		assertEquals(2, s.steps.size());
		assertEquals("widgetLoaded", s.steps.get(0).kind);
		assertEquals(0, s.steps.get(0).waitMs);
		assertEquals(600, s.steps.get(1).waitMs);
		assertEquals("close it", s.steps.get(1).note);
		assertEquals(2, s.expect.size());
		assertEquals("log", s.expect.get(0).probe);
	}

	@Test
	public void anUnknownKindIsRefusedNamingTheFileTheStepAndTheKnownKinds()
	{
		String msg = refusal(() -> parse("{\"name\":\"x\",\"steps\":[{\"kind\":\"chat\",\"type\":\"GAMEMESSAGE\","
			+ "\"message\":\"hi\"},{\"kind\":\"teleport\"}]}"));
		assertTrue(msg, msg.contains("test.json"));
		assertTrue(msg, msg.contains("step 2"));
		assertTrue(msg, msg.contains("unknown kind 'teleport'"));
		assertTrue("lists what is known: " + msg, msg.contains("stat") && msg.contains("widgetLoaded"));
	}

	@Test
	public void aMissingOrWrongFieldIsRefusedAtParseNotHalfWayThroughARun()
	{
		String missing = refusal(() -> parse("{\"name\":\"x\",\"steps\":[{\"kind\":\"stat\",\"skill\":\"PRAYER\"}]}"));
		assertTrue(missing, missing.contains("step 1 (stat)") && missing.contains("missing field 'level'"));

		String badEnum = refusal(() -> parse("{\"name\":\"x\",\"steps\":[{\"kind\":\"stat\",\"skill\":\"PRAYR\","
			+ "\"level\":5}]}"));
		assertTrue(badEnum, badEnum.contains("'PRAYR'") && badEnum.contains("PRAYER"));

		String badConstant = refusal(() -> parse("{\"name\":\"x\",\"steps\":[{\"kind\":\"widgetLoaded\","
			+ "\"group\":\"NOPE\"}]}"));
		assertTrue(badConstant, badConstant.contains("unknown constant 'NOPE'") && badConstant.contains("BANK"));
	}

	@Test
	public void aScenarioNeedsANameAndAtLeastOneStep()
	{
		assertTrue(refusal(() -> parse("{\"steps\":[{\"kind\":\"tick\"}]}")).contains("'name'"));
		assertTrue(refusal(() -> parse("{\"name\":\"x\",\"steps\":[]}")).contains("no steps"));
		assertTrue(refusal(() -> parse("{\"name\":\"x\",\"steps\":[{\"type\":\"chat\"}]}")).contains("no 'kind'"));
		assertTrue(refusal(() -> parse("not json")).contains("test.json"));
	}

	@Test
	public void anExpectationNeedsAProbeAndOneCheck()
	{
		String msg = refusal(() -> parse("{\"name\":\"x\",\"steps\":[{\"kind\":\"tick\"}],"
			+ "\"expect\":[{\"probe\":\"log\"}]}"));
		assertTrue(msg, msg.contains("expect 1") && msg.contains("contains, absent or count"));
	}

	@Test
	public void stepsFireInOrderAndEachWaitComesBeforeItsStep()
	{
		Scenario s = parse("{\"name\":\"x\",\"steps\":["
			+ "{\"kind\":\"chat\",\"type\":\"GAMEMESSAGE\",\"message\":\"one\"},"
			+ "{\"kind\":\"chat\",\"type\":\"GAMEMESSAGE\",\"message\":\"two\",\"wait\":1000},"
			+ "{\"kind\":\"chat\",\"type\":\"GAMEMESSAGE\",\"message\":\"three\",\"wait\":5}]}");
		List<String> seen = new ArrayList<>();
		ScenarioRun run = new ScenarioRun(s, kinds, e -> seen.add("post " + ((ChatMessage) e).getMessage()));
		run.runAll(ms -> seen.add("wait " + ms));
		assertEquals(Arrays.asList("post one", "wait 1000", "post two", "wait 5", "post three"), seen);
		assertFalse(run.hasNext());
	}

	@Test
	public void stepByStepReportsWhatFiredAndStopsAtTheEnd()
	{
		Scenario s = parse("{\"name\":\"x\",\"steps\":[{\"kind\":\"tick\"},{\"kind\":\"widgetClosed\","
			+ "\"group\":\"BANK\",\"wait\":600}]}");
		List<Object> posted = new ArrayList<>();
		ScenarioRun run = new ScenarioRun(s, kinds, posted::add);
		assertEquals(0, run.nextWait());
		ScenarioRun.Fired first = run.step();
		assertEquals(1, first.number);
		assertEquals("tick", first.step.kind);
		assertEquals(600, run.nextWait());
		ScenarioRun.Fired second = run.step();
		assertSame(posted.get(1), second.event);
		assertEquals(12, ((WidgetClosed) second.event).getGroupId());
		assertNull("nothing left", run.step());
	}

	@Test
	public void aHeadlessOnlyStepIsSkippedLiveAndSaysWhy()
	{
		Scenario s = parse("{\"name\":\"x\",\"steps\":[{\"kind\":\"tick\"},{\"kind\":\"chat\","
			+ "\"type\":\"GAMEMESSAGE\",\"message\":\"hi\"}]}");
		List<Object> posted = new ArrayList<>();
		ScenarioRun run = new ScenarioRun(s, kinds, posted::add).live(true);
		ScenarioRun.Fired tick = run.step();
		assertNull(tick.event);
		assertTrue(tick.skipped, tick.skipped.contains("headless"));
		run.step();
		assertEquals(1, posted.size());
		assertTrue(posted.get(0) instanceof ChatMessage);
	}

	@Test
	public void coreKindsBuildTheRuneLiteEventsTheirFieldsDescribe()
	{
		Scenario s = parse("{\"name\":\"x\",\"steps\":["
			+ "{\"kind\":\"chat\",\"type\":\"CLAN_GIM_MESSAGE\",\"name\":\"Alex\",\"message\":\"hello\"},"
			+ "{\"kind\":\"stat\",\"skill\":\"PRAYER\",\"level\":44,\"xp\":50000},"
			+ "{\"kind\":\"container\",\"id\":93,\"items\":{\"SHARK\":3,\"995\":100}},"
			+ "{\"kind\":\"varbit\",\"varbit\":4070,\"value\":2},"
			+ "{\"kind\":\"varp\",\"varp\":101,\"value\":7},"
			+ "{\"kind\":\"gameState\",\"state\":\"LOGIN_SCREEN\"},"
			+ "{\"kind\":\"userPart\",\"memberId\":42}]}");
		List<Object> posted = new ArrayList<>();
		new ScenarioRun(s, kinds, posted::add).runAll(ms ->
		{
		});

		ChatMessage chat = (ChatMessage) posted.get(0);
		assertEquals(ChatMessageType.CLAN_GIM_MESSAGE, chat.getType());
		assertEquals("Alex", chat.getName());
		assertEquals("hello", chat.getMessage());

		StatChanged stat = (StatChanged) posted.get(1);
		assertEquals(Skill.PRAYER, stat.getSkill());
		assertEquals(44, stat.getLevel());
		assertEquals("boosted defaults to the level", 44, stat.getBoostedLevel());
		assertEquals(50000, stat.getXp());

		ItemContainerChanged inv = (ItemContainerChanged) posted.get(2);
		assertEquals(93, inv.getContainerId());
		assertEquals(3, inv.getItemContainer().count(385));
		assertEquals(100, inv.getItemContainer().count(995));
		assertEquals(Arrays.asList(new Item(385, 3), new Item(995, 100)),
			Arrays.asList(inv.getItemContainer().getItems()));

		VarbitChanged varbit = (VarbitChanged) posted.get(3);
		assertEquals(4070, varbit.getVarbitId());
		assertEquals(-1, varbit.getVarpId());
		assertEquals(2, varbit.getValue());
		assertEquals(101, ((VarbitChanged) posted.get(4)).getVarpId());

		assertEquals(GameState.LOGIN_SCREEN, ((GameStateChanged) posted.get(5)).getGameState());
		assertEquals(42, ((UserPart) posted.get(6)).getMemberId());
	}

	@Test
	public void widgetEventsCarryTheirGroup()
	{
		Scenario s = parse("{\"name\":\"x\",\"steps\":[{\"kind\":\"widgetLoaded\",\"group\":\"BANK\"}]}");
		List<Object> posted = new ArrayList<>();
		new ScenarioRun(s, kinds, posted::add).step();
		assertEquals(12, ((WidgetLoaded) posted.get(0)).getGroupId());
	}

	@Test
	public void theFakeContainerAnswersLikeTheGamesOne()
	{
		FakeItemContainer c = new FakeItemContainer(93, Arrays.asList(new Item(385, 3), new Item(995, 100)));
		assertEquals(93, c.getId());
		assertEquals(2, c.size());
		assertEquals(2, c.count());
		assertTrue(c.contains(995));
		assertFalse(c.contains(1));
		assertEquals(1, c.find(995));
		assertEquals(-1, c.find(1));
		assertEquals(new Item(385, 3), c.getItem(0));
		assertNull(c.getItem(5));
		assertEquals(0, new FakeItemContainer(1, Collections.emptyList()).count());
	}

	@Test
	public void expectationsPassAndFailWithMessagesThatSayWhatWasSeen()
	{
		Scenario s = parse("{\"name\":\"x\",\"steps\":[{\"kind\":\"tick\"}],\"expect\":["
			+ "{\"probe\":\"log\",\"contains\":\"deposited 5\"},"
			+ "{\"probe\":\"log\",\"absent\":\"took\"},"
			+ "{\"probe\":\"log\",\"count\":3}]}");
		Probes probes = new Probes().add("log", () -> Arrays.asList("You deposited 5 Trout", "You took 2 Coal"));
		List<String> failures = Expectations.check(s, probes);
		assertEquals(2, failures.size());
		assertTrue(failures.get(0), failures.get(0).contains("expect 2")
			&& failures.get(0).contains("'took'") && failures.get(0).contains("You took 2 Coal"));
		assertTrue(failures.get(1), failures.get(1).contains("has 2 lines, expected count 3"));

		Probes right = new Probes().add("log", () -> Arrays.asList("You deposited 5 Trout", "Alex looked", "Sam looked"));
		assertTrue(Expectations.check(s, right).isEmpty());
	}

	@Test
	public void anUnknownProbeIsAFailureNamingTheKnownOnes()
	{
		Scenario s = parse("{\"name\":\"x\",\"steps\":[{\"kind\":\"tick\"}],\"expect\":["
			+ "{\"probe\":\"discord\",\"count\":0}]}");
		List<String> failures = Expectations.check(s, new Probes().add("log", Collections::emptyList));
		assertEquals(1, failures.size());
		assertTrue(failures.get(0), failures.get(0).contains("unknown probe 'discord'") && failures.get(0).contains("log"));
	}

	@Test
	public void aPluginKindRegistersBesideTheCoreOnesAndCannotReplaceThem()
	{
		EventKinds mine = EventKinds.core().add("hello", f -> "hello " + f.string("who"));
		Scenario s = ScenarioParser.parse("{\"name\":\"x\",\"steps\":[{\"kind\":\"hello\",\"who\":\"Sam\"}]}",
			"t.json", mine);
		List<Object> posted = new ArrayList<>();
		new ScenarioRun(s, mine, posted::add).step();
		assertEquals("hello Sam", posted.get(0));
		assertTrue(refusal(() -> mine.add("chat", f -> "x")).contains("already registered"));
	}

	@Test
	public void scenariosLoadFromTheClasspathDirectorySortedByFile()
	{
		List<Scenario> all = ScenarioParser.loadAll("harness-fixtures", kinds);
		assertEquals(2, all.size());
		assertEquals("Alpha", all.get(0).name);
		assertEquals("Beta", all.get(1).name);
		assertEquals("a-alpha.json", all.get(0).source);
	}

	@Test
	public void aMissingScenarioDirectoryIsRefusedClearly()
	{
		assertTrue(refusal(() -> ScenarioParser.loadAll("no-such-dir", kinds)).contains("no-such-dir"));
	}
}

package com.vinnyvangogh.scenarios;

import java.awt.BorderLayout;
import java.awt.GridLayout;
