/**
 * The Scenarios sidebar: pick a scenario, Run it (steps keep their waits) or Step through it one event at a time.
 * Swing thread only; events leave through {@code post}, which hands them to the client thread.
 */
final class ScenarioPanel extends PluginPanel
{
	private static final String WARNING = "Events go to every plugin in this client, and the plugin's outputs are "
		+ "real: a webhook you set gets real posts. Point webhooks at a test channel first.";

	private final EventKinds kinds;
	private final Consumer<Object> post;
	private final JComboBox<Scenario> picker = new JComboBox<>();
	private final JTextArea about = text(4);
	private final JTextArea log = text(14);
	private ScenarioRun run;
	private Timer timer;

	ScenarioPanel(EventKinds kinds, Consumer<Object> post)
	{
		this.kinds = kinds;
		this.post = post;
		setLayout(new BorderLayout(0, 6));

		JTextArea warning = text(4);
		warning.setText(WARNING);
		picker.addActionListener(e -> chosen());

		JPanel buttons = new JPanel(new GridLayout(1, 4, 4, 0));
		buttons.add(button("Run", this::runAll));
		buttons.add(button("Step", this::stepOnce));
		buttons.add(button("Reset", this::reset));
		buttons.add(button("Reload", this::reload));

		JPanel top = new JPanel(new BorderLayout(0, 6));
		top.add(warning, BorderLayout.NORTH);
		top.add(picker, BorderLayout.CENTER);
		top.add(buttons, BorderLayout.SOUTH);

		JPanel middle = new JPanel(new BorderLayout(0, 6));
		middle.add(about, BorderLayout.NORTH);
		middle.add(new JScrollPane(log), BorderLayout.CENTER);

		add(top, BorderLayout.NORTH);
		add(middle, BorderLayout.CENTER);
	}

	private static JTextArea text(int rows)
	{
		JTextArea area = new JTextArea(rows, 20);
		area.setEditable(false);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
		return area;
	}

	private static JButton button(String label, Runnable action)
	{
		JButton b = new JButton(label);
		b.addActionListener(e -> action.run());
		return b;
	}

	/** Reads every scenario again: edit a JSON file, rebuild resources, Reload. */
	void reload()
	{
		reset();
		picker.removeAllItems();
		try
		{
			for (Scenario s : ScenarioParser.loadAll(ScenarioParser.DEFAULT_DIR, kinds))
			{
				picker.addItem(s);
			}
			say("Loaded " + picker.getItemCount() + " scenarios.");
		}
		catch (ScenarioException e)
		{
			say("Cannot load scenarios: " + e.getMessage());
		}
	}

	private void chosen()
	{
		reset();
		Scenario s = (Scenario) picker.getSelectedItem();
		about.setText(s == null ? "" : s.description == null ? s.name : s.description);
	}

	private ScenarioRun current()
	{
		Scenario s = (Scenario) picker.getSelectedItem();
		if (s != null && (run == null || !run.hasNext()))
		{
			run = new ScenarioRun(s, kinds, post).live(true);
			say("— " + s.name + " —");
		}
		return run;
	}

	private void stepOnce()
	{
		stopTimer();
		fire(current());
	}

	private void runAll()
	{
		stopTimer();
		ScenarioRun r = current();
		if (r != null)
		{
			schedule(r);
		}
	}

	/** The next step after its wait, then the one after that, until the scenario ends or Reset. */
	private void schedule(ScenarioRun r)
	{
		if (!r.hasNext())
		{
			say("Done. Check the plugin's panel, overlay and Discord channel.");
			return;
		}
		timer = new Timer((int) Math.min(Integer.MAX_VALUE, r.nextWait()), e ->
		{
			fire(r);
			schedule(r);
		});
		timer.setRepeats(false);
		timer.start();
	}

	private void fire(ScenarioRun r)
	{
		if (r == null || !r.hasNext())
		{
			return;
		}
		try
		{
			say(r.step().toString());
		}
		catch (ScenarioException e)
		{
			say(e.getMessage());
		}
	}

	private void reset()
	{
		stopTimer();
		run = null;
		log.setText("");
	}

	private void stopTimer()
	{
		if (timer != null)
		{
			timer.stop();
			timer = null;
		}
	}

	private void say(String line)
	{
		log.append(line + "\n");
	}
}

package com.vinnyvangogh.scenarios;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.net.JarURLConnection;
import java.net.URISyntaxException;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Enumeration;
import java.util.List;
import java.util.jar.JarEntry;
import java.util.jar.JarFile;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/**
 * Reads scenario JSON. Everything a run would trip over is refused here instead: an unknown kind, a missing or
 * mistyped field, an unknown constant. Each step's event is built once while parsing, so a scenario that parses
 * is one whose every step can fire.
 */
public final class ScenarioParser
{
	/** Where scenarios live on the test classpath: {@code src/test/resources/scenarios}. */
	public static final String DEFAULT_DIR = "scenarios";

	private static final Gson GSON = new Gson();

	private ScenarioParser()
	{
	}

	public static Scenario parse(String json, String source, EventKinds kinds)
	{
		JsonObject root;
		try
		{
			root = GSON.fromJson(json, JsonObject.class);
		}
		catch (JsonParseException | ClassCastException e)
		{
			// ClassCastException: valid JSON that is not an object, such as a bare string.
			throw new ScenarioException(source + ": not a JSON object: " + e.getMessage(), e);
		}
		if (root == null)
		{
			throw new ScenarioException(source + ": empty file");
		}
		try
		{
			return read(root, source, kinds);
		}
		catch (ScenarioException e)
		{
			throw new ScenarioException(source + ": " + e.getMessage(), e);
		}
	}

	private static Scenario read(JsonObject root, String source, EventKinds kinds)
	{
		String name = text(root, "name");
		if (name == null || name.trim().isEmpty())
		{
			throw new ScenarioException("a scenario needs a 'name'");
		}
		List<Step> steps = new ArrayList<>();
		for (JsonElement e : array(root, "steps"))
		{
			steps.add(step(e, steps.size() + 1, kinds));
		}
		if (steps.isEmpty())
		{
			throw new ScenarioException("'" + name + "' has no steps");
		}
		List<Scenario.Expect> expect = new ArrayList<>();
		for (JsonElement e : array(root, "expect"))
		{
			expect.add(expectation(e, expect.size() + 1));
		}
		return new Scenario(source, name, text(root, "description"), steps, expect);
	}

	/** The array at {@code key}; empty when absent or not an array. */
	private static JsonArray array(JsonObject o, String key)
	{
		return o.has(key) && o.get(key).isJsonArray() ? o.getAsJsonArray(key) : new JsonArray();
	}

	private static Step step(JsonElement e, int number, EventKinds kinds)
	{
		if (!e.isJsonObject())
		{
			throw new ScenarioException("step " + number + " is not an object");
		}
		JsonObject o = e.getAsJsonObject();
		String kind = text(o, Step.KIND);
		if (kind == null)
		{
			throw new ScenarioException("step " + number + " has no 'kind'");
		}
		JsonObject fields = o.deepCopy();
		fields.remove(Step.KIND);
		fields.remove(Step.WAIT);
		fields.remove(Step.NOTE);
		long wait = o.has(Step.WAIT) ? o.get(Step.WAIT).getAsLong() : 0;
		if (wait < 0)
		{
			throw new ScenarioException("step " + number + ": 'wait' cannot be negative");
		}
		Step step = new Step(number, kind, wait, text(o, Step.NOTE), fields);
		EventFactory factory;
		try
		{
			factory = kinds.factory(kind);
		}
		catch (ScenarioException ex)
		{
			throw new ScenarioException("step " + number + ": " + ex.getMessage(), ex);
		}
		build(step, factory, kinds);
		return step;
	}

	/** Builds the step's event, turning any failure into one that names the step. */
	static Object build(Step step, EventFactory factory, EventKinds kinds)
	{
		try
		{
			return factory.create(new Fields(step, kinds));
		}
		catch (ScenarioException e)
		{
			throw e;
		}
		catch (RuntimeException e)
		{
			throw new ScenarioException(step.label() + ": " + e, e);
		}
	}

	private static Scenario.Expect expectation(JsonElement e, int number)
	{
		if (!e.isJsonObject())
		{
			throw new ScenarioException("expect " + number + " is not an object");
		}
		JsonObject o = e.getAsJsonObject();
		String probe = text(o, "probe");
		String contains = text(o, "contains");
		String absent = text(o, "absent");
		Integer count = o.has("count") ? o.get("count").getAsInt() : null;
		int checks = (contains == null ? 0 : 1) + (absent == null ? 0 : 1) + (count == null ? 0 : 1);
		if (probe == null || checks != 1)
		{
			throw new ScenarioException("expect " + number + " needs a 'probe' and exactly one of contains, absent "
				+ "or count");
		}
		return new Scenario.Expect(number, probe, contains, absent, count);
	}

	private static String text(JsonObject o, String key)
	{
		return o.has(key) && o.get(key).isJsonPrimitive() ? o.get(key).getAsString() : null;
	}

	/** Every {@code *.json} in {@code dir} on the test classpath, in file name order. */
	public static List<Scenario> loadAll(String dir, EventKinds kinds)
	{
		ClassLoader loader = ScenarioParser.class.getClassLoader();
		URL url = loader.getResource(dir);
		if (url == null)
		{
			throw new ScenarioException("no scenario directory '" + dir + "' on the test classpath (src/test/resources/"
				+ dir + ")");
		}
		List<Scenario> out = new ArrayList<>();
		for (String file : list(url, dir))
		{
			out.add(parse(read(loader, dir + "/" + file), file, kinds));
		}
		return out;
	}

	private static List<String> list(URL url, String dir)
	{
		try
		{
			List<String> names = "jar".equals(url.getProtocol()) ? inJar(url, dir) : inDirectory(Paths.get(url.toURI()));
			Collections.sort(names);
			return names;
		}
		catch (IOException | URISyntaxException e)
		{
			throw new ScenarioException("cannot list scenarios in " + url + ": " + e, e);
		}
	}

	private static List<String> inDirectory(Path dir) throws IOException
	{
		try (Stream<Path> files = Files.list(dir))
		{
			return files.map(p -> p.getFileName().toString()).filter(n -> n.endsWith(".json"))
				.collect(Collectors.toList());
		}
	}

	/** The shadow jar ({@code ./gradlew shadowJar}) keeps scenarios inside it. */
	private static List<String> inJar(URL url, String dir) throws IOException
	{
		List<String> names = new ArrayList<>();
		String prefix = dir + "/";
		try (JarFile jar = ((JarURLConnection) url.openConnection()).getJarFile())
		{
			Enumeration<JarEntry> entries = jar.entries();
			while (entries.hasMoreElements())
			{
				String name = entries.nextElement().getName();
				if (name.startsWith(prefix) && name.endsWith(".json") && name.indexOf('/', prefix.length()) < 0)
				{
					names.add(name.substring(prefix.length()));
				}
			}
		}
		return names;
	}

	private static String read(ClassLoader loader, String resource)
	{
		try (InputStream in = loader.getResourceAsStream(resource))
		{
			if (in == null)
			{
				throw new ScenarioException("cannot read " + resource);
			}
			StringBuilder sb = new StringBuilder();
			char[] buf = new char[4096];
			try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				for (int n = r.read(buf); n > 0; n = r.read(buf))
				{
					sb.append(buf, 0, n);
				}
			}
			return sb.toString();
		}
		catch (IOException e)
		{
			throw new ScenarioException("cannot read " + resource + ": " + e, e);
		}
	}
}

package com.vinnyvangogh.scenarios;

import java.util.function.Consumer;
import java.util.function.LongConsumer;

/**
 * One pass through a scenario, a step at a time. It never sleeps: {@link #nextWait} says how long the next step
 * wants, and the caller waits its own way (a fake clock headless, a Swing timer in the panel).
 */
public final class ScenarioRun
{
	private final Scenario scenario;
	private final EventKinds kinds;
	private final Consumer<Object> post;
	private boolean live;
	private int next;

	/** {@code post}: where each event goes, an EventBus's {@code post} or a test's list. */
	public ScenarioRun(Scenario scenario, EventKinds kinds, Consumer<Object> post)
	{
		this.scenario = scenario;
		this.kinds = kinds;
		this.post = post;
	}

	/** Live, in the developer client: steps whose kind is headless-only are skipped, not posted. */
	public ScenarioRun live(boolean live)
	{
		this.live = live;
		return this;
	}

	public Scenario scenario()
	{
		return scenario;
	}

	public boolean hasNext()
	{
		return next < scenario.steps.size();
	}

	/** Milliseconds the next step waits before it fires; 0 when there is none. */
	public long nextWait()
	{
		return hasNext() ? scenario.steps.get(next).waitMs : 0;
	}

	/** Fires the next step and says what happened; null when every step has fired. */
	public Fired step()
	{
		if (!hasNext())
		{
			return null;
		}
		Step step = scenario.steps.get(next++);
		EventFactory factory = kinds.factory(step.kind);
		String why = factory.headlessOnly();
		if (live && why != null)
		{
			return new Fired(step, null, "skipped, headless only: " + why);
		}
		Object event = ScenarioParser.build(step, factory, kinds);
		post.accept(event);
		return new Fired(step, event, null);
	}

	/** Every remaining step in order, handing each wait to {@code waiter} first. */
	public void runAll(LongConsumer waiter)
	{
		while (hasNext())
		{
			long wait = nextWait();
			if (wait > 0)
			{
				waiter.accept(wait);
			}
			step();
		}
	}

	/** One step's outcome: the event posted, or why it was skipped. */
	public static final class Fired
	{
		public final int number;
		public final Step step;
		/** Null when skipped. */
		public final Object event;
		/** Null when posted. */
		public final String skipped;

		Fired(Step step, Object event, String skipped)
		{
			this.number = step.number;
			this.step = step;
			this.event = event;
			this.skipped = skipped;
		}

		@Override
		public String toString()
		{
			String what = skipped != null ? skipped : "posted " + event.getClass().getSimpleName();
			return step + ": " + what;
		}
	}
}

package com.vinnyvangogh.scenarios;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

/**
 * Developer client only: a "Scenarios" sidebar that posts a scenario's events into the client's real EventBus,
 * on the client thread, as the game would. Lives in src/test, so it is never in the Plugin Hub jar.
 *
 * <p>Started by the plugin's {@code *PluginTest} launcher, which calls {@link #use} first:
 * <pre>
 *   ScenariosPlugin.use(MyEventKinds.kinds());
 *   ExternalPluginManager.loadBuiltin(MyPlugin.class, ScenariosPlugin.class);
 * </pre>
 * No game input is sent and nothing reaches Jagex: an event is only a Java object handed to subscribers.
 */
@PluginDescriptor(
	name = "Scenarios (dev)",
	description = "Posts made-up game events from src/test/resources/scenarios into the developer client",
	developerPlugin = true
)
public class ScenariosPlugin extends Plugin
{
	/** Set by the launcher before RuneLite starts; read once when the plugin starts. */
	private static volatile EventKinds kinds = EventKinds.core();

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private EventBus eventBus;

	@Inject
	private ClientThread clientThread;

	private NavigationButton button;

	/** The plugin's kinds (core plus its own), for the panel to read scenarios with. */
	public static void use(EventKinds pluginKinds)
	{
		kinds = pluginKinds;
	}

	@Override
	protected void startUp()
	{
		ScenarioPanel panel = new ScenarioPanel(kinds, event -> clientThread.invokeLater(() -> eventBus.post(event)));
		button = NavigationButton.builder()
			.tooltip("Scenarios (dev)")
			.icon(icon())
			.priority(99)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(button);
		SwingUtilities.invokeLater(panel::reload);
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(button);
		button = null;
	}

	/** A drawn "S" so the template needs no image resource. */
	private static BufferedImage icon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setColor(new Color(0x2E7D32));
		g.fillRoundRect(0, 0, 16, 16, 5, 5);
		g.setColor(Color.WHITE);
		g.drawString("S", 4, 13);
		g.dispose();
		return image;
	}
}

package com.vinnyvangogh.scenarios;

import com.google.gson.JsonObject;

/**
 * One line of a scenario: an event kind, its fields, and how long to wait before it fires.
 *
 * <p>Reserved keys in the step object are {@code kind}, {@code wait} (milliseconds before this step) and
 * {@code note} (shown in the panel); every other key is a field for the kind's {@link EventFactory}.
 */
public final class Step
{
	static final String KIND = "kind";
	static final String WAIT = "wait";
	static final String NOTE = "note";

	/** 1-based, as error messages and the panel number it. */
	public final int number;
	public final String kind;
	public final long waitMs;
	public final String note;
	final JsonObject fields;

	Step(int number, String kind, long waitMs, String note, JsonObject fields)
	{
		this.number = number;
		this.kind = kind;
		this.waitMs = waitMs;
		this.note = note;
		this.fields = fields;
	}

	/** "step 2 (stat)": how every message about this step starts. */
	public String label()
	{
		return "step " + number + " (" + kind + ")";
	}

	@Override
	public String toString()
	{
		return label() + (note == null ? "" : " " + note);
	}
}

package com.vinnyvangogh.testkit.ui;

import java.awt.Component;
import java.awt.Container;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.Map;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigDescriptor;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * RuneLite's own settings panel ({@code ConfigPanel}) for a plugin's config
 * interface, built without the client: the page a player opens from the
 * wrench, with the same sections, widgets and order.
 *
 * <p>ConfigPanel is package-private with a private Guice constructor, and the
 * client jar is signed, so a test class cannot join its package: it is
 * reached by reflection here. That is test code only; it never ships. Its
 * other collaborators are used only on clicks a test never makes (plugin
 * toggle, reset, colour picker), so they are null. {@link ConfigManager} is a
 * mock that answers every read from the interface's own defaults, overridden
 * per test. If RuneLite changes the panel's shape, this fails loudly saying so.
 *
 * <p>Copy-in template: no plugin types; pass any plugin's config interface.
 */
public final class ConfigPanelHarness
{
	private static final String PANEL = "net.runelite.client.plugins.config.ConfigPanel";
	private static final String DESCRIPTOR = "net.runelite.client.plugins.config.PluginConfigurationDescriptor";

	private final PluginPanel panel;

	private ConfigPanelHarness(PluginPanel panel)
	{
		this.panel = panel;
	}

	/**
	 * The panel for {@code defaults}' config interface ({@code new MyConfig(){}}
	 * serves), showing {@code overrides} (keyName to value) over the defaults.
	 * Call on the Swing thread.
	 */
	public static ConfigPanelHarness of(String title, Config defaults, Map<String, Object> overrides)
	{
		Map<String, Object> values = defaults(defaults);
		values.putAll(overrides);
		ConfigManager configManager = configManager(values);
		ConfigDescriptor descriptor = configManager.getConfigDescriptor(defaults);
		try
		{
			Class<?> panelClass = Class.forName(PANEL);
			resetSectionMemory(panelClass);
			Constructor<?> make = panelClass.getDeclaredConstructors()[0];
			make.setAccessible(true);
			Object[] args = new Object[make.getParameterCount()];
			for (int i = 0; i < args.length; i++)
			{
				args[i] = make.getParameterTypes()[i] == ConfigManager.class ? configManager : null;
			}
			PluginPanel panel = (PluginPanel) make.newInstance(args);
			Method init = panelClass.getDeclaredMethod("init", Class.forName(DESCRIPTOR));
			init.setAccessible(true);
			init.invoke(panel, descriptor(title, defaults, descriptor));
			return new ConfigPanelHarness(panel);
		}
		catch (ReflectiveOperationException e)
		{
			throw new IllegalStateException("RuneLite's ConfigPanel changed shape; update ConfigPanelHarness", e);
		}
	}

	private static Object descriptor(String title, Config config, ConfigDescriptor cd)
		throws ReflectiveOperationException
	{
		Constructor<?> make = Class.forName(DESCRIPTOR).getDeclaredConstructor(String.class, String.class,
			String[].class, Config.class, ConfigDescriptor.class);
		make.setAccessible(true);
		return make.newInstance(title, "", new String[0], config, cd);
	}

	public PluginPanel panel()
	{
		return panel;
	}

	/** The section titled {@code name}: its header and its contents. */
	public JComponent section(String name)
	{
		return (JComponent) title(name).getParent().getParent();
	}

	/** Whether the section's contents are showing. */
	public boolean isOpen(String name)
	{
		Container header = title(name).getParent();
		for (Component c : header.getParent().getComponents())
		{
			if (c != header)
			{
				return c.isVisible();
			}
		}
		return false;
	}

	/** Opens or closes a section with its own expand button, as a click would. */
	public void setOpen(String name, boolean open)
	{
		if (isOpen(name) == open)
		{
			return;
		}
		for (Component c : title(name).getParent().getComponents())
		{
			if (c instanceof JButton)
			{
				((JButton) c).doClick(0);
				return;
			}
		}
		throw new AssertionError("Section '" + name + "' has no expand button");
	}

	/** A section's title: RuneLite draws them in brand orange, which tells them apart from setting names. */
	private JLabel title(String name)
	{
		for (JLabel l : new SwingDriver(panel).all(JLabel.class))
		{
			if (name.equals(l.getText()) && ColorScheme.BRAND_ORANGE.equals(l.getForeground()))
			{
				return l;
			}
		}
		throw new AssertionError("No section '" + name + "'");
	}

	// ---- The mocked ConfigManager ----

	/** Each item's default, by keyName, read by calling the interface's default methods. */
	static Map<String, Object> defaults(Config defaults)
	{
		Map<String, Object> out = new HashMap<>();
		Class<?> iface = defaults.getClass().getInterfaces()[0];
		for (Method m : iface.getDeclaredMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item == null || m.getParameterCount() != 0 || !m.isDefault())
			{
				continue;
			}
			try
			{
				out.put(item.keyName(), m.invoke(defaults));
			}
			catch (ReflectiveOperationException e)
			{
				throw new IllegalStateException("Cannot read the default of " + item.keyName(), e);
			}
		}
		return out;
	}

	private static ConfigManager configManager(Map<String, Object> values)
	{
		ConfigManager cm = mock(ConfigManager.class);
		when(cm.getConfigDescriptor(any())).thenCallRealMethod();
		when(cm.getConfiguration(anyString(), anyString())).thenAnswer(inv ->
			asString(values.get(inv.<String>getArgument(1))));
		when(cm.getConfiguration(anyString(), anyString(), any(Type.class))).thenAnswer(inv ->
			values.get(inv.<String>getArgument(1)));
		return cm;
	}

	/** A value as ConfigManager stores it: enums by name, everything else as its text. */
	static String asString(Object value)
	{
		if (value == null)
		{
			return null;
		}
		if (value instanceof Enum)
		{
			return ((Enum<?>) value).name();
		}
		return String.valueOf(value);
	}

	/** The panel remembers opened sections for the whole JVM; each harness starts from the defaults. */
	@SuppressWarnings("unchecked")
	private static void resetSectionMemory(Class<?> panelClass) throws ReflectiveOperationException
	{
		Field f = panelClass.getDeclaredField("sectionExpandStates");
		f.setAccessible(true);
		((Map<Object, Object>) f.get(null)).clear();
	}
}

package com.vinnyvangogh.testkit.ui;

import net.runelite.client.ui.laf.RuneLiteLAF;

/**
 * RuneLite's own look and feel ({@link RuneLiteLAF}, the dark FlatLaf theme the
 * client installs at startup), so a panel under test is built, sized and drawn
 * the way players see it. Install before creating any component.
 */
public final class RuneLiteLook
{
	private static boolean installed;

	private RuneLiteLook()
	{
	}

	/** Idempotent; call on the Swing thread. */
	public static synchronized void install()
	{
		if (!installed)
		{
			RuneLiteLAF.setup();
			installed = true;
		}
	}
}

package com.vinnyvangogh.testkit.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.awt.event.MouseListener;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.function.Predicate;
import javax.imageio.ImageIO;
import javax.swing.AbstractButton;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import javax.swing.text.JTextComponent;

/**
 * Drives a plugin's own Swing panel from a test: find a component by its text,
 * click it, type into it, read what is on screen, and render it to a PNG.
 *
 * <p>Nothing here moves the mouse or sends a key to the operating system. A
 * click is the button's own {@link AbstractButton#doClick(int)} or a
 * {@link MouseEvent} handed straight to the component's listeners, so it never
 * leaves the component tree, never reaches the game, and needs no display: it
 * runs with {@code java.awt.headless=true}, on CI as on the Mac. (Why not
 * {@code java.awt.Robot} or AssertJ Swing: both drive the real OS pointer, need
 * a display, and take over the developer's mouse while they run.)
 *
 * <p>The tree is never put in a window. {@link #layout} sizes and lays it out
 * by hand, and "visible" means the component and every parent up to the root
 * are {@link Component#isVisible() visible}: a CardLayout's hidden cards and a
 * collapsed section's body do not count.
 *
 * <p>Copy-in template: the same file in every plugin, no plugin types. Call
 * everything on the Swing thread ({@link #onEdt}).
 */
public final class SwingDriver
{
	private final Container root;

	public SwingDriver(Container root)
	{
		this.root = root;
	}

	public Container root()
	{
		return root;
	}

	// ---- Threading ----

	/** Runs {@code r} on the Swing thread and waits, rethrowing what it threw. */
	public static void onEdt(Runnable r)
	{
		onEdt(() ->
		{
			r.run();
			return null;
		});
	}

	public static <T> T onEdt(Callable<T> c)
	{
		if (SwingUtilities.isEventDispatchThread())
		{
			return call(c);
		}
		List<T> out = new ArrayList<>();
		try
		{
			SwingUtilities.invokeAndWait(() -> out.add(call(c)));
		}
		catch (InterruptedException e)
		{
			Thread.currentThread().interrupt();
			throw new IllegalStateException(e);
		}
		catch (InvocationTargetException e)
		{
			Throwable cause = e.getCause();
			if (cause instanceof RuntimeException)
			{
				throw (RuntimeException) cause;
			}
			if (cause instanceof Error)
			{
				throw (Error) cause;
			}
			throw new IllegalStateException(cause);
		}
		return out.get(0);
	}

	private static <T> T call(Callable<T> c)
	{
		try
		{
			return c.call();
		}
		catch (RuntimeException e)
		{
			throw e;
		}
		catch (Exception e)
		{
			throw new IllegalStateException(e);
		}
	}

	// ---- Layout ----

	/** Lays the tree out {@code width} wide and as tall as it wants; returns that height. */
	public int layout(int width)
	{
		// Until the height settles: a wrapping text area only knows its height once it
		// has been given a width and a height, so each pass can grow the one above.
		int height = 10_000;
		for (int pass = 0; pass < 6; pass++)
		{
			layout(width, height);
			int wanted = Math.max(1, root.getPreferredSize().height);
			if (wanted == height)
			{
				break;
			}
			height = wanted;
		}
		layout(width, height);
		return height;
	}

	/** Lays the tree out at exactly {@code width} x {@code height}. */
	public void layout(int width, int height)
	{
		root.setSize(width, height);
		layoutTree(root);
		layoutTree(root);
	}

	/** Drops every cached size: BoxLayout keeps its children's sizes until invalidated, and a window would. */
	private static void invalidateTree(Component c)
	{
		c.invalidate();
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				invalidateTree(child);
			}
		}
	}

	/** Where {@code c} sits from the root's top edge, in layout pixels. */
	public int yOf(Component c)
	{
		return SwingUtilities.convertPoint(c.getParent(), c.getLocation(), root).y;
	}

	private static void layoutTree(Component root)
	{
		invalidateTree(root);
		doLayoutTree(root);
	}

	private static void doLayoutTree(Component c)
	{
		if (c instanceof Container)
		{
			Container k = (Container) c;
			k.doLayout();
			for (Component child : k.getComponents())
			{
				doLayoutTree(child);
			}
		}
	}

	// ---- Reading ----

	/** Visible components of {@code type}, in tree order. */
	public <T extends Component> List<T> all(Class<T> type)
	{
		List<T> out = new ArrayList<>();
		collect(root, type, out);
		return out;
	}

	private static <T extends Component> void collect(Component c, Class<T> type, List<T> out)
	{
		if (!c.isVisible())
		{
			return;
		}
		if (type.isInstance(c))
		{
			out.add(type.cast(c));
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				collect(child, type, out);
			}
		}
	}

	/** The first visible {@code type} matching {@code test}; fails naming what was on screen. */
	public <T extends Component> T find(Class<T> type, Predicate<T> test, String what)
	{
		for (T c : all(type))
		{
			if (test.test(c))
			{
				return c;
			}
		}
		throw new AssertionError("No " + what + " on screen. Showing: " + texts());
	}

	/** Every visible label, button and text field's text, html stripped, in tree order. */
	public List<String> texts()
	{
		List<String> out = new ArrayList<>();
		for (Component c : all(Component.class))
		{
			String t = textOf(c);
			if (t != null && !t.isEmpty())
			{
				out.add(t);
			}
		}
		return out;
	}

	/** Whether some visible text contains {@code fragment}. */
	public boolean shows(String fragment)
	{
		for (String t : texts())
		{
			if (t.contains(fragment))
			{
				return true;
			}
		}
		return false;
	}

	public void assertShows(String fragment)
	{
		if (!shows(fragment))
		{
			throw new AssertionError("Expected '" + fragment + "' on screen. Showing: " + texts());
		}
	}

	public void assertHides(String fragment)
	{
		if (shows(fragment))
		{
			throw new AssertionError("Expected no '" + fragment + "' on screen. Showing: " + texts());
		}
	}

	/** A visible button whose text is exactly {@code text}. */
	public AbstractButton button(String text)
	{
		return find(AbstractButton.class, b -> text.equals(plain(b.getText())), "button '" + text + "'");
	}

	/** A visible label whose text contains {@code fragment}. */
	public JLabel label(String fragment)
	{
		return find(JLabel.class, l -> plain(l.getText()).contains(fragment), "label '" + fragment + "'");
	}

	/**
	 * A visible text field or area whose tooltip contains {@code fragment}: its
	 * own, or a wrapper's (RuneLite's IconTextField puts it on the panel around
	 * the field).
	 */
	public JTextComponent field(String tooltipFragment)
	{
		return find(JTextComponent.class, f ->
		{
			for (Component c = f; c != null && c != root.getParent(); c = c.getParent())
			{
				String tip = tooltipOf(c);
				if (tip != null && tip.contains(tooltipFragment))
				{
					return true;
				}
			}
			return false;
		}, "text field '" + tooltipFragment + "'");
	}

	// ---- Acting ----

	/** Clicks the button with exactly this text, or else the first label containing it. */
	public SwingDriver click(String text)
	{
		for (AbstractButton b : all(AbstractButton.class))
		{
			if (text.equals(plain(b.getText())))
			{
				return click(b);
			}
		}
		return click(label(text));
	}

	/** A button's own click, or a left press, release and click handed to the component's listeners. */
	public SwingDriver click(Component c)
	{
		if (c instanceof AbstractButton)
		{
			if (!c.isEnabled())
			{
				throw new AssertionError("Button '" + textOf(c) + "' is disabled");
			}
			((AbstractButton) c).doClick(0);
			return this;
		}
		long when = System.currentTimeMillis();
		MouseListener[] listeners = c.getMouseListeners();
		for (int id : new int[]{MouseEvent.MOUSE_PRESSED, MouseEvent.MOUSE_RELEASED, MouseEvent.MOUSE_CLICKED})
		{
			MouseEvent e = new MouseEvent(c, id, when, 0, 1, 1, 1, false, MouseEvent.BUTTON1);
			for (MouseListener l : listeners)
			{
				if (id == MouseEvent.MOUSE_PRESSED)
				{
					l.mousePressed(e);
				}
				else if (id == MouseEvent.MOUSE_RELEASED)
				{
					l.mouseReleased(e);
				}
				else
				{
					l.mouseClicked(e);
				}
			}
		}
		return this;
	}

	/** Replaces the field's text, firing its document listeners as typing would. */
	public SwingDriver type(JTextComponent field, String text)
	{
		field.setText(text);
		return this;
	}

	public SwingDriver select(JComboBox<?> box, Object item)
	{
		box.setSelectedItem(item);
		if (box.getSelectedItem() == null || !box.getSelectedItem().equals(item))
		{
			throw new AssertionError("'" + item + "' is not in the list");
		}
		return this;
	}

	// ---- Rendering ----

	/**
	 * Renders the tree at {@code width} x {@code height} (height 0: as tall as it
	 * wants), scaled by {@code scale} for a sharp README image. Whatever does not
	 * fit is cut off; empty space is the root's background.
	 */
	public BufferedImage render(int width, int height, double scale)
	{
		int h = height > 0 ? height : layout(width);
		layout(width, h);
		BufferedImage image = new BufferedImage((int) Math.round(width * scale), (int) Math.round(h * scale),
			BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.scale(scale, scale);
			Color bg = root.getBackground();
			g.setColor(bg == null ? Color.DARK_GRAY : bg);
			g.fillRect(0, 0, width, h);
			root.printAll(g);
		}
		finally
		{
			g.dispose();
		}
		return image;
	}

	/**
	 * Stacks renders of several components, one under the other, {@code width}
	 * wide overall with {@code pad} layout pixels of margin around them (the
	 * margin the component's own parent panel would give it).
	 */
	public static BufferedImage stack(int width, int pad, double scale, Color background, Component... parts)
	{
		List<BufferedImage> images = new ArrayList<>();
		int padPx = (int) Math.round(pad * scale);
		int total = 2 * padPx;
		for (Component part : parts)
		{
			if (!(part instanceof Container))
			{
				throw new IllegalArgumentException("Only containers can be stacked: " + part);
			}
			BufferedImage img = new SwingDriver((Container) part).render(width - 2 * pad, 0, scale);
			images.add(img);
			total += img.getHeight();
		}
		BufferedImage out = new BufferedImage((int) Math.round(width * scale), Math.max(1, total),
			BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		try
		{
			g.setColor(background);
			g.fillRect(0, 0, out.getWidth(), out.getHeight());
			int y = padPx;
			for (BufferedImage img : images)
			{
				g.drawImage(img, padPx, y, null);
				y += img.getHeight();
			}
		}
		finally
		{
			g.dispose();
		}
		return out;
	}

	/** The part of {@code image} from {@code top} (in image pixels) down, e.g. to start a shot at a section. */
	public static BufferedImage from(BufferedImage image, int top)
	{
		int y = Math.max(0, Math.min(top, image.getHeight() - 1));
		return image.getSubimage(0, y, image.getWidth(), image.getHeight() - y);
	}

	/** Pads or cuts {@code image} to exactly {@code width} x {@code height}, so every README shot has a fixed size. */
	public static BufferedImage fit(BufferedImage image, int width, int height, Color background)
	{
		BufferedImage out = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		try
		{
			g.setColor(background);
			g.fillRect(0, 0, width, height);
			g.drawImage(image, 0, 0, null);
		}
		finally
		{
			g.dispose();
		}
		return out;
	}

	public static void writePng(BufferedImage image, File file)
	{
		File dir = file.getAbsoluteFile().getParentFile();
		if (dir != null && !dir.isDirectory() && !dir.mkdirs())
		{
			throw new IllegalStateException("Cannot create " + dir);
		}
		try
		{
			if (!ImageIO.write(image, "png", file))
			{
				throw new IllegalStateException("No PNG writer");
			}
		}
		catch (IOException e)
		{
			throw new IllegalStateException("Cannot write " + file, e);
		}
	}

	// ---- Text ----

	static String textOf(Component c)
	{
		if (c instanceof JLabel)
		{
			return plain(((JLabel) c).getText());
		}
		if (c instanceof AbstractButton)
		{
			return plain(((AbstractButton) c).getText());
		}
		if (c instanceof JTextComponent)
		{
			return ((JTextComponent) c).getText();
		}
		return null;
	}

	private static String tooltipOf(Component c)
	{
		return c instanceof JComponent ? ((JComponent) c).getToolTipText() : null;
	}

	/** {@code <html>} label text as the reader sees it: tags dropped, entities decoded, spaces collapsed. */
	public static String plain(String text)
	{
		if (text == null)
		{
			return "";
		}
		String s = text.replaceAll("(?i)<br\\s*/?>", " ").replaceAll("<[^>]*>", "");
		s = s.replace("&lt;", "<").replace("&gt;", ">").replace("&nbsp;", " ").replace("&amp;", "&");
		return s.replaceAll("\\s+", " ").trim();
	}

	/** The size the tree wants at its current width. */
	public Dimension preferred()
	{
		return root.getPreferredSize();
	}
}

package com.vinnyvangogh.testkit.ui;

import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.io.File;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import javax.imageio.ImageIO;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/** The driver itself, on a tiny panel: no display needed. */
public class SwingDriverTest
{
	/** Two cards, a button that switches them, a clickable label, a field and a picker. */
	private static final class Fixture
	{
		final JPanel root = new JPanel(new BorderLayout());
		final CardLayout cards = new CardLayout();
		final JPanel views = new JPanel(cards);
		final AtomicInteger labelClicks = new AtomicInteger();
		final List<String> typed = new ArrayList<>();
		final JTextField field = new JTextField();
		final JComboBox<String> picker = new JComboBox<>(new String[]{"Any", "Alex", "Sam"});
		final JButton disabled = new JButton("Disabled");

		Fixture()
		{
			JPanel top = new JPanel();
			top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));
			JButton next = new JButton("Next");
			next.addActionListener(e -> cards.next(views));
			top.add(next);
			JLabel fold = new JLabel("<html><b>Fold</b> &amp; unfold</html>");
			fold.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					labelClicks.incrementAndGet();
				}
			});
			top.add(fold);
			field.setToolTipText("Filter by item name");
			field.getDocument().addDocumentListener(new DocumentListener()
			{
				@Override
				public void insertUpdate(DocumentEvent e)
				{
					typed.add(field.getText());
				}

				@Override
				public void removeUpdate(DocumentEvent e)
				{
				}

				@Override
				public void changedUpdate(DocumentEvent e)
				{
				}
			});
			top.add(field);
			top.add(picker);
			disabled.setEnabled(false);
			top.add(disabled);
			root.add(top, BorderLayout.NORTH);
			views.add(new JLabel("First card"), "one");
			views.add(new JLabel("Second card"), "two");
			root.add(views, BorderLayout.CENTER);
			root.setBackground(Color.BLACK);
		}
	}

	@Test
	public void hiddenCardsAreNotOnScreenAndAButtonClickSwitchesThem()
	{
		SwingDriver.onEdt(() ->
		{
			Fixture f = new Fixture();
			SwingDriver d = new SwingDriver(f.root);
			d.assertShows("First card");
			d.assertHides("Second card");
			d.click("Next");
			d.assertShows("Second card");
			d.assertHides("First card");
		});
	}

	@Test
	public void labelsAreClickedThroughTheirOwnListenersAndReadWithoutHtml()
	{
		SwingDriver.onEdt(() ->
		{
			Fixture f = new Fixture();
			SwingDriver d = new SwingDriver(f.root);
			assertTrue(d.texts().contains("Fold & unfold"));
			d.click("Fold & unfold");
			assertEquals(1, f.labelClicks.get());
		});
	}

	@Test
	public void typingFiresDocumentListenersAndPickingSelects()
	{
		SwingDriver.onEdt(() ->
		{
			Fixture f = new Fixture();
			SwingDriver d = new SwingDriver(f.root);
			d.type(d.field("item name"), "guam");
			assertEquals("guam", f.typed.get(f.typed.size() - 1));
			d.select(f.picker, "Sam");
			assertEquals("Sam", f.picker.getSelectedItem());
		});
	}

	@Test
	public void aMissingComponentFailsWithWhatIsOnScreen()
	{
		SwingDriver.onEdt(() ->
		{
			SwingDriver d = new SwingDriver(new Fixture().root);
			try
			{
				d.button("Nope");
				fail("found a button that is not there");
			}
			catch (AssertionError e)
			{
				assertTrue(e.getMessage(), e.getMessage().contains("First card"));
			}
		});
	}

	@Test
	public void aDisabledButtonRefusesTheClick()
	{
		SwingDriver.onEdt(() ->
		{
			SwingDriver d = new SwingDriver(new Fixture().root);
			try
			{
				d.click("Disabled");
				fail("clicked a disabled button");
			}
			catch (AssertionError e)
			{
				assertTrue(e.getMessage().contains("disabled"));
			}
		});
	}

	@Test
	public void aPickerRefusesAnItemItDoesNotHave()
	{
		SwingDriver.onEdt(() ->
		{
			Fixture f = new Fixture();
			try
			{
				new SwingDriver(f.root).select(f.picker, "Zed");
				fail("selected a missing item");
			}
			catch (AssertionError e)
			{
				assertTrue(e.getMessage().contains("Zed"));
			}
		});
	}

	@Test
	public void rendersAtAFixedScaledSizeAndWritesAPng() throws Exception
	{
		File dir = Files.createTempDirectory("swingdriver").toFile();
		File png = new File(dir, "shot.png");
		SwingDriver.onEdt(() ->
		{
			SwingDriver d = new SwingDriver(new Fixture().root);
			BufferedImage img = d.render(200, 150, 2.0);
			assertEquals(400, img.getWidth());
			assertEquals(300, img.getHeight());
			SwingDriver.writePng(SwingDriver.fit(img, 400, 500, Color.BLACK), png);
		});
		BufferedImage back = ImageIO.read(png);
		assertEquals(400, back.getWidth());
		assertEquals(500, back.getHeight());
	}

	@Test
	public void stackPadsAndCropStartsLower()
	{
		SwingDriver.onEdt(() ->
		{
			JPanel a = new Fixture().root;
			JPanel b = new Fixture().root;
			int ha = new SwingDriver(a).layout(180);
			int hb = new SwingDriver(b).layout(180);
			BufferedImage both = SwingDriver.stack(200, 10, 2.0, Color.RED, a, b);
			assertEquals(400, both.getWidth());
			assertEquals((ha + hb) * 2 + 40, both.getHeight());
			assertEquals("the margin is the background", Color.RED.getRGB(), both.getRGB(5, 5));
			assertEquals(both.getHeight() - 30, SwingDriver.from(both, 30).getHeight());
			JLabel card = new SwingDriver(a).label("First card");
			assertTrue("below the buttons", new SwingDriver(a).yOf(card) > 0);
		});
	}

	@Test
	public void layoutGivesThePreferredHeight()
	{
		SwingDriver.onEdt(() ->
		{
			SwingDriver d = new SwingDriver(new Fixture().root);
			int h = d.layout(220);
			assertTrue("height " + h, h > 20);
			assertEquals(220, d.root().getWidth());
		});
	}

